    'carry_forward_released_count', COALESCE(v_carry_forward_released_count, 0),
    'carry_forward_create_result', COALESCE(v_carry_forward_create_result, '{}'::jsonb),
    'carry_forward_release_result', COALESCE(v_carry_forward_release_result, '{}'::jsonb),
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_groups_json', COALESCE(v_provider_failure_reason_groups_json, '[]'::jsonb),
    'changed_scope_json', COALESCE(v_changed_scope_json, '{}'::jsonb),
    'resolved_scope', COALESCE(v_resolved_scope_json, '{}'::jsonb),
    'summary_refresh_candidate_count', v_summary_refresh_candidate_count,
    'active_batch_item_count_after', COALESCE(v_active_batch_item_count_after, 0),
    'active_batch_amount_inc_vat_after', COALESCE(v_active_batch_amount_inc_vat_after, 0),
    'batch_empty_after', COALESCE(v_batch_empty_after, false),
    'notice_group_id', v_notice_group_id,
    'notice_queue_result', v_notice_queue_result,
    'accepted_finance_resolution', v_finance_resolution_result,
    'classification_result', v_classification_result,
    'provider_evidence_result', COALESCE(v_provider_evidence_result, '{}'::jsonb),
    'rail_state_summary', COALESCE(v_rail_state_summary_json, '{}'::jsonb)
  ) || jsonb_build_object(
    'workbench_refresh_status', COALESCE(v_workbench_refresh_status, 'NOT_REQUIRED'),
    'workbench_refresh_queued_count', COALESCE(v_workbench_refresh_queued_count, 0),
    'workbench_refresh_deferred_count', COALESCE(v_workbench_refresh_deferred_count, 0),
    'workbench_refresh_failed_count', COALESCE(v_workbench_refresh_failed_count, 0),
    'workbench_refresh_job_ids', COALESCE(v_workbench_refresh_job_ids, '[]'::jsonb),
    'requires_workbench_session', COALESCE(v_workbench_requires_session, false),
    'workbench_refresh', jsonb_build_object(
      'status', COALESCE(v_workbench_refresh_status, 'NOT_REQUIRED'),
      'queued_count', COALESCE(v_workbench_refresh_queued_count, 0),
      'deferred_count', COALESCE(v_workbench_refresh_deferred_count, 0),
      'failed_count', COALESCE(v_workbench_refresh_failed_count, 0),
      'job_ids', COALESCE(v_workbench_refresh_job_ids, '[]'::jsonb),
      'results', COALESCE(v_workbench_refresh_results, '[]'::jsonb),
      'requires_workbench_session', COALESCE(v_workbench_requires_session, false),
      'session_id', CASE WHEN v_batch.source_workbench_session_id IS NULL THEN NULL ELSE v_batch.source_workbench_session_id::text END,
      'source_snapshot_run_id', CASE WHEN v_batch.source_snapshot_run_id IS NULL THEN NULL ELSE v_batch.source_snapshot_run_id::text END
    ),
    'applied_at_utc', v_now
  );

  UPDATE public.pay_payment_correction_work_items AS applied_work_item
  SET
    status = 'APPLIED',
    locked_at_utc = NULL,
    locked_by = NULL,
    processed_at_utc = COALESCE(applied_work_item.processed_at_utc, v_now),
    last_error = NULL,
    result_json = COALESCE(applied_work_item.result_json, '{}'::jsonb) || v_result
  WHERE applied_work_item.id = p_work_item_id;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_NO_MONEY_UNWIND_WORK_RESULT',
    v_result,
    'pay_payment_correction',
    p_work_item_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_result;

EXCEPTION
  WHEN OTHERS THEN
    v_blocker := jsonb_build_object(
      'code', 'NO_MONEY_UNWIND_WORK_ITEM_BLOCKED_BY_EXCEPTION',
      'message', 'No-money unwind work item was blocked after an exception; no partial correction was committed.',
      'work_item_id', p_work_item_id,
      'correction_request_id', CASE WHEN v_work_item.correction_request_id IS NULL THEN NULL ELSE v_work_item.correction_request_id END,
      'pay_batch_id', CASE WHEN v_work_item.pay_batch_id IS NULL THEN NULL ELSE v_work_item.pay_batch_id END,
      'sqlstate', SQLSTATE,
      'error_message', SQLERRM,
      'blocked_at_utc', v_now
    );

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_NO_MONEY_UNWIND_WORK_ERROR',
      v_blocker,
      'pay_payment_correction',
      COALESCE(p_work_item_id::text, 'NO_WORK_ITEM_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    IF p_work_item_id IS NOT NULL THEN
      UPDATE public.pay_payment_correction_work_items AS exception_blocked_work_item
      SET
        status = 'BLOCKED',
        locked_at_utc = NULL,
        locked_by = NULL,
        processed_at_utc = COALESCE(exception_blocked_work_item.processed_at_utc, v_now),
        last_error = SQLERRM,
        result_json = COALESCE(exception_blocked_work_item.result_json, '{}'::jsonb) || jsonb_build_object(
          'ok', false,
          'status', 'BLOCKED',
          'blocker', v_blocker,
          'processed_at_utc', v_now
        )
      WHERE exception_blocked_work_item.id = p_work_item_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', false,
      'status', 'BLOCKED',
      'result_code', 'NO_MONEY_UNWIND_WORK_ITEM_BLOCKED_BY_EXCEPTION',
      'work_item_id', p_work_item_id,
      'candidate_id', v_work_item.candidate_id,
      'expected_item_count', COALESCE(v_selected_item_count, 0),
      'applied_item_count', 0,
      'released_reservations', 0,
      'restored_finance_components', 0,
      'carry_forward_created', 0,
      'carry_forward_existing', 0,
      'carry_forward_released', 0,
      'changed_scope_json', '{}'::jsonb,
      'blocker', v_blocker
    );
END;
$function$;

-- pay_operation_remittance_scope_seed(uuid,uuid,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_operation_remittance_scope_seed(p_operation_id uuid, p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_scope text := upper(BTRIM(COALESCE(p_scope, 'ALL')));
  v_created_count integer := 0;
  v_reused_count integer := 0;
  v_recipient_count integer := 0;
  v_stale_scope_skipped_count integer := 0;
  v_trigger text;
  v_only_confirmed boolean := false;
  v_configured_timing text := 'ON_EXECUTION';
  v_batch_status text := null;
  v_batch_schedule_kind text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;
  v_scheduled_execution_eligible boolean := false;
  v_deferred_by_timing boolean := false;
  v_pending_provider_skipped_count integer := 0;
  v_no_transfer_skipped_count integer := 0;
  v_terminal_no_money_skipped_count integer := 0;
  v_confirmed_scope_row_count integer := 0;
  v_scheduled_scope_row_count integer := 0;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope NOT IN ('ALL', 'CANDIDATE', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'p_scope must be ALL, CANDIDATE, PAYE, or UMBRELLA';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
  END IF;

  IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
    RAISE EXCEPTION 'operation % is not a remittance-capable operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
  END IF;

  IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
  END IF;


  v_trigger := upper(btrim(coalesce(
    nullif(btrim(coalesce(v_operation_row.input_json->>'trigger', '')), ''),
    CASE
      WHEN v_operation_row.operation_type = 'PAYMENT_SETTLEMENT' THEN 'ON_PAYMENT_CONFIRMED'
      ELSE 'ON_EXECUTION'
    END
  )));

  v_only_confirmed := lower(btrim(coalesce(v_operation_row.input_json->>'only_confirmed', 'false'))) IN ('true','1','yes','y','on');

  IF v_trigger NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    RAISE EXCEPTION 'unsupported remittance trigger %', v_trigger;
  END IF;

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_remittance_send_timing), ''), 'ON_EXECUTION')
  INTO v_configured_timing
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_configured_timing := upper(coalesce(nullif(btrim(v_configured_timing), ''), 'ON_EXECUTION'));

  IF v_configured_timing NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    v_configured_timing := 'ON_EXECUTION';
  END IF;

  v_deferred_by_timing := v_configured_timing <> v_trigger;

  IF v_batch_row.execution_intent_json IS NOT NULL AND jsonb_typeof(v_batch_row.execution_intent_json) = 'object' THEN
    v_execution_intent_json := v_batch_row.execution_intent_json;
  ELSE
    v_execution_intent_json := '{}'::jsonb;
  END IF;

  IF v_batch_row.settlement_confirmation_json IS NOT NULL AND jsonb_typeof(v_batch_row.settlement_confirmation_json) = 'object' THEN
    v_settlement_confirmation_json := v_batch_row.settlement_confirmation_json;
  ELSE
    v_settlement_confirmation_json := '{}'::jsonb;
  END IF;

  v_batch_status := upper(btrim(coalesce(v_batch_row.status, '')));
  v_batch_schedule_kind := upper(btrim(coalesce(v_batch_row.schedule_kind, v_execution_intent_json->>'schedule_kind', '')));

  IF v_deferred_by_timing THEN
    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'trigger', v_trigger,
      'configured_timing', v_configured_timing,
      'only_confirmed', v_only_confirmed,
      'deferred', true,
      'suppressed', false,
      'scope_rows_created', 0,
      'scope_rows_reused', 0,
      'recipient_count', 0,
      'stale_scope_skipped_count', 0,
      'scheduled_scope_rows', 0,
      'confirmed_scope_rows', 0,
      'pending_provider_skipped_count', 0,
      'no_transfer_skipped_count', 0,
      'terminal_no_money_skipped_count', 0,
      'scheduled_execution_eligible', false,
      'trigger_status', 'REMITTANCE_SCOPE_DEFERRED_BY_CONFIGURED_TIMING'
    );
  END IF;

  v_suppress_remittances :=
    lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances_pending', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_settlement_confirmation_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_settlement_confirmation_json->>'suppress_remittances_pending', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_operation_row.input_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on');

  IF v_suppress_remittances THEN
    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'trigger', v_trigger,
      'configured_timing', v_configured_timing,
      'only_confirmed', v_only_confirmed,
      'deferred', false,
      'suppressed', true,
      'scope_rows_created', 0,
      'scope_rows_reused', 0,
      'recipient_count', 0,
      'stale_scope_skipped_count', 0,
      'scheduled_scope_rows', 0,
      'confirmed_scope_rows', 0,
      'pending_provider_skipped_count', 0,
      'no_transfer_skipped_count', 0,
      'terminal_no_money_skipped_count', 0,
      'scheduled_execution_eligible', false,
      'trigger_status', 'REMITTANCE_SCOPE_SUPPRESSED'
    );
  END IF;

  v_scheduled_execution_eligible :=
    v_operation_row.operation_type = 'REMITTANCE_QUEUE'
    AND v_trigger = 'ON_EXECUTION'
    AND v_configured_timing = 'ON_EXECUTION'
    AND COALESCE(v_only_confirmed, false) = false
    AND v_batch_schedule_kind = 'SCHEDULED'
    AND v_batch_row.scheduled_at_utc IS NOT NULL
    AND v_batch_status NOT IN (
      'BLOCKED_FUNDS',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'REJECTED',
      'DECLINED',
      'RETURNED',
      'VOID',
      'DELETED'
    )
    AND lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) NOT IN ('true','1','yes','y','on')
    AND (
      v_operation_row.root_operation_id IS NULL
      OR nullif(btrim(coalesce(v_execution_intent_json->>'operation_id', '')), '') IS NULL
      OR v_execution_intent_json->>'operation_id' = v_operation_row.root_operation_id::text
    );

  WITH scoped_item_rows AS (
    SELECT
      batch_candidate.id AS pay_batch_candidate_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_bank_transfer_id,
      upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) AS settlement_status,
      transfer_row.id AS transfer_id,
      upper(BTRIM(COALESCE(transfer_row.status, ''))) AS transfer_status,
      upper(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS transfer_rail_state,
      transfer_row.completed_at_utc,
      COALESCE(transfer_classifier.is_final_money_moved, false) AS is_final_money_moved,
      COALESCE(transfer_classifier.is_terminal_no_money, false) AS is_terminal_no_money,
      COALESCE(transfer_classifier.is_pending_non_final, false) AS is_pending_non_final
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = batch_item.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      transfer_row.status,
      transfer_row.rail_state,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier ON transfer_row.id IS NOT NULL
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      AND (
        v_scope = 'ALL'
        OR (v_scope IN ('CANDIDATE', 'PAYE') AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE')
        OR (v_scope = 'UMBRELLA' AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'UMBRELLA')
      )
  ), scoped_item_flags AS (
    SELECT
      scoped_item_rows.*,
      (
        scoped_item_rows.settlement_status IN ('SETTLED', 'PAID', 'CONFIRMED')
        OR scoped_item_rows.is_final_money_moved
        OR scoped_item_rows.transfer_status IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR scoped_item_rows.transfer_rail_state IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR scoped_item_rows.completed_at_utc IS NOT NULL
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
          WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id
            AND settlement_scope_row.pay_batch_candidate_id = scoped_item_rows.pay_batch_candidate_id
            AND settlement_scope_row.status = 'SETTLED'
            AND (
              (
                scoped_item_rows.pay_bank_transfer_id IS NOT NULL
                AND settlement_scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}' = scoped_item_rows.pay_bank_transfer_id::text
              )
              OR COALESCE(settlement_scope_row.payload_json->'pay_batch_item_ids', '[]'::jsonb) ? scoped_item_rows.pay_batch_item_id::text
            )
        )
      ) AS confirmed_or_final,
      (
        scoped_item_rows.is_pending_non_final
        OR scoped_item_rows.transfer_status IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION', 'WAITING', 'WAITING_BANK_CONFIRM')
        OR scoped_item_rows.transfer_rail_state IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION', 'WAITING', 'WAITING_BANK_CONFIRM')
      ) AS pending_provider,
      (
        scoped_item_rows.is_terminal_no_money
        OR scoped_item_rows.transfer_status IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
        OR scoped_item_rows.transfer_rail_state IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
      ) AS terminal_no_money
    FROM scoped_item_rows
  )
  SELECT
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NOT NULL AND scoped_item_flags.pending_provider IS TRUE AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END,
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NULL AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END,
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NOT NULL AND scoped_item_flags.terminal_no_money IS TRUE AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END
  INTO v_pending_provider_skipped_count,
       v_no_transfer_skipped_count,
       v_terminal_no_money_skipped_count
  FROM scoped_item_flags;

  WITH eligible_item_rows AS (
    SELECT
      batch_candidate.id AS pay_batch_candidate_id,
      batch_candidate.candidate_id,
      upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) AS pay_channel,
      batch_item.umbrella_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_bank_transfer_id,
      transfer_row.transfer_group_key,
      COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS item_amount,
      CASE
        WHEN batch_item.pay_bank_transfer_id IS NOT NULL THEN 'transfer:' || batch_item.pay_bank_transfer_id::text
        ELSE 'batch_candidate:' || batch_candidate.id::text || ':channel:' || upper(BTRIM(COALESCE(batch_item.pay_channel, '')))
      END AS payment_scope_key
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = batch_item.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      transfer_row.status,
      transfer_row.rail_state,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier ON transfer_row.id IS NOT NULL
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      AND (
        v_scheduled_execution_eligible
        OR upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
        OR COALESCE(transfer_classifier.is_final_money_moved, false)
        OR upper(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR upper(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR transfer_row.completed_at_utc IS NOT NULL
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
          WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id
            AND settlement_scope_row.pay_batch_candidate_id = batch_candidate.id
            AND settlement_scope_row.status = 'SETTLED'
            AND (
              (
                batch_item.pay_bank_transfer_id IS NOT NULL
                AND settlement_scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}' = batch_item.pay_bank_transfer_id::text
              )
              OR COALESCE(settlement_scope_row.payload_json->'pay_batch_item_ids', '[]'::jsonb) ? batch_item.id::text
            )
        )
      )
      AND (
        v_scope = 'ALL'
        OR (v_scope IN ('CANDIDATE', 'PAYE') AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE')
        OR (v_scope = 'UMBRELLA' AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'UMBRELLA')
      )
  ), candidate_scope AS (
    SELECT
      eligible_item_rows.pay_batch_candidate_id,
      eligible_item_rows.candidate_id,
      'CANDIDATE'::text AS recipient_kind,
      eligible_item_rows.candidate_id AS recipient_id,
      'CANDIDATE_REMITTANCE'::text AS remittance_type,
      'remittance:batch:' || p_pay_batch_id::text || ':candidate:' || eligible_item_rows.candidate_id::text || ':scope:' || eligible_item_rows.payment_scope_key || ':type:CANDIDATE_REMITTANCE' AS deterministic_outbox_key,
      eligible_item_rows.payment_scope_key,
      eligible_item_rows.pay_bank_transfer_id,
      eligible_item_rows.transfer_group_key,
      COALESCE(jsonb_agg(to_jsonb(eligible_item_rows.pay_batch_item_id::text) ORDER BY eligible_item_rows.pay_batch_item_id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) AS total_amount
    FROM eligible_item_rows
    WHERE eligible_item_rows.pay_channel = 'PAYE'
      AND v_scope IN ('ALL', 'CANDIDATE', 'PAYE')
      AND EXISTS (
        SELECT 1
        FROM public.candidates AS remittance_candidate
        WHERE remittance_candidate.id = eligible_item_rows.candidate_id
          AND (
            CASE
              WHEN COALESCE(remittance_candidate.remittance_overrides_enabled, false)
                THEN COALESCE(remittance_candidate.remittance_receive_enabled, false)
              ELSE COALESCE((
                SELECT settings_row.paye_remittances_enabled
                FROM public.settings_defaults AS settings_row
                ORDER BY settings_row.id
                LIMIT 1
              ), false)
            END
          )
      )
    GROUP BY eligible_item_rows.pay_batch_candidate_id,
             eligible_item_rows.candidate_id,
             eligible_item_rows.payment_scope_key,
             eligible_item_rows.pay_bank_transfer_id,
             eligible_item_rows.transfer_group_key
    HAVING ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) <> 0
        OR (
          COUNT(*) FILTER (WHERE eligible_item_rows.item_amount > 0) > 0
          AND COUNT(*) FILTER (WHERE eligible_item_rows.item_amount < 0) > 0
        )
  ), umbrella_scope AS (
    SELECT
      eligible_item_rows.pay_batch_candidate_id,
      eligible_item_rows.candidate_id,
      'UMBRELLA'::text AS recipient_kind,
      eligible_item_rows.umbrella_id AS recipient_id,
      'UMBRELLA_REMITTANCE'::text AS remittance_type,
      'remittance:batch:' || p_pay_batch_id::text || ':candidate:' || eligible_item_rows.candidate_id::text || ':umbrella:' || eligible_item_rows.umbrella_id::text || ':scope:' || eligible_item_rows.payment_scope_key || ':type:UMBRELLA_REMITTANCE' AS deterministic_outbox_key,
      eligible_item_rows.payment_scope_key,
      eligible_item_rows.pay_bank_transfer_id,
      eligible_item_rows.transfer_group_key,
      COALESCE(jsonb_agg(to_jsonb(eligible_item_rows.pay_batch_item_id::text) ORDER BY eligible_item_rows.pay_batch_item_id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) AS total_amount
    FROM eligible_item_rows
    WHERE eligible_item_rows.pay_channel = 'UMBRELLA'
      AND eligible_item_rows.umbrella_id IS NOT NULL
      AND v_scope IN ('ALL', 'UMBRELLA')
    GROUP BY eligible_item_rows.pay_batch_candidate_id,
             eligible_item_rows.candidate_id,
             eligible_item_rows.umbrella_id,
             eligible_item_rows.payment_scope_key,
             eligible_item_rows.pay_bank_transfer_id,
             eligible_item_rows.transfer_group_key
    HAVING ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) <> 0
  ), scope_rows AS (
    SELECT candidate_scope.pay_batch_candidate_id,
           candidate_scope.candidate_id,
           candidate_scope.recipient_kind,
           candidate_scope.recipient_id,
           candidate_scope.remittance_type,
           candidate_scope.deterministic_outbox_key,
           jsonb_build_object(
             'pay_batch_id', p_pay_batch_id::text,
             'pay_batch_candidate_id', candidate_scope.pay_batch_candidate_id::text,
             'candidate_id', candidate_scope.candidate_id::text,
             'recipient_kind', candidate_scope.recipient_kind,
             'recipient_id', candidate_scope.recipient_id::text,
             'remittance_type', candidate_scope.remittance_type,
             'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
               'scope_key', candidate_scope.payment_scope_key,
               'pay_bank_transfer_id', CASE WHEN candidate_scope.pay_bank_transfer_id IS NULL THEN NULL ELSE candidate_scope.pay_bank_transfer_id::text END,
               'transfer_group_key', candidate_scope.transfer_group_key,
               'remittance_trigger', CASE WHEN v_scheduled_execution_eligible THEN v_trigger ELSE NULL END,
               'configured_timing', CASE WHEN v_scheduled_execution_eligible THEN v_configured_timing ELSE NULL END,
               'scheduled_execution_eligible', CASE WHEN v_scheduled_execution_eligible THEN true ELSE NULL END,
               'scheduled_at_utc', CASE WHEN v_scheduled_execution_eligible AND v_batch_row.scheduled_at_utc IS NOT NULL THEN v_batch_row.scheduled_at_utc::text ELSE NULL END,
               'schedule_kind', CASE WHEN v_scheduled_execution_eligible THEN v_batch_schedule_kind ELSE NULL END
             )),
             'pay_batch_item_ids', candidate_scope.pay_batch_item_ids_json,
             'item_count', candidate_scope.item_count,
             'total_amount', candidate_scope.total_amount,
             'scope', v_scope
           ) AS payload_json
    FROM candidate_scope

    UNION ALL

    SELECT umbrella_scope.pay_batch_candidate_id,
           umbrella_scope.candidate_id,
           umbrella_scope.recipient_kind,
           umbrella_scope.recipient_id,
           umbrella_scope.remittance_type,
           umbrella_scope.deterministic_outbox_key,
           jsonb_build_object(
             'pay_batch_id', p_pay_batch_id::text,
             'pay_batch_candidate_id', umbrella_scope.pay_batch_candidate_id::text,
             'candidate_id', umbrella_scope.candidate_id::text,
             'recipient_kind', umbrella_scope.recipient_kind,
             'recipient_id', umbrella_scope.recipient_id::text,
             'remittance_type', umbrella_scope.remittance_type,
             'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
               'scope_key', umbrella_scope.payment_scope_key,
               'pay_bank_transfer_id', CASE WHEN umbrella_scope.pay_bank_transfer_id IS NULL THEN NULL ELSE umbrella_scope.pay_bank_transfer_id::text END,
               'transfer_group_key', umbrella_scope.transfer_group_key,
               'remittance_trigger', CASE WHEN v_scheduled_execution_eligible THEN v_trigger ELSE NULL END,
               'configured_timing', CASE WHEN v_scheduled_execution_eligible THEN v_configured_timing ELSE NULL END,
               'scheduled_execution_eligible', CASE WHEN v_scheduled_execution_eligible THEN true ELSE NULL END,
               'scheduled_at_utc', CASE WHEN v_scheduled_execution_eligible AND v_batch_row.scheduled_at_utc IS NOT NULL THEN v_batch_row.scheduled_at_utc::text ELSE NULL END,
               'schedule_kind', CASE WHEN v_scheduled_execution_eligible THEN v_batch_schedule_kind ELSE NULL END
             )),
             'pay_batch_item_ids', umbrella_scope.pay_batch_item_ids_json,
             'item_count', umbrella_scope.item_count,
             'total_amount', umbrella_scope.total_amount,
             'scope', v_scope
           ) AS payload_json
    FROM umbrella_scope
  ), stale_scope AS (
    UPDATE public.banking_pay_operation_remittance_scope AS scope_update
    SET status = 'SKIPPED',
        updated_at_utc = v_now
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.pay_batch_id = p_pay_batch_id
      AND scope_update.status IN ('PENDING', 'FAILED')
      AND NOT EXISTS (
        SELECT 1
        FROM scope_rows
        WHERE scope_rows.deterministic_outbox_key = scope_update.deterministic_outbox_key
      )
    RETURNING scope_update.id
  ), upserted_scope AS (
    INSERT INTO public.banking_pay_operation_remittance_scope (
      operation_id,
      pay_batch_id,
      pay_batch_candidate_id,
      candidate_id,
      recipient_kind,
      recipient_id,
      remittance_type,
      deterministic_outbox_key,
      payload_json,
      status,
      outbox_id,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_operation_id,
      p_pay_batch_id,
      scope_rows.pay_batch_candidate_id,
      scope_rows.candidate_id,
      scope_rows.recipient_kind,
      scope_rows.recipient_id,
      scope_rows.remittance_type,
      scope_rows.deterministic_outbox_key,
      scope_rows.payload_json,
      'PENDING',
      NULL::uuid,
      v_now,
      v_now
    FROM scope_rows
    ON CONFLICT (operation_id, deterministic_outbox_key)
    DO UPDATE
    SET pay_batch_candidate_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.pay_batch_candidate_id ELSE EXCLUDED.pay_batch_candidate_id END,
        candidate_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.candidate_id ELSE EXCLUDED.candidate_id END,
        recipient_kind = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.recipient_kind ELSE EXCLUDED.recipient_kind END,
        recipient_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.recipient_id ELSE EXCLUDED.recipient_id END,
        remittance_type = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.remittance_type ELSE EXCLUDED.remittance_type END,
        payload_json = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.payload_json ELSE EXCLUDED.payload_json END,
        status = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.status ELSE EXCLUDED.status END,
        updated_at_utc = v_now
    RETURNING public.banking_pay_operation_remittance_scope.id,
              public.banking_pay_operation_remittance_scope.recipient_kind,
              public.banking_pay_operation_remittance_scope.recipient_id,
              (xmax = 0) AS was_inserted
  )
  SELECT COUNT(*) FILTER (WHERE upserted_scope.was_inserted)::integer,
         COUNT(*) FILTER (WHERE upserted_scope.was_inserted IS NOT TRUE)::integer,
         COUNT(DISTINCT upserted_scope.recipient_kind || ':' || upserted_scope.recipient_id::text)::integer,
         COALESCE((SELECT COUNT(*)::integer FROM stale_scope), 0)
  INTO v_created_count,
       v_reused_count,
       v_recipient_count,
       v_stale_scope_skipped_count
  FROM upserted_scope;

  v_scheduled_scope_row_count := CASE WHEN v_scheduled_execution_eligible THEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) ELSE 0 END;
  v_confirmed_scope_row_count := CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) END;

  UPDATE public.banking_pay_operations AS operation_update
  SET pay_batch_id = p_pay_batch_id,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id
    AND operation_update.pay_batch_id IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'scope', v_scope,
    'trigger', v_trigger,
    'configured_timing', v_configured_timing,
    'only_confirmed', v_only_confirmed,
    'scheduled_execution_eligible', v_scheduled_execution_eligible,
    'deferred', false,
    'suppressed', false,
    'trigger_status', CASE
      WHEN v_scheduled_execution_eligible THEN 'SCHEDULED_ON_EXECUTION_SCOPE_SEEDED'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_pending_provider_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_DEFERRED_PENDING_PROVIDER'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_no_transfer_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_DEFERRED_NO_TRANSFER'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_terminal_no_money_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_SKIPPED_TERMINAL_NO_MONEY'
      ELSE 'STANDARD_REMITTANCE_SCOPE_SEEDED'
    END,
    'scope_rows_created', COALESCE(v_created_count, 0),
    'scope_rows_reused', COALESCE(v_reused_count, 0),
    'recipient_count', COALESCE(v_recipient_count, 0),
    'stale_scope_skipped_count', COALESCE(v_stale_scope_skipped_count, 0),
    'scheduled_scope_rows', COALESCE(v_scheduled_scope_row_count, 0),
    'confirmed_scope_rows', COALESCE(v_confirmed_scope_row_count, 0),
    'pending_provider_skipped_count', COALESCE(v_pending_provider_skipped_count, 0),
    'no_transfer_skipped_count', COALESCE(v_no_transfer_skipped_count, 0),
    'terminal_no_money_skipped_count', COALESCE(v_terminal_no_money_skipped_count, 0)
  );
END;
$function$;

-- pay_operation_settlement_scope_seed(uuid,uuid,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_operation_settlement_scope_seed(p_operation_id uuid, p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_execution_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_scope text := upper(BTRIM(COALESCE(p_scope, 'ALL')));
  v_created_count integer := 0;
  v_reused_count integer := 0;
  v_settlement_unit_count integer := 0;
  v_stale_scope_skipped_count integer := 0;
  v_transfer_scope_operation_id uuid := NULL::uuid;
  v_execution_operation_resolved_from_batch_intent boolean := false;
  v_item_transfer_linked_count integer := 0;
  v_item_transfer_reused_count integer := 0;
  v_item_transfer_conflict_count integer := 0;
  v_batch_already_settled boolean := false;
  v_idempotent_settlement_complete boolean := false;
  v_transfer_count integer := 0;
  v_terminal_success_transfer_count integer := 0;
  v_terminal_failed_transfer_count integer := 0;
  v_pending_or_unknown_transfer_count integer := 0;
  v_transfer_event_count integer := 0;
  v_provider_attempt_count integer := 0;
  v_explicit_zero_transfer_evidence_count integer := 0;
  v_candidate_count integer := 0;
  v_settled_candidate_count integer := 0;
  v_item_count integer := 0;
  v_linked_nonvoid_item_count integer := 0;
  v_covered_nonvoid_item_count integer := 0;
  v_existing_completed_settlement_operation_id uuid := NULL::uuid;
  v_freshness_clean boolean := true;
  v_current_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_current_scoped_paye_net_state_hash text := NULL::text;
  v_current_bank_payment_projection_hash text := NULL::text;
  v_current_missing_paye_count integer := 0;
  v_current_global_explicit_zero_count integer := 0;
  v_current_global_positive_payment_count integer := 0;
  v_current_global_invalid_payment_row_count integer := 0;
  v_current_scoped_missing_paye_count integer := 0;
  v_current_scoped_explicit_zero_count integer := 0;
  v_current_scoped_positive_payment_count integer := 0;
  v_current_scoped_positive_payment_total numeric(14,2) := 0;
  v_current_scoped_invalid_payment_row_count integer := 0;
  v_explicit_zero_no_bank_scope_count integer := 0;
  v_transfer_backed_scope_count integer := 0;
  v_no_bank_batch_already_settled boolean := false;
  v_batch_intent_json jsonb := '{}'::jsonb;
  v_auth_intent_json jsonb := '{}'::jsonb;
  v_auth_request_id uuid := NULL::uuid;
  v_auth_state text := NULL::text;
  v_auth_operation_id uuid := NULL::uuid;
  v_batch_operation_id uuid := NULL::uuid;
  v_authorised_execution_mode text := NULL::text;
  v_batch_execution_mode text := NULL::text;
  v_authorised_scope text := NULL::text;
  v_batch_scope text := NULL::text;
  v_authorised_paye_net_state_hash text := NULL::text;
  v_batch_paye_net_state_hash text := NULL::text;
  v_authorised_global_bank_payment_projection_hash text := NULL::text;
  v_batch_global_bank_payment_projection_hash text := NULL::text;
  v_authorised_scoped_paye_net_state_hash text := NULL::text;
  v_batch_scoped_paye_net_state_hash text := NULL::text;
  v_authorised_bank_payment_projection_hash text := NULL::text;
  v_batch_bank_payment_projection_hash text := NULL::text;
  v_authorised_missing_count integer := NULL::integer;
  v_batch_missing_count integer := NULL::integer;
  v_authorised_global_zero_count integer := NULL::integer;
  v_batch_global_zero_count integer := NULL::integer;
  v_authorised_global_positive_count integer := NULL::integer;
  v_batch_global_positive_count integer := NULL::integer;
  v_authorised_global_invalid_count integer := NULL::integer;
  v_batch_global_invalid_count integer := NULL::integer;
  v_authorised_scoped_missing_count integer := NULL::integer;
  v_batch_scoped_missing_count integer := NULL::integer;
  v_authorised_scoped_zero_count integer := NULL::integer;
  v_batch_scoped_zero_count integer := NULL::integer;
  v_authorised_scoped_positive_count integer := NULL::integer;
  v_batch_scoped_positive_count integer := NULL::integer;
  v_authorised_scoped_invalid_count integer := NULL::integer;
  v_batch_scoped_invalid_count integer := NULL::integer;
  v_authorised_scoped_no_transfer_execution boolean := false;
  v_batch_scoped_no_transfer_execution boolean := false;
  v_authorised_no_bank_payment_execution boolean := false;
  v_batch_no_bank_payment_execution boolean := false;
