  v_current_global_paye_positive_count integer := 0;
  v_current_scoped_paye_positive_count integer := 0;
  v_authorised_global_paye_positive_count integer := NULL::integer;
  v_batch_global_paye_positive_count integer := NULL::integer;
  v_authorised_scoped_paye_positive_count integer := NULL::integer;
  v_batch_scoped_paye_positive_count integer := NULL::integer;
  v_authorised_projection_proof_source text := NULL::text;
  v_batch_projection_proof_source text := NULL::text;
  v_authorised_provider_submission_required boolean := false;
  v_batch_provider_submission_required boolean := false;
  v_authorised_provider_submission_attempted boolean := false;
  v_batch_provider_submission_attempted boolean := false;
  v_authorised_submitted_to_bank boolean := false;
  v_batch_submitted_to_bank boolean := false;
  v_expected_allow_zero_scopes boolean := false;
  v_expected_scoped_no_transfer boolean := false;
  v_expected_no_bank_payment boolean := false;
  v_auth_binding_valid boolean := false;
  v_projection_contract_valid boolean := false;
  v_mode_specific_proof_valid boolean := true;
  v_settlement_proof_blocked boolean := false;
  v_settlement_proof_error_code text := NULL::text;
  v_settlement_proof_error_message text := NULL::text;
  v_authorised_manual_confirmation_mode text := NULL::text;
  v_batch_manual_confirmation_mode text := NULL::text;
  v_expected_manual_confirmation_mode text := NULL::text;
  v_authorised_external_settlement_comment text := NULL::text;
  v_batch_external_settlement_comment text := NULL::text;
  v_authorised_external_proof_source text := NULL::text;
  v_batch_external_proof_source text := NULL::text;
  v_authorised_external_confirmed boolean := false;
  v_batch_external_confirmed boolean := false;
  v_authorised_csv_uploaded_confirmed boolean := false;
  v_batch_csv_uploaded_confirmed boolean := false;
  v_authorised_csv_bank_confirm_ref text := NULL::text;
  v_batch_csv_bank_confirm_ref text := NULL::text;
  v_authorised_csv_evidence_json jsonb := '{}'::jsonb;
  v_batch_csv_evidence_json jsonb := '{}'::jsonb;
  v_authorised_csv_currentness_json jsonb := '{}'::jsonb;
  v_batch_csv_currentness_json jsonb := '{}'::jsonb;
  v_authorised_csv_scope text := NULL::text;
  v_authorised_csv_paye_hash text := NULL::text;
  v_authorised_csv_projection_hash text := NULL::text;
  v_authorised_csv_row_count integer := NULL::integer;
  v_authorised_csv_total numeric(14,2) := NULL::numeric;
  v_batch_csv_scope text := NULL::text;
  v_batch_csv_paye_hash text := NULL::text;
  v_batch_csv_projection_hash text := NULL::text;
  v_batch_csv_row_count integer := NULL::integer;
  v_batch_csv_total numeric(14,2) := NULL::numeric;
  v_current_csv_export_json jsonb := '{}'::jsonb;
  v_current_csv_scope text := NULL::text;
  v_current_csv_paye_hash text := NULL::text;
  v_current_csv_projection_hash text := NULL::text;
  v_current_csv_row_count integer := NULL::integer;
  v_current_csv_total numeric(14,2) := NULL::numeric;
  v_local_manual_provider_scope_count integer := 0;
  v_local_manual_provider_chunk_count integer := 0;
  v_local_manual_provider_attempt_count integer := 0;
  v_local_manual_provider_event_count integer := 0;
  v_local_manual_provider_transfer_count integer := 0;
  v_local_manual_provider_evidence_count integer := 0;
  v_local_manual_transfer_scope_count integer := 0;
  v_local_manual_invalid_transfer_scope_count integer := 0;
  v_local_manual_scope_item_mismatch_count integer := 0;
  v_local_manual_uncovered_item_count integer := 0;
  v_local_manual_scope_amount_total numeric(14,2) := 0;
  v_local_manual_transfer_amount_total numeric(14,2) := 0;
  v_local_manual_scope_item_amount_total numeric(14,2) := 0;
  v_local_manual_scope_proof_json jsonb := '{}'::jsonb;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS') THEN
    RAISE EXCEPTION 'p_scope must be ALL, PAYE, UMBRELLA, or LOANS';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  -- Resolve the execution binding without holding a row lock, then acquire
  -- canonical locks in root-execution -> requested-operation -> batch order.
  -- The requested operation and batch binding are re-read and revalidated after
  -- the canonical locks are held so an initial read can never become authority.
  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
  END IF;

  IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
    RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'SETTLEMENT_OPERATION_BATCH_MISMATCH',
      'message', 'The settlement operation is not durably bound to the requested pay batch.',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
  END IF;

  IF v_operation_row.operation_type = 'PAYMENT_EXECUTE' THEN
    v_transfer_scope_operation_id := v_operation_row.id;
  ELSIF v_operation_row.root_operation_id IS NOT NULL THEN
    v_transfer_scope_operation_id := v_operation_row.root_operation_id;
  ELSE
    SELECT CASE
      WHEN JSONB_TYPEOF(batch_row.execution_intent_json) = 'object'
        THEN COALESCE(batch_row.execution_intent_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END
    INTO v_batch_intent_json
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_transfer_scope_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
      v_execution_operation_resolved_from_batch_intent := true;
    ELSE
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
        'code', 'EXECUTION_OPERATION_REQUIRED',
        'message', 'The settlement operation is not bound to a payment execution operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT execution_operation.*
  INTO v_execution_operation_row
  FROM public.banking_pay_operations AS execution_operation
  WHERE execution_operation.id = v_transfer_scope_operation_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_execution_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR v_execution_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'EXECUTION_OPERATION_INVALID',
      'message', 'The resolved payment execution operation is missing or incompatible with this settlement operation.',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_operation_id', CASE
        WHEN v_transfer_scope_operation_id IS NULL THEN NULL::text
        ELSE v_transfer_scope_operation_id::text
      END
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id = v_transfer_scope_operation_id THEN
    v_operation_row := v_execution_operation_row;
  ELSE
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;
  END IF;

  IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
    RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'SETTLEMENT_OPERATION_BATCH_MISMATCH',
      'message', 'The settlement operation is not durably bound to the requested pay batch.',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
  END IF;

  IF v_operation_row.operation_type = 'PAYMENT_EXECUTE' THEN
    IF v_operation_row.id IS DISTINCT FROM v_transfer_scope_operation_id THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
        'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
        'message', 'The requested operation changed its execution-operation binding while settlement scope seeding was acquiring its canonical locks.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'locked_execution_operation_id', v_transfer_scope_operation_id::text,
        'current_operation_type', v_operation_row.operation_type,
        'current_root_operation_id', CASE WHEN v_operation_row.root_operation_id IS NULL THEN NULL::text ELSE v_operation_row.root_operation_id::text END
      )::text USING ERRCODE = 'P0001';
    END IF;
  ELSIF v_operation_row.root_operation_id IS NOT NULL THEN
    IF v_operation_row.root_operation_id IS DISTINCT FROM v_transfer_scope_operation_id THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
        'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
        'message', 'The settlement operation changed its execution-operation binding while settlement scope seeding was acquiring its canonical locks.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'locked_execution_operation_id', v_transfer_scope_operation_id::text,
        'current_root_operation_id', v_operation_row.root_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  ELSE
    v_execution_operation_resolved_from_batch_intent := true;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
  END IF;

  v_batch_intent_json := CASE
    WHEN JSONB_TYPEOF(v_batch_row.execution_intent_json) = 'object'
      THEN COALESCE(v_batch_row.execution_intent_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  IF v_execution_operation_resolved_from_batch_intent
     AND (
       CASE
         WHEN NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           THEN (v_batch_intent_json->>'operation_id')::uuid
         ELSE NULL::uuid
       END
     ) IS DISTINCT FROM v_transfer_scope_operation_id THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
      'message', 'The batch execution-operation binding changed while settlement scope seeding was acquiring its canonical locks.',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'locked_execution_operation_id', v_transfer_scope_operation_id::text,
      'current_batch_execution_operation_id', NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
    )::text USING ERRCODE = 'P0001';
  END IF;


  v_settlement_input_json := COALESCE(v_operation_row.input_json, '{}'::jsonb);
  v_root_input_json := COALESCE(v_execution_operation_row.input_json, '{}'::jsonb);
  v_root_execution_mode_raw := UPPER(NULLIF(BTRIM(COALESCE(
    v_root_input_json->>'execution_mode',
    v_root_input_json->>'executionMode',
    ''
  )), ''));
  v_root_execution_mode := CASE
    WHEN v_root_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_root_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_root_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE NULL::text
  END;

  IF v_root_execution_mode IS NULL THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', CASE WHEN v_root_execution_mode_raw IS NULL THEN 'MISSING_DURABLE_EXECUTION_MODE' ELSE 'UNSUPPORTED_DURABLE_EXECUTION_MODE' END,
      'message', 'The root payment execution operation has no supported durable execution mode.',
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'durable_execution_mode_raw', v_root_execution_mode_raw,
      'supported_execution_modes', JSONB_BUILD_ARRAY('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_is_local_manual_mode := v_root_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT');
  v_settlement_operation_mode_raw := UPPER(NULLIF(BTRIM(COALESCE(
    v_settlement_input_json->>'execution_mode',
    v_settlement_input_json->>'settlement_mode',
    ''
  )), ''));
  v_settlement_operation_mode := CASE
    WHEN v_settlement_operation_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_settlement_operation_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_settlement_operation_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE NULL::text
  END;

  IF v_settlement_operation_mode_raw IS NOT NULL
     AND v_settlement_operation_mode IS DISTINCT FROM v_root_execution_mode THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'SETTLEMENT_OPERATION_EXECUTION_MODE_MISMATCH',
      'message', 'The settlement operation mode does not match the durable root payment execution mode.',
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_operation_mode', v_settlement_operation_mode,
      'root_execution_mode', v_root_execution_mode
    )::text USING ERRCODE = 'P0001';
  END IF;


  IF v_operation_row.operation_type = 'PAYMENT_SETTLEMENT' THEN
    IF NULLIF(BTRIM(COALESCE(
         v_settlement_input_json->>'execution_operation_id',
         v_settlement_input_json->>'root_execution_operation_id',
         v_settlement_input_json->>'root_operation_id',
         ''
       )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_child_execution_operation_id := COALESCE(
        v_settlement_input_json->>'execution_operation_id',
        v_settlement_input_json->>'root_execution_operation_id',
        v_settlement_input_json->>'root_operation_id'
      )::uuid;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_settlement_input_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_child_auth_request_id := (v_settlement_input_json->>'auth_request_id')::uuid;
    END IF;

    v_child_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_settlement_input_json->>'pay_channel_scope',
      v_settlement_input_json->>'scope',
      ''
    )), ''));
    v_child_payment_date := NULLIF(BTRIM(COALESCE(v_settlement_input_json->>'payment_date', '')), '');
  END IF;

  IF v_is_local_manual_mode
     AND v_operation_row.operation_type = 'PAYMENT_SETTLEMENT'
     AND (
       v_child_execution_operation_id IS DISTINCT FROM v_transfer_scope_operation_id
       OR v_settlement_operation_mode IS DISTINCT FROM v_root_execution_mode
       OR v_child_scope IS DISTINCT FROM v_scope
       OR v_child_auth_request_id IS NULL
       OR v_child_payment_date IS NULL
     ) THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_OPERATION_SETTLEMENT_SCOPE_SEED',
      'code', 'LOCAL_MANUAL_SETTLEMENT_CHILD_BINDING_INVALID',
      'message', 'The local/manual settlement child is missing or mismatches the frozen root execution, mode, scope, authorisation request, or payment date.',
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'child_execution_operation_id', CASE WHEN v_child_execution_operation_id IS NULL THEN NULL::text ELSE v_child_execution_operation_id::text END,
      'root_execution_mode', v_root_execution_mode,
      'child_execution_mode', v_settlement_operation_mode,
      'requested_scope', v_scope,
      'child_scope', v_child_scope,
      'child_auth_request_id', CASE WHEN v_child_auth_request_id IS NULL THEN NULL::text ELSE v_child_auth_request_id::text END,
      'child_payment_date', v_child_payment_date,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_operation_settlement_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_operation_settlement_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(
    p_pay_batch_id,
    'ALL'
  ) AS projection_row;

  DROP TABLE IF EXISTS pg_temp.tmp_operation_settlement_scoped_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_operation_settlement_scoped_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(
    p_pay_batch_id,
    v_scope
  ) AS projection_row;

  SELECT
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'MISSING'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'ZERO'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'POSITIVE'
    )::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_current_missing_paye_count,
    v_current_global_explicit_zero_count,
    v_current_global_paye_positive_count,
    v_current_global_positive_payment_count,
    v_current_global_invalid_payment_row_count,
    v_current_paye_net_state_hash,
    v_all_bank_payment_projection_hash
  FROM pg_temp.tmp_operation_settlement_projection_rows AS projection_row;

  SELECT
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'MISSING'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'ZERO'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'POSITIVE'
    )::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    ROUND(
      COALESCE(SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment), 0),
      2
    )::numeric(14,2),
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_current_scoped_missing_paye_count,
    v_current_scoped_explicit_zero_count,
    v_current_scoped_paye_positive_count,
    v_current_scoped_positive_payment_count,
    v_current_scoped_positive_payment_total,
    v_current_scoped_invalid_payment_row_count,
    v_current_scoped_paye_net_state_hash,
    v_current_bank_payment_projection_hash
  FROM pg_temp.tmp_operation_settlement_scoped_projection_rows AS projection_row;

  v_current_missing_paye_count := COALESCE(v_current_missing_paye_count, 0);
  v_current_global_explicit_zero_count := COALESCE(v_current_global_explicit_zero_count, 0);
  v_current_global_paye_positive_count := COALESCE(v_current_global_paye_positive_count, 0);
  v_current_global_positive_payment_count := COALESCE(v_current_global_positive_payment_count, 0);
  v_current_global_invalid_payment_row_count := COALESCE(v_current_global_invalid_payment_row_count, 0);
  v_current_scoped_missing_paye_count := COALESCE(v_current_scoped_missing_paye_count, 0);
  v_current_scoped_explicit_zero_count := COALESCE(v_current_scoped_explicit_zero_count, 0);
  v_current_scoped_paye_positive_count := COALESCE(v_current_scoped_paye_positive_count, 0);
  v_current_scoped_positive_payment_count := COALESCE(v_current_scoped_positive_payment_count, 0);
  v_current_scoped_positive_payment_total := ROUND(COALESCE(v_current_scoped_positive_payment_total, 0), 2);
  v_current_scoped_invalid_payment_row_count := COALESCE(v_current_scoped_invalid_payment_row_count, 0);
  v_current_paye_net_state_hash := COALESCE(
    v_current_paye_net_state_hash,
    MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text)
  );
  v_all_bank_payment_projection_hash := COALESCE(
    v_all_bank_payment_projection_hash,
    MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text)
  );
  v_current_scoped_paye_net_state_hash := COALESCE(
    v_current_scoped_paye_net_state_hash,
    MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_scope, 'rows', '[]'::jsonb)::text)
  );
  v_current_bank_payment_projection_hash := COALESCE(
    v_current_bank_payment_projection_hash,
    MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_scope, 'rows', '[]'::jsonb)::text)
  );

  v_proof_validation_outcome := 'TRANSFER_BACKED_PROJECTION_DIAGNOSTIC_ONLY';
  v_expected_allow_zero_scopes := v_current_scoped_explicit_zero_count > 0;
  v_expected_scoped_no_transfer := (
    v_current_scoped_missing_paye_count = 0
    AND v_current_scoped_explicit_zero_count > 0
    AND v_current_scoped_positive_payment_count = 0
    AND v_current_scoped_invalid_payment_row_count = 0
  );
  v_expected_no_bank_payment := (
    v_expected_scoped_no_transfer
    AND v_current_missing_paye_count = 0
    AND v_current_global_positive_payment_count = 0
    AND v_current_global_invalid_payment_row_count = 0
  );

  v_auth_request_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_settlement_input_json->>'auth_request_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_settlement_input_json #>> '{execution_intent_json,auth_request_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_root_input_json->>'auth_request_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_root_input_json #>> '{execution_intent_json,auth_request_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
  );

  IF v_auth_request_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_auth_request_id := v_auth_request_id_text::uuid;
  END IF;

  IF v_auth_request_id IS NOT NULL THEN
    SELECT
      auth_request.state,
      CASE
        WHEN JSONB_TYPEOF(auth_request.execution_intent_json) = 'object'
          THEN COALESCE(auth_request.execution_intent_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
    INTO
      v_auth_state,
      v_auth_intent_json
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.id = v_auth_request_id
      AND auth_request.pay_batch_id = p_pay_batch_id
    FOR UPDATE;
    v_auth_request_found := FOUND;
  ELSE
    v_auth_request_found := false;
  END IF;

  IF v_auth_request_found IS NOT TRUE
     OR UPPER(BTRIM(COALESCE(v_auth_state, ''))) <> 'AUTHORISED'
     OR v_auth_intent_json = '{}'::jsonb
     OR v_batch_intent_json = '{}'::jsonb THEN
    v_settlement_proof_blocked := true;
    v_settlement_proof_error_code := 'AUTHORISED_EXECUTION_INTENT_REQUIRED';
    v_settlement_proof_error_message := 'An authorised server-frozen execution intent bound to the root payment execution is required before settlement scopes can be seeded.';
  ELSE
    IF NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_operation_id := (v_auth_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_intent_auth_request_id := (v_auth_intent_json->>'auth_request_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_intent_auth_request_id := (v_batch_intent_json->>'auth_request_id')::uuid;
    END IF;

    v_authorised_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;
    v_batch_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;
    v_authorised_scope := UPPER(NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'pay_channel_scope', v_auth_intent_json->>'scope', '')), ''));
    v_batch_scope := UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'pay_channel_scope', v_batch_intent_json->>'scope', '')), ''));
    v_authorised_payment_date := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'payment_date', '')), '');
    v_batch_payment_date := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'payment_date', '')), '');
    v_root_payment_date := NULLIF(BTRIM(COALESCE(v_root_input_json->>'payment_date', '')), '');

    v_authorised_paye_net_state_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'global_paye_net_state_hash', v_auth_intent_json->>'paye_net_state_hash', '')), '');
    v_batch_paye_net_state_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'global_paye_net_state_hash', v_batch_intent_json->>'paye_net_state_hash', '')), '');
    v_authorised_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'global_bank_payment_projection_hash', '')), '');
    v_batch_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'global_bank_payment_projection_hash', '')), '');
    v_authorised_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'scoped_paye_net_state_hash', '')), '');
    v_batch_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'scoped_paye_net_state_hash', '')), '');
    v_authorised_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'scoped_bank_payment_projection_hash', v_auth_intent_json->>'bank_payment_projection_hash', '')), '');
    v_batch_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'scoped_bank_payment_projection_hash', v_batch_intent_json->>'bank_payment_projection_hash', '')), '');

    IF COALESCE(v_auth_intent_json->>'global_missing_explicit_paye_input_count', v_auth_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_authorised_missing_count := COALESCE(v_auth_intent_json->>'global_missing_explicit_paye_input_count', v_auth_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_missing_count := COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'global_explicit_zero_count', v_auth_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_authorised_global_zero_count := COALESCE(v_auth_intent_json->>'global_explicit_zero_count', v_auth_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_global_zero_count := COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'global_paye_positive_count', '') ~ '^[0-9]+$' THEN
      v_authorised_global_paye_positive_count := (v_auth_intent_json->>'global_paye_positive_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_paye_positive_count', '') ~ '^[0-9]+$' THEN
      v_batch_global_paye_positive_count := (v_batch_intent_json->>'global_paye_positive_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_authorised_global_positive_count := (v_auth_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_global_positive_count := (v_batch_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_authorised_global_invalid_count := (v_auth_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_global_invalid_count := (v_batch_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_authorised_scoped_missing_count := (v_auth_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_scoped_missing_count := (v_batch_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_authorised_scoped_zero_count := (v_auth_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_scoped_zero_count := (v_batch_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_paye_positive_count', '') ~ '^[0-9]+$' THEN
      v_authorised_scoped_paye_positive_count := (v_auth_intent_json->>'scoped_paye_positive_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_paye_positive_count', '') ~ '^[0-9]+$' THEN
      v_batch_scoped_paye_positive_count := (v_batch_intent_json->>'scoped_paye_positive_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_positive_bank_payment_count', v_auth_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_authorised_scoped_positive_count := COALESCE(v_auth_intent_json->>'scoped_positive_bank_payment_count', v_auth_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_scoped_positive_count := COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_positive_bank_payment_total', v_auth_intent_json->>'positive_bank_payment_total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_authorised_scoped_positive_total := ROUND(COALESCE(v_auth_intent_json->>'scoped_positive_bank_payment_total', v_auth_intent_json->>'positive_bank_payment_total')::numeric, 2)::numeric(14,2);
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_total', v_batch_intent_json->>'positive_bank_payment_total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_batch_scoped_positive_total := ROUND(COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_total', v_batch_intent_json->>'positive_bank_payment_total')::numeric, 2)::numeric(14,2);
    END IF;
    IF COALESCE(v_auth_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_authorised_scoped_invalid_count := (v_auth_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_scoped_invalid_count := (v_batch_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;

    v_authorised_scoped_no_transfer_execution := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_scoped_no_transfer_execution := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_no_bank_payment_execution := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_no_bank_payment_execution := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_allow_zero_scopes := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_allow_zero_scopes := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_suppress_remittances := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_suppress_remittances := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_server_owned_proof := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_server_owned_proof := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_projection_proof_source := UPPER(NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'payment_projection_proof_source', '')), ''));
    v_batch_projection_proof_source := UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'payment_projection_proof_source', '')), ''));
    v_authorised_provider_submission_required := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'provider_submission_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_provider_submission_required := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'provider_submission_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_provider_submission_attempted := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'provider_submission_attempted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_provider_submission_attempted := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'provider_submission_attempted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_authorised_submitted_to_bank := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'submitted_to_bank', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_submitted_to_bank := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'submitted_to_bank', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    v_auth_binding_valid := (
      v_auth_operation_id = v_transfer_scope_operation_id
      AND v_batch_operation_id = v_transfer_scope_operation_id
      AND v_auth_intent_auth_request_id = v_auth_request_id
      AND v_batch_intent_auth_request_id = v_auth_request_id
      AND v_authorised_execution_mode = v_root_execution_mode
      AND v_batch_execution_mode = v_root_execution_mode
      AND v_authorised_scope = v_scope
      AND v_batch_scope = v_scope
      AND v_authorised_payment_date ~ '^\d{4}-\d{2}-\d{2}$'
      AND v_batch_payment_date IS NOT DISTINCT FROM v_authorised_payment_date
      AND (v_root_payment_date IS NULL OR v_root_payment_date IS NOT DISTINCT FROM v_authorised_payment_date)
      AND (
        v_is_local_manual_mode IS NOT TRUE
        OR (
          v_child_execution_operation_id = v_transfer_scope_operation_id
          AND v_child_auth_request_id = v_auth_request_id
          AND v_settlement_operation_mode = v_root_execution_mode
          AND v_child_scope = v_scope
          AND v_child_payment_date = v_authorised_payment_date
        )
      )
      AND NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
      AND NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
    );

    v_projection_contract_valid := (
      v_auth_binding_valid
      AND v_authorised_server_owned_proof IS TRUE
      AND v_batch_server_owned_proof IS TRUE
      AND v_authorised_projection_proof_source = 'PAY_BATCH_AUTH_START'
      AND v_batch_projection_proof_source = 'PAY_BATCH_AUTH_START'
      AND v_authorised_paye_net_state_hash IS NOT NULL
      AND v_authorised_paye_net_state_hash = v_batch_paye_net_state_hash
      AND v_authorised_paye_net_state_hash = v_current_paye_net_state_hash
      AND v_authorised_global_bank_payment_projection_hash IS NOT NULL
      AND v_authorised_global_bank_payment_projection_hash = v_batch_global_bank_payment_projection_hash
      AND v_authorised_global_bank_payment_projection_hash = v_all_bank_payment_projection_hash
      AND v_authorised_scoped_paye_net_state_hash IS NOT NULL
      AND v_authorised_scoped_paye_net_state_hash = v_batch_scoped_paye_net_state_hash
      AND v_authorised_scoped_paye_net_state_hash = v_current_scoped_paye_net_state_hash
      AND v_authorised_bank_payment_projection_hash IS NOT NULL
      AND v_authorised_bank_payment_projection_hash = v_batch_bank_payment_projection_hash
      AND v_authorised_bank_payment_projection_hash = v_current_bank_payment_projection_hash
      AND v_authorised_missing_count IS NOT NULL
      AND v_authorised_missing_count = v_batch_missing_count
      AND v_authorised_missing_count = v_current_missing_paye_count
      AND v_authorised_global_zero_count IS NOT NULL
      AND v_authorised_global_zero_count = v_batch_global_zero_count
      AND v_authorised_global_zero_count = v_current_global_explicit_zero_count
      AND v_authorised_global_paye_positive_count IS NOT NULL
      AND v_authorised_global_paye_positive_count = v_batch_global_paye_positive_count
      AND v_authorised_global_paye_positive_count = v_current_global_paye_positive_count
      AND v_authorised_global_positive_count IS NOT NULL
      AND v_authorised_global_positive_count = v_batch_global_positive_count
      AND v_authorised_global_positive_count = v_current_global_positive_payment_count
      AND v_authorised_global_invalid_count IS NOT NULL
      AND v_authorised_global_invalid_count = v_batch_global_invalid_count
      AND v_authorised_global_invalid_count = v_current_global_invalid_payment_row_count
      AND v_authorised_scoped_missing_count IS NOT NULL
      AND v_authorised_scoped_missing_count = v_batch_scoped_missing_count
      AND v_authorised_scoped_missing_count = v_current_scoped_missing_paye_count
      AND v_authorised_scoped_zero_count IS NOT NULL
      AND v_authorised_scoped_zero_count = v_batch_scoped_zero_count
      AND v_authorised_scoped_zero_count = v_current_scoped_explicit_zero_count
      AND v_authorised_scoped_paye_positive_count IS NOT NULL
      AND v_authorised_scoped_paye_positive_count = v_batch_scoped_paye_positive_count
      AND v_authorised_scoped_paye_positive_count = v_current_scoped_paye_positive_count
      AND v_authorised_scoped_positive_count IS NOT NULL
      AND v_authorised_scoped_positive_count = v_batch_scoped_positive_count
      AND v_authorised_scoped_positive_count = v_current_scoped_positive_payment_count
      AND v_authorised_scoped_positive_total IS NOT NULL
      AND v_authorised_scoped_positive_total = v_batch_scoped_positive_total
      AND ROUND(v_authorised_scoped_positive_total, 2) = ROUND(v_current_scoped_positive_payment_total, 2)
      AND v_authorised_scoped_invalid_count IS NOT NULL
      AND v_authorised_scoped_invalid_count = v_batch_scoped_invalid_count
      AND v_authorised_scoped_invalid_count = v_current_scoped_invalid_payment_row_count
      AND v_authorised_allow_zero_scopes IS NOT DISTINCT FROM v_batch_allow_zero_scopes
      AND v_authorised_allow_zero_scopes IS NOT DISTINCT FROM v_expected_allow_zero_scopes
      AND v_authorised_scoped_no_transfer_execution IS NOT DISTINCT FROM v_batch_scoped_no_transfer_execution
      AND v_authorised_scoped_no_transfer_execution IS NOT DISTINCT FROM v_expected_scoped_no_transfer
      AND v_authorised_no_bank_payment_execution IS NOT DISTINCT FROM v_batch_no_bank_payment_execution
      AND v_authorised_no_bank_payment_execution IS NOT DISTINCT FROM v_expected_no_bank_payment
      AND v_authorised_suppress_remittances IS NOT DISTINCT FROM v_batch_suppress_remittances
      AND v_current_missing_paye_count = 0
      AND v_current_scoped_invalid_payment_row_count = 0
    );

    IF v_auth_binding_valid IS NOT TRUE THEN
      v_settlement_proof_blocked := true;
      v_settlement_proof_error_code := 'AUTHORISED_EXECUTION_INTENT_BINDING_MISMATCH';
      v_settlement_proof_error_message := 'The authorised request, batch intent, requested scope, payment date, or durable root execution mode is not consistently bound to this settlement operation.';
    ELSIF v_is_local_manual_mode AND v_projection_contract_valid IS NOT TRUE THEN
      v_settlement_proof_blocked := true;
      v_settlement_proof_error_code := 'AUTHORISED_PAYMENT_PROJECTION_PROOF_INVALID';
      v_settlement_proof_error_message := 'The authorised local/manual settlement projection proof does not match the batch intent and current frozen batch projection.';
    END IF;

    v_expected_manual_confirmation_mode := CASE
      WHEN v_root_execution_mode = 'CSV_SETTLEMENT' AND v_current_scoped_positive_payment_count > 0 THEN 'BANK_UPLOAD_CONFIRMED'
      WHEN v_root_execution_mode = 'CSV_SETTLEMENT' THEN 'ZERO_ROW_REVIEW_NO_BANK_PAYMENT'
      WHEN v_root_execution_mode = 'EXTERNAL_SETTLEMENT' AND v_current_scoped_positive_payment_count > 0 THEN 'EXTERNAL_SETTLEMENT_CONFIRMED'
      WHEN v_root_execution_mode = 'EXTERNAL_SETTLEMENT' THEN 'NO_BANK_PAYMENT_CONFIRMED'
      ELSE NULL::text
    END;
    v_authorised_manual_confirmation_mode := UPPER(NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'manual_confirmation_mode', '')), ''));
    v_batch_manual_confirmation_mode := UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'manual_confirmation_mode', '')), ''));

    IF v_root_execution_mode = 'CSV_SETTLEMENT' THEN
      v_authorised_csv_uploaded_confirmed := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_batch_csv_uploaded_confirmed := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_authorised_csv_bank_confirm_ref := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'csv_bank_confirm_ref', '')), '');
      v_batch_csv_bank_confirm_ref := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'csv_bank_confirm_ref', '')), '');
      v_authorised_csv_evidence_json := CASE WHEN JSONB_TYPEOF(v_auth_intent_json->'bank_csv_evidence') = 'object' THEN COALESCE(v_auth_intent_json->'bank_csv_evidence', '{}'::jsonb) ELSE '{}'::jsonb END;
      v_batch_csv_evidence_json := CASE WHEN JSONB_TYPEOF(v_batch_intent_json->'bank_csv_evidence') = 'object' THEN COALESCE(v_batch_intent_json->'bank_csv_evidence', '{}'::jsonb) ELSE '{}'::jsonb END;
      v_authorised_csv_currentness_json := CASE WHEN JSONB_TYPEOF(v_auth_intent_json->'csv_currentness_proof') = 'object' THEN COALESCE(v_auth_intent_json->'csv_currentness_proof', '{}'::jsonb) ELSE '{}'::jsonb END;
      v_batch_csv_currentness_json := CASE WHEN JSONB_TYPEOF(v_batch_intent_json->'csv_currentness_proof') = 'object' THEN COALESCE(v_batch_intent_json->'csv_currentness_proof', '{}'::jsonb) ELSE '{}'::jsonb END;
      v_authorised_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'bank_csv_scope', v_authorised_csv_evidence_json->>'scope', '')), ''));
      v_batch_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'bank_csv_scope', v_batch_csv_evidence_json->>'scope', '')), ''));
      v_authorised_csv_paye_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'bank_csv_paye_net_state_hash', v_authorised_csv_evidence_json->>'paye_net_state_hash', '')), '');
      v_batch_csv_paye_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'bank_csv_paye_net_state_hash', v_batch_csv_evidence_json->>'paye_net_state_hash', '')), '');
      v_authorised_csv_projection_hash := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'bank_csv_bank_payment_projection_hash', v_authorised_csv_evidence_json->>'bank_payment_projection_hash', '')), '');
      v_batch_csv_projection_hash := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'bank_csv_bank_payment_projection_hash', v_batch_csv_evidence_json->>'bank_payment_projection_hash', '')), '');
      IF COALESCE(v_auth_intent_json->>'bank_csv_row_count', v_authorised_csv_evidence_json->>'row_count', '') ~ '^[0-9]+$' THEN
        v_authorised_csv_row_count := COALESCE(v_auth_intent_json->>'bank_csv_row_count', v_authorised_csv_evidence_json->>'row_count')::integer;
      END IF;
      IF COALESCE(v_batch_intent_json->>'bank_csv_row_count', v_batch_csv_evidence_json->>'row_count', '') ~ '^[0-9]+$' THEN
        v_batch_csv_row_count := COALESCE(v_batch_intent_json->>'bank_csv_row_count', v_batch_csv_evidence_json->>'row_count')::integer;
      END IF;
      IF COALESCE(v_auth_intent_json->>'bank_csv_total_amount', v_authorised_csv_evidence_json->>'total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        v_authorised_csv_total := ROUND(COALESCE(v_auth_intent_json->>'bank_csv_total_amount', v_authorised_csv_evidence_json->>'total_amount')::numeric, 2)::numeric(14,2);
      END IF;
      IF COALESCE(v_batch_intent_json->>'bank_csv_total_amount', v_batch_csv_evidence_json->>'total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        v_batch_csv_total := ROUND(COALESCE(v_batch_intent_json->>'bank_csv_total_amount', v_batch_csv_evidence_json->>'total_amount')::numeric, 2)::numeric(14,2);
      END IF;

      v_current_csv_export_json := CASE
        WHEN JSONB_TYPEOF(v_batch_row.bank_csv_export_json) = 'object'
          THEN COALESCE(v_batch_row.bank_csv_export_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END;
      v_current_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(
        v_current_csv_export_json->>'scope',
        v_current_csv_export_json->>'pay_channel_scope',
        v_current_csv_export_json->>'payChannelScope',
        ''
      )), ''));
      v_current_csv_paye_hash := NULLIF(BTRIM(COALESCE(
        v_current_csv_export_json->>'paye_net_state_hash',
        v_current_csv_export_json->>'current_paye_net_state_hash',
        v_current_csv_export_json->>'payeNetStateHash',
        ''
      )), '');
      v_current_csv_projection_hash := NULLIF(BTRIM(COALESCE(
        v_current_csv_export_json->>'bank_payment_projection_hash',
        v_current_csv_export_json->>'current_bank_payment_projection_hash',
        v_current_csv_export_json->>'bankPaymentProjectionHash',
        ''
      )), '');
      IF COALESCE(v_current_csv_export_json->>'row_count', v_current_csv_export_json->>'rowCount', '') ~ '^[0-9]+$' THEN
        v_current_csv_row_count := COALESCE(v_current_csv_export_json->>'row_count', v_current_csv_export_json->>'rowCount')::integer;
      END IF;
      IF COALESCE(v_current_csv_export_json->>'total_amount', v_current_csv_export_json->>'totalAmount', v_current_csv_export_json->>'total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        v_current_csv_total := ROUND(COALESCE(v_current_csv_export_json->>'total_amount', v_current_csv_export_json->>'totalAmount', v_current_csv_export_json->>'total')::numeric, 2)::numeric(14,2);
      END IF;

      v_mode_specific_proof_valid := (
        v_authorised_manual_confirmation_mode = v_expected_manual_confirmation_mode
        AND v_batch_manual_confirmation_mode = v_expected_manual_confirmation_mode
        AND v_authorised_csv_uploaded_confirmed IS TRUE
        AND v_batch_csv_uploaded_confirmed IS TRUE
        AND v_authorised_csv_bank_confirm_ref IS NOT DISTINCT FROM v_batch_csv_bank_confirm_ref
        AND (v_current_scoped_positive_payment_count = 0 OR v_authorised_csv_bank_confirm_ref IS NOT NULL)
        AND LOWER(BTRIM(COALESCE(v_auth_intent_json->>'csv_evidence_validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_intent_json->>'csv_evidence_validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_auth_intent_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_auth_intent_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_intent_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_intent_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_authorised_csv_evidence_json->>'validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_csv_evidence_json->>'validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_authorised_csv_currentness_json->>'validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_authorised_csv_currentness_json->>'current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_csv_currentness_json->>'validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_batch_csv_currentness_json->>'current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(NULLIF(BTRIM(COALESCE(v_authorised_csv_currentness_json->>'scope', '')), '')) = v_scope
        AND UPPER(NULLIF(BTRIM(COALESCE(v_batch_csv_currentness_json->>'scope', '')), '')) = v_scope
        AND NULLIF(BTRIM(COALESCE(v_authorised_csv_currentness_json->>'paye_net_state_hash', '')), '') = v_current_scoped_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(v_batch_csv_currentness_json->>'paye_net_state_hash', '')), '') = v_current_scoped_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(v_authorised_csv_currentness_json->>'bank_payment_projection_hash', '')), '') = v_current_bank_payment_projection_hash
        AND NULLIF(BTRIM(COALESCE(v_batch_csv_currentness_json->>'bank_payment_projection_hash', '')), '') = v_current_bank_payment_projection_hash
        AND COALESCE(v_authorised_csv_currentness_json->>'row_count', '') = v_current_scoped_positive_payment_count::text
        AND COALESCE(v_batch_csv_currentness_json->>'row_count', '') = v_current_scoped_positive_payment_count::text
        AND CASE WHEN COALESCE(v_authorised_csv_currentness_json->>'total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ROUND((v_authorised_csv_currentness_json->>'total_amount')::numeric, 2) = ROUND(v_current_scoped_positive_payment_total, 2) ELSE false END
        AND CASE WHEN COALESCE(v_batch_csv_currentness_json->>'total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ROUND((v_batch_csv_currentness_json->>'total_amount')::numeric, 2) = ROUND(v_current_scoped_positive_payment_total, 2) ELSE false END
        AND v_authorised_csv_evidence_json IS NOT DISTINCT FROM v_batch_csv_evidence_json
        AND v_authorised_csv_currentness_json IS NOT DISTINCT FROM v_batch_csv_currentness_json
        AND v_current_csv_export_json <> '{}'::jsonb
        AND v_current_csv_scope = v_scope
        AND v_current_csv_paye_hash = v_current_scoped_paye_net_state_hash
        AND v_current_csv_projection_hash = v_current_bank_payment_projection_hash
        AND v_current_csv_row_count = v_current_scoped_positive_payment_count
        AND ROUND(v_current_csv_total, 2) = ROUND(v_current_scoped_positive_payment_total, 2)
        AND v_authorised_csv_scope = v_scope
        AND v_batch_csv_scope = v_scope
        AND v_authorised_csv_paye_hash = v_current_scoped_paye_net_state_hash
        AND v_batch_csv_paye_hash = v_current_scoped_paye_net_state_hash
        AND v_authorised_csv_projection_hash = v_current_bank_payment_projection_hash
        AND v_batch_csv_projection_hash = v_current_bank_payment_projection_hash
        AND v_authorised_csv_row_count = v_current_scoped_positive_payment_count
        AND v_batch_csv_row_count = v_current_scoped_positive_payment_count
        AND ROUND(v_authorised_csv_total, 2) = ROUND(v_current_scoped_positive_payment_total, 2)
        AND ROUND(v_batch_csv_total, 2) = ROUND(v_current_scoped_positive_payment_total, 2)
        AND LOWER(BTRIM(COALESCE(v_authorised_csv_evidence_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND NULLIF(BTRIM(COALESCE(v_authorised_csv_evidence_json->>'csv_bank_confirm_ref', '')), '') IS NOT DISTINCT FROM v_authorised_csv_bank_confirm_ref
      );
    ELSIF v_root_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
      v_authorised_external_settlement_comment := NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'external_settlement_comment', '')), '');
      v_batch_external_settlement_comment := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'external_settlement_comment', '')), '');
      v_authorised_external_proof_source := UPPER(NULLIF(BTRIM(COALESCE(v_auth_intent_json->>'external_settlement_proof_source', '')), ''));
      v_batch_external_proof_source := UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'external_settlement_proof_source', '')), ''));
      v_authorised_external_confirmed := LOWER(BTRIM(COALESCE(v_auth_intent_json->>'external_settlement_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_batch_external_confirmed := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'external_settlement_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_mode_specific_proof_valid := (
        v_authorised_manual_confirmation_mode = v_expected_manual_confirmation_mode
        AND v_batch_manual_confirmation_mode = v_expected_manual_confirmation_mode
        AND v_authorised_external_proof_source = 'EXTERNAL_MANUAL_CONFIRMATION'
        AND v_batch_external_proof_source = 'EXTERNAL_MANUAL_CONFIRMATION'
        AND v_authorised_external_confirmed IS TRUE
        AND v_batch_external_confirmed IS TRUE
        AND v_authorised_external_settlement_comment IS NOT DISTINCT FROM v_batch_external_settlement_comment
        AND (v_current_scoped_positive_payment_count = 0 OR v_authorised_external_settlement_comment IS NOT NULL)
      );
    ELSE
      v_mode_specific_proof_valid := true;
    END IF;

    IF v_is_local_manual_mode THEN
      IF v_authorised_provider_submission_required
         OR v_batch_provider_submission_required
         OR v_authorised_provider_submission_attempted
         OR v_batch_provider_submission_attempted
         OR v_authorised_submitted_to_bank
         OR v_batch_submitted_to_bank THEN
        v_mode_specific_proof_valid := false;
      END IF;

      IF v_projection_contract_valid IS TRUE AND v_mode_specific_proof_valid IS NOT TRUE THEN
        v_settlement_proof_blocked := true;
        v_settlement_proof_error_code := CASE WHEN v_root_execution_mode = 'CSV_SETTLEMENT' THEN 'AUTHORISED_CSV_SETTLEMENT_PROOF_INVALID' ELSE 'AUTHORISED_EXTERNAL_SETTLEMENT_PROOF_INVALID' END;
        v_settlement_proof_error_message := CASE WHEN v_root_execution_mode = 'CSV_SETTLEMENT' THEN 'The authorised CSV settlement evidence is missing, stale, or inconsistent with the current frozen payment projection.' ELSE 'The authorised external/manual settlement evidence is missing or inconsistent with the current frozen payment projection.' END;
      END IF;
    END IF;

    v_zero_scope_creation_authorised := (
      v_projection_contract_valid
      AND v_expected_allow_zero_scopes
      AND v_authorised_allow_zero_scopes
    );

    IF v_expected_allow_zero_scopes AND v_zero_scope_creation_authorised IS NOT TRUE THEN
      v_zero_scope_proof_blocked := true;
      v_zero_scope_proof_error_code := 'AUTHORISED_PAYMENT_PROJECTION_PROOF_INVALID';
      v_zero_scope_proof_error_message := 'The authorised explicit-zero payment proof no longer matches the current frozen payment projection. No-bank settlement scopes were not created.';
    END IF;

    IF v_projection_contract_valid THEN
      v_proof_validation_outcome := CASE
        WHEN v_authorised_no_bank_payment_execution THEN 'VALIDATED_NO_BANK_PAYMENT_FROM_AUTHORISED_INTENT'
        WHEN v_current_scoped_explicit_zero_count > 0 AND v_current_scoped_positive_payment_count > 0 THEN 'VALIDATED_MIXED_ZERO_AND_TRANSFER_FROM_AUTHORISED_INTENT'
        WHEN v_root_execution_mode = 'CSV_SETTLEMENT' THEN 'VALIDATED_CSV_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
        WHEN v_root_execution_mode = 'EXTERNAL_SETTLEMENT' THEN 'VALIDATED_EXTERNAL_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
        WHEN v_authorised_scoped_no_transfer_execution THEN 'VALIDATED_SCOPED_NO_TRANSFER_FROM_AUTHORISED_INTENT'
        ELSE 'VALIDATED_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
      END;
    END IF;
  END IF;

  IF v_settlement_proof_blocked THEN
    UPDATE public.banking_pay_operations AS operation_review_update
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        resume_reason = v_settlement_proof_error_code,
        progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_review_update.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'review_required', true,
            'review_reason_code', v_settlement_proof_error_code,
            'review_message', v_settlement_proof_error_message,
            'execution_mode', v_root_execution_mode,
            'auth_request_id', CASE WHEN v_auth_request_id IS NULL THEN NULL::text ELSE v_auth_request_id::text END,
            'proof_validation_outcome', v_proof_validation_outcome,
            'review_required_at_utc', v_now::text
          )
        ),
        error_json = JSONB_STRIP_NULLS(
          COALESCE(operation_review_update.error_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'code', v_settlement_proof_error_code,
            'message', v_settlement_proof_error_message,
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_transfer_scope_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'execution_mode', v_root_execution_mode,
            'detected_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE operation_review_update.id = p_operation_id;

    RETURN JSONB_BUILD_OBJECT(
      'ok', false,
      'hard_blocker', true,
      'code', v_settlement_proof_error_code,
      'message', v_settlement_proof_error_message,
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'execution_mode', v_root_execution_mode,
      'auth_request_id', CASE WHEN v_auth_request_id IS NULL THEN NULL::text ELSE v_auth_request_id::text END,
      'auth_state', v_auth_state,
      'auth_binding_valid', v_auth_binding_valid,
      'projection_contract_valid', v_projection_contract_valid,
      'mode_specific_proof_valid', v_mode_specific_proof_valid,
      'proof_validation_outcome', v_proof_validation_outcome
    );
  END IF;

  IF v_is_local_manual_mode THEN
    SELECT COUNT(*)::integer
    INTO v_local_manual_provider_scope_count
    FROM public.banking_pay_operation_transfer_scope AS provider_scope
    WHERE provider_scope.pay_batch_id = p_pay_batch_id
      AND (
        v_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(provider_scope.pay_channel, ''))) = v_scope
        OR (
          v_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(provider_scope.pay_channel, ''))) = 'PAYE'
        )
      )
      AND (
        COALESCE(provider_scope.provider_submit_ready, false)
        OR UPPER(BTRIM(COALESCE(provider_scope.provider_submit_state, 'NOT_READY'))) <> 'NOT_READY'
        OR provider_scope.provider_submit_chunk_id IS NOT NULL
        OR provider_scope.provider_submit_claimed_at_utc IS NOT NULL
        OR COALESCE(provider_scope.provider_submit_attempt_count, 0) > 0
        OR NULLIF(BTRIM(COALESCE(provider_scope.provider_idempotency_key, '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(provider_scope.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(provider_scope.provider_transaction_id, '')), '') IS NOT NULL
        OR provider_scope.provider_request_prepared_at_utc IS NOT NULL
        OR provider_scope.provider_request_sending_at_utc IS NOT NULL
        OR provider_scope.provider_request_sent_at_utc IS NOT NULL
        OR provider_scope.provider_response_at_utc IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(provider_scope.provider_submission_status, '')), '') IS NOT NULL
        OR UPPER(BTRIM(COALESCE(provider_scope.status, ''))) = 'SUBMITTED'
      );

    SELECT COUNT(*)::integer
    INTO v_local_manual_provider_chunk_count
    FROM public.banking_pay_operation_chunks AS provider_chunk
    JOIN public.banking_pay_operations AS provider_chunk_operation
      ON provider_chunk_operation.id = provider_chunk.operation_id
     AND provider_chunk_operation.pay_batch_id = p_pay_batch_id
    WHERE (
        UPPER(BTRIM(COALESCE(provider_chunk.phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND', 'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES')
        OR UPPER(BTRIM(COALESCE(provider_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
      );

    SELECT COUNT(*)::integer
    INTO v_local_manual_provider_attempt_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt
    WHERE provider_attempt.operation_id = v_transfer_scope_operation_id
       OR provider_attempt.pay_batch_id = p_pay_batch_id;

    SELECT COUNT(*)::integer
    INTO v_local_manual_provider_event_count
    FROM public.pay_bank_transfer_events AS provider_event
    WHERE provider_event.pay_batch_id = p_pay_batch_id
      AND (
        UPPER(BTRIM(COALESCE(provider_event.event_source, ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
        OR NULLIF(BTRIM(COALESCE(provider_event.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(provider_event.provider_transaction_id, '')), '') IS NOT NULL
      );

    SELECT COUNT(*)::integer
    INTO v_local_manual_provider_transfer_count
    FROM public.pay_bank_transfers AS provider_transfer
    WHERE provider_transfer.pay_batch_id = p_pay_batch_id
      AND (
        v_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(provider_transfer.pay_channel, ''))) = v_scope
        OR (
          v_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(provider_transfer.pay_channel, ''))) = 'PAYE'
        )
      )
      AND (
        NULLIF(BTRIM(COALESCE(provider_transfer.rail_tx_id, '')), '') IS NOT NULL
        OR UPPER(BTRIM(COALESCE(provider_transfer.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
        OR LOWER(BTRIM(COALESCE(provider_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(provider_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(provider_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(provider_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      );

    v_local_manual_provider_evidence_count :=
      COALESCE(v_local_manual_provider_scope_count, 0)
      + COALESCE(v_local_manual_provider_chunk_count, 0)
      + COALESCE(v_local_manual_provider_attempt_count, 0)
      + COALESCE(v_local_manual_provider_event_count, 0)
      + COALESCE(v_local_manual_provider_transfer_count, 0);

    IF v_local_manual_provider_evidence_count > 0 THEN
      UPDATE public.banking_pay_operations AS operation_provider_review
      SET status = 'REVIEW_REQUIRED',
          phase = 'REVIEW_REQUIRED',
          runner_state = 'WAITING_USER_REVIEW',
          requires_user_action = true,
          resume_reason = 'LOCAL_MANUAL_PROVIDER_EVIDENCE_CONFLICT',
          progress_json = JSONB_STRIP_NULLS(
            COALESCE(operation_provider_review.progress_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'review_required', true,
              'review_reason_code', 'LOCAL_MANUAL_PROVIDER_EVIDENCE_CONFLICT',
              'execution_mode', v_root_execution_mode,
              'provider_scope_evidence_count', v_local_manual_provider_scope_count,
              'provider_chunk_count', v_local_manual_provider_chunk_count,
              'provider_attempt_count', v_local_manual_provider_attempt_count,
              'provider_event_count', v_local_manual_provider_event_count,
              'provider_transfer_evidence_count', v_local_manual_provider_transfer_count,
              'review_required_at_utc', v_now::text
            )
          ),
          error_json = JSONB_BUILD_OBJECT(
            'code', 'LOCAL_MANUAL_PROVIDER_EVIDENCE_CONFLICT',
            'message', 'Local/manual settlement scope seeding cannot continue because provider submission evidence exists.',
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_transfer_scope_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'execution_mode', v_root_execution_mode,
            'provider_scope_evidence_count', v_local_manual_provider_scope_count,
            'provider_chunk_count', v_local_manual_provider_chunk_count,
            'provider_attempt_count', v_local_manual_provider_attempt_count,
            'provider_event_count', v_local_manual_provider_event_count,
            'provider_transfer_evidence_count', v_local_manual_provider_transfer_count,
            'detected_at_utc', v_now::text
          ),
          updated_at_utc = v_now
      WHERE operation_provider_review.id = p_operation_id;

      RETURN JSONB_BUILD_OBJECT(
        'ok', false,
        'hard_blocker', true,
        'code', 'LOCAL_MANUAL_PROVIDER_EVIDENCE_CONFLICT',
        'message', 'Local/manual settlement scope seeding cannot continue because provider submission evidence exists.',
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_transfer_scope_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'execution_mode', v_root_execution_mode,
        'provider_scope_evidence_count', v_local_manual_provider_scope_count,
        'provider_chunk_count', v_local_manual_provider_chunk_count,
        'provider_attempt_count', v_local_manual_provider_attempt_count,
        'provider_event_count', v_local_manual_provider_event_count,
        'provider_transfer_evidence_count', v_local_manual_provider_transfer_count,
        'provider_evidence_count', v_local_manual_provider_evidence_count
      );
    END IF;

    v_local_manual_scope_proof_json := JSONB_STRIP_NULLS(
      JSONB_BUILD_OBJECT(
        'server_owned_payment_projection_proof', true,
        'payment_projection_proof_source', 'PAY_BATCH_AUTH_START',
        'execution_operation_id', v_transfer_scope_operation_id::text,
        'settlement_operation_id', p_operation_id::text,
        'auth_request_id', v_auth_request_id::text,
        'execution_mode', v_root_execution_mode,
        'authorised_execution_mode', v_authorised_execution_mode,
        'projection_scope', v_scope,
        'authorised_scope', v_authorised_scope,
        'payment_date', v_authorised_payment_date,
        'authorised_payment_date', v_authorised_payment_date
      )
      || JSONB_BUILD_OBJECT(
        'global_paye_net_state_hash', v_authorised_paye_net_state_hash,
        'paye_net_state_hash', v_authorised_paye_net_state_hash,
        'global_bank_payment_projection_hash', v_authorised_global_bank_payment_projection_hash,
        'scoped_paye_net_state_hash', v_authorised_scoped_paye_net_state_hash,
        'scoped_bank_payment_projection_hash', v_authorised_bank_payment_projection_hash,
        'bank_payment_projection_hash', v_authorised_bank_payment_projection_hash,
        'authorised_missing_explicit_paye_input_count', v_authorised_missing_count,
        'authorised_explicit_zero_count', v_authorised_global_zero_count,
        'authorised_global_paye_positive_count', v_authorised_global_paye_positive_count,
        'authorised_global_positive_bank_payment_count', v_authorised_global_positive_count,
        'authorised_global_invalid_payment_row_count', v_authorised_global_invalid_count,
        'authorised_scoped_missing_explicit_paye_input_count', v_authorised_scoped_missing_count,
        'authorised_scoped_explicit_zero_count', v_authorised_scoped_zero_count,
        'authorised_scoped_paye_positive_count', v_authorised_scoped_paye_positive_count,
        'authorised_scoped_positive_bank_payment_count', v_authorised_scoped_positive_count,
        'authorised_scoped_positive_bank_payment_total', v_authorised_scoped_positive_total,
        'authorised_scoped_invalid_payment_row_count', v_authorised_scoped_invalid_count
      )
      || JSONB_BUILD_OBJECT(
        'scoped_no_transfer_execution', v_authorised_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_authorised_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_authorised_allow_zero_scopes,
        'suppress_remittances', v_authorised_suppress_remittances,
        'provider_submission_required', false,
        'provider_submission_attempted', false,
        'submitted_to_bank', false,
        'manual_confirmation_mode', v_authorised_manual_confirmation_mode
      )
      || CASE
           WHEN v_root_execution_mode = 'CSV_SETTLEMENT' THEN JSONB_BUILD_OBJECT(
             'csv_uploaded_confirmed', v_authorised_csv_uploaded_confirmed,
             'csv_bank_confirm_ref', v_authorised_csv_bank_confirm_ref,
             'bank_csv_evidence', v_authorised_csv_evidence_json,
             'csv_evidence_validated', true,
             'csv_currentness_proof', v_authorised_csv_currentness_json,
             'bank_csv_scope', v_authorised_csv_scope,
             'bank_csv_paye_net_state_hash', v_authorised_csv_paye_hash,
             'bank_csv_bank_payment_projection_hash', v_authorised_csv_projection_hash,
             'bank_csv_row_count', v_authorised_csv_row_count,
             'bank_csv_total_amount', v_authorised_csv_total
           )
           WHEN v_root_execution_mode = 'EXTERNAL_SETTLEMENT' THEN JSONB_BUILD_OBJECT(
             'external_settlement_comment', v_authorised_external_settlement_comment,
             'external_settlement_proof_source', v_authorised_external_proof_source,
             'external_settlement_confirmed', v_authorised_external_confirmed
           )
           ELSE '{}'::jsonb
         END
    );
  END IF;

  IF v_zero_scope_creation_authorised THEN
    WITH explicit_zero_candidate AS MATERIALIZED (
      SELECT DISTINCT
        projection_row.pay_batch_candidate_id,
        projection_row.candidate_id
      FROM pg_temp.tmp_operation_settlement_scoped_projection_rows AS projection_row
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.pay_channel = 'PAYE'
        AND projection_row.paye_net_classification = 'ZERO'
        AND projection_row.has_effective_paye_input IS TRUE
        AND projection_row.effective_paye_net_input_id IS NOT NULL
        AND projection_row.final_frozen_bank_amount IS NOT NULL
        AND ROUND(projection_row.final_frozen_bank_amount, 2) = 0
        AND v_scope IN ('ALL', 'PAYE', 'LOANS')
    ), explicit_zero_evidence AS (
      SELECT 'PAY_BATCH_ITEM_TRANSFER'::text AS evidence_kind, linked_item.id::text AS evidence_id
      FROM explicit_zero_candidate AS zero_candidate
      JOIN public.pay_batch_items AS linked_item
        ON linked_item.pay_batch_candidate_id = zero_candidate.pay_batch_candidate_id
       AND UPPER(BTRIM(COALESCE(linked_item.pay_channel, ''))) = 'PAYE'
       AND COALESCE(linked_item.is_voided, false) = false
       AND linked_item.pay_bank_transfer_id IS NOT NULL

      UNION ALL

      SELECT 'TRANSFER_SCOPE'::text, transfer_scope_evidence.id::text
      FROM explicit_zero_candidate AS zero_candidate
      JOIN public.banking_pay_operation_transfer_scope AS transfer_scope_evidence
        ON transfer_scope_evidence.operation_id = v_transfer_scope_operation_id
       AND transfer_scope_evidence.pay_batch_id = p_pay_batch_id
       AND transfer_scope_evidence.candidate_id = zero_candidate.candidate_id
       AND UPPER(BTRIM(COALESCE(transfer_scope_evidence.pay_channel, ''))) = 'PAYE'
      WHERE transfer_scope_evidence.pay_bank_transfer_id IS NOT NULL
         OR transfer_scope_evidence.provider_submit_attempt_count > 0
         OR transfer_scope_evidence.provider_request_sent_at_utc IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_request_id, '')), '') IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_transaction_id, '')), '') IS NOT NULL

      UNION ALL

      SELECT 'PAY_BANK_TRANSFER'::text, transfer_evidence.id::text
      FROM explicit_zero_candidate AS zero_candidate
      JOIN public.pay_bank_transfers AS transfer_evidence
        ON transfer_evidence.pay_batch_id = p_pay_batch_id
       AND transfer_evidence.candidate_id = zero_candidate.candidate_id
       AND UPPER(BTRIM(COALESCE(transfer_evidence.pay_channel, ''))) = 'PAYE'

      UNION ALL

      SELECT 'PAY_BANK_TRANSFER_EVENT'::text, transfer_event_evidence.id::text
      FROM explicit_zero_candidate AS zero_candidate
      JOIN public.pay_bank_transfer_events AS transfer_event_evidence
        ON transfer_event_evidence.pay_batch_id = p_pay_batch_id
       AND transfer_event_evidence.candidate_id = zero_candidate.candidate_id
      LEFT JOIN public.pay_bank_transfers AS event_transfer_evidence
        ON event_transfer_evidence.id = transfer_event_evidence.pay_bank_transfer_id
      WHERE transfer_event_evidence.pay_bank_transfer_id IS NULL
         OR UPPER(BTRIM(COALESCE(event_transfer_evidence.pay_channel, ''))) = 'PAYE'

      UNION ALL

      SELECT 'PROVIDER_ATTEMPT'::text, provider_attempt_evidence.id::text
      FROM explicit_zero_candidate AS zero_candidate
      JOIN public.banking_pay_operation_transfer_scope AS provider_attempt_scope
        ON provider_attempt_scope.operation_id = v_transfer_scope_operation_id
       AND provider_attempt_scope.pay_batch_id = p_pay_batch_id
       AND provider_attempt_scope.candidate_id = zero_candidate.candidate_id
       AND UPPER(BTRIM(COALESCE(provider_attempt_scope.pay_channel, ''))) = 'PAYE'
      JOIN public.banking_pay_operation_provider_attempts AS provider_attempt_evidence
        ON provider_attempt_evidence.operation_id = v_transfer_scope_operation_id
       AND provider_attempt_evidence.transfer_scope_id = provider_attempt_scope.id
    )
    SELECT COUNT(*)::integer
    INTO v_explicit_zero_transfer_evidence_count
    FROM explicit_zero_evidence;

    IF COALESCE(v_explicit_zero_transfer_evidence_count, 0) > 0 THEN
      v_zero_scope_creation_authorised := false;
      v_zero_scope_proof_blocked := true;
      v_zero_scope_proof_error_code := 'EXPLICIT_ZERO_PAYE_TRANSFER_EVIDENCE_CONFLICT';
      v_zero_scope_proof_error_message := 'No-bank settlement scopes were not created because transfer, transfer-event, or provider evidence exists for an explicit-zero PAYE candidate.';
      v_proof_validation_outcome := 'ZERO_SCOPE_EVIDENCE_CONFLICT';
    END IF;
  END IF;

  IF v_is_local_manual_mode
     AND v_zero_scope_proof_blocked
     AND COALESCE(v_explicit_zero_transfer_evidence_count, 0) > 0 THEN
    UPDATE public.banking_pay_operations AS operation_zero_review
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        resume_reason = COALESCE(v_zero_scope_proof_error_code, 'EXPLICIT_ZERO_PAYE_TRANSFER_EVIDENCE_CONFLICT'),
        progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_zero_review.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'review_required', true,
            'review_reason_code', COALESCE(v_zero_scope_proof_error_code, 'EXPLICIT_ZERO_PAYE_TRANSFER_EVIDENCE_CONFLICT'),
            'review_message', v_zero_scope_proof_error_message,
            'execution_mode', v_root_execution_mode,
            'explicit_zero_transfer_evidence_count', v_explicit_zero_transfer_evidence_count,
            'review_required_at_utc', v_now::text
          )
        ),
        error_json = JSONB_BUILD_OBJECT(
          'code', COALESCE(v_zero_scope_proof_error_code, 'EXPLICIT_ZERO_PAYE_TRANSFER_EVIDENCE_CONFLICT'),
          'message', v_zero_scope_proof_error_message,
          'operation_id', p_operation_id::text,
          'execution_operation_id', v_transfer_scope_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'scope', v_scope,
          'execution_mode', v_root_execution_mode,
          'explicit_zero_transfer_evidence_count', v_explicit_zero_transfer_evidence_count,
          'detected_at_utc', v_now::text
        ),
        updated_at_utc = v_now
    WHERE operation_zero_review.id = p_operation_id;

    RETURN JSONB_BUILD_OBJECT(
      'ok', false,
      'hard_blocker', true,
      'code', COALESCE(v_zero_scope_proof_error_code, 'EXPLICIT_ZERO_PAYE_TRANSFER_EVIDENCE_CONFLICT'),
      'message', v_zero_scope_proof_error_message,
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'execution_mode', v_root_execution_mode,
      'auth_request_id', CASE WHEN v_auth_request_id IS NULL THEN NULL::text ELSE v_auth_request_id::text END,
      'explicit_zero_transfer_evidence_count', v_explicit_zero_transfer_evidence_count,
      'proof_validation_outcome', 'ZERO_SCOPE_EVIDENCE_CONFLICT'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_settlement_item_transfer_repair;
  CREATE TEMPORARY TABLE pg_temp.tmp_settlement_item_transfer_repair ON COMMIT DROP AS
  SELECT DISTINCT
         transfer_scope_row.id AS transfer_scope_id,
         transfer_scope_row.pay_bank_transfer_id AS pay_bank_transfer_id,
         transfer_scope_item_row.pay_batch_item_id AS pay_batch_item_id,
         batch_item.pay_bank_transfer_id AS existing_pay_bank_transfer_id
  FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
  JOIN public.banking_pay_operation_transfer_scope_items AS transfer_scope_item_row
    ON transfer_scope_item_row.operation_id = transfer_scope_row.operation_id
   AND transfer_scope_item_row.pay_batch_id = transfer_scope_row.pay_batch_id
   AND transfer_scope_item_row.transfer_scope_id = transfer_scope_row.id
  JOIN public.pay_batch_items AS batch_item
    ON batch_item.id = transfer_scope_item_row.pay_batch_item_id
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id = batch_item.pay_batch_candidate_id
   AND batch_candidate.pay_batch_id = p_pay_batch_id
  WHERE transfer_scope_row.operation_id = v_transfer_scope_operation_id
    AND transfer_scope_row.pay_batch_id = p_pay_batch_id
    AND transfer_scope_item_row.pay_batch_id = p_pay_batch_id
    AND transfer_scope_row.pay_bank_transfer_id IS NOT NULL
    AND COALESCE(batch_item.is_voided, false) = false
    AND (
      v_scope = 'ALL'
      OR (v_scope = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
      OR upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = v_scope
    );

  SELECT COUNT(*) FILTER (
           WHERE repair_row.existing_pay_bank_transfer_id IS NOT NULL
             AND repair_row.existing_pay_bank_transfer_id <> repair_row.pay_bank_transfer_id
         )::integer,
         COUNT(*) FILTER (
           WHERE repair_row.existing_pay_bank_transfer_id = repair_row.pay_bank_transfer_id
         )::integer
  INTO v_item_transfer_conflict_count,
       v_item_transfer_reused_count
  FROM pg_temp.tmp_settlement_item_transfer_repair AS repair_row;

  WITH repaired_batch_items AS (
    UPDATE public.pay_batch_items AS batch_item_update
    SET pay_bank_transfer_id = repair_row.pay_bank_transfer_id,
        updated_at = v_now
    FROM pg_temp.tmp_settlement_item_transfer_repair AS repair_row
    WHERE batch_item_update.id = repair_row.pay_batch_item_id
      AND batch_item_update.pay_bank_transfer_id IS NULL
      AND repair_row.pay_bank_transfer_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_settlement_item_transfer_repair AS conflict_row
        WHERE conflict_row.pay_batch_item_id = repair_row.pay_batch_item_id
          AND conflict_row.existing_pay_bank_transfer_id IS NOT NULL
          AND conflict_row.existing_pay_bank_transfer_id <> conflict_row.pay_bank_transfer_id
      )
    RETURNING batch_item_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_item_transfer_linked_count
  FROM repaired_batch_items;

  IF COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN
    UPDATE public.banking_pay_operation_transfer_scope AS transfer_scope_conflict_update
    SET status = 'FAILED',
        provider_submit_ready = false,
        provider_submit_state = 'REVIEW_REQUIRED',
        provider_review_required = true,
        provider_unsafe_reason = 'SETTLEMENT_ITEM_TRANSFER_LINK_CONFLICT',
        updated_at_utc = v_now
    FROM (
      SELECT DISTINCT conflict_repair.transfer_scope_id
      FROM pg_temp.tmp_settlement_item_transfer_repair AS conflict_repair
      WHERE conflict_repair.existing_pay_bank_transfer_id IS NOT NULL
        AND conflict_repair.existing_pay_bank_transfer_id <> conflict_repair.pay_bank_transfer_id
    ) AS conflict_scope
    WHERE transfer_scope_conflict_update.id = conflict_scope.transfer_scope_id
      AND transfer_scope_conflict_update.operation_id = v_transfer_scope_operation_id
      AND transfer_scope_conflict_update.pay_batch_id = p_pay_batch_id;

    UPDATE public.banking_pay_operations AS operation_conflict_update
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        progress_json = jsonb_strip_nulls(coalesce(operation_conflict_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'review_required', true,
          'review_reason_code', 'SETTLEMENT_ITEM_TRANSFER_LINK_CONFLICT',
          'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
          'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
          'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
          'detected_at_utc', v_now::text
        )),
        error_json = jsonb_strip_nulls(coalesce(operation_conflict_update.error_json, '{}'::jsonb) || jsonb_build_object(
          'code', 'SETTLEMENT_ITEM_TRANSFER_LINK_CONFLICT',
          'message', 'One or more frozen pay batch items are linked to a different bank transfer. Settlement scope seeding has been blocked.',
          'operation_id', p_operation_id::text,
          'transfer_scope_operation_id', CASE WHEN v_transfer_scope_operation_id IS NULL THEN NULL ELSE v_transfer_scope_operation_id::text END,
          'pay_batch_id', p_pay_batch_id::text,
          'conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
          'detected_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE operation_conflict_update.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', false,
      'hard_blocker', true,
      'code', 'SETTLEMENT_ITEM_TRANSFER_LINK_CONFLICT',
      'operation_id', p_operation_id::text,
      'transfer_scope_operation_id', CASE WHEN v_transfer_scope_operation_id IS NULL THEN NULL ELSE v_transfer_scope_operation_id::text END,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
      'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
      'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
      'message', 'Settlement scope seeding blocked because a batch item is already linked to a different bank transfer.'
    );
  END IF;

  IF v_is_local_manual_mode THEN
    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(local_scope.status, ''))) <> 'PREPARED'
           OR local_scope.pay_bank_transfer_id IS NULL
           OR local_transfer.id IS NULL
           OR local_transfer.pay_batch_id IS DISTINCT FROM local_scope.pay_batch_id
           OR local_transfer.pay_channel IS DISTINCT FROM local_scope.pay_channel
           OR local_transfer.transfer_group_key IS DISTINCT FROM local_scope.transfer_group_key
           OR ROUND(COALESCE(local_scope.prepared_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(local_scope.amount, 0), 2)
           OR ROUND(COALESCE(local_transfer.amount, 0), 2) IS DISTINCT FROM ROUND(COALESCE(local_scope.amount, 0), 2)
           OR UPPER(BTRIM(COALESCE(local_transfer.currency, 'GBP'))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(local_scope.currency, 'GBP')))
           OR NULLIF(BTRIM(COALESCE(local_scope.prepared_scope_hash, '')), '') IS NULL
           OR NULLIF(BTRIM(COALESCE(local_scope.prepared_result_hash, '')), '') IS NULL
           OR COALESCE(local_scope.prepared_item_count, 0) <= 0
           OR COALESCE(local_item_summary.scope_item_count, 0) <> COALESCE(local_scope.prepared_item_count, 0)
           OR ROUND(COALESCE(local_item_summary.scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(local_scope.prepared_amount_total, 0), 2)
           OR COALESCE(local_item_summary.invalid_rollup_count, 0) > 0
           OR COALESCE(local_item_summary.item_binding_conflict_count, 0) > 0
           OR COALESCE(local_scope.provider_submit_ready, false)
           OR UPPER(BTRIM(COALESCE(local_scope.provider_submit_state, 'NOT_READY'))) <> 'NOT_READY'
           OR local_scope.provider_submit_chunk_id IS NOT NULL
           OR local_scope.provider_submit_claimed_at_utc IS NOT NULL
           OR COALESCE(local_scope.provider_submit_attempt_count, 0) > 0
           OR NULLIF(BTRIM(COALESCE(local_scope.provider_idempotency_key, '')), '') IS NOT NULL
           OR NULLIF(BTRIM(COALESCE(local_scope.provider_request_id, '')), '') IS NOT NULL
           OR NULLIF(BTRIM(COALESCE(local_scope.provider_transaction_id, '')), '') IS NOT NULL
           OR local_scope.provider_request_prepared_at_utc IS NOT NULL
           OR local_scope.provider_request_sending_at_utc IS NOT NULL
           OR local_scope.provider_request_sent_at_utc IS NOT NULL
           OR local_scope.provider_response_at_utc IS NOT NULL
           OR NULLIF(BTRIM(COALESCE(local_scope.provider_submission_status, '')), '') IS NOT NULL
           OR COALESCE(local_scope.provider_review_required, false)
           OR NULLIF(BTRIM(COALESCE(local_scope.provider_unsafe_reason, '')), '') IS NOT NULL
           OR NULLIF(BTRIM(COALESCE(local_transfer.rail_tx_id, '')), '') IS NOT NULL
           OR NULLIF(BTRIM(COALESCE(local_transfer.failed_reason, '')), '') IS NOT NULL
           OR UPPER(BTRIM(COALESCE(local_transfer.status, ''))) NOT IN (
                'PENDING',
                CASE WHEN UPPER(BTRIM(COALESCE(v_batch_row.status, ''))) = 'SETTLED' THEN 'COMPLETED' ELSE 'PENDING' END
              )
           OR UPPER(BTRIM(COALESCE(local_transfer.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING', 'CSV_MANUAL_CONFIRM', 'EXTERNAL_SETTLEMENT_CONFIRM')
           OR UPPER(BTRIM(COALESCE(local_transfer.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
           OR LOWER(BTRIM(COALESCE(local_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR LOWER(BTRIM(COALESCE(local_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR LOWER(BTRIM(COALESCE(local_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )::integer,
      COUNT(*) FILTER (
        WHERE COALESCE(local_item_summary.scope_item_count, 0) <> COALESCE(local_scope.prepared_item_count, 0)
           OR ROUND(COALESCE(local_item_summary.scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(local_scope.prepared_amount_total, 0), 2)
           OR COALESCE(local_item_summary.invalid_rollup_count, 0) > 0
           OR COALESCE(local_item_summary.item_binding_conflict_count, 0) > 0
      )::integer,
      ROUND(COALESCE(SUM(local_scope.amount), 0), 2)::numeric(14,2),
      ROUND(COALESCE(SUM(local_transfer.amount), 0), 2)::numeric(14,2),
      ROUND(COALESCE(SUM(local_item_summary.scope_item_amount_total), 0), 2)::numeric(14,2)
    INTO
      v_local_manual_transfer_scope_count,
      v_local_manual_invalid_transfer_scope_count,
      v_local_manual_scope_item_mismatch_count,
      v_local_manual_scope_amount_total,
      v_local_manual_transfer_amount_total,
      v_local_manual_scope_item_amount_total
    FROM public.banking_pay_operation_transfer_scope AS local_scope
    LEFT JOIN public.pay_bank_transfers AS local_transfer
      ON local_transfer.id = local_scope.pay_bank_transfer_id
     AND local_transfer.pay_batch_id = local_scope.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(scope_item.id)::integer AS scope_item_count,
        ROUND(COALESCE(SUM(scope_item.item_amount), 0), 2)::numeric(14,2) AS scope_item_amount_total,
        COUNT(*) FILTER (
          WHERE UPPER(BTRIM(COALESCE(scope_item.rollup_status, ''))) NOT IN ('ROLLED_UP', 'ROLLEDUP', 'READY', 'PREPARED', 'COMPLETE', 'COMPLETED')
        )::integer AS invalid_rollup_count,
        COUNT(*) FILTER (
          WHERE batch_item.id IS NULL
             OR batch_candidate.id IS NULL
             OR batch_candidate.pay_batch_id IS DISTINCT FROM p_pay_batch_id
             OR (batch_item.pay_bank_transfer_id IS NOT NULL AND batch_item.pay_bank_transfer_id IS DISTINCT FROM local_scope.pay_bank_transfer_id)
             OR scope_item.pay_batch_id IS DISTINCT FROM p_pay_batch_id
             OR scope_item.operation_id IS DISTINCT FROM v_transfer_scope_operation_id
        )::integer AS item_binding_conflict_count
      FROM public.banking_pay_operation_transfer_scope_items AS scope_item
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = scope_item.pay_batch_item_id
      LEFT JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = batch_item.pay_batch_candidate_id
      WHERE scope_item.transfer_scope_id = local_scope.id
        AND scope_item.operation_id = v_transfer_scope_operation_id
        AND scope_item.pay_batch_id = p_pay_batch_id
    ) AS local_item_summary ON true
    WHERE local_scope.operation_id = v_transfer_scope_operation_id
      AND local_scope.pay_batch_id = p_pay_batch_id
      AND ROUND(COALESCE(local_scope.prepared_amount_total, local_scope.amount, 0), 2) > 0
      AND (
        v_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(local_scope.pay_channel, ''))) = v_scope
        OR (
          v_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(local_scope.pay_channel, ''))) = 'PAYE'
        )
      );

    WITH positive_projection_candidate AS MATERIALIZED (
      SELECT DISTINCT
        projection_row.pay_batch_candidate_id,
        UPPER(BTRIM(COALESCE(projection_row.pay_channel, ''))) AS pay_channel
      FROM pg_temp.tmp_operation_settlement_scoped_projection_rows AS projection_row
      WHERE projection_row.is_positive_bank_payment
    )
    SELECT COUNT(*)::integer
    INTO v_local_manual_uncovered_item_count
    FROM positive_projection_candidate AS positive_candidate
    JOIN public.pay_batch_items AS positive_item
      ON positive_item.pay_batch_candidate_id = positive_candidate.pay_batch_candidate_id
     AND UPPER(BTRIM(COALESCE(positive_item.pay_channel, ''))) = positive_candidate.pay_channel
     AND COALESCE(positive_item.is_voided, false) = false
     AND COALESCE(positive_item.item_type, '') <> 'DEBT_CREATED'
    WHERE positive_item.pay_bank_transfer_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.banking_pay_operation_transfer_scope_items AS positive_scope_item
         JOIN public.banking_pay_operation_transfer_scope AS positive_scope
           ON positive_scope.id = positive_scope_item.transfer_scope_id
          AND positive_scope.operation_id = v_transfer_scope_operation_id
          AND positive_scope.pay_batch_id = p_pay_batch_id
          AND positive_scope.pay_bank_transfer_id = positive_item.pay_bank_transfer_id
         WHERE positive_scope_item.operation_id = v_transfer_scope_operation_id
           AND positive_scope_item.pay_batch_id = p_pay_batch_id
           AND positive_scope_item.pay_batch_item_id = positive_item.id
       );

    IF COALESCE(v_local_manual_transfer_scope_count, 0) IS DISTINCT FROM COALESCE(v_current_scoped_positive_payment_count, 0)
       OR COALESCE(v_local_manual_invalid_transfer_scope_count, 0) > 0
       OR COALESCE(v_local_manual_scope_item_mismatch_count, 0) > 0
       OR COALESCE(v_local_manual_uncovered_item_count, 0) > 0
       OR ROUND(COALESCE(v_local_manual_scope_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_local_manual_transfer_amount_total, 0), 2)
       OR ROUND(COALESCE(v_local_manual_scope_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_local_manual_scope_item_amount_total, 0), 2)
       OR ROUND(COALESCE(v_local_manual_scope_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_current_scoped_positive_payment_total, 0), 2) THEN
      UPDATE public.banking_pay_operations AS operation_evidence_review
      SET status = 'REVIEW_REQUIRED',
          phase = 'REVIEW_REQUIRED',
          runner_state = 'WAITING_USER_REVIEW',
          requires_user_action = true,
          resume_reason = 'LOCAL_MANUAL_PREPARED_TRANSFER_PROOF_INVALID',
          progress_json = JSONB_STRIP_NULLS(
            COALESCE(operation_evidence_review.progress_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'review_required', true,
              'review_reason_code', 'LOCAL_MANUAL_PREPARED_TRANSFER_PROOF_INVALID',
              'execution_mode', v_root_execution_mode,
              'transfer_scope_count', v_local_manual_transfer_scope_count,
              'invalid_transfer_scope_count', v_local_manual_invalid_transfer_scope_count,
              'scope_item_mismatch_count', v_local_manual_scope_item_mismatch_count,
              'uncovered_item_count', v_local_manual_uncovered_item_count,
              'review_required_at_utc', v_now::text
            )
          ),
          error_json = JSONB_BUILD_OBJECT(
            'code', 'LOCAL_MANUAL_PREPARED_TRANSFER_PROOF_INVALID',
            'message', 'The local/manual prepared transfer evidence is incomplete or does not match frozen transfer-scope and item evidence.',
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_transfer_scope_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'execution_mode', v_root_execution_mode,
            'transfer_scope_count', v_local_manual_transfer_scope_count,
            'invalid_transfer_scope_count', v_local_manual_invalid_transfer_scope_count,
            'scope_item_mismatch_count', v_local_manual_scope_item_mismatch_count,
            'uncovered_item_count', v_local_manual_uncovered_item_count,
            'scope_amount_total', v_local_manual_scope_amount_total,
            'transfer_amount_total', v_local_manual_transfer_amount_total,
            'scope_item_amount_total', v_local_manual_scope_item_amount_total,
            'detected_at_utc', v_now::text
          ),
          updated_at_utc = v_now
      WHERE operation_evidence_review.id = p_operation_id;

      RETURN JSONB_BUILD_OBJECT(
        'ok', false,
        'hard_blocker', true,
        'code', 'LOCAL_MANUAL_PREPARED_TRANSFER_PROOF_INVALID',
        'message', 'The local/manual prepared transfer evidence is incomplete or does not match frozen transfer-scope and item evidence.',
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_transfer_scope_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'execution_mode', v_root_execution_mode,
        'transfer_scope_count', v_local_manual_transfer_scope_count,
        'invalid_transfer_scope_count', v_local_manual_invalid_transfer_scope_count,
        'scope_item_mismatch_count', v_local_manual_scope_item_mismatch_count,
        'uncovered_item_count', v_local_manual_uncovered_item_count,
        'scope_amount_total', v_local_manual_scope_amount_total,
        'transfer_amount_total', v_local_manual_transfer_amount_total,
        'scope_item_amount_total', v_local_manual_scope_item_amount_total
      );
    END IF;
  END IF;

  WITH current_nonpositive_paye_candidate AS MATERIALIZED (
    SELECT DISTINCT
      projection_row.pay_batch_candidate_id,
      projection_row.candidate_id
    FROM pg_temp.tmp_operation_settlement_scoped_projection_rows AS projection_row
    WHERE projection_row.is_paye_net_state_row
      AND projection_row.pay_channel = 'PAYE'
      AND COALESCE(projection_row.paye_net_classification, '') <> 'POSITIVE'
      AND v_scope IN ('ALL', 'PAYE', 'LOANS')
  ), current_explicit_zero_paye_candidate AS MATERIALIZED (
    SELECT
      projection_row.pay_batch_candidate_id,
      projection_row.candidate_id,
      projection_row.effective_paye_net_input_id,
      projection_row.transfer_group_key
    FROM pg_temp.tmp_operation_settlement_scoped_projection_rows AS projection_row
    JOIN public.pay_batch_candidates AS zero_batch_candidate
      ON zero_batch_candidate.id = projection_row.pay_batch_candidate_id
     AND zero_batch_candidate.pay_batch_id = p_pay_batch_id
    WHERE projection_row.is_paye_net_state_row
      AND projection_row.pay_channel = 'PAYE'
      AND projection_row.paye_net_classification = 'ZERO'
      AND projection_row.has_effective_paye_input IS TRUE
      AND projection_row.effective_paye_net_input_id IS NOT NULL
      AND projection_row.final_frozen_bank_amount IS NOT NULL
      AND ROUND(projection_row.final_frozen_bank_amount, 2) = 0
      AND zero_batch_candidate.net_bank_amount IS NOT NULL
      AND ROUND(zero_batch_candidate.net_bank_amount, 2) = 0
      AND v_scope IN ('ALL', 'PAYE', 'LOANS')
  ), explicit_zero_paye_candidate AS MATERIALIZED (
    SELECT
      current_zero.pay_batch_candidate_id,
      current_zero.candidate_id,
      current_zero.effective_paye_net_input_id,
      current_zero.transfer_group_key,
      v_authorised_paye_net_state_hash AS paye_net_state_hash,
      v_authorised_bank_payment_projection_hash AS bank_payment_projection_hash
    FROM current_explicit_zero_paye_candidate AS current_zero
    WHERE v_zero_scope_creation_authorised
  ), item_scope AS (
    SELECT
      batch_candidate.id AS pay_batch_candidate_id,
      batch_candidate.candidate_id,
      upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) AS pay_channel,
      batch_item.pay_bank_transfer_id,
      transfer_row.transfer_group_key,
      transfer_scope_proof.transfer_scope_id,
      transfer_scope_proof.prepared_scope_hash,
      transfer_scope_proof.prepared_result_hash,
      transfer_scope_proof.prepared_amount_total,
      CASE
        WHEN batch_item.pay_bank_transfer_id IS NOT NULL THEN 'transfer:' || batch_item.pay_bank_transfer_id::text
        ELSE 'batch_candidate:' || batch_candidate.id::text || ':channel:' || upper(BTRIM(COALESCE(batch_item.pay_channel, '')))
      END AS settlement_scope_key,
      COALESCE(jsonb_agg(to_jsonb(batch_item.id::text) ORDER BY batch_item.id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(batch_item.id)::integer AS item_count,
      ROUND(COALESCE(SUM(COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)), 0), 2) AS total_amount
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = batch_item.pay_bank_transfer_id
    LEFT JOIN LATERAL (
      SELECT
        root_scope.id AS transfer_scope_id,
        root_scope.prepared_scope_hash,
        root_scope.prepared_result_hash,
        root_scope.prepared_amount_total
      FROM public.banking_pay_operation_transfer_scope AS root_scope
      WHERE v_is_local_manual_mode
        AND root_scope.operation_id = v_transfer_scope_operation_id
        AND root_scope.pay_batch_id = p_pay_batch_id
        AND root_scope.pay_bank_transfer_id = batch_item.pay_bank_transfer_id
      ORDER BY root_scope.id
      LIMIT 1
    ) AS transfer_scope_proof ON true
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      AND NOT (
        upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
        OR batch_candidate.settled_at_utc IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM current_nonpositive_paye_candidate AS nonpositive_candidate
        WHERE nonpositive_candidate.pay_batch_candidate_id = batch_candidate.id
          AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE'
          AND batch_item.pay_bank_transfer_id IS NULL
      )
      AND (
        v_scope = 'ALL'
        OR (v_scope = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
        OR upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = v_scope
      )
      AND (
        v_is_local_manual_mode IS NOT TRUE
        OR (
          batch_item.pay_bank_transfer_id IS NOT NULL
          AND transfer_scope_proof.transfer_scope_id IS NOT NULL
        )
      )
    GROUP BY batch_candidate.id,
             batch_candidate.candidate_id,
             upper(BTRIM(COALESCE(batch_item.pay_channel, ''))),
             batch_item.pay_bank_transfer_id,
             transfer_row.transfer_group_key,
             transfer_scope_proof.transfer_scope_id,
             transfer_scope_proof.prepared_scope_hash,
             transfer_scope_proof.prepared_result_hash,
             transfer_scope_proof.prepared_amount_total,
             CASE
               WHEN batch_item.pay_bank_transfer_id IS NOT NULL THEN 'transfer:' || batch_item.pay_bank_transfer_id::text
               ELSE 'batch_candidate:' || batch_candidate.id::text || ':channel:' || upper(BTRIM(COALESCE(batch_item.pay_channel, '')))
             END
    HAVING ROUND(COALESCE(SUM(COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)), 0), 2) <> 0
  ), zero_item_scope AS (
    SELECT
      zero_candidate.pay_batch_candidate_id,
      zero_candidate.candidate_id,
      'PAYE'::text AS pay_channel,
      NULL::uuid AS pay_bank_transfer_id,
      zero_candidate.transfer_group_key,
      'no_bank_payment:explicit_zero_paye'::text AS settlement_scope_key,
      COALESCE(JSONB_AGG(TO_JSONB(batch_item.id::text) ORDER BY batch_item.id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(batch_item.id)::integer AS item_count,
      0::numeric AS total_amount,
      zero_candidate.effective_paye_net_input_id,
      zero_candidate.paye_net_state_hash,
      zero_candidate.bank_payment_projection_hash
    FROM explicit_zero_paye_candidate AS zero_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = zero_candidate.pay_batch_candidate_id
     AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE'
     AND COALESCE(batch_item.is_voided, false) = false
     AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = zero_candidate.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = p_pay_batch_id
    WHERE NOT (
      upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
      OR batch_candidate.settled_at_utc IS NOT NULL
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS linked_item
        WHERE linked_item.pay_batch_candidate_id = zero_candidate.pay_batch_candidate_id
          AND upper(BTRIM(COALESCE(linked_item.pay_channel, ''))) = 'PAYE'
          AND COALESCE(linked_item.is_voided, false) = false
          AND linked_item.pay_bank_transfer_id IS NOT NULL
      )
    GROUP BY zero_candidate.pay_batch_candidate_id,
             zero_candidate.candidate_id,
             zero_candidate.transfer_group_key,
             zero_candidate.effective_paye_net_input_id,
             zero_candidate.paye_net_state_hash,
             zero_candidate.bank_payment_projection_hash
  ), scope_rows AS (
    SELECT
      item_scope.pay_batch_candidate_id,
      item_scope.candidate_id,
      item_scope.pay_channel,
      'settlement:batch:' || p_pay_batch_id::text || ':batch_candidate:' || item_scope.pay_batch_candidate_id::text || ':channel:' || item_scope.pay_channel || ':scope:' || item_scope.settlement_scope_key AS settlement_key,
      JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_batch_candidate_id', item_scope.pay_batch_candidate_id::text,
        'candidate_id', item_scope.candidate_id::text,
        'pay_channel', item_scope.pay_channel,
        'payment_scope_json', JSONB_STRIP_NULLS(JSONB_BUILD_OBJECT(
          'scope_key', item_scope.settlement_scope_key,
          'pay_bank_transfer_id', CASE WHEN item_scope.pay_bank_transfer_id IS NULL THEN NULL ELSE item_scope.pay_bank_transfer_id::text END,
          'transfer_group_key', item_scope.transfer_group_key
        )),
        'pay_batch_item_ids', item_scope.pay_batch_item_ids_json,
        'item_count', item_scope.item_count,
        'total_amount', item_scope.total_amount,
        'scope', v_scope
      )
      || CASE
           WHEN v_is_local_manual_mode THEN
             v_local_manual_scope_proof_json
             || JSONB_BUILD_OBJECT(
               'scope_kind', 'LOCAL_MANUAL_TRANSFER',
               'local_manual_settlement_scope', true,
               'no_transfer_required', false,
               'provider_payload_required', false,
               'transfer_scope_id', CASE WHEN item_scope.transfer_scope_id IS NULL THEN NULL::text ELSE item_scope.transfer_scope_id::text END,
               'prepared_scope_hash', item_scope.prepared_scope_hash,
               'prepared_result_hash', item_scope.prepared_result_hash,
               'prepared_amount_total', item_scope.prepared_amount_total,
               'pay_bank_transfer_id', CASE WHEN item_scope.pay_bank_transfer_id IS NULL THEN NULL::text ELSE item_scope.pay_bank_transfer_id::text END
             )
           ELSE '{}'::jsonb
         END AS payload_json
    FROM item_scope

    UNION ALL

    SELECT
      zero_item_scope.pay_batch_candidate_id,
      zero_item_scope.candidate_id,
      zero_item_scope.pay_channel,
      'settlement:batch:' || p_pay_batch_id::text || ':batch_candidate:' || zero_item_scope.pay_batch_candidate_id::text || ':channel:PAYE:scope:no_bank_payment:explicit_zero_paye' AS settlement_key,
      JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_batch_candidate_id', zero_item_scope.pay_batch_candidate_id::text,
        'candidate_id', zero_item_scope.candidate_id::text,
        'pay_channel', 'PAYE',
        'scope_kind', 'NO_BANK_PAYMENT',
        'no_bank_payment_reason', 'EXPLICIT_ZERO_PAYE',
        'no_bank_payment_scope', true,
        'server_owned_payment_projection_proof', true,
        'net_bank_amount', 0,
        'has_effective_paye_input', true,
        'effective_paye_net_input_id', zero_item_scope.effective_paye_net_input_id::text,
        'paye_net_state_hash', zero_item_scope.paye_net_state_hash,
        'authorised_paye_net_state_hash', v_authorised_paye_net_state_hash,
        'global_bank_payment_projection_hash', v_authorised_global_bank_payment_projection_hash,
        'scoped_paye_net_state_hash', v_authorised_scoped_paye_net_state_hash,
        'bank_payment_projection_hash', zero_item_scope.bank_payment_projection_hash,
        'authorised_bank_payment_projection_hash', v_authorised_bank_payment_projection_hash,
        'projection_scope', v_scope,
        'authorised_scope', v_authorised_scope,
        'execution_operation_id', v_transfer_scope_operation_id::text,
        'settlement_operation_id', p_operation_id::text,
        'auth_request_id', v_auth_request_id::text,
        'authorised_execution_mode', v_authorised_execution_mode,
        'scoped_no_transfer_execution', v_authorised_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_authorised_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_authorised_allow_zero_scopes,
        'suppress_remittances', v_authorised_suppress_remittances,
        'no_transfer_required', true
      )
      || JSONB_BUILD_OBJECT(
        'authorised_missing_explicit_paye_input_count', v_authorised_missing_count,
        'authorised_explicit_zero_count', v_authorised_global_zero_count,
        'authorised_global_positive_bank_payment_count', v_authorised_global_positive_count,
        'authorised_global_invalid_payment_row_count', v_authorised_global_invalid_count,
        'authorised_scoped_missing_explicit_paye_input_count', v_authorised_scoped_missing_count,
        'authorised_scoped_explicit_zero_count', v_authorised_scoped_zero_count,
        'authorised_scoped_positive_bank_payment_count', v_authorised_scoped_positive_count,
        'authorised_scoped_invalid_payment_row_count', v_authorised_scoped_invalid_count,
        'current_missing_explicit_paye_input_count', v_current_missing_paye_count,
        'current_explicit_zero_count', v_current_global_explicit_zero_count,
        'current_global_positive_bank_payment_count', v_current_global_positive_payment_count,
        'current_global_invalid_payment_row_count', v_current_global_invalid_payment_row_count,
        'current_scoped_missing_explicit_paye_input_count', v_current_scoped_missing_paye_count,
        'current_scoped_explicit_zero_count', v_current_scoped_explicit_zero_count,
        'current_scoped_positive_bank_payment_count', v_current_scoped_positive_payment_count,
        'current_scoped_invalid_payment_row_count', v_current_scoped_invalid_payment_row_count,
        'payment_scope_json', JSONB_BUILD_OBJECT(
          'scope_key', zero_item_scope.settlement_scope_key,
          'scope_kind', 'NO_BANK_PAYMENT',
          'no_bank_payment_reason', 'EXPLICIT_ZERO_PAYE',
          'pay_bank_transfer_id', NULL::text,
          'transfer_group_key', zero_item_scope.transfer_group_key
        ),
        'pay_batch_item_ids', zero_item_scope.pay_batch_item_ids_json,
        'item_count', zero_item_scope.item_count,
        'total_amount', 0,
        'scope', v_scope
      )
      || CASE
           WHEN v_is_local_manual_mode THEN v_local_manual_scope_proof_json
           ELSE '{}'::jsonb
         END AS payload_json
    FROM zero_item_scope
  ), stale_scope AS (
    UPDATE public.banking_pay_operation_settlement_scope AS scope_update
    SET status = 'SKIPPED',
        updated_at_utc = v_now
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.pay_batch_id = p_pay_batch_id
      AND scope_update.status IN ('PENDING', 'FAILED')
      AND UPPER(BTRIM(COALESCE(scope_update.payload_json->>'scope_kind', ''))) <> 'NO_BANK_PAYMENT'
      AND NULLIF(BTRIM(COALESCE(scope_update.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM JSONB_ARRAY_ELEMENTS_TEXT(
          CASE
            WHEN JSONB_TYPEOF(scope_update.payload_json->'pay_batch_item_ids') = 'array'
              THEN scope_update.payload_json->'pay_batch_item_ids'
            ELSE '[]'::jsonb
          END
        ) AS stale_item(item_id_text)
        JOIN public.pay_batch_items AS stale_batch_item
          ON stale_batch_item.id = CASE
               WHEN stale_item.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN stale_item.item_id_text::uuid
               ELSE NULL::uuid
             END
        WHERE stale_batch_item.pay_bank_transfer_id IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM scope_rows
        WHERE scope_rows.settlement_key = scope_update.settlement_key
      )
    RETURNING scope_update.id
  ), upserted_scope AS (
    INSERT INTO public.banking_pay_operation_settlement_scope (
      operation_id,
      pay_batch_id,
      pay_batch_candidate_id,
      candidate_id,
      pay_channel,
      settlement_key,
      payload_json,
      status,
      settlement_event_id,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_operation_id,
      p_pay_batch_id,
      scope_rows.pay_batch_candidate_id,
      scope_rows.candidate_id,
      scope_rows.pay_channel,
      scope_rows.settlement_key,
      scope_rows.payload_json,
      'PENDING',
      NULL::uuid,
      v_now,
      v_now
    FROM scope_rows
    ON CONFLICT (operation_id, settlement_key)
    DO UPDATE
    SET pay_batch_candidate_id = CASE WHEN public.banking_pay_operation_settlement_scope.status = 'SETTLED' THEN public.banking_pay_operation_settlement_scope.pay_batch_candidate_id ELSE EXCLUDED.pay_batch_candidate_id END,
        candidate_id = CASE WHEN public.banking_pay_operation_settlement_scope.status = 'SETTLED' THEN public.banking_pay_operation_settlement_scope.candidate_id ELSE EXCLUDED.candidate_id END,
        pay_channel = CASE WHEN public.banking_pay_operation_settlement_scope.status = 'SETTLED' THEN public.banking_pay_operation_settlement_scope.pay_channel ELSE EXCLUDED.pay_channel END,
        payload_json = CASE WHEN public.banking_pay_operation_settlement_scope.status = 'SETTLED' THEN public.banking_pay_operation_settlement_scope.payload_json ELSE EXCLUDED.payload_json END,
        status = CASE WHEN public.banking_pay_operation_settlement_scope.status = 'SETTLED' THEN public.banking_pay_operation_settlement_scope.status ELSE EXCLUDED.status END,
        updated_at_utc = v_now
    RETURNING public.banking_pay_operation_settlement_scope.id,
              (xmax = 0) AS was_inserted
  )
  SELECT COUNT(*) FILTER (WHERE upserted_scope.was_inserted)::integer,
         COUNT(*) FILTER (WHERE upserted_scope.was_inserted IS NOT TRUE)::integer,
         COUNT(*)::integer,
         COALESCE((SELECT COUNT(*)::integer FROM stale_scope), 0)
  INTO v_created_count,
       v_reused_count,
       v_settlement_unit_count,
       v_stale_scope_skipped_count
  FROM upserted_scope;

  SELECT
    COUNT(*) FILTER (
      WHERE UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = 'PAYE'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        AND scope_row.status <> 'SKIPPED'
    )::integer,
    COUNT(*) FILTER (
      WHERE NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NOT NULL
        AND scope_row.status <> 'SKIPPED'
    )::integer
  INTO
    v_explicit_zero_no_bank_scope_count,
    v_transfer_backed_scope_count
  FROM public.banking_pay_operation_settlement_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id;

  WITH batch_summary AS (
    SELECT
      UPPER(BTRIM(COALESCE(batch_row.status, ''))) AS batch_status,
      UPPER(BTRIM(COALESCE(batch_row.execution_commit_state, ''))) AS execution_commit_state,
      NULLIF(BTRIM(COALESCE(batch_row.execution_commit_ref, '')), '') AS execution_commit_ref,
      batch_row.completed_at_utc IS NOT NULL AS completed_at_utc_present,
      batch_row.freshness_validation_status,
      COALESCE(batch_row.execution_intent_json, '{}'::jsonb) AS execution_intent_json,
      COALESCE(batch_row.settlement_confirmation_json, '{}'::jsonb) AS settlement_confirmation_json
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id
  ), confirmation_summary AS (
    SELECT
      LOWER(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS no_bank_payment_execution,
      UPPER(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'confirmation_mode', ''))) AS confirmation_mode,
      UPPER(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'settlement_mode', ''))) AS settlement_mode,
      NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'local_commit_reference', '')), '') AS local_commit_reference,
      NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'paye_net_state_hash', '')), '') AS paye_net_state_hash,
      NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'bank_payment_projection_hash', '')), '') AS bank_payment_projection_hash,
      UPPER(NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'projection_scope', '')), '')) AS projection_scope,
      NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'auth_request_id', '')), '') AS auth_request_id_text,
      NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'execution_operation_id', '')), '') AS execution_operation_id_text,
      COALESCE(
        NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'settlement_operation_id', '')), ''),
        NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'settlement_operation_id', '')), '')
      ) AS settlement_operation_id_text
    FROM batch_summary
  ), confirmation_auth_summary AS (
    SELECT EXISTS (
      SELECT 1
      FROM public.pay_batch_auth_requests AS auth_request
      CROSS JOIN confirmation_summary
      WHERE auth_request.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(auth_request.state, ''))) = 'AUTHORISED'
        AND auth_request.id::text = confirmation_summary.auth_request_id_text
        AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = confirmation_summary.execution_operation_id_text
        AND LOWER(BTRIM(COALESCE(auth_request.execution_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'paye_net_state_hash', '')), '') = confirmation_summary.paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'bank_payment_projection_hash', '')), '') = confirmation_summary.bank_payment_projection_hash
        AND UPPER(NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'pay_channel_scope', '')), '')) = confirmation_summary.projection_scope
    ) AS confirmation_auth_authorised
  ), transfer_base AS (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      UPPER(BTRIM(COALESCE(transfer_row.status, ''))) AS status_text,
      UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS rail_state_text,
      transfer_row.completed_at_utc
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  ), transfer_flags AS (
    SELECT
      transfer_base.pay_bank_transfer_id,
      (
        transfer_base.status_text IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'VOIDED', 'RETURNED', 'REVERTED', 'BLOCKED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
        OR transfer_base.rail_state_text IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'VOIDED', 'RETURNED', 'REVERTED', 'BLOCKED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
      ) AS is_failed,
      (
        transfer_base.status_text IN ('COMPLETED', 'SETTLED', 'PAID', 'CONFIRMED', 'SUCCESS', 'SUCCEEDED')
        OR transfer_base.rail_state_text IN ('COMPLETED', 'SETTLED', 'PAID', 'CONFIRMED', 'SUCCESS', 'SUCCEEDED')
        OR transfer_base.completed_at_utc IS NOT NULL
      ) AS has_success_evidence
    FROM transfer_base
  ), transfer_summary AS (
    SELECT
      COUNT(*)::integer AS transfer_count,
      COUNT(*) FILTER (WHERE transfer_flags.has_success_evidence AND transfer_flags.is_failed IS NOT TRUE)::integer AS terminal_success_transfer_count,
      COUNT(*) FILTER (WHERE transfer_flags.is_failed)::integer AS terminal_failed_transfer_count,
      COUNT(*) FILTER (WHERE transfer_flags.has_success_evidence IS NOT TRUE AND transfer_flags.is_failed IS NOT TRUE)::integer AS pending_or_unknown_transfer_count
    FROM transfer_flags
  ), event_summary AS (
    SELECT COUNT(*)::integer AS transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event_row
    WHERE transfer_event_row.pay_batch_id = p_pay_batch_id
  ), provider_attempt_summary AS (
    SELECT COUNT(*)::integer AS provider_attempt_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
    LEFT JOIN public.banking_pay_operations AS provider_operation
      ON provider_operation.id = provider_attempt_row.operation_id
    WHERE provider_attempt_row.pay_batch_id = p_pay_batch_id
       OR provider_operation.pay_batch_id = p_pay_batch_id
  ), provider_artifact_summary AS (
    SELECT COUNT(*) FILTER (
      WHERE COALESCE(transfer_scope.provider_submit_attempt_count, 0) > 0
         OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_idempotency_key, '')), '') IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_request_id, '')), '') IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_transaction_id, '')), '') IS NOT NULL
         OR transfer_scope.provider_request_prepared_at_utc IS NOT NULL
         OR transfer_scope.provider_request_sending_at_utc IS NOT NULL
         OR transfer_scope.provider_request_sent_at_utc IS NOT NULL
         OR transfer_scope.provider_response_at_utc IS NOT NULL
         OR UPPER(BTRIM(COALESCE(transfer_scope.provider_submit_state, 'NOT_READY'))) IN (
           'CLAIMED', 'REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL',
           'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'CHUNK_FINALISED'
         )
    )::integer AS provider_artifact_count
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope
    WHERE transfer_scope.pay_batch_id = p_pay_batch_id
  ), candidate_summary AS (
    SELECT
      COUNT(*)::integer AS candidate_count,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
           OR batch_candidate.settled_at_utc IS NOT NULL
      )::integer AS settled_candidate_count
    FROM public.pay_batch_candidates AS batch_candidate
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
  ), no_bank_scope_identity AS (
    SELECT
      settlement_scope.id AS settlement_scope_id,
      settlement_scope.operation_id,
      settlement_scope.status,
      settlement_scope.payload_json,
      COALESCE(
        NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'auth_request_id', '')), ''),
        confirmation_summary.auth_request_id_text,
        NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'auth_request_id', '')), '')
      ) AS auth_request_id_text,
      COALESCE(
        NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'execution_operation_id', '')), ''),
        CASE WHEN settlement_operation.root_operation_id IS NULL THEN NULL::text ELSE settlement_operation.root_operation_id::text END,
        confirmation_summary.execution_operation_id_text,
        NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'operation_id', '')), '')
      ) AS execution_operation_id_text,
      (
        NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'settlement_operation_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'settlement_operation_id', '')), '') = settlement_scope.operation_id::text
      ) AS payload_settlement_operation_matches,
      (
        confirmation_summary.settlement_operation_id_text IS NULL
        OR settlement_scope.operation_id::text = confirmation_summary.settlement_operation_id_text
      ) AS confirmation_settlement_operation_matches
    FROM public.banking_pay_operation_settlement_scope AS settlement_scope
    JOIN public.banking_pay_operations AS settlement_operation
      ON settlement_operation.id = settlement_scope.operation_id
    CROSS JOIN batch_summary
    CROSS JOIN confirmation_summary
    WHERE settlement_scope.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(settlement_scope.pay_channel, ''))) = 'PAYE'
      AND UPPER(BTRIM(COALESCE(settlement_scope.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
      AND UPPER(BTRIM(COALESCE(settlement_scope.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
  ), no_bank_scope_base AS (
    SELECT
      no_bank_scope_identity.*,
      EXISTS (
        SELECT 1
        FROM public.pay_batch_auth_requests AS auth_request
        WHERE auth_request.pay_batch_id = p_pay_batch_id
          AND UPPER(BTRIM(COALESCE(auth_request.state, ''))) = 'AUTHORISED'
          AND auth_request.id::text = no_bank_scope_identity.auth_request_id_text
          AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = no_bank_scope_identity.execution_operation_id_text
          AND LOWER(BTRIM(COALESCE(auth_request.execution_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'paye_net_state_hash', '')), '') = NULLIF(BTRIM(COALESCE(
            no_bank_scope_identity.payload_json->>'authorised_paye_net_state_hash',
            no_bank_scope_identity.payload_json->>'paye_net_state_hash',
            ''
          )), '')
          AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'bank_payment_projection_hash', '')), '') = NULLIF(BTRIM(COALESCE(
            no_bank_scope_identity.payload_json->>'authorised_bank_payment_projection_hash',
            no_bank_scope_identity.payload_json->>'bank_payment_projection_hash',
            ''
          )), '')
          AND UPPER(NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'pay_channel_scope', '')), '')) = UPPER(NULLIF(BTRIM(COALESCE(
            no_bank_scope_identity.payload_json->>'authorised_scope',
            no_bank_scope_identity.payload_json->>'projection_scope',
            no_bank_scope_identity.payload_json->>'scope',
            ''
          )), ''))
      )
      AND no_bank_scope_identity.payload_settlement_operation_matches
      AND no_bank_scope_identity.confirmation_settlement_operation_matches AS is_authorised
    FROM no_bank_scope_identity
  ), no_bank_scope_summary AS (
    SELECT
      COUNT(DISTINCT no_bank_scope_base.operation_id) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED')::integer AS no_bank_operation_count,
      COUNT(*) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED')::integer AS no_bank_scope_count,
      COUNT(*) FILTER (WHERE no_bank_scope_base.status = 'SETTLED')::integer AS settled_no_bank_scope_count,
      COUNT(*) FILTER (WHERE no_bank_scope_base.status NOT IN ('SETTLED', 'SKIPPED'))::integer AS unresolved_no_bank_scope_count,
      COUNT(*) FILTER (WHERE no_bank_scope_base.status = 'SETTLED' AND no_bank_scope_base.is_authorised)::integer AS authorised_no_bank_scope_count,
      COUNT(*) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED' AND no_bank_scope_base.is_authorised IS NOT TRUE)::integer AS unauthorised_no_bank_scope_count
    FROM no_bank_scope_base
  ), authorised_no_bank_item_ids AS (
    SELECT DISTINCT scope_item.item_id_text::uuid AS pay_batch_item_id
    FROM no_bank_scope_base
    CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(
      CASE
        WHEN JSONB_TYPEOF(no_bank_scope_base.payload_json->'pay_batch_item_ids') = 'array'
          THEN no_bank_scope_base.payload_json->'pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS scope_item(item_id_text)
    WHERE no_bank_scope_base.status = 'SETTLED'
      AND no_bank_scope_base.is_authorised
      AND scope_item.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), item_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE COALESCE(batch_item.is_voided, false) = false
          AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      )::integer AS item_count,
      COUNT(*) FILTER (
        WHERE COALESCE(batch_item.is_voided, false) = false
          AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
          AND batch_item.pay_bank_transfer_id IS NOT NULL
      )::integer AS linked_nonvoid_item_count,
      COUNT(*) FILTER (
        WHERE COALESCE(batch_item.is_voided, false) = false
          AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
          AND (
            batch_item.pay_bank_transfer_id IS NOT NULL
            OR EXISTS (
              SELECT 1
              FROM authorised_no_bank_item_ids AS authorised_item
              WHERE authorised_item.pay_batch_item_id = batch_item.id
            )
          )
      )::integer AS covered_nonvoid_item_count
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
  ), completed_settlement_operation AS (
    SELECT settlement_operation.id AS operation_id
    FROM public.banking_pay_operations AS settlement_operation
    WHERE settlement_operation.pay_batch_id = p_pay_batch_id
      AND settlement_operation.operation_type = 'PAYMENT_SETTLEMENT'
      AND settlement_operation.status = 'COMPLETE'
      AND settlement_operation.phase = 'COMPLETE'
      AND settlement_operation.id <> p_operation_id
    ORDER BY COALESCE(settlement_operation.completed_at_utc, settlement_operation.updated_at_utc, settlement_operation.created_at_utc) DESC,
             settlement_operation.id DESC
    LIMIT 1
  )
  SELECT
    COALESCE(transfer_summary.transfer_count, 0),
    COALESCE(transfer_summary.terminal_success_transfer_count, 0),
    COALESCE(transfer_summary.terminal_failed_transfer_count, 0),
    COALESCE(transfer_summary.pending_or_unknown_transfer_count, 0),
    COALESCE(event_summary.transfer_event_count, 0),
    COALESCE(provider_attempt_summary.provider_attempt_count, 0),
    COALESCE(provider_artifact_summary.provider_artifact_count, 0),
    COALESCE(candidate_summary.candidate_count, 0),
    COALESCE(candidate_summary.settled_candidate_count, 0),
    COALESCE(item_summary.item_count, 0),
    COALESCE(item_summary.linked_nonvoid_item_count, 0),
    COALESCE(item_summary.covered_nonvoid_item_count, 0),
    COALESCE(no_bank_scope_summary.no_bank_operation_count, 0),
    COALESCE(no_bank_scope_summary.no_bank_scope_count, 0),
    COALESCE(no_bank_scope_summary.settled_no_bank_scope_count, 0),
    COALESCE(no_bank_scope_summary.unresolved_no_bank_scope_count, 0),
    COALESCE(no_bank_scope_summary.authorised_no_bank_scope_count, 0),
    COALESCE(no_bank_scope_summary.unauthorised_no_bank_scope_count, 0),
    COALESCE(confirmation_summary.no_bank_payment_execution, false),
    confirmation_summary.confirmation_mode,
    confirmation_summary.settlement_mode,
    confirmation_summary.local_commit_reference,
    COALESCE(confirmation_auth_summary.confirmation_auth_authorised, false),
    completed_settlement_operation.operation_id,
    UPPER(BTRIM(COALESCE(v_batch_row.freshness_validation_status, ''))) NOT IN ('STALE', 'FAILED', 'BLOCKED', 'CONFLICT')
  INTO
    v_transfer_count,
    v_terminal_success_transfer_count,
    v_terminal_failed_transfer_count,
    v_pending_or_unknown_transfer_count,
    v_transfer_event_count,
    v_provider_attempt_count,
    v_provider_artifact_count,
    v_candidate_count,
    v_settled_candidate_count,
    v_item_count,
    v_linked_nonvoid_item_count,
    v_covered_nonvoid_item_count,
    v_no_bank_operation_count,
    v_no_bank_scope_count,
    v_settled_no_bank_scope_count,
    v_unresolved_no_bank_scope_count,
    v_authorised_no_bank_scope_count,
    v_unauthorised_no_bank_scope_count,
    v_confirmation_no_bank,
    v_confirmation_mode,
    v_confirmation_settlement_mode,
    v_confirmation_local_commit_ref,
    v_confirmation_auth_authorised,
    v_existing_completed_settlement_operation_id,
    v_freshness_clean
  FROM transfer_summary
  CROSS JOIN event_summary
  CROSS JOIN provider_attempt_summary
  CROSS JOIN provider_artifact_summary
  CROSS JOIN candidate_summary
  CROSS JOIN item_summary
  CROSS JOIN no_bank_scope_summary
  CROSS JOIN confirmation_summary
  CROSS JOIN confirmation_auth_summary
  LEFT JOIN completed_settlement_operation ON true;

  v_positive_batch_already_settled := (
       UPPER(BTRIM(COALESCE(v_batch_row.status, ''))) = 'SETTLED'
   AND UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, ''))) = 'COMMITTED'
   AND NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
   AND v_batch_row.completed_at_utc IS NOT NULL
   AND COALESCE(v_transfer_count, 0) > 0
   AND COALESCE(v_terminal_success_transfer_count, 0) > 0
   AND COALESCE(v_terminal_failed_transfer_count, 0) = 0
   AND COALESCE(v_pending_or_unknown_transfer_count, 0) = 0
   AND COALESCE(v_candidate_count, 0) > 0
   AND COALESCE(v_settled_candidate_count, 0) = COALESCE(v_candidate_count, 0)
   AND COALESCE(v_no_bank_scope_count, 0) = 0
   AND (COALESCE(v_item_count, 0) = 0 OR COALESCE(v_linked_nonvoid_item_count, 0) = COALESCE(v_item_count, 0))
  );

  v_no_bank_batch_already_settled := (
       UPPER(BTRIM(COALESCE(v_batch_row.status, ''))) = 'SETTLED'
   AND UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, ''))) = 'COMMITTED'
   AND NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') LIKE 'NO_BANK_PAYMENT:%'
   AND v_batch_row.completed_at_utc IS NOT NULL
   AND COALESCE(v_transfer_count, 0) = 0
   AND COALESCE(v_transfer_event_count, 0) = 0
   AND COALESCE(v_provider_attempt_count, 0) = 0
   AND COALESCE(v_provider_artifact_count, 0) = 0
   AND COALESCE(v_candidate_count, 0) > 0
   AND COALESCE(v_settled_candidate_count, 0) = COALESCE(v_candidate_count, 0)
   AND COALESCE(v_confirmation_no_bank, false)
   AND v_confirmation_local_commit_ref IS NOT NULL
   AND v_confirmation_local_commit_ref = NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '')
   AND UPPER(BTRIM(COALESCE(v_confirmation_mode, ''))) IN ('NO_BANK_PAYMENT_REVIEW', 'NO_BANK_PAYMENT_EXECUTION', 'NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION')
   AND UPPER(BTRIM(COALESCE(v_confirmation_settlement_mode, ''))) IN ('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
   AND COALESCE(v_confirmation_auth_authorised, false)
   AND COALESCE(v_no_bank_operation_count, 0) = 1
   AND COALESCE(v_no_bank_scope_count, 0) > 0
   AND COALESCE(v_settled_no_bank_scope_count, 0) = COALESCE(v_no_bank_scope_count, 0)
   AND COALESCE(v_authorised_no_bank_scope_count, 0) = COALESCE(v_no_bank_scope_count, 0)
   AND COALESCE(v_unresolved_no_bank_scope_count, 0) = 0
   AND COALESCE(v_unauthorised_no_bank_scope_count, 0) = 0
   AND (COALESCE(v_item_count, 0) = 0 OR COALESCE(v_covered_nonvoid_item_count, 0) = COALESCE(v_item_count, 0))
  );

  v_mixed_batch_already_settled := (
       UPPER(BTRIM(COALESCE(v_batch_row.status, ''))) = 'SETTLED'
   AND UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, ''))) = 'COMMITTED'
   AND NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
   AND NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') NOT LIKE 'NO_BANK_PAYMENT:%'
   AND v_batch_row.completed_at_utc IS NOT NULL
   AND COALESCE(v_transfer_count, 0) > 0
   AND COALESCE(v_terminal_success_transfer_count, 0) > 0
   AND COALESCE(v_terminal_failed_transfer_count, 0) = 0
   AND COALESCE(v_pending_or_unknown_transfer_count, 0) = 0
   AND COALESCE(v_candidate_count, 0) > 0
   AND COALESCE(v_settled_candidate_count, 0) = COALESCE(v_candidate_count, 0)
   AND COALESCE(v_no_bank_operation_count, 0) = 1
   AND COALESCE(v_no_bank_scope_count, 0) > 0
   AND COALESCE(v_settled_no_bank_scope_count, 0) = COALESCE(v_no_bank_scope_count, 0)
   AND COALESCE(v_authorised_no_bank_scope_count, 0) = COALESCE(v_no_bank_scope_count, 0)
   AND COALESCE(v_unresolved_no_bank_scope_count, 0) = 0
   AND COALESCE(v_unauthorised_no_bank_scope_count, 0) = 0
   AND (COALESCE(v_item_count, 0) = 0 OR COALESCE(v_covered_nonvoid_item_count, 0) = COALESCE(v_item_count, 0))
  );

  v_batch_already_settled := (
    COALESCE(v_positive_batch_already_settled, false)
    OR COALESCE(v_no_bank_batch_already_settled, false)
    OR COALESCE(v_mixed_batch_already_settled, false)
  );

  v_idempotent_settlement_complete := (
    COALESCE(v_batch_already_settled, false) = true
    AND COALESCE(v_created_count, 0) = 0
    AND COALESCE(v_settlement_unit_count, 0) = 0
  );

  IF v_zero_scope_proof_blocked
     AND COALESCE(v_batch_already_settled, false) IS NOT TRUE THEN
    UPDATE public.banking_pay_operations AS operation_review_update
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        resume_reason = v_zero_scope_proof_error_code,
        progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_review_update.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'review_required', true,
            'review_reason_code', v_zero_scope_proof_error_code,
            'review_message', v_zero_scope_proof_error_message,
            'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
            'explicit_zero_no_bank_scope_count', COALESCE(v_explicit_zero_no_bank_scope_count, 0),
            'proof_validation_outcome', v_proof_validation_outcome,
            'review_required_at_utc', v_now::text
          )
        ),
        error_json = JSONB_STRIP_NULLS(
          COALESCE(operation_review_update.error_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'code', v_zero_scope_proof_error_code,
            'message', v_zero_scope_proof_error_message,
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_transfer_scope_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'detected_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE operation_review_update.id = p_operation_id;

    RETURN JSONB_BUILD_OBJECT(
      'ok', false,
      'hard_blocker', true,
      'code', v_zero_scope_proof_error_code,
      'message', v_zero_scope_proof_error_message,
      'operation_id', p_operation_id::text,
      'execution_operation_id', v_transfer_scope_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'scope_rows_created', COALESCE(v_created_count, 0),
      'scope_rows_reused', COALESCE(v_reused_count, 0),
      'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
      'explicit_zero_no_bank_scope_count', COALESCE(v_explicit_zero_no_bank_scope_count, 0),
      'proof_validation_outcome', v_proof_validation_outcome,
      'batch_already_settled', false,
      'idempotent_settlement_complete', false
    );
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET pay_batch_id = p_pay_batch_id,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id
    AND operation_update.pay_batch_id IS NULL;

  RETURN JSONB_BUILD_OBJECT(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'scope', v_scope,
    'scope_rows_created', COALESCE(v_created_count, 0),
    'scope_rows_reused', COALESCE(v_reused_count, 0),
    'settlement_unit_count', COALESCE(v_settlement_unit_count, 0),
    'explicit_zero_no_bank_scope_count', COALESCE(v_explicit_zero_no_bank_scope_count, 0),
    'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
    'stale_scope_skipped_count', COALESCE(v_stale_scope_skipped_count, 0),
    'transfer_scope_operation_id', v_transfer_scope_operation_id::text,
    'execution_operation_id', v_transfer_scope_operation_id::text,
    'settlement_operation_id', p_operation_id::text,
    'auth_request_id', v_auth_request_id::text,
    'authorised_execution_mode', v_authorised_execution_mode,
    'execution_mode', v_root_execution_mode,
    'provider_submission_required', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
    'provider_submission_attempted', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
    'submitted_to_bank', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
    'proof_validation_outcome', v_proof_validation_outcome,
    'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
    'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
    'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
    'explicit_zero_transfer_evidence_count', COALESCE(v_explicit_zero_transfer_evidence_count, 0),
    'batch_already_settled', COALESCE(v_batch_already_settled, false),
    'idempotent_settlement_complete', COALESCE(v_idempotent_settlement_complete, false)
  )
  || JSONB_BUILD_OBJECT(
    'server_owned_payment_projection_proof', true,
    'scoped_no_transfer_execution', v_authorised_scoped_no_transfer_execution,
    'no_bank_payment_execution', v_authorised_no_bank_payment_execution,
    'allow_explicit_zero_no_bank_scopes', v_authorised_allow_zero_scopes,
    'authorised_paye_net_state_hash', v_authorised_paye_net_state_hash,
    'current_paye_net_state_hash', v_current_paye_net_state_hash,
    'paye_net_state_hash', v_current_paye_net_state_hash,
    'authorised_bank_payment_projection_hash', v_authorised_bank_payment_projection_hash,
    'current_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'authorised_missing_explicit_paye_input_count', v_authorised_missing_count,
    'current_missing_explicit_paye_input_count', v_current_missing_paye_count,
    'authorised_explicit_zero_count', v_authorised_global_zero_count,
    'current_explicit_zero_count', v_current_global_explicit_zero_count,
    'authorised_scoped_explicit_zero_count', v_authorised_scoped_zero_count,
    'current_scoped_explicit_zero_count', v_current_scoped_explicit_zero_count,
    'authorised_scoped_positive_bank_payment_count', v_authorised_scoped_positive_count,
    'current_scoped_positive_bank_payment_count', v_current_scoped_positive_payment_count,
    'current_scoped_positive_bank_payment_total', v_current_scoped_positive_payment_total,
    'existing_completed_settlement_operation_id', CASE
      WHEN v_existing_completed_settlement_operation_id IS NULL THEN NULL::text
      ELSE v_existing_completed_settlement_operation_id::text
    END,
    'durable_settlement_truth', JSONB_BUILD_OBJECT(
      'batch_status', v_batch_row.status,
      'execution_commit_state', v_batch_row.execution_commit_state,
      'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
      'completed_at_utc_present', v_batch_row.completed_at_utc IS NOT NULL,
      'freshness_validation_status', v_batch_row.freshness_validation_status,
      'freshness_clean', COALESCE(v_freshness_clean, true),
      'transfer_count', COALESCE(v_transfer_count, 0),
      'terminal_success_transfer_count', COALESCE(v_terminal_success_transfer_count, 0),
      'terminal_failed_transfer_count', COALESCE(v_terminal_failed_transfer_count, 0),
      'pending_or_unknown_transfer_count', COALESCE(v_pending_or_unknown_transfer_count, 0),
      'transfer_event_count', COALESCE(v_transfer_event_count, 0),
      'provider_attempt_count', COALESCE(v_provider_attempt_count, 0),
      'provider_artifact_count', COALESCE(v_provider_artifact_count, 0),
      'candidate_count', COALESCE(v_candidate_count, 0),
      'settled_candidate_count', COALESCE(v_settled_candidate_count, 0),
      'unsettled_candidate_count', GREATEST(COALESCE(v_candidate_count, 0) - COALESCE(v_settled_candidate_count, 0), 0),
      'item_count', COALESCE(v_item_count, 0),
      'linked_nonvoid_item_count', COALESCE(v_linked_nonvoid_item_count, 0),
      'covered_nonvoid_item_count', COALESCE(v_covered_nonvoid_item_count, 0),
      'no_bank_operation_count', COALESCE(v_no_bank_operation_count, 0),
      'no_bank_scope_count', COALESCE(v_no_bank_scope_count, 0),
      'settled_no_bank_scope_count', COALESCE(v_settled_no_bank_scope_count, 0),
      'unresolved_no_bank_scope_count', COALESCE(v_unresolved_no_bank_scope_count, 0),
      'authorised_no_bank_scope_count', COALESCE(v_authorised_no_bank_scope_count, 0),
      'unauthorised_no_bank_scope_count', COALESCE(v_unauthorised_no_bank_scope_count, 0),
      'positive_transfer_backed_success', COALESCE(v_positive_batch_already_settled, false),
      'pure_no_bank_success', COALESCE(v_no_bank_batch_already_settled, false),
      'mixed_transfer_and_no_bank_success', COALESCE(v_mixed_batch_already_settled, false),
      'freshness_is_diagnostic_only', true,
      'verified_clean_success', COALESCE(v_batch_already_settled, false)
    )
  );
END;
$function$;

-- pay_paye_guardrails(date,uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_paye_guardrails(p_pay_date date, p_ignore_pay_batch_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
declare
  v_pay_date date := p_pay_date;
  v_week_start date;
  v_week_end date;

  v_existing_draft_batch_id uuid := null;
  v_existing_draft_status text := null;
  v_existing_draft_pay_date date := null;
  v_existing_draft_authoritative_payment_date date := null;
  v_existing_draft_created_at_utc timestamptz := null;

  v_has_existing_paye_draft boolean := false;
  v_has_same_week_non_draft_paye_batch boolean := false;
  v_override_required boolean := false;
  v_create_paye_blocked boolean := false;

  v_same_week_batches jsonb := '[]'::jsonb;

  v_blocking_copy jsonb := '{}'::jsonb;
  v_override_copy jsonb := '{}'::jsonb;
  v_active_copy jsonb := '{}'::jsonb;

  v_result jsonb := '{}'::jsonb;
begin
  if v_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYE_GUARDRAILS',
      'code', 'PAY_DATE_REQUIRED',
      'message', 'pay_paye_guardrails: pay_date is required'
    )::text;
  end if;

  v_week_start := date_trunc('week', v_pay_date::timestamp)::date;
  v_week_end := v_week_start + 6;

  with paye_batches as (
    select
      pb.id,
      upper(coalesce(pb.status, '')) as status_upper,
      pb.status,
      pb.pay_date,
      pb.authoritative_payment_date,
      pb.created_at_utc,
      pb.batch_kind_fixed
    from public.pay_batches as pb
    where upper(coalesce(pb.batch_kind_fixed, '')) <> 'LOANS'
      and (p_ignore_pay_batch_id is null or pb.id <> p_ignore_pay_batch_id)
      and (
        upper(coalesce(pb.batch_kind_fixed, '')) = 'PAYE'
        or exists (
          select 1
          from public.pay_batch_candidates as pbc
          join public.pay_batch_items as pbi
            on pbi.pay_batch_candidate_id = pbc.id
          where pbc.pay_batch_id = pb.id
            and upper(coalesce(pbi.pay_channel, '')) = 'PAYE'
        )
        or exists (
          select 1
          from public.pay_batch_candidates as pbc
          where pbc.pay_batch_id = pb.id
            and (
              pbc.paye_state is not null
              or coalesce(pbc.awaiting_net_amount, false) = true
            )
        )
      )
  ),
  existing_draft as (
    select
      b.id,
      b.status,
      b.pay_date,
      b.authoritative_payment_date,
      b.created_at_utc
    from paye_batches as b
    where b.status_upper in ('DRAFT', 'DRAFT_CREATED')
    order by b.created_at_utc asc, b.id asc
    limit 1
  ),
  same_week_non_draft as (
    select
      b.id,
      b.status,
      b.pay_date,
      b.authoritative_payment_date,
      b.created_at_utc
    from paye_batches as b
    where b.status_upper not in ('DRAFT', 'DRAFT_CREATED', 'CANCELLED')
      and coalesce(b.authoritative_payment_date, b.pay_date) between v_week_start and v_week_end
    order by coalesce(b.authoritative_payment_date, b.pay_date) asc, b.created_at_utc asc, b.id asc
  )
  select
    ed.id,
    ed.status,
    ed.pay_date,
    ed.authoritative_payment_date,
    ed.created_at_utc,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'pay_batch_id', sw.id::text,
            'status', sw.status,
            'pay_date', case when sw.pay_date is null then null else sw.pay_date::text end,
            'authoritative_payment_date', case when sw.authoritative_payment_date is null then null else sw.authoritative_payment_date::text end,
            'created_at_utc', sw.created_at_utc
          )
          order by coalesce(sw.authoritative_payment_date, sw.pay_date), sw.created_at_utc, sw.id
        )
        from same_week_non_draft as sw
      ),
      '[]'::jsonb
    )
  into
    v_existing_draft_batch_id,
    v_existing_draft_status,
    v_existing_draft_pay_date,
    v_existing_draft_authoritative_payment_date,
    v_existing_draft_created_at_utc,
    v_same_week_batches
  from existing_draft as ed
  right join (select 1 as keep_row) as k
    on true;

  v_has_existing_paye_draft := v_existing_draft_batch_id is not null;
  v_has_same_week_non_draft_paye_batch := jsonb_array_length(coalesce(v_same_week_batches, '[]'::jsonb)) > 0;

  v_create_paye_blocked := v_has_existing_paye_draft;
  v_override_required := (not v_has_existing_paye_draft) and v_has_same_week_non_draft_paye_batch;

  v_blocking_copy := jsonb_build_object(
    'severity', 'BLOCK',
    'code', 'PAYE_DRAFT_ALREADY_EXISTS',
    'title', 'Existing PAYE draft already exists',
    'message', 'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.',
    'action_hint', 'CANCEL_EXISTING_PAYE_DRAFT_FIRST',
    'frontend_can_continue', false
  );

  v_override_copy := jsonb_build_object(
    'severity', 'WARNING',
    'code', 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED',
    'title', 'A PAYE batch already exists for this payroll week',
    'message', 'A non-draft PAYE batch already exists in this Monday-based payroll week. Creating another PAYE batch for the same week is override-only. Replacement or cancellation is usually the correct path. Continue only after password reauthentication, 2FA, and explicit confirmation.',
    'action_hint', 'REAUTH_THEN_2FA_THEN_EXPLICIT_CONTINUE',
    'frontend_can_continue', true
  );

  if v_create_paye_blocked then
    v_active_copy := v_blocking_copy;
  elsif v_override_required then
    v_active_copy := v_override_copy;
  else
    v_active_copy := jsonb_build_object(
      'severity', 'INFO',
      'code', 'PAYE_GUARDRAILS_CLEAR',
      'title', 'PAYE guardrails clear',
      'message', 'No existing PAYE draft was found and no same-week PAYE override is required.',
      'action_hint', 'NONE',
      'frontend_can_continue', true
    );
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'pay_date', v_pay_date::text,
    'pay_week_start', v_week_start::text,
    'pay_week_end', v_week_end::text,
    'has_existing_paye_draft', v_has_existing_paye_draft,
    'existing_paye_draft', case
      when v_existing_draft_batch_id is null then null
      else jsonb_build_object(
        'pay_batch_id', v_existing_draft_batch_id::text,
        'status', v_existing_draft_status,
        'pay_date', case when v_existing_draft_pay_date is null then null else v_existing_draft_pay_date::text end,
        'authoritative_payment_date', case when v_existing_draft_authoritative_payment_date is null then null else v_existing_draft_authoritative_payment_date::text end,
        'created_at_utc', v_existing_draft_created_at_utc
      )
    end,
    'has_same_week_non_draft_paye_batch', v_has_same_week_non_draft_paye_batch,
    'same_week_non_draft_paye_batches', coalesce(v_same_week_batches, '[]'::jsonb),
    'override_required', v_override_required,
    'create_paye_blocked', v_create_paye_blocked,
    'ui', jsonb_build_object(
      'active', v_active_copy,
      'existing_draft_block', v_blocking_copy,
      'same_week_override', v_override_copy
    )
  );

  begin
    if p_actor_user_id is not null then
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_PAYE_GUARDRAILS',
        v_result,
        'pay_batches',
        'pay_date:' || v_pay_date::text,
        null,
        null,
        null,
        null,
        null
      );
    end if;
  exception when others then
    null;
  end;

  return v_result;
end;
$function$;

-- pay_payment_advance_create(uuid,numeric,numeric,integer,date,uuid,text,numeric,numeric,text,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_payment_advance_create(p_candidate_id uuid, p_principal_amount numeric, p_weekly_due numeric, p_weeks_total integer, p_start_week_start date, p_actor_user_id uuid, p_note text DEFAULT NULL::text, p_minimum_earnings_threshold numeric DEFAULT NULL::numeric, p_take_home_floor_override numeric DEFAULT NULL::numeric, p_beneficiary_name text DEFAULT NULL::text, p_sort_code text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_bank_details_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_pay_date date := (now() at time zone 'Europe/London')::date;

  v_settings record;
  v_candidate record;

  v_schedule_json jsonb := '[]'::jsonb;
  v_next_due date := null;

  v_finance_case_id uuid := null;
  v_finance_component_id uuid := null;

  v_warnings jsonb := '[]'::jsonb;

  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;

  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;

  v_required_weeks int := 0;
  v_pay_channel text := null;
  v_paye_treatment text := 'NONE';

  v_principal_amount_norm numeric(12,2) := 0;
  v_weekly_due_norm numeric(12,2) := null;
  v_weeks_total_norm int := null;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_source_family_key text := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;

  v_taxability public.pay_finance_taxability_enum := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;

  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;

  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_entity_id uuid := null;
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;
  v_readiness_sort_code text := null;
  v_readiness_account_number text := null;
  v_readiness_account_type text := null;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_payment_advance_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_create: actor_user_id is required'
    )::text;
  end if;

  if p_principal_amount is null or round(p_principal_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PRINCIPAL_INVALID',
      'message', 'pay_payment_advance_create: principal_amount must be > 0'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_create: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_create: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_create: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_create: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_principal_amount_norm := round(p_principal_amount,2);
  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKLY_DUE_INVALID',
        'message', 'pay_payment_advance_create: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_payment_advance_create: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'REPAYMENT_INPUT_REQUIRED',
      'message', 'pay_payment_advance_create: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_weeks_total_norm := p_weeks_total;
    v_weekly_due_norm := round((ceil((v_principal_amount_norm / v_weeks_total_norm) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  end if;

  if v_weekly_due_norm is null or v_weekly_due_norm <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_create: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_weeks_total_norm is null or v_weeks_total_norm < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_create: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  if v_weeks_total_norm < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_create: repayment schedule does not cover the principal amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_weeks_total_norm
    )::text;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_payment_advance_create: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    c.umbrella_id,
    upper(coalesce(c.pay_method,'')) as pay_method
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_payment_advance_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_payment_advance_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_payment_advance_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  v_pay_channel := v_candidate.pay_method;

  if v_pay_channel = 'PAYE' then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;

    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_payment_advance_create: one-off bank fields are not allowed for PAYE loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
    v_readiness_sort_code := v_candidate.sort_code;
    v_readiness_account_number := v_candidate.account_number;
    v_readiness_account_type := 'Personal';
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;

    v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
    v_sort_code_norm := case
      when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
      else null
    end;
    v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');

    if v_beneficiary_name_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'BENEFICIARY_NAME_REQUIRED',
        'message', 'pay_payment_advance_create: beneficiary_name is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_sort_code_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'SORT_CODE_REQUIRED',
        'message', 'pay_payment_advance_create: valid sort_code is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_account_number_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'ACCOUNT_NUMBER_REQUIRED',
        'message', 'pay_payment_advance_create: valid account_number is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
    if v_oneoff_bank_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'BANK_DETAILS_HASH_FAILED',
        'message', 'pay_payment_advance_create: unable to derive bank_details_hash for umbrella loan payout bank details',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_readiness_bank_hash := v_oneoff_bank_hash;
    v_readiness_payee_name := v_beneficiary_name_norm;
    v_readiness_sort_code := v_sort_code_norm;
    v_readiness_account_number := v_account_number_norm;
    v_readiness_account_type := 'Personal';
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (p_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_weekly_due_norm,
              greatest(v_principal_amount_norm - (v_weekly_due_norm * gs.i), 0)
            ),
            2
          )
        )
        order by (p_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due
  from (
    select
      (p_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_weekly_due_norm,
          greatest(v_principal_amount_norm - (v_weekly_due_norm * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id,
    taxability,
    routing_kind,
    oneoff_bank_details_required
  )
  values (
    p_candidate_id,
    null::uuid,
    'LOAN'::public.pay_advance_reason_enum,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null::date,
    coalesce(v_schedule_json,'[]'::jsonb),
    v_next_due,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LOAN'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    'PENDING'::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    v_weekly_due_norm,
    v_weeks_total_norm,
    p_start_week_start,
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    null::text,
    null::numeric,
    null::numeric,
    case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid,
    v_taxability,
    v_routing_kind,
    v_oneoff_required
  )
  returning id into v_finance_case_id;

  if v_pay_channel = 'UMBRELLA' then
    insert into public.pay_finance_case_oneoff_payout_bank_details(
      finance_case_id,
      candidate_id,
      beneficiary_name,
      sort_code,
      account_number,
      bank_details_hash,
      note,
      created_at_utc,
      created_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    values (
      v_finance_case_id,
      p_candidate_id,
      v_beneficiary_name_norm,
      v_sort_code_norm,
      v_account_number_norm,
      v_oneoff_bank_hash,
      nullif(btrim(coalesce(p_bank_details_note,'')), ''),
      v_now_utc,
      p_actor_user_id,
      v_now_utc,
      p_actor_user_id
    );

    v_oneoff_after := jsonb_build_object(
      'finance_case_id', v_finance_case_id::text,
      'candidate_id', p_candidate_id::text,
      'beneficiary_name', v_beneficiary_name_norm,
      'sort_code_masked', case when v_sort_code_norm is null then null else 'XX-XX-' || right(v_sort_code_norm, 2) end,
      'account_number_masked', case when v_account_number_norm is null then null else lpad(right(v_account_number_norm, 4), length(v_account_number_norm), '*') end,
      'bank_details_hash', v_oneoff_bank_hash,
      'note', nullif(btrim(coalesce(p_bank_details_note,'')), '')
    );

    perform public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'ONEOFF_BANK_DETAILS_CREATED',
      v_oneoff_before,
      v_oneoff_after,
      'ONE_OFF_PAYOUT_BANK_DETAILS',
      p_actor_user_id
    );
  end if;

  v_source_family_key := 'case:' || v_finance_case_id::text;
  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'schedule_json', coalesce(v_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  insert into public.pay_finance_case_components (
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    v_source_family_key,
    'CASE_TOTAL',
    'TOTAL',
    'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
    v_candidate.pay_method,
    v_component_source_basis_json,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null,
    null,
    null,
    null,
    null,
    false,
    null,
    0,
    0,
    v_now_utc,
    v_now_utc,
    null,
    null
  )
  returning id into v_finance_component_id;

  v_component_snapshot_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'finance_case_id', v_finance_case_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_candidate.pay_method,
    'target_pay_method', v_candidate.pay_method,
    'source_basis_json', v_component_source_basis_json,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'current_component_fingerprint', public.pay_finance_component_fingerprint(
      p_source_family_key => v_source_family_key,
      p_component_key_type => 'CASE_TOTAL',
      p_component_key_value => 'TOTAL',
      p_classification => 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      p_source_pay_method => v_candidate.pay_method,
      p_current_target_pay_method => v_candidate.pay_method,
      p_source_basis_json => v_component_source_basis_json,
      p_source_amount => v_principal_amount_norm,
      p_relevant_erni_pct => null,
      p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate.pay_method)
    )
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'original_amount', v_principal_amount_norm,
      'outstanding_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'payout_pay_batch_id', null,
      'payout_status', 'PENDING',
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'oneoff_bank_details_required', v_oneoff_required,
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'schedule_input_mode', v_schedule_input_mode
    ),
    null::text,
    'Payment Advance created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    v_component_snapshot_json,
    'PAYMENT_ADVANCE_COMPONENT_CREATE',
    'Created non-taxable fixed finance component for Payment Advance principal'
  );

  if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'BLOCKED_BANK_DETAILS',
        'message', case when v_pay_channel = 'PAYE'
                        then 'Candidate bank details are missing; the loan payout will appear as Blocked for Pay until bank details are present.'
                        else 'One-off payout bank details are missing or incomplete; the loan payout will appear as Blocked for Pay until valid bank details are present.' end,
        'candidate_id', p_candidate_id::text
      )
    );
  else
    if v_need_name_check = true then
      select
        coalesce(bnc.status, 'UNVERIFIED') as status,
        (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
      into
        v_bnc_status,
        v_bnc_has_override
      from public.bank_name_checks bnc
      where bnc.rail_provider = v_settings.rail_provider_default
        and bnc.rail_env = v_settings.rail_env_default
        and bnc.entity_kind = v_readiness_entity_kind
        and bnc.entity_id = p_candidate_id
        and bnc.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NAME_CHECK',
            'message', 'Name check has not passed (or override missing) for the payout destination; the loan payout will appear as Blocked for Pay until resolved.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;

    if v_requires_payee_map = true then
      select (bpm.payee_id is not null) as present
      into v_bpm_present
      from public.bank_payee_map bpm
      where bpm.rail_provider = v_settings.rail_provider_default
        and bpm.rail_env = v_settings.rail_env_default
        and bpm.entity_kind = v_readiness_entity_kind
        and bpm.entity_id = p_candidate_id
        and bpm.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bpm_present,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NO_PAYEE_MAP',
            'message', 'Payee map is missing for the payout destination on this rail; the loan payout will appear as Blocked for Pay until payee mapping exists.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;
  end if;

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_candidate.pay_method,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'saved_target_pay_method', null,
    'saved_resolution_mode', null,
    'is_resolution_stale', false,
    'stale_reason', null,
    'source_basis_json', v_component_source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'advance_id', v_finance_case_id::text,
    'pay_batch_id', null,
    'pay_date', v_pay_date::text,
    'batch_kind_fixed', null,
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', v_principal_amount_norm,
    'weekly_due', v_weekly_due_norm,
    'weeks_total', v_weeks_total_norm,
    'start_week_start', p_start_week_start::text,
    'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
    'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    'schedule_json', coalesce(v_schedule_json,'[]'::jsonb),
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'oneoff_bank_details_required', v_oneoff_required,
    'oneoff_bank_details_present', case when v_pay_channel = 'UMBRELLA' then true else false end,
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_pay_channel = 'UMBRELLA' then v_beneficiary_name_norm else null end,
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$function$;

-- pay_payment_advance_create(uuid,numeric,numeric,integer,date,uuid,text,numeric,numeric)
CREATE OR REPLACE FUNCTION public.pay_payment_advance_create(p_candidate_id uuid, p_principal_amount numeric, p_weekly_due numeric, p_weeks_total integer, p_start_week_start date, p_actor_user_id uuid, p_note text DEFAULT NULL::text, p_minimum_earnings_threshold numeric DEFAULT NULL::numeric, p_take_home_floor_override numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_pay_date date := (now() at time zone 'Europe/London')::date;

  v_settings record;
  v_candidate record;

  v_schedule_json jsonb := '[]'::jsonb;
  v_next_due date := null;

  v_finance_case_id uuid := null;
  v_pay_batch_id uuid := null;
  v_pay_batch_candidate_id uuid := null;
  v_pay_batch_item_id uuid := null;
  v_finance_component_id uuid := null;

  v_warnings jsonb := '[]'::jsonb;

  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;

  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;

  v_required_weeks int := 0;
  v_pay_channel text := null;
  v_paye_treatment text := 'NONE';

  v_principal_amount_norm numeric(12,2) := 0;
  v_weekly_due_norm numeric(12,2) := null;
  v_weeks_total_norm int := null;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_source_family_key text := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_payment_advance_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_create: actor_user_id is required'
    )::text;
  end if;

  if p_principal_amount is null or round(p_principal_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PRINCIPAL_INVALID',
      'message', 'pay_payment_advance_create: principal_amount must be > 0'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_create: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_create: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_create: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_create: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_principal_amount_norm := round(p_principal_amount,2);
  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKLY_DUE_INVALID',
        'message', 'pay_payment_advance_create: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_payment_advance_create: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'REPAYMENT_INPUT_REQUIRED',
      'message', 'pay_payment_advance_create: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_weeks_total_norm := p_weeks_total;
    v_weekly_due_norm := round((ceil((v_principal_amount_norm / v_weeks_total_norm) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  end if;

  if v_weekly_due_norm is null or v_weekly_due_norm <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_create: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_weeks_total_norm is null or v_weeks_total_norm < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_create: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  if v_weeks_total_norm < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_create: repayment schedule does not cover the principal amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_weeks_total_norm
    )::text;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_payment_advance_create: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    c.umbrella_id,
    upper(coalesce(c.pay_method,'')) as pay_method
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_payment_advance_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_payment_advance_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_payment_advance_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  v_pay_channel := v_candidate.pay_method;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (p_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_weekly_due_norm,
              greatest(v_principal_amount_norm - (v_weekly_due_norm * gs.i), 0)
            ),
            2
          )
        )
        order by (p_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due
  from (
    select
      (p_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_weekly_due_norm,
          greatest(v_principal_amount_norm - (v_weekly_due_norm * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id
  )
  values (
    p_candidate_id,
    null::uuid,
    'LOAN'::public.pay_advance_reason_enum,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null::date,
    coalesce(v_schedule_json,'[]'::jsonb),
    v_next_due,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LOAN'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    'PENDING'::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    v_weekly_due_norm,
    v_weeks_total_norm,
    p_start_week_start,
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    null::text,
    null::numeric,
    null::numeric,
    case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid
  )
  returning id into v_finance_case_id;

  v_source_family_key := 'case:' || v_finance_case_id::text;
  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'schedule_json', coalesce(v_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  insert into public.pay_finance_case_components (
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    v_source_family_key,
    'CASE_TOTAL',
    'TOTAL',
    'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
    v_candidate.pay_method,
    v_component_source_basis_json,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null,
    null,
    null,
    null,
    null,
    false,
    null,
    0,
    0,
    v_now_utc,
    v_now_utc,
    null,
    null
  )
  returning id into v_finance_component_id;

  v_component_snapshot_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'finance_case_id', v_finance_case_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'NET_PAY_FIXED_RECOVERY',
    'source_pay_method', v_candidate.pay_method,
    'target_pay_method', v_candidate.pay_method,
    'source_basis_json', v_component_source_basis_json,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'current_component_fingerprint', public.pay_finance_component_fingerprint(
      p_source_family_key => v_source_family_key,
      p_component_key_type => 'CASE_TOTAL',
      p_component_key_value => 'TOTAL',
      p_classification => 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
      p_source_pay_method => v_candidate.pay_method,
      p_current_target_pay_method => v_candidate.pay_method,
      p_source_basis_json => v_component_source_basis_json,
      p_source_amount => v_principal_amount_norm,
      p_relevant_erni_pct => null,
      p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate.pay_method)
    )
  );

  insert into public.pay_batches(
    pay_date,
    created_at_utc,
    created_by_user_id,
    status,
    banking_system_snapshot,
    external_paye_system_snapshot,
    rail_provider_snapshot,
    rail_env_snapshot,
    batch_kind_fixed
  )
  values (
    v_pay_date,
    v_now_utc,
    p_actor_user_id,
    'DRAFT',
    v_settings.banking_system,
    v_settings.external_paye_system,
    v_settings.rail_provider_default,
    v_settings.rail_env_default,
    'LOANS'
  )
  returning id into v_pay_batch_id;

  update public.pay_advances pa
  set payout_pay_batch_id = v_pay_batch_id,
      updated_at = v_now_utc
  where pa.id = v_finance_case_id;

  insert into public.pay_batch_candidates(
    pay_batch_id,
    candidate_id,
    candidate_tms_ref,
    candidate_display_name,
    paye_state,
    mismatch_settlement_choice,
    gross_preview,
    net_bank_amount,
    debt_created,
    loan_repayment_taken,
    overpayment_recovery_taken,
    awaiting_net_amount,
    updated_at
  )
  values (
    v_pay_batch_id,
    p_candidate_id,
    v_candidate.tms_ref,
    v_candidate.display_name,
    null,
    null,
    v_principal_amount_norm,
    v_principal_amount_norm,
    0,
    0,
    0,
    false,
    v_now_utc
  )
  returning id into v_pay_batch_candidate_id;

  insert into public.pay_batch_items(
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    bank_reference,
    pay_bank_transfer_id,
    repayment_week_start,
    is_voided,
    is_mismatch,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  values (
    v_pay_batch_candidate_id,
    'LOAN_PAYOUT',
    null::uuid,
    null::text,
    ('advance:' || v_finance_case_id::text),
    'Payment Advance',
    v_principal_amount_norm,
    0,
    v_principal_amount_norm,
    v_pay_channel,
    case when v_pay_channel = 'UMBRELLA' then v_candidate.umbrella_id else null::uuid end,
    null::text,
    null::uuid,
    null::date,
    false,
    false,
    v_now_utc,
    v_now_utc,
    v_finance_case_id,
    null::uuid,
    v_paye_treatment,
    v_finance_component_id,
    v_component_snapshot_json,
    'CASE_TOTAL',
    'TOTAL',
    'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
    v_component_source_basis_json,
    v_candidate.pay_method,
    v_candidate.pay_method,
    null,
    null,
    null,
    v_principal_amount_norm,
    v_principal_amount_norm,
    0,
    v_principal_amount_norm
  )
  returning id into v_pay_batch_item_id;

  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  values (
    v_pay_batch_item_id,
    'LOAN_PAYOUT',
    null,
    'Payment Advance',
    null::numeric,
    null::numeric,
    v_principal_amount_norm,
    0,
    v_principal_amount_norm,
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'worker_label', 'Payment Advance'
    )
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    v_pay_batch_id,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'original_amount', v_principal_amount_norm,
      'outstanding_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'payout_pay_batch_id', v_pay_batch_id::text,
      'payout_status', 'PENDING',
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'schedule_input_mode', v_schedule_input_mode
    ),
    null::text,
    'Payment Advance created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    v_pay_batch_id,
    null::jsonb,
    v_component_snapshot_json,
    'PAYMENT_ADVANCE_COMPONENT_CREATE',
    'Created net-fixed finance component for Payment Advance principal'
  );

  if v_candidate.bank_details_hash is null or btrim(coalesce(v_candidate.bank_details_hash,'')) = '' then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'BLOCKED_BANK_DETAILS',
        'message', 'Candidate bank details are missing; batch can be created but will be blocked at prepare/schedule until bank details are present.',
        'candidate_id', p_candidate_id::text
      )
    );
  else
    if v_need_name_check = true then
      select
        coalesce(bnc.status, 'UNVERIFIED') as status,
        (bnc.override_reason is not null and bnc.override_hash = v_candidate.bank_details_hash) as has_override
      into
        v_bnc_status,
        v_bnc_has_override
      from public.bank_name_checks bnc
      where bnc.rail_provider = v_settings.rail_provider_default
        and bnc.rail_env = v_settings.rail_env_default
        and bnc.entity_kind = 'CANDIDATE'
        and bnc.entity_id = p_candidate_id
        and bnc.bank_details_hash = v_candidate.bank_details_hash
      limit 1;

      if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NAME_CHECK',
            'message', 'Name check has not passed (or override missing) for candidate bank details; scheduling/execution may be blocked until resolved.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;

    if v_requires_payee_map = true then
      select (bpm.payee_id is not null) as present
      into v_bpm_present
      from public.bank_payee_map bpm
      where bpm.rail_provider = v_settings.rail_provider_default
        and bpm.rail_env = v_settings.rail_env_default
        and bpm.entity_kind = 'CANDIDATE'
        and bpm.entity_id = p_candidate_id
        and bpm.bank_details_hash = v_candidate.bank_details_hash
      limit 1;

      if coalesce(v_bpm_present,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NO_PAYEE_MAP',
            'message', 'Payee map is missing for candidate bank details on this rail; scheduling/execution may be blocked until payee mapping exists.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;
  end if;

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'NET_PAY_FIXED_RECOVERY',
    'source_pay_method', v_candidate.pay_method,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'saved_target_pay_method', null,
    'saved_resolution_mode', null,
    'is_resolution_stale', false,
    'stale_reason', null,
    'source_basis_json', v_component_source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'advance_id', v_finance_case_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'pay_date', v_pay_date::text,
    'batch_kind_fixed', 'LOANS',
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', v_principal_amount_norm,
    'weekly_due', v_weekly_due_norm,
    'weeks_total', v_weeks_total_norm,
    'start_week_start', p_start_week_start::text,
    'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
    'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    'schedule_json', coalesce(v_schedule_json,'[]'::jsonb),
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$function$;

-- pay_payment_advance_update(uuid,uuid,numeric,numeric,integer,date,text,numeric,numeric,text,text,text,text,boolean)
CREATE OR REPLACE FUNCTION public.pay_payment_advance_update(p_finance_case_id uuid, p_actor_user_id uuid, p_principal_amount numeric DEFAULT NULL::numeric, p_weekly_due numeric DEFAULT NULL::numeric, p_weeks_total integer DEFAULT NULL::integer, p_start_week_start date DEFAULT NULL::date, p_note text DEFAULT NULL::text, p_minimum_earnings_threshold numeric DEFAULT NULL::numeric, p_take_home_floor_override numeric DEFAULT NULL::numeric, p_beneficiary_name text DEFAULT NULL::text, p_sort_code text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_bank_details_note text DEFAULT NULL::text, p_remove_oneoff_bank_details boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_batch public.pay_batches%rowtype;
  v_has_batch boolean := false;
  v_is_committed boolean := false;
  v_has_newflow_draft_item boolean := false;

  v_new_principal numeric(12,2);
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_notes text;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due date := null;
  v_required_weeks int := 0;

  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_can_edit_payout_details boolean := false;
  v_has_principal_change boolean := false;
  v_batch_item_id uuid := null;
  v_pay_batch_candidate_id uuid := null;

  v_schedule_base_amount numeric(12,2) := 0;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_component public.pay_finance_case_components%rowtype;
  v_component_after public.pay_finance_case_components%rowtype;
  v_finance_component_id uuid := null;
  v_component_before_json jsonb := '{}'::jsonb;
  v_component_after_json jsonb := '{}'::jsonb;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
  v_component_remaining_amount numeric(12,2) := 0;
  v_source_family_key text := null;

  v_candidate_pay_method text := null;
  v_taxability public.pay_finance_taxability_enum := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;

  v_existing_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;
  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_change_requested boolean := false;

  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;

  v_settings record;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;
  v_warnings jsonb := '[]'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_payment_advance_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_payment_advance_update: Payment Advance not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method,''))
  into v_candidate_pay_method
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate_pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_payment_advance_update: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_case.payout_pay_batch_id is not null then
    select pb.*
    into v_batch
    from public.pay_batches pb
    where pb.id = v_case.payout_pay_batch_id
    limit 1;

    v_has_batch := v_batch.id is not null;
  end if;

  if v_has_batch then
    v_is_committed := (
      coalesce(v_batch.authoritative_payment_date is not null, false)
      or upper(coalesce(v_batch.status,'')) in ('SCHEDULED','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT','EXECUTING','SETTLED','COMPLETED','PARTIAL')
    );
  else
    v_is_committed := false;
  end if;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'LOAN_PAYOUT'
      and pbi.is_voided = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status,'')) <> 'CANCELLED'
  ) into v_has_newflow_draft_item;

  if v_has_batch then
    v_can_edit_payout_details := (v_is_committed = false);
  else
    v_can_edit_payout_details := (v_has_newflow_draft_item = false);
  end if;

  select *
  into v_existing_oneoff
  from public.pay_finance_case_oneoff_payout_bank_details d
  where d.finance_case_id = p_finance_case_id
  for update;

  v_before_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', null,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required
  );

  v_new_principal := coalesce(round(p_principal_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;

  if v_new_minimum_earnings_threshold is not null and v_new_minimum_earnings_threshold < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_update: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if v_new_take_home_floor_override is not null and v_new_take_home_floor_override < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_update: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_has_principal_change := round(v_new_principal,2) <> round(coalesce(v_case.original_amount,0),2);

  if (not v_can_edit_payout_details) and v_has_principal_change then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'PAYOUT_ALREADY_DRAFTED_OR_COMMITTED',
      'message', 'pay_payment_advance_update: payout principal can only be edited while the item is Not processed yet',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_can_edit_payout_details then
    if v_new_principal <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'PRINCIPAL_INVALID',
        'message', 'pay_payment_advance_update: principal_amount must be > 0'
      )::text;
    end if;
    v_schedule_base_amount := v_new_principal;
  else
    v_schedule_base_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  if p_start_week_start is not null and public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if p_weekly_due is not null and round(p_weekly_due,2) <= 0 and not v_has_weeks_total_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: weekly_due must be > 0 when provided'
    )::text;
  end if;

  if p_weeks_total is not null and p_weeks_total < 1 and not v_has_weekly_due_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: weeks_total must be >= 1 when provided'
    )::text;
  end if;

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    v_schedule_input_mode := 'UNCHANGED';
    v_new_weekly_due := round(coalesce(v_case.weekly_due,0),2);
    v_new_weeks_total := v_case.weeks_total;
  elsif v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_schedule_base_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: normalized weeks_total must be >= 1'
    )::text;
  end if;

  if p_start_week_start is not null then
    v_new_start_week_start := p_start_week_start;
  elsif v_case.next_due_week_start is not null then
    v_new_start_week_start := v_case.next_due_week_start;
  else
    v_new_start_week_start := v_case.start_week_start;
  end if;

  if v_new_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_update: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(v_new_start_week_start) <> v_new_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', v_new_start_week_start::text
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_update: repayment schedule does not cover the remaining amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total
    )::text;
  end if;

  if v_candidate_pay_method = 'PAYE' then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;

    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null
       or coalesce(p_remove_oneoff_bank_details, false) = true then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_payment_advance_update: one-off bank fields are not allowed for PAYE loan payouts',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'PAY_METHOD_NOW_PAYE',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce((select c.bank_details_hash from public.candidates c where c.id = v_case.candidate_id limit 1), '')), '');
    v_readiness_payee_name := nullif(btrim(coalesce((select c.account_holder from public.candidates c where c.id = v_case.candidate_id limit 1), (select c.display_name from public.candidates c where c.id = v_case.candidate_id limit 1))), '');
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;

    v_oneoff_change_requested := (
      nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
      or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
      or nullif(btrim(coalesce(p_account_number,'')), '') is not null
      or p_bank_details_note is not null
      or coalesce(p_remove_oneoff_bank_details, false) = true
    );

    if v_oneoff_change_requested and not v_can_edit_payout_details then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_LOCKED',
        'message', 'pay_payment_advance_update: one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if coalesce(p_remove_oneoff_bank_details, false) = true then
      if v_existing_oneoff.finance_case_id is not null then
        v_oneoff_before := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        delete from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          'ONEOFF_BANK_DETAILS_REMOVED',
          v_oneoff_before,
          null::jsonb,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := null;
      v_readiness_payee_name := null;
    else
      if v_existing_oneoff.finance_case_id is not null then
        v_beneficiary_name_norm := coalesce(
          nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), ''),
          v_existing_oneoff.beneficiary_name
        );
        v_sort_code_norm := coalesce(
          case
            when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
            else null
          end,
          v_existing_oneoff.sort_code
        );
        v_account_number_norm := coalesce(
          nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), ''),
          v_existing_oneoff.account_number
        );
      else
        v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
        v_sort_code_norm := case
          when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
          else null
        end;
        v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');
      end if;

      if v_beneficiary_name_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'BENEFICIARY_NAME_REQUIRED',
          'message', 'pay_payment_advance_update: beneficiary_name is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_sort_code_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'SORT_CODE_REQUIRED',
          'message', 'pay_payment_advance_update: valid sort_code is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_account_number_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'ACCOUNT_NUMBER_REQUIRED',
          'message', 'pay_payment_advance_update: valid account_number is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
      if v_oneoff_bank_hash is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'BANK_DETAILS_HASH_FAILED',
          'message', 'pay_payment_advance_update: unable to derive bank_details_hash for umbrella loan payout bank details',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_can_edit_payout_details then
        v_oneoff_before := case
          when v_existing_oneoff.finance_case_id is null then null
          else jsonb_build_object(
            'finance_case_id', p_finance_case_id::text,
            'candidate_id', v_case.candidate_id::text,
            'beneficiary_name', v_existing_oneoff.beneficiary_name,
            'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
            'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
            'bank_details_hash', v_existing_oneoff.bank_details_hash,
            'note', v_existing_oneoff.note
          )
        end;

        insert into public.pay_finance_case_oneoff_payout_bank_details(
          finance_case_id,
          candidate_id,
          beneficiary_name,
          sort_code,
          account_number,
          bank_details_hash,
          note,
          created_at_utc,
          created_by_user_id,
          updated_at_utc,
          updated_by_user_id
        )
        values (
          p_finance_case_id,
          v_case.candidate_id,
          v_beneficiary_name_norm,
          v_sort_code_norm,
          v_account_number_norm,
          v_oneoff_bank_hash,
          case when p_bank_details_note is null then coalesce(v_existing_oneoff.note, null) else nullif(btrim(coalesce(p_bank_details_note,'')), '') end,
          v_now_utc,
          p_actor_user_id,
          v_now_utc,
          p_actor_user_id
        )
        on conflict (finance_case_id) do update
        set candidate_id = excluded.candidate_id,
            beneficiary_name = excluded.beneficiary_name,
            sort_code = excluded.sort_code,
            account_number = excluded.account_number,
            bank_details_hash = excluded.bank_details_hash,
            note = excluded.note,
            updated_at_utc = excluded.updated_at_utc,
            updated_by_user_id = excluded.updated_by_user_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        v_oneoff_after := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          case when v_oneoff_before is null then 'ONEOFF_BANK_DETAILS_CREATED' else 'ONEOFF_BANK_DETAILS_UPDATED' end,
          v_oneoff_before,
          v_oneoff_after,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := v_oneoff_bank_hash;
      v_readiness_payee_name := v_beneficiary_name_norm;
    end if;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_payment_advance_update: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_new_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_new_weekly_due,
              greatest(v_schedule_base_amount - (v_new_weekly_due * gs.i), 0)
            ),
            2
          )
        )
        order by (v_new_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_schedule_base_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_source_family_key := 'case:' || p_finance_case_id::text;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.source_family_key = v_source_family_key
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
    and pfc.closed_at_utc is null
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_new_principal,
      'weekly_due', v_new_weekly_due,
      'weeks_total', v_new_weeks_total,
      'start_week_start', v_new_start_week_start::text,
      'next_due_week_start', case when v_new_next_due is null then null else v_new_next_due::text end,
      'schedule_json', coalesce(v_new_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', v_new_minimum_earnings_threshold,
      'take_home_floor_override', v_new_take_home_floor_override,
      'note', v_new_notes
    )
  );

  if v_component.id is null then
    insert into public.pay_finance_case_components (
      finance_case_id,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      source_pay_method,
      source_basis_json,
      source_amount,
      remaining_source_amount,
      saved_target_pay_method,
      saved_resolution_mode,
      saved_resolution_payload_json,
      saved_resolution_result_json,
      resolution_fingerprint,
      is_resolution_stale,
      stale_reason,
      allocation_priority_group,
      allocation_priority_order,
      created_at_utc,
      updated_at_utc,
      resolved_at_utc,
      closed_at_utc
    )
    values (
      p_finance_case_id,
      v_case.candidate_id,
      v_case.client_id,
      v_case.linked_timesheet_id,
      v_source_family_key,
      'CASE_TOTAL',
      'TOTAL',
      'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      v_candidate_pay_method,
      v_component_source_basis_json,
      v_new_principal,
      case when v_can_edit_payout_details then v_new_principal else round(coalesce(v_case.outstanding_amount,0),2) end,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      0,
      0,
      v_now_utc,
      v_now_utc,
      null,
      null
    )
    returning * into v_component;
  end if;

  if v_can_edit_payout_details then
    v_component_remaining_amount := v_new_principal;
  else
    v_component_remaining_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  v_component_before_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  update public.pay_finance_case_components pfc
  set
    candidate_id = v_case.candidate_id,
    client_id = v_case.client_id,
    linked_timesheet_id = v_case.linked_timesheet_id,
    classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
    source_pay_method = v_candidate_pay_method,
    source_basis_json = v_component_source_basis_json,
    source_amount = v_new_principal,
    remaining_source_amount = v_component_remaining_amount,
    saved_target_pay_method = null,
    saved_resolution_mode = null,
    saved_resolution_payload_json = null,
    saved_resolution_result_json = null,
    resolution_fingerprint = null,
    is_resolution_stale = false,
    stale_reason = null,
    allocation_priority_group = 0,
    allocation_priority_order = 0,
    updated_at_utc = v_now_utc
  where pfc.id = v_component.id
  returning * into v_component_after;

  v_finance_component_id := v_component_after.id;

  update public.pay_advances pa
  set
    original_amount = case when v_can_edit_payout_details then v_new_principal else pa.original_amount end,
    outstanding_amount = case when v_can_edit_payout_details then v_new_principal else pa.outstanding_amount end,
    schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
    next_due_week_start = v_new_next_due,
    notes = v_new_notes,
    weekly_due = v_new_weekly_due,
    weeks_total = v_new_weeks_total,
    start_week_start = v_new_start_week_start,
    minimum_earnings_threshold = v_new_minimum_earnings_threshold,
    take_home_floor_override = v_new_take_home_floor_override,
    updated_at = v_now_utc,
    taxability = v_taxability,
    routing_kind = v_routing_kind,
    oneoff_bank_details_required = v_oneoff_required
  where pa.id = p_finance_case_id;

  if v_can_edit_payout_details and v_has_batch then
    select pbc.id
    into v_pay_batch_candidate_id
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = v_batch.id
      and pbc.candidate_id = v_case.candidate_id
    limit 1;

    select pbi.id
    into v_batch_item_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc2
      on pbc2.id = pbi.pay_batch_candidate_id
    where pbc2.pay_batch_id = v_batch.id
      and pbc2.candidate_id = v_case.candidate_id
      and pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'LOAN_PAYOUT'
      and pbi.is_voided = false
    limit 1;

    if v_pay_batch_candidate_id is not null then
      update public.pay_batch_candidates pbc
      set gross_preview = v_new_principal,
          net_bank_amount = v_new_principal,
          updated_at = v_now_utc
      where pbc.id = v_pay_batch_candidate_id;
    end if;

    v_component_snapshot_json := jsonb_build_object(
      'finance_component_id', v_finance_component_id::text,
      'finance_case_id', p_finance_case_id::text,
      'source_family_key', v_source_family_key,
      'component_key_type', 'CASE_TOTAL',
      'component_key_value', 'TOTAL',
      'classification', 'REIMBURSEMENT_GROSS_FIXED',
      'source_pay_method', v_candidate_pay_method,
      'target_pay_method', v_candidate_pay_method,
      'source_basis_json', v_component_source_basis_json,
      'source_amount', v_new_principal,
      'remaining_source_amount', v_component_remaining_amount,
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_after.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_after.saved_resolution_result_json,
      'current_component_fingerprint', public.pay_finance_component_fingerprint(
        p_source_family_key => v_source_family_key,
        p_component_key_type => 'CASE_TOTAL',
        p_component_key_value => 'TOTAL',
        p_classification => 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
        p_source_pay_method => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json => v_component_source_basis_json,
        p_source_amount => v_new_principal,
        p_relevant_erni_pct => null,
        p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate_pay_method)
      )
    );

    if v_batch_item_id is not null then
      update public.pay_batch_items pbi
      set description = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          updated_at = v_now_utc,
          finance_case_id = p_finance_case_id,
          reservation_id = null,
          paye_treatment = 'NONE',
          finance_component_id = v_finance_component_id,
          frozen_component_snapshot_json = v_component_snapshot_json,
          frozen_component_key_type = 'CASE_TOTAL',
          frozen_component_key_value = 'TOTAL',
          frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
          frozen_source_basis_json = v_component_source_basis_json,
          frozen_source_pay_method = v_candidate_pay_method,
          frozen_target_pay_method = v_candidate_pay_method,
          frozen_resolution_mode = v_component_after.saved_resolution_mode,
          frozen_resolution_payload_json = v_component_after.saved_resolution_payload_json,
          frozen_resolution_result_json = v_component_after.saved_resolution_result_json,
          frozen_source_amount = v_new_principal,
          frozen_target_amount_ex_vat = v_new_principal,
          frozen_target_amount_vat = 0,
          frozen_target_amount_inc_vat = v_new_principal,
          payout_instruction_snapshot_json = case
            when v_candidate_pay_method = 'UMBRELLA' and v_existing_oneoff.finance_case_id is not null then
              jsonb_build_object(
                'taxability', 'NON_TAXABLE',
                'routing_kind', 'ONE_OFF_SPECIFIED_BANK_ACCOUNT',
                'destination_label', 'one-off specified bank account',
                'pay_channel', 'UMBRELLA',
                'payee_entity_kind', 'CANDIDATE',
                'payee_entity_id', v_case.candidate_id::text,
                'beneficiary_name', v_existing_oneoff.beneficiary_name,
                'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
                'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
                'bank_details_hash', v_existing_oneoff.bank_details_hash,
                'bank_details_note', v_existing_oneoff.note,
                'appears_on_umbrella_remittance', false,
                'generates_candidate_payment_advice', true
              )
            else null
          end
      where pbi.id = v_batch_item_id;

      update public.pay_batch_item_breakdowns pbib
      set unit_name = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          meta_json = jsonb_build_object(
            'case_type', 'PAYMENT_ADVANCE',
            'worker_label', 'Payment Advance'
          )
      where pbib.pay_batch_item_id = v_batch_item_id;
    end if;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  if v_candidate_pay_method = 'PAYE' then
    v_readiness_bank_hash := nullif(btrim(coalesce((select c.bank_details_hash from public.candidates c where c.id = v_case.candidate_id limit 1), '')), '');
    v_readiness_payee_name := nullif(btrim(coalesce((select c.account_holder from public.candidates c where c.id = v_case.candidate_id limit 1), (select c.display_name from public.candidates c where c.id = v_case.candidate_id limit 1))), '');
  elsif v_existing_oneoff.finance_case_id is not null then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_existing_oneoff.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_existing_oneoff.beneficiary_name,'')), '');
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'BLOCKED_BANK_DETAILS',
        'message', case when v_candidate_pay_method = 'PAYE'
                        then 'Candidate bank details are missing; the loan payout will appear as Blocked for Pay until bank details are present.'
                        else 'One-off payout bank details are missing or incomplete; the loan payout will appear as Blocked for Pay until valid bank details are present.' end,
        'candidate_id', v_case.candidate_id::text
      )
    );
  else
    if v_need_name_check = true then
      select
        coalesce(bnc.status, 'UNVERIFIED') as status,
        (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
      into
        v_bnc_status,
        v_bnc_has_override
      from public.bank_name_checks bnc
      where bnc.rail_provider = v_settings.rail_provider_default
        and bnc.rail_env = v_settings.rail_env_default
        and bnc.entity_kind = 'CANDIDATE'
        and bnc.entity_id = v_case.candidate_id
        and bnc.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NAME_CHECK',
            'message', 'Name check has not passed (or override missing) for the payout destination; the loan payout will appear as Blocked for Pay until resolved.',
            'candidate_id', v_case.candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;

    if v_requires_payee_map = true then
      select (bpm.payee_id is not null) as present
      into v_bpm_present
      from public.bank_payee_map bpm
      where bpm.rail_provider = v_settings.rail_provider_default
        and bpm.rail_env = v_settings.rail_env_default
        and bpm.entity_kind = 'CANDIDATE'
        and bpm.entity_id = v_case.candidate_id
        and bpm.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bpm_present,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NO_PAYEE_MAP',
            'message', 'Payee map is missing for the payout destination on this rail; the loan payout will appear as Blocked for Pay until payee mapping exists.',
            'candidate_id', v_case.candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;
  end if;

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', v_schedule_input_mode,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required
  );

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component_after.id::text,
    'classification', v_component_after.classification::text,
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_before_json,
    v_after_json,
    null::text,
    case when v_can_edit_payout_details then 'Payment Advance payout details updated while Not processed yet' else 'Payment Advance future repayment terms updated after draft/commit' end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_finance_component_id,
    'COMPONENT_UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_component_before_json,
    v_component_after_json,
    'PAYMENT_ADVANCE_COMPONENT_UPDATED',
    'Updated Payment Advance non-taxable fixed component state'
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'advance_id', p_finance_case_id::text,
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'payout_editable', v_can_edit_payout_details,
    'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end,
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required,
    'oneoff_bank_details_present', exists(
      select 1
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id
    ),
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_existing_oneoff.finance_case_id is null then null else v_existing_oneoff.beneficiary_name end,
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$function$;

-- pay_payment_advance_update(uuid,uuid,numeric,numeric,integer,date,text,numeric,numeric)
CREATE OR REPLACE FUNCTION public.pay_payment_advance_update(p_finance_case_id uuid, p_actor_user_id uuid, p_principal_amount numeric DEFAULT NULL::numeric, p_weekly_due numeric DEFAULT NULL::numeric, p_weeks_total integer DEFAULT NULL::integer, p_start_week_start date DEFAULT NULL::date, p_note text DEFAULT NULL::text, p_minimum_earnings_threshold numeric DEFAULT NULL::numeric, p_take_home_floor_override numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_batch public.pay_batches%rowtype;
  v_has_batch boolean := false;
  v_is_committed boolean := false;

  v_new_principal numeric(12,2);
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_notes text;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due date := null;
  v_required_weeks int := 0;

  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_can_edit_payout_details boolean := false;
  v_has_principal_change boolean := false;
  v_batch_item_id uuid := null;
  v_pay_batch_candidate_id uuid := null;

  v_schedule_base_amount numeric(12,2) := 0;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_component public.pay_finance_case_components%rowtype;
  v_component_after public.pay_finance_case_components%rowtype;
  v_finance_component_id uuid := null;
  v_component_before_json jsonb := '{}'::jsonb;
  v_component_after_json jsonb := '{}'::jsonb;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
  v_component_has_saved_resolution boolean := false;
  v_component_mark_stale boolean := false;
  v_component_stale_reason text := null;
  v_component_remaining_amount numeric(12,2) := 0;
  v_source_family_key text := null;

  v_candidate_pay_method text := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_payment_advance_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_payment_advance_update: Payment Advance not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method,''))
  into v_candidate_pay_method
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_case.payout_pay_batch_id is not null then
    select pb.*
    into v_batch
    from public.pay_batches pb
    where pb.id = v_case.payout_pay_batch_id
    limit 1;

    v_has_batch := v_batch.id is not null;
  end if;

  if v_has_batch then
    v_is_committed := (
      coalesce(v_batch.authoritative_payment_date is not null, false)
      or upper(coalesce(v_batch.status,'')) in ('SCHEDULED','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT','EXECUTING','SETTLED','COMPLETED','PARTIAL')
    );
  else
    v_is_committed := false;
  end if;

  v_can_edit_payout_details := (v_is_committed = false);

  v_new_principal := coalesce(round(p_principal_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;

  if v_new_minimum_earnings_threshold is not null and v_new_minimum_earnings_threshold < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_update: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if v_new_take_home_floor_override is not null and v_new_take_home_floor_override < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_update: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_has_principal_change := round(v_new_principal,2) <> round(coalesce(v_case.original_amount,0),2);

  if v_is_committed and v_has_principal_change then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'PAYOUT_ALREADY_COMMITTED',
      'message', 'pay_payment_advance_update: payout details can only be edited before commit; after commit only future repayment terms may be changed',
      'finance_case_id', p_finance_case_id::text,
      'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end
    )::text;
  end if;

  if v_can_edit_payout_details then
    if v_new_principal <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'PRINCIPAL_INVALID',
        'message', 'pay_payment_advance_update: principal_amount must be > 0'
      )::text;
    end if;
    v_schedule_base_amount := v_new_principal;
  else
    v_schedule_base_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  if p_start_week_start is not null and public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if p_weekly_due is not null and round(p_weekly_due,2) <= 0 and not v_has_weeks_total_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: weekly_due must be > 0 when provided'
    )::text;
  end if;

  if p_weeks_total is not null and p_weeks_total < 1 and not v_has_weekly_due_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: weeks_total must be >= 1 when provided'
    )::text;
  end if;

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    v_schedule_input_mode := 'UNCHANGED';
    v_new_weekly_due := round(coalesce(v_case.weekly_due,0),2);
    v_new_weeks_total := v_case.weeks_total;
  elsif v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_schedule_base_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: normalized weeks_total must be >= 1'
    )::text;
  end if;

  if p_start_week_start is not null then
    v_new_start_week_start := p_start_week_start;
  elsif v_case.next_due_week_start is not null then
    v_new_start_week_start := v_case.next_due_week_start;
  else
    v_new_start_week_start := v_case.start_week_start;
  end if;

  if v_new_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_update: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(v_new_start_week_start) <> v_new_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', v_new_start_week_start::text
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_update: repayment schedule does not cover the remaining amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total
    )::text;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_new_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_new_weekly_due,
              greatest(v_schedule_base_amount - (v_new_weekly_due * gs.i), 0)
            ),
            2
          )
        )
        order by (v_new_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_schedule_base_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_source_family_key := 'case:' || p_finance_case_id::text;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.source_family_key = v_source_family_key
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
    and pfc.closed_at_utc is null
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_new_principal,
      'weekly_due', v_new_weekly_due,
      'weeks_total', v_new_weeks_total,
      'start_week_start', v_new_start_week_start::text,
      'next_due_week_start', case when v_new_next_due is null then null else v_new_next_due::text end,
      'schedule_json', coalesce(v_new_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', v_new_minimum_earnings_threshold,
      'take_home_floor_override', v_new_take_home_floor_override,
      'note', v_new_notes
    )
  );

  if v_component.id is null then
    insert into public.pay_finance_case_components (
      finance_case_id,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      source_pay_method,
      source_basis_json,
      source_amount,
      remaining_source_amount,
      saved_target_pay_method,
      saved_resolution_mode,
      saved_resolution_payload_json,
      saved_resolution_result_json,
      resolution_fingerprint,
      is_resolution_stale,
      stale_reason,
      allocation_priority_group,
      allocation_priority_order,
      created_at_utc,
      updated_at_utc,
      resolved_at_utc,
      closed_at_utc
    )
    values (
      p_finance_case_id,
      v_case.candidate_id,
      v_case.client_id,
      v_case.linked_timesheet_id,
      v_source_family_key,
      'CASE_TOTAL',
      'TOTAL',
      'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
      v_candidate_pay_method,
      v_component_source_basis_json,
      v_new_principal,
      case when v_can_edit_payout_details then v_new_principal else round(coalesce(v_case.outstanding_amount,0),2) end,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      0,
      0,
      v_now_utc,
      v_now_utc,
      null,
      null
    )
    returning * into v_component;
  end if;

  v_component_has_saved_resolution := false;

  if v_can_edit_payout_details then
    v_component_remaining_amount := v_new_principal;
  else
    v_component_remaining_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  v_component_mark_stale := false;
  v_component_stale_reason := null;

  v_component_before_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  update public.pay_finance_case_components pfc
  set
    candidate_id = v_case.candidate_id,
    client_id = v_case.client_id,
    linked_timesheet_id = v_case.linked_timesheet_id,
    classification = 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
    source_pay_method = v_candidate_pay_method,
    source_basis_json = v_component_source_basis_json,
    source_amount = v_new_principal,
    remaining_source_amount = v_component_remaining_amount,
    saved_target_pay_method = null,
    saved_resolution_mode = null,
    saved_resolution_payload_json = null,
    saved_resolution_result_json = null,
    resolution_fingerprint = null,
    is_resolution_stale = false,
    stale_reason = null,
    allocation_priority_group = 0,
    allocation_priority_order = 0,
    updated_at_utc = v_now_utc
  where pfc.id = v_component.id
  returning * into v_component_after;

  v_finance_component_id := v_component_after.id;

  update public.pay_advances pa
  set
    original_amount = case when v_can_edit_payout_details then v_new_principal else pa.original_amount end,
    outstanding_amount = case when v_can_edit_payout_details then v_new_principal else pa.outstanding_amount end,
    schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
    next_due_week_start = v_new_next_due,
    notes = v_new_notes,
    weekly_due = v_new_weekly_due,
    weeks_total = v_new_weeks_total,
    start_week_start = v_new_start_week_start,
    minimum_earnings_threshold = v_new_minimum_earnings_threshold,
    take_home_floor_override = v_new_take_home_floor_override,
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  if v_can_edit_payout_details and v_has_batch then
    select pbc.id
    into v_pay_batch_candidate_id
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = v_batch.id
      and pbc.candidate_id = v_case.candidate_id
    limit 1;

    select pbi.id
    into v_batch_item_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc2
      on pbc2.id = pbi.pay_batch_candidate_id
    where pbc2.pay_batch_id = v_batch.id
      and pbc2.candidate_id = v_case.candidate_id
      and pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'LOAN_PAYOUT'
      and pbi.is_voided = false
    limit 1;

    if v_pay_batch_candidate_id is not null then
      update public.pay_batch_candidates pbc
      set gross_preview = v_new_principal,
          net_bank_amount = v_new_principal,
          updated_at = v_now_utc
      where pbc.id = v_pay_batch_candidate_id;
    end if;

    v_component_snapshot_json := jsonb_build_object(
      'finance_component_id', v_finance_component_id::text,
      'finance_case_id', p_finance_case_id::text,
      'source_family_key', v_source_family_key,
      'component_key_type', 'CASE_TOTAL',
      'component_key_value', 'TOTAL',
      'classification', 'NET_PAY_FIXED_RECOVERY',
      'source_pay_method', v_candidate_pay_method,
      'target_pay_method', v_candidate_pay_method,
      'source_basis_json', v_component_source_basis_json,
      'source_amount', v_new_principal,
      'remaining_source_amount', v_component_remaining_amount,
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_after.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_after.saved_resolution_result_json,
      'current_component_fingerprint', public.pay_finance_component_fingerprint(
        p_source_family_key => v_source_family_key,
        p_component_key_type => 'CASE_TOTAL',
        p_component_key_value => 'TOTAL',
        p_classification => 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
        p_source_pay_method => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json => v_component_source_basis_json,
        p_source_amount => v_new_principal,
        p_relevant_erni_pct => null,
        p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate_pay_method)
      )
    );

    if v_batch_item_id is not null then
      update public.pay_batch_items pbi
      set description = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          updated_at = v_now_utc,
          finance_case_id = p_finance_case_id,
          reservation_id = null,
          paye_treatment = 'NONE',
          finance_component_id = v_finance_component_id,
          frozen_component_snapshot_json = v_component_snapshot_json,
          frozen_component_key_type = 'CASE_TOTAL',
          frozen_component_key_value = 'TOTAL',
          frozen_component_classification = 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
          frozen_source_basis_json = v_component_source_basis_json,
          frozen_source_pay_method = v_candidate_pay_method,
          frozen_target_pay_method = v_candidate_pay_method,
          frozen_resolution_mode = v_component_after.saved_resolution_mode,
          frozen_resolution_payload_json = v_component_after.saved_resolution_payload_json,
          frozen_resolution_result_json = v_component_after.saved_resolution_result_json,
          frozen_source_amount = v_new_principal,
          frozen_target_amount_ex_vat = v_new_principal,
          frozen_target_amount_vat = 0,
          frozen_target_amount_inc_vat = v_new_principal
      where pbi.id = v_batch_item_id;

      update public.pay_batch_item_breakdowns pbib
      set unit_name = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          meta_json = jsonb_build_object(
            'case_type', 'PAYMENT_ADVANCE',
            'worker_label', 'Payment Advance'
          )
      where pbib.pay_batch_item_id = v_batch_item_id;
    end if;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', v_schedule_input_mode
  );

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component_after.id::text,
    'classification', v_component_after.classification::text,
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_before_json,
    v_after_json,
    null::text,
    case when v_can_edit_payout_details then 'Payment Advance payout details updated before commit' else 'Payment Advance future repayment terms updated after commit' end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_finance_component_id,
    'COMPONENT_UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_component_before_json,
    v_component_after_json,
    'PAYMENT_ADVANCE_COMPONENT_UPDATED',
    'Updated Payment Advance net-fixed component state'
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'NET_PAY_FIXED_RECOVERY',
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'advance_id', p_finance_case_id::text,
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'payout_editable', v_can_edit_payout_details,
    'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end,
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json
  );
end;
$function$;

-- pay_payment_cancel_finalise_metadata_v1(uuid,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_payment_cancel_finalise_metadata_v1(p_pay_batch_id uuid, p_correction_request_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_batch public.pay_batches%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_effective_actor_user_id uuid;
  v_actor_display text;
  v_actor_role text;
  v_effective_reason text;
  v_non_voided_item_count integer := 0;
  v_non_terminal_work_count integer := 0;
  v_audit_inserted_count integer := 0;
  v_before_json jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL OR p_correction_request_id IS NULL OR p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_REQUIRED_IDENTIFIERS_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_REQUIRED_IDENTIFIERS_MISSING',
              'pay_batch_id_present', p_pay_batch_id IS NOT NULL,
              'correction_request_id_present', p_correction_request_id IS NOT NULL,
              'actor_user_id_present', p_actor_user_id IS NOT NULL
            )::text;
  END IF;

  SELECT request_row.*
  INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_request.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR UPPER(BTRIM(COALESCE(v_request.correction_kind, ''))) <> 'PRE_BANK_CANCEL' THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_CORRECTION_REQUEST_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_CORRECTION_REQUEST_INVALID',
              'pay_batch_id', p_pay_batch_id::text,
              'correction_request_id', p_correction_request_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_request.status, ''))) <> 'APPLIED' THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_CORRECTION_NOT_APPLIED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_CORRECTION_NOT_APPLIED',
              'pay_batch_id', p_pay_batch_id::text,
              'correction_request_id', p_correction_request_id::text,
              'correction_status', v_request.status
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_non_terminal_work_count
  FROM public.pay_payment_correction_work_items AS work_item
  WHERE work_item.correction_request_id = p_correction_request_id
    AND UPPER(BTRIM(COALESCE(work_item.status, ''))) NOT IN ('APPLIED', 'SKIPPED', 'CANCELLED');

  IF COALESCE(v_non_terminal_work_count, 0) <> 0 THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_WORK_NOT_TERMINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_WORK_NOT_TERMINAL',
              'pay_batch_id', p_pay_batch_id::text,
              'correction_request_id', p_correction_request_id::text,
              'non_terminal_work_count', v_non_terminal_work_count
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_batch.status, ''))) <> 'CANCELLED'
     OR UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_BATCH_NOT_SAFE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_BATCH_NOT_SAFE',
              'pay_batch_id', p_pay_batch_id::text,
              'status', v_batch.status,
              'execution_commit_state', v_batch.execution_commit_state,
              'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL,
              'execution_committed_at_present', v_batch.execution_committed_at_utc IS NOT NULL
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_non_voided_item_count
  FROM public.pay_batch_items AS batch_item
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id = batch_item.pay_batch_candidate_id
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id
    AND COALESCE(batch_item.is_voided, false) IS NOT TRUE
    AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) <> 'DEBT_CREATED';

  IF COALESCE(v_non_voided_item_count, 0) <> 0 THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_ACTIVE_ITEMS_REMAIN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_ACTIVE_ITEMS_REMAIN',
              'pay_batch_id', p_pay_batch_id::text,
              'active_item_count', v_non_voided_item_count
            )::text;
  END IF;

  v_effective_actor_user_id := COALESCE(
    v_batch.cancelled_by_user_id,
    v_request.requested_by_user_id,
    p_actor_user_id
  );
  v_effective_reason := COALESCE(
    NULLIF(BTRIM(COALESCE(v_batch.cancel_reason, '')), ''),
    NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
    NULLIF(BTRIM(COALESCE(v_request.reason, '')), ''),
    'Draft batch cancelled before bank submission'
  );

  SELECT
    COALESCE(NULLIF(BTRIM(COALESCE(user_row.display_name, '')), ''), NULLIF(BTRIM(COALESCE(user_row.email, '')), ''), 'CloudTMS user'),
    COALESCE(NULLIF(BTRIM(COALESCE(user_row.role, '')), ''), 'system')
  INTO v_actor_display, v_actor_role
  FROM public.tms_users AS user_row
  WHERE user_row.id = v_effective_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FINALISE_ACTOR_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FINALISE_ACTOR_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text,
              'correction_request_id', p_correction_request_id::text
            )::text;
  END IF;

  v_before_json := jsonb_build_object(
    'status', v_batch.status,
    'cancelled_at_utc', v_batch.cancelled_at_utc,
    'cancelled_by_user_id', v_batch.cancelled_by_user_id,
    'cancel_reason', v_batch.cancel_reason,
    'schedule_kind', v_batch.schedule_kind,
    'scheduled_at_utc', v_batch.scheduled_at_utc,
    'scheduled_by_user_id', v_batch.scheduled_by_user_id,
    'funding_account_ref_present', NULLIF(BTRIM(COALESCE(v_batch.funding_account_ref, '')), '') IS NOT NULL
  );

  UPDATE public.pay_batches AS batch_to_finalise
  SET cancelled_at_utc = COALESCE(batch_to_finalise.cancelled_at_utc, v_request.applied_at_utc, v_now),
      cancelled_by_user_id = COALESCE(batch_to_finalise.cancelled_by_user_id, v_effective_actor_user_id),
      cancel_reason = COALESCE(NULLIF(BTRIM(COALESCE(batch_to_finalise.cancel_reason, '')), ''), v_effective_reason),
      schedule_kind = NULL,
      scheduled_at_utc = NULL,
      scheduled_by_user_id = NULL,
      funding_account_ref = NULL,
      funds_warning_hours_json = NULL,
      execution_commit_state = COALESCE(NULLIF(BTRIM(COALESCE(batch_to_finalise.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
  WHERE batch_to_finalise.id = p_pay_batch_id;

  INSERT INTO public.audit_events (
    actor_user_id,
    actor_display,
    actor_role_at_time,
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason,
    correlation_id
  )
  SELECT
    v_effective_actor_user_id,
    v_actor_display,
    v_actor_role,
    'pay_batch',
    p_pay_batch_id::text,
    'PAY_BATCH_CANCELLED',
    v_before_json,
    jsonb_build_object(
      'status', 'CANCELLED',
      'cancelled_at_utc', final_batch.cancelled_at_utc,
      'cancelled_by_user_id', final_batch.cancelled_by_user_id,
      'cancelled_by_display', v_actor_display,
      'cancel_reason', final_batch.cancel_reason,
      'correction_request_id', p_correction_request_id::text,
      'source_workbench_session_id', final_batch.source_workbench_session_id,
      'source_session_preserved', true,
      'execution_commit_state', final_batch.execution_commit_state
    ),
    v_effective_reason,
    p_correction_request_id::text
  FROM public.pay_batches AS final_batch
  WHERE final_batch.id = p_pay_batch_id
    AND NOT EXISTS (
      SELECT 1
      FROM public.audit_events AS existing_audit
      WHERE existing_audit.object_type = 'pay_batch'
        AND existing_audit.object_id_text = p_pay_batch_id::text
        AND existing_audit.action = 'PAY_BATCH_CANCELLED'
        AND existing_audit.correlation_id = p_correction_request_id::text
    );

  GET DIAGNOSTICS v_audit_inserted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', p_correction_request_id::text,
    'batch_status', 'CANCELLED',
    'cancelled_by_user_id', v_effective_actor_user_id::text,
    'cancelled_by_display', v_actor_display,
    'audit_action', 'PAY_BATCH_CANCELLED',
    'audit_inserted', COALESCE(v_audit_inserted_count, 0) > 0,
    'source_session_preserved', true,
    'policy_x_checked', true
  );
END;
$function$;

-- pay_payment_cancel_not_sent_and_recalculate_complete_v1(uuid,jsonb,uuid,text,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_payment_cancel_not_sent_and_recalculate_complete_v1(p_pay_batch_id uuid, p_selection_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_confirmation_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_chunk_result jsonb := '{}'::jsonb;
  v_finalise_result jsonb := '{}'::jsonb;
  v_changed_scope_json jsonb := '{}'::jsonb;
  v_correction_request_id uuid;
  v_complete boolean := false;
  v_iteration integer := 0;
  v_released_reservations integer := 0;
  v_restored_finance_components integer := 0;
  v_carry_forward_created integer := 0;
  v_carry_forward_existing integer := 0;
  v_carry_forward_released integer := 0;
BEGIN
  v_result := public.pay_payment_cancel_not_sent_and_recalculate(
    p_pay_batch_id => p_pay_batch_id,
    p_selection_json => p_selection_json,
    p_actor_user_id => p_actor_user_id,
    p_reason => p_reason,
    p_idempotency_key => p_idempotency_key,
    p_confirmation_json => p_confirmation_json
  );

  IF COALESCE((v_result->>'ok')::boolean, true) IS NOT TRUE THEN
    RETURN v_result;
  END IF;

  IF COALESCE(v_result->>'correction_request_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_COMPLETE_CORRECTION_REQUEST_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_COMPLETE_CORRECTION_REQUEST_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_correction_request_id := (v_result->>'correction_request_id')::uuid;
  v_complete := COALESCE(
    NULLIF(v_result->>'is_complete', '')::boolean,
    NULLIF(v_result#>>'{process_result,complete}', '')::boolean,
    false
  );
  v_released_reservations := COALESCE((v_result->>'released_reservation_count')::integer, 0);
  v_restored_finance_components := COALESCE((v_result->>'restored_finance_component_count')::integer, 0);
  v_carry_forward_created := COALESCE((v_result->>'carry_forward_created_count')::integer, 0);
  v_carry_forward_existing := COALESCE((v_result->>'carry_forward_existing_count')::integer, 0);
  v_carry_forward_released := COALESCE((v_result->>'carry_forward_released_count')::integer, 0);

  WHILE v_complete IS NOT TRUE AND v_iteration < 100 LOOP
    v_iteration := v_iteration + 1;
    v_chunk_result := public.pay_payment_correction_process_chunk(
      p_correction_request_id => v_correction_request_id,
      p_limit => 100,
      p_worker_id => 'cancel-not-sent-complete-v1',
      p_actor_user_id => p_actor_user_id
    );

    v_released_reservations := v_released_reservations + COALESCE((v_chunk_result->>'released_reservations')::integer, 0);
    v_restored_finance_components := v_restored_finance_components + COALESCE((v_chunk_result->>'restored_finance_components')::integer, 0);
    v_carry_forward_created := v_carry_forward_created + COALESCE((v_chunk_result->>'carry_forward_created')::integer, 0);
    v_carry_forward_existing := v_carry_forward_existing + COALESCE((v_chunk_result->>'carry_forward_existing')::integer, 0);
    v_carry_forward_released := v_carry_forward_released + COALESCE((v_chunk_result->>'carry_forward_released')::integer, 0);
    v_complete := COALESCE((v_chunk_result->>'complete')::boolean, false);

    IF COALESCE((v_chunk_result->>'requires_user_action')::boolean, false)
       OR COALESCE((v_chunk_result#>>'{totals,blocked}')::integer, 0) > 0
       OR COALESCE((v_chunk_result#>>'{totals,failed_retryable}')::integer, 0) > 0
       OR COALESCE((v_chunk_result#>>'{totals,failed_final}')::integer, 0) > 0 THEN
      RETURN v_result || jsonb_build_object(
        'ok', false,
        'is_complete', v_complete,
        'error_code', 'PAYMENT_CANCEL_NOT_SENT_PROCESS_INCOMPLETE',
        'code', 'PAYMENT_CANCEL_NOT_SENT_PROCESS_INCOMPLETE',
        'message', 'The draft was not cancelled because one or more frozen payment items could not be safely released. Refresh Banking Pay and review the specific blocked item.',
        'user_message', 'The draft was not cancelled because one or more frozen payment items could not be safely released. Refresh Banking Pay and review the specific blocked item.',
        'process_result', v_chunk_result
      );
    END IF;
  END LOOP;

  IF v_complete IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_COMPLETE_LIMIT_EXCEEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_COMPLETE_LIMIT_EXCEEDED',
              'message', 'Cancellation could not finish within the safe processing limit, so no partial cancellation was committed.',
              'pay_batch_id', p_pay_batch_id::text,
              'correction_request_id', v_correction_request_id::text,
              'iterations', v_iteration
            )::text;
  END IF;

  SELECT jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_correction_request_id::text,
    'change_kind', 'PRE_BANK_CANCEL',
    'changed_pay_batch_item_ids', COALESCE(jsonb_agg(DISTINCT item_row.pay_batch_item_id::text ORDER BY item_row.pay_batch_item_id::text) FILTER (WHERE item_row.pay_batch_item_id IS NOT NULL), '[]'::jsonb),
    'changed_pay_batch_candidate_ids', COALESCE(jsonb_agg(DISTINCT item_row.pay_batch_candidate_id::text ORDER BY item_row.pay_batch_candidate_id::text) FILTER (WHERE item_row.pay_batch_candidate_id IS NOT NULL), '[]'::jsonb),
    'changed_candidate_ids', COALESCE(jsonb_agg(DISTINCT item_row.candidate_id::text ORDER BY item_row.candidate_id::text) FILTER (WHERE item_row.candidate_id IS NOT NULL), '[]'::jsonb),
    'changed_transfer_ids', COALESCE(jsonb_agg(DISTINCT item_row.pay_bank_transfer_id::text ORDER BY item_row.pay_bank_transfer_id::text) FILTER (WHERE item_row.pay_bank_transfer_id IS NOT NULL), '[]'::jsonb),
    'changed_finance_case_ids', COALESCE(jsonb_agg(DISTINCT item_row.finance_case_id::text ORDER BY item_row.finance_case_id::text) FILTER (WHERE item_row.finance_case_id IS NOT NULL), '[]'::jsonb),
    'changed_finance_component_ids', COALESCE(jsonb_agg(DISTINCT item_row.finance_component_id::text ORDER BY item_row.finance_component_id::text) FILTER (WHERE item_row.finance_component_id IS NOT NULL), '[]'::jsonb),
    'changed_reservation_ids', COALESCE(jsonb_agg(DISTINCT item_row.reservation_id::text ORDER BY item_row.reservation_id::text) FILTER (WHERE item_row.reservation_id IS NOT NULL), '[]'::jsonb),
    'applied_correction_item_count', COUNT(*)::integer
  )
  INTO v_changed_scope_json
  FROM public.pay_payment_correction_items AS item_row
  WHERE item_row.correction_request_id = v_correction_request_id
    AND item_row.correction_item_kind = 'PRE_BANK_CANCEL'
    AND item_row.status = 'APPLIED';

  v_finalise_result := public.pay_payment_cancel_finalise_metadata_v1(
    p_pay_batch_id,
    v_correction_request_id,
    p_actor_user_id,
    p_reason
  );

  RETURN v_result || jsonb_build_object(
    'ok', true,
    'is_complete', true,
    'complete', true,
    'process_result', CASE WHEN v_iteration > 0 THEN v_chunk_result ELSE COALESCE(v_result->'process_result', '{}'::jsonb) END,
    'changed_scope_json', COALESCE(v_changed_scope_json, '{}'::jsonb),
    'released_reservation_count', v_released_reservations,
    'restored_finance_component_count', v_restored_finance_components,
    'carry_forward_created_count', v_carry_forward_created,
    'carry_forward_existing_count', v_carry_forward_existing,
    'carry_forward_released_count', v_carry_forward_released,
    'completion_chunk_count', v_iteration,
    'cancellation_finalisation', v_finalise_result,
    'source_session_preserved', true,
    'policy_x_checked', true
  );
END;
$function$;

-- pay_payment_cancel_not_sent_and_recalculate_with_workbench_refr(uuid,jsonb,uuid,text,text,jsonb,uuid,bigint,text)
CREATE OR REPLACE FUNCTION public.pay_payment_cancel_not_sent_and_recalculate_with_workbench_refr(p_pay_batch_id uuid, p_selection_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_confirmation_json jsonb DEFAULT '{}'::jsonb, p_source_workbench_session_id uuid DEFAULT NULL::uuid, p_expected_source_session_version bigint DEFAULT NULL::bigint, p_replacement_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_actor_is_active boolean := false;
  v_source_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_cancellation_result jsonb := '{}'::jsonb;
  v_process_result jsonb := '{}'::jsonb;
  v_replacement_result jsonb := NULL::jsonb;
  v_final_result jsonb := NULL::jsonb;
  v_replay_metadata_json jsonb := NULL::jsonb;
  v_stored_result_json jsonb := NULL::jsonb;
  v_stored_input_fingerprint text := NULL::text;
  v_input_fingerprint text := NULL::text;
  v_replacement_idempotency_key text := NULLIF(
    BTRIM(COALESCE(p_replacement_idempotency_key, '')),
    ''
  );
  v_cancellation_idempotency_key text := NULLIF(
    BTRIM(COALESCE(p_idempotency_key, '')),
    ''
  );
  v_cancellation_ok boolean := false;
  v_payable_state_changed boolean := false;
  v_process_applied_count integer := 0;
  v_voided_item_count integer := 0;
  v_voided_transfer_count integer := 0;
  v_released_reservation_count integer := 0;
  v_restored_finance_component_count integer := 0;
  v_carry_forward_created_count integer := 0;
  v_carry_forward_released_count integer := 0;
  v_replacement_session_id_text text := NULL::text;
  v_replacement_session_id uuid := NULL::uuid;
  v_replacement_session_version bigint := NULL::bigint;
  v_replacement_created boolean := false;
  v_replacement_reused boolean := false;
  v_work_queued boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED'
            )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED'
            )::text;
  END IF;

  IF p_selection_json IS NOT NULL
     AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT'
            )::text;
  END IF;

  IF p_confirmation_json IS NOT NULL
     AND COALESCE(jsonb_typeof(p_confirmation_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT'
            )::text;
  END IF;

  IF p_source_workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_expected_source_session_version IS NULL
     OR p_expected_source_session_version < 1 THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_EXPECTED_VERSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_EXPECTED_VERSION_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text
            )::text;
  END IF;

  IF v_replacement_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_IDEMPOTENCY_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_IDEMPOTENCY_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text
            )::text;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id
      AND COALESCE(actor_user.is_active, false) = true
  )
  INTO v_actor_is_active;

  IF COALESCE(v_actor_is_active, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED',
              'actor_user_id', p_actor_user_id::text
            )::text;
  END IF;

  v_input_fingerprint := md5(
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'selection_hash', md5(COALESCE(p_selection_json, '{}'::jsonb)::text),
      'actor_user_id', p_actor_user_id::text,
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'cancellation_idempotency_key', v_cancellation_idempotency_key,
      'ui_mode', UPPER(REPLACE(NULLIF(BTRIM(COALESCE(
        p_confirmation_json->>'ui_mode',
        p_selection_json->>'ui_mode',
        ''
      )), ''), '-', '_')),
      'source_workbench_session_id', p_source_workbench_session_id::text,
      'expected_source_session_version', p_expected_source_session_version,
      'replacement_idempotency_key', v_replacement_idempotency_key
    )::text
  );

  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtext('public.pay_payment_cancel_not_sent_and_recalculate_with_workbench_refresh'),
    pg_catalog.hashtext(v_replacement_idempotency_key)
  );

  SELECT source_session.*
  INTO v_source_session_row
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.id = p_source_workbench_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text
            )::text;
  END IF;

  IF v_source_session_row.replacement_session_id IS NOT NULL
     AND v_source_session_row.replacement_idempotency_key IS DISTINCT FROM v_replacement_idempotency_key THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_ALREADY_REPLACED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_ALREADY_REPLACED',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'replacement_session_id', v_source_session_row.replacement_session_id::text,
              'existing_replacement_idempotency_key', v_source_session_row.replacement_idempotency_key,
              'requested_replacement_idempotency_key', v_replacement_idempotency_key
            )::text;
  END IF;

  IF v_source_session_row.replacement_session_id IS NOT NULL
     AND v_source_session_row.replacement_idempotency_key = v_replacement_idempotency_key THEN
    SELECT replay_audit.after_json
    INTO v_replay_metadata_json
    FROM public.audit_events AS replay_audit
    WHERE replay_audit.object_type = 'banking_pay_workbench_session'
      AND replay_audit.object_id_text = p_source_workbench_session_id::text
      AND replay_audit.action = 'PAYMENT_CANCEL_WORKBENCH_SESSION_REPLACED'
      AND replay_audit.after_json->>'replacement_idempotency_key' = v_replacement_idempotency_key
    ORDER BY replay_audit.ts_utc DESC,
             replay_audit.id DESC
    LIMIT 1;

    v_stored_input_fingerprint := NULLIF(
      BTRIM(COALESCE(v_replay_metadata_json->>'input_fingerprint', '')),
      ''
    );
    v_stored_result_json := CASE
      WHEN jsonb_typeof(v_replay_metadata_json->'result') = 'object'
        THEN v_replay_metadata_json->'result'
      ELSE NULL::jsonb
    END;

    IF v_stored_input_fingerprint IS NULL OR v_stored_result_json IS NULL THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_RESULT_INCOMPLETE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_RESULT_INCOMPLETE',
                'pay_batch_id', p_pay_batch_id::text,
                'source_workbench_session_id', p_source_workbench_session_id::text,
                'replacement_session_id', v_source_session_row.replacement_session_id::text,
                'replacement_idempotency_key', v_replacement_idempotency_key
              )::text;
    END IF;

    IF v_stored_input_fingerprint IS DISTINCT FROM v_input_fingerprint THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_CONFLICT',
                'pay_batch_id', p_pay_batch_id::text,
                'source_workbench_session_id', p_source_workbench_session_id::text,
                'replacement_idempotency_key', v_replacement_idempotency_key
              )::text;
    END IF;

    v_replacement_result := public.pay_workbench_session_replace_after_mutation(
      p_actor_user_id => p_actor_user_id,
      p_source_session_id => p_source_workbench_session_id,
      p_replacement_idempotency_key => v_replacement_idempotency_key,
      p_expected_source_version => p_expected_source_session_version,
      p_reason => 'PAYMENT_CANCEL_NOT_SENT_AND_RECALCULATE'
    );

    IF jsonb_typeof(COALESCE(v_replacement_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_replacement_result->>'ok', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLAY_REPLACEMENT_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLAY_REPLACEMENT_INVALID',
                'pay_batch_id', p_pay_batch_id::text,
                'source_workbench_session_id', p_source_workbench_session_id::text,
                'replacement_idempotency_key', v_replacement_idempotency_key,
                'replacement_result', COALESCE(v_replacement_result, '{}'::jsonb)
              )::text;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_stored_result_json->>'replacement_session_id', '')), '')
       IS DISTINCT FROM v_source_session_row.replacement_session_id::text THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_REPLACEMENT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_IDEMPOTENCY_REPLACEMENT_MISMATCH',
                'pay_batch_id', p_pay_batch_id::text,
                'source_workbench_session_id', p_source_workbench_session_id::text,
                'stored_replacement_session_id', v_stored_result_json->>'replacement_session_id',
                'actual_replacement_session_id', v_source_session_row.replacement_session_id::text
              )::text;
    END IF;

    RETURN v_stored_result_json;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_source_session_row.status, ''))) <> 'OPEN'
     OR v_source_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_SOURCE_SESSION_NOT_OPEN',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'source_session_status', v_source_session_row.status,
              'source_discarded_at_utc', v_source_session_row.discarded_at_utc
            )::text;
  END IF;

  IF v_source_session_row.version IS DISTINCT FROM p_expected_source_session_version THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_EXPECTED_VERSION_CONFLICT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_EXPECTED_VERSION_CONFLICT',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'expected_source_session_version', p_expected_source_session_version,
              'actual_source_session_version', v_source_session_row.version
            )::text;
  END IF;

  v_cancellation_result := public.pay_payment_cancel_not_sent_and_recalculate(
    p_pay_batch_id => p_pay_batch_id,
    p_selection_json => p_selection_json,
    p_actor_user_id => p_actor_user_id,
    p_reason => p_reason,
    p_idempotency_key => p_idempotency_key,
    p_confirmation_json => p_confirmation_json
  );

  IF v_cancellation_result IS NULL
     OR jsonb_typeof(v_cancellation_result) <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_CANCELLATION_RESULT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_CANCELLATION_RESULT_INVALID',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_cancellation_ok := LOWER(BTRIM(COALESCE(v_cancellation_result->>'ok', 'false')))
    IN ('true', 't', '1', 'yes', 'y', 'on');

  v_process_result := CASE
    WHEN jsonb_typeof(v_cancellation_result->'process_result') = 'object'
      THEN COALESCE(v_cancellation_result->'process_result', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_process_applied_count := CASE
    WHEN COALESCE(v_process_result #>> '{totals,applied}', '') ~ '^[0-9]{1,9}$'
      THEN (v_process_result #>> '{totals,applied}')::integer
    WHEN COALESCE(v_process_result->>'applied', '') ~ '^[0-9]{1,9}$'
      THEN (v_process_result->>'applied')::integer
    WHEN COALESCE(v_cancellation_result->>'progress_completed', '') ~ '^[0-9]{1,9}$'
         AND COALESCE(v_cancellation_result->>'voided_item_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'voided_item_count')::integer
    ELSE 0
  END;

  v_voided_item_count := CASE
    WHEN COALESCE(v_cancellation_result->>'voided_item_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'voided_item_count')::integer
    ELSE 0
  END;

  v_voided_transfer_count := CASE
    WHEN COALESCE(v_cancellation_result->>'voided_transfer_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'voided_transfer_count')::integer
    ELSE 0
  END;

  v_released_reservation_count := CASE
    WHEN COALESCE(v_cancellation_result->>'released_reservation_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'released_reservation_count')::integer
    ELSE 0
  END;

  v_restored_finance_component_count := CASE
    WHEN COALESCE(v_cancellation_result->>'restored_finance_component_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'restored_finance_component_count')::integer
    ELSE 0
  END;

  v_carry_forward_created_count := CASE
    WHEN COALESCE(v_cancellation_result->>'carry_forward_created_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'carry_forward_created_count')::integer
    ELSE 0
  END;

  v_carry_forward_released_count := CASE
    WHEN COALESCE(v_cancellation_result->>'carry_forward_released_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_cancellation_result->>'carry_forward_released_count')::integer
    ELSE 0
  END;

  v_payable_state_changed := v_cancellation_ok
    AND (
      v_process_applied_count > 0
      OR v_voided_item_count > 0
      OR v_voided_transfer_count > 0
      OR v_released_reservation_count > 0
      OR v_restored_finance_component_count > 0
      OR v_carry_forward_created_count > 0
      OR v_carry_forward_released_count > 0
    );

  IF v_payable_state_changed IS NOT TRUE THEN
    RETURN v_cancellation_result
      || jsonb_build_object(
        'payable_state_changed', false,
        'workbench_refresh_required', false,
        'workbench_replacement_attempted', false,
        'workbench_session_replaced', false,
        'source_workbench_session_id', p_source_workbench_session_id::text,
        'expected_source_session_version', p_expected_source_session_version,
        'replacement_idempotency_key', v_replacement_idempotency_key,
        'replacement_session_id', NULL::text,
        'replacement_session_version', NULL::bigint,
        'replacement_created', false,
        'replacement_reused', false,
        'work_queued', false,
        'workbench_refresh', NULL::jsonb
      );
  END IF;

  v_replacement_result := public.pay_workbench_session_replace_after_mutation(
    p_actor_user_id => p_actor_user_id,
    p_source_session_id => p_source_workbench_session_id,
    p_replacement_idempotency_key => v_replacement_idempotency_key,
    p_expected_source_version => p_expected_source_session_version,
    p_reason => 'PAYMENT_CANCEL_NOT_SENT_AND_RECALCULATE'
  );

  IF jsonb_typeof(COALESCE(v_replacement_result, '{}'::jsonb)) <> 'object'
     OR LOWER(BTRIM(COALESCE(v_replacement_result->>'ok', 'false')))
        NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_FAILED',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'replacement_idempotency_key', v_replacement_idempotency_key,
              'replacement_result', COALESCE(v_replacement_result, '{}'::jsonb)
            )::text;
  END IF;

  v_replacement_session_id_text := NULLIF(
    BTRIM(COALESCE(v_replacement_result->>'replacement_session_id', '')),
    ''
  );

  IF v_replacement_session_id_text IS NULL THEN
    v_replacement_session_id_text := NULLIF(
      BTRIM(COALESCE(v_replacement_result->>'session_id', '')),
      ''
    );
  END IF;

  IF COALESCE(v_replacement_session_id_text, '')
     !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_SESSION_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_SESSION_INVALID',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'replacement_result', v_replacement_result
            )::text;
  END IF;

  v_replacement_session_id := v_replacement_session_id_text::uuid;

  SELECT source_session.*
  INTO v_source_session_row
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.id = p_source_workbench_session_id;

  IF NOT FOUND
     OR v_source_session_row.replacement_session_id IS DISTINCT FROM v_replacement_session_id
     OR v_source_session_row.replacement_idempotency_key IS DISTINCT FROM v_replacement_idempotency_key THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_LINK_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_WORKBENCH_REPLACEMENT_LINK_MISMATCH',
              'pay_batch_id', p_pay_batch_id::text,
              'source_workbench_session_id', p_source_workbench_session_id::text,
              'expected_replacement_session_id', v_replacement_session_id_text,
              'actual_replacement_session_id', CASE
                WHEN v_source_session_row.replacement_session_id IS NULL THEN NULL::text
                ELSE v_source_session_row.replacement_session_id::text
              END,
              'expected_replacement_idempotency_key', v_replacement_idempotency_key,
              'actual_replacement_idempotency_key', v_source_session_row.replacement_idempotency_key
            )::text;
  END IF;

  v_replacement_session_version := CASE
    WHEN COALESCE(v_replacement_result->>'replacement_session_version', '') ~ '^[0-9]{1,18}$'
      THEN (v_replacement_result->>'replacement_session_version')::bigint
    WHEN COALESCE(v_replacement_result->>'session_version', '') ~ '^[0-9]{1,18}$'
      THEN (v_replacement_result->>'session_version')::bigint
    ELSE NULL::bigint
  END;

  v_replacement_created := LOWER(BTRIM(COALESCE(
    v_replacement_result->>'replacement_created',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_replacement_reused := LOWER(BTRIM(COALESCE(
    v_replacement_result->>'replacement_reused',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_work_queued := LOWER(BTRIM(COALESCE(
    v_replacement_result->>'work_queued',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_final_result := v_cancellation_result
    || jsonb_build_object(
      'payable_state_changed', true,
      'workbench_refresh_required', true,
      'workbench_replacement_attempted', true,
      'workbench_session_replaced', true,
      'source_workbench_session_id', p_source_workbench_session_id::text,
      'expected_source_session_version', p_expected_source_session_version,
      'replacement_idempotency_key', v_replacement_idempotency_key,
      'replacement_session_id', v_replacement_session_id_text,
      'replacement_session_version', v_replacement_session_version,
      'replacement_created', v_replacement_created,
      'replacement_reused', v_replacement_reused,
      'work_queued', v_work_queued
    )
    || jsonb_build_object(
      'source_session_obsolete', LOWER(BTRIM(COALESCE(
        v_replacement_result->>'source_session_obsolete',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'replacement_session_status', v_replacement_result->>'replacement_session_status',
      'replacement_progress_state', v_replacement_result->>'replacement_progress_state',
      'replacement_lifecycle_action', v_replacement_result->>'replacement_lifecycle_action',
      'old_rows_retained', LOWER(BTRIM(COALESCE(
        v_replacement_result->>'old_rows_retained',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'atomic_replacement', LOWER(BTRIM(COALESCE(
        v_replacement_result->>'atomic_replacement',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'workbench_refresh', v_replacement_result
    );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_source_workbench_session_id::text,
    'PAYMENT_CANCEL_WORKBENCH_SESSION_REPLACED',
    NULL::jsonb,
    jsonb_build_object(
      'input_fingerprint', v_input_fingerprint,
      'pay_batch_id', p_pay_batch_id::text,
      'cancellation_idempotency_key', v_cancellation_idempotency_key,
      'replacement_idempotency_key', v_replacement_idempotency_key,
      'replacement_session_id', v_replacement_session_id_text,
      'completed_at_utc', v_now::text,
      'result', v_final_result
    ),
    'PAYMENT_CANCEL_NOT_SENT_AND_RECALCULATE',
    p_actor_user_id
  );

  RETURN v_final_result;
END;
$function$;

-- pay_payment_cancel_not_sent_and_recalculate(uuid,jsonb,uuid,text,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_payment_cancel_not_sent_and_recalculate(p_pay_batch_id uuid, p_selection_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_confirmation_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_selection_json jsonb := '{}'::jsonb;
  v_confirmation_json jsonb := '{}'::jsonb;
  v_diagnostic_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_lifecycle_state text := NULL::text;
  v_recommended_action text := NULL::text;
  v_blockers jsonb := '[]'::jsonb;
  v_race_blockers jsonb := '[]'::jsonb;
  v_effective_selection_json jsonb := '{}'::jsonb;
  v_selection_hash text := NULL::text;
  v_plan_json jsonb := '{}'::jsonb;
  v_plan_hash text := NULL::text;
  v_accepted_resolution_json jsonb := '{}'::jsonb;
  v_accepted_resolution_hash text := NULL::text;
  v_required_quantity integer := 1;
  v_reason text := NULL::text;
  v_existing_request public.pay_payment_correction_requests%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_expand_result jsonb := '{}'::jsonb;
  v_process_result jsonb := '{}'::jsonb;
  v_signal_result jsonb := '{}'::jsonb;
  v_idempotency_key text := NULL::text;
  v_scope_type text := NULL::text;
  v_ui_mode text := NULL::text;
  v_batch_status text := NULL::text;
  v_execution_commit_state text := NULL::text;
  v_execution_commit_ref text := NULL::text;
  v_execution_committed_at_utc timestamptz := NULL::timestamptz;
  v_active_unsafe_operation_count integer := 0;
  v_active_unsafe_operation_ids jsonb := '[]'::jsonb;
  v_actor_valid boolean := false;
  v_is_complete boolean := false;
  v_grouped_alert_updates jsonb := '[]'::jsonb;
  v_process_total integer := 0;
  v_process_applied integer := 0;
  v_process_skipped integer := 0;
  v_process_blocked integer := 0;
  v_process_failed_retryable integer := 0;
  v_process_failed_final integer := 0;
  v_process_pending integer := 0;
  v_process_processing integer := 0;
  v_process_cancelled integer := 0;
  v_process_parent_status text := NULL::text;
  v_process_failed boolean := false;
  v_process_error_code text := NULL::text;
  v_process_error_message text := NULL::text;
  v_process_voided_item_count integer := 0;
  v_request_changed_scope_json jsonb := '{}'::jsonb;
  v_resume_request_count integer := 0;
  v_resume_existing_request boolean := false;
  v_resume_blocked_reset_count integer := 0;
  v_resume_expected_json_count integer := 0;
  v_resume_expected_valid_count integer := 0;
  v_resume_expected_belongs_count integer := 0;
  v_resume_expected_active_count integer := 0;
  v_resume_expected_same_request_voided_count integer := 0;
  v_resume_expected_disallowed_state_count integer := 0;
  v_resume_active_outside_original_count integer := 0;
  v_resume_applied_work_item_count integer := 0;
  v_resume_blocked_work_item_count integer := 0;
  v_resume_invalid_blocked_work_item_count integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_confirmation_json IS NOT NULL AND COALESCE(jsonb_typeof(p_confirmation_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT')::text;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id
      AND COALESCE(actor_user.is_active, false) = true
  )
  INTO v_actor_valid;

  IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED', 'actor_user_id', p_actor_user_id::text)::text;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_confirmation_json := COALESCE(p_confirmation_json, '{}'::jsonb);
  v_reason := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_scope_type := COALESCE(NULLIF(BTRIM(UPPER(COALESCE(v_selection_json ->> 'scope_type', v_selection_json ->> 'scopeType', ''))), ''), 'BATCH');
  v_ui_mode := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'ui_mode', v_selection_json ->> 'ui_mode', '')), ''), '-', '_'));

  SELECT batch_rows.status,
         batch_rows.execution_commit_state,
         batch_rows.execution_commit_ref,
         batch_rows.execution_committed_at_utc
  INTO v_batch_status,
       v_execution_commit_state,
       v_execution_commit_ref,
       v_execution_committed_at_utc
  FROM public.pay_batches AS batch_rows
  WHERE batch_rows.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF UPPER(COALESCE(v_execution_commit_state, '')) <> 'NOT_SUBMITTED'
     OR NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') IS NOT NULL
     OR v_execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_COMMIT_BOUNDARY_CROSSED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_COMMIT_BOUNDARY_CROSSED',
              'pay_batch_id', p_pay_batch_id::text,
              'status', v_batch_status,
              'execution_commit_state', v_execution_commit_state,
              'has_execution_commit_ref', NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') IS NOT NULL,
              'has_execution_committed_at_utc', v_execution_committed_at_utc IS NOT NULL
            )::text;
  END IF;

  IF v_ui_mode = 'DRAFT_DELETE' AND UPPER(COALESCE(v_batch_status, '')) NOT IN ('DRAFT', 'DRAFT_CREATED') THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_NOT_AVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'status', v_batch_status,
              'execution_commit_state', v_execution_commit_state
            )::text;
  END IF;

  IF v_ui_mode = 'DRAFT_DELETE' AND v_scope_type NOT IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH') THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_REQUIRES_BATCH_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_REQUIRES_BATCH_SCOPE',
              'pay_batch_id', p_pay_batch_id::text,
              'scope_type', v_scope_type
            )::text;
  END IF;

  IF v_ui_mode = 'DRAFT_DELETE'
     OR v_scope_type IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH') THEN
    SELECT count(*)::integer,
           COALESCE(jsonb_agg(active_operation_rows.id::text ORDER BY active_operation_rows.created_at_utc, active_operation_rows.id), '[]'::jsonb)
    INTO v_active_unsafe_operation_count,
         v_active_unsafe_operation_ids
    FROM public.banking_pay_operations AS active_operation_rows
    WHERE active_operation_rows.pay_batch_id = p_pay_batch_id
      AND UPPER(COALESCE(active_operation_rows.operation_type::text, '')) IN (
        'DRAFT_CREATE',
        'PAYMENT_DRAFT_CREATE',
        'PAY_BATCH_DRAFT_CREATE',
        'CREATE_DRAFT',
        'PAYMENT_EXECUTE',
        'PAY_EXECUTE',
        'PROVIDER_SUBMIT',
        'PAYMENT_PROVIDER_SUBMIT',
        'PAYMENT_SUBMISSION',
        'RAIL_SUBMIT',
        'BANK_SUBMISSION',
        'PAYMENT_AUTHORISE',
        'PAYMENT_AUTHORIZE',
        'PAYMENT_AUTH_START',
        'PAYMENT_RETRY_BLOCKED_FUNDS',
        'PAYMENT_RETRY_UNSENT_PAYMENTS',
        'PAYMENT_RETRY_UNSENT',
        'PAYMENT_SETTLEMENT'
      )
      AND UPPER(COALESCE(active_operation_rows.status::text, '')) NOT IN (
        'COMPLETE',
        'COMPLETED',
        'SUCCESS',
        'SUCCEEDED',
        'DONE',
        'FAILED',
        'ERROR',
        'ERRORED',
        'REVIEW_REQUIRED',
        'CANCELLED',
        'CANCELED',
        'ABORTED'
      )
      AND (
        UPPER(COALESCE(active_operation_rows.status::text, '')) IN (
          'QUEUED',
          'RUNNABLE',
          'RUNNING',
          'CONTINUING',
          'WAITING_RETRY',
          'LEASED',
          'ADVANCING',
          'PENDING',
          'STARTED',
          'INITIALISING',
          'INITIALIZING',
          'PROCESSING',
          'CLAIMED',
          'IN_PROGRESS',
          'WAITING_PROVIDER',
          'WAITING_FOR_PROVIDER',
          'PROVIDER_WAIT',
          'PROVIDER_WAITING',
          'WAITING_PROVIDER_CONFIRMATION',
          'WAITING_AUTHORISATION',
          'WAITING_AUTHORIZATION',
          'AWAITING_AUTHORISATION',
          'AWAITING_AUTHORIZATION',
          'AUTHORISATION_REQUIRED',
          'AUTHORIZATION_REQUIRED',
          'WAITING_BANK_CONFIRM',
          'SUBMITTED_NOT_COMMITTED'
        )
        OR UPPER(COALESCE(active_operation_rows.runner_state::text, '')) IN (
          'RUNNABLE',
          'RUNNING',
          'CONTINUING',
          'WAITING_RETRY',
          'LEASED',
          'ADVANCING',
          'PENDING',
          'STARTED',
          'INITIALISING',
          'INITIALIZING',
          'PROCESSING',
          'CLAIMED',
          'IN_PROGRESS',
          'WAITING_PROVIDER',
          'WAITING_FOR_PROVIDER',
          'PROVIDER_WAIT',
          'PROVIDER_WAITING',
          'WAITING_PROVIDER_CONFIRMATION',
          'WAITING_AUTHORISATION',
          'WAITING_AUTHORIZATION',
          'AWAITING_AUTHORISATION',
          'AWAITING_AUTHORIZATION',
          'AUTHORISATION_REQUIRED',
          'AUTHORIZATION_REQUIRED',
          'WAITING_BANK_CONFIRM'
        )
        OR (
          NULLIF(BTRIM(COALESCE(active_operation_rows.lease_owner, '')), '') IS NOT NULL
          AND COALESCE(active_operation_rows.lease_expires_at_utc, now()) > now()
        )
        OR (
          NULLIF(BTRIM(COALESCE(active_operation_rows.locked_by, '')), '') IS NOT NULL
          AND COALESCE(active_operation_rows.lock_expires_at_utc, now()) > now()
        )
      );

    IF COALESCE(v_active_unsafe_operation_count, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_OPERATION_IN_PROGRESS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_DRAFT_DELETE_OPERATION_IN_PROGRESS',
                'pay_batch_id', p_pay_batch_id::text,
                'active_operation_count', COALESCE(v_active_unsafe_operation_count, 0),
                'active_operation_ids', COALESCE(v_active_unsafe_operation_ids, '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  SELECT count(*)::integer
  INTO v_resume_request_count
  FROM public.pay_payment_correction_requests AS resumable_request_rows
  WHERE resumable_request_rows.pay_batch_id = p_pay_batch_id
    AND resumable_request_rows.correction_kind = 'PRE_BANK_CANCEL'
    AND resumable_request_rows.status = 'APPLIED_WITH_BLOCKERS'
    AND UPPER(BTRIM(COALESCE(resumable_request_rows.selection_json->>'scope_type', ''))) IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH')
    AND EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_work_items AS resumable_applied_items
      WHERE resumable_applied_items.correction_request_id = resumable_request_rows.id
        AND resumable_applied_items.work_kind = 'PRE_BANK_CANCEL'
        AND resumable_applied_items.status = 'APPLIED'
    )
    AND EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_work_items AS resumable_blocked_items
      WHERE resumable_blocked_items.correction_request_id = resumable_request_rows.id
        AND resumable_blocked_items.work_kind = 'PRE_BANK_CANCEL'
        AND resumable_blocked_items.status = 'BLOCKED'
        AND COALESCE(
          resumable_blocked_items.result_json#>>'{blocker,code}',
          resumable_blocked_items.result_json->>'error_code',
          ''
        ) = 'PRE_BANK_CANCEL_CLASSIFICATION_REQUIRED'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_work_items AS resumable_invalid_items
      WHERE resumable_invalid_items.correction_request_id = resumable_request_rows.id
        AND resumable_invalid_items.status NOT IN ('APPLIED', 'BLOCKED')
    );

  IF v_resume_request_count = 1 THEN
    SELECT resumable_request_rows.*
    INTO v_existing_request
    FROM public.pay_payment_correction_requests AS resumable_request_rows
    WHERE resumable_request_rows.pay_batch_id = p_pay_batch_id
      AND resumable_request_rows.correction_kind = 'PRE_BANK_CANCEL'
      AND resumable_request_rows.status = 'APPLIED_WITH_BLOCKERS'
      AND UPPER(BTRIM(COALESCE(resumable_request_rows.selection_json->>'scope_type', ''))) IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH')
      AND EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS resumable_applied_items
        WHERE resumable_applied_items.correction_request_id = resumable_request_rows.id
          AND resumable_applied_items.work_kind = 'PRE_BANK_CANCEL'
          AND resumable_applied_items.status = 'APPLIED'
      )
      AND EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS resumable_blocked_items
        WHERE resumable_blocked_items.correction_request_id = resumable_request_rows.id
          AND resumable_blocked_items.work_kind = 'PRE_BANK_CANCEL'
          AND resumable_blocked_items.status = 'BLOCKED'
          AND COALESCE(
            resumable_blocked_items.result_json#>>'{blocker,code}',
            resumable_blocked_items.result_json->>'error_code',
            ''
          ) = 'PRE_BANK_CANCEL_CLASSIFICATION_REQUIRED'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS resumable_invalid_items
        WHERE resumable_invalid_items.correction_request_id = resumable_request_rows.id
          AND resumable_invalid_items.status NOT IN ('APPLIED', 'BLOCKED')
      )
    ORDER BY resumable_request_rows.created_at_utc DESC, resumable_request_rows.id
    LIMIT 1
    FOR UPDATE;

    v_diagnostic_json := public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      v_existing_request.selection_json,
      p_actor_user_id,
      'CANCEL_WHOLE_BATCH_ACTION'
    );

    WITH original_expected_raw AS (
      SELECT original_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(v_existing_request.selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
            THEN v_existing_request.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS original_values(raw_value)
    ),
    original_expected AS (
      SELECT DISTINCT
        original_expected_raw.raw_value,
        CASE
          WHEN original_expected_raw.raw_value ~* v_uuid_regex
            THEN original_expected_raw.raw_value::uuid
          ELSE NULL::uuid
        END AS pay_batch_item_id
      FROM original_expected_raw
    ),
    original_expected_valid AS (
      SELECT original_expected.pay_batch_item_id
      FROM original_expected
      WHERE original_expected.pay_batch_item_id IS NOT NULL
    ),
    original_item_state AS (
      SELECT
        original_expected_valid.pay_batch_item_id,
        batch_items.id IS NOT NULL
          AND batch_candidates.pay_batch_id = p_pay_batch_id AS belongs_to_batch,
        COALESCE(batch_items.is_voided, false) AS is_voided,
        EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS same_request_correction_items
          WHERE same_request_correction_items.correction_request_id = v_existing_request.id
            AND same_request_correction_items.pay_batch_item_id = original_expected_valid.pay_batch_item_id
            AND same_request_correction_items.correction_item_kind = 'PRE_BANK_CANCEL'
            AND same_request_correction_items.status = 'APPLIED'
        ) AS voided_by_same_request,
        EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS any_applied_correction_items
          WHERE any_applied_correction_items.pay_batch_item_id = original_expected_valid.pay_batch_item_id
            AND any_applied_correction_items.status = 'APPLIED'
        ) AS has_any_applied_correction
      FROM original_expected_valid
      LEFT JOIN public.pay_batch_items AS batch_items
        ON batch_items.id = original_expected_valid.pay_batch_item_id
      LEFT JOIN public.pay_batch_candidates AS batch_candidates
        ON batch_candidates.id = batch_items.pay_batch_candidate_id
    )
    SELECT
      jsonb_array_length(
        CASE
          WHEN COALESCE(jsonb_typeof(v_existing_request.selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
            THEN v_existing_request.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      )::integer,
      (SELECT count(*)::integer FROM original_expected_valid),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch AND NOT original_item_state.is_voided),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch AND original_item_state.is_voided AND original_item_state.voided_by_same_request),
      (
        SELECT count(*)::integer
        FROM original_item_state
        WHERE original_item_state.belongs_to_batch
          AND NOT (
            (
              NOT original_item_state.is_voided
              AND NOT original_item_state.has_any_applied_correction
            )
            OR (
              original_item_state.is_voided
              AND original_item_state.voided_by_same_request
            )
          )
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_batch_items AS active_outside_items
        JOIN public.pay_batch_candidates AS active_outside_candidates
          ON active_outside_candidates.id = active_outside_items.pay_batch_candidate_id
        WHERE active_outside_candidates.pay_batch_id = p_pay_batch_id
          AND COALESCE(active_outside_items.is_voided, false) = false
          AND NOT EXISTS (
            SELECT 1
            FROM original_expected_valid
            WHERE original_expected_valid.pay_batch_item_id = active_outside_items.id
          )
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_payment_correction_work_items AS applied_request_items
        WHERE applied_request_items.correction_request_id = v_existing_request.id
          AND applied_request_items.work_kind = 'PRE_BANK_CANCEL'
          AND applied_request_items.status = 'APPLIED'
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_payment_correction_work_items AS blocked_request_items
        WHERE blocked_request_items.correction_request_id = v_existing_request.id
          AND blocked_request_items.work_kind = 'PRE_BANK_CANCEL'
          AND blocked_request_items.status = 'BLOCKED'
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_payment_correction_work_items AS invalid_blocked_request_items
        WHERE invalid_blocked_request_items.correction_request_id = v_existing_request.id
          AND invalid_blocked_request_items.status = 'BLOCKED'
          AND COALESCE(
            invalid_blocked_request_items.result_json#>>'{blocker,code}',
            invalid_blocked_request_items.result_json->>'error_code',
            ''
          ) <> 'PRE_BANK_CANCEL_CLASSIFICATION_REQUIRED'
      )
    INTO
      v_resume_expected_json_count,
      v_resume_expected_valid_count,
      v_resume_expected_belongs_count,
      v_resume_expected_active_count,
      v_resume_expected_same_request_voided_count,
      v_resume_expected_disallowed_state_count,
      v_resume_active_outside_original_count,
      v_resume_applied_work_item_count,
      v_resume_blocked_work_item_count,
      v_resume_invalid_blocked_work_item_count;

    v_resume_existing_request := (
      v_existing_request.requested_by_user_id = p_actor_user_id
      AND COALESCE(v_existing_request.selection_json->>'correction_kind', 'PRE_BANK_CANCEL') = 'PRE_BANK_CANCEL'
      AND COALESCE(v_diagnostic_json->>'payment_lifecycle_state', '') IN (
        'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION',
        'CANCELLED_BEFORE_BANK_SUBMISSION'
      )
      AND COALESCE(jsonb_array_length(COALESCE(v_diagnostic_json->'blockers', '[]'::jsonb)), 0) = 0
      AND COALESCE(jsonb_array_length(COALESCE(v_diagnostic_json->'race_or_submission_blockers', '[]'::jsonb)), 0) = 0
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{blocking_paid_evidence_json,has_paid_or_settled}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{pending_provider_evidence_json,has_provider_pending}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_outcome_unknown_evidence_json,has_provider_unknown}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(v_diagnostic_json#>>'{provider_evidence_summary_json,evidence_class}', '') = 'NO_PROVIDER_EVIDENCE'
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_evidence_summary_json,provider_submitted}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_evidence_summary_json,provider_request_sent}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_evidence_summary_json,provider_response_present}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_evidence_summary_json,provider_event_present}', '')::boolean, false) IS NOT TRUE
      AND COALESCE(NULLIF(v_diagnostic_json#>>'{provider_evidence_summary_json,provider_external_id_present}', '')::boolean, false) IS NOT TRUE
      AND v_resume_expected_json_count > 0
      AND v_resume_expected_valid_count = v_resume_expected_json_count
      AND v_resume_expected_belongs_count = v_resume_expected_json_count
      AND v_resume_expected_active_count > 0
      AND v_resume_expected_same_request_voided_count > 0
      AND v_resume_expected_active_count + v_resume_expected_same_request_voided_count = v_resume_expected_json_count
      AND v_resume_expected_disallowed_state_count = 0
      AND v_resume_active_outside_original_count = 0
      AND v_resume_applied_work_item_count > 0
      AND v_resume_blocked_work_item_count > 0
      AND v_resume_invalid_blocked_work_item_count = 0
    );

    IF v_resume_existing_request THEN
      v_selection_json := v_existing_request.selection_json;
      v_reason := COALESCE(v_reason, v_existing_request.reason);
      v_scope_type := 'BATCH';
    END IF;
  END IF;

  IF NOT v_resume_existing_request THEN
  v_diagnostic_json := public.pay_payment_cancelability_diagnostic(
    p_pay_batch_id,
    v_selection_json,
    p_actor_user_id,
    CASE
      WHEN v_scope_type IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH') THEN 'CANCEL_WHOLE_BATCH_ACTION'
      ELSE 'CANCEL_PAYMENT_ACTION'
    END
  );
  END IF;

  v_lifecycle_state := v_diagnostic_json ->> 'payment_lifecycle_state';
  v_recommended_action := v_diagnostic_json ->> 'recommended_action';
  v_blockers := COALESCE(v_diagnostic_json -> 'blockers', '[]'::jsonb);
  v_race_blockers := COALESCE(v_diagnostic_json -> 'race_or_submission_blockers', '[]'::jsonb);
  v_resolved_scope_json := COALESCE(v_diagnostic_json -> 'resolved_full_payment_scope_json', '{}'::jsonb);
  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');

  IF (
    NOT v_resume_existing_request
    AND (
      v_lifecycle_state NOT IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
      OR v_recommended_action IS DISTINCT FROM 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
    )
  ) OR (
    v_resume_existing_request
    AND v_lifecycle_state NOT IN (
      'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION',
      'CANCELLED_BEFORE_BANK_SUBMISSION'
    )
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_NOT_AVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'payment_lifecycle_state', v_lifecycle_state,
              'recommended_action', v_recommended_action,
              'diagnostic_json', v_diagnostic_json
            )::text;
  END IF;

  IF COALESCE(jsonb_array_length(v_blockers), 0) > 0 OR COALESCE(jsonb_array_length(v_race_blockers), 0) > 0 THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BLOCKED',
              'pay_batch_id', p_pay_batch_id::text,
              'blockers', v_blockers,
              'race_or_submission_blockers', v_race_blockers
            )::text;
  END IF;

  IF v_resume_existing_request THEN
    v_effective_selection_json := v_existing_request.selection_json;
    v_selection_hash := v_existing_request.selection_hash;
    v_plan_json := v_existing_request.plan_json;
    v_plan_hash := v_existing_request.plan_hash;
    v_accepted_resolution_json := COALESCE(v_existing_request.accepted_resolution_json, '{}'::jsonb);
    v_accepted_resolution_hash := v_existing_request.accepted_resolution_hash;
    v_required_quantity := GREATEST(COALESCE(v_existing_request.required_quantity, 1), 1);
    v_idempotency_key := COALESCE(
      NULLIF(BTRIM(COALESCE(v_existing_request.plan_json->>'idempotency_key', '')), ''),
      NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''),
      md5(jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'correction_request_id', v_existing_request.id::text,
        'action', 'RESUME_PRE_PROVIDER_CANCEL_AND_RECALCULATE'
      )::text)
    );
  ELSE
  v_effective_selection_json := v_selection_json
    || jsonb_build_object(
      'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
      'correction_kind', 'PRE_BANK_CANCEL',
      'scope_type', v_scope_type,
      'work_unit', CASE
        WHEN v_scope_type IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH') THEN 'BATCH'
        WHEN jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0 THEN 'TRANSFER'
        ELSE 'CANDIDATE'
      END,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'expected_pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)
    )
    || jsonb_build_object(
      'candidate_ids', COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb),
      'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb)
    );

  v_selection_hash := md5(v_effective_selection_json::text);
  v_idempotency_key := COALESCE(NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''), md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', v_selection_hash,
    'action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
    'actor_user_id', p_actor_user_id::text
  )::text));

  SELECT GREATEST(COALESCE(settings_row.payment_authoriser_quantity, 1), 1)
  INTO v_required_quantity
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_required_quantity := GREATEST(COALESCE(v_required_quantity, 1), 1);

  v_plan_json := jsonb_build_object(
    'classification', v_lifecycle_state,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', COALESCE(v_diagnostic_json -> 'finance_scope_json', '{}'::jsonb),
    'provider_evidence', COALESCE(v_diagnostic_json -> 'provider_evidence_summary_json', '{}'::jsonb),
    'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'work_expansion_plan', jsonb_build_object(
      'work_unit',
      CASE
        WHEN v_scope_type IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH') THEN 'BATCH'
        WHEN jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0 THEN 'TRANSFER'
        ELSE 'CANDIDATE_PAYEE'
      END,
      'chunk_size',
      50
    ),
    'idempotency_key', v_idempotency_key
  );

  v_plan_hash := md5(v_plan_json::text);

  v_accepted_resolution_json := jsonb_build_object(
    'accepted_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
    'accepted_at_utc', now(),
    'accepted_by_user_id', p_actor_user_id::text,
    'reason', v_reason,
    'confirmation_json', v_confirmation_json,
    'diagnostic_json', v_diagnostic_json,
    'idempotency_key', v_idempotency_key
  );

  v_accepted_resolution_hash := md5(v_accepted_resolution_json::text);
  END IF;

  SELECT request_rows.*
  INTO v_existing_request
  FROM public.pay_payment_correction_requests AS request_rows
  WHERE request_rows.pay_batch_id = p_pay_batch_id
    AND request_rows.selection_hash = v_selection_hash
    AND request_rows.correction_kind = 'PRE_BANK_CANCEL'
    AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING', 'APPLIED_WITH_BLOCKERS')
  ORDER BY request_rows.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    IF v_resume_existing_request THEN
      UPDATE public.pay_payment_correction_work_items AS resumable_blocked_items
      SET
        status = 'PENDING',
        processed_at_utc = NULL,
        processed_by_user_id = NULL,
        locked_at_utc = NULL,
        locked_by = NULL,
        last_error = NULL,
        result_json = (
          COALESCE(resumable_blocked_items.result_json, '{}'::jsonb)
          - 'blocker'
          - 'classification_result'
          - 'error_message'
          - 'sqlstate'
          - 'failed_at_utc'
          - 'status'
          - 'ok'
        ) || jsonb_build_object(
          'resumed_same_request_pre_bank_cancel', true,
          'resumed_at_utc', now(),
          'resumed_by_user_id', p_actor_user_id::text,
          'resume_reason', 'SAFE_SAME_REQUEST_PARTIAL_PRE_BANK_CANCEL_CONTINUATION'
        )
      WHERE resumable_blocked_items.correction_request_id = v_existing_request.id
        AND resumable_blocked_items.work_kind = 'PRE_BANK_CANCEL'
        AND resumable_blocked_items.status = 'BLOCKED'
        AND COALESCE(
          resumable_blocked_items.result_json#>>'{blocker,code}',
          resumable_blocked_items.result_json->>'error_code',
          ''
        ) = 'PRE_BANK_CANCEL_CLASSIFICATION_REQUIRED';

      GET DIAGNOSTICS v_resume_blocked_reset_count = ROW_COUNT;

      IF v_resume_blocked_reset_count <= 0 THEN
        RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_RESUME_WORK_NOT_FOUND'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_RESUME_WORK_NOT_FOUND',
                  'pay_batch_id', p_pay_batch_id::text,
                  'correction_request_id', v_existing_request.id::text
                )::text;
      END IF;

      UPDATE public.pay_payment_correction_requests AS request_to_resume
      SET
        status = 'EXPANDED',
        applied_at_utc = NULL,
        approved_count = GREATEST(COALESCE(request_to_resume.approved_count, 0), COALESCE(request_to_resume.required_quantity, v_required_quantity, 1)),
        authorised_at_utc = COALESCE(request_to_resume.authorised_at_utc, now()),
        updated_at_utc = now()
      WHERE request_to_resume.id = v_existing_request.id
      RETURNING request_to_resume.*
      INTO v_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_request.id,
        p_pay_batch_id,
        'USER',
        p_actor_user_id,
        'RETRY',
        now(),
        'Resume the remaining frozen scope of the same whole-batch pre-bank cancellation request.',
        to_jsonb(v_existing_request),
        to_jsonb(v_request),
        jsonb_build_object(
          'resume_reason', 'SAFE_SAME_REQUEST_PARTIAL_PRE_BANK_CANCEL_CONTINUATION',
          'resume_blocked_work_item_count', v_resume_blocked_reset_count,
          'expected_item_count', v_resume_expected_json_count,
          'active_expected_item_count', v_resume_expected_active_count,
          'same_request_voided_item_count', v_resume_expected_same_request_voided_count,
          'applied_work_item_count', v_resume_applied_work_item_count,
          'blocked_work_item_count', v_resume_blocked_work_item_count
        )
      );
    ELSE
      UPDATE public.pay_payment_correction_requests AS request_to_authorise
      SET status = CASE WHEN request_to_authorise.status IN ('REQUESTED', 'AWAITING_AUTHORISATION') THEN 'AUTHORISED' ELSE request_to_authorise.status END,
          approved_count = GREATEST(COALESCE(request_to_authorise.approved_count, 0), COALESCE(request_to_authorise.required_quantity, v_required_quantity, 1)),
          authorised_at_utc = COALESCE(request_to_authorise.authorised_at_utc, now()),
          accepted_resolution_json = COALESCE(request_to_authorise.accepted_resolution_json, v_accepted_resolution_json),
          accepted_resolution_hash = COALESCE(request_to_authorise.accepted_resolution_hash, v_accepted_resolution_hash),
          updated_at_utc = now()
      WHERE request_to_authorise.id = v_existing_request.id
      RETURNING request_to_authorise.*
      INTO v_request;
    END IF;
  ELSE
    BEGIN
      INSERT INTO public.pay_payment_correction_requests (
        pay_batch_id,
        correction_kind,
        status,
        requested_by_user_id,
        requested_at_utc,
        required_quantity,
        approved_count,
        golden_key_used,
        golden_key_user_id,
        reason,
        selection_json,
        selection_hash,
        plan_json,
        plan_hash,
        accepted_resolution_json,
        accepted_resolution_hash,
        source_bank_event_id,
        auto_requested,
        created_at_utc,
        authorised_at_utc,
        applied_at_utc,
        cancelled_at_utc,
        updated_at_utc
      )
      VALUES (
        p_pay_batch_id,
        'PRE_BANK_CANCEL',
        'AUTHORISED',
        p_actor_user_id,
        now(),
        v_required_quantity,
        v_required_quantity,
        false,
        NULL::uuid,
        v_reason,
        v_effective_selection_json,
        v_selection_hash,
        v_plan_json,
        v_plan_hash,
        v_accepted_resolution_json,
        v_accepted_resolution_hash,
        NULL::uuid,
        false,
        now(),
        now(),
        NULL::timestamptz,
        NULL::timestamptz,
        now()
      )
      RETURNING public.pay_payment_correction_requests.*
      INTO v_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_request.id,
        p_pay_batch_id,
        'USER',
        p_actor_user_id,
        'REQUEST',
        now(),
        v_reason,
        NULL::jsonb,
        to_jsonb(v_request),
        jsonb_build_object(
          'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
          'correction_kind', 'PRE_BANK_CANCEL',
          'selection_hash', v_selection_hash,
          'idempotency_key', v_idempotency_key
        )
      );
    EXCEPTION WHEN unique_violation THEN
      SELECT request_rows.*
      INTO v_request
      FROM public.pay_payment_correction_requests AS request_rows
      WHERE request_rows.pay_batch_id = p_pay_batch_id
        AND request_rows.selection_hash = v_selection_hash
        AND request_rows.correction_kind = 'PRE_BANK_CANCEL'
        AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING', 'APPLIED_WITH_BLOCKERS')
      ORDER BY request_rows.created_at_utc
      LIMIT 1
      FOR UPDATE;
    END;
  END IF;

  v_expand_result := public.pay_payment_correction_expand_work(v_request.id, p_actor_user_id);
  v_process_result := public.pay_payment_correction_process_chunk(v_request.id, 50, 'cancel-not-sent-recalculate', p_actor_user_id);
  v_grouped_alert_updates := COALESCE(v_process_result -> 'grouped_alert_updates', '[]'::jsonb);
  v_is_complete := COALESCE((v_process_result ->> 'complete')::boolean, false);

  v_process_total := COALESCE(NULLIF(v_process_result #>> '{totals,total}', '')::integer, NULLIF(v_process_result ->> 'progress_total', '')::integer, 0);
  v_process_applied := COALESCE(NULLIF(v_process_result #>> '{totals,applied}', '')::integer, NULLIF(v_process_result ->> 'applied', '')::integer, 0);
  v_process_skipped := COALESCE(NULLIF(v_process_result #>> '{totals,skipped}', '')::integer, NULLIF(v_process_result ->> 'skipped', '')::integer, 0);
  v_process_blocked := COALESCE(NULLIF(v_process_result #>> '{totals,blocked}', '')::integer, NULLIF(v_process_result ->> 'blocked', '')::integer, 0);
  v_process_failed_retryable := COALESCE(NULLIF(v_process_result #>> '{totals,failed_retryable}', '')::integer, NULLIF(v_process_result ->> 'failed_retryable', '')::integer, 0);
  v_process_failed_final := COALESCE(NULLIF(v_process_result #>> '{totals,failed_final}', '')::integer, NULLIF(v_process_result ->> 'failed_final', '')::integer, 0);
  v_process_pending := COALESCE(NULLIF(v_process_result #>> '{totals,pending}', '')::integer, NULLIF(v_process_result ->> 'pending', '')::integer, 0);
  v_process_processing := COALESCE(NULLIF(v_process_result #>> '{totals,processing}', '')::integer, NULLIF(v_process_result ->> 'processing', '')::integer, 0);
  v_process_cancelled := COALESCE(NULLIF(v_process_result #>> '{totals,cancelled}', '')::integer, NULLIF(v_process_result ->> 'cancelled', '')::integer, 0);
  v_process_parent_status := UPPER(NULLIF(BTRIM(COALESCE(v_process_result ->> 'parent_status', '')), ''));

  SELECT jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'change_kind', 'PRE_BANK_CANCEL',
    'changed_pay_batch_item_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.pay_batch_item_id::text ORDER BY applied_scope_item.pay_batch_item_id::text)
        FILTER (WHERE applied_scope_item.pay_batch_item_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_pay_batch_candidate_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.pay_batch_candidate_id::text ORDER BY applied_scope_item.pay_batch_candidate_id::text)
        FILTER (WHERE applied_scope_item.pay_batch_candidate_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_candidate_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.candidate_id::text ORDER BY applied_scope_item.candidate_id::text)
        FILTER (WHERE applied_scope_item.candidate_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_transfer_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.pay_bank_transfer_id::text ORDER BY applied_scope_item.pay_bank_transfer_id::text)
        FILTER (WHERE applied_scope_item.pay_bank_transfer_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_finance_case_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.finance_case_id::text ORDER BY applied_scope_item.finance_case_id::text)
        FILTER (WHERE applied_scope_item.finance_case_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_finance_component_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.finance_component_id::text ORDER BY applied_scope_item.finance_component_id::text)
        FILTER (WHERE applied_scope_item.finance_component_id IS NOT NULL),
      '[]'::jsonb
    ),
    'changed_reservation_ids', COALESCE(
      jsonb_agg(DISTINCT applied_scope_item.reservation_id::text ORDER BY applied_scope_item.reservation_id::text)
        FILTER (WHERE applied_scope_item.reservation_id IS NOT NULL),
      '[]'::jsonb
    ),
    'applied_correction_item_count', count(*)::integer
  )
  INTO v_request_changed_scope_json
  FROM public.pay_payment_correction_items AS applied_scope_item
  WHERE applied_scope_item.correction_request_id = v_request.id
    AND applied_scope_item.correction_item_kind = 'PRE_BANK_CANCEL'
    AND applied_scope_item.status = 'APPLIED';

  v_request_changed_scope_json := COALESCE(v_request_changed_scope_json, jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'change_kind', 'PRE_BANK_CANCEL',
    'changed_pay_batch_item_ids', '[]'::jsonb,
    'changed_pay_batch_candidate_ids', '[]'::jsonb,
    'changed_candidate_ids', '[]'::jsonb,
    'changed_transfer_ids', '[]'::jsonb,
    'changed_finance_case_ids', '[]'::jsonb,
    'changed_finance_component_ids', '[]'::jsonb,
    'changed_reservation_ids', '[]'::jsonb,
    'applied_correction_item_count', 0
  ));

  v_process_voided_item_count := COALESCE(
    jsonb_array_length(
      CASE
        WHEN COALESCE(jsonb_typeof(v_request_changed_scope_json->'changed_pay_batch_item_ids'), 'null') = 'array'
          THEN v_request_changed_scope_json->'changed_pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ),
    0
  );

  v_process_failed := (
    COALESCE((v_process_result ->> 'ok')::boolean, true) IS NOT TRUE
    OR COALESCE(v_process_failed_final, 0) > 0
    OR COALESCE(v_process_failed_retryable, 0) > 0
    OR COALESCE(v_process_blocked, 0) > 0
    OR v_process_parent_status IN ('FAILED', 'BLOCKED', 'APPLIED_WITH_BLOCKERS')
    OR (
      COALESCE(v_process_total, 0) > 0
      AND COALESCE(v_is_complete, false) = true
      AND COALESCE(v_process_applied, 0) + COALESCE(v_process_skipped, 0) + COALESCE(v_process_cancelled, 0) <= 0
    )
  );

  v_process_error_code := CASE
    WHEN COALESCE(v_process_failed_final, 0) > 0 OR v_process_parent_status = 'FAILED' THEN 'PAY_PAYMENT_CANCEL_NOT_SENT_PROCESS_FAILED'
    WHEN COALESCE(v_process_failed_retryable, 0) > 0 THEN 'PAY_PAYMENT_CANCEL_NOT_SENT_PROCESS_RETRYABLE'
    WHEN COALESCE(v_process_blocked, 0) > 0 OR v_process_parent_status IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS') THEN 'PAY_PAYMENT_CANCEL_NOT_SENT_PROCESS_BLOCKED'
    WHEN COALESCE(v_process_failed, false) THEN 'PAY_PAYMENT_CANCEL_NOT_SENT_NOT_APPLIED'
    ELSE NULL::text
  END;

  v_process_error_message := CASE
    WHEN COALESCE(v_process_failed_final, 0) > 0 OR v_process_parent_status = 'FAILED' THEN 'Cancel Draft Batch could not be completed because the cancellation work item failed.'
    WHEN COALESCE(v_process_failed_retryable, 0) > 0 THEN 'Cancel Draft Batch could not be completed because the cancellation work item needs to be retried.'
    WHEN COALESCE(v_process_blocked, 0) > 0 OR v_process_parent_status IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS') THEN 'Cancel Draft Batch could not be completed because the cancellation work item was blocked.'
    WHEN COALESCE(v_process_failed, false) THEN 'Cancel Draft Batch could not be completed because no cancellation work item was applied.'
    ELSE NULL::text
  END;

  v_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id,
    'PAYMENT_CANCEL_NOT_SENT_AND_RECALCULATE',
    'pay_payment_cancel_not_sent_and_recalculate',
    COALESCE(v_request_changed_scope_json, '{}'::jsonb) || jsonb_build_object(
      'correction_request_id', v_request.id::text,
      'selection_hash', v_selection_hash,
      'payment_lifecycle_state', v_lifecycle_state,
      'resumed_existing_correction_request', v_resume_existing_request,
      'resume_blocked_work_item_count', v_resume_blocked_reset_count,
      'progress', v_process_result
    ),
    true,
    true,
    COALESCE(jsonb_array_length(v_grouped_alert_updates), 0) > 0,
    true
  );

  IF COALESCE(v_process_failed, false) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', v_process_error_code,
      'code', v_process_error_code,
      'message', v_process_error_message,
      'user_message', v_process_error_message,
      'pay_batch_id', p_pay_batch_id::text,
      'correction_request_id', v_request.id::text,
      'resumed_existing_correction_request', v_resume_existing_request,
      'resume_blocked_work_item_count', v_resume_blocked_reset_count,
      'payment_lifecycle_state', v_lifecycle_state,
      'recommended_action', v_recommended_action,
      'next_step', NULL::text,
      'progress_completed', COALESCE(v_process_applied, 0) + COALESCE(v_process_skipped, 0) + COALESCE(v_process_cancelled, 0),
      'progress_total', COALESCE(v_process_total, 0),
      'is_complete', v_is_complete,
      'voided_transfer_count', COALESCE((v_process_result ->> 'updated_transfer_count')::integer, 0),
      'voided_item_count', COALESCE(v_process_voided_item_count, 0),
      'released_reservation_count', COALESCE((v_process_result ->> 'released_reservations')::integer, 0),
      'restored_finance_component_count', COALESCE((v_process_result ->> 'restored_finance_components')::integer, 0),
      'carry_forward_created_count', COALESCE((v_process_result ->> 'carry_forward_created')::integer, 0),
      'carry_forward_existing_count', COALESCE((v_process_result ->> 'carry_forward_existing')::integer, 0),
      'carry_forward_released_count', COALESCE((v_process_result ->> 'carry_forward_released')::integer, 0),
      'freshness_dirty_result', COALESCE(v_process_result -> 'freshness_dirty_result', '{}'::jsonb),
      'changed_scope_json', COALESCE(v_request_changed_scope_json, '{}'::jsonb),
      'diagnostic_json', v_diagnostic_json,
      'expand_result', v_expand_result,
      'process_result', v_process_result,
      'live_signal', v_signal_result,
      'grouped_alert_summary_impact', v_grouped_alert_updates,
      'failure_summary', jsonb_build_object(
        'parent_status', v_process_parent_status,
        'total', COALESCE(v_process_total, 0),
        'applied', COALESCE(v_process_applied, 0),
        'skipped', COALESCE(v_process_skipped, 0),
        'blocked', COALESCE(v_process_blocked, 0),
        'failed_retryable', COALESCE(v_process_failed_retryable, 0),
        'failed_final', COALESCE(v_process_failed_final, 0),
        'pending', COALESCE(v_process_pending, 0),
        'processing', COALESCE(v_process_processing, 0),
        'cancelled', COALESCE(v_process_cancelled, 0)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'resumed_existing_correction_request', v_resume_existing_request,
    'resume_blocked_work_item_count', v_resume_blocked_reset_count,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'next_step', 'AMEND_TIMESHEET_AND_RECALCULATE',
    'progress_completed', COALESCE((v_process_result -> 'totals' ->> 'applied')::integer, COALESCE((v_process_result ->> 'applied')::integer, 0)),
    'progress_total', COALESCE((v_process_result -> 'totals' ->> 'total')::integer, 0),
    'is_complete', v_is_complete,
    'voided_transfer_count', COALESCE((v_process_result ->> 'updated_transfer_count')::integer, 0),
    'voided_item_count', COALESCE(v_process_voided_item_count, 0),
    'released_reservation_count', COALESCE((v_process_result ->> 'released_reservations')::integer, 0),
    'restored_finance_component_count', COALESCE((v_process_result ->> 'restored_finance_components')::integer, 0),
    'carry_forward_created_count', COALESCE((v_process_result ->> 'carry_forward_created')::integer, 0),
    'carry_forward_existing_count', COALESCE((v_process_result ->> 'carry_forward_existing')::integer, 0),
    'carry_forward_released_count', COALESCE((v_process_result ->> 'carry_forward_released')::integer, 0),
    'freshness_dirty_result', COALESCE(v_process_result -> 'freshness_dirty_result', '{}'::jsonb),
    'changed_scope_json', COALESCE(v_request_changed_scope_json, '{}'::jsonb),
    'diagnostic_json', v_diagnostic_json,
    'expand_result', v_expand_result,
    'process_result', v_process_result,
    'live_signal', v_signal_result,
    'grouped_alert_summary_impact', v_grouped_alert_updates
  );
END;
$function$;

-- pay_payment_cancelability_diagnostic(uuid,jsonb,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_payment_cancelability_diagnostic(p_pay_batch_id uuid, p_selection_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_diagnostic_context text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_batch public.pay_batches%ROWTYPE;
  v_selection_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_scope_type text := NULL::text;
  v_scope_is_full boolean := true;
  v_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_provider_evidence_class text := 'NO_PROVIDER_EVIDENCE';
  v_provider_submitted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_response_present boolean := false;
  v_provider_event_present boolean := false;
  v_provider_external_id_present boolean := false;
  v_local_prepared_only boolean := true;
  v_provider_cash_state text := NULL::text;
  v_provider_blocker_code text := NULL::text;
  v_provider_reason text := NULL::text;
  v_provider_support_details_json jsonb := '{}'::jsonb;
  v_transfer_count integer := 0;
  v_transfer_final_count integer := 0;
  v_transfer_terminal_no_money_count integer := 0;
  v_transfer_pending_count integer := 0;
  v_event_count integer := 0;
  v_event_final_count integer := 0;
  v_event_terminal_no_money_count integer := 0;
  v_event_pending_count integer := 0;
  v_event_unknown_count integer := 0;
  v_provider_webhook_evidence_count integer := 0;
  v_invalid_webhook_evidence_count integer := 0;
  v_failed_webhook_replay_evidence_count integer := 0;
  v_provider_poll_evidence_count integer := 0;
  v_provider_outage_count integer := 0;
  v_pre_bank_applied_count integer := 0;
  v_no_money_applied_count integer := 0;
  v_open_provider_submit_count integer := 0;
  v_manual_adjustment_result jsonb := '{}'::jsonb;
  v_freshness_result jsonb := '{}'::jsonb;
  v_manual_carry_forward_required boolean := false;
  v_can_carry_forward_automatically boolean := true;
  v_manual_carry_forward_blocker_count integer := 0;
  v_freshness_blocker_count integer := 0;
  v_partial_scope_blocker_count integer := 0;
  v_final_evidence_count integer := 0;
  v_terminal_no_money_count integer := 0;
  v_pending_provider_count integer := 0;
  v_unknown_provider_count integer := 0;
  v_has_paid_or_settled boolean := false;
  v_has_provider_unknown boolean := false;
  v_has_provider_pending boolean := false;
  v_has_provider_outage boolean := false;
  v_has_terminal_no_money boolean := false;
  v_is_local_not_sent boolean := false;
  v_lifecycle_state text := 'PROVIDER_OUTCOME_UNKNOWN';
  v_lifecycle_label text := 'Provider outcome unknown — check provider';
  v_recommended_action text := 'CHECK_PROVIDER_STATUS';
  v_can_pre_provider_cancel boolean := false;
  v_can_no_money_unwind boolean := false;
  v_can_recover_overpayment boolean := false;
  v_requires_provider_cancel boolean := false;
  v_requires_bank_check boolean := false;
  v_requires_retry_later boolean := false;
  v_whole_batch_cancel_available boolean := false;
  v_row_cancel_available boolean := false;
  v_retry_same_batch_safe boolean := false;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_race_or_submission_blockers jsonb := '[]'::jsonb;
  v_provider_evidence_summary_json jsonb := '{}'::jsonb;
  v_blocking_paid_evidence_json jsonb := '{}'::jsonb;
  v_terminal_no_money_evidence_json jsonb := '{}'::jsonb;
  v_pending_provider_evidence_json jsonb := '{}'::jsonb;
  v_provider_outcome_unknown_evidence_json jsonb := '{}'::jsonb;
  v_provider_webhook_evidence_json jsonb := '{}'::jsonb;
  v_finance_scope_json jsonb := '{}'::jsonb;
  v_support_details_json jsonb := '{}'::jsonb;
  v_provider_failure_reason_code text := NULL::text;
  v_provider_failure_reason_group text := NULL::text;
  v_provider_failure_reason_label text := NULL::text;
  v_provider_failure_reason_result jsonb := '{}'::jsonb;
  v_failure_event_provider_key text := NULL::text;
  v_failure_event_state text := NULL::text;
  v_failure_event_reason_code text := NULL::text;
  v_failure_event_reason_text text := NULL::text;
  v_failure_event_payload jsonb := '{}'::jsonb;
  v_alert_candidate_kind text := NULL::text;
  v_alert_candidate_severity text := NULL::text;
  v_alert_candidate_is_success_only boolean := false;
  v_paid_recovery_required boolean := false;
  v_has_actual_recovery_context boolean := false;
  v_status_update_signature text := NULL::text;
  v_result jsonb := '{}'::jsonb;
  v_actor_valid boolean := true;
  v_batch_terminal boolean := false;
  v_diagnostic_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_diagnostic_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_REQUIRED')::text;
  END IF;


  IF v_diagnostic_context IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_REQUIRED',
              'message', 'pay_payment_cancelability_diagnostic requires an explicit diagnostic/action context.'
            )::text;
  END IF;

  IF v_diagnostic_context IN (
    'LIST',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'PAY_BATCH_GET',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'PREVIEW_OPEN',
    'PREVIEW_PROGRESS',
    'WORKBENCH_OPEN',
    'WORKBENCH_PROGRESS',
    'OPERATION_GET',
    'OPERATION_WORKER',
    'OPERATION_WORKER_PROOF',
    'OPERATION_PROGRESS',
    'PROGRESS_POLLING',
    'LIVE_WATCH',
    'WATCH_SIGNAL',
    'RPC_CHANGES_PING'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_ALLOWED',
              'context', v_diagnostic_context,
              'message', 'Cancelability diagnostics are blocked from list, bootstrap, Overview, preview, operation progress, operation GET, and worker proof paths.'
            )::text;
  END IF;

  IF v_diagnostic_context NOT IN (
    'CURRENT_PAYMENT_STATUS',
    'CURRENT_PAYMENT_STATUS_TAB',
    'PAYMENT_STATUS_TAB',
    'PAYMENT_ISSUES_TAB',
    'PAYMENT_ISSUE_REVIEW',
    'CANCELLATION_ACTION',
    'CANCEL_PAYMENT_ACTION',
    'CANCEL_WHOLE_BATCH_ACTION',
    'CORRECTION_REVIEW',
    'CORRECTION_ACTION',
    'PAYMENT_CORRECTION_PLAN',
    'USER_TRIGGERED_DIAGNOSTIC',
    'EXPLICIT_DIAGNOSTIC'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT',
              'context', v_diagnostic_context,
              'message', 'Cancelability diagnostics are only allowed from explicit Current Payment Status, cancellation, correction, or user-triggered diagnostic flows.'
            )::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_paid_recovery_required := (
    lower(NULLIF(btrim(COALESCE(v_selection_json->>'recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR lower(NULLIF(btrim(COALESCE(v_selection_json->>'paid_recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR lower(NULLIF(btrim(COALESCE(v_selection_json->>'payment_recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR upper(NULLIF(btrim(COALESCE(v_selection_json->>'requested_action', '')), '')) = 'AMEND_AND_RECOVER_OVERPAYMENT'
    OR upper(NULLIF(btrim(COALESCE(v_selection_json->>'source_context', '')), '')) = 'PAID_RECOVERY_REQUIRED'
  );

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_batch_terminal := upper(btrim(COALESCE(v_batch.status, ''))) IN (
    'COMMITTED', 'COMPLETED', 'PAID', 'SETTLED', 'CANCELLED', 'CANCELED'
  );

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_valid;

    IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  v_resolved_scope_json := public._pay_resolve_payment_scope_for_cancel_rewind(
    p_pay_batch_id,
    v_selection_json,
    false,
    p_actor_user_id
  );

  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');
  v_scope_is_full := COALESCE((v_resolved_scope_json ->> 'is_full_scope')::boolean, true);

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_bank_transfer_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_candidate_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT provider_evidence.evidence_class,
         provider_evidence.provider_submitted,
         provider_evidence.provider_request_sent,
         provider_evidence.provider_response_present,
         provider_evidence.provider_event_present,
         provider_evidence.provider_external_id_present,
         provider_evidence.local_prepared_only,
         provider_evidence.cash_state,
         provider_evidence.blocker_code,
         provider_evidence.reason,
         provider_evidence.support_details_json
  INTO v_provider_evidence_class,
       v_provider_submitted,
       v_provider_request_sent,
       v_provider_response_present,
       v_provider_event_present,
       v_provider_external_id_present,
       v_local_prepared_only,
       v_provider_cash_state,
       v_provider_blocker_code,
       v_provider_reason,
       v_provider_support_details_json
  FROM public._pay_bank_transfer_provider_evidence_classify(
    p_pay_batch_id,
    NULL::uuid,
    v_resolved_scope_json,
    NULL::uuid
  ) AS provider_evidence
  LIMIT 1;

  v_provider_evidence_class := COALESCE(v_provider_evidence_class, 'NO_PROVIDER_EVIDENCE');
  v_provider_submitted := COALESCE(v_provider_submitted, false);
  v_provider_request_sent := COALESCE(v_provider_request_sent, false);
  v_provider_response_present := COALESCE(v_provider_response_present, false);
  v_provider_event_present := COALESCE(v_provider_event_present, false);
  v_provider_external_id_present := COALESCE(v_provider_external_id_present, false);
  v_local_prepared_only := COALESCE(v_local_prepared_only, true);
  v_provider_support_details_json := COALESCE(v_provider_support_details_json, '{}'::jsonb);

  v_manual_adjustment_result := public._pay_detect_manual_adjustments_for_carry_forward(
    p_pay_batch_id,
    v_resolved_scope_json,
    p_actor_user_id
  );

  v_freshness_result := public._pay_manual_adjustment_carry_forward_freshness_check(
    p_pay_batch_id,
    v_candidate_ids,
    v_pay_batch_item_ids,
    v_resolved_scope_json,
    p_actor_user_id
  );

  v_manual_carry_forward_required := COALESCE((v_manual_adjustment_result ->> 'manual_adjustment_carry_forward_required')::boolean, false);
  v_can_carry_forward_automatically := COALESCE((v_manual_adjustment_result ->> 'can_carry_forward_automatically')::boolean, true);
  v_manual_carry_forward_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb)), 0);
  v_freshness_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_freshness_result -> 'blockers', '[]'::jsonb)), 0);
  v_partial_scope_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_resolved_scope_json -> 'partial_scope_blockers', '[]'::jsonb)), 0);

  WITH scoped_transfers AS (
    SELECT transfer_rows.*
    FROM public.pay_bank_transfers AS transfer_rows
    WHERE transfer_rows.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
        OR transfer_rows.id = ANY(v_pay_bank_transfer_ids)
      )
  ), classified_transfers AS (
    SELECT
      scoped_transfers.id AS pay_bank_transfer_id,
      movement_rows.cash_state,
      movement_rows.is_final_money_moved,
      movement_rows.is_terminal_no_money,
      movement_rows.is_pending_non_final
    FROM scoped_transfers
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      scoped_transfers.status,
      scoped_transfers.rail_state,
      COALESCE(scoped_transfers.rail_meta_json, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', scoped_transfers.rail_provider,
        'rail_env', scoped_transfers.rail_env,
        'request_id', scoped_transfers.request_id,
        'rail_tx_id', scoped_transfers.rail_tx_id
      )
    ) AS movement_rows
  )
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE classified_transfers.is_final_money_moved)::integer,
    count(*) FILTER (WHERE classified_transfers.is_terminal_no_money)::integer,
    count(*) FILTER (WHERE classified_transfers.is_pending_non_final)::integer
  INTO v_transfer_count,
       v_transfer_final_count,
       v_transfer_terminal_no_money_count,
       v_transfer_pending_count
  FROM classified_transfers;

  WITH scoped_events AS (
    SELECT
      event_rows.*,
      receipt_rows.status AS receipt_status,
      receipt_rows.provider_key AS receipt_provider_key,
      receipt_rows.rail_env AS receipt_rail_env,
      receipt_rows.provider_event_key AS receipt_provider_event_key,
      receipt_rows.signature_valid AS receipt_signature_valid
    FROM public.pay_bank_transfer_events AS event_rows
    LEFT JOIN public.bank_provider_webhook_receipts AS receipt_rows
      ON receipt_rows.id = event_rows.provider_webhook_receipt_id
    WHERE event_rows.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
        OR event_rows.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
        OR event_rows.pay_bank_transfer_id IS NULL
      )
  ), classified_events AS (
    SELECT
      scoped_events.id AS event_id,
      scoped_events.provider_event_transport,
      scoped_events.provider_signature_valid,
      scoped_events.provider_webhook_receipt_id,
      scoped_events.receipt_status,
      scoped_events.receipt_provider_key,
      scoped_events.receipt_rail_env,
      scoped_events.receipt_provider_event_key,
      scoped_events.receipt_signature_valid,
      scoped_events.provider_failure_reason_group,
      scoped_events.mapping_status,
      scoped_events.normalised_state,
      scoped_events.provider_state,
      movement_rows.cash_state,
      movement_rows.is_final_money_moved,
      movement_rows.is_terminal_no_money,
      movement_rows.is_pending_non_final
    FROM scoped_events
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      scoped_events.normalised_state,
      scoped_events.provider_state,
      COALESCE(scoped_events.raw_payload, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', scoped_events.provider_key,
        'provider_event_type', scoped_events.provider_event_type,
        'provider_event_transport', scoped_events.provider_event_transport,
        'provider_event_key', scoped_events.provider_event_key
      )
    ) AS movement_rows
  )
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE classified_events.is_final_money_moved)::integer,
    count(*) FILTER (WHERE classified_events.is_terminal_no_money)::integer,
    count(*) FILTER (WHERE classified_events.is_pending_non_final)::integer,
    count(*) FILTER (
      WHERE (
        upper(COALESCE(classified_events.normalised_state, '')) IN ('UNKNOWN', 'OUTCOME_UNKNOWN', 'PROVIDER_UNKNOWN')
        OR upper(COALESCE(classified_events.mapping_status, '')) IN ('UNMATCHED', 'AMBIGUOUS', 'REVIEW_REQUIRED')
        OR upper(COALESCE(classified_events.provider_failure_reason_group, '')) IN ('WEBHOOK_UNMATCHED', 'PROVIDER_UNKNOWN')
      )
      AND upper(COALESCE(classified_events.provider_failure_reason_group, '')) <> 'PROVIDER_OUTAGE'
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND classified_events.provider_signature_valid IS DISTINCT FROM false
        AND classified_events.provider_webhook_receipt_id IS NOT NULL
        AND classified_events.receipt_signature_valid IS TRUE
        AND upper(COALESCE(classified_events.receipt_status, '')) IN ('VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED')
        AND classified_events.receipt_provider_key IS NOT DISTINCT FROM v_batch.rail_provider_snapshot
        AND classified_events.receipt_rail_env IS NOT DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
        AND NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND (
          classified_events.provider_signature_valid IS FALSE
          OR classified_events.provider_webhook_receipt_id IS NULL
          OR classified_events.receipt_signature_valid IS DISTINCT FROM true
          OR upper(COALESCE(classified_events.receipt_status, '')) IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
          OR classified_events.receipt_provider_key IS DISTINCT FROM v_batch.rail_provider_snapshot
          OR classified_events.receipt_rail_env IS DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
          OR NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NULL
        )
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
        AND classified_events.provider_webhook_receipt_id IS NOT NULL
        AND upper(COALESCE(classified_events.receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
        AND classified_events.receipt_provider_key IS NOT DISTINCT FROM v_batch.rail_provider_snapshot
        AND classified_events.receipt_rail_env IS NOT DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
        AND NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (WHERE classified_events.provider_event_transport = 'PROVIDER_POLL')::integer,
    count(*) FILTER (
      WHERE upper(COALESCE(classified_events.provider_failure_reason_group, '')) = 'PROVIDER_OUTAGE'
        AND upper(COALESCE(classified_events.mapping_status, '')) = 'MATCHED'
    )::integer
  INTO v_event_count,
       v_event_final_count,
       v_event_terminal_no_money_count,
       v_event_pending_count,
       v_event_unknown_count,
       v_provider_webhook_evidence_count,
       v_invalid_webhook_evidence_count,
       v_failed_webhook_replay_evidence_count,
       v_provider_poll_evidence_count,
       v_provider_outage_count
  FROM classified_events;

  SELECT event_rows.provider_key,
         COALESCE(NULLIF(BTRIM(event_rows.provider_state), ''), NULLIF(BTRIM(event_rows.normalised_state), '')),
         event_rows.provider_failure_reason_code,
         event_rows.provider_failure_reason_group,
         COALESCE(event_rows.raw_payload, '{}'::jsonb)
  INTO v_failure_event_provider_key,
       v_failure_event_state,
       v_failure_event_reason_code,
       v_provider_failure_reason_group,
       v_failure_event_payload
  FROM public.pay_bank_transfer_events AS event_rows
  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
    event_rows.normalised_state,
    event_rows.provider_state,
    COALESCE(event_rows.raw_payload, '{}'::jsonb),
    jsonb_build_object(
      'provider_key', event_rows.provider_key,
      'provider_event_type', event_rows.provider_event_type,
      'provider_event_transport', event_rows.provider_event_transport
    )
  ) AS movement_rows
  WHERE event_rows.pay_batch_id = p_pay_batch_id
    AND (
      COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
      OR event_rows.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
      OR event_rows.pay_bank_transfer_id IS NULL
    )
    AND (
      movement_rows.is_terminal_no_money
      OR event_rows.provider_failure_reason_group IS NOT NULL
      OR event_rows.provider_failure_reason_code IS NOT NULL
    )
  ORDER BY event_rows.received_at_utc DESC, event_rows.id DESC
  LIMIT 1;

  IF v_failure_event_provider_key IS NOT NULL OR v_failure_event_state IS NOT NULL OR v_failure_event_reason_code IS NOT NULL OR v_provider_failure_reason_group IS NOT NULL THEN
    v_provider_failure_reason_result := public._banking_provider_failure_reason_normalise(
      v_failure_event_provider_key,
      v_failure_event_state,
      v_failure_event_reason_code,
      v_provider_failure_reason_group,
      COALESCE(v_failure_event_payload, '{}'::jsonb)
    );
    v_provider_failure_reason_code := COALESCE(v_failure_event_reason_code, v_provider_failure_reason_result ->> 'failure_reason_code');
    v_provider_failure_reason_group := COALESCE(NULLIF(v_provider_failure_reason_group, ''), v_provider_failure_reason_result ->> 'failure_reason_group');
    v_provider_failure_reason_label := v_provider_failure_reason_result ->> 'failure_reason_label';
  END IF;

  SELECT
    count(*) FILTER (WHERE correction_work_items.work_kind = 'PRE_BANK_CANCEL' AND correction_work_items.status = 'APPLIED')::integer,
    count(*) FILTER (WHERE correction_work_items.work_kind = 'NO_MONEY_UNWIND' AND correction_work_items.status = 'APPLIED')::integer
  INTO v_pre_bank_applied_count,
       v_no_money_applied_count
  FROM public.pay_payment_correction_work_items AS correction_work_items
  WHERE correction_work_items.pay_batch_id = p_pay_batch_id
    AND (
      COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
      OR correction_work_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
      OR correction_work_items.pay_bank_transfer_id IS NULL
    );

  SELECT EXISTS (
           SELECT 1
           FROM public.pay_payment_correction_requests AS recovery_request
           WHERE recovery_request.pay_batch_id = p_pay_batch_id
             AND upper(BTRIM(COALESCE(recovery_request.status::text, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING', 'APPLIED', 'COMPLETE', 'COMPLETED')
             AND upper(BTRIM(COALESCE(recovery_request.correction_kind::text, ''))) IN ('PAID_RECOVERY_REQUIRED', 'PAID_SETTLED_RECOVERY_REQUIRED', 'AMEND_AND_RECOVER_OVERPAYMENT', 'OVERPAYMENT_RECOVERY', 'SETTLED_REVERSAL', 'POST_PAYMENT_AMENDMENT')
         )
         OR EXISTS (
           SELECT 1
           FROM public.pay_payment_correction_items AS recovery_item
           WHERE recovery_item.pay_batch_id = p_pay_batch_id
             AND upper(BTRIM(COALESCE(recovery_item.status::text, ''))) IN ('PENDING', 'APPROVED', 'AUTHORISED', 'APPLIED', 'PROCESSING')
             AND upper(BTRIM(COALESCE(recovery_item.correction_item_kind::text, ''))) IN ('SETTLED_REVERSAL', 'OVERPAYMENT_RECOVERY', 'PAID_RECOVERY', 'POST_PAYMENT_AMENDMENT')
         )
         OR EXISTS (
           SELECT 1
           FROM public.pay_batch_items AS recovery_batch_item
           JOIN public.pay_batch_candidates AS recovery_batch_candidate
             ON recovery_batch_candidate.id = recovery_batch_item.pay_batch_candidate_id
           WHERE recovery_batch_candidate.pay_batch_id = p_pay_batch_id
             AND COALESCE(recovery_batch_item.is_voided, false) = false
             AND upper(BTRIM(COALESCE(recovery_batch_item.item_type::text, ''))) = 'OVERPAYMENT_RECOVERY'
             AND COALESCE(recovery_batch_item.amount_inc_vat, recovery_batch_item.amount_ex_vat, 0) <> 0
         )
         OR upper(NULLIF(BTRIM(COALESCE(v_selection_json->>'source_context', '')), '')) IN ('PAID_RECOVERY_REQUIRED', 'POST_PAYMENT_AMENDMENT', 'OVERPAYMENT_RECOVERY')
  INTO v_has_actual_recovery_context;

  v_has_actual_recovery_context := COALESCE(v_has_actual_recovery_context, false);

  SELECT count(*)::integer
  INTO v_open_provider_submit_count
  FROM public.banking_pay_operations AS provider_operations
  WHERE provider_operations.pay_batch_id = p_pay_batch_id
    AND provider_operations.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND provider_operations.status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS')
    AND NOT (
      provider_operations.operation_type = 'PAYMENT_EXECUTE'
      AND provider_operations.phase = 'SCHEDULE_PAYMENT'
      AND provider_operations.resume_reason IN (
        'WAIT_FOR_SCHEDULED_NO_BANK_PAYMENT',
        'WAIT_FOR_SCHEDULED_LOCAL_MANUAL_SETTLEMENT'
      )
    );

  v_transfer_count := COALESCE(v_transfer_count, 0);
  v_transfer_final_count := COALESCE(v_transfer_final_count, 0);
  v_transfer_terminal_no_money_count := COALESCE(v_transfer_terminal_no_money_count, 0);
  v_transfer_pending_count := COALESCE(v_transfer_pending_count, 0);
  v_event_count := COALESCE(v_event_count, 0);
  v_event_final_count := COALESCE(v_event_final_count, 0);
  v_event_terminal_no_money_count := COALESCE(v_event_terminal_no_money_count, 0);
  v_event_pending_count := COALESCE(v_event_pending_count, 0);
  v_event_unknown_count := COALESCE(v_event_unknown_count, 0);
  v_provider_webhook_evidence_count := COALESCE(v_provider_webhook_evidence_count, 0);
  v_invalid_webhook_evidence_count := COALESCE(v_invalid_webhook_evidence_count, 0);
  v_failed_webhook_replay_evidence_count := COALESCE(v_failed_webhook_replay_evidence_count, 0);
  v_provider_poll_evidence_count := COALESCE(v_provider_poll_evidence_count, 0);
  v_provider_outage_count := COALESCE(v_provider_outage_count, 0);
  v_pre_bank_applied_count := COALESCE(v_pre_bank_applied_count, 0);
  v_no_money_applied_count := COALESCE(v_no_money_applied_count, 0);
  v_open_provider_submit_count := COALESCE(v_open_provider_submit_count, 0);

  v_final_evidence_count := v_transfer_final_count + v_event_final_count;
  v_terminal_no_money_count := v_transfer_terminal_no_money_count + v_event_terminal_no_money_count;
  -- A locally prepared transfer is stored as PENDING before any provider call.
  -- Do not turn that local row into provider-pending authority when the central
  -- evidence classifier proves that nothing was submitted or sent. Provider
  -- events and explicit request/submission evidence remain fail-closed.
  v_pending_provider_count :=
    CASE WHEN v_local_prepared_only THEN 0 ELSE v_transfer_pending_count END
    + v_event_pending_count
    + CASE WHEN v_provider_submitted OR v_provider_request_sent THEN 1 ELSE 0 END;
  v_unknown_provider_count := v_event_unknown_count + CASE
    WHEN v_provider_outage_count > 0 OR v_provider_blocker_code = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 0
    WHEN v_provider_evidence_class = 'PROVIDER_OUTCOME_UNKNOWN' OR v_provider_blocker_code = 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 1
    ELSE 0
  END;

  v_has_paid_or_settled := v_final_evidence_count > 0 OR upper(COALESCE(v_provider_cash_state, '')) = 'FINAL_PAID';
  v_has_provider_unknown := v_unknown_provider_count > 0;
  v_has_provider_pending := v_pending_provider_count > 0 AND v_terminal_no_money_count = 0 AND v_final_evidence_count = 0;
  v_has_provider_outage := v_provider_outage_count > 0 OR v_provider_blocker_code = 'PROVIDER_OUTAGE_RETRY_LATER';
  v_has_terminal_no_money := v_terminal_no_money_count > 0 OR upper(COALESCE(v_provider_cash_state, '')) = 'TERMINAL_NO_MONEY';
  v_is_local_not_sent := v_has_paid_or_settled IS NOT TRUE
                          AND v_has_provider_unknown IS NOT TRUE
                          AND v_has_provider_pending IS NOT TRUE
                          AND v_has_terminal_no_money IS NOT TRUE
                          AND v_provider_submitted IS NOT TRUE
                          AND v_provider_request_sent IS NOT TRUE
                          AND v_provider_response_present IS NOT TRUE
                          AND v_provider_event_present IS NOT TRUE
                          AND v_provider_external_id_present IS NOT TRUE;

  IF COALESCE(v_has_paid_or_settled, false) IS TRUE
     AND COALESCE(v_has_terminal_no_money, false) IS TRUE THEN
    v_has_actual_recovery_context := true;
  END IF;

  IF v_partial_scope_blocker_count > 0 THEN
    v_blockers := v_blockers || COALESCE(v_resolved_scope_json -> 'partial_scope_blockers', '[]'::jsonb);
  END IF;

  IF v_freshness_blocker_count > 0 THEN
    v_blockers := v_blockers || COALESCE(v_freshness_result -> 'blockers', '[]'::jsonb);
  END IF;

  IF v_manual_carry_forward_blocker_count > 0 OR v_can_carry_forward_automatically IS NOT TRUE THEN
    v_blockers := v_blockers || COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb);
  END IF;

  IF v_open_provider_submit_count > 0 THEN
    v_race_or_submission_blockers := v_race_or_submission_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PROVIDER_SUBMISSION_IN_PROGRESS',
      'message', 'Provider submission is in progress for this batch.'
    ));
    v_blockers := v_blockers || v_race_or_submission_blockers;
  END IF;

  IF v_batch_terminal THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PAYMENT_CORRECTION_BATCH_TERMINAL',
      'message', 'This payment batch is already complete and cannot be changed.',
      'batch_status', v_batch.status
    ));
  END IF;

  IF v_has_paid_or_settled AND COALESCE(v_has_actual_recovery_context, false) THEN
    v_lifecycle_state := 'PAID_OR_SETTLED';
    v_lifecycle_label := 'Recover overpayment in next pay run';
    v_recommended_action := 'AMEND_AND_RECOVER_OVERPAYMENT';
  ELSIF v_has_provider_unknown THEN
    v_lifecycle_state := 'PROVIDER_OUTCOME_UNKNOWN';
    v_lifecycle_label := 'Provider outcome unknown — check provider';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  ELSIF v_has_paid_or_settled THEN
    v_lifecycle_state := 'PAID_OR_SETTLED';
    v_lifecycle_label := CASE WHEN upper(COALESCE(v_batch.status, '')) = 'SETTLED' THEN 'Settled' ELSE 'Paid' END;
    v_recommended_action := 'VIEW_DETAILS';
  ELSIF v_has_provider_pending THEN
    v_lifecycle_state := 'PROVIDER_SUBMITTED_PENDING';
    v_lifecycle_label := 'Provider pending';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  ELSIF v_has_provider_outage
        AND COALESCE(v_provider_request_sent, false) IS NOT TRUE
        AND COALESCE(v_provider_submitted, false) IS NOT TRUE
        AND COALESCE(v_provider_external_id_present, false) IS NOT TRUE
        AND COALESCE(jsonb_array_length(v_blockers), 0) = 0 THEN
    v_lifecycle_state := 'PROVIDER_OUTAGE_RETRY_LATER';
    v_lifecycle_label := 'Bank unavailable — unsent payments can be retried';
    v_recommended_action := 'RETRY_PROVIDER_LATER';
  ELSIF v_no_money_applied_count > 0 THEN
    v_lifecycle_state := 'FINANCIALS_REWOUND';
    v_lifecycle_label := 'Financials rewound — amend timesheet and recalculate';
    v_recommended_action := 'VIEW_RECALCULATE_NEXT_STEP';
  ELSIF v_has_terminal_no_money THEN
    IF upper(COALESCE(v_failure_event_state, '')) IN ('CANCELLED', 'CANCELED') THEN
      v_lifecycle_state := 'PROVIDER_CANCELLED_NO_MONEY';
    ELSE
      v_lifecycle_state := 'PROVIDER_FAILED_NO_MONEY';
    END IF;
    v_lifecycle_label := 'Failed — not paid';
    v_recommended_action := 'NO_MONEY_UNWIND_AND_RECALCULATE';
  ELSIF v_pre_bank_applied_count > 0 THEN
    IF v_scope_type = 'BATCH' THEN
      v_lifecycle_state := 'CANCELLED_BEFORE_BANK_SUBMISSION';
      v_lifecycle_label := 'Cancelled before bank submission';
    ELSE
      v_lifecycle_state := 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION';
      v_lifecycle_label := 'Partially cancelled before bank submission';
    END IF;
    v_recommended_action := 'VIEW_RECALCULATE_NEXT_STEP';
  ELSIF v_is_local_not_sent THEN
    IF upper(COALESCE(v_batch.status, '')) = 'SCHEDULED' OR v_batch.scheduled_at_utc IS NOT NULL THEN
      v_lifecycle_state := 'SCHEDULED_LOCAL_NOT_SENT';
      v_lifecycle_label := 'Scheduled — not sent to bank yet';
    ELSE
      v_lifecycle_state := 'LOCAL_PREPARED_NOT_SENT';
      v_lifecycle_label := 'Prepared locally — not sent to bank yet';
    END IF;
    v_recommended_action := 'PRE_PROVIDER_CANCEL_AND_RECALCULATE';
  ELSE
    v_lifecycle_state := 'PROVIDER_OUTCOME_UNKNOWN';
    v_lifecycle_label := 'Provider outcome unknown — check provider';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  END IF;

  v_can_pre_provider_cancel := v_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
                               AND v_scope_is_full
                               AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;
  v_can_no_money_unwind := v_lifecycle_state IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
                           AND v_scope_is_full
                           AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;
  v_can_recover_overpayment := v_lifecycle_state = 'PAID_OR_SETTLED' AND COALESCE(v_has_actual_recovery_context, false);
  v_requires_provider_cancel := v_provider_submitted OR v_provider_request_sent;
  v_requires_bank_check := v_lifecycle_state IN ('PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_SUBMITTED_PENDING');
  v_requires_retry_later := v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER';
  v_whole_batch_cancel_available := v_can_pre_provider_cancel AND v_scope_type = 'BATCH';
  v_row_cancel_available := v_can_pre_provider_cancel AND v_scope_type <> 'BATCH';
  v_retry_same_batch_safe := v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER'
                             AND v_provider_request_sent IS NOT TRUE
                             AND v_provider_submitted IS NOT TRUE
                             AND v_provider_external_id_present IS NOT TRUE
                             AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;

  v_provider_evidence_summary_json := jsonb_build_object(
    'evidence_class', v_provider_evidence_class,
    'provider_submitted', v_provider_submitted,
    'provider_request_sent', v_provider_request_sent,
    'provider_response_present', v_provider_response_present,
    'provider_event_present', v_provider_event_present,
    'provider_external_id_present', v_provider_external_id_present,
    'local_prepared_only', v_local_prepared_only,
    'cash_state', v_provider_cash_state,
    'provider_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'provider_poll_evidence_count', v_provider_poll_evidence_count,
    'support_details_json', v_provider_support_details_json
  );

  v_blocking_paid_evidence_json := jsonb_build_object(
    'has_paid_or_settled', v_has_paid_or_settled,
    'final_evidence_count', v_final_evidence_count,
    'transfer_final_count', v_transfer_final_count,
    'event_final_count', v_event_final_count
  );

  v_terminal_no_money_evidence_json := jsonb_build_object(
    'has_terminal_no_money', v_has_terminal_no_money,
    'terminal_no_money_count', v_terminal_no_money_count,
    'transfer_terminal_no_money_count', v_transfer_terminal_no_money_count,
    'event_terminal_no_money_count', v_event_terminal_no_money_count,
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_label', v_provider_failure_reason_label
  );

  v_pending_provider_evidence_json := jsonb_build_object(
    'has_provider_pending', v_has_provider_pending,
    'pending_provider_count', v_pending_provider_count,
    'transfer_pending_count', v_transfer_pending_count,
    'event_pending_count', v_event_pending_count
  );

  v_provider_outcome_unknown_evidence_json := jsonb_build_object(
    'has_provider_unknown', v_has_provider_unknown,
    'unknown_provider_count', v_unknown_provider_count,
    'event_unknown_count', v_event_unknown_count,
    'provider_blocker_code', v_provider_blocker_code,
    'provider_reason', v_provider_reason
  );

  v_provider_webhook_evidence_json := jsonb_build_object(
    'provider_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'provider_poll_evidence_count', v_provider_poll_evidence_count,
    'event_count', v_event_count
  );

  v_finance_scope_json := jsonb_build_object(
    'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
    'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
    'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb)
  );

  v_alert_candidate_is_success_only := v_lifecycle_state = 'PAID_OR_SETTLED'
    AND COALESCE(v_has_actual_recovery_context, false) IS NOT TRUE;
  v_alert_candidate_kind := CASE
    WHEN v_alert_candidate_is_success_only THEN NULL::text
    WHEN v_lifecycle_state = 'PAID_OR_SETTLED' AND v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
    WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
    WHEN v_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN v_lifecycle_state IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY') THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
    WHEN v_lifecycle_state = 'PROVIDER_SUBMITTED_PENDING' THEN NULL::text
    WHEN v_manual_carry_forward_blocker_count > 0 THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    ELSE NULL::text
  END;

  v_alert_candidate_severity := CASE
    WHEN v_alert_candidate_kind IN ('PROVIDER_OUTAGE_RETRY_LATER', 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER', 'TERMINAL_NO_MONEY_REWIND_AVAILABLE', 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS', 'PAID_SETTLED_RECOVERY_REQUIRED') THEN 'ACTION_REQUIRED'
    ELSE NULL::text
  END;

  v_status_update_signature := md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'scope_type', v_scope_type,
    'lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'final_evidence_count', v_final_evidence_count,
    'terminal_no_money_count', v_terminal_no_money_count,
    'pending_provider_count', v_pending_provider_count,
    'unknown_provider_count', v_unknown_provider_count,
    'pre_bank_applied_count', v_pre_bank_applied_count,
    'no_money_applied_count', v_no_money_applied_count
  )::text);

  v_support_details_json := jsonb_build_object(
    'batch_status', v_batch.status,
    'scope_type', v_scope_type,
    'scope_is_full', v_scope_is_full,
    'transfer_count', v_transfer_count,
    'event_count', v_event_count,
    'pre_bank_applied_count', v_pre_bank_applied_count,
    'no_money_applied_count', v_no_money_applied_count,
    'open_provider_submit_count', v_open_provider_submit_count,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
  );

  v_result := jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'selection_json', v_selection_json,
    'scope_type', v_scope_type,
    'payment_lifecycle_state', v_lifecycle_state,
    'payment_lifecycle_label', v_lifecycle_label,
    'recommended_action', v_recommended_action,
    'next_step', CASE WHEN v_lifecycle_state IN ('FINANCIALS_REWOUND', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION') THEN 'AMEND_TIMESHEET_AND_RECALCULATE' ELSE NULL::text END,
    'next_step_label', CASE WHEN v_lifecycle_state IN ('FINANCIALS_REWOUND', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION') THEN 'Amend timesheets and recalculate' ELSE NULL::text END,
    'can_pre_provider_cancel', v_can_pre_provider_cancel,
    'can_no_money_unwind', v_can_no_money_unwind,
    'can_recover_overpayment', v_can_recover_overpayment,
    'requires_provider_cancel', v_requires_provider_cancel,
    'requires_bank_check', v_requires_bank_check,
    'requires_retry_later', v_requires_retry_later,
    'whole_batch_cancel_available', v_whole_batch_cancel_available,
    'row_cancel_available', v_row_cancel_available,
    'retry_same_batch_safe', v_retry_same_batch_safe,
    'retry_status_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried' ELSE NULL::text END,
    'retry_row_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available' ELSE NULL::text END,
    'retry_button_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry unsent payments' ELSE NULL::text END,
    'retry_running_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retrying unsent payments' ELSE NULL::text END,
    'retry_disabled_button_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry in progress' ELSE NULL::text END,
    'retry_row_action_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Open retry summary' ELSE NULL::text END,
    'paid_recovery_label', CASE WHEN v_lifecycle_state = 'PAID_OR_SETTLED' AND COALESCE(v_has_actual_recovery_context, false) THEN 'Recover overpayment in next pay run' ELSE NULL::text END,
    'has_actual_recovery_context', COALESCE(v_has_actual_recovery_context, false)
  );

  v_result := v_result || jsonb_build_object(
    'provider_evidence_summary_json', v_provider_evidence_summary_json,
    'blocking_paid_evidence_json', v_blocking_paid_evidence_json,
    'terminal_no_money_evidence_json', v_terminal_no_money_evidence_json,
    'pending_provider_evidence_json', v_pending_provider_evidence_json,
    'provider_outcome_unknown_evidence_json', v_provider_outcome_unknown_evidence_json,
    'provider_webhook_evidence_json', v_provider_webhook_evidence_json,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', v_finance_scope_json,
    'manual_adjustment_carry_forward_required', v_manual_carry_forward_required,
    'manual_adjustments_to_carry_forward', COALESCE(v_manual_adjustment_result -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_manual_adjustment_result -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'can_carry_forward_automatically', v_can_carry_forward_automatically
  );

  v_result := v_result || jsonb_build_object(
    'carry_forward_blockers', COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb),
    'manual_adjustment_support_details_json', COALESCE(v_manual_adjustment_result -> 'manual_adjustment_support_details_json', '{}'::jsonb),
    'race_or_submission_blockers', v_race_or_submission_blockers,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'support_details_json', v_support_details_json,
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_label', v_provider_failure_reason_label,
    'status_update_signature', v_status_update_signature,
    'verified_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'alert_candidate_kind', v_alert_candidate_kind,
    'alert_candidate_severity', v_alert_candidate_severity,
    'alert_candidate_is_success_only', v_alert_candidate_is_success_only
  );

  RETURN v_result;
END;
$function$;

-- pay_payment_cancellation_route_diagnostic_v1(uuid,jsonb,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_payment_cancellation_route_diagnostic_v1(p_pay_batch_id uuid, p_selection_json jsonb, p_actor_user_id uuid, p_context text DEFAULT 'ROUTE_TRUTH'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5000ms'
AS $function$
DECLARE
  v_context text:=pg_catalog.upper(pg_catalog.btrim(COALESCE(p_context,'ROUTE_TRUTH')));
  v_selection jsonb:=COALESCE(p_selection_json,'{}'::jsonb);
  v_tokens jsonb:='[]'::jsonb;
  v_candidate_ids jsonb:='[]'::jsonb;
  v_candidate_count integer:=0;
  v_status_page jsonb:='{}'::jsonb;
  v_proof jsonb:='{}'::jsonb;
  v_results jsonb:='[]'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL OR p_actor_user_id IS NULL
     OR pg_catalog.jsonb_typeof(v_selection)<>'object'
     OR v_context NOT IN ('ROUTE_TRUTH','CI_PARITY','OBSERVE_ONLY') THEN
    RAISE EXCEPTION 'PAYMENT_CANCELLATION_ROUTE_DIAGNOSTIC_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','PAYMENT_CANCELLATION_ROUTE_DIAGNOSTIC_ARGUMENT_INVALID'
      )::text;
  END IF;

  v_tokens:=CASE
    WHEN pg_catalog.jsonb_typeof(v_selection#>'{selection,explicit_candidate_tokens}')='array'
      THEN v_selection#>'{selection,explicit_candidate_tokens}'
    WHEN pg_catalog.jsonb_typeof(v_selection->'explicit_candidate_tokens')='array'
      THEN v_selection->'explicit_candidate_tokens'
    WHEN pg_catalog.jsonb_typeof(v_selection->'candidate_tokens')='array'
      THEN v_selection->'candidate_tokens'
    ELSE '[]'::jsonb END;

  IF pg_catalog.jsonb_array_length(v_tokens)<1
     OR pg_catalog.jsonb_array_length(v_tokens)>100 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'read_only',true,
      'contract_version','PAYMENT_CANCELLATION_ROUTE_DIAGNOSTIC_V1',
      'code','BOUNDED_EXPLICIT_SELECTION_REQUIRED',
      'candidate_limit',100,'requested_token_count',pg_catalog.jsonb_array_length(v_tokens),
      'mutation_count',0
    );
  END IF;

  WITH requested_tokens AS (
    SELECT token.value,token.ordinality
    FROM pg_catalog.jsonb_array_elements_text(v_tokens)
      WITH ORDINALITY AS token(value,ordinality)
  ), resolved AS (
    SELECT DISTINCT ON (batch_candidate.candidate_id)
      batch_candidate.candidate_id,requested_tokens.ordinality
    FROM requested_tokens
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.pay_batch_id=p_pay_batch_id
     AND (
       batch_candidate.id::text=requested_tokens.value
       OR batch_candidate.candidate_id::text=requested_tokens.value
     )
    ORDER BY batch_candidate.candidate_id,requested_tokens.ordinality
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(resolved.candidate_id ORDER BY resolved.ordinality),'[]'::jsonb),
         pg_catalog.count(*)::integer
  INTO v_candidate_ids,v_candidate_count
  FROM resolved;

  IF v_candidate_count IS DISTINCT FROM pg_catalog.jsonb_array_length(v_tokens) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'read_only',true,
      'contract_version','PAYMENT_CANCELLATION_ROUTE_DIAGNOSTIC_V1',
      'code','SELECTION_MEMBERSHIP_NOT_EXACT',
      'requested_token_count',pg_catalog.jsonb_array_length(v_tokens),
      'resolved_candidate_count',v_candidate_count,'mutation_count',0
    );
  END IF;

  v_status_page:=public.pay_batch_payment_status_page_v1(
    p_pay_batch_id,p_actor_user_id,
    pg_catalog.jsonb_build_object(
      'included_candidate_tokens',(
        SELECT pg_catalog.jsonb_agg(batch_candidate.id::text ORDER BY batch_candidate.id)
        FROM public.pay_batch_candidates AS batch_candidate
        WHERE batch_candidate.pay_batch_id=p_pay_batch_id
          AND batch_candidate.candidate_id IN (
            SELECT candidate_value.value::uuid
            FROM pg_catalog.jsonb_array_elements_text(v_candidate_ids) AS candidate_value(value)
          )
      )
    ),
    'STATUS','ASC',100,NULL::jsonb
  );

  v_proof:=private.pay_workbench_cancel_reversion_proof_core_v1(
    NULL::uuid,NULL::uuid,NULL::uuid,ARRAY[]::uuid[],'PRE_REQUEST',
    pg_catalog.jsonb_build_object(
      'pay_batch_id',p_pay_batch_id,'candidate_ids',v_candidate_ids
    )
  );

  WITH candidates AS (
    SELECT candidate_value.value::uuid AS candidate_id,candidate_value.ordinality
    FROM pg_catalog.jsonb_array_elements_text(v_candidate_ids)
      WITH ORDINALITY AS candidate_value(value,ordinality)
  ), status_rows AS (
    SELECT status_row.value
    FROM pg_catalog.jsonb_array_elements(COALESCE(v_status_page->'rows','[]'::jsonb)) AS status_row(value)
  ), proof_rows AS (
    SELECT proof_row.value
    FROM pg_catalog.jsonb_array_elements(COALESCE(v_proof->'candidate_results','[]'::jsonb)) AS proof_row(value)
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'candidate_id',candidates.candidate_id,
    'pay_batch_candidate_id',status_rows.value->>'pay_batch_candidate_id',
    'canonical_ui_actions',COALESCE(status_rows.value->'available_actions','[]'::jsonb),
    'payment_display_state',status_rows.value->>'payment_display_state',
    'financial_correction_action',CASE
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'CANCEL_PAYMENT'
        THEN 'PRE_BANK_CANCEL'
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'DRAFT_CANCEL'
        THEN 'DRAFT_CANCEL'
      ELSE NULL END,
    'scheduled_reversion_admitted',COALESCE((proof_rows.value->>'admitted')::boolean,false),
    'rejection_reason',proof_rows.value->>'rejection_reason',
    'expected_economic_route',CASE
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'CANCEL_PAYMENT'
       AND COALESCE((proof_rows.value->>'admitted')::boolean,false)
        THEN 'CERTIFIED_CANCELLATION_REVERSION'
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'CANCEL_PAYMENT'
        THEN 'SAFE_ROUTE_LADDER_FALLBACK'
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'DRAFT_CANCEL'
        THEN 'DRAFT_OVERLAY_FAST_PREFLIGHT_REQUIRED'
      ELSE 'NOT_CANCELLABLE' END,
    'expected_full_build_count',CASE
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'CANCEL_PAYMENT'
       AND COALESCE((proof_rows.value->>'admitted')::boolean,false) THEN 0
      ELSE NULL END,
    'expected_reconciliation_count',CASE
      WHEN COALESCE(status_rows.value->'available_actions','[]'::jsonb) ? 'CANCEL_PAYMENT'
       AND COALESCE((proof_rows.value->>'admitted')::boolean,false) THEN 0
      ELSE NULL END,
    'proof',COALESCE(proof_rows.value,'{}'::jsonb)
  ) ORDER BY candidates.ordinality),'[]'::jsonb)
  INTO v_results
  FROM candidates
  LEFT JOIN status_rows ON status_rows.value->>'candidate_id'=candidates.candidate_id::text
  LEFT JOIN proof_rows ON proof_rows.value->>'candidate_id'=candidates.candidate_id::text;

  RETURN pg_catalog.jsonb_build_object(
    'ok',COALESCE((v_status_page->>'ok')::boolean,false),
    'read_only',true,'mutation_count',0,
    'contract_version','PAYMENT_CANCELLATION_ROUTE_DIAGNOSTIC_V1',
    'context',v_context,'pay_batch_id',p_pay_batch_id,
    'status_snapshot_token',v_status_page->>'snapshot_token',
    'candidate_count',v_candidate_count,'candidate_results',v_results
  );
END;
$function$;

-- pay_payment_confirm_no_money_and_unwind(uuid,jsonb,uuid,jsonb,text,text)
CREATE OR REPLACE FUNCTION public.pay_payment_confirm_no_money_and_unwind(p_pay_batch_id uuid, p_selection_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_confirmation_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_selection_json jsonb := '{}'::jsonb;
  v_confirmation_json jsonb := '{}'::jsonb;
  v_diagnostic_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_lifecycle_state text := NULL::text;
  v_recommended_action text := NULL::text;
  v_blockers jsonb := '[]'::jsonb;
  v_race_blockers jsonb := '[]'::jsonb;
  v_carry_forward_blockers jsonb := '[]'::jsonb;
  v_effective_selection_json jsonb := '{}'::jsonb;
  v_selection_hash text := NULL::text;
  v_plan_json jsonb := '{}'::jsonb;
  v_plan_hash text := NULL::text;
  v_accepted_resolution_json jsonb := '{}'::jsonb;
  v_accepted_resolution_hash text := NULL::text;
  v_required_quantity integer := 1;
  v_reason text := NULL::text;
  v_existing_request public.pay_payment_correction_requests%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_expand_result jsonb := '{}'::jsonb;
  v_process_result jsonb := '{}'::jsonb;
  v_signal_result jsonb := '{}'::jsonb;
  v_idempotency_key text := NULL::text;
  v_scope_type text := NULL::text;
  v_actor_valid boolean := true;
  v_source_text text := NULL::text;
  v_source_bank_event_id uuid := NULL::uuid;
  v_source_bank_event_text text := NULL::text;
  v_source_bank_event_pay_batch_id uuid := NULL::uuid;
  v_source_bank_event_provider_key text := NULL::text;
  v_source_bank_event_transport text := NULL::text;
  v_source_bank_event_key text := NULL::text;
  v_source_bank_event_provider_event_id text := NULL::text;
  v_source_bank_event_provider_transaction_id text := NULL::text;
  v_source_bank_event_provider_request_id text := NULL::text;
  v_source_bank_event_mapping_status text := NULL::text;
  v_source_bank_event_mapping_method text := NULL::text;
  v_source_bank_event_webhook_receipt_id uuid := NULL::uuid;
  v_source_bank_event_signature_valid boolean := NULL::boolean;
  v_source_bank_event_terminal_no_money boolean := false;
  v_source_bank_event_final_paid boolean := false;
  v_source_bank_event_pending boolean := false;
  v_provider_key_text text := NULL::text;
  v_provider_event_key_text text := NULL::text;
  v_provider_event_id_text text := NULL::text;
  v_provider_transaction_id_text text := NULL::text;
  v_provider_request_id_text text := NULL::text;
  v_provider_webhook_receipt_id_text text := NULL::text;
  v_provider_webhook_receipt_id uuid := NULL::uuid;
  v_provider_signature_valid_confirmed boolean := false;
  v_source_is_provider boolean := false;
  v_webhook_receipt_status text := NULL::text;
  v_webhook_receipt_provider_key text := NULL::text;
  v_webhook_receipt_rail_env text := NULL::text;
  v_webhook_receipt_event_key text := NULL::text;
  v_webhook_receipt_signature_valid boolean := NULL::boolean;
  v_webhook_receipt_ok boolean := false;
  v_failed_webhook_replay_receipt_ok boolean := false;
  v_diagnostic_terminal_no_money_count integer := 0;
  v_scope_is_full boolean := true;
  v_strong_mapping_confirmed boolean := false;
  v_strong_provider_evidence boolean := false;
  v_manual_confirmation_ok boolean := false;
  v_manual_confirmation_reference_text text := NULL::text;
  v_is_system_request boolean := false;
  v_auto_unwind_setting boolean := false;
  v_correction_kind text := 'NO_MONEY_UNWIND';
  v_is_complete boolean := false;
  v_grouped_alert_updates jsonb := '[]'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_BATCH_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_BATCH_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_confirmation_json IS NOT NULL AND COALESCE(jsonb_typeof(p_confirmation_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_CONFIRMATION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_CONFIRMATION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_valid;

    IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_ACTOR_NOT_ALLOWED', 'actor_user_id', p_actor_user_id::text)::text;
    END IF;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_confirmation_json := COALESCE(p_confirmation_json, '{}'::jsonb);
  v_reason := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_source_text := UPPER(NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'source', v_confirmation_json ->> 'evidence_source', '')), ''));
  v_provider_key_text := UPPER(NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_key', v_confirmation_json ->> 'provider', v_confirmation_json ->> 'rail_provider', '')), ''));
  v_provider_event_key_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_event_key', v_confirmation_json ->> 'event_key', '')), '');
  v_provider_event_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_event_id', v_confirmation_json ->> 'event_id', '')), '');
  v_provider_transaction_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_transaction_id', v_confirmation_json ->> 'transaction_id', v_confirmation_json ->> 'provider_payment_id', '')), '');
  v_provider_request_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_request_id', v_confirmation_json ->> 'request_id', '')), '');
  v_provider_webhook_receipt_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_webhook_receipt_id', v_confirmation_json ->> 'webhook_receipt_id', '')), '');
  v_provider_signature_valid_confirmed := lower(BTRIM(COALESCE(v_confirmation_json ->> 'provider_signature_valid', v_confirmation_json ->> 'signature_valid', 'false'))) IN ('true','t','yes','y','1','on');
  v_source_is_provider := v_source_text IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE');

  v_source_bank_event_text := COALESCE(
    NULLIF(BTRIM(v_confirmation_json ->> 'source_bank_event_id'), ''),
    NULLIF(BTRIM(v_confirmation_json ->> 'bank_event_id'), '')
  );

  IF v_source_bank_event_text IS NOT NULL THEN
    IF v_source_bank_event_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_SOURCE_BANK_EVENT_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_SOURCE_BANK_EVENT_ID',
                'source_bank_event_id', v_source_bank_event_text
              )::text;
    END IF;
    v_source_bank_event_id := v_source_bank_event_text::uuid;
  END IF;

  IF v_provider_webhook_receipt_id_text IS NOT NULL THEN
    IF v_provider_webhook_receipt_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_WEBHOOK_RECEIPT_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_WEBHOOK_RECEIPT_ID',
                'provider_webhook_receipt_id', v_provider_webhook_receipt_id_text
              )::text;
    END IF;
    v_provider_webhook_receipt_id := v_provider_webhook_receipt_id_text::uuid;
  END IF;

  v_manual_confirmation_reference_text := NULLIF(BTRIM(COALESCE(
    v_confirmation_json ->> 'provider_reference',
    v_confirmation_json ->> 'provider_ref',
    v_confirmation_json ->> 'bank_reference',
    v_confirmation_json ->> 'bank_ref',
    v_confirmation_json ->> 'rail_tx_id',
    v_confirmation_json ->> 'provider_transaction_id',
    v_confirmation_json ->> 'audit_note',
    v_confirmation_json ->> 'manual_note',
    v_confirmation_json ->> 'note',
    v_reason,
    ''
  )), '');
  v_is_system_request := p_actor_user_id IS NULL;

  SELECT COALESCE(settings_row.banking_pay_auto_unwind_terminal_no_money, false)
  INTO v_auto_unwind_setting
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF v_is_system_request AND COALESCE(v_auto_unwind_setting, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_AUTO_UNWIND_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_AUTO_UNWIND_DISABLED')::text;
  END IF;

  v_diagnostic_json := public.pay_payment_cancelability_diagnostic(p_pay_batch_id, v_selection_json, p_actor_user_id);
  v_lifecycle_state := v_diagnostic_json ->> 'payment_lifecycle_state';
  v_recommended_action := v_diagnostic_json ->> 'recommended_action';
  v_blockers := COALESCE(v_diagnostic_json -> 'blockers', '[]'::jsonb);
  v_race_blockers := COALESCE(v_diagnostic_json -> 'race_or_submission_blockers', '[]'::jsonb);
  v_carry_forward_blockers := COALESCE(v_diagnostic_json -> 'carry_forward_blockers', '[]'::jsonb);
  v_resolved_scope_json := COALESCE(v_diagnostic_json -> 'resolved_full_payment_scope_json', '{}'::jsonb);
  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');
  v_scope_is_full := CASE
    WHEN LOWER(BTRIM(COALESCE(v_resolved_scope_json ->> 'is_full_scope', 'true'))) IN ('true','t','yes','y','1','on') THEN true
    WHEN LOWER(BTRIM(COALESCE(v_resolved_scope_json ->> 'is_full_scope', 'true'))) IN ('false','f','no','n','0','off') THEN false
    ELSE true
  END;

  IF v_source_bank_event_id IS NOT NULL THEN
    SELECT source_event_row.pay_batch_id,
           source_event_row.provider_key,
           source_event_row.provider_event_transport,
           source_event_row.provider_event_key,
           source_event_row.provider_event_id,
           source_event_row.provider_transaction_id,
           source_event_row.provider_request_id,
           source_event_row.mapping_status,
           source_event_row.mapping_method,
           source_event_row.provider_webhook_receipt_id,
           source_event_row.provider_signature_valid,
           COALESCE(source_event_classification.is_terminal_no_money, false),
           COALESCE(source_event_classification.is_final_money_moved, false),
           COALESCE(source_event_classification.is_pending_non_final, false)
    INTO v_source_bank_event_pay_batch_id,
         v_source_bank_event_provider_key,
         v_source_bank_event_transport,
         v_source_bank_event_key,
         v_source_bank_event_provider_event_id,
         v_source_bank_event_provider_transaction_id,
         v_source_bank_event_provider_request_id,
         v_source_bank_event_mapping_status,
         v_source_bank_event_mapping_method,
         v_source_bank_event_webhook_receipt_id,
         v_source_bank_event_signature_valid,
         v_source_bank_event_terminal_no_money,
         v_source_bank_event_final_paid,
         v_source_bank_event_pending
    FROM public.pay_bank_transfer_events AS source_event_row
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_event_row.normalised_state,
      source_event_row.provider_state,
      COALESCE(source_event_row.raw_payload, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', source_event_row.provider_key,
        'provider_event_transport', source_event_row.provider_event_transport,
        'provider_event_key', source_event_row.provider_event_key,
        'provider_transaction_id', source_event_row.provider_transaction_id,
        'provider_request_id', source_event_row.provider_request_id,
        'rail_env', source_event_row.rail_env
      )
    ) AS source_event_classification
    WHERE source_event_row.id = v_source_bank_event_id;

    IF v_source_bank_event_pay_batch_id IS NULL THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_NOT_FOUND',
                'source_bank_event_id', v_source_bank_event_id::text
              )::text;
    END IF;

    IF v_source_bank_event_pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_BATCH_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_BATCH_MISMATCH',
                'pay_batch_id', p_pay_batch_id::text,
                'source_bank_event_pay_batch_id', v_source_bank_event_pay_batch_id::text,
                'source_bank_event_id', v_source_bank_event_id::text
              )::text;
    END IF;

    v_provider_key_text := COALESCE(v_provider_key_text, UPPER(NULLIF(BTRIM(v_source_bank_event_provider_key), '')));
    v_source_text := COALESCE(v_source_text, UPPER(NULLIF(BTRIM(v_source_bank_event_transport), '')));
    v_source_is_provider := v_source_text IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE');
    v_provider_event_key_text := COALESCE(v_provider_event_key_text, NULLIF(BTRIM(v_source_bank_event_key), ''));
    v_provider_event_id_text := COALESCE(v_provider_event_id_text, NULLIF(BTRIM(v_source_bank_event_provider_event_id), ''));
    v_provider_transaction_id_text := COALESCE(v_provider_transaction_id_text, NULLIF(BTRIM(v_source_bank_event_provider_transaction_id), ''));
    v_provider_request_id_text := COALESCE(v_provider_request_id_text, NULLIF(BTRIM(v_source_bank_event_provider_request_id), ''));
    v_provider_webhook_receipt_id := COALESCE(v_provider_webhook_receipt_id, v_source_bank_event_webhook_receipt_id);
    v_provider_signature_valid_confirmed := COALESCE(v_provider_signature_valid_confirmed, false) OR COALESCE(v_source_bank_event_signature_valid, false);
  END IF;

  IF v_lifecycle_state NOT IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
     OR v_recommended_action IS DISTINCT FROM 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_NOT_AVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'payment_lifecycle_state', v_lifecycle_state,
              'recommended_action', v_recommended_action,
              'diagnostic_json', v_diagnostic_json
            )::text;
  END IF;

  IF COALESCE(v_scope_is_full, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_FULL_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_FULL_SCOPE_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'scope_type', v_scope_type,
              'resolved_full_payment_scope_json', v_resolved_scope_json
            )::text;
  END IF;

  IF COALESCE(jsonb_array_length(v_blockers), 0) > 0
     OR COALESCE(jsonb_array_length(v_race_blockers), 0) > 0
     OR COALESCE(jsonb_array_length(v_carry_forward_blockers), 0) > 0 THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_BLOCKED',
              'pay_batch_id', p_pay_batch_id::text,
              'blockers', v_blockers,
              'race_or_submission_blockers', v_race_blockers,
              'carry_forward_blockers', v_carry_forward_blockers
            )::text;
  END IF;

  v_diagnostic_terminal_no_money_count := COALESCE(NULLIF(BTRIM(COALESCE(v_diagnostic_json #>> '{terminal_no_money_evidence_json,terminal_no_money_count}', '')), '')::integer, 0);

  IF v_provider_webhook_receipt_id IS NOT NULL THEN
    SELECT receipt_row.status,
           receipt_row.provider_key,
           receipt_row.rail_env,
           receipt_row.provider_event_key,
           receipt_row.signature_valid
    INTO v_webhook_receipt_status,
         v_webhook_receipt_provider_key,
         v_webhook_receipt_rail_env,
         v_webhook_receipt_event_key,
         v_webhook_receipt_signature_valid
    FROM public.bank_provider_webhook_receipts AS receipt_row
    WHERE receipt_row.id = v_provider_webhook_receipt_id;

    v_provider_event_key_text := COALESCE(v_provider_event_key_text, v_webhook_receipt_event_key);
  END IF;

  v_webhook_receipt_ok := (
    v_provider_webhook_receipt_id IS NOT NULL
    AND v_webhook_receipt_status IS NOT NULL
    AND UPPER(COALESCE(v_webhook_receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
    AND v_webhook_receipt_signature_valid IS TRUE
    AND (v_provider_key_text IS NULL OR v_webhook_receipt_provider_key IS NOT DISTINCT FROM v_provider_key_text)
    AND NULLIF(BTRIM(COALESCE(v_provider_event_key_text, '')), '') IS NOT NULL
    AND v_webhook_receipt_event_key IS NOT NULL
    AND v_webhook_receipt_event_key = v_provider_event_key_text
  );

  v_failed_webhook_replay_receipt_ok := (
    v_provider_webhook_receipt_id IS NOT NULL
    AND v_webhook_receipt_status IS NOT NULL
    AND UPPER(COALESCE(v_webhook_receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
    AND (v_provider_key_text IS NULL OR v_webhook_receipt_provider_key IS NOT DISTINCT FROM v_provider_key_text)
    AND NULLIF(BTRIM(COALESCE(v_provider_event_key_text, '')), '') IS NOT NULL
    AND v_webhook_receipt_event_key IS NOT NULL
    AND v_webhook_receipt_event_key = v_provider_event_key_text
  );

  v_strong_mapping_confirmed := (
    lower(BTRIM(COALESCE(v_confirmation_json ->> 'strong_mapping_method', v_confirmation_json ->> 'strong_transfer_mapping', 'false'))) IN ('true','t','yes','y','1','on')
    OR (
      UPPER(BTRIM(COALESCE(v_source_bank_event_mapping_status, ''))) = 'MATCHED'
      AND UPPER(BTRIM(COALESCE(v_source_bank_event_mapping_method, ''))) IN (
        'TRANSFER_ID',
        'PROVIDER_EVENT_ID',
        'PROVIDER_TRANSACTION_ID',
        'PROVIDER_REQUEST_ID',
        'PROVIDER_REFERENCE',
        'RAIL_TX_ID',
        'MANUAL_TRANSFER_SELECTION'
      )
    )
    OR (
      v_source_bank_event_id IS NULL
      AND jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0
      AND v_source_text IN ('PROVIDER_POLL', 'PROVIDER_RESPONSE')
    )
  );

  v_strong_provider_evidence := (
    v_source_is_provider
    AND v_provider_key_text IS NOT NULL
    AND (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL)
    AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'terminal_no_money_evidence', 'false'))) IN ('true','t','yes','y','1','on')
    AND COALESCE(v_diagnostic_terminal_no_money_count, 0) > 0
    AND COALESCE(v_strong_mapping_confirmed, false) IS TRUE
    AND (v_source_bank_event_id IS NULL OR v_source_bank_event_terminal_no_money IS TRUE)
    AND v_source_bank_event_final_paid IS NOT TRUE
    AND v_source_bank_event_pending IS NOT TRUE
    AND (
      v_source_text <> 'PROVIDER_WEBHOOK'
      OR (
        v_provider_signature_valid_confirmed IS TRUE
        AND v_webhook_receipt_ok IS TRUE
      )
    )
    AND (
      v_source_text <> 'FAILED_WEBHOOK_REPLAY'
      OR v_failed_webhook_replay_receipt_ok IS TRUE
    )
  );

  v_manual_confirmation_ok := lower(BTRIM(COALESCE(v_confirmation_json ->> 'provider_checked', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'no_payment_made', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'terminal_no_money_confirmed', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'will_not_later_be_paid', 'false'))) IN ('true','t','yes','y','1','on')
                              AND v_manual_confirmation_reference_text IS NOT NULL;

  IF v_source_is_provider AND v_strong_provider_evidence IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_PROVIDER_SOURCE_REQUIRES_STRONG_PROVIDER_EVIDENCE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_PROVIDER_SOURCE_REQUIRES_STRONG_PROVIDER_EVIDENCE',
              'confirmation_json', v_confirmation_json,
              'source', v_source_text,
              'provider_key_present', v_provider_key_text IS NOT NULL,
              'provider_event_identity_present', (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL),
              'diagnostic_terminal_no_money_count', v_diagnostic_terminal_no_money_count,
              'provider_signature_valid', v_provider_signature_valid_confirmed,
              'webhook_receipt_ok', v_webhook_receipt_ok,
              'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
              'scope_is_full', v_scope_is_full,
              'strong_mapping_confirmed', v_strong_mapping_confirmed,
              'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
              'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
              'source_bank_event_final_paid', v_source_bank_event_final_paid,
              'source_bank_event_pending', v_source_bank_event_pending
            )::text;
  END IF;

  IF v_is_system_request AND v_strong_provider_evidence IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SYSTEM_REQUIRES_STRONG_PROVIDER_EVIDENCE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SYSTEM_REQUIRES_STRONG_PROVIDER_EVIDENCE',
              'confirmation_json', v_confirmation_json,
              'source', v_source_text,
              'provider_key_present', v_provider_key_text IS NOT NULL,
              'provider_event_identity_present', (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL),
              'diagnostic_terminal_no_money_count', v_diagnostic_terminal_no_money_count,
              'provider_signature_valid', v_provider_signature_valid_confirmed,
              'webhook_receipt_ok', v_webhook_receipt_ok,
              'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
              'scope_is_full', v_scope_is_full,
              'strong_mapping_confirmed', v_strong_mapping_confirmed,
              'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
              'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
              'source_bank_event_final_paid', v_source_bank_event_final_paid,
              'source_bank_event_pending', v_source_bank_event_pending
            )::text;
  END IF;

  IF v_is_system_request IS NOT TRUE AND v_source_is_provider IS NOT TRUE AND v_strong_provider_evidence IS NOT TRUE AND v_manual_confirmation_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_MANUAL_CONFIRMATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_MANUAL_CONFIRMATION_REQUIRED',
              'required_fields', jsonb_build_array('provider_checked', 'no_payment_made', 'terminal_no_money_confirmed', 'will_not_later_be_paid', 'provider_reference_or_audit_note')
            )::text;
  END IF;

  v_correction_kind := CASE
    WHEN v_strong_provider_evidence THEN 'NO_MONEY_UNWIND'
    ELSE 'MANUAL_EVIDENCE_NO_MONEY'
  END;

  v_effective_selection_json := v_selection_json
    || jsonb_build_object(
      'requested_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
      'correction_kind', v_correction_kind,
      'scope_type', v_scope_type,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'expected_pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)
    )
    || jsonb_build_object(
      'candidate_ids', COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb),
      'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb)
    );

  v_selection_hash := md5(v_effective_selection_json::text);
  v_idempotency_key := COALESCE(NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''), md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', v_selection_hash,
    'action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
    'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
    'provider_event_key', v_provider_event_key_text,
    'provider_event_id', v_provider_event_id_text,
    'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
    'provider_transaction_id', v_provider_transaction_id_text,
    'provider_request_id', v_provider_request_id_text,
    'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
    'source', v_source_text
  )::text));

  SELECT GREATEST(COALESCE(settings_row.payment_authoriser_quantity, 1), 1)
  INTO v_required_quantity
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_required_quantity := GREATEST(COALESCE(v_required_quantity, 1), 1);

  v_plan_json := jsonb_build_object(
    'classification', v_lifecycle_state,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', COALESCE(v_diagnostic_json -> 'finance_scope_json', '{}'::jsonb),
    'provider_evidence', COALESCE(v_diagnostic_json -> 'provider_evidence_summary_json', '{}'::jsonb),
    'terminal_no_money_evidence_json', COALESCE(v_diagnostic_json -> 'terminal_no_money_evidence_json', '{}'::jsonb),
    'carry_forward_blockers', v_carry_forward_blockers,
    'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'work_expansion_plan', jsonb_build_object('work_unit', CASE WHEN jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0 THEN 'TRANSFER' ELSE 'CANDIDATE_PAYEE' END, 'chunk_size', 50),
    'idempotency_key', v_idempotency_key,
    'provider_event_key', v_provider_event_key_text,
    'provider_event_id', v_provider_event_id_text,
    'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
    'provider_transaction_id', v_provider_transaction_id_text,
    'provider_request_id', v_provider_request_id_text,
    'strong_provider_evidence', v_strong_provider_evidence,
    'strong_mapping_confirmed', v_strong_mapping_confirmed,
    'webhook_receipt_ok', v_webhook_receipt_ok,
    'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
    'scope_is_full', v_scope_is_full,
    'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
    'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
    'source_bank_event_final_paid', v_source_bank_event_final_paid,
    'source_bank_event_pending', v_source_bank_event_pending,
    'manual_confirmation_ok', v_manual_confirmation_ok
  );

  v_plan_hash := md5(v_plan_json::text);

  v_accepted_resolution_json := jsonb_build_object(
    'accepted_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
    'actor_kind', CASE WHEN v_is_system_request THEN 'SYSTEM' ELSE 'USER' END,
    'accepted_at_utc', now(),
    'accepted_by_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
    'reason', v_reason,
    'manual_confirmation_reference_text', v_manual_confirmation_reference_text,
    'confirmation_json', v_confirmation_json,
    'diagnostic_json', v_diagnostic_json,
    'carry_forward_blockers', v_carry_forward_blockers,
    'idempotency_key', v_idempotency_key
  );

  v_accepted_resolution_hash := md5(v_accepted_resolution_json::text);

  SELECT request_rows.*
  INTO v_existing_request
  FROM public.pay_payment_correction_requests AS request_rows
  WHERE request_rows.pay_batch_id = p_pay_batch_id
    AND request_rows.selection_hash = v_selection_hash
    AND request_rows.correction_kind = v_correction_kind
    AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
  ORDER BY request_rows.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.pay_payment_correction_requests AS request_to_authorise
    SET status = CASE WHEN request_to_authorise.status IN ('REQUESTED', 'AWAITING_AUTHORISATION') THEN 'AUTHORISED' ELSE request_to_authorise.status END,
        approved_count = GREATEST(COALESCE(request_to_authorise.approved_count, 0), COALESCE(request_to_authorise.required_quantity, v_required_quantity, 1)),
        authorised_at_utc = COALESCE(request_to_authorise.authorised_at_utc, now()),
        accepted_resolution_json = COALESCE(request_to_authorise.accepted_resolution_json, v_accepted_resolution_json),
        accepted_resolution_hash = COALESCE(request_to_authorise.accepted_resolution_hash, v_accepted_resolution_hash),
        updated_at_utc = now()
    WHERE request_to_authorise.id = v_existing_request.id
    RETURNING request_to_authorise.*
    INTO v_request;
  ELSE
    BEGIN
      INSERT INTO public.pay_payment_correction_requests (
        pay_batch_id,
        correction_kind,
        status,
        requested_by_user_id,
        requested_at_utc,
        required_quantity,
        approved_count,
        golden_key_used,
        golden_key_user_id,
        reason,
        selection_json,
        selection_hash,
        plan_json,
        plan_hash,
        accepted_resolution_json,
        accepted_resolution_hash,
        source_bank_event_id,
        auto_requested,
        created_at_utc,
        authorised_at_utc,
        applied_at_utc,
        cancelled_at_utc,
        updated_at_utc
      )
      VALUES (
        p_pay_batch_id,
        v_correction_kind,
        'AUTHORISED',
        CASE WHEN v_is_system_request THEN NULL::uuid ELSE p_actor_user_id END,
        now(),
        v_required_quantity,
        v_required_quantity,
        false,
        NULL::uuid,
        v_reason,
        v_effective_selection_json,
        v_selection_hash,
        v_plan_json,
        v_plan_hash,
        v_accepted_resolution_json,
        v_accepted_resolution_hash,
        v_source_bank_event_id,
        v_is_system_request,
        now(),
        now(),
        NULL::timestamptz,
        NULL::timestamptz,
        now()
      )
      RETURNING public.pay_payment_correction_requests.*
      INTO v_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_request.id,
        p_pay_batch_id,
        CASE WHEN v_is_system_request THEN 'SYSTEM' ELSE 'USER' END,
        CASE WHEN v_is_system_request THEN NULL::uuid ELSE p_actor_user_id END,
        'REQUEST',
        now(),
        v_reason,
        NULL::jsonb,
        to_jsonb(v_request),
        jsonb_build_object(
          'requested_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
          'correction_kind', v_correction_kind,
          'selection_hash', v_selection_hash,
          'idempotency_key', v_idempotency_key,
          'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
          'source', v_source_text
        )
      );
    EXCEPTION WHEN unique_violation THEN
      SELECT request_rows.*
      INTO v_request
      FROM public.pay_payment_correction_requests AS request_rows
      WHERE request_rows.pay_batch_id = p_pay_batch_id
        AND request_rows.selection_hash = v_selection_hash
        AND request_rows.correction_kind = v_correction_kind
        AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
      ORDER BY request_rows.created_at_utc
      LIMIT 1
      FOR UPDATE;
    END;
  END IF;

  v_expand_result := public.pay_payment_correction_expand_work(v_request.id, p_actor_user_id);
  v_process_result := public.pay_payment_correction_process_chunk(v_request.id, 50, 'confirm-no-money-unwind', p_actor_user_id);
  v_grouped_alert_updates := COALESCE(v_process_result -> 'grouped_alert_updates', '[]'::jsonb);
  v_is_complete := COALESCE((v_process_result ->> 'complete')::boolean, false);

  v_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id,
    'PAYMENT_CONFIRM_NO_MONEY_AND_UNWIND',
    'pay_payment_confirm_no_money_and_unwind',
    jsonb_build_object(
      'correction_request_id', v_request.id::text,
      'selection_hash', v_selection_hash,
      'payment_lifecycle_state', v_lifecycle_state,
      'provider_failure_reason_group', v_diagnostic_json ->> 'provider_failure_reason_group',
      'progress', v_process_result
    ),
    true,
    true,
    COALESCE(jsonb_array_length(v_grouped_alert_updates), 0) > 0 OR v_is_complete IS NOT TRUE,
    true
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'progress_completed', COALESCE((v_process_result -> 'totals' ->> 'applied')::integer, COALESCE((v_process_result ->> 'applied')::integer, 0)),
    'progress_total', COALESCE((v_process_result -> 'totals' ->> 'total')::integer, 0),
    'is_complete', v_is_complete,
    'released_reservation_count', COALESCE((v_process_result ->> 'released_reservations')::integer, 0),
    'restored_finance_component_count', COALESCE((v_process_result ->> 'restored_finance_components')::integer, 0),
    'voided_transfer_count', COALESCE((v_process_result ->> 'updated_transfer_count')::integer, 0),
    'voided_item_count', COALESCE((v_process_result ->> 'applied')::integer, 0),
    'carry_forward_created_count', COALESCE((v_process_result ->> 'carry_forward_created')::integer, 0),
    'carry_forward_existing_count', COALESCE((v_process_result ->> 'carry_forward_existing')::integer, 0),
    'carry_forward_released_count', COALESCE((v_process_result ->> 'carry_forward_released')::integer, 0),
    'freshness_dirty_result', COALESCE(v_process_result -> 'freshness_dirty_result', '{}'::jsonb),
    'blocked_work_items', COALESCE(v_process_result -> 'blocked_work_items', '[]'::jsonb),
    'diagnostic_json', v_diagnostic_json,
    'expand_result', v_expand_result,
    'process_result', v_process_result,
    'workbench_refresh_status', COALESCE(NULLIF(v_process_result->>'workbench_refresh_status', ''), 'NOT_REQUIRED'),
    'workbench_refresh_queued_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_queued_count', '')::integer, 0),
    'workbench_refresh_deferred_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_deferred_count', '')::integer, 0),
    'workbench_refresh_failed_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_failed_count', '')::integer, 0),
    'workbench_refresh_job_ids', COALESCE(v_process_result->'workbench_refresh_job_ids', '[]'::jsonb),
    'requires_workbench_session', lower(BTRIM(COALESCE(v_process_result->>'requires_workbench_session', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'workbench_refresh', COALESCE(v_process_result->'workbench_refresh', jsonb_build_object(
      'status', COALESCE(NULLIF(v_process_result->>'workbench_refresh_status', ''), 'NOT_REQUIRED'),
      'queued_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_queued_count', '')::integer, 0),
      'deferred_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_deferred_count', '')::integer, 0),
      'failed_count', COALESCE(NULLIF(v_process_result->>'workbench_refresh_failed_count', '')::integer, 0),
      'job_ids', COALESCE(v_process_result->'workbench_refresh_job_ids', '[]'::jsonb),
      'requires_workbench_session', lower(BTRIM(COALESCE(v_process_result->>'requires_workbench_session', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    )),
    'live_signal', v_signal_result,
    'grouped_alert_summary_impact', v_grouped_alert_updates
  );
END;
$function$;

-- pay_payment_correction_authorise(uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_authorise(p_correction_request_id uuid, p_actor_user_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_action text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_action, ''))
  );
  v_pay_batch_id uuid;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_actor public.tms_users%ROWTYPE;
  v_guard jsonb;
  v_before_request jsonb;
  v_after_request jsonb;
  v_new_approved_count integer;
  v_selected_candidate_count integer;
  v_selected_active_item_count integer;
  v_selected_amount_pence bigint;
  v_old_auth_request_ids jsonb := '[]'::jsonb;
  v_old_schedule_kind text;
  v_old_scheduled_at_utc timestamptz;
  v_requested_action text;
  v_active_scope_hash text;
BEGIN
  IF p_correction_request_id IS NULL OR p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_AUTHORISE_IDENTIFIERS_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_AUTHORISE_IDENTIFIERS_REQUIRED'
      )::text;
  END IF;

  IF v_action NOT IN (
    'AUTHORISE',
    'USE_GOLDEN_KEY',
    'REJECT',
    'CANCEL'
  ) THEN
    RAISE EXCEPTION 'UNSUPPORTED_PAYMENT_CORRECTION_AUTHORISE_ACTION'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'UNSUPPORTED_PAYMENT_CORRECTION_AUTHORISE_ACTION',
        'action', p_action
      )::text;
  END IF;

  SELECT request_lookup.pay_batch_id
  INTO v_pay_batch_id
  FROM public.pay_payment_correction_requests AS request_lookup
  WHERE request_lookup.id = p_correction_request_id;

  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND',
        'correction_request_id', p_correction_request_id
      )::text;
  END IF;

  v_guard := private.pay_payment_mutation_guard_v1(
    v_pay_batch_id,
    p_correction_request_id,
    'CORRECTION_APPLY'
  );
  IF coalesce((v_guard->>'blocked')::boolean, true) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_GATE_OWNER_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', coalesce(
          v_guard->>'code',
          'PAYMENT_CORRECTION_GATE_OWNER_MISMATCH'
        ),
        'message', v_guard->>'message'
      )::text;
  END IF;

  SELECT request_row.*
  INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;

  IF v_request.status IN (
    'APPLIED',
    'APPLIED_WITH_BLOCKERS',
    'BLOCKED',
    'FAILED',
    'REJECTED',
    'CANCELLED'
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'request_id', v_request.id,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'action', v_action,
      'status', v_request.status,
      'request_status', v_request.status,
      'operation_id', (
        SELECT operation_row.id
        FROM public.banking_pay_operations AS operation_row
        WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
          AND operation_row.input_json->>'correction_request_id'
              = v_request.id::text
        ORDER BY operation_row.created_at_utc DESC
        LIMIT 1
      ),
      'operation_status', (
        SELECT operation_row.status
        FROM public.banking_pay_operations AS operation_row
        WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
          AND operation_row.input_json->>'correction_request_id'
              = v_request.id::text
        ORDER BY operation_row.created_at_utc DESC
        LIMIT 1
      ),
      'operation_phase', (
        SELECT operation_row.phase
        FROM public.banking_pay_operations AS operation_row
        WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
          AND operation_row.input_json->>'correction_request_id'
              = v_request.id::text
        ORDER BY operation_row.created_at_utc DESC
        LIMIT 1
      ),
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'old_authorisation_invalidated',
        v_request.plan_json->>'old_authorisation_invalidated_at_utc'
          IS NOT NULL,
      'old_schedule_invalidated',
        v_request.plan_json->>'old_schedule_invalidated_at_utc'
          IS NOT NULL,
      'batch_status', (
        SELECT terminal_batch.status
        FROM public.pay_batches AS terminal_batch
        WHERE terminal_batch.id = v_request.pay_batch_id
      ),
      'gate_active', false,
      'display_message', 'This cancellation request is already complete.',
      'continuation', pg_catalog.jsonb_build_object(
        'required', false, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', v_operation.phase, 'run_after_utc', v_operation.run_after_utc,
        'reason', 'REQUEST_ALREADY_TERMINAL', 'successor_relation', 'NONE',
        'requires_user_action', false, 'terminal', true
      ),
      'code', 'REQUEST_ALREADY_TERMINAL'
    );
  END IF;

  IF v_request.status NOT IN (
    'REQUESTED',
    'AWAITING_AUTHORISATION',
    'AUTHORISED'
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISABLE'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISABLE',
        'status', v_request.status
      )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_request.pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_BATCH_NOT_FOUND'
      )::text;
  END IF;

  SELECT actor_row.*
  INTO v_actor
  FROM public.tms_users AS actor_row
  WHERE actor_row.id = p_actor_user_id;

  IF NOT FOUND OR coalesce(v_actor.is_active, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_AUTHORISER_NOT_ACTIVE'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PERMISSION_DENIED'
      )::text;
  END IF;

  IF v_action = 'AUTHORISE'
     AND coalesce(v_actor.payment_authoriser, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'ACTOR_IS_NOT_PAYMENT_AUTHORISER'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PERMISSION_DENIED'
      )::text;
  END IF;

  IF v_action = 'USE_GOLDEN_KEY'
     AND coalesce(v_actor.payment_golden_key, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'ACTOR_DOES_NOT_HAVE_PAYMENT_GOLDEN_KEY'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PERMISSION_DENIED'
      )::text;
  END IF;

  IF v_action = 'AUTHORISE'
     AND p_actor_user_id = v_request.requested_by_user_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_MAKER_CHECKER_VIOLATION'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'MAKER_CHECKER_VIOLATION'
      )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_actions AS existing_action
    WHERE existing_action.correction_request_id = v_request.id
      AND existing_action.actor_user_id = p_actor_user_id
      AND existing_action.action IN (
        'AUTHORISE',
        'USE_GOLDEN_KEY',
        'REJECT',
        'CANCEL'
      )
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_DUPLICATE_AUTHORISER'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'DUPLICATE_AUTHORISER'
      )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND operation_row.pay_batch_id = v_request.pay_batch_id
    AND operation_row.input_json->>'correction_request_id'
        = v_request.id::text
  ORDER BY operation_row.created_at_utc DESC, operation_row.id DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_operation.status IN (
    'COMPLETE',
    'FAILED',
    'CANCELLED'
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'OPERATION_MISMATCH'
      )::text;
  END IF;

  v_before_request := pg_catalog.to_jsonb(v_request);

  IF v_action IN ('REJECT', 'CANCEL') THEN
    UPDATE public.pay_payment_correction_requests AS terminal_request
    SET status = CASE
          WHEN v_action = 'REJECT' THEN 'REJECTED'
          ELSE 'CANCELLED'
        END,
        cancelled_at_utc = CASE
          WHEN v_action = 'CANCEL' THEN
            coalesce(terminal_request.cancelled_at_utc, v_now)
          ELSE terminal_request.cancelled_at_utc
        END,
        reauth_proof_hash = NULL,
        reauth_expires_at_utc = NULL,
        reauth_consumed_at_utc =
          coalesce(terminal_request.reauth_consumed_at_utc, v_now),
        updated_at_utc = v_now
    WHERE terminal_request.id = v_request.id
    RETURNING terminal_request.* INTO v_request;

    UPDATE public.banking_pay_operations AS terminal_operation
    SET status = 'CANCELLED',
        phase = 'COMPLETE',
        runner_state = 'CANCELLED',
        requires_user_action = false,
        result_json = coalesce(
          terminal_operation.result_json,
          '{}'::jsonb
        ) || pg_catalog.jsonb_build_object(
          'code', CASE
            WHEN v_action = 'REJECT' THEN 'REQUEST_REJECTED'
            ELSE 'REQUEST_CANCELLED'
          END,
          'correction_request_id', v_request.id
        ),
        lease_owner = NULL,
        lease_expires_at_utc = NULL,
        locked_by = NULL,
        lock_expires_at_utc = NULL,
        run_after_utc = NULL,
        completed_at_utc = coalesce(
          terminal_operation.completed_at_utc,
          v_now
        ),
        updated_at_utc = v_now
    WHERE terminal_operation.id = v_operation.id;

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    ) VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      v_action,
      v_now,
      NULLIF(pg_catalog.btrim(coalesce(p_note, '')), ''),
      v_before_request,
      pg_catalog.to_jsonb(v_request),
      pg_catalog.jsonb_build_object(
        'code', CASE
          WHEN v_action = 'REJECT' THEN 'REQUEST_REJECTED'
          ELSE 'REQUEST_CANCELLED'
        END
      )
    );

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'request_id', v_request.id,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'operation_id', v_operation.id,
      'action', v_action,
      'status', v_request.status,
      'request_status', v_request.status,
      'operation_status', 'CANCELLED',
      'operation_phase', 'COMPLETE',
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'old_authorisation_invalidated', false,
      'old_schedule_invalidated', false,
      'batch_status', v_batch.status,
      'gate_active', false,
      'display_message', CASE
        WHEN v_action = 'REJECT' THEN 'Cancellation request rejected.'
        ELSE 'Cancellation request cancelled.'
      END,
      'authorised', false,
      'queued', false,
      'continuation', pg_catalog.jsonb_build_object(
        'required', false, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', 'COMPLETE', 'run_after_utc', NULL, 'reason', 'REQUEST_ENDED_BY_USER',
        'successor_relation', 'NONE', 'requires_user_action', false, 'terminal', true
      ),
      'code', CASE
        WHEN v_action = 'REJECT' THEN 'REQUEST_REJECTED'
        ELSE 'REQUEST_CANCELLED'
      END
    );
  END IF;

  v_active_scope_hash := private.pay_payment_correction_sha256_v1(
    pg_catalog.jsonb_build_object(
      'version', 1,
      'pay_batch_id', v_batch.id,
      'batch_status', v_batch.status,
      'total_bank_out_pence', pg_catalog.round(coalesce(v_batch.total_bank_out, 0) * 100)::bigint,
      'source_scope_change_generation', v_batch.source_scope_change_generation,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', v_batch.execution_committed_at_utc,
      'execution_intent_json', v_batch.execution_intent_json,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot,
      'rail_env_snapshot', v_batch.rail_env_snapshot,
      'freshness_validation_status', v_batch.freshness_validation_status,
      'freshness_result_hash', v_batch.freshness_result_hash,
      'freshness_scope_hash', v_batch.freshness_scope_hash,
      'schedule_kind', v_batch.schedule_kind,
      'scheduled_at_utc', v_batch.scheduled_at_utc,
      'active_authorisation', (
        SELECT pg_catalog.jsonb_build_object(
          'auth_request_id', auth_row.id,
          'state', auth_row.state,
          'required_quantity', auth_row.required_quantity,
          'schedule_kind', auth_row.schedule_kind,
          'scheduled_at_utc', auth_row.scheduled_at_utc,
          'execution_intent_json', auth_row.execution_intent_json
        )
        FROM public.pay_batch_auth_requests AS auth_row
        WHERE auth_row.pay_batch_id = v_batch.id
          AND auth_row.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
        ORDER BY auth_row.created_at_utc DESC, auth_row.id DESC
        LIMIT 1
      ),
      'active_candidate_items', (
        SELECT coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'pay_batch_candidate_id', candidate_scope.id,
              'candidate_id', candidate_scope.candidate_id,
              'settlement_status', candidate_scope.settlement_status,
              'net_bank_amount_pence', pg_catalog.round(
                coalesce(candidate_scope.net_bank_amount, 0) * 100
              )::bigint,
              'pay_batch_item_id', item_scope.id,
              'item_type', item_scope.item_type,
              'amount_ex_vat_pence', pg_catalog.round(
                coalesce(item_scope.amount_ex_vat, 0) * 100
              )::bigint,
              'amount_vat_pence', pg_catalog.round(
                coalesce(item_scope.amount_vat, 0) * 100
              )::bigint,
              'amount_inc_vat_pence', pg_catalog.round(
                coalesce(item_scope.amount_inc_vat, 0) * 100
              )::bigint,
              'frozen_component_key_type', item_scope.frozen_component_key_type,
              'frozen_component_key_value', item_scope.frozen_component_key_value,
              'frozen_component_classification', item_scope.frozen_component_classification,
              'frozen_source_basis_json', item_scope.frozen_source_basis_json,
              'operation_source_key', item_scope.operation_source_key,
              'reservation_id', item_scope.reservation_id,
              'finance_component_id', item_scope.finance_component_id,
              'pay_bank_transfer_id', item_scope.pay_bank_transfer_id
            )
            ORDER BY candidate_scope.id, item_scope.id
          ),
          '[]'::jsonb
        )
        FROM public.pay_batch_candidates AS candidate_scope
        JOIN public.pay_batch_items AS item_scope
          ON item_scope.pay_batch_candidate_id = candidate_scope.id
         AND coalesce(item_scope.is_voided, false) IS NOT TRUE
        WHERE candidate_scope.pay_batch_id = v_batch.id
      ),
      'provider_scope', (
        SELECT coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'pay_bank_transfer_id', transfer_scope.id,
              'status', transfer_scope.status,
              'rail_state', transfer_scope.rail_state,
              'request_id', transfer_scope.request_id,
              'rail_tx_id', transfer_scope.rail_tx_id,
              'transfer_group_key', transfer_scope.transfer_group_key,
              'amount_pence', pg_catalog.round(
                coalesce(transfer_scope.amount, 0) * 100
              )::bigint
            )
            ORDER BY transfer_scope.id
          ),
          '[]'::jsonb
        )
        FROM public.pay_bank_transfers AS transfer_scope
        WHERE transfer_scope.pay_batch_id = v_batch.id
      ),
      'provider_events', (
        SELECT coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'bank_event_id', event_scope.id,
              'pay_bank_transfer_id', event_scope.pay_bank_transfer_id,
              'normalised_state', event_scope.normalised_state,
              'movement_classification', event_scope.movement_classification,
              'correction_disposition', event_scope.correction_disposition,
              'mapping_status', event_scope.mapping_status,
              'event_time_utc', event_scope.event_time_utc,
              'provider_request_id', event_scope.provider_request_id,
              'provider_transaction_id', event_scope.provider_transaction_id
            )
            ORDER BY event_scope.id
          ),
          '[]'::jsonb
        )
        FROM public.pay_bank_transfer_events AS event_scope
        WHERE event_scope.pay_batch_id = v_batch.id
      ),
      'candidate_count', (
        SELECT pg_catalog.count(*)
        FROM public.pay_batch_candidates AS candidate_row
        WHERE candidate_row.pay_batch_id = v_batch.id
      ),
      'active_item_count', (
        SELECT pg_catalog.count(*)
        FROM public.pay_batch_items AS item_row
        JOIN public.pay_batch_candidates AS candidate_row
          ON candidate_row.id = item_row.pay_batch_candidate_id
        WHERE candidate_row.pay_batch_id = v_batch.id
          AND coalesce(item_row.is_voided, false) IS NOT TRUE
      ),
      'latest_request_update', (
        SELECT pg_catalog.max(other_request.updated_at_utc)
        FROM public.pay_payment_correction_requests AS other_request
        WHERE other_request.pay_batch_id = v_batch.id
          AND other_request.id <> v_request.id
          AND other_request.status NOT IN ('PLANNING', 'PLANNED')
      ),
      'latest_provider_event', (
        SELECT pg_catalog.max(event_row.received_at_utc)
        FROM public.pay_bank_transfer_events AS event_row
        WHERE event_row.pay_batch_id = v_batch.id
      )
    )
  );

  IF v_request.plan_json ->> 'active_batch_scope_hash'
       IS DISTINCT FROM v_active_scope_hash THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PROVIDER_OR_SCOPE_CHANGED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PROVIDER_STATE_CHANGED',
        'message', 'Payment status changed before final approval. Resolve the payment status or cancel this request.'
      )::text;
  END IF;

  SELECT
    pg_catalog.count(*)::integer,
    coalesce(pg_catalog.sum(member_row.active_item_count), 0)::integer,
    coalesce(
      pg_catalog.sum(
        pg_catalog.round(member_row.active_amount * 100)::bigint
      ),
      0
    )::bigint
  INTO
    v_selected_candidate_count,
    v_selected_active_item_count,
    v_selected_amount_pence
  FROM public.pay_payment_correction_request_candidates AS member_row
  WHERE member_row.correction_request_id = v_request.id;

  IF v_selected_candidate_count < 1
     OR v_selected_candidate_count IS DISTINCT FROM
          NULLIF(
            v_request.plan_json->>'selected_candidate_count',
            ''
          )::integer
     OR v_selected_active_item_count IS DISTINCT FROM
          NULLIF(
            v_request.plan_json->>'selected_active_item_count',
            ''
          )::integer
     OR v_selected_amount_pence IS DISTINCT FROM
          NULLIF(
            v_request.plan_json->>'selected_amount_pence',
            ''
          )::bigint
     OR EXISTS (
       SELECT 1
       FROM public.pay_payment_correction_request_candidates AS member_row
       LEFT JOIN public.pay_batch_items AS item_row
         ON item_row.id = ANY(member_row.pay_batch_item_ids)
        AND item_row.pay_batch_candidate_id =
            member_row.pay_batch_candidate_id
        AND coalesce(item_row.is_voided, false) IS NOT TRUE
       WHERE member_row.correction_request_id = v_request.id
       GROUP BY member_row.pay_batch_candidate_id,
                member_row.active_item_count
       HAVING pg_catalog.count(item_row.id)
              IS DISTINCT FROM member_row.active_item_count
     ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PLAN_STALE'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PLAN_STALE'
      )::text;
  END IF;

  v_requested_action := coalesce(
    v_request.plan_json->>'requested_action',
    v_request.selection_json->>'requested_action',
    v_request.selection_json->>'action'
  );

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_request_candidates AS member_row
    JOIN public.pay_batch_items AS item_row
      ON item_row.id = ANY(member_row.pay_batch_item_ids)
    JOIN public.pay_bank_transfer_events AS event_row
      ON event_row.pay_batch_id = v_request.pay_batch_id
     AND (
       event_row.pay_bank_transfer_id = item_row.pay_bank_transfer_id
       OR event_row.candidate_id = (
         SELECT candidate_row.candidate_id
         FROM public.pay_batch_candidates AS candidate_row
         WHERE candidate_row.id = member_row.pay_batch_candidate_id
       )
     )
    WHERE member_row.correction_request_id = v_request.id
      AND event_row.normalised_state IN (
        'COMPLETED',
        'PAID',
        'SETTLED'
      )
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PROVIDER_STATE_CHANGED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PROVIDER_STATE_CHANGED'
      )::text;
  END IF;

  INSERT INTO public.pay_payment_correction_actions (
    correction_request_id,
    pay_batch_id,
    actor_kind,
    actor_user_id,
    action,
    action_at_utc,
    note,
    before_json,
    after_json,
    metadata_json
  ) VALUES (
    v_request.id,
    v_request.pay_batch_id,
    'USER',
    p_actor_user_id,
    v_action,
    v_now,
    NULLIF(pg_catalog.btrim(coalesce(p_note, '')), ''),
    v_before_request,
    NULL,
    pg_catalog.jsonb_build_object(
      'approved_count_before',
        coalesce(v_request.approved_count, 0),
      'required_quantity',
        greatest(
          coalesce(v_request.required_quantity, 1),
          1
        )
    )
  );

  v_new_approved_count := CASE
    WHEN v_action = 'USE_GOLDEN_KEY' THEN
      greatest(
        coalesce(v_request.required_quantity, 1),
        1
      )
    ELSE
      least(
        coalesce(v_request.approved_count, 0) + 1,
        greatest(
          coalesce(v_request.required_quantity, 1),
          1
        )
      )
  END;

  IF v_new_approved_count <
       greatest(
         coalesce(v_request.required_quantity, 1),
         1
       ) THEN
    UPDATE public.pay_payment_correction_requests AS awaiting_request
    SET approved_count = v_new_approved_count,
        status = 'AWAITING_AUTHORISATION',
        updated_at_utc = v_now
    WHERE awaiting_request.id = v_request.id
    RETURNING awaiting_request.* INTO v_request;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'request_id', v_request.id,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'operation_id', v_operation.id,
      'action', v_action,
      'status', v_request.status,
      'request_status', v_request.status,
      'operation_status', v_operation.status,
      'operation_phase', v_operation.phase,
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'old_authorisation_invalidated', false,
      'old_schedule_invalidated', false,
      'batch_status', v_batch.status,
      'gate_active', true,
      'display_message', 'Authorisation recorded. Further approval is required.',
      'authorised', false,
      'queued', false,
      'continuation', pg_catalog.jsonb_build_object(
        'required', false, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', v_operation.phase, 'run_after_utc', v_operation.run_after_utc,
        'reason', 'AWAITING_AUTHORISATION', 'successor_relation', 'NONE',
        'requires_user_action', true, 'terminal', false
      ),
      'code', 'AUTHORISATION_RECORDED'
    );
  END IF;

  SELECT
    coalesce(
      pg_catalog.jsonb_agg(auth_request.id ORDER BY auth_request.created_at_utc),
      '[]'::jsonb
    )
  INTO v_old_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = v_request.pay_batch_id
    AND auth_request.state IN ('AWAITING', 'AUTHORISED');

  v_old_schedule_kind := v_batch.schedule_kind;
  v_old_scheduled_at_utc := v_batch.scheduled_at_utc;

  UPDATE public.pay_batch_auth_requests AS old_auth
  SET state = 'CANCELLED',
      finalised_at_utc = coalesce(
        old_auth.finalised_at_utc,
        v_now
      ),
      finalised_by_user_id = p_actor_user_id
  WHERE old_auth.pay_batch_id = v_request.pay_batch_id
    AND old_auth.state IN ('AWAITING', 'AUTHORISED');

  UPDATE public.pay_batch_auth_tokens AS old_token
  SET used_at_utc = coalesce(old_token.used_at_utc, v_now)
  WHERE old_token.auth_request_id IN (
    SELECT auth_request.id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.pay_batch_id = v_request.pay_batch_id
      AND auth_request.state = 'CANCELLED'
  )
    AND old_token.used_at_utc IS NULL;

  UPDATE public.pay_batches AS correction_batch
  SET status = CASE
        WHEN v_requested_action = 'DRAFT_CANCEL' THEN
          correction_batch.status
        ELSE 'AWAITING_AUTHORISATION'
      END,
      schedule_kind = NULL,
      scheduled_at_utc = NULL,
      scheduled_by_user_id = NULL,
      funding_account_ref = NULL,
      funds_warning_hours_json = NULL,
      execution_intent_json = coalesce(
        correction_batch.execution_intent_json,
        '{}'::jsonb
      ) || pg_catalog.jsonb_build_object(
        'correction_request_id', v_request.id,
        'old_authorisation_invalidated_at_utc', v_now,
        'old_schedule_invalidated_at_utc', v_now,
        'reauthorisation_required',
          v_requested_action <> 'DRAFT_CANCEL'
      )
  WHERE correction_batch.id = v_request.pay_batch_id;

  UPDATE public.pay_payment_correction_requests AS authorised_request
  SET approved_count = v_new_approved_count,
      golden_key_used = v_action = 'USE_GOLDEN_KEY',
      golden_key_user_id = CASE
        WHEN v_action = 'USE_GOLDEN_KEY' THEN p_actor_user_id
        ELSE authorised_request.golden_key_user_id
      END,
      status = 'AUTHORISED',
      authorised_at_utc = coalesce(
        authorised_request.authorised_at_utc,
        v_now
      ),
      plan_json = coalesce(
        authorised_request.plan_json,
        '{}'::jsonb
      ) || pg_catalog.jsonb_build_object(
        'old_authorisation_request_ids', v_old_auth_request_ids,
        'old_schedule_kind', v_old_schedule_kind,
        'old_scheduled_at_utc', v_old_scheduled_at_utc,
        'old_authorisation_invalidated_at_utc', v_now,
        'old_schedule_invalidated_at_utc', v_now
      ),
      updated_at_utc = v_now
  WHERE authorised_request.id = v_request.id
  RETURNING authorised_request.* INTO v_request;

  UPDATE public.banking_pay_operations AS correction_operation
  SET status = 'RUNNING',
      phase = 'EXPAND_WORK',
      runner_state = 'RUNNABLE',
      requires_user_action = false,
      run_after_utc = v_now,
      lease_owner = NULL,
      lease_expires_at_utc = NULL,
      locked_by = NULL,
      lock_expires_at_utc = NULL,
      progress_json = coalesce(
        correction_operation.progress_json,
        '{}'::jsonb
      ) || pg_catalog.jsonb_build_object(
        'phase', 'EXPAND_WORK',
        'authorised_at_utc', v_now,
        'approved_count', v_new_approved_count
      ),
      updated_at_utc = v_now
  WHERE correction_operation.id = v_operation.id;

  UPDATE public.pay_payment_correction_actions AS final_action
  SET after_json = pg_catalog.to_jsonb(v_request),
      metadata_json = coalesce(
        final_action.metadata_json,
        '{}'::jsonb
      ) || pg_catalog.jsonb_build_object(
        'code', 'CORRECTION_AUTHORISED',
        'operation_id', v_operation.id,
        'old_authorisation_request_ids', v_old_auth_request_ids,
        'old_schedule_kind', v_old_schedule_kind,
        'old_scheduled_at_utc', v_old_scheduled_at_utc,
        'old_authorisation_invalidated_at_utc', v_now,
        'old_schedule_invalidated_at_utc', v_now
      )
  WHERE final_action.correction_request_id = v_request.id
    AND final_action.actor_user_id = p_actor_user_id
    AND final_action.action = v_action
    AND final_action.action_at_utc = v_now;

  PERFORM public.banking_pay_batch_signal_touch(
    p_pay_batch_id := v_request.pay_batch_id,
    p_change_reason := 'PAYMENT_CORRECTION_AUTHORISED',
    p_change_source := 'pay_payment_correction_authorise',
    p_change_scope_json := pg_catalog.jsonb_build_object(
      'correction_request_id', v_request.id,
      'operation_id', v_operation.id,
      'requested_action', v_requested_action
    ),
    p_touch_payment_status := true,
    p_touch_correction_progress := true,
    p_touch_alerts := false,
    p_touch_overview := true
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'request_id', v_request.id,
    'correction_request_id', v_request.id,
    'pay_batch_id', v_request.pay_batch_id,
    'operation_id', v_operation.id,
    'action', v_action,
    'status', v_request.status,
    'request_status', v_request.status,
    'operation_status', 'RUNNING',
    'operation_phase', 'EXPAND_WORK',
    'approved_count', v_request.approved_count,
    'required_quantity', v_request.required_quantity,
    'old_authorisation_invalidated', true,
    'old_schedule_invalidated', true,
    'batch_status', CASE
      WHEN v_requested_action = 'DRAFT_CANCEL' THEN v_batch.status
      ELSE 'AWAITING_AUTHORISATION'
    END,
    'gate_active', true,
    'display_message', 'Cancellation approved and queued.',
    'authorised', true,
    'queued', true,
    'phase', 'EXPAND_WORK',
    'continuation', pg_catalog.jsonb_build_object(
      'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
      'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
      'phase', 'EXPAND_WORK', 'run_after_utc', v_now, 'reason', 'CORRECTION_AUTHORISED',
      'successor_relation', 'SELF', 'requires_user_action', false, 'terminal', false
    ),
    'code', 'CORRECTION_AUTHORISED'
  );
END;
$function$;

-- pay_payment_correction_expand_work(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_expand_work(p_correction_request_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.pay_payment_correction_requests%rowtype;
  v_batch public.pay_batches%rowtype;
  v_operation public.banking_pay_operations%rowtype;
  v_batch_id uuid;
  v_guard jsonb;
  v_last_ordinal bigint := 0;
  v_next_ordinal bigint := 0;
  v_page_count integer := 0;
  v_child_count integer := 0;
  v_work_count integer := 0;
  v_mismatch_count integer := 0;
  v_complete boolean := false;
  v_work_kind text;
  v_requested_action text;
  v_fast_draft_enabled boolean := false;
  v_fast_draft_result jsonb := '{}'::jsonb;
  v_fast_draft_after_candidate_id uuid := NULL::uuid;
  v_candidate_id uuid;
  v_candidate_scope_contract_version integer := 1;
  v_candidate_scope_contract_raw text;
  v_source_row_count_semantics text := 'FINANCIAL_AND_QUEUED_COMMUNICATIONS';
BEGIN
  IF p_correction_request_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  -- Resolve identifiers without taking row locks, then use the canonical
  -- mutation order: guard -> request -> batch -> operation.
  SELECT request_row.pay_batch_id
  INTO v_batch_id
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  v_guard := private.pay_payment_mutation_guard_v1(
    v_batch_id,
    p_correction_request_id,
    'CORRECTION_APPLY'
  );

  SELECT request_row.*
  INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;

  IF NOT FOUND OR v_request.status NOT IN ('AUTHORISED', 'EXPANDED') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_STATE_INVALID')::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_request.pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPAND_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND operation_row.input_json->>'correction_request_id' = p_correction_request_id::text
  ORDER BY operation_row.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_operation.phase IS DISTINCT FROM 'EXPAND_WORK' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPAND_OPERATION_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'OPERATION_MISMATCH')::text;
  END IF;

  IF v_operation.pay_batch_id IS DISTINCT FROM v_request.pay_batch_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPAND_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'OPERATION_MISMATCH')::text;
  END IF;

  IF p_actor_user_id IS NOT NULL
     AND p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id
     AND coalesce(v_request.auto_requested, false) IS NOT TRUE THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.tms_users AS actor_row
      WHERE actor_row.id = p_actor_user_id AND coalesce(actor_row.is_active, false)
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPAND_ACTOR_NOT_ALLOWED'
        USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object('code', 'PERMISSION_DENIED')::text;
    END IF;
  END IF;

  v_last_ordinal := coalesce(
    NULLIF(v_operation.progress_json->>'last_expanded_selection_ordinal', '')::bigint,
    0
  );
  v_work_kind := CASE WHEN v_request.correction_kind = 'NO_MONEY_UNWIND'
                      THEN 'NO_MONEY_UNWIND' ELSE 'PRE_BANK_CANCEL' END;
  v_requested_action := coalesce(
    v_request.plan_json->>'requested_action', v_request.selection_json->>'requested_action'
  );

  v_candidate_scope_contract_raw := NULLIF(
    BTRIM(COALESCE(v_request.plan_json->>'candidate_scope_contract_version', '')),
    ''
  );
  IF v_candidate_scope_contract_raw IS NULL OR v_candidate_scope_contract_raw = '1' THEN
    v_candidate_scope_contract_version := 1;
    v_source_row_count_semantics := 'FINANCIAL_AND_QUEUED_COMMUNICATIONS';
  ELSIF v_candidate_scope_contract_raw = '2' THEN
    v_candidate_scope_contract_version := 2;
    v_source_row_count_semantics := 'FINANCIAL_ONLY';
    IF v_request.plan_json->>'candidate_scope_hash_version' IS DISTINCT FROM '2'
       OR v_request.plan_json->>'source_row_count_semantics' IS DISTINCT FROM 'FINANCIAL_ONLY'
       OR v_request.plan_json->>'communication_cleanup_contract_version' IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH',
          'correction_request_id', p_correction_request_id,
          'candidate_scope_contract_version', v_candidate_scope_contract_raw
        )::text;
    END IF;
  ELSE
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED',
        'correction_request_id', p_correction_request_id,
        'candidate_scope_contract_version', v_candidate_scope_contract_raw
      )::text;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_draft_overlay_fast_cancel_v1_enabled,false)
  INTO v_fast_draft_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  IF COALESCE(v_fast_draft_enabled,false)
     AND UPPER(BTRIM(COALESCE(v_batch.status,''))) IN ('DRAFT','DRAFT_CREATED','CANCELLED')
     AND v_batch.source_workbench_session_id IS NOT NULL THEN
    v_fast_draft_after_candidate_id := CASE
      WHEN COALESCE(v_operation.progress_json->>'last_fast_draft_candidate_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_operation.progress_json->>'last_fast_draft_candidate_id')::uuid
      ELSE NULL::uuid END;

    v_fast_draft_result := private.pay_workbench_draft_overlay_remove_page_v1(
      p_correction_request_id,v_request.pay_batch_id,v_batch.source_workbench_session_id,
      v_fast_draft_after_candidate_id,100,500,p_actor_user_id,
      jsonb_build_object('requested_action',v_requested_action)
    );

    IF COALESCE((v_fast_draft_result->>'fast_route_eligible')::boolean,true) IS NOT TRUE THEN
      -- Admission occurs before any Draft mutation.  A rejected candidate page
      -- therefore falls through to the existing frozen financial correction
      -- route without partial voiding, reservation release or publication.
      UPDATE public.banking_pay_operations AS fallback_operation
      SET progress_json=COALESCE(fallback_operation.progress_json,'{}'::jsonb)
            || jsonb_build_object(
              'draft_overlay_fast_rejected',true,
              'draft_overlay_fast_rejection',v_fast_draft_result
            ),
          updated_at_utc=v_now
      WHERE fallback_operation.id=v_operation.id;
    ELSE
    UPDATE public.banking_pay_operations AS fast_operation
    SET progress_json=COALESCE(fast_operation.progress_json,'{}'::jsonb)
          || jsonb_build_object(
            'draft_overlay_fast',true,
            'last_fast_draft_candidate_id',v_fast_draft_result->>'last_candidate_id',
            'last_fast_draft_page',v_fast_draft_result
          ),
        phase=CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
          THEN 'EXPAND_WORK' ELSE 'COMPLETE' END,
        status=CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
          THEN 'RUNNING' ELSE 'COMPLETE' END,
        runner_state=CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
          THEN 'RUNNABLE' ELSE 'COMPLETE' END,
        run_after_utc=CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
          THEN v_now ELSE NULL END,
        completed_at_utc=CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
          THEN fast_operation.completed_at_utc ELSE v_now END,
        updated_at_utc=v_now
    WHERE fast_operation.id=v_operation.id;

    IF COALESCE((v_fast_draft_result->>'has_more')::boolean,false) IS NOT TRUE THEN
      UPDATE public.pay_payment_correction_requests AS fast_request
      SET status='APPLIED',applied_at_utc=COALESCE(fast_request.applied_at_utc,v_now),updated_at_utc=v_now
      WHERE fast_request.id=p_correction_request_id;

      INSERT INTO public.pay_payment_correction_actions(
        correction_request_id,pay_batch_id,actor_kind,actor_user_id,action,
        action_at_utc,note,before_json,after_json,metadata_json
      ) VALUES (
        p_correction_request_id,v_request.pay_batch_id,
        CASE WHEN p_actor_user_id IS NULL THEN 'SYSTEM' ELSE 'USER' END,
        p_actor_user_id,'APPLY',v_now,'DRAFT_OVERLAY_FAST_COMPLETE',NULL,
        jsonb_build_object('status','APPLIED'),v_fast_draft_result
      );

      -- The fast Draft route intentionally creates no financial work items, so
      -- it never enters process_chunk's ordinary terminal alert branch.  Emit
      -- the same request-scoped success event here from frozen correction
      -- membership.  The unique request event key makes lost-response replay
      -- idempotent and prevents per-candidate alert fanout.
      INSERT INTO public.banking_alert_success_events (
        pay_batch_id,
        alert_kind,
        event_key,
        payload_json,
        occurred_at_utc,
        expires_at_utc,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        v_request.pay_batch_id,
        'BATCH_CANCELLATION_SUCCESS',
        'CANCELLATION:' || p_correction_request_id::text,
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'contract_version', 'BANKING_ALERT_CANCELLATION_SUCCESS_V1',
          'correction_request_id', p_correction_request_id::text,
          'operation_id', v_operation.id::text,
          'pay_batch_id', v_request.pay_batch_id::text,
          'cancelled_payment_count', frozen_scope.payment_count,
          'cancelled_amount_pence', frozen_scope.amount_pence,
          'user_label', frozen_scope.payment_count::text || ' payment'
            || CASE WHEN frozen_scope.payment_count = 1 THEN '' ELSE 's' END
            || ' cancelled',
          'user_description', 'Cancellation completed for '
            || frozen_scope.payment_count::text || ' payment'
            || CASE WHEN frozen_scope.payment_count = 1 THEN '' ELSE 's' END
            || '. Banking Pay has been updated.',
          'required_user_action', 'Review or clear this Banking alert.',
          'stable_issue_key', v_request.pay_batch_id::text
            || ':BATCH_CANCELLATION_SUCCESS:' || p_correction_request_id::text,
          'dedupe_key', v_request.pay_batch_id::text
            || ':BATCH_CANCELLATION_SUCCESS:' || p_correction_request_id::text,
          'policy_x_source', 'FROZEN_CORRECTION_REQUEST_MEMBERSHIP'
        )),
        v_now,
        v_now + interval '365 days',
        v_now,
        v_now
      FROM (
        SELECT
          pg_catalog.count(*)::integer AS payment_count,
          pg_catalog.round(COALESCE(pg_catalog.sum(request_candidate.active_amount),0) * 100)::bigint AS amount_pence
        FROM public.pay_payment_correction_request_candidates AS request_candidate
        WHERE request_candidate.correction_request_id = p_correction_request_id
      ) AS frozen_scope
      WHERE frozen_scope.payment_count > 0
      ON CONFLICT (pay_batch_id, alert_kind, event_key) DO NOTHING;
    END IF;

    RETURN v_fast_draft_result || jsonb_build_object(
      'correction_request_id',p_correction_request_id,
      'operation_id',v_operation.id,
      'phase',CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
        THEN 'EXPAND_WORK' ELSE 'COMPLETE' END,
      'complete',COALESCE((v_fast_draft_result->>'has_more')::boolean,false) IS NOT TRUE,
      'processing_continues',COALESCE((v_fast_draft_result->>'has_more')::boolean,false),
      'code',CASE WHEN COALESCE((v_fast_draft_result->>'has_more')::boolean,false)
        THEN 'DRAFT_OVERLAY_FAST_PAGE' ELSE 'DRAFT_OVERLAY_FAST_COMPLETE' END
    );
    END IF;
  END IF;

  FOR v_candidate_id IN
    SELECT candidate_row.candidate_id
    FROM public.pay_payment_correction_request_candidates AS member_row
    JOIN public.pay_batch_candidates AS candidate_row ON candidate_row.id=member_row.pay_batch_candidate_id
    WHERE member_row.correction_request_id=p_correction_request_id
      AND member_row.selection_ordinal>v_last_ordinal
    ORDER BY member_row.selection_ordinal
    LIMIT 100
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_candidate_id),24062027));
  END LOOP;

  WITH page AS (
    SELECT member_row.*
    FROM public.pay_payment_correction_request_candidates AS member_row
    WHERE member_row.correction_request_id = p_correction_request_id
      AND member_row.selection_ordinal > v_last_ordinal
    ORDER BY member_row.selection_ordinal
    LIMIT 100
  ), resolved AS (
    SELECT page.*,candidate_row.candidate_id,
      COALESCE(
        v_request.selection_json->'cancellation_reversion_pre_request_authorities_v3'
          ->candidate_row.candidate_id::text,
        v_request.selection_json->'cancellation_reversion_pre_request_authorities_v2'
          ->candidate_row.candidate_id::text,
        page_authority.pre_request_authority
      ) AS pre_request_authority,
      COALESCE(
        page_authority.pre_request_authority->>'authority_digest',
        v_request.selection_json->'cancellation_reversion_pre_request_authorities_v3'
          ->candidate_row.candidate_id::text->>'authority_digest',
        v_request.selection_json->'cancellation_reversion_pre_request_authorities_v2'
          ->candidate_row.candidate_id::text->>'authority_digest'
      ) AS candidate_scope_hash_pre_request_authority_digest,
      COALESCE(
        v_operation.input_json->'cancellation_reversion_start_authorities_v2'
          ->candidate_row.candidate_id::text,
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'contract_version','CANCELLATION_REVERSION_START_AUTHORITY_V2',
          'correction_request_id',p_correction_request_id,
          'operation_id',v_operation.id,
          'candidate_id',candidate_row.candidate_id,
          'source_change_seq',COALESCE(candidate_counter.seq,0),
          'dirty_generation',COALESCE(candidate_counter.scope_change_generation,0),
          'start_exact',COALESCE((page_authority.pre_request_authority->>'pre_request_exact')::boolean,false)
            AND (
              (page_authority.pre_request_authority->>'source_change_seq')::bigint=COALESCE(candidate_counter.seq,0)
              AND (page_authority.pre_request_authority->>'dirty_generation')::bigint=COALESCE(candidate_counter.scope_change_generation,0)
              OR request_dirty.job_id IS NOT NULL
            ),
          'rejection_reason',CASE WHEN COALESCE((page_authority.pre_request_authority->>'pre_request_exact')::boolean,false)
            AND (((page_authority.pre_request_authority->>'source_change_seq')::bigint=COALESCE(candidate_counter.seq,0)
              AND (page_authority.pre_request_authority->>'dirty_generation')::bigint=COALESCE(candidate_counter.scope_change_generation,0))
              OR request_dirty.job_id IS NOT NULL) THEN NULL
            ELSE 'ECONOMIC_AUTHORITY_CHANGED_BEFORE_CANCELLATION_START' END,
          'pre_request_fence_digest',page_authority.pre_request_authority->>'authority_digest',
          'request_owned_dirty_job_id',request_dirty.job_id,
          'request_owned_dirty_proven',request_dirty.job_id IS NOT NULL,
          'fence_digest',pg_catalog.md5(
            p_correction_request_id::text||'|'||v_operation.id::text||'|'||candidate_row.candidate_id::text||'|'||
            COALESCE(candidate_counter.seq,0)::text||'|'||COALESCE(candidate_counter.scope_change_generation,0)::text||'|'||
            COALESCE(page_authority.pre_request_authority->>'authority_digest','')||'|'||
            COALESCE(request_dirty.job_id::text,'')||'|'||(request_dirty.job_id IS NOT NULL)::text||'|'||
            (COALESCE((page_authority.pre_request_authority->>'pre_request_exact')::boolean,false)
              AND (((page_authority.pre_request_authority->>'source_change_seq')::bigint=COALESCE(candidate_counter.seq,0)
                AND (page_authority.pre_request_authority->>'dirty_generation')::bigint=COALESCE(candidate_counter.scope_change_generation,0))
                OR request_dirty.job_id IS NOT NULL))::text||'|CANCELLATION_REVERSION_START_AUTHORITY_V2'
          )
        ))
      ) AS start_authority
    FROM page
    JOIN public.pay_batch_candidates AS candidate_row
      ON candidate_row.id=page.pay_batch_candidate_id
     AND candidate_row.pay_batch_id=v_request.pay_batch_id
    LEFT JOIN public.app_change_counters AS candidate_counter
      ON candidate_counter.entity_key='pay_candidate:'||candidate_row.candidate_id::text
    LEFT JOIN LATERAL (
      SELECT page_chunk.result_json->'cancellation_reversion_pre_request_authorities_v3'
               ->candidate_row.candidate_id::text AS pre_request_authority
      FROM public.banking_pay_operation_chunks AS page_chunk
      WHERE page_chunk.operation_id=v_operation.id
        AND page_chunk.phase='PREPARE_SELECTION'
        AND page_chunk.chunk_type='CANDIDATE_SCOPE'
        AND page_chunk.status='COMPLETE'
        AND page_chunk.result_json->'cancellation_reversion_pre_request_authorities_v3'
              ? candidate_row.candidate_id::text
      ORDER BY page_chunk.sequence_no
      LIMIT 1
    ) AS page_authority ON true
    LEFT JOIN LATERAL (
      SELECT dirty_job.id AS job_id
      FROM public.banking_pay_workbench_jobs AS dirty_job
      WHERE dirty_job.candidate_id=candidate_row.candidate_id
        AND dirty_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND dirty_job.status IN ('QUEUED','RUNNING','SUCCEEDED')
        AND dirty_job.scope_change_generation=COALESCE(candidate_counter.scope_change_generation,0)
        AND COALESCE(dirty_job.payload_json->>'source_change_seq','')=COALESCE(candidate_counter.seq,0)::text
        AND COALESCE(dirty_job.payload_json->>'correction_dirty_causal_contract_version','')
              ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
        AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
              ->candidate_row.candidate_id::text->>'correction_request_id','')=p_correction_request_id::text
        AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
              ->candidate_row.candidate_id::text->>'correction_operation_id','')=v_operation.id::text
        AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
              =COALESCE(dirty_job.payload_json->>'scope_change_tx_token','')
      ORDER BY dirty_job.updated_at_utc DESC NULLS LAST,dirty_job.created_at_utc DESC,dirty_job.id DESC
      LIMIT 1
    ) AS request_dirty ON true
  ), inserted AS (
    INSERT INTO public.pay_payment_correction_work_items (
      correction_request_id, pay_batch_id, pay_batch_candidate_id,
      pay_bank_transfer_id, candidate_id, umbrella_id, work_kind,
      selection_json, selection_hash, status, attempt_count, last_error,
      locked_at_utc, locked_by, created_at_utc, processed_at_utc, result_json
    )
    SELECT
      p_correction_request_id,
      v_request.pay_batch_id,
       resolved.pay_batch_candidate_id,
      (
        SELECT item_row.pay_bank_transfer_id
        FROM public.pay_batch_items AS item_row
         WHERE item_row.id = ANY(resolved.pay_batch_item_ids)
          AND item_row.pay_bank_transfer_id IS NOT NULL
        ORDER BY item_row.pay_bank_transfer_id
        LIMIT 1
      ),
      resolved.candidate_id,
      (
        SELECT item_row.umbrella_id
        FROM public.pay_batch_items AS item_row
         WHERE item_row.id = ANY(resolved.pay_batch_item_ids)
          AND item_row.umbrella_id IS NOT NULL
        ORDER BY item_row.umbrella_id
        LIMIT 1
      ),
      v_work_kind,
      pg_catalog.jsonb_build_object(
        'contract_version', 1,
        'scope_type', 'CANDIDATES',
        'work_unit', 'CANDIDATE',
        'requested_action', v_requested_action,
        'selection_ordinal', resolved.selection_ordinal,
        'pay_batch_candidate_ids', pg_catalog.jsonb_build_array(resolved.pay_batch_candidate_id),
        'pay_batch_item_ids', pg_catalog.to_jsonb(resolved.pay_batch_item_ids),
        'expected_pay_batch_item_ids', pg_catalog.to_jsonb(resolved.pay_batch_item_ids),
        'expected_item_count', resolved.active_item_count,
        'source_row_count', resolved.source_row_count,
        'amount_inc_vat', resolved.active_amount,
        'shared_instruction_scope_hash', resolved.shared_instruction_scope_hash,
        'eligibility_code_at_plan', resolved.eligibility_code_at_plan,
        'source_correction_request_id', p_correction_request_id,
        'cancellation_reversion_pre_request_authority',resolved.pre_request_authority,
        'candidate_scope_hash_pre_request_authority_digest',
          resolved.candidate_scope_hash_pre_request_authority_digest,
        'cancellation_reversion_start_authority_v2',resolved.start_authority
      ) || CASE WHEN v_candidate_scope_contract_version = 2 THEN
        pg_catalog.jsonb_build_object(
          'candidate_scope_contract_version', 2,
          'candidate_scope_hash_version', 2,
          'source_row_count_semantics', v_source_row_count_semantics,
          'communication_cleanup_contract_version', 1
        )
      ELSE '{}'::jsonb END,
      resolved.candidate_scope_hash,
      'PENDING', 0, NULL, NULL, NULL, v_now, NULL,
      pg_catalog.jsonb_build_object(
        'created_by', 'pay_payment_correction_expand_work',
         'selection_ordinal', resolved.selection_ordinal,
         'candidate_scope_hash', resolved.candidate_scope_hash,
         'candidate_scope_contract_version', v_candidate_scope_contract_version,
         'source_row_count_semantics', v_source_row_count_semantics
      )
    FROM resolved
    ON CONFLICT (correction_request_id, work_kind, selection_hash) DO NOTHING
    RETURNING id
  )
  SELECT pg_catalog.count(*)::integer INTO v_page_count FROM inserted;

  SELECT coalesce(pg_catalog.max(member_row.selection_ordinal), v_last_ordinal)
  INTO v_next_ordinal
  FROM public.pay_payment_correction_request_candidates AS member_row
  WHERE member_row.correction_request_id = p_correction_request_id
    AND member_row.selection_ordinal > v_last_ordinal
    AND member_row.selection_ordinal <= v_last_ordinal + 100;

  v_next_ordinal := greatest(v_next_ordinal, v_last_ordinal);
  v_complete := NOT EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_request_candidates AS remaining_member
    WHERE remaining_member.correction_request_id = p_correction_request_id
      AND remaining_member.selection_ordinal > v_next_ordinal
  );

  UPDATE public.banking_pay_operations AS progress_operation
  SET progress_json = coalesce(progress_operation.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'last_expanded_selection_ordinal', v_next_ordinal,
          'expanded_page_count', v_page_count
        ),
      updated_at_utc = v_now
  WHERE progress_operation.id = v_operation.id;

  IF v_complete THEN
    SELECT pg_catalog.count(*)::integer INTO v_child_count
    FROM public.pay_payment_correction_request_candidates AS member_row
    WHERE member_row.correction_request_id = p_correction_request_id;

    SELECT pg_catalog.count(*)::integer INTO v_work_count
    FROM public.pay_payment_correction_work_items AS work_row
    WHERE work_row.correction_request_id = p_correction_request_id;

    SELECT pg_catalog.count(*)::integer INTO v_mismatch_count
    FROM (
      (
        SELECT member_row.pay_batch_candidate_id, member_row.candidate_scope_hash
        FROM public.pay_payment_correction_request_candidates AS member_row
        WHERE member_row.correction_request_id = p_correction_request_id
        EXCEPT
        SELECT work_row.pay_batch_candidate_id, work_row.selection_hash
        FROM public.pay_payment_correction_work_items AS work_row
        WHERE work_row.correction_request_id = p_correction_request_id
      )
      UNION ALL
      (
        SELECT work_row.pay_batch_candidate_id, work_row.selection_hash
        FROM public.pay_payment_correction_work_items AS work_row
        WHERE work_row.correction_request_id = p_correction_request_id
        EXCEPT
        SELECT member_row.pay_batch_candidate_id, member_row.candidate_scope_hash
        FROM public.pay_payment_correction_request_candidates AS member_row
        WHERE member_row.correction_request_id = p_correction_request_id
      )
    ) AS membership_difference;

    v_mismatch_count := v_mismatch_count + (
      SELECT pg_catalog.count(*)::integer
      FROM public.pay_payment_correction_work_items AS work_row
      JOIN public.pay_payment_correction_request_candidates AS member_row
        ON member_row.correction_request_id = work_row.correction_request_id
       AND member_row.pay_batch_candidate_id = work_row.pay_batch_candidate_id
      JOIN public.pay_batch_candidates AS candidate_row
        ON candidate_row.id = member_row.pay_batch_candidate_id
       AND candidate_row.pay_batch_id = v_request.pay_batch_id
      WHERE work_row.correction_request_id = p_correction_request_id
        AND (
          work_row.candidate_id IS DISTINCT FROM candidate_row.candidate_id
          OR work_row.selection_hash IS DISTINCT FROM member_row.candidate_scope_hash
          OR work_row.selection_json->>'expected_item_count'
               IS DISTINCT FROM member_row.active_item_count::text
          OR work_row.selection_json->'expected_pay_batch_item_ids'
               IS DISTINCT FROM pg_catalog.to_jsonb(member_row.pay_batch_item_ids)
          OR (
            v_candidate_scope_contract_version = 2
            AND (
              work_row.selection_json->>'candidate_scope_contract_version' IS DISTINCT FROM '2'
              OR work_row.selection_json->>'candidate_scope_hash_version' IS DISTINCT FROM '2'
              OR work_row.selection_json->>'source_row_count_semantics' IS DISTINCT FROM 'FINANCIAL_ONLY'
              OR work_row.selection_json->>'communication_cleanup_contract_version' IS DISTINCT FROM '1'
            )
          )
        )
    );

    IF v_child_count < 1 OR v_child_count <> v_work_count OR v_mismatch_count <> 0 THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_MEMBERSHIP_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'WORK_MEMBERSHIP_MISMATCH',
          'child_count', v_child_count, 'work_count', v_work_count,
          'mismatch_count', v_mismatch_count
        )::text;
    END IF;

    UPDATE public.pay_payment_correction_requests AS expanded_request
    SET status = 'EXPANDED', updated_at_utc = v_now
    WHERE expanded_request.id = p_correction_request_id;

    UPDATE public.banking_pay_operations AS expanded_operation
    SET phase = 'PROCESS_CHUNKS', status = 'RUNNING', runner_state = 'RUNNABLE',
        run_after_utc = v_now, requires_user_action = false,
        progress_json = coalesce(expanded_operation.progress_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object('materialised_work_count', v_work_count),
        updated_at_utc = v_now
    WHERE expanded_operation.id = v_operation.id;

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
      action_at_utc, note, before_json, after_json, metadata_json
    ) VALUES (
      p_correction_request_id, v_request.pay_batch_id,
      CASE WHEN p_actor_user_id IS NULL THEN 'SYSTEM' ELSE 'USER' END,
      p_actor_user_id, 'EXPAND_WORK', v_now, NULL, NULL,
      pg_catalog.jsonb_build_object('status', 'EXPANDED'),
      pg_catalog.jsonb_build_object('work_count', v_work_count, 'membership_reconciled', true)
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true, 'correction_request_id', p_correction_request_id,
    'operation_id', v_operation.id, 'page_work_count', v_page_count,
    'inserted_count', v_page_count,
    'existing_count', greatest(
      (v_next_ordinal - v_last_ordinal)::integer - v_page_count,
      0
    ),
    'blocked_count', 0,
    'next_selection_ordinal', v_next_ordinal,
    'has_more', NOT v_complete,
    'deprecation_code', NULL,
    'last_selection_ordinal', v_next_ordinal, 'complete', v_complete,
    'phase', CASE WHEN v_complete THEN 'PROCESS_CHUNKS' ELSE 'EXPAND_WORK' END,
    'code', CASE WHEN v_complete THEN 'PAYMENT_CORRECTION_WORK_EXPANDED' ELSE 'PAYMENT_CORRECTION_WORK_PAGE_EXPANDED' END
  );
END;
$function$;

-- pay_payment_correction_expire_due_v1(integer)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_expire_due_v1(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_claimed_count integer := 0;
    v_expired_count integer := 0;
    v_skipped_count integer := 0;
    v_request record;
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 50 THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'checked_at_utc', v_now,
            'claimed_count', 0,
            'expired_count', 0,
            'skipped_count', 0,
            'code', 'EXPIRY_LIMIT_INVALID',
            'message', 'The expiry drain limit must be between 1 and 50.'
        );
    END IF;

    IF NOT pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended('BANKING_PAY_PAYMENT_CORRECTION_EXPIRY', 0)
    ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', true,
            'checked_at_utc', v_now,
            'claimed_count', 0,
            'expired_count', 0,
            'skipped_count', 0,
            'code', 'EXPIRY_OVERLAP_SKIPPED',
            'message', NULL
        );
    END IF;

    FOR v_request IN
        SELECT request_row.id,
               request_row.pay_batch_id,
               request_row.status,
               request_row.requested_by_user_id,
               request_row.requested_at_utc,
               request_row.authorised_at_utc
        FROM public.pay_payment_correction_requests AS request_row
        WHERE request_row.status IN (
                  'PLANNING',
                  'PLANNED',
                  'REQUESTED',
                  'AWAITING_AUTHORISATION'
              )
          AND request_row.requested_at_utc <= v_now - interval '24 hours'
          AND request_row.authorised_at_utc IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_work_items AS work_item
              WHERE work_item.correction_request_id = request_row.id
                AND work_item.status = 'APPLIED'
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_items AS correction_item
              WHERE correction_item.correction_request_id = request_row.id
                AND correction_item.status = 'APPLIED'
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_actions AS effect_action
              WHERE effect_action.correction_request_id = request_row.id
                AND (
                    pg_catalog.lower(COALESCE(effect_action.metadata_json->>'provider_outcome_changed', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR pg_catalog.lower(COALESCE(effect_action.metadata_json->>'settlement_outcome_changed', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR effect_action.metadata_json->>'effect_code' IN (
                        'PROVIDER_OUTCOME_CHANGED_BY_REQUEST',
                        'SETTLEMENT_OUTCOME_CHANGED_BY_REQUEST'
                    )
                )
          )
        ORDER BY request_row.requested_at_utc, request_row.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
    LOOP
        v_claimed_count := v_claimed_count + 1;

        UPDATE public.pay_payment_correction_requests AS request_to_expire
        SET status = 'CANCELLED',
            cancelled_at_utc = v_now,
            reauth_proof_hash = NULL,
            reauth_expires_at_utc = NULL,
            reauth_consumed_at_utc = NULL,
            updated_at_utc = v_now
        WHERE request_to_expire.id = v_request.id
          AND request_to_expire.status IN (
              'PLANNING',
              'PLANNED',
              'REQUESTED',
              'AWAITING_AUTHORISATION'
          )
          AND request_to_expire.authorised_at_utc IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_work_items AS work_item
              WHERE work_item.correction_request_id = request_to_expire.id
                AND work_item.status = 'APPLIED'
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_items AS correction_item
              WHERE correction_item.correction_request_id = request_to_expire.id
                AND correction_item.status = 'APPLIED'
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pay_payment_correction_actions AS effect_action
              WHERE effect_action.correction_request_id = request_to_expire.id
                AND (
                    pg_catalog.lower(COALESCE(effect_action.metadata_json->>'provider_outcome_changed', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR pg_catalog.lower(COALESCE(effect_action.metadata_json->>'settlement_outcome_changed', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR effect_action.metadata_json->>'effect_code' IN (
                        'PROVIDER_OUTCOME_CHANGED_BY_REQUEST',
                        'SETTLEMENT_OUTCOME_CHANGED_BY_REQUEST'
                    )
                )
          );

        IF NOT FOUND THEN
            v_skipped_count := v_skipped_count + 1;
            CONTINUE;
        END IF;

        INSERT INTO public.pay_payment_correction_actions (
            correction_request_id,
            pay_batch_id,
            actor_kind,
            actor_user_id,
            action,
            action_at_utc,
            note,
            before_json,
            after_json,
            metadata_json
        )
        SELECT
            v_request.id,
            v_request.pay_batch_id,
            'SYSTEM',
            NULL,
            'CANCEL',
            v_now,
            NULL,
            pg_catalog.jsonb_build_object('status', v_request.status),
            pg_catalog.jsonb_build_object('status', 'CANCELLED'),
            pg_catalog.jsonb_build_object(
                'audit_code', 'UNAPPROVED_REQUEST_EXPIRED',
                'expired_at_utc', v_now,
                'membership_retained', true
            )
        WHERE NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_actions AS existing_action
            WHERE existing_action.correction_request_id = v_request.id
              AND existing_action.action = 'CANCEL'
              AND existing_action.metadata_json ->> 'audit_code' = 'UNAPPROVED_REQUEST_EXPIRED'
        );

        UPDATE public.banking_pay_operations AS operation_to_cancel
        SET status = 'CANCELLED',
            phase = 'COMPLETE',
            result_json = COALESCE(operation_to_cancel.result_json, '{}'::jsonb)
                || pg_catalog.jsonb_build_object(
                    'code', 'UNAPPROVED_REQUEST_EXPIRED',
                    'correction_request_id', v_request.id,
                    'expired_at_utc', v_now,
                    'membership_retained', true
                ),
            completed_at_utc = COALESCE(operation_to_cancel.completed_at_utc, v_now),
            requires_user_action = false,
            locked_by = NULL,
            lock_expires_at_utc = NULL,
            lease_owner = NULL,
            lease_expires_at_utc = NULL,
            run_after_utc = NULL
        WHERE operation_to_cancel.operation_type = 'PAYMENT_CORRECTION'
          AND operation_to_cancel.input_json ->> 'correction_request_id' = v_request.id::text
          AND operation_to_cancel.status NOT IN ('COMPLETE', 'FAILED', 'CANCELLED');

        v_expired_count := v_expired_count + 1;
    END LOOP;

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'checked_at_utc', v_now,
        'claimed_count', v_claimed_count,
        'expired_count', v_expired_count,
        'skipped_count', v_skipped_count,
        'code', 'EXPIRY_DRAIN_OK',
        'message', NULL
    );
END
$function$;

-- pay_payment_correction_integrity_check_v1(uuid,uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_integrity_check_v1(p_correction_request_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_max_candidates integer DEFAULT 10000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '5000ms'
AS $function$
DECLARE
    v_checked_at_utc timestamptz := pg_catalog.statement_timestamp();
    v_request public.pay_payment_correction_requests%ROWTYPE;
    v_operation public.banking_pay_operations%ROWTYPE;
    v_operation_id uuid;
    v_selected_candidate_count integer := 0;
    v_selected_active_item_count integer := 0;
    v_selected_source_row_count integer := 0;
    v_selected_amount numeric(14,2) := 0;
    v_materialised_work_count integer := 0;
    v_terminal_work_count integer := 0;
    v_applied_candidate_count integer := 0;
    v_blocked_candidate_count integer := 0;
    v_failed_candidate_count integer := 0;
    v_source_item_expected_count integer := 0;
    v_source_item_applied_count integer := 0;
    v_reservation_release_expected_count integer := 0;
    v_reservation_release_actual_count integer := 0;
    v_active_candidate_count integer := 0;
    v_expected_active_total numeric(14,2) := 0;
    v_actual_active_total numeric(14,2) := 0;
    v_active_total_difference numeric(14,2) := 0;
    v_old_authorisation_invalidated boolean := true;
    v_old_schedule_invalidated boolean := true;
    v_actionable_cancelled_provider_scope_count integer := 0;
    v_unselected_before_hash text;
    v_unselected_after_hash text;
    v_unselected_unchanged boolean := true;
    v_refresh_group_total integer := 0;
    v_refresh_group_complete integer := 0;
    v_workbench_refresh_status text := 'NOT_STAGED';
    v_failure_categories jsonb := '[]'::jsonb;
    v_warnings jsonb := '[]'::jsonb;
    v_recalculated_selection_hash text;
    v_expected_selection_hash text;
    v_work_membership_mismatch boolean := false;
    v_terminal_request boolean := false;
    v_nonterminal_work_count integer := 0;
    v_old_auth_request_id uuid;
    v_expected_old_schedule_kind text;
    v_expected_old_scheduled_at timestamptz;
    v_blocked_scope_mismatch_count integer := 0;
    v_workbench_session_id uuid;
    v_refresh_candidate_count integer := 0;
    v_refresh_failed_count integer := 0;
    v_refresh_pending_count integer := 0;
    v_refresh_ready_count integer := 0;
    v_prepare_page_count integer := 0;
    v_finalise_page_count integer := 0;
    v_page_chain_mismatch_count integer := 0;
BEGIN
    IF p_correction_request_id IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'status', 'FAIL',
            'check_version', 1,
            'checked_at_utc', v_checked_at_utc,
            'correction_request_id', NULL,
            'operation_id', p_operation_id,
            'pay_batch_id', NULL,
            'failure_categories', pg_catalog.jsonb_build_array('REQUEST_NOT_FOUND'),
            'warnings', '[]'::jsonb
        );
    END IF;

    IF p_max_candidates IS NULL
       OR p_max_candidates < 1
       OR p_max_candidates > 10000 THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'status', 'FAIL',
            'check_version', 1,
            'checked_at_utc', v_checked_at_utc,
            'correction_request_id', p_correction_request_id,
            'operation_id', p_operation_id,
            'pay_batch_id', NULL,
            'failure_categories', pg_catalog.jsonb_build_array('CAPACITY_EXCEEDED'),
            'warnings', '[]'::jsonb
        );
    END IF;

    SELECT request_row.*
    INTO v_request
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.id = p_correction_request_id;

    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'status', 'FAIL',
            'check_version', 1,
            'checked_at_utc', v_checked_at_utc,
            'correction_request_id', p_correction_request_id,
            'operation_id', p_operation_id,
            'pay_batch_id', NULL,
            'failure_categories', pg_catalog.jsonb_build_array('REQUEST_NOT_FOUND'),
            'warnings', '[]'::jsonb
        );
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
      AND operation_row.pay_batch_id = v_request.pay_batch_id
      AND operation_row.input_json ->> 'correction_request_id'
          = v_request.id::text
      AND (p_operation_id IS NULL OR operation_row.id = p_operation_id)
    ORDER BY operation_row.created_at_utc DESC, operation_row.id DESC
    LIMIT 1;

    IF NOT FOUND THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('OPERATION_MISMATCH');
        v_operation_id := p_operation_id;
    ELSE
        v_operation_id := v_operation.id;
        IF p_operation_id IS NOT NULL
           AND v_operation.id IS DISTINCT FROM p_operation_id THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('OPERATION_MISMATCH');
        END IF;
    END IF;

    SELECT
        pg_catalog.count(*)::integer,
        COALESCE(pg_catalog.sum(member_row.active_item_count), 0)::integer,
        COALESCE(pg_catalog.sum(member_row.source_row_count), 0)::integer,
        COALESCE(pg_catalog.sum(member_row.active_amount), 0)::numeric(14,2)
    INTO
        v_selected_candidate_count,
        v_selected_active_item_count,
        v_selected_source_row_count,
        v_selected_amount
    FROM public.pay_payment_correction_request_candidates AS member_row
    WHERE member_row.correction_request_id = v_request.id;

    IF v_selected_candidate_count > p_max_candidates
       OR v_selected_active_item_count > 250000 THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('CAPACITY_EXCEEDED');
    END IF;

    IF v_selected_candidate_count
           IS DISTINCT FROM COALESCE(
               NULLIF(v_request.plan_json ->> 'selected_candidate_count', '')::integer,
               v_selected_candidate_count
           )
       OR v_selected_active_item_count
           IS DISTINCT FROM COALESCE(
               NULLIF(v_request.plan_json ->> 'selected_active_item_count', '')::integer,
               v_selected_active_item_count
           )
       OR pg_catalog.round(v_selected_amount * 100)::bigint
           IS DISTINCT FROM COALESCE(
               NULLIF(v_request.plan_json ->> 'selected_amount_pence', '')::bigint,
               pg_catalog.round(v_selected_amount * 100)::bigint
           ) THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('SELECTION_COUNT_MISMATCH');
    END IF;

    IF v_selected_candidate_count > 0 THEN
        v_recalculated_selection_hash := private.pay_payment_correction_sha256_v1(
            pg_catalog.jsonb_build_object(
                'version', 2,
                'pay_batch_id', v_request.pay_batch_id,
                'requested_action', COALESCE(
                    v_request.plan_json ->> 'requested_action',
                    v_request.selection_json ->> 'requested_action',
                    v_request.selection_json ->> 'action'
                ),
                'active_batch_scope_hash',
                    v_request.plan_json ->> 'active_batch_scope_hash',
                'selected_candidate_count', v_selected_candidate_count,
                'selected_active_item_count', v_selected_active_item_count,
                'selected_source_row_count', v_selected_source_row_count,
                'selected_amount_pence',
                    pg_catalog.round(v_selected_amount * 100)::bigint,
                'selected_chain_hash', v_request.plan_json->>'selected_chain_hash',
                'unselected_chain_hash', v_request.plan_json->>'unselected_chain_hash',
                'prepare_page_count', (v_request.plan_json->>'prepare_page_count')::integer
            )
        );
        v_expected_selection_hash := v_request.selection_hash;

        IF v_expected_selection_hash IS NULL
           OR v_recalculated_selection_hash IS DISTINCT FROM v_expected_selection_hash THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('SELECTION_HASH_MISMATCH');
        END IF;
    ELSIF v_request.status NOT IN ('PLANNING', 'CANCELLED', 'REJECTED') THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('SELECTION_COUNT_MISMATCH');
    END IF;

    WITH prepare_pages AS (
      SELECT chunk_row.sequence_no, chunk_row.result_json,
             pg_catalog.row_number() OVER (ORDER BY chunk_row.sequence_no)::integer AS expected_sequence,
             pg_catalog.lag(chunk_row.result_json->>'page_hash')
               OVER (ORDER BY chunk_row.sequence_no) AS previous_page_hash
      FROM public.banking_pay_operation_chunks AS chunk_row
      WHERE chunk_row.operation_id = v_operation_id
        AND chunk_row.phase = 'PREPARE_SELECTION'
        AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
        AND chunk_row.status = 'COMPLETE'
    )
    SELECT pg_catalog.count(*)::integer,
           pg_catalog.count(*) FILTER (
             WHERE sequence_no <> expected_sequence
                OR (sequence_no > 1 AND result_json->>'prior_page_hash'
                    IS DISTINCT FROM previous_page_hash)
           )::integer
    INTO v_prepare_page_count, v_page_chain_mismatch_count
    FROM prepare_pages;

    IF v_prepare_page_count > 200
       OR v_prepare_page_count IS DISTINCT FROM COALESCE(
            NULLIF(v_request.plan_json->>'prepare_page_count', '')::integer,
            v_prepare_page_count
          )
       OR v_page_chain_mismatch_count <> 0 THEN
      v_failure_categories := v_failure_categories
        || pg_catalog.jsonb_build_array('SELECTION_HASH_MISMATCH');
    END IF;

    WITH final_pages AS (
      SELECT chunk_row.sequence_no, chunk_row.result_json,
             pg_catalog.row_number() OVER (ORDER BY chunk_row.sequence_no)::integer AS expected_sequence,
             pg_catalog.lag(chunk_row.result_json->>'last_candidate_id')
               OVER (ORDER BY chunk_row.sequence_no) AS previous_last_candidate_id
      FROM public.banking_pay_operation_chunks AS chunk_row
      WHERE chunk_row.operation_id = v_operation_id
        AND chunk_row.phase = 'FINALISE'
        AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
        AND chunk_row.status = 'COMPLETE'
    )
    SELECT pg_catalog.count(*)::integer,
           pg_catalog.count(*) FILTER (
             WHERE sequence_no <> expected_sequence
                OR (sequence_no > 1 AND (result_json->>'first_candidate_id')::uuid
                    <= previous_last_candidate_id::uuid)
           )::integer
    INTO v_finalise_page_count, v_page_chain_mismatch_count
    FROM final_pages;

    IF v_finalise_page_count > 100 OR v_page_chain_mismatch_count <> 0 THEN
      v_failure_categories := v_failure_categories
        || pg_catalog.jsonb_build_array('WORK_MEMBERSHIP_MISMATCH');
    END IF;

    SELECT
        pg_catalog.count(*)::integer,
        pg_catalog.count(*) FILTER (
            WHERE work_row.status IN (
                'APPLIED',
                'SKIPPED',
                'BLOCKED',
                'FAILED_FINAL',
                'CANCELLED'
            )
        )::integer,
        pg_catalog.count(*) FILTER (
            WHERE work_row.status = 'APPLIED'
        )::integer,
        pg_catalog.count(*) FILTER (
            WHERE work_row.status = 'BLOCKED'
        )::integer,
        pg_catalog.count(*) FILTER (
            WHERE work_row.status = 'FAILED_FINAL'
        )::integer,
        pg_catalog.count(*) FILTER (
            WHERE work_row.status IN (
                'PENDING',
                'PROCESSING',
                'FAILED_RETRYABLE'
            )
        )::integer
    INTO
        v_materialised_work_count,
        v_terminal_work_count,
        v_applied_candidate_count,
        v_blocked_candidate_count,
        v_failed_candidate_count,
        v_nonterminal_work_count
    FROM public.pay_payment_correction_work_items AS work_row
    WHERE work_row.correction_request_id = v_request.id;

    SELECT EXISTS (
        (
            SELECT member_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_request_candidates AS member_row
            WHERE member_row.correction_request_id = v_request.id
            EXCEPT
            SELECT work_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_work_items AS work_row
            WHERE work_row.correction_request_id = v_request.id
        )
        UNION ALL
        (
            SELECT work_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_work_items AS work_row
            WHERE work_row.correction_request_id = v_request.id
            EXCEPT
            SELECT member_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_request_candidates AS member_row
            WHERE member_row.correction_request_id = v_request.id
        )
    )
    INTO v_work_membership_mismatch;

    IF v_request.status IN (
        'EXPANDED',
        'PROCESSING',
        'APPLIED',
        'APPLIED_WITH_BLOCKERS',
        'BLOCKED',
        'FAILED'
    )
       AND (
           v_materialised_work_count IS DISTINCT FROM v_selected_candidate_count
           OR v_work_membership_mismatch
       ) THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('WORK_MEMBERSHIP_MISMATCH');
    END IF;

    v_terminal_request := v_request.status IN (
        'APPLIED',
        'APPLIED_WITH_BLOCKERS',
        'BLOCKED',
        'FAILED',
        'REJECTED',
        'CANCELLED'
    );

    IF v_terminal_request AND v_nonterminal_work_count > 0 THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('NONTERMINAL_WORK_REMAINS');
    END IF;

    SELECT COALESCE(
        pg_catalog.sum(member_row.active_item_count),
        0
    )::integer
    INTO v_source_item_expected_count
    FROM public.pay_payment_correction_request_candidates AS member_row
    JOIN public.pay_payment_correction_work_items AS work_row
      ON work_row.correction_request_id = member_row.correction_request_id
     AND work_row.pay_batch_candidate_id = member_row.pay_batch_candidate_id
    WHERE member_row.correction_request_id = v_request.id
      AND work_row.status = 'APPLIED';

    SELECT pg_catalog.count(
        DISTINCT correction_item.pay_batch_item_id
    )::integer
    INTO v_source_item_applied_count
    FROM public.pay_payment_correction_items AS correction_item
    WHERE correction_item.correction_request_id = v_request.id
      AND correction_item.status = 'APPLIED';

    IF v_source_item_expected_count IS DISTINCT FROM v_source_item_applied_count THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('SOURCE_EVIDENCE_MISSING');
    END IF;

    SELECT
        pg_catalog.count(DISTINCT reservation_row.id)::integer,
        pg_catalog.count(DISTINCT reservation_row.id) FILTER (
            WHERE reservation_row.status = 'RELEASED'
              AND reservation_row.released_at_utc IS NOT NULL
        )::integer
    INTO
        v_reservation_release_expected_count,
        v_reservation_release_actual_count
    FROM public.pay_advance_reservations AS reservation_row
    JOIN public.pay_payment_correction_request_candidates AS member_row
      ON reservation_row.pay_batch_item_id = ANY(member_row.pay_batch_item_ids)
    JOIN public.pay_payment_correction_work_items AS work_row
      ON work_row.correction_request_id = member_row.correction_request_id
     AND work_row.pay_batch_candidate_id = member_row.pay_batch_candidate_id
    WHERE member_row.correction_request_id = v_request.id
      AND work_row.status = 'APPLIED'
      AND reservation_row.status IN ('RESERVED', 'COMMITTED', 'RELEASED')
      AND (
          reservation_row.status <> 'COMMITTED'
          OR reservation_row.settled_at_utc IS NULL
      );

    IF v_reservation_release_expected_count
           IS DISTINCT FROM v_reservation_release_actual_count THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('RESERVATION_RELEASE_MISMATCH');
    END IF;

    SELECT COALESCE(pg_catalog.sum(
             (chunk_row.result_json->>'active_candidate_count')::integer
           ), 0)::integer,
           (COALESCE(pg_catalog.sum(
             (chunk_row.result_json->>'active_net_amount_pence')::bigint
           ), 0)::numeric / 100)::numeric(14,2)
    INTO v_active_candidate_count, v_expected_active_total
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = v_operation_id
      AND chunk_row.phase = 'FINALISE'
      AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
      AND chunk_row.status = 'COMPLETE';

    IF v_terminal_request AND v_finalise_page_count > 0 THEN
        SELECT COALESCE(batch_row.total_bank_out, 0)::numeric(14,2)
        INTO v_actual_active_total
        FROM public.pay_batches AS batch_row
        WHERE batch_row.id = v_request.pay_batch_id;

        v_active_total_difference := pg_catalog.round(
            v_actual_active_total - v_expected_active_total,
            2
        );

        IF v_active_total_difference <> 0::numeric THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('ACTIVE_TOTAL_MISMATCH');
        END IF;
    ELSIF v_finalise_page_count > 0 THEN
        v_warnings := v_warnings
            || pg_catalog.jsonb_build_array('FINALISE_REDUCTION_IN_PROGRESS');
    END IF;

    v_unselected_before_hash := v_request.plan_json ->> 'unselected_scope_hash_before';
    v_unselected_after_hash := COALESCE(
        v_request.plan_json ->> 'unselected_scope_hash_after',
        v_request.plan_json #>> '{final_result,unselected_scope_hash_after}',
        v_operation.result_json ->> 'unselected_scope_hash_after'
    );

    IF v_unselected_before_hash IS NULL OR v_unselected_after_hash IS NULL THEN
        v_unselected_unchanged := false;
        IF v_terminal_request THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('UNSELECTED_SCOPE_CHANGED');
        ELSE
            v_warnings := v_warnings
                || pg_catalog.jsonb_build_array('UNSELECTED_SCOPE_HASH_NOT_YET_AVAILABLE');
        END IF;
    ELSE
        v_unselected_unchanged :=
            v_unselected_before_hash IS NOT DISTINCT FROM v_unselected_after_hash;
        IF NOT v_unselected_unchanged THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('UNSELECTED_SCOPE_CHANGED');
        END IF;
    END IF;

    SELECT COALESCE(pg_catalog.sum(
      (chunk_row.result_json->>'blocked_scope_mismatch_count')::integer
    ), 0)::integer
    INTO v_blocked_scope_mismatch_count
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = v_operation_id
      AND chunk_row.phase = 'FINALISE'
      AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
      AND chunk_row.status = 'COMPLETE';
    IF v_blocked_scope_mismatch_count > 0 THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('WORK_MEMBERSHIP_MISMATCH');
    END IF;

    BEGIN
        v_old_auth_request_id := NULLIF(
            v_request.plan_json ->> 'old_authorisation_request_id',
            ''
        )::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_old_auth_request_id := NULL;
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('OLD_AUTHORISATION_STILL_ACTIVE');
    END;

    IF v_request.authorised_at_utc IS NOT NULL
       AND v_old_auth_request_id IS NOT NULL THEN
        SELECT NOT EXISTS (
            SELECT 1
            FROM public.pay_batch_auth_requests AS auth_request
            WHERE auth_request.id = v_old_auth_request_id
              AND auth_request.state IN (
                  'AWAITING',
                  'REQUESTED',
                  'AUTHORISED',
                  'AUTHORIZED'
              )
        )
        INTO v_old_authorisation_invalidated;

        IF NOT v_old_authorisation_invalidated THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('OLD_AUTHORISATION_STILL_ACTIVE');
        END IF;
    END IF;

    v_expected_old_schedule_kind :=
        v_request.plan_json ->> 'old_schedule_kind';
    BEGIN
        v_expected_old_scheduled_at := NULLIF(
            v_request.plan_json ->> 'old_scheduled_at_utc',
            ''
        )::timestamptz;
    EXCEPTION WHEN invalid_datetime_format THEN
        v_expected_old_scheduled_at := NULL;
    END;

    IF v_request.authorised_at_utc IS NOT NULL
       AND (
           v_expected_old_schedule_kind IS NOT NULL
           OR v_expected_old_scheduled_at IS NOT NULL
       ) THEN
        SELECT
            batch_row.schedule_kind IS NULL
            AND batch_row.scheduled_at_utc IS NULL
        INTO v_old_schedule_invalidated
        FROM public.pay_batches AS batch_row
        WHERE batch_row.id = v_request.pay_batch_id;

        IF NOT v_old_schedule_invalidated THEN
            v_failure_categories := v_failure_categories
                || pg_catalog.jsonb_build_array('OLD_SCHEDULE_STILL_ACTIVE');
        END IF;
    END IF;

    SELECT pg_catalog.count(*)::integer
    INTO v_actionable_cancelled_provider_scope_count
    FROM public.pay_payment_correction_items AS correction_item
    JOIN public.banking_pay_operation_transfer_scope_items AS scope_item
      ON scope_item.pay_batch_item_id = correction_item.pay_batch_item_id
    JOIN public.banking_pay_operation_transfer_scope AS transfer_scope
      ON transfer_scope.id = scope_item.transfer_scope_id
    WHERE correction_item.correction_request_id = v_request.id
      AND correction_item.status = 'APPLIED'
      AND (
          COALESCE(transfer_scope.provider_submit_ready, false)
          OR transfer_scope.provider_submit_state IN (
              'READY',
              'CLAIMED',
              'SENDING',
              'SUBMIT_READY'
          )
      );

    IF v_actionable_cancelled_provider_scope_count > 0 THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array(
                'CANCELLED_PROVIDER_SCOPE_ACTIONABLE'
            );
    END IF;

    IF v_operation_id IS NOT NULL THEN
        SELECT
            pg_catalog.count(*)::integer,
            pg_catalog.count(*) FILTER (
                WHERE refresh_chunk.status = 'COMPLETE'
            )::integer
        INTO
            v_refresh_group_total,
            v_refresh_group_complete
        FROM public.banking_pay_operation_chunks AS refresh_chunk
        WHERE refresh_chunk.operation_id = v_operation_id
          AND refresh_chunk.phase = 'REFRESH_WORKBENCH'
          AND refresh_chunk.chunk_type = 'CANDIDATE_SCOPE';
    END IF;

    v_workbench_session_id := COALESCE(
        v_operation.workbench_session_id,
        (SELECT batch_row.source_workbench_session_id FROM public.pay_batches AS batch_row WHERE batch_row.id = v_request.pay_batch_id)
    );

    WITH refresh_candidates AS (
        SELECT DISTINCT (candidate_token.value #>> '{}')::uuid AS candidate_id
        FROM public.banking_pay_operation_chunks AS refresh_chunk
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
            COALESCE(refresh_chunk.payload_json->'candidate_ids', '[]'::jsonb)
        ) AS candidate_token(value)
        WHERE refresh_chunk.operation_id = v_operation_id
          AND refresh_chunk.phase = 'REFRESH_WORKBENCH'
          AND refresh_chunk.chunk_type = 'CANDIDATE_SCOPE'
          AND (candidate_token.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), candidate_freshness AS (
        SELECT refresh_candidate.candidate_id,
               pg_catalog.upper(COALESCE(candidate_state.status, 'MISSING')) AS candidate_state,
               candidate_state.pending_job_id,
               COALESCE(candidate_state.source_change_seq, 0) AS source_change_seq,
               pg_catalog.upper(COALESCE(latest_job.status, 'NONE')) AS job_status,
               COALESCE(latest_job.scope_change_generation, 0) AS job_generation
        FROM refresh_candidates AS refresh_candidate
        LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
          ON candidate_state.session_id = v_workbench_session_id
         AND candidate_state.candidate_id = refresh_candidate.candidate_id
        LEFT JOIN LATERAL (
            SELECT job_row.status, job_row.scope_change_generation
            FROM public.banking_pay_workbench_jobs AS job_row
            WHERE job_row.session_id = v_workbench_session_id
              AND job_row.candidate_id = refresh_candidate.candidate_id
            ORDER BY job_row.updated_at_utc DESC, job_row.id DESC
            LIMIT 1
        ) AS latest_job ON true
    )
    SELECT pg_catalog.count(*)::integer,
           pg_catalog.count(*) FILTER (WHERE candidate_freshness.candidate_state = 'FAILED' OR candidate_freshness.job_status IN ('FAILED', 'DEAD'))::integer,
           pg_catalog.count(*) FILTER (WHERE candidate_freshness.candidate_state = 'READY' AND candidate_freshness.pending_job_id IS NULL AND candidate_freshness.job_status IN ('NONE', 'SUCCEEDED') AND candidate_freshness.source_change_seq >= candidate_freshness.job_generation)::integer,
           pg_catalog.count(*) FILTER (WHERE NOT (candidate_freshness.candidate_state = 'FAILED' OR candidate_freshness.job_status IN ('FAILED', 'DEAD')) AND NOT (candidate_freshness.candidate_state = 'READY' AND candidate_freshness.pending_job_id IS NULL AND candidate_freshness.job_status IN ('NONE', 'SUCCEEDED') AND candidate_freshness.source_change_seq >= candidate_freshness.job_generation))::integer
    INTO v_refresh_candidate_count, v_refresh_failed_count, v_refresh_ready_count, v_refresh_pending_count
    FROM candidate_freshness;

    v_workbench_refresh_status := CASE
        WHEN v_refresh_group_total = 0 THEN 'NOT_STAGED'
        WHEN EXISTS (
            SELECT 1 FROM public.banking_pay_operation_chunks AS failed_refresh_chunk
            WHERE failed_refresh_chunk.operation_id = v_operation_id
              AND failed_refresh_chunk.phase = 'REFRESH_WORKBENCH'
              AND failed_refresh_chunk.status IN ('FAILED', 'FAILED_FINAL')
        ) OR v_refresh_failed_count > 0 THEN 'FAILED'
        WHEN v_refresh_group_complete < v_refresh_group_total THEN 'STAGED'
        WHEN v_refresh_candidate_count = 0
          OR NOT EXISTS (
              SELECT 1 FROM public.banking_pay_operation_chunks AS required_refresh_chunk
              WHERE required_refresh_chunk.operation_id = v_operation_id
                AND required_refresh_chunk.phase = 'REFRESH_WORKBENCH'
                AND COALESCE(required_refresh_chunk.result_json->>'status', '') NOT LIKE 'NOT_REQUIRED%'
          ) THEN 'CURRENT'
        WHEN v_refresh_ready_count = v_refresh_candidate_count THEN 'CURRENT'
        WHEN v_refresh_pending_count > 0 THEN 'PENDING'
        ELSE 'STAGED'
    END;

    IF v_terminal_request
       AND v_request.status IN ('APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED')
       AND v_workbench_refresh_status = 'NOT_STAGED' THEN
        v_failure_categories := v_failure_categories
            || pg_catalog.jsonb_build_array('WORKBENCH_REFRESH_NOT_STAGED');
    END IF;

    v_failure_categories := (
        SELECT COALESCE(
            pg_catalog.jsonb_agg(category_value ORDER BY first_ordinal),
            '[]'::jsonb
        )
        FROM (
            SELECT category_value,
                   pg_catalog.min(category_ordinal) AS first_ordinal
            FROM pg_catalog.jsonb_array_elements_text(
                v_failure_categories
            ) WITH ORDINALITY AS category_rows(
                category_value,
                category_ordinal
            )
            GROUP BY category_value
        ) AS unique_categories
    );

    RETURN pg_catalog.jsonb_build_object(
        'ok', pg_catalog.jsonb_array_length(v_failure_categories) = 0,
        'status', CASE
            WHEN pg_catalog.jsonb_array_length(v_failure_categories) > 0
                THEN 'FAIL'
            WHEN NOT v_terminal_request
                THEN 'IN_PROGRESS'
            ELSE 'PASS'
        END,
        'check_version', 1,
        'checked_at_utc', v_checked_at_utc,
        'correction_request_id', v_request.id,
        'operation_id', v_operation_id,
        'pay_batch_id', v_request.pay_batch_id,
        'selected_candidate_count', v_selected_candidate_count,
        'materialised_work_count', v_materialised_work_count,
        'terminal_work_count', v_terminal_work_count,
        'applied_candidate_count', v_applied_candidate_count,
        'blocked_candidate_count', v_blocked_candidate_count,
        'failed_candidate_count', v_failed_candidate_count,
        'source_item_expected_count', v_source_item_expected_count,
        'source_item_applied_count', v_source_item_applied_count,
        'reservation_release_expected_count',
            v_reservation_release_expected_count,
        'reservation_release_actual_count',
            v_reservation_release_actual_count,
        'active_candidate_count', v_active_candidate_count,
        'expected_active_total', v_expected_active_total,
        'actual_active_total', v_actual_active_total,
        'active_total_difference', v_active_total_difference,
        'old_authorisation_invalidated', v_old_authorisation_invalidated,
        'old_schedule_invalidated', v_old_schedule_invalidated,
        'actionable_cancelled_provider_scope_count',
            v_actionable_cancelled_provider_scope_count,
        'unselected_before_hash', v_unselected_before_hash,
        'unselected_after_hash', v_unselected_after_hash,
        'unselected_unchanged', v_unselected_unchanged,
        'refresh_group_total', v_refresh_group_total,
        'refresh_group_complete', v_refresh_group_complete,
        'workbench_refresh_status', v_workbench_refresh_status,
        'failure_categories', v_failure_categories,
        'warnings', v_warnings
    );
END;
$function$;

-- pay_payment_correction_plan(uuid,jsonb,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_plan(p_pay_batch_id uuid, p_selection_json jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_correction_context text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid;
  v_batch_status text;
  v_batch_pay_date date;
  v_batch_authoritative_payment_date date;
  v_effective_pay_date date;
  v_batch_created_at_utc timestamptz;
  v_batch_execution_commit_state text;
  v_batch_execution_commit_ref text;
  v_classification_result jsonb := '{}'::jsonb;
  v_classification text := 'AMBIGUOUS_REVIEW_REQUIRED';
  v_recommended_action text := 'REVIEW_BANK_EVIDENCE';
  v_hard_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_selection_summary jsonb := '{}'::jsonb;
  v_affected_candidates jsonb := '[]'::jsonb;
  v_affected_transfers jsonb := '[]'::jsonb;
  v_affected_umbrellas jsonb := '[]'::jsonb;
  v_affected_items jsonb := '[]'::jsonb;
  v_affected_finance_cases jsonb := '[]'::jsonb;
  v_communication_effects jsonb := '{}'::jsonb;
  v_suggested_resolution_required boolean := false;
  v_suggested_resolution jsonb := NULL::jsonb;
  v_amounts jsonb := '{}'::jsonb;
  v_draft_interference jsonb := '[]'::jsonb;
  v_large_correction jsonb := '{}'::jsonb;
  v_work_expansion_plan jsonb := '{}'::jsonb;
  v_can_apply boolean := false;
  v_draft_removal_requested boolean := false;
  v_strict_draft_removal_pre_bank_cancel boolean := false;
  v_expected_item_count integer := NULL::integer;
  v_expected_item_id_count integer := 0;
  v_expected_item_mismatch_count integer := 0;

  v_selected_item_count integer := 0;
  v_selected_candidate_count integer := 0;
  v_selected_transfer_count integer := 0;
  v_selected_umbrella_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_already_corrected_count integer := 0;
  v_voided_count integer := 0;
  v_pay_channel_change_count integer := 0;
  v_umbrella_change_count integer := 0;
  v_timesheet_item_count integer := 0;
  v_net_fixed_finance_item_count integer := 0;
  v_gross_channel_sensitive_item_count integer := 0;
  v_work_item_count integer := 0;
  v_large_correction_threshold integer := 100;
  v_recommended_chunk_size integer := 50;
  v_total_amount_ex_vat numeric := 0;
  v_total_amount_vat numeric := 0;
  v_total_amount_inc_vat numeric := 0;
  v_queued_unsent_count integer := 0;
  v_sent_notice_count integer := 0;
  v_subject_id text;
  v_scope_type text;
  v_selected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_selected_selection_hash text;
  v_selection_filters_applied jsonb := '{}'::jsonb;
  v_suggested_resolution_finance_cases jsonb := '[]'::jsonb;
  v_finance_case_record record;
  v_case_component_ids jsonb := '[]'::jsonb;
  v_case_component_fingerprints jsonb := '{}'::jsonb;
  v_case_suggestion jsonb := NULL::jsonb;
  v_case_suggestion_hash text := NULL::text;
  v_case_generation_error jsonb := NULL::jsonb;
  v_selected_mail_scope_json jsonb := '{}'::jsonb;
  v_mail_legacy_review_count integer := 0;
  v_mail_legacy_queued_review_count integer := 0;

  v_retry_eligible_count integer := 0;
  v_retry_ineligible_count integer := 0;
  v_retry_eligible_scope_json jsonb := '{}'::jsonb;
  v_retry_ineligible_summary_json jsonb := '[]'::jsonb;
  v_retry_in_progress boolean := false;
  v_retry_already_in_progress boolean := false;
  v_retry_operation_id uuid := NULL::uuid;
  v_retry_operation_status text := NULL::text;
  v_retry_button_visible boolean := false;
  v_retry_button_disabled_reason text := NULL::text;
  v_retry_scope_signature text := NULL::text;
  v_retry_status_label text := NULL::text;
  v_retry_button_label text := NULL::text;
  v_retry_running_label text := NULL::text;
  v_recovery_action_label text := NULL::text;
  v_correction_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_correction_context, '')), ''), '-', '_'));
BEGIN
  v_subject_id := COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID');
  v_scope_type := upper(nullif(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''));


  IF v_correction_context IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_REQUIRED',
              'message', 'pay_payment_correction_plan requires an explicit correction context.'
            )::text;
  END IF;

  IF v_correction_context IN (
    'LIST',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'PREVIEW_OPEN',
    'OPERATION_GET',
    'OPERATION_PROGRESS',
    'PROGRESS_POLLING',
    'PREVIEW_PROGRESS',
    'LIVE_WATCH',
    'WATCH_SIGNAL',
    'RPC_CHANGES_PING'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_NOT_ALLOWED',
              'context', v_correction_context,
              'message', 'Payment correction planning is blocked from list, bootstrap, Overview, preview, operation GET/progress, and progress polling paths.'
            )::text;
  END IF;

  IF v_correction_context NOT IN (
    'CORRECTION_REVIEW',
    'CORRECTION_ACTION',
    'PAYMENT_CORRECTION_REVIEW',
    'PAYMENT_CORRECTION_ACTION',
    'USER_TRIGGERED_CORRECTION',
    'CURRENT_PAYMENT_STATUS_CORRECTION_ACTION',
    'PAYMENT_ISSUES_CORRECTION_ACTION',
    'DRAFT_REMOVE_FROM_BATCH'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CORRECTION_PLAN_CONTEXT_NOT_EXPLICIT',
              'context', v_correction_context,
              'message', 'Payment correction planning is only allowed from explicit correction review/action flows.'
            )::text;
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PLAN_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'selection_scope_type', CASE WHEN p_selection_json IS NULL THEN NULL ELSE p_selection_json->>'scope_type' END,
      'actor_user_id', p_actor_user_id,
      'selection_json', p_selection_json
    ),
    'pay_payment_correction',
    v_subject_id,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.authoritative_payment_date,
    public.pay_batches.created_at_utc,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref
  INTO
    v_batch_id,
    v_batch_status,
    v_batch_pay_date,
    v_batch_authoritative_payment_date,
    v_batch_created_at_utc,
    v_batch_execution_commit_state,
    v_batch_execution_commit_ref
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id;

  IF v_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_effective_pay_date := COALESCE(v_batch_authoritative_payment_date, v_batch_pay_date);

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_selected;
  CREATE TEMP TABLE _tmp_payment_correction_plan_selected ON COMMIT DROP AS
  SELECT
    selected_rows.pay_batch_id,
    selected_rows.pay_batch_candidate_id,
    selected_rows.candidate_id,
    selected_rows.candidate_display_name,
    selected_rows.candidate_tms_ref,
    selected_rows.pay_batch_item_id,
    selected_rows.item_type,
    selected_rows.timesheet_id,
    selected_rows.pay_bank_transfer_id,
    selected_rows.transfer_status,
    selected_rows.transfer_amount,
    selected_rows.transfer_group_key,
    selected_rows.payee_entity_kind,
    selected_rows.payee_entity_id,
    selected_rows.umbrella_id,
    selected_rows.umbrella_name,
    selected_rows.finance_case_id,
    selected_rows.finance_component_id,
    selected_rows.reservation_id,
    selected_rows.pay_channel,
    selected_rows.frozen_source_pay_method,
    selected_rows.frozen_target_pay_method,
    selected_rows.current_candidate_pay_method,
    selected_rows.economic_key_type,
    selected_rows.economic_key_value,
    selected_rows.source_amount_ex_vat,
    selected_rows.target_amount_ex_vat,
    selected_rows.key_resolution_source,
    selected_rows.key_resolution_failure_reason,
    selected_rows.amount_ex_vat,
    selected_rows.amount_vat,
    selected_rows.amount_inc_vat,
    selected_rows.is_voided,
    selected_rows.already_corrected,
    selected_rows.applied_correction_kinds
  FROM public._pay_payment_correction_selected_items(
    p_pay_batch_id,
    p_selection_json,
    true
  ) AS selected_rows;

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_batch_item_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_batch_candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (finance_case_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (finance_component_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (reservation_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (timesheet_id, economic_key_type, economic_key_value);

  SELECT
    COALESCE(array_agg(plan_selected.pay_batch_item_id ORDER BY plan_selected.pay_batch_item_id), ARRAY[]::uuid[]),
    md5(COALESCE(string_agg(plan_selected.pay_batch_item_id::text, ',' ORDER BY plan_selected.pay_batch_item_id::text), 'NO_SELECTED_ITEMS'))
  INTO
    v_selected_pay_batch_item_ids,
    v_selected_selection_hash
  FROM pg_temp._tmp_payment_correction_plan_selected AS plan_selected;

  v_selection_filters_applied := jsonb_build_object(
    'scope_type', v_scope_type,
    'pay_batch_item_id_supplied', p_selection_json ? 'pay_batch_item_id',
    'pay_batch_item_ids_supplied', p_selection_json ? 'pay_batch_item_ids',
    'pay_bank_transfer_id_supplied', p_selection_json ? 'pay_bank_transfer_id',
    'pay_bank_transfer_ids_supplied', p_selection_json ? 'pay_bank_transfer_ids',
    'finance_case_id_supplied', p_selection_json ? 'finance_case_id',
    'finance_case_ids_supplied', p_selection_json ? 'finance_case_ids',
    'finance_component_id_supplied', p_selection_json ? 'finance_component_id',
    'finance_component_ids_supplied', p_selection_json ? 'finance_component_ids',
    'reservation_id_supplied', p_selection_json ? 'reservation_id',
    'reservation_ids_supplied', p_selection_json ? 'reservation_ids',
    'item_type_supplied', p_selection_json ? 'item_type',
    'item_types_supplied', p_selection_json ? 'item_types',
    'expected_item_count_supplied', p_selection_json ? 'expected_item_count',
    'expected_pay_batch_item_ids_supplied', p_selection_json ? 'expected_pay_batch_item_ids'
  );

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_detail;
  CREATE TEMP TABLE _tmp_payment_correction_plan_detail ON COMMIT DROP AS
  SELECT
    plan_selected.pay_batch_id,
    plan_selected.pay_batch_candidate_id,
    plan_selected.candidate_id,
    plan_selected.candidate_display_name,
    plan_selected.candidate_tms_ref,
    plan_selected.pay_batch_item_id,
    plan_selected.item_type,
    plan_selected.timesheet_id,
    plan_selected.pay_bank_transfer_id,
    plan_selected.transfer_status,
    plan_selected.transfer_amount,
    plan_selected.transfer_group_key,
    plan_selected.payee_entity_kind,
    plan_selected.payee_entity_id,
    plan_selected.umbrella_id,
    plan_selected.umbrella_name,
    plan_selected.finance_case_id,
    plan_selected.finance_component_id,
    plan_selected.reservation_id,
    plan_selected.pay_channel,
    plan_selected.frozen_source_pay_method,
    plan_selected.frozen_target_pay_method,
    plan_selected.current_candidate_pay_method,
    plan_selected.economic_key_type,
    plan_selected.economic_key_value,
    plan_selected.source_amount_ex_vat,
    plan_selected.target_amount_ex_vat,
    plan_selected.key_resolution_source,
    plan_selected.key_resolution_failure_reason,
    plan_selected.amount_ex_vat,
    plan_selected.amount_vat,
    plan_selected.amount_inc_vat,
    plan_selected.is_voided,
    plan_selected.already_corrected,
    plan_selected.applied_correction_kinds,
    public.candidates.pay_method AS live_candidate_pay_method,
    public.candidates.umbrella_id AS live_candidate_umbrella_id,
    public.pay_batch_items.frozen_component_classification::text AS frozen_component_classification,
    public.pay_batch_items.frozen_resolution_mode::text AS frozen_resolution_mode,
    public.pay_batch_items.frozen_resolution_payload_json AS frozen_resolution_payload_json,
    public.pay_batch_items.frozen_resolution_result_json AS frozen_resolution_result_json,
    public.pay_batch_items.payout_instruction_snapshot_json AS payout_instruction_snapshot_json,
    public.pay_finance_case_components.classification::text AS finance_component_classification,
    public.pay_finance_case_components.source_pay_method AS finance_component_source_pay_method,
    public.pay_finance_case_components.saved_target_pay_method AS finance_component_saved_target_pay_method,
    public.pay_finance_case_components.saved_resolution_mode::text AS finance_component_saved_resolution_mode,
    public.pay_finance_case_components.is_resolution_stale AS finance_component_is_resolution_stale,
    public.pay_finance_case_components.stale_reason AS finance_component_stale_reason,
    public.pay_finance_case_components.closed_at_utc AS finance_component_closed_at_utc,
    public.pay_advances.case_type::text AS finance_case_type,
    public.pay_advances.advance_kind::text AS finance_advance_kind,
    public.pay_advances.status::text AS finance_case_status,
    public.pay_advances.payout_status::text AS finance_payout_status,
    public.pay_advances.taxability::text AS finance_taxability,
    public.pay_advances.routing_kind::text AS finance_routing_kind,
    public.pay_advances.written_off_at_utc AS finance_written_off_at_utc,
    public.pay_advances.cleared_at_utc AS finance_cleared_at_utc
  FROM pg_temp._tmp_payment_correction_plan_selected AS plan_selected
  JOIN public.pay_batch_items
    ON public.pay_batch_items.id = plan_selected.pay_batch_item_id
  JOIN public.candidates
    ON public.candidates.id = plan_selected.candidate_id
  LEFT JOIN public.pay_finance_case_components
    ON public.pay_finance_case_components.id = plan_selected.finance_component_id
  LEFT JOIN public.pay_advances
    ON public.pay_advances.id = plan_selected.finance_case_id;

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (finance_case_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (finance_component_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (reservation_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (timesheet_id, economic_key_type, economic_key_value);

  v_classification_result := public.pay_payment_cancelability_diagnostic(
    p_pay_batch_id,
    p_selection_json,
    p_actor_user_id,
    'CORRECTION_REVIEW'
  );

  v_classification := COALESCE(
    NULLIF(btrim(v_classification_result->>'payment_lifecycle_state'), ''),
    NULLIF(btrim(v_classification_result->>'classification'), ''),
    'AMBIGUOUS_REVIEW_REQUIRED'
  );

  v_recommended_action := COALESCE(
    NULLIF(btrim(v_classification_result->>'recommended_action'), ''),
    CASE v_classification
      WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
      WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
      WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'FINANCIALS_REWOUND' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
      WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
      WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'RETRY_PROVIDER_LATER'
      WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'CHECK_PROVIDER_STATUS'
      WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'CHECK_PROVIDER_STATUS'
      WHEN 'PAID_OR_SETTLED' THEN 'AMEND_AND_RECOVER_OVERPAYMENT'
      ELSE 'CHECK_PROVIDER_STATUS'
    END
  );

  v_hard_blockers := COALESCE(v_classification_result->'blockers', '[]'::jsonb);

  IF jsonb_array_length(COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb)) > 0 THEN
    v_hard_blockers := v_hard_blockers || COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb);
  END IF;

  v_warnings := COALESCE(v_classification_result->'warnings', '[]'::jsonb);

  IF v_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
     AND jsonb_array_length(v_hard_blockers) = 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CLASSIFICATION_AMBIGUOUS_REVIEW_REQUIRED',
      'message', 'Payment correction action cannot be planned until provider/bank state is clarified.'
    ));
  END IF;

  SELECT
    count(*)::integer,
    count(DISTINCT plan_detail.candidate_id)::integer,
    count(DISTINCT plan_detail.pay_bank_transfer_id) FILTER (WHERE plan_detail.pay_bank_transfer_id IS NOT NULL)::integer,
    count(DISTINCT plan_detail.umbrella_id) FILTER (WHERE plan_detail.umbrella_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE plan_detail.key_resolution_failure_reason IS NOT NULL OR plan_detail.economic_key_type IS NULL OR plan_detail.economic_key_value IS NULL)::integer,
    count(*) FILTER (WHERE COALESCE(plan_detail.already_corrected, false))::integer,
    count(*) FILTER (WHERE COALESCE(plan_detail.is_voided, false))::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_detail.item_type, ''))) IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    )::integer,
    count(*) FILTER (
      WHERE plan_detail.finance_case_id IS NOT NULL
        AND COALESCE(plan_detail.finance_component_classification, plan_detail.frozen_component_classification, '') IN ('REIMBURSEMENT_GROSS_FIXED', 'NET_PAY_FIXED_RECOVERY')
    )::integer,
    count(*) FILTER (
      WHERE (
        COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
        OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
        OR (
          COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
          AND plan_detail.finance_case_id IS NOT NULL
          AND (
            COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
            OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
            OR NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
            OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
          )
        )
      )
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method, ''))) IS DISTINCT FROM upper(btrim(COALESCE(plan_detail.frozen_target_pay_method, plan_detail.frozen_source_pay_method, plan_detail.pay_channel, '')))
        AND NULLIF(btrim(COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method, '')), '') IS NOT NULL
        AND NULLIF(btrim(COALESCE(plan_detail.frozen_target_pay_method, plan_detail.frozen_source_pay_method, plan_detail.pay_channel, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (
      WHERE plan_detail.umbrella_id IS NOT NULL
        AND plan_detail.live_candidate_umbrella_id IS DISTINCT FROM plan_detail.umbrella_id
    )::integer,
    round(COALESCE(sum(COALESCE(plan_detail.amount_ex_vat, 0)), 0), 2)::numeric,
    round(COALESCE(sum(COALESCE(plan_detail.amount_vat, 0)), 0), 2)::numeric,
    round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)::numeric
  INTO
    v_selected_item_count,
    v_selected_candidate_count,
    v_selected_transfer_count,
    v_selected_umbrella_count,
    v_key_resolution_failure_count,
    v_already_corrected_count,
    v_voided_count,
    v_timesheet_item_count,
    v_net_fixed_finance_item_count,
    v_gross_channel_sensitive_item_count,
    v_pay_channel_change_count,
    v_umbrella_change_count,
    v_total_amount_ex_vat,
    v_total_amount_vat,
    v_total_amount_inc_vat
  FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail;

  v_draft_removal_requested := COALESCE(NULLIF(btrim(p_selection_json->>'source_context'), ''), '') = 'DRAFT_REMOVE_FROM_BATCH'
    AND COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), '') = 'CANCEL_PAYMENT_ATTEMPT';

  IF v_draft_removal_requested THEN
    IF v_selected_item_count <= 0 THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_SELECTED_ITEM_REQUIRED',
        'message', 'Draft removal requires at least one selected non-voided frozen batch item.',
        'pay_batch_id', p_pay_batch_id::text
      ));
    END IF;

    IF NULLIF(btrim(COALESCE(p_selection_json->>'expected_item_count', '')), '') IS NOT NULL THEN
      IF (p_selection_json->>'expected_item_count') !~ '^\d+$' THEN
        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'DRAFT_REMOVE_EXPECTED_ITEM_COUNT_INVALID',
          'message', 'Draft removal expected_item_count must be a whole number.',
          'pay_batch_id', p_pay_batch_id::text,
          'expected_item_count', p_selection_json->>'expected_item_count'
        ));
      ELSE
        v_expected_item_count := (p_selection_json->>'expected_item_count')::integer;
        IF v_expected_item_count IS DISTINCT FROM v_selected_item_count THEN
          v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
            'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
            'message', 'Draft removal selection has changed since the UI built the request.',
            'pay_batch_id', p_pay_batch_id::text,
            'expected_item_count', v_expected_item_count,
            'selected_item_count', v_selected_item_count
          ));
        END IF;
      END IF;
    END IF;

    IF p_selection_json ? 'expected_pay_batch_item_ids' THEN
      IF COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') <> 'array' THEN
        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'DRAFT_REMOVE_EXPECTED_ITEM_IDS_INVALID',
          'message', 'Draft removal expected_pay_batch_item_ids must be an array.',
          'pay_batch_id', p_pay_batch_id::text
        ));
      ELSE
        SELECT
          count(*)::integer,
          COALESCE(sum(CASE WHEN NOT EXISTS (
            SELECT 1
            FROM pg_temp._tmp_payment_correction_plan_selected AS selected_item_rows
            WHERE selected_item_rows.pay_batch_item_id::text = expected_item_ids.value
          ) THEN 1 ELSE 0 END), 0)::integer
        INTO
          v_expected_item_id_count,
          v_expected_item_mismatch_count
        FROM jsonb_array_elements_text(p_selection_json->'expected_pay_batch_item_ids') AS expected_item_ids(value);

        IF v_expected_item_id_count IS DISTINCT FROM v_selected_item_count
           OR COALESCE(v_expected_item_mismatch_count, 0) > 0 THEN
          v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
            'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
            'message', 'Draft removal selected item ids have changed since the UI built the request.',
            'pay_batch_id', p_pay_batch_id::text,
            'expected_item_id_count', v_expected_item_id_count,
            'selected_item_count', v_selected_item_count,
            'mismatch_count', v_expected_item_mismatch_count
          ));
        END IF;
      END IF;
    END IF;

    IF v_recommended_action <> 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_CLASSIFICATION_MISMATCH',
        'message', 'Draft removal is only allowed while the selected payment is still a strict pre-bank cancel.',
        'pay_batch_id', p_pay_batch_id::text,
        'classification', v_classification
      ));
    END IF;

    IF upper(btrim(COALESCE(v_batch_status, ''))) NOT IN ('DRAFT', 'DRAFT_CREATED')
       OR upper(btrim(COALESCE(v_batch_execution_commit_state, ''))) IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'SETTLED', 'CANCELLED') THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_NO_LONGER_PRE_BANK',
        'message', 'Draft removal is only allowed before the batch is submitted, executed, settled, cancelled, or committed.',
        'pay_batch_id', p_pay_batch_id::text,
        'batch_status', v_batch_status,
        'execution_commit_state', v_batch_execution_commit_state
      ));
    END IF;
  END IF;

  v_strict_draft_removal_pre_bank_cancel := v_draft_removal_requested
    AND v_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
    AND v_selected_item_count > 0
    AND upper(btrim(COALESCE(v_batch_status, ''))) IN ('DRAFT', 'DRAFT_CREATED')
    AND upper(btrim(COALESCE(v_batch_execution_commit_state, ''))) NOT IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'SETTLED', 'CANCELLED')
    AND jsonb_array_length(v_hard_blockers) = 0;

  IF v_gross_channel_sensitive_item_count > 0
     AND NOT COALESCE(v_strict_draft_removal_pre_bank_cancel, false)
     AND v_recommended_action NOT IN ('PRE_PROVIDER_CANCEL_AND_RECALCULATE', 'NO_MONEY_UNWIND_AND_RECALCULATE') THEN
    v_suggested_resolution_required := true;
  END IF;

  SELECT COALESCE(jsonb_agg(candidate_rows.candidate_json ORDER BY candidate_rows.candidate_display_name), '[]'::jsonb)
  INTO v_affected_candidates
  FROM (
    SELECT
      plan_detail.candidate_display_name,
      jsonb_build_object(
        'pay_batch_candidate_id', plan_detail.pay_batch_candidate_id,
        'candidate_id', plan_detail.candidate_id,
        'candidate_display_name', plan_detail.candidate_display_name,
        'candidate_tms_ref', plan_detail.candidate_tms_ref,
        'current_candidate_pay_method', COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method),
        'current_umbrella_id', plan_detail.live_candidate_umbrella_id,
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS candidate_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    GROUP BY
      plan_detail.pay_batch_candidate_id,
      plan_detail.candidate_id,
      plan_detail.candidate_display_name,
      plan_detail.candidate_tms_ref,
      COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method),
      plan_detail.live_candidate_umbrella_id
  ) AS candidate_rows;

  SELECT COALESCE(jsonb_agg(transfer_rows.transfer_json ORDER BY transfer_rows.transfer_group_key, transfer_rows.pay_bank_transfer_id), '[]'::jsonb)
  INTO v_affected_transfers
  FROM (
    SELECT
      plan_detail.pay_bank_transfer_id,
      plan_detail.transfer_group_key,
      jsonb_build_object(
        'pay_bank_transfer_id', plan_detail.pay_bank_transfer_id,
        'transfer_status', plan_detail.transfer_status,
        'transfer_amount', plan_detail.transfer_amount,
        'transfer_group_key', plan_detail.transfer_group_key,
        'payee_entity_kind', plan_detail.payee_entity_kind,
        'payee_entity_id', plan_detail.payee_entity_id,
        'candidate_count', count(DISTINCT plan_detail.candidate_id)::integer,
        'item_count', count(*)::integer,
        'selected_amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS transfer_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
    GROUP BY
      plan_detail.pay_bank_transfer_id,
      plan_detail.transfer_status,
      plan_detail.transfer_amount,
      plan_detail.transfer_group_key,
      plan_detail.payee_entity_kind,
      plan_detail.payee_entity_id
  ) AS transfer_rows;

  SELECT COALESCE(jsonb_agg(umbrella_rows.umbrella_json ORDER BY umbrella_rows.umbrella_name), '[]'::jsonb)
  INTO v_affected_umbrellas
  FROM (
    SELECT
      plan_detail.umbrella_name,
      jsonb_build_object(
        'umbrella_id', plan_detail.umbrella_id,
        'umbrella_name', plan_detail.umbrella_name,
        'candidate_count', count(DISTINCT plan_detail.candidate_id)::integer,
        'transfer_count', count(DISTINCT plan_detail.pay_bank_transfer_id) FILTER (WHERE plan_detail.pay_bank_transfer_id IS NOT NULL)::integer,
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS umbrella_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.umbrella_id IS NOT NULL
    GROUP BY plan_detail.umbrella_id, plan_detail.umbrella_name
  ) AS umbrella_rows;

  SELECT COALESCE(jsonb_agg(item_rows.item_json ORDER BY item_rows.candidate_display_name, item_rows.pay_batch_item_id), '[]'::jsonb)
  INTO v_affected_items
  FROM (
    SELECT
      plan_detail.candidate_display_name,
      plan_detail.pay_batch_item_id,
      jsonb_build_object(
        'pay_batch_item_id', plan_detail.pay_batch_item_id,
        'pay_batch_candidate_id', plan_detail.pay_batch_candidate_id,
        'candidate_id', plan_detail.candidate_id,
        'candidate_display_name', plan_detail.candidate_display_name,
        'item_type', plan_detail.item_type,
        'timesheet_id', plan_detail.timesheet_id,
        'pay_bank_transfer_id', plan_detail.pay_bank_transfer_id,
        'finance_case_id', plan_detail.finance_case_id,
        'finance_component_id', plan_detail.finance_component_id,
        'reservation_id', plan_detail.reservation_id,
        'economic_key_type', plan_detail.economic_key_type,
        'economic_key_value', plan_detail.economic_key_value,
        'key_resolution_source', plan_detail.key_resolution_source,
        'key_resolution_failure_reason', plan_detail.key_resolution_failure_reason,
        'amount_ex_vat', plan_detail.amount_ex_vat,
        'amount_vat', plan_detail.amount_vat,
        'amount_inc_vat', plan_detail.amount_inc_vat,
        'is_voided', plan_detail.is_voided,
        'already_corrected', plan_detail.already_corrected,
        'applied_correction_kinds', plan_detail.applied_correction_kinds
      ) AS item_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
  ) AS item_rows;

  SELECT COALESCE(jsonb_agg(finance_case_rows.finance_case_json ORDER BY finance_case_rows.finance_case_id), '[]'::jsonb)
  INTO v_affected_finance_cases
  FROM (
    SELECT
      plan_detail.finance_case_id,
      jsonb_build_object(
        'finance_case_id', plan_detail.finance_case_id,
        'candidate_id', min(plan_detail.candidate_id::text),
        'case_type', max(plan_detail.finance_case_type),
        'advance_kind', max(plan_detail.finance_advance_kind),
        'status', max(plan_detail.finance_case_status),
        'payout_status', max(plan_detail.finance_payout_status),
        'taxability', max(plan_detail.finance_taxability),
        'routing_kind', max(plan_detail.finance_routing_kind),
        'written_off_at_utc', max(plan_detail.finance_written_off_at_utc),
        'cleared_at_utc', max(plan_detail.finance_cleared_at_utc),
        'component_ids', COALESCE(jsonb_agg(DISTINCT plan_detail.finance_component_id) FILTER (WHERE plan_detail.finance_component_id IS NOT NULL), '[]'::jsonb),
        'reservation_ids', COALESCE(jsonb_agg(DISTINCT plan_detail.reservation_id) FILTER (WHERE plan_detail.reservation_id IS NOT NULL), '[]'::jsonb),
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2),
        'requires_suggested_resolution', bool_or(
          COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR (
            COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
            AND (
              NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
              OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
            )
          )
        )
      ) AS finance_case_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_case_id IS NOT NULL
    GROUP BY plan_detail.finance_case_id
  ) AS finance_case_rows;

  v_amounts := jsonb_build_object(
    'amount_ex_vat', v_total_amount_ex_vat,
    'amount_vat', v_total_amount_vat,
    'amount_inc_vat', v_total_amount_inc_vat,
    'by_pay_channel', COALESCE((
      SELECT jsonb_agg(channel_rows.channel_json ORDER BY channel_rows.pay_channel)
      FROM (
        SELECT
          COALESCE(plan_detail.pay_channel, 'UNKNOWN') AS pay_channel,
          jsonb_build_object(
            'pay_channel', COALESCE(plan_detail.pay_channel, 'UNKNOWN'),
            'item_count', count(*)::integer,
            'amount_ex_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_ex_vat, 0)), 0), 2),
            'amount_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_vat, 0)), 0), 2),
            'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
          ) AS channel_json
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        GROUP BY COALESCE(plan_detail.pay_channel, 'UNKNOWN')
      ) AS channel_rows
    ), '[]'::jsonb)
  );

  IF v_pay_channel_change_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'PAY_CHANNEL_CHANGED_AFTER_BATCH',
      'message', 'Correction will use the original frozen batch artifact. Any future replacement payment will use the candidate current live pay channel.',
      'affected_item_count', v_pay_channel_change_count
    ));
  END IF;

  IF v_umbrella_change_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'CANDIDATE_UMBRELLA_CHANGED_AFTER_BATCH',
      'message', 'One or more selected items were frozen against a different umbrella/payment group from the candidate current umbrella. Correction uses the frozen batch artifact; future replacement payment uses the current live umbrella routing.',
      'affected_item_count', v_umbrella_change_count
    ));
  END IF;

  IF v_timesheet_item_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'TIMESHEET_CORRECTION_USES_FROZEN_BATCH_METHOD',
      'message', 'Timesheet correction follows the old frozen batch artifact and does not recalculate the old payment from current live timesheet financials.',
      'affected_item_count', v_timesheet_item_count
    ));
  END IF;

  IF v_net_fixed_finance_item_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'NET_FIXED_FINANCE_ITEMS_NO_CHANNEL_CONVERSION',
      'message', 'Net/fixed finance items do not require PAYE/Umbrella amount conversion. Reservation and payout state still need correction handling.',
      'affected_item_count', v_net_fixed_finance_item_count
    ));
  END IF;

  IF v_suggested_resolution_required THEN
    v_suggested_resolution_finance_cases := '[]'::jsonb;

    FOR v_finance_case_record IN
      SELECT
        plan_detail.finance_case_id AS finance_case_id,
        (array_agg(DISTINCT plan_detail.candidate_id ORDER BY plan_detail.candidate_id))[1] AS candidate_id,
        COALESCE(jsonb_agg(DISTINCT plan_detail.finance_component_id) FILTER (WHERE plan_detail.finance_component_id IS NOT NULL), '[]'::jsonb) AS selected_component_ids
      FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
      WHERE plan_detail.finance_case_id IS NOT NULL
        AND (
          COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR (
            COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
            AND (
              NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
              OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
            )
          )
        )
      GROUP BY plan_detail.finance_case_id
      ORDER BY plan_detail.finance_case_id
    LOOP
      SELECT
        COALESCE(jsonb_agg(finance_components.id ORDER BY finance_components.id), '[]'::jsonb),
        COALESCE(jsonb_object_agg(
          finance_components.id::text,
          COALESCE(
            NULLIF(btrim(finance_components.resolution_fingerprint), ''),
            md5(jsonb_build_object(
              'finance_component_id', finance_components.id,
              'finance_case_id', finance_components.finance_case_id,
              'classification', finance_components.classification::text,
              'source_pay_method', finance_components.source_pay_method,
              'source_amount', finance_components.source_amount,
              'remaining_source_amount', finance_components.remaining_source_amount,
              'saved_target_pay_method', finance_components.saved_target_pay_method,
              'saved_resolution_mode', finance_components.saved_resolution_mode::text,
              'saved_resolution_payload_json', finance_components.saved_resolution_payload_json,
              'saved_resolution_result_json', finance_components.saved_resolution_result_json,
              'is_resolution_stale', finance_components.is_resolution_stale,
              'closed_at_utc', finance_components.closed_at_utc,
              'updated_at_utc', finance_components.updated_at_utc
            )::text)
          )
        ), '{}'::jsonb)
      INTO
        v_case_component_ids,
        v_case_component_fingerprints
      FROM public.pay_finance_case_components AS finance_components
      WHERE finance_components.finance_case_id = v_finance_case_record.finance_case_id
        AND finance_components.id IN (
          SELECT DISTINCT plan_detail.finance_component_id
          FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
          WHERE plan_detail.finance_case_id = v_finance_case_record.finance_case_id
            AND plan_detail.finance_component_id IS NOT NULL
        );

      v_case_suggestion := NULL::jsonb;
      v_case_suggestion_hash := NULL::text;
      v_case_generation_error := NULL::jsonb;

      IF p_actor_user_id IS NULL THEN
        v_case_generation_error := jsonb_build_object(
          'code', 'ACTOR_USER_ID_REQUIRED_FOR_SUGGESTED_RESOLUTION',
          'message', 'A real taxable channel restructure suggestion requires an actor user id because the existing suggested-resolution function requires p_actor_user_id.'
        );

        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'ACTOR_USER_ID_REQUIRED_FOR_SUGGESTED_RESOLUTION',
          'message', 'Gross/taxable/channel-sensitive finance items require a suggested resolution, but no actor user id was supplied to generate it.',
          'finance_case_id', v_finance_case_record.finance_case_id
        ));
      ELSE
        BEGIN
          v_case_suggestion := public.pay_finance_case_taxable_channel_restructure_suggestion(
            p_finance_case_id => v_finance_case_record.finance_case_id,
            p_actor_user_id => p_actor_user_id,
            p_effective_pay_date => v_effective_pay_date,
            p_resolution_path => 'SUGGESTED',
            p_schedule_input_mode => NULL::text,
            p_weeks_total => NULL::integer,
            p_weekly_due => NULL::numeric,
            p_manual_total_remaining => NULL::numeric,
            p_note => 'Generated for payment correction plan ' || p_pay_batch_id::text
          );

          v_case_suggestion_hash := md5(jsonb_build_object(
            'finance_case_id', v_finance_case_record.finance_case_id,
            'candidate_id', v_finance_case_record.candidate_id,
            'component_ids', v_case_component_ids,
            'selected_component_ids', v_finance_case_record.selected_component_ids,
            'component_fingerprints', v_case_component_fingerprints,
            'effective_pay_date', v_effective_pay_date,
            'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
            'resolution_path', COALESCE(v_case_suggestion->>'resolution_path', v_case_suggestion#>>'{request,resolution_path}', 'SUGGESTED'),
            'resolution_mode', COALESCE(v_case_suggestion->>'resolution_mode', v_case_suggestion#>>'{result,resolution_mode}', v_case_suggestion#>>'{suggestion,resolution_mode}'),
            'weeks_total', COALESCE(v_case_suggestion->>'weeks_total', v_case_suggestion#>>'{result,weeks_total}', v_case_suggestion#>>'{suggestion,weeks_total}'),
            'weekly_due', COALESCE(v_case_suggestion->>'weekly_due', v_case_suggestion#>>'{result,weekly_due}', v_case_suggestion#>>'{suggestion,weekly_due}'),
            'manual_total_remaining', COALESCE(v_case_suggestion->>'manual_total_remaining', v_case_suggestion#>>'{result,manual_total_remaining}', v_case_suggestion#>>'{suggestion,manual_total_remaining}'),
            'taxable_channel_result', COALESCE(
              v_case_suggestion->'taxable_channel_result',
              v_case_suggestion->'result',
              v_case_suggestion->'suggestion',
              v_case_suggestion
            ) - 'generated_at'
              - 'generated_at_utc'
              - 'created_at'
              - 'created_at_utc'
              - 'updated_at'
              - 'updated_at_utc'
              - 'audit'
              - 'debug'
          )::text);
        EXCEPTION
          WHEN OTHERS THEN
            v_case_generation_error := jsonb_build_object(
              'code', 'SUGGESTED_RESOLUTION_GENERATION_FAILED',
              'sqlstate', SQLSTATE,
              'message', SQLERRM
            );

            v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
              'code', 'SUGGESTED_RESOLUTION_GENERATION_FAILED',
              'message', 'A gross/taxable/channel-sensitive finance suggested resolution could not be generated using the existing suggested-resolution process.',
              'finance_case_id', v_finance_case_record.finance_case_id,
              'sqlstate', SQLSTATE,
              'error_message', SQLERRM
            ));
        END;
      END IF;

      v_suggested_resolution_finance_cases := v_suggested_resolution_finance_cases || jsonb_build_array(jsonb_build_object(
        'finance_case_id', v_finance_case_record.finance_case_id,
        'candidate_id', v_finance_case_record.candidate_id,
        'component_ids', v_case_component_ids,
        'selected_component_ids', v_finance_case_record.selected_component_ids,
        'current_component_fingerprints', v_case_component_fingerprints,
        'suggestion', v_case_suggestion,
        'suggestion_hash', v_case_suggestion_hash,
        'suggestion_hash_basis', jsonb_build_object(
          'finance_case_id', v_finance_case_record.finance_case_id,
          'candidate_id', v_finance_case_record.candidate_id,
          'component_ids', v_case_component_ids,
          'selected_component_ids', v_finance_case_record.selected_component_ids,
          'component_fingerprints', v_case_component_fingerprints,
          'effective_pay_date', v_effective_pay_date,
          'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure'
        ),
        'suggestion_generation_error', v_case_generation_error,
        'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
        'effective_pay_date', v_effective_pay_date,
        'accepted_payload_required', true
      ));
    END LOOP;

    v_suggested_resolution := jsonb_build_object(
      'required', true,
      'reason', 'Gross/taxable/channel-sensitive finance items are present and must use the existing suggested-resolution process before correction apply.',
      'must_be_accepted_before_apply', true,
      'must_be_applied_atomically_with_correction', true,
      'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
      'finance_cases', v_suggested_resolution_finance_cases
    );

    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'SUGGESTED_RESOLUTION_REQUIRED',
      'message', 'Gross/taxable/channel-sensitive finance items require an accepted suggested resolution before this correction request can be started.',
      'affected_item_count', v_gross_channel_sensitive_item_count,
      'suggested_resolution', v_suggested_resolution
    ));
  ELSE
    v_suggested_resolution := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_overlap_items;
  CREATE TEMP TABLE _tmp_payment_correction_plan_overlap_items ON COMMIT DROP AS
  WITH selected_candidate_ids AS (
    SELECT DISTINCT plan_detail.candidate_id
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.candidate_id IS NOT NULL
  ),
  selected_economic_keys AS (
    SELECT DISTINCT
      plan_detail.candidate_id,
      plan_detail.timesheet_id,
      plan_detail.economic_key_type,
      plan_detail.economic_key_value
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.candidate_id IS NOT NULL
      AND plan_detail.timesheet_id IS NOT NULL
      AND plan_detail.economic_key_type IS NOT NULL
      AND plan_detail.economic_key_value IS NOT NULL
  ),
  selected_finance_scope AS (
    SELECT DISTINCT
      plan_detail.finance_case_id,
      plan_detail.finance_component_id,
      plan_detail.reservation_id
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_case_id IS NOT NULL
       OR plan_detail.finance_component_id IS NOT NULL
       OR plan_detail.reservation_id IS NOT NULL
  ),
  filtered_other_items AS (
    SELECT
      public.pay_batches.id AS other_pay_batch_id,
      public.pay_batches.status AS other_batch_status,
      public.pay_batches.created_at_utc AS other_batch_created_at_utc,
      public.pay_batches.execution_commit_state AS other_execution_commit_state,
      public.pay_batches.execution_commit_ref AS other_execution_commit_ref,
      public.pay_batch_candidates.candidate_id AS other_candidate_id,
      public.pay_batch_items.id AS other_pay_batch_item_id,
      public.pay_batch_items.pay_batch_candidate_id AS other_pay_batch_candidate_id,
      public.pay_batch_items.timesheet_id AS other_timesheet_id,
      public.pay_batch_items.finance_case_id AS other_finance_case_id,
      public.pay_batch_items.finance_component_id AS other_finance_component_id,
      public.pay_batch_items.reservation_id AS other_reservation_id,
      public.pay_batch_items.pay_bank_transfer_id AS other_pay_bank_transfer_id,
      other_economic_components.key_type AS other_economic_key_type,
      other_economic_components.key_value AS other_economic_key_value,
      public.pay_batch_candidates.settlement_status AS other_candidate_settlement_status,
      public.pay_batch_candidates.settled_at_utc AS other_candidate_settled_at_utc,
      public.pay_bank_transfers.status AS other_transfer_status,
      public.pay_bank_transfers.completed_at_utc AS other_transfer_completed_at_utc
    FROM public.pay_batches
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.pay_batch_id = public.pay_batches.id
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = public.pay_batch_candidates.id
    JOIN selected_candidate_ids
      ON selected_candidate_ids.candidate_id = public.pay_batch_candidates.candidate_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN LATERAL public._pay_batch_item_economic_components(NULL::uuid, ARRAY[public.pay_batch_items.id]) AS other_economic_components
      ON true
    WHERE public.pay_batches.id <> p_pay_batch_id
      AND COALESCE(public.pay_batch_items.is_voided, false) = false
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS other_applied_corrections
        WHERE other_applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND other_applied_corrections.status = 'APPLIED'
      )
  )
  SELECT
    filtered_other_items.other_pay_batch_id,
    filtered_other_items.other_batch_status,
    filtered_other_items.other_batch_created_at_utc,
    filtered_other_items.other_execution_commit_state,
    filtered_other_items.other_execution_commit_ref,
    filtered_other_items.other_candidate_id,
    filtered_other_items.other_pay_batch_item_id,
    filtered_other_items.other_pay_batch_candidate_id,
    filtered_other_items.other_timesheet_id,
    filtered_other_items.other_finance_case_id,
    filtered_other_items.other_finance_component_id,
    filtered_other_items.other_reservation_id,
    filtered_other_items.other_pay_bank_transfer_id,
    filtered_other_items.other_economic_key_type,
    filtered_other_items.other_economic_key_value,
    filtered_other_items.other_candidate_settlement_status,
    filtered_other_items.other_candidate_settled_at_utc,
    filtered_other_items.other_transfer_status,
    filtered_other_items.other_transfer_completed_at_utc,
    CASE
      WHEN EXISTS (
        SELECT 1
        FROM selected_economic_keys
        WHERE selected_economic_keys.candidate_id = filtered_other_items.other_candidate_id
          AND selected_economic_keys.timesheet_id = filtered_other_items.other_timesheet_id
          AND selected_economic_keys.economic_key_type = filtered_other_items.other_economic_key_type
          AND selected_economic_keys.economic_key_value = filtered_other_items.other_economic_key_value
      ) THEN 'ECONOMIC_KEY'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.finance_case_id IS NOT NULL
          AND selected_finance_scope.finance_case_id = filtered_other_items.other_finance_case_id
      ) THEN 'FINANCE_CASE'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.finance_component_id IS NOT NULL
          AND selected_finance_scope.finance_component_id = filtered_other_items.other_finance_component_id
      ) THEN 'FINANCE_COMPONENT'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.reservation_id IS NOT NULL
          AND selected_finance_scope.reservation_id = filtered_other_items.other_reservation_id
      ) THEN 'RESERVATION'
      ELSE NULL
    END AS overlap_kind
  FROM filtered_other_items
  WHERE EXISTS (
      SELECT 1
      FROM selected_economic_keys
      WHERE selected_economic_keys.candidate_id = filtered_other_items.other_candidate_id
        AND selected_economic_keys.timesheet_id = filtered_other_items.other_timesheet_id
        AND selected_economic_keys.economic_key_type = filtered_other_items.other_economic_key_type
        AND selected_economic_keys.economic_key_value = filtered_other_items.other_economic_key_value
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.finance_case_id IS NOT NULL
        AND selected_finance_scope.finance_case_id = filtered_other_items.other_finance_case_id
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.finance_component_id IS NOT NULL
        AND selected_finance_scope.finance_component_id = filtered_other_items.other_finance_component_id
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.reservation_id IS NOT NULL
        AND selected_finance_scope.reservation_id = filtered_other_items.other_reservation_id
    );

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (other_pay_batch_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (other_candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (overlap_kind);

  SELECT COALESCE(jsonb_agg(overlap_batches.overlap_json ORDER BY overlap_batches.other_batch_created_at_utc, overlap_batches.other_pay_batch_id), '[]'::jsonb)
  INTO v_draft_interference
  FROM (
    SELECT
      overlap_items.other_pay_batch_id,
      min(overlap_items.other_batch_created_at_utc) AS other_batch_created_at_utc,
      jsonb_build_object(
        'pay_batch_id', overlap_items.other_pay_batch_id,
        'status', max(overlap_items.other_batch_status),
        'execution_commit_state', max(overlap_items.other_execution_commit_state),
        'execution_commit_ref', max(overlap_items.other_execution_commit_ref),
        'overlap_kinds', COALESCE(jsonb_agg(DISTINCT overlap_items.overlap_kind) FILTER (WHERE overlap_items.overlap_kind IS NOT NULL), '[]'::jsonb),
        'candidate_count', count(DISTINCT overlap_items.other_candidate_id)::integer,
        'item_count', count(DISTINCT overlap_items.other_pay_batch_item_id)::integer,
        'message', 'This correction cannot be applied because draft batch ' || overlap_items.other_pay_batch_id::text || ' already reserves affected items under the current pay channel. Delete/cancel draft batch ' || overlap_items.other_pay_batch_id::text || ' first, then retry.'
      ) AS overlap_json
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE public._pay_batch_status_is_active_reservation(overlap_items.other_batch_status)
    GROUP BY overlap_items.other_pay_batch_id
  ) AS overlap_batches;

  IF jsonb_array_length(v_draft_interference) > 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'OVERLAPPING_DRAFT_BATCH_RESERVES_AFFECTED_ITEMS',
      'message', 'This correction cannot be applied because another draft/reserved batch already reserves affected items. Delete/cancel the interfering draft batch first, then retry.',
      'draft_interference', v_draft_interference
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_batch_status, ''))) IN ('SCHEDULED', 'EXECUTING', 'WAITING_BANK_CONFIRM', 'AUTHORISED_FOR_PAYMENT', 'AWAITING_AUTHORISATION')
        OR upper(btrim(COALESCE(overlap_items.other_execution_commit_state, ''))) IN ('COMMITTED', 'SUBMITTED')
        OR NULLIF(btrim(COALESCE(overlap_items.other_execution_commit_ref, '')), '') IS NOT NULL
      )
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_AUTHORISED_OR_SUBMITTED_BATCH_OVERLAP',
      'message', 'A later authorised/submitted batch overlaps the selected correction scope. Manual review is required before correction can apply.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_batch_status, ''))) IN ('FAILED', 'PARTIAL')
      )
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_FAILED_OR_AMBIGUOUS_BATCH_OVERLAP',
      'message', 'A later failed or partial batch overlaps the selected correction scope. Manual review is required.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_candidate_settlement_status, ''))) = 'SETTLED'
        OR overlap_items.other_candidate_settled_at_utc IS NOT NULL
        OR upper(btrim(COALESCE(overlap_items.other_transfer_status, ''))) = 'COMPLETED'
        OR overlap_items.other_transfer_completed_at_utc IS NOT NULL
      )
  ) THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_SETTLED_BATCH_OVERLAP_WARNING',
      'message', 'A later settled batch overlaps the candidate/economic scope. It must remain untouched; this correction only affects the selected old frozen batch artifacts.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_written_off_at_utc IS NOT NULL
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'FINANCE_CASE_WRITTEN_OFF',
      'message', 'One or more selected finance cases have been written off and require manual finance review.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_component_is_resolution_stale IS TRUE
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'FINANCE_COMPONENT_RESOLUTION_STALE',
      'message', 'One or more selected finance component resolutions are stale and must be regenerated before correction apply.'
    ));
  END IF;

  SELECT jsonb_build_object(
    'scope_type', v_scope_type,
    'work_unit', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'work_unit', '')), ''), v_scope_type, 'UNKNOWN'),
    'pay_batch_id', p_pay_batch_id::text,
    'pay_batch_ids', jsonb_build_array(p_pay_batch_id::text),
    'is_whole_batch', (
      v_scope_type = 'BATCH'
      AND NOT (COALESCE(p_selection_json, '{}'::jsonb) ?| ARRAY[
        'pay_batch_item_id',
        'pay_batch_item_ids',
        'selected_pay_batch_item_ids',
        'expected_pay_batch_item_ids',
        'pay_batch_candidate_id',
        'pay_batch_candidate_ids',
        'selected_pay_batch_candidate_ids',
        'candidate_id',
        'candidate_ids',
        'selected_candidate_ids',
        'pay_bank_transfer_id',
        'pay_bank_transfer_ids',
        'selected_pay_bank_transfer_ids',
        'umbrella_id',
        'umbrella_ids',
        'selected_umbrella_ids',
        'finance_case_id',
        'finance_case_ids',
        'selected_finance_case_ids',
        'finance_component_id',
        'finance_component_ids',
        'selected_finance_component_ids',
        'reservation_id',
        'reservation_ids',
        'selected_reservation_ids',
        'payout_transfer_id',
        'payout_transfer_ids',
        'selected_payout_transfer_ids',
        'transfer_group_key',
        'transfer_group_keys',
        'selected_transfer_group_keys'
      ]::text[])
    ),
    'selected_candidate_scope_complete', (
      v_scope_type = 'CANDIDATES'
      AND NOT (COALESCE(p_selection_json, '{}'::jsonb) ?| ARRAY[
        'pay_batch_item_id',
        'pay_batch_item_ids',
        'selected_pay_batch_item_ids',
        'expected_pay_batch_item_ids',
        'pay_bank_transfer_id',
        'pay_bank_transfer_ids',
        'selected_pay_bank_transfer_ids',
        'finance_case_id',
        'finance_case_ids',
        'selected_finance_case_ids',
        'finance_component_id',
        'finance_component_ids',
        'selected_finance_component_ids',
        'reservation_id',
        'reservation_ids',
        'selected_reservation_ids',
        'payout_transfer_id',
        'payout_transfer_ids',
        'selected_payout_transfer_ids',
        'transfer_group_key',
        'transfer_group_keys',
        'selected_transfer_group_keys'
      ]::text[])
    ),
    'pay_batch_item_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_batch_item_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_batch_item_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_batch_candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_batch_candidate_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_batch_candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.candidate_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'umbrella_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.umbrella_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.umbrella_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_case_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.finance_case_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.finance_case_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_component_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.finance_component_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.finance_component_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'reservation_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.reservation_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.reservation_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'payout_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'transfer_group_keys', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.transfer_group_key AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE NULLIF(btrim(COALESCE(plan_detail.transfer_group_key, '')), '') IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb)
  )
  INTO v_selected_mail_scope_json;

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_mail;
  CREATE TEMP TABLE _tmp_payment_correction_plan_mail ON COMMIT DROP AS
  WITH candidate_mail AS (
    SELECT
      public.mail_outbox.id,
      public.mail_outbox.type,
      public.mail_outbox."to" AS mail_to,
      public.mail_outbox.subject,
      public.mail_outbox.status::text AS status,
      public.mail_outbox.created_at_utc,
      public.mail_outbox.sent_at,
      public.mail_outbox.failed_at,
      public.mail_outbox.reference,
      public.mail_outbox.recipient_kind,
      public.mail_outbox.recipient_id,
      public.mail_outbox.context_kind,
      public.mail_outbox.context_id,
      public.mail_outbox.email_type,
      COALESCE(public.mail_outbox.payment_scope_json, '{}'::jsonb) AS payment_scope_json
    FROM public.mail_outbox
    WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) IN ('QUEUED', 'SENT')
      AND lower(concat_ws('|', public.mail_outbox.type, public.mail_outbox.email_type, public.mail_outbox.context_kind, public.mail_outbox.reference, COALESCE(public.mail_outbox.payment_scope_json::text, '{}'))) LIKE ANY (
        ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%']
      )
  ), matched_mail AS (
    SELECT
      candidate_mail.id,
      candidate_mail.type,
      candidate_mail.mail_to,
      candidate_mail.subject,
      candidate_mail.status,
      candidate_mail.created_at_utc,
      candidate_mail.sent_at,
      candidate_mail.failed_at,
      candidate_mail.reference,
      candidate_mail.recipient_kind,
      candidate_mail.recipient_id,
      candidate_mail.context_kind,
      candidate_mail.context_id,
      candidate_mail.email_type,
      candidate_mail.payment_scope_json,
      mail_match.match_result
    FROM candidate_mail
    CROSS JOIN LATERAL (
      SELECT public._pay_payment_correction_mail_scope_match(
        candidate_mail.id,
        p_pay_batch_id,
        p_selection_json,
        v_selected_mail_scope_json,
        false
      ) AS match_result
    ) AS mail_match
  )
  SELECT
    matched_mail.id,
    matched_mail.type,
    matched_mail.mail_to,
    matched_mail.subject,
    matched_mail.status,
    matched_mail.created_at_utc,
    matched_mail.sent_at,
    matched_mail.failed_at,
    matched_mail.reference,
    matched_mail.recipient_kind,
    matched_mail.recipient_id,
    matched_mail.context_kind,
    matched_mail.context_id,
    matched_mail.email_type,
    matched_mail.payment_scope_json,
    COALESCE(matched_mail.match_result->>'match_kind', 'NONE') AS scope_match,
    COALESCE(matched_mail.match_result->>'match_confidence', 'NONE') AS match_confidence,
    COALESCE(NULLIF(matched_mail.match_result->>'safe_to_cancel', '')::boolean, false) AS safe_to_cancel,
    COALESCE(NULLIF(matched_mail.match_result->>'requires_review', '')::boolean, false) AS requires_review,
    COALESCE(matched_mail.match_result->>'reason', 'NO_SCOPE_MATCH') AS match_reason,
    matched_mail.match_result AS match_result
  FROM matched_mail
  WHERE COALESCE(NULLIF(matched_mail.match_result->>'matched', '')::boolean, false);

  SELECT
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'SENT'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    )::integer,
    count(*) FILTER (
      WHERE COALESCE(plan_mail.requires_review, false)
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.requires_review, false)
    )::integer
  INTO
    v_queued_unsent_count,
    v_sent_notice_count,
    v_mail_legacy_review_count,
    v_mail_legacy_queued_review_count
  FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail;

  IF v_mail_legacy_queued_review_count > 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'MAIL_SCOPE_LEGACY_BROAD_MATCH_REQUIRES_REVIEW',
      'message', 'One or more queued payment notices only match the selected payment scope by broad legacy candidate, umbrella, recipient, or reference data. Manual review is required before applying this correction.',
      'queued_notice_count', v_mail_legacy_queued_review_count
    ));
  ELSIF v_mail_legacy_review_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'MAIL_SCOPE_LEGACY_BROAD_MATCH_REQUIRES_REVIEW',
      'message', 'One or more payment notices only match the selected payment scope by broad legacy candidate, umbrella, recipient, or reference data and require review.',
      'notice_count', v_mail_legacy_review_count
    ));
  END IF;

  v_communication_effects := jsonb_build_object(
    'queued_unsent_to_cancel', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb)
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    ), '[]'::jsonb),
    'legacy_broad_matches_requiring_review', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'status', plan_mail.status,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb)
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE COALESCE(plan_mail.requires_review, false)
        AND COALESCE(plan_mail.safe_to_cancel, false) = false
    ), '[]'::jsonb),
    'sent_to_leave_as_audit', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb),
        'sent_at', plan_mail.sent_at
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'SENT'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    ), '[]'::jsonb),
    'external_correction_notice', false,
    'admin_notice_required', true,
    'queued_unsent_count', v_queued_unsent_count,
    'sent_notice_count', v_sent_notice_count,
    'legacy_broad_review_count', v_mail_legacy_review_count,
    'legacy_broad_queued_review_count', v_mail_legacy_queued_review_count,
    'selected_scope_json', v_selected_mail_scope_json
  );

  v_work_item_count := CASE
    WHEN v_selected_transfer_count > 0
      AND v_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE'
      THEN v_selected_transfer_count
    WHEN v_selected_candidate_count > 0
      THEN v_selected_candidate_count
    ELSE v_selected_item_count
  END;

  v_large_correction := jsonb_build_object(
    'large_correction', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
    'threshold', v_large_correction_threshold,
    'work_item_count', COALESCE(v_work_item_count, 0),
    'recommended_chunk_size', v_recommended_chunk_size
  );

  v_work_expansion_plan := jsonb_build_object(
    'recommended_action', v_recommended_action,
    'work_kind', NULL::text,
    'work_unit', CASE
      WHEN v_selected_transfer_count > 0 THEN 'TRANSFER'
      WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE'
      ELSE 'ITEM'
    END,
    'work_item_count', COALESCE(v_work_item_count, 0),
    'process_synchronously', COALESCE(v_work_item_count, 0) <= v_large_correction_threshold,
    'recommended_chunk_size', v_recommended_chunk_size,
    'requires_work_queue', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
    'selected_pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
    'selected_selection_hash', v_selected_selection_hash,
    'chunking_plan', jsonb_build_object(
      'default_limit', v_recommended_chunk_size,
      'hard_cap', 100,
      'requires_chunking', COALESCE(v_work_item_count, 0) > v_large_correction_threshold
    )
  );

  v_selection_summary := jsonb_build_object(
    'scope_type', upper(nullif(btrim(COALESCE(p_selection_json->>'scope_type', '')), '')),
    'selected_pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
    'selected_selection_hash', v_selected_selection_hash,
    'selection_filters_applied', v_selection_filters_applied,
    'selected_item_count', v_selected_item_count,
    'selected_candidate_count', v_selected_candidate_count,
    'selected_transfer_count', v_selected_transfer_count,
    'selected_umbrella_count', v_selected_umbrella_count,
    'key_resolution_failure_count', v_key_resolution_failure_count,
    'already_corrected_count', v_already_corrected_count,
    'voided_count', v_voided_count,
    'pay_channel_change_count', v_pay_channel_change_count,
    'umbrella_change_count', v_umbrella_change_count,
    'gross_channel_sensitive_item_count', v_gross_channel_sensitive_item_count,
    'net_fixed_finance_item_count', v_net_fixed_finance_item_count
  );

  v_can_apply := (
    v_recommended_action IN ('PRE_PROVIDER_CANCEL_AND_RECALCULATE', 'NO_MONEY_UNWIND_AND_RECALCULATE')
    AND v_classification NOT IN ('AMBIGUOUS_REVIEW_REQUIRED', 'PAID_OR_SETTLED', 'PROVIDER_SUBMITTED_PENDING', 'PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_OUTAGE_RETRY_LATER')
    AND jsonb_array_length(v_hard_blockers) = 0
    AND v_selected_item_count > 0
    AND NOT v_suggested_resolution_required
  );

  v_retry_scope_signature := md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', COALESCE(v_selected_selection_hash, 'NO_SELECTED_ITEMS'),
    'classification', v_classification,
    'recommended_action', v_recommended_action,
    'pay_channel_scope', COALESCE(p_selection_json->>'pay_channel_scope', p_selection_json->>'pay_channel', 'ALL'),
    'retry_contract', 'RETRY_UNSENT_PAYMENTS'
  )::text);

  v_retry_status_label := 'Bank unavailable — unsent payments can be retried';
  v_retry_button_label := 'Retry unsent payments';
  v_retry_running_label := 'Retrying unsent payments';
  v_recovery_action_label := 'Recover overpayment in next pay run';

  IF v_recommended_action = 'RETRY_PROVIDER_LATER'
     AND v_classification = 'PROVIDER_OUTAGE_RETRY_LATER'
     AND jsonb_array_length(v_hard_blockers) = 0
     AND v_selected_item_count > 0 THEN
    v_retry_eligible_count := CASE
      WHEN COALESCE(v_selected_transfer_count, 0) > 0 THEN v_selected_transfer_count
      WHEN COALESCE(v_selected_candidate_count, 0) > 0 THEN v_selected_candidate_count
      ELSE v_selected_item_count
    END;
    v_retry_ineligible_count := 0;
    v_retry_eligible_scope_json := jsonb_build_object(
      'scope_type', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''), 'BATCH'),
      'pay_batch_id', p_pay_batch_id::text,
      'retry_scope_signature', v_retry_scope_signature,
      'pay_batch_item_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_item_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_candidate_ids', '[]'::jsonb),
      'candidate_ids', COALESCE(v_selected_mail_scope_json->'candidate_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_selected_mail_scope_json->'pay_bank_transfer_ids', '[]'::jsonb),
      'transfer_group_keys', COALESCE(v_selected_mail_scope_json->'transfer_group_keys', '[]'::jsonb),
      'reason', 'Backend-confirmed provider request was not sent; eligible for Retry unsent payments.'
    );
  ELSE
    v_retry_eligible_count := 0;
    v_retry_ineligible_count := CASE
      WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN GREATEST(COALESCE(v_selected_transfer_count, 0), COALESCE(v_selected_candidate_count, 0), COALESCE(v_selected_item_count, 0))
      ELSE 0
    END;
    v_retry_eligible_scope_json := jsonb_build_object(
      'scope_type', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''), 'BATCH'),
      'pay_batch_id', p_pay_batch_id::text,
      'retry_scope_signature', v_retry_scope_signature,
      'eligible', false
    );
    IF v_recommended_action = 'RETRY_PROVIDER_LATER' THEN
      v_retry_ineligible_summary_json := jsonb_build_array(jsonb_build_object(
        'code', 'RETRY_UNSENT_PAYMENTS_NOT_CURRENTLY_ELIGIBLE',
        'message', 'No selected payment scope is currently confirmed as unsent and retry-safe.',
        'classification', v_classification,
        'recommended_action', v_recommended_action
      ));
    END IF;
  END IF;

  SELECT operation_rows.id,
         operation_rows.status
  INTO v_retry_operation_id,
       v_retry_operation_status
  FROM public.banking_pay_operations AS operation_rows
  WHERE operation_rows.pay_batch_id = p_pay_batch_id
    AND upper(btrim(COALESCE(operation_rows.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
    AND upper(btrim(COALESCE(operation_rows.status, ''))) NOT IN ('COMPLETED', 'COMPLETE', 'SUCCEEDED', 'SUCCESS', 'FAILED', 'FAILED_FINAL', 'CANCELLED', 'CANCELED')
    AND (
      COALESCE(operation_rows.input_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(operation_rows.progress_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(operation_rows.result_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(v_retry_eligible_count, 0) > 0
    )
  ORDER BY operation_rows.created_at_utc DESC NULLS LAST, operation_rows.id DESC
  LIMIT 1;

  v_retry_in_progress := v_retry_operation_id IS NOT NULL;
  v_retry_already_in_progress := v_retry_in_progress;
  v_retry_button_visible := COALESCE(v_retry_eligible_count, 0) > 0 AND COALESCE(v_retry_in_progress, false) IS NOT TRUE;

  IF COALESCE(v_retry_in_progress, false) THEN
    v_retry_button_disabled_reason := 'Retry already in progress';
  ELSIF COALESCE(v_retry_eligible_count, 0) <= 0 AND v_recommended_action = 'RETRY_PROVIDER_LATER' THEN
    v_retry_button_disabled_reason := 'No unsent payments available to retry';
  ELSE
    v_retry_button_disabled_reason := NULL::text;
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PLAN_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'classification', v_classification,
      'recommended_action', v_recommended_action,
      'can_apply', v_can_apply,
      'selected_item_count', v_selected_item_count,
      'selected_candidate_count', v_selected_candidate_count,
      'selected_transfer_count', v_selected_transfer_count,
      'hard_blocker_count', jsonb_array_length(v_hard_blockers),
      'warning_count', jsonb_array_length(v_warnings),
      'suggested_resolution_required', v_suggested_resolution_required,
      'umbrella_change_count', v_umbrella_change_count,
      'work_item_count', v_work_item_count,
      'large_correction', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
      'retry_eligible_count', v_retry_eligible_count,
      'retry_in_progress', v_retry_in_progress,
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END
    ),
    'pay_payment_correction',
    v_subject_id,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id,
    'classification', v_classification,
    'recommended_action', v_recommended_action,
    'user_facing_recommended_action', v_recommended_action,
    'next_step', CASE WHEN v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP' THEN 'AMEND_TIMESHEET_AND_RECALCULATE' ELSE NULL::text END,
    'next_step_label', CASE WHEN v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP' THEN 'Amend timesheets and recalculate' ELSE NULL::text END,
    'display_only_action', v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP',
    'action_label', CASE WHEN v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN v_recovery_action_label WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_button_label ELSE NULL::text END,
    'status_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_status_label ELSE NULL::text END,
    'button_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_button_label ELSE NULL::text END,
    'running_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_running_label ELSE NULL::text END,
    'recovery_action_label', CASE WHEN v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN v_recovery_action_label ELSE NULL::text END,
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason,
    'retry_scope_signature', v_retry_scope_signature,
    'payment_lifecycle_state', v_classification,
    'provider_failure_reason_code', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_code'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_code}'), '')),
    'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_group'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_group}'), '')),
    'provider_failure_reason_label', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_label'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_label}'), '')),
    'alert_candidate_kind', NULLIF(btrim(COALESCE(v_classification_result->>'alert_candidate_kind', '')), ''),
    'alert_candidate_severity', NULLIF(btrim(COALESCE(v_classification_result->>'alert_candidate_severity', '')), ''),
    'alert_candidate_is_success_only', COALESCE(NULLIF(v_classification_result->>'alert_candidate_is_success_only', '')::boolean, false),
    'live_status_signature', COALESCE(NULLIF(btrim(v_classification_result->>'live_status_signature'), ''), NULLIF(btrim(v_classification_result->>'status_update_signature'), ''), md5(jsonb_build_object('pay_batch_id', p_pay_batch_id::text, 'classification', v_classification, 'recommended_action', v_recommended_action, 'selection_hash', COALESCE(v_selected_selection_hash, ''))::text)),
    'status_update_signature', COALESCE(NULLIF(btrim(v_classification_result->>'status_update_signature'), ''), NULLIF(btrim(v_classification_result->>'live_status_signature'), ''), md5(jsonb_build_object('pay_batch_id', p_pay_batch_id::text, 'classification', v_classification, 'recommended_action', v_recommended_action, 'selection_hash', COALESCE(v_selected_selection_hash, ''))::text)),
    'can_apply', v_can_apply,
    'hard_blockers', v_hard_blockers,
    'warnings', v_warnings,
    'selection', v_selection_summary,
    'affected_candidates', v_affected_candidates,
    'affected_transfers', v_affected_transfers,
    'affected_umbrellas', v_affected_umbrellas,
    'affected_items', v_affected_items,
    'affected_finance_cases', v_affected_finance_cases,
    'communication_effects', v_communication_effects,
    'suggested_resolution_required', v_suggested_resolution_required,
    'suggested_resolution', v_suggested_resolution,
    'amounts', v_amounts
  ) || jsonb_build_object(
    'draft_interference', v_draft_interference,
    'large_correction', v_large_correction,
    'work_expansion_plan', v_work_expansion_plan,
    'chunking_plan', COALESCE(v_work_expansion_plan->'chunking_plan', '{}'::jsonb),
    'full_payment_scope', COALESCE(v_classification_result->'resolved_full_payment_scope_json', v_classification_result->'full_payment_scope', '{}'::jsonb),
    'resolved_full_payment_scope_json', COALESCE(v_classification_result->'resolved_full_payment_scope_json', v_classification_result->'full_payment_scope', '{}'::jsonb),
    'finance_scope', COALESCE(v_classification_result->'finance_scope_json', v_classification_result->'finance_scope', '{}'::jsonb),
    'finance_scope_json', COALESCE(v_classification_result->'finance_scope_json', v_classification_result->'finance_scope', '{}'::jsonb),
    'manual_adjustment_carry_forward_required', COALESCE(NULLIF(v_classification_result->>'manual_adjustment_carry_forward_required', '')::boolean, false),
    'manual_adjustments_to_carry_forward', COALESCE(v_classification_result->'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'safe_carry_forward_items', COALESCE(v_classification_result->'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_classification_result->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'ambiguous_manual_adjustment_blockers', COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb),
    'provider_evidence', jsonb_build_object(
      'pending_provider_evidence_json', COALESCE(v_classification_result->'pending_provider_evidence_json', '{}'::jsonb),
      'terminal_no_money_evidence_json', COALESCE(v_classification_result->'terminal_no_money_evidence_json', '{}'::jsonb),
      'provider_outcome_unknown_evidence_json', COALESCE(v_classification_result->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
      'provider_webhook_evidence_json', COALESCE(v_classification_result->'provider_webhook_evidence_json', '{}'::jsonb),
      'provider_failure_reason_code', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_code'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_code}'), '')),
      'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_group'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_group}'), '')),
      'provider_failure_reason_label', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_label'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_label}'), ''))
    ),
    'provider_webhook_evidence_json', COALESCE(v_classification_result->'provider_webhook_evidence_json', '{}'::jsonb),
    'provider_outcome_unknown_evidence_json', COALESCE(v_classification_result->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
    'paid_evidence', COALESCE(v_classification_result->'blocking_paid_evidence_json', '{}'::jsonb),
    'race_submission_blockers', COALESCE((
      SELECT jsonb_agg(race_blockers.blocker_value ORDER BY race_blockers.blocker_ordinal)
      FROM jsonb_array_elements(COALESCE(v_classification_result->'blockers', '[]'::jsonb)) WITH ORDINALITY AS race_blockers(blocker_value, blocker_ordinal)
      WHERE COALESCE(race_blockers.blocker_value->>'code', '') IN (
        'PROVIDER_SUBMISSION_ALREADY_CLAIMED',
        'PROVIDER_SUBMISSION_IN_PROGRESS',
        'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
      )
    ), '[]'::jsonb),
    'movement_classification_detail', v_classification_result,
    'live_refresh_scope', jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'classification', v_classification,
      'recommended_action', v_recommended_action,
      'selected_selection_hash', v_selected_selection_hash,
      'pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
      'pay_bank_transfer_ids', COALESCE(v_selected_mail_scope_json->'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_candidate_ids', '[]'::jsonb),
      'candidate_ids', COALESCE(v_selected_mail_scope_json->'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_selected_mail_scope_json->'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_selected_mail_scope_json->'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_selected_mail_scope_json->'reservation_ids', '[]'::jsonb),
      'retry_scope_signature', v_retry_scope_signature,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false)
    ),
    'batch', jsonb_build_object(
      'status', v_batch_status,
      'pay_date', v_batch_pay_date,
      'authoritative_payment_date', v_batch_authoritative_payment_date,
      'effective_pay_date', v_effective_pay_date,
      'created_at_utc', v_batch_created_at_utc,
      'execution_commit_state', v_batch_execution_commit_state,
      'execution_commit_ref', v_batch_execution_commit_ref
    )
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_PLAN_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'selection_json', p_selection_json,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_payment_correction_process_chunk(uuid,integer,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_process_chunk(p_correction_request_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_worker_id text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.pay_payment_correction_requests%rowtype;
  v_operation public.banking_pay_operations%rowtype;
  v_batch public.pay_batches%rowtype;
  v_phase text;
  v_phase_result jsonb := '{}'::jsonb;
  v_work_result jsonb := '{}'::jsonb;
  v_work record;
  v_claim_limit integer;
  v_claimed_count integer := 0;
  v_applied_count integer := 0;
  v_blocked_count integer := 0;
  v_failed_count integer := 0;
  v_retryable_count integer := 0;
  v_nonterminal_count integer := 0;
  v_summary_cursor bigint := 0;
  v_summary_count integer := 0;
  v_summary_has_more boolean := false;
  v_total_applied integer := 0;
  v_total_blocked integer := 0;
  v_total_failed integer := 0;
  v_total_cancelled integer := 0;
  v_total_terminal integer := 0;
  v_request_result text;
  v_final_result jsonb;
  v_final_result_hash text;
  v_active_item_count integer := 0;
  v_active_candidate_count integer := 0;
  v_active_source_item_amount numeric(14,2) := 0;
  v_active_net_bank_amount numeric(14,2) := 0;
  v_active_paye_schedule_amount numeric(14,2) := 0;
  v_active_transfer_amount numeric(14,2) := 0;
  v_active_paye_candidate_count integer := 0;
  v_unselected_scope_hash_before text;
  v_unselected_scope_hash_after text;
  v_blocked_scope_mismatch_count integer := 0;
  v_requested_action text;
  v_refresh_cursor bigint := 0;
  v_refresh_next bigint := 0;
  v_refresh_candidate_ids jsonb := '[]'::jsonb;
  v_refresh_pay_batch_item_ids jsonb := '[]'::jsonb;
  v_refresh_count integer := 0;
  v_refresh_has_more boolean := false;
  v_refresh_result jsonb := '{}'::jsonb;
  v_refresh_sequence integer := 0;
  v_session_id uuid;
  v_session_version bigint;
  v_refresh_actor_user_id uuid;
  v_workbench_refresh_nudge jsonb := '{}'::jsonb;
  v_workbench_nudge_candidate_ids jsonb := '[]'::jsonb;
  v_workbench_nudge_job_ids jsonb := '[]'::jsonb;
  v_workbench_nudge_candidate_count integer := 0;
  v_workbench_nudge_job_count integer := 0;
  v_workbench_nudge_refresh_status text := 'NOT_REQUIRED';
  v_latest_refresh_payload jsonb := '{}'::jsonb;
  v_error_message text;
  v_error_state text;
  v_preflight record;
  v_auto_start_result jsonb := '{}'::jsonb;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_finalise_candidate_cursor uuid;
  v_finalise_first_candidate_id uuid;
  v_finalise_last_candidate_id uuid;
  v_finalise_page_sequence integer := 0;
  v_page_active_item_count integer := 0;
  v_page_active_candidate_count integer := 0;
  v_page_active_source_amount_pence bigint := 0;
  v_page_active_net_amount_pence bigint := 0;
  v_page_active_paye_candidate_count integer := 0;
  v_page_active_paye_amount_pence bigint := 0;
  v_page_active_transfer_amount_pence bigint := 0;
  v_page_blocked_scope_mismatch_count integer := 0;
  v_page_actionable_provider_scope_count integer := 0;
  v_page_unselected_chain_hash text;
  v_page_summary_hash text;
  v_actionable_cancelled_provider_scope_count integer := 0;
  v_source_event public.pay_bank_transfer_events%rowtype;
  v_auto_classification_result jsonb := '{}'::jsonb;
  v_auto_unwind_enabled boolean := false;
  v_existing_money_moved boolean := false;
  v_contention_retry_at timestamptz;
  v_cancel_reversion_observe_enabled boolean := false;
  v_cancel_reversion_publish_enabled boolean := false;
  v_scheduled_reversion_v2_observe_enabled boolean := false;
  v_scheduled_reversion_v2_publish_enabled boolean := false;
  v_held_dirty_absorption_enabled boolean := false;
  v_route_reversion_observe_enabled boolean := false;
  v_route_reversion_publish_enabled boolean := false;
  v_refresh_work_item_ids uuid[] := ARRAY[]::uuid[];
  v_reversion_admission jsonb := '{}'::jsonb;
  v_reversion_descriptors jsonb := '[]'::jsonb;
  v_reversion_candidate_ids jsonb := '[]'::jsonb;
  v_reversion_rejected_candidate_ids jsonb := '[]'::jsonb;
  v_reversion_publication jsonb := '{}'::jsonb;
  v_reversion_admitted_count integer := 0;
  v_financial_page_result jsonb := '{}'::jsonb;
  v_terminal_authorities_v2 jsonb := '{}'::jsonb;
  v_post_commit_authorities_v3 jsonb := '{}'::jsonb;
  v_terminal_authority_count integer := 0;
  v_held_dirty_resolution jsonb := '{}'::jsonb;
  v_finalise_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_physical_currentness jsonb := '{}'::jsonb;
  v_route_candidate_ids jsonb := '[]'::jsonb;
  v_route_work_item_ids jsonb := '[]'::jsonb;
  v_route_authorities_v3 jsonb := '{}'::jsonb;
  v_route_input jsonb := '{}'::jsonb;
  v_route_input_digest text;
  v_committed_route_input jsonb := '{}'::jsonb;
  v_committed_route_input_digest text;
  v_existing_refresh_result jsonb := '{}'::jsonb;
  v_existing_refresh_found boolean := false;
  v_q_bound_authority_set jsonb := '{}'::jsonb;
  v_q_bound_candidate_authorities jsonb := '{}'::jsonb;
  v_q_bound_execution_operation_id uuid;
  v_q_bound_route_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_q_bound_route_eligible_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_q_bound_route_eligible_candidate_count integer := 0;
  v_q_bound_chain_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_selected_anchor_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_affected_closure_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_residual_proof_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_parent_proof_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_pre_request_authority_digest_by_candidate jsonb := '{}'::jsonb;
  v_q_bound_route_replay jsonb := '{}'::jsonb;
  v_q_bound_route_replay_complete boolean := false;
  v_q_bound_route_replay_exact boolean := false;
  v_q_bound_authority_set_digest_recomputed text;
  v_standard_reversion_admission jsonb := '{}'::jsonb;
  v_execution_step text := 'INITIALISE';
BEGIN
  IF p_correction_request_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PROCESS_LIMIT_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'LIMIT_INVALID')::text;
  END IF;

  IF p_worker_id IS NULL OR pg_catalog.btrim(p_worker_id) = '' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_LEASE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'LEASE_REQUIRED')::text;
  END IF;

  SELECT
    COALESCE(settings_row.banking_pay_cancellation_reversion_observe_v1_enabled,false),
    COALESCE(settings_row.banking_pay_cancellation_reversion_publish_v1_enabled,false),
    COALESCE((pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_scheduled_cancellation_reversion_v2_observe_enabled')::boolean,false),
    COALESCE((pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_scheduled_cancellation_reversion_v2_publish_enabled')::boolean,false),
    COALESCE((pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_correction_held_dirty_route_absorption_v1_enabled')::boolean,false)
  INTO v_cancel_reversion_observe_enabled,v_cancel_reversion_publish_enabled,
       v_scheduled_reversion_v2_observe_enabled,v_scheduled_reversion_v2_publish_enabled,
       v_held_dirty_absorption_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  -- Resolve identifiers without row locks.  Every mutating phase then follows
  -- guard -> request -> batch -> operation.  PREPARE_SELECTION is non-gating
  -- and follows request -> batch -> operation.  No state transition, including
  -- START_AUTO, can occur before the exact lease has been validated.
  SELECT operation_row.id AS operation_id,
         operation_row.phase,
         operation_row.pay_batch_id AS operation_pay_batch_id,
         request_row.auto_requested,
         request_row.pay_batch_id,
         request_row.reason,
         request_row.source_bank_event_id,
         request_row.accepted_resolution_json
  INTO v_preflight
  FROM public.banking_pay_operations AS operation_row
  JOIN public.pay_payment_correction_requests AS request_row
    ON request_row.id::text = operation_row.input_json ->> 'correction_request_id'
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND request_row.id = p_correction_request_id
  ORDER BY operation_row.created_at_utc
  LIMIT 1;

  IF NOT FOUND
     OR v_preflight.operation_pay_batch_id IS DISTINCT FROM v_preflight.pay_batch_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_OPERATION_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'OPERATION_MISMATCH')::text;
  END IF;

  IF v_preflight.phase = 'AWAITING_REAUTHENTICATION'
     AND COALESCE(v_preflight.auto_requested, false) THEN
    v_mutation_guard := private.pay_payment_mutation_guard_v1(
      v_preflight.pay_batch_id,
      NULL::uuid,
      'NEW_PAYMENT_ACTION'
    );
  ELSIF v_preflight.phase NOT IN ('PREPARE_SELECTION', 'COMPLETE') THEN
    v_mutation_guard := private.pay_payment_mutation_guard_v1(
      v_preflight.pay_batch_id,
      p_correction_request_id,
      'CORRECTION_APPLY'
    );
  END IF;

  IF v_preflight.phase NOT IN ('PREPARE_SELECTION', 'COMPLETE')
     AND COALESCE((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_mutation_guard->>'code', 'PAYMENT_MUTATION_LOCK_TIMEOUT')
      USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
  END IF;

  SELECT request_row.* INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;
  IF NOT FOUND OR v_request.pay_batch_id IS DISTINCT FROM v_preflight.pay_batch_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_OPERATION_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'OPERATION_MISMATCH')::text;
  END IF;

  SELECT batch_row.* INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_request.pay_batch_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = v_preflight.operation_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_operation.operation_type IS DISTINCT FROM 'PAYMENT_CORRECTION'
     OR v_operation.input_json->>'correction_request_id' IS DISTINCT FROM p_correction_request_id::text
     OR v_operation.pay_batch_id IS DISTINCT FROM v_batch.id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'OPERATION_MISMATCH')::text;
  END IF;

  IF COALESCE(v_operation.lease_owner, v_operation.locked_by) IS NULL
     OR COALESCE(v_operation.lease_owner, v_operation.locked_by) IS DISTINCT FROM p_worker_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_LEASE_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'LEASE_MISMATCH')::text;
  END IF;
  IF COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc) IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_LEASE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'LEASE_REQUIRED')::text;
  END IF;
  IF COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc) <= v_now THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_LEASE_EXPIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'LEASE_MISMATCH')::text;
  END IF;

  IF v_operation.phase = 'AWAITING_REAUTHENTICATION'
     AND COALESCE(v_request.auto_requested, false) THEN
    -- Revalidate the exact automatic authority while the canonical locks and
    -- lease are held.  request_start re-enters the same transaction/locks.
    SELECT coalesce(settings_row.banking_pay_auto_unwind_terminal_no_money, false)
    INTO v_auto_unwind_enabled
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    SELECT event_row.*
    INTO v_source_event
    FROM public.pay_bank_transfer_events AS event_row
    WHERE event_row.id = v_request.source_bank_event_id
      AND event_row.pay_batch_id = v_batch.id;

    v_auto_classification_result := public._pay_payment_movement_classify(
      v_batch.id,
      v_request.selection_json
    );

    v_existing_money_moved := false;
    IF v_source_event.pay_bank_transfer_id IS NOT NULL THEN
      SELECT coalesce(movement_state.is_final_money_moved, false)
      INTO v_existing_money_moved
      FROM public.pay_bank_transfers AS transfer_row
      CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
        transfer_row.status,
        transfer_row.rail_state,
        coalesce(transfer_row.rail_meta_json, '{}'::jsonb),
        coalesce(transfer_row.rail_meta_json, '{}'::jsonb)
      ) AS movement_state
      WHERE transfer_row.id = v_source_event.pay_bank_transfer_id
      LIMIT 1;

      v_existing_money_moved := coalesce(v_existing_money_moved, false) OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS paid_event
        WHERE paid_event.pay_bank_transfer_id = v_source_event.pay_bank_transfer_id
          AND paid_event.id IS DISTINCT FROM v_source_event.id
          AND paid_event.normalised_state IN ('COMPLETED', 'PAID', 'SETTLED')
      );
    END IF;

    IF v_request.source_bank_event_id IS NULL
       OR v_request.selection_json->>'requested_action' IS DISTINCT FROM 'NO_MONEY_UNWIND'
       OR coalesce(v_auto_unwind_enabled, false) IS NOT TRUE
       OR v_source_event.id IS NULL
       OR v_source_event.pay_bank_transfer_id IS NULL
       OR v_source_event.event_source NOT IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
       OR v_source_event.provider_event_transport NOT IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
       OR v_source_event.mapping_status IS DISTINCT FROM 'MATCHED'
       OR v_source_event.mapping_method NOT IN (
         'TRANSFER_ID', 'PROVIDER_EVENT_ID', 'PROVIDER_TRANSACTION_ID', 'REQUEST_ID',
         'PROVIDER_REFERENCE', 'RAIL_TX_ID', 'MATCHED_PROVIDER_EVENT', 'MANUAL_TRANSFER_SELECTION'
       )
       OR v_source_event.normalised_state NOT IN ('FAILED', 'REJECTED', 'CANCELLED')
       OR v_source_event.correction_disposition IS DISTINCT FROM 'AUTO_PROCESSING'
       OR coalesce((v_auto_classification_result->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
       OR (
         v_auto_classification_result->>'classification' NOT IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
         AND v_auto_classification_result->>'recommended_action' IS DISTINCT FROM 'NO_MONEY_UNWIND_AND_RECALCULATE'
       )
       OR coalesce(v_existing_money_moved, false)
       OR pg_catalog.jsonb_typeof(v_request.accepted_resolution_json) IS DISTINCT FROM 'object'
       OR v_request.accepted_resolution_json->>'contract_version' IS DISTINCT FROM '2'
       OR v_request.accepted_resolution_json->>'requested_action' IS DISTINCT FROM 'NO_MONEY_UNWIND'
       OR v_request.accepted_resolution_json->>'source_bank_event_id' IS DISTINCT FROM v_source_event.id::text
       OR v_request.accepted_resolution_json->>'source' IS DISTINCT FROM v_source_event.provider_event_transport
       OR v_request.accepted_resolution_json->>'event_source' IS DISTINCT FROM v_source_event.event_source
       OR v_request.accepted_resolution_json->>'provider_key' IS DISTINCT FROM v_source_event.provider_key
       OR v_request.accepted_resolution_json->>'provider_event_id' IS DISTINCT FROM v_source_event.provider_event_id
       OR v_request.accepted_resolution_json->>'provider_event_key' IS DISTINCT FROM v_source_event.provider_event_key
       OR v_request.accepted_resolution_json->>'provider_webhook_receipt_id'
            IS DISTINCT FROM (CASE WHEN v_source_event.provider_webhook_receipt_id IS NULL THEN NULL ELSE v_source_event.provider_webhook_receipt_id::text END)
       OR v_request.accepted_resolution_json->>'provider_transaction_id' IS DISTINCT FROM v_source_event.provider_transaction_id
       OR v_request.accepted_resolution_json->>'provider_request_id' IS DISTINCT FROM v_source_event.provider_request_id
       OR v_request.accepted_resolution_json->>'mapping_status' IS DISTINCT FROM v_source_event.mapping_status
       OR v_request.accepted_resolution_json->>'mapping_method' IS DISTINCT FROM v_source_event.mapping_method
       OR v_request.accepted_resolution_json->>'normalised_state' IS DISTINCT FROM v_source_event.normalised_state
       OR v_request.accepted_resolution_json->>'classification' IS DISTINCT FROM v_auto_classification_result->>'classification'
       OR v_request.accepted_resolution_json->>'recommended_action' IS DISTINCT FROM v_auto_classification_result->>'recommended_action'
       OR coalesce((v_request.accepted_resolution_json->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
       OR v_request.accepted_resolution_json->>'correction_disposition' IS DISTINCT FROM 'AUTO_PROCESSING'
       OR coalesce((v_request.accepted_resolution_json->>'terminal_no_money_evidence')::boolean, false) IS NOT TRUE
       OR coalesce((v_request.accepted_resolution_json->>'signature_valid')::boolean, false)
            IS DISTINCT FROM coalesce(v_source_event.provider_signature_valid, (
              SELECT receipt_row.signature_valid
              FROM public.bank_provider_webhook_receipts AS receipt_row
              WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
            ), false)
       OR (
         v_source_event.provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
         AND (
           v_source_event.provider_webhook_receipt_id IS NULL
           OR coalesce(v_source_event.provider_signature_valid, (
             SELECT receipt_row.signature_valid
             FROM public.bank_provider_webhook_receipts AS receipt_row
             WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
           ), false) IS NOT TRUE
           OR NOT EXISTS (
             SELECT 1
             FROM public.bank_provider_webhook_receipts AS receipt_row
             WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
               AND receipt_row.signature_valid IS TRUE
               AND receipt_row.provider_key IS NOT DISTINCT FROM v_source_event.provider_key
               AND receipt_row.rail_env IS NOT DISTINCT FROM v_source_event.rail_env
               AND pg_catalog.upper(coalesce(receipt_row.status, '')) IN (
                 'VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED'
               )
           )
         )
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_AUTO_START_EVIDENCE_STALE'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_AUTO_EVIDENCE_INVALID',
          'source_bank_event_id', v_request.source_bank_event_id
        )::text;
    END IF;

    v_auto_start_result := public.pay_payment_correction_request_start(
      p_pay_batch_id := v_batch.id,
      p_selection_json := pg_catalog.jsonb_build_object(
        'command', 'START_AUTO', 'correction_request_id', p_correction_request_id
      ),
      p_reason := v_request.reason,
      p_actor_user_id := p_actor_user_id,
      p_source_bank_event_id := v_request.source_bank_event_id,
      p_auto_requested := true,
      p_accepted_resolution_json := v_request.accepted_resolution_json
    );

    RETURN v_auto_start_result || pg_catalog.jsonb_build_object(
      'phase_owner', 'pay_payment_correction_process_chunk',
      'automatic_provider_no_money', true, 'processed', 0, 'applied', 0,
      'skipped', 0, 'blocked', 0, 'failed_retryable', 0, 'failed_final', 0,
      'pending', 0, 'processing', 0, 'progress_completed', 0,
      'progress_total', 0, 'parent_status', v_auto_start_result->>'request_status',
      'totals', '{}'::jsonb, 'complete', false, 'requires_user_action', false,
      'processing_continues', true, 'changed_scope_json', '{}'::jsonb,
      'live_signal_updates', '{}'::jsonb
    );
  END IF;

  v_phase := v_operation.phase;
  v_requested_action := COALESCE(
    v_request.plan_json->>'requested_action', v_request.selection_json->>'requested_action'
  );
  v_route_reversion_observe_enabled:=COALESCE(v_cancel_reversion_observe_enabled,false)
    AND (
      v_requested_action='DRAFT_CANCEL'
      OR (v_requested_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
          AND COALESCE(v_scheduled_reversion_v2_observe_enabled,false))
    );
  v_route_reversion_publish_enabled:=COALESCE(v_cancel_reversion_publish_enabled,false)
    AND (
      v_requested_action='DRAFT_CANCEL'
      OR (v_requested_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
          AND COALESCE(v_scheduled_reversion_v2_publish_enabled,false))
    );

  IF v_phase = 'PREPARE_SELECTION' THEN
    v_phase_result := public.pay_payment_correction_selection_prepare_chunk_v1(
      p_correction_request_id,
      v_operation.id,
      v_operation.progress_json->'selection_cursor_json',
      GREATEST(LEAST(p_limit, 100), 50),
      p_worker_id,
      p_actor_user_id
    );
    RETURN v_phase_result || pg_catalog.jsonb_build_object(
      'phase_owner', 'pay_payment_correction_process_chunk',
      'processed', COALESCE((v_phase_result->>'page_candidate_count')::integer, 0),
      'applied', 0,
      'skipped', 0,
      'blocked', 0,
      'failed_retryable', 0,
      'failed_final', 0,
      'pending', 0,
      'processing', 0,
      'progress_completed', COALESCE(v_operation.completed_units, 0),
      'progress_total', COALESCE(v_operation.total_units, 0),
      'parent_status', v_request.status,
      'totals', pg_catalog.jsonb_build_object(
        'selected_candidate_count', v_request.plan_json->>'selected_candidate_count',
        'selected_active_item_count', v_request.plan_json->>'selected_active_item_count'
      ),
      'complete', COALESCE((v_phase_result->>'complete')::boolean, false),
      'requires_user_action', COALESCE((v_phase_result->>'complete')::boolean, false),
      'processing_continues', NOT COALESCE((v_phase_result->>'complete')::boolean, false),
      'changed_scope_json', '{}'::jsonb,
      'live_signal_updates', '{}'::jsonb,
      'continuation', pg_catalog.jsonb_build_object(
        'required', NOT COALESCE((v_phase_result->>'complete')::boolean, false),
        'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', CASE WHEN COALESCE((v_phase_result->>'complete')::boolean, false) THEN 'AWAITING_REAUTHENTICATION' ELSE 'PREPARE_SELECTION' END,
        'run_after_utc', CASE WHEN COALESCE((v_phase_result->>'complete')::boolean, false) THEN NULL ELSE v_now END,
        'reason', CASE WHEN COALESCE((v_phase_result->>'complete')::boolean, false) THEN 'SELECTION_READY_FOR_REVIEW' ELSE 'SELECTION_PAGE_COMPLETE' END,
        'successor_relation', CASE WHEN COALESCE((v_phase_result->>'complete')::boolean, false) THEN 'NONE' ELSE 'SELF' END,
        'requires_user_action', COALESCE((v_phase_result->>'complete')::boolean, false), 'terminal', false
      )
    );
  END IF;

  IF v_phase = 'EXPAND_WORK' THEN
    v_phase_result := public.pay_payment_correction_expand_work(p_correction_request_id, p_actor_user_id);
    RETURN v_phase_result || pg_catalog.jsonb_build_object(
      'phase_owner', 'pay_payment_correction_process_chunk',
      'processed', COALESCE((v_phase_result->>'page_work_count')::integer, 0),
      'applied', 0,
      'skipped', 0,
      'blocked', 0,
      'failed_retryable', 0,
      'failed_final', 0,
      'pending', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS pending_work
        WHERE pending_work.correction_request_id = p_correction_request_id
          AND pending_work.status = 'PENDING'
      ),
      'processing', 0,
      'progress_completed', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS expanded_work
        WHERE expanded_work.correction_request_id = p_correction_request_id
      ),
      'progress_total', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_request_candidates AS selected_member
        WHERE selected_member.correction_request_id = p_correction_request_id
      ),
      'parent_status', v_request.status,
      'totals', pg_catalog.jsonb_build_object(
        'inserted_count', v_phase_result->>'inserted_count',
        'existing_count', v_phase_result->>'existing_count'
      ),
      'complete', COALESCE((v_phase_result->>'complete')::boolean, false),
      'requires_user_action', false,
      'processing_continues', true,
      'changed_scope_json', '{}'::jsonb,
      'live_signal_updates', '{}'::jsonb,
      'continuation', pg_catalog.jsonb_build_object(
        'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', COALESCE(v_phase_result->>'phase', CASE WHEN COALESCE((v_phase_result->>'complete')::boolean, false) THEN 'PROCESS_CHUNKS' ELSE 'EXPAND_WORK' END),
        'run_after_utc', v_now, 'reason', 'PAYMENT_CORRECTION_EXPAND_MORE_WORK',
        'successor_relation', 'SELF', 'requires_user_action', false, 'terminal', false
      )
    );
  END IF;

  IF v_phase = 'PROCESS_CHUNKS' THEN
    v_claim_limit := LEAST(p_limit, 25);

    UPDATE public.pay_payment_correction_work_items AS stale_work
    SET status = CASE WHEN stale_work.attempt_count >= 5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
        locked_at_utc = NULL, locked_by = NULL,
        processed_at_utc = CASE WHEN stale_work.attempt_count >= 5 THEN v_now ELSE stale_work.processed_at_utc END,
        last_error = 'STALE_PROCESSING_LEASE_RECOVERED',
        result_json = COALESCE(stale_work.result_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'code', CASE
              WHEN stale_work.attempt_count >= 5 THEN 'FAILED_FINAL'
              ELSE 'ZERO_APPLIED_STALE_LEASE_RECOVERED'
            END,
            'stale_lease_recovered', true
          )
    WHERE stale_work.correction_request_id = p_correction_request_id
      AND stale_work.status = 'PROCESSING'
      AND stale_work.locked_at_utc < v_now - interval '120 seconds';

    DROP TABLE IF EXISTS pg_temp._bpay_correction_claimed_work_page;
    CREATE TEMP TABLE pg_temp._bpay_correction_claimed_work_page ON COMMIT DROP AS
    WITH claimable AS (
      SELECT work_row.id
      FROM public.pay_payment_correction_work_items AS work_row
      WHERE work_row.correction_request_id = p_correction_request_id
        AND work_row.status IN ('PENDING', 'FAILED_RETRYABLE')
        AND work_row.attempt_count < 5
      ORDER BY work_row.created_at_utc, work_row.id
      LIMIT v_claim_limit
      FOR UPDATE SKIP LOCKED
    ), claimed AS (
      UPDATE public.pay_payment_correction_work_items AS work_row
      SET status = 'PROCESSING', attempt_count = work_row.attempt_count + 1,
          locked_at_utc = v_now, locked_by = p_worker_id, last_error = NULL
      FROM claimable
      WHERE work_row.id = claimable.id
      RETURNING work_row.*
    )
    SELECT * FROM claimed;

    SELECT pg_catalog.count(*)::integer
    INTO v_claimed_count
    FROM pg_temp._bpay_correction_claimed_work_page;

    IF EXISTS (
      SELECT 1 FROM pg_temp._bpay_correction_claimed_work_page AS claimed_work
      WHERE claimed_work.work_kind='PRE_BANK_CANCEL'
    ) THEN
      v_financial_page_result := private.pay_pre_bank_cancel_apply_work_page_v1(
        p_correction_request_id,
        ARRAY(
          SELECT claimed_work.id
          FROM pg_temp._bpay_correction_claimed_work_page AS claimed_work
          WHERE claimed_work.work_kind='PRE_BANK_CANCEL'
          ORDER BY claimed_work.candidate_id,claimed_work.id
        ),
        p_actor_user_id,
        pg_catalog.jsonb_build_object('worker_id',p_worker_id)
      );
    ELSE
      v_financial_page_result := pg_catalog.jsonb_build_object(
        'ok',true,'candidate_results','[]'::jsonb
      );
    END IF;

    FOR v_work IN
      SELECT *
      FROM pg_temp._bpay_correction_claimed_work_page AS claimed_work
      ORDER BY claimed_work.created_at_utc,claimed_work.id
    LOOP
      BEGIN
        IF v_work.work_kind = 'PRE_BANK_CANCEL' THEN
          SELECT page_result.value->'result'
          INTO v_work_result
          FROM pg_catalog.jsonb_array_elements(
            COALESCE(v_financial_page_result->'candidate_results','[]'::jsonb)
          ) AS page_result(value)
          WHERE page_result.value->>'work_item_id'=v_work.id::text
          LIMIT 1;

          IF v_work_result IS NULL THEN
            RAISE EXCEPTION 'PRE_BANK_CANCEL_APPLY_PAGE_RESULT_MISSING'
              USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
                'code','PRE_BANK_CANCEL_APPLY_PAGE_RESULT_MISSING',
                'work_item_id',v_work.id
              )::text;
          END IF;
        ELSIF v_work.work_kind = 'NO_MONEY_UNWIND' THEN
          v_work_result := public.pay_no_money_unwind_apply_work_item(v_work.id, p_actor_user_id);
        ELSE
          v_work_result := pg_catalog.jsonb_build_object(
            'ok', false, 'status', 'BLOCKED',
            'blocker', pg_catalog.jsonb_build_object('code', 'BLOCKED_BY_UNSUPPORTED_SOURCE')
          );
        END IF;

        UPDATE public.pay_payment_correction_work_items AS completed_work
        SET status = CASE
              WHEN completed_work.status <> 'PROCESSING' THEN completed_work.status
              WHEN pg_catalog.upper(COALESCE(v_work_result->>'status', '')) IN ('APPLIED','BLOCKED','SKIPPED','FAILED_FINAL')
                THEN pg_catalog.upper(v_work_result->>'status')
              WHEN COALESCE((v_work_result->>'ok')::boolean, false) THEN 'APPLIED'
              ELSE 'BLOCKED'
            END,
            locked_at_utc = NULL, locked_by = NULL,
            processed_at_utc = COALESCE(completed_work.processed_at_utc, v_now),
            result_json = COALESCE(completed_work.result_json, '{}'::jsonb) || v_work_result
        WHERE completed_work.id = v_work.id;
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT, v_error_state = RETURNED_SQLSTATE;
        UPDATE public.pay_payment_correction_work_items AS failed_work
        SET status = CASE WHEN failed_work.attempt_count >= 5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
            locked_at_utc = NULL, locked_by = NULL,
            processed_at_utc = CASE WHEN failed_work.attempt_count >= 5 THEN v_now ELSE NULL END,
            last_error = v_error_message,
            result_json = COALESCE(failed_work.result_json, '{}'::jsonb)
              || pg_catalog.jsonb_build_object(
                'code', CASE WHEN failed_work.attempt_count >= 5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
                'sqlstate', v_error_state, 'message', v_error_message
              )
        WHERE failed_work.id = v_work.id;
      END;
    END LOOP;

    UPDATE public.pay_payment_correction_requests AS processing_request
    SET status = 'PROCESSING', updated_at_utc = v_now
    WHERE processing_request.id = p_correction_request_id
      AND processing_request.status IN ('EXPANDED', 'PROCESSING');

    SELECT
      pg_catalog.count(*) FILTER (WHERE work_row.status = 'APPLIED')::integer,
      pg_catalog.count(*) FILTER (WHERE work_row.status = 'BLOCKED')::integer,
      pg_catalog.count(*) FILTER (WHERE work_row.status = 'FAILED_FINAL')::integer,
      pg_catalog.count(*) FILTER (WHERE work_row.status = 'FAILED_RETRYABLE')::integer,
      pg_catalog.count(*) FILTER (WHERE work_row.status IN ('PENDING','PROCESSING','FAILED_RETRYABLE'))::integer
    INTO v_applied_count, v_blocked_count, v_failed_count, v_retryable_count, v_nonterminal_count
    FROM public.pay_payment_correction_work_items AS work_row
    WHERE work_row.correction_request_id = p_correction_request_id;

    v_contention_retry_at := v_now;
    IF v_claimed_count = 0 AND v_nonterminal_count > 0 THEN
      v_contention_retry_at := v_now + interval '5 seconds';
      SELECT GREATEST(
               v_contention_retry_at,
               coalesce(pg_catalog.min(active_work.locked_at_utc + interval '120 seconds'), v_contention_retry_at)
             )
      INTO v_contention_retry_at
      FROM public.pay_payment_correction_work_items AS active_work
      WHERE active_work.correction_request_id = p_correction_request_id
        AND active_work.status = 'PROCESSING'
        AND active_work.locked_at_utc IS NOT NULL;
    END IF;

    UPDATE public.banking_pay_operations AS processing_operation
    SET phase = CASE WHEN v_nonterminal_count = 0 THEN 'FINALISE' ELSE 'PROCESS_CHUNKS' END,
        status = 'RUNNING', runner_state = 'RUNNABLE', run_after_utc = v_contention_retry_at,
        completed_units = v_applied_count + v_blocked_count + v_failed_count,
        failed_units = v_blocked_count + v_failed_count,
        progress_json = COALESCE(processing_operation.progress_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'applied', v_applied_count, 'blocked', v_blocked_count,
            'failed_final', v_failed_count, 'failed_retryable', v_retryable_count
          ),
        updated_at_utc = v_now
    WHERE processing_operation.id = v_operation.id;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'correction_request_id', p_correction_request_id,
      'operation_id', v_operation.id, 'phase', CASE WHEN v_nonterminal_count = 0 THEN 'FINALISE' ELSE 'PROCESS_CHUNKS' END,
      'claimed_count', v_claimed_count, 'applied_count', v_applied_count,
      'blocked_count', v_blocked_count, 'failed_count', v_failed_count,
      'retryable_count', v_retryable_count,
      'processed', v_claimed_count,
      'applied', v_applied_count,
      'skipped', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS skipped_work
        WHERE skipped_work.correction_request_id = p_correction_request_id
          AND skipped_work.status = 'SKIPPED'
      ),
      'blocked', v_blocked_count,
      'failed_retryable', v_retryable_count,
      'failed_final', v_failed_count,
      'pending', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS pending_work
        WHERE pending_work.correction_request_id = p_correction_request_id
          AND pending_work.status = 'PENDING'
      ),
      'processing', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS active_work
        WHERE active_work.correction_request_id = p_correction_request_id
          AND active_work.status = 'PROCESSING'
      ),
      'progress_completed', v_applied_count + v_blocked_count + v_failed_count + (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS skipped_work
        WHERE skipped_work.correction_request_id = p_correction_request_id
          AND skipped_work.status = 'SKIPPED'
      ),
      'progress_total', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS all_work
        WHERE all_work.correction_request_id = p_correction_request_id
      ),
      'parent_status', 'PROCESSING',
      'totals', pg_catalog.jsonb_build_object(
        'applied', v_applied_count,
        'blocked', v_blocked_count,
        'failed_retryable', v_retryable_count,
        'failed_final', v_failed_count,
        'nonterminal', v_nonterminal_count
      ),
      'complete', false,
      'requires_user_action', false,
      'processing_continues', v_nonterminal_count > 0,
      'changed_scope_json', pg_catalog.jsonb_build_object(
        'pay_batch_id', v_request.pay_batch_id,
        'applied_candidate_count', v_applied_count
      ),
      'live_signal_updates', pg_catalog.jsonb_build_object(
        'overview_updated', v_applied_count > 0,
        'payment_status_updated', v_applied_count > 0
      ),
      'continuation', pg_catalog.jsonb_build_object(
        'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', CASE WHEN v_nonterminal_count = 0 THEN 'FINALISE' ELSE 'PROCESS_CHUNKS' END,
        'run_after_utc', v_contention_retry_at,
        'reason', CASE
          WHEN v_claimed_count = 0 AND v_nonterminal_count > 0
            THEN 'PAYMENT_CORRECTION_PROCESS_CONTENTION_RETRY'
          ELSE 'PAYMENT_CORRECTION_MORE_WORK'
        END,
        'successor_relation', 'SELF', 'requires_user_action', false, 'terminal', false
      ),
      'code', 'PAYMENT_CORRECTION_PROCESS_PAGE_COMPLETE'
    );
  END IF;

  IF v_phase = 'FINALISE' THEN
    IF EXISTS (
      SELECT 1 FROM public.pay_payment_correction_work_items AS nonterminal_work
      WHERE nonterminal_work.correction_request_id = p_correction_request_id
        AND nonterminal_work.status IN ('PENDING','PROCESSING','FAILED_RETRYABLE')
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_NONTERMINAL_WORK_REMAINS'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'NONTERMINAL_WORK_REMAINS')::text;
    END IF;

    v_finalise_candidate_cursor := NULLIF(
      v_operation.progress_json->>'last_finalised_candidate_id', ''
    )::uuid;
    v_finalise_page_sequence := COALESCE(
      NULLIF(v_operation.progress_json->>'finalise_page_sequence_no', '')::integer, 0
    ) + 1;

    WITH RECURSIVE candidate_page AS MATERIALIZED (
      SELECT candidate_row.id, candidate_row.candidate_id,
             candidate_row.net_bank_amount, candidate_row.settlement_status
      FROM public.pay_batch_candidates AS candidate_row
      WHERE candidate_row.pay_batch_id = v_request.pay_batch_id
        AND (v_finalise_candidate_cursor IS NULL OR candidate_row.id > v_finalise_candidate_cursor)
      ORDER BY candidate_row.id
      LIMIT 100
    ), candidate_facts AS MATERIALIZED (
      SELECT page_candidate.id AS pay_batch_candidate_id,
             page_candidate.candidate_id,
             page_candidate.net_bank_amount,
             page_candidate.settlement_status,
             member_row.selection_ordinal,
             member_row.candidate_scope_hash,
             member_row.active_amount AS selected_active_amount,
             member_row.active_item_count AS selected_active_item_count,
             member_row.pay_batch_item_ids AS selected_item_ids,
             work_row.status AS work_status,
             COALESCE(item_fact.active_item_count, 0)::integer AS active_item_count,
             COALESCE(item_fact.active_source_amount_pence, 0)::bigint AS active_source_amount_pence,
             COALESCE(item_fact.has_paye, false) AS has_paye,
             COALESCE(item_fact.active_item_ids, ARRAY[]::uuid[]) AS active_item_ids,
             private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
               'version', 1,
               'pay_batch_candidate_id', page_candidate.id,
               'candidate_id', page_candidate.candidate_id,
               'net_bank_amount_pence', pg_catalog.round(COALESCE(page_candidate.net_bank_amount, 0) * 100)::bigint,
               'settlement_status', page_candidate.settlement_status,
               'item_state', COALESCE(item_fact.item_state, '[]'::jsonb),
               'reservation_state', COALESCE(reservation_fact.reservation_state, '[]'::jsonb),
               'transfer_state', COALESCE(transfer_fact.transfer_state, '[]'::jsonb)
             )) AS candidate_audit_hash
      FROM candidate_page AS page_candidate
      LEFT JOIN public.pay_payment_correction_request_candidates AS member_row
        ON member_row.correction_request_id = p_correction_request_id
       AND member_row.pay_batch_candidate_id = page_candidate.id
      LEFT JOIN public.pay_payment_correction_work_items AS work_row
        ON work_row.correction_request_id = p_correction_request_id
       AND work_row.pay_batch_candidate_id = page_candidate.id
       AND work_row.selection_hash = member_row.candidate_scope_hash
      LEFT JOIN LATERAL (
        SELECT pg_catalog.count(*) FILTER (
                 WHERE COALESCE(item_row.is_voided, false) IS NOT TRUE
                   AND item_row.item_type <> 'DEBT_CREATED'
               )::integer AS active_item_count,
               COALESCE(pg_catalog.sum(item_row.amount_inc_vat) FILTER (
                 WHERE COALESCE(item_row.is_voided, false) IS NOT TRUE
                   AND item_row.item_type <> 'DEBT_CREATED'
               ), 0)::numeric * 100 AS active_source_amount_pence,
               pg_catalog.bool_or(
                 COALESCE(item_row.is_voided, false) IS NOT TRUE
                 AND pg_catalog.upper(COALESCE(item_row.pay_channel, '')) = 'PAYE'
               ) AS has_paye,
               pg_catalog.array_agg(item_row.id ORDER BY item_row.id) FILTER (
                 WHERE COALESCE(item_row.is_voided, false) IS NOT TRUE
               ) AS active_item_ids,
               pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
                 item_row.id, item_row.item_type, COALESCE(item_row.is_voided, false),
                 pg_catalog.round(COALESCE(item_row.amount_ex_vat, 0) * 100)::bigint,
                 pg_catalog.round(COALESCE(item_row.amount_vat, 0) * 100)::bigint,
                 pg_catalog.round(COALESCE(item_row.amount_inc_vat, 0) * 100)::bigint,
                 item_row.reservation_id, item_row.finance_component_id,
                 item_row.pay_bank_transfer_id, item_row.operation_source_key
               ) ORDER BY item_row.id) AS item_state
        FROM public.pay_batch_items AS item_row
        WHERE item_row.pay_batch_candidate_id = page_candidate.id
      ) AS item_fact ON true
      LEFT JOIN LATERAL (
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
          reservation_row.id, reservation_row.pay_batch_item_id,
          reservation_row.status, reservation_row.committed_at_utc,
          reservation_row.settled_at_utc, reservation_row.released_at_utc
        ) ORDER BY reservation_row.id) AS reservation_state
        FROM public.pay_advance_reservations AS reservation_row
        JOIN public.pay_batch_items AS reservation_item
          ON reservation_item.id = reservation_row.pay_batch_item_id
        WHERE reservation_item.pay_batch_candidate_id = page_candidate.id
          AND COALESCE(reservation_item.is_voided, false) IS NOT TRUE
      ) AS reservation_fact ON true
      LEFT JOIN LATERAL (
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
          transfer_row.id, transfer_row.status, transfer_row.rail_state,
          transfer_row.request_id, transfer_row.rail_tx_id,
          transfer_row.transfer_group_key
        ) ORDER BY transfer_row.id) AS transfer_state
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.id IN (
          SELECT transfer_item.pay_bank_transfer_id
          FROM public.pay_batch_items AS transfer_item
          WHERE transfer_item.pay_batch_candidate_id = page_candidate.id
            AND transfer_item.pay_bank_transfer_id IS NOT NULL
            AND COALESCE(transfer_item.is_voided, false) IS NOT TRUE
        )
      ) AS transfer_fact ON true
    ), numbered_facts AS (
      SELECT candidate_facts.*,
             pg_catalog.row_number() OVER (ORDER BY pay_batch_candidate_id)::integer AS rn
      FROM candidate_facts
    ), audit_chain(rn, chain_hash) AS (
      SELECT 0, COALESCE(
        v_operation.progress_json->>'finalise_unselected_chain_hash',
        private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
          'version', 1, 'correction_request_id', p_correction_request_id, 'chain', 'UNSELECTED'
        ))
      )
      UNION ALL
      SELECT fact_row.rn,
             CASE WHEN fact_row.selection_ordinal IS NULL
               THEN private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
                 'prior', audit_chain.chain_hash,
                 'candidate_hash', fact_row.candidate_audit_hash
               ))
               ELSE audit_chain.chain_hash END
      FROM audit_chain
      JOIN numbered_facts AS fact_row ON fact_row.rn = audit_chain.rn + 1
    ), page_transfer_ids AS (
      SELECT DISTINCT item_row.pay_bank_transfer_id
      FROM candidate_page AS page_candidate
      JOIN public.pay_batch_items AS item_row
        ON item_row.pay_batch_candidate_id = page_candidate.id
      WHERE COALESCE(item_row.is_voided, false) IS NOT TRUE
        AND item_row.pay_bank_transfer_id IS NOT NULL
    ), transfer_owner AS (
      SELECT transfer_row.id, transfer_row.amount,
             pg_catalog.min(owner_candidate.id::text)::uuid AS owner_candidate_id
      FROM public.pay_bank_transfers AS transfer_row
      JOIN page_transfer_ids ON page_transfer_ids.pay_bank_transfer_id = transfer_row.id
      JOIN public.pay_batch_items AS owner_item ON owner_item.pay_bank_transfer_id = transfer_row.id
      JOIN public.pay_batch_candidates AS owner_candidate
        ON owner_candidate.id = owner_item.pay_batch_candidate_id
       AND owner_candidate.pay_batch_id = v_request.pay_batch_id
      WHERE COALESCE(owner_item.is_voided, false) IS NOT TRUE
      GROUP BY transfer_row.id, transfer_row.amount
    )
    SELECT pg_catalog.count(*)::integer,
           pg_catalog.min(fact_row.pay_batch_candidate_id::text)::uuid,
           pg_catalog.max(fact_row.pay_batch_candidate_id::text)::uuid,
           pg_catalog.count(*) FILTER (WHERE fact_row.selection_ordinal IS NOT NULL)::integer,
           pg_catalog.count(*) FILTER (WHERE fact_row.work_status = 'APPLIED')::integer,
           pg_catalog.count(*) FILTER (WHERE fact_row.work_status IN ('BLOCKED','SKIPPED'))::integer,
           pg_catalog.count(*) FILTER (WHERE fact_row.work_status = 'FAILED_FINAL')::integer,
           pg_catalog.count(*) FILTER (WHERE fact_row.work_status = 'CANCELLED')::integer,
           COALESCE(pg_catalog.sum(fact_row.active_item_count), 0)::integer,
           pg_catalog.count(*) FILTER (WHERE fact_row.active_item_count > 0)::integer,
           COALESCE(pg_catalog.sum(fact_row.active_source_amount_pence), 0)::bigint,
           COALESCE(pg_catalog.sum(pg_catalog.round(COALESCE(fact_row.net_bank_amount, 0) * 100)::bigint)
             FILTER (WHERE fact_row.active_item_count > 0), 0)::bigint,
           pg_catalog.count(*) FILTER (WHERE fact_row.active_item_count > 0 AND fact_row.has_paye)::integer,
           COALESCE(pg_catalog.sum(pg_catalog.round(COALESCE(fact_row.net_bank_amount, 0) * 100)::bigint)
             FILTER (WHERE fact_row.active_item_count > 0 AND fact_row.has_paye), 0)::bigint,
           COALESCE((SELECT pg_catalog.sum(pg_catalog.round(COALESCE(transfer_owner.amount, 0) * 100)::bigint)
             FROM transfer_owner
             WHERE transfer_owner.owner_candidate_id IN (
               SELECT page_candidate.id FROM candidate_page AS page_candidate
             )), 0)::bigint,
           pg_catalog.count(*) FILTER (
             WHERE fact_row.selection_ordinal IS NOT NULL
               AND fact_row.work_status IS DISTINCT FROM 'APPLIED'
               AND (fact_row.net_bank_amount IS DISTINCT FROM fact_row.selected_active_amount
                 OR fact_row.active_item_ids IS DISTINCT FROM fact_row.selected_item_ids
                 OR EXISTS (
                   SELECT 1 FROM public.pay_payment_correction_items AS applied_item
                   WHERE applied_item.correction_request_id = p_correction_request_id
                     AND applied_item.pay_batch_candidate_id = fact_row.pay_batch_candidate_id
                     AND applied_item.status = 'APPLIED'
                 ))
           )::integer,
           COALESCE((
             SELECT pg_catalog.count(DISTINCT provider_transfer.id)::integer
             FROM candidate_facts AS selected_fact
             JOIN public.pay_batch_items AS selected_transfer_item
               ON selected_transfer_item.pay_batch_candidate_id = selected_fact.pay_batch_candidate_id
             JOIN public.pay_bank_transfers AS provider_transfer
               ON provider_transfer.id = selected_transfer_item.pay_bank_transfer_id
             WHERE selected_fact.selection_ordinal IS NOT NULL
               AND selected_fact.work_status = 'APPLIED'
               AND (
                 provider_transfer.status IN ('PENDING','SUBMITTED','PROCESSING','COMPLETED','PAID','SETTLED')
                 OR provider_transfer.rail_state IN ('PENDING','SUBMITTED','PROCESSING','COMPLETED','PAID','SETTLED')
               )
           ), 0)::integer,
           COALESCE((SELECT audit_chain.chain_hash FROM audit_chain
                     ORDER BY audit_chain.rn DESC LIMIT 1),
                    v_operation.progress_json->>'finalise_unselected_chain_hash')
    INTO v_summary_count, v_finalise_first_candidate_id, v_finalise_last_candidate_id,
         v_total_terminal, v_applied_count, v_blocked_count, v_failed_count, v_total_cancelled,
         v_page_active_item_count, v_page_active_candidate_count,
         v_page_active_source_amount_pence, v_page_active_net_amount_pence,
         v_page_active_paye_candidate_count, v_page_active_paye_amount_pence,
         v_page_active_transfer_amount_pence, v_page_blocked_scope_mismatch_count,
         v_page_actionable_provider_scope_count, v_page_unselected_chain_hash
    FROM candidate_facts AS fact_row;

    IF v_summary_count < 1 THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_FINALISE_ZERO_WORK'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'WORK_MEMBERSHIP_MISMATCH')::text;
    END IF;

    v_page_summary_hash := private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
      'version', 1, 'sequence_no', v_finalise_page_sequence,
      'first_candidate_id', v_finalise_first_candidate_id,
      'last_candidate_id', v_finalise_last_candidate_id,
      'candidate_count', v_summary_count, 'selected_terminal_count', v_total_terminal,
      'applied_count', v_applied_count, 'blocked_count', v_blocked_count,
      'failed_count', v_failed_count, 'cancelled_count', v_total_cancelled,
      'active_item_count', v_page_active_item_count,
      'active_candidate_count', v_page_active_candidate_count,
      'active_source_amount_pence', v_page_active_source_amount_pence,
      'active_net_amount_pence', v_page_active_net_amount_pence,
      'active_paye_candidate_count', v_page_active_paye_candidate_count,
      'active_paye_amount_pence', v_page_active_paye_amount_pence,
      'active_transfer_amount_pence', v_page_active_transfer_amount_pence,
      'unselected_chain_hash', v_page_unselected_chain_hash,
      'blocked_scope_mismatch_count', v_page_blocked_scope_mismatch_count
      , 'actionable_cancelled_provider_scope_count', v_page_actionable_provider_scope_count
    ));

    INSERT INTO public.banking_pay_operation_chunks (
      operation_id, phase, chunk_type, sequence_no, status, payload_json, result_json,
      error_json, unit_count, completed_count, failed_count, started_at_utc, completed_at_utc
    ) VALUES (
      v_operation.id, 'FINALISE', 'CANDIDATE_SCOPE', v_finalise_page_sequence,
      'COMPLETE', pg_catalog.jsonb_build_object(
        'after_candidate_id', v_finalise_candidate_cursor, 'limit', 100
      ), pg_catalog.jsonb_build_object(
        'first_candidate_id', v_finalise_first_candidate_id,
        'last_candidate_id', v_finalise_last_candidate_id,
        'candidate_count', v_summary_count, 'terminal_count', v_total_terminal,
        'applied_count', v_applied_count, 'blocked_count', v_blocked_count,
        'failed_count', v_failed_count, 'cancelled_count', v_total_cancelled,
        'active_item_count', v_page_active_item_count,
        'active_candidate_count', v_page_active_candidate_count,
        'active_source_amount_pence', v_page_active_source_amount_pence,
        'active_net_amount_pence', v_page_active_net_amount_pence,
        'active_paye_candidate_count', v_page_active_paye_candidate_count,
        'active_paye_amount_pence', v_page_active_paye_amount_pence,
        'active_transfer_amount_pence', v_page_active_transfer_amount_pence,
        'unselected_chain_hash', v_page_unselected_chain_hash,
        'blocked_scope_mismatch_count', v_page_blocked_scope_mismatch_count,
        'actionable_cancelled_provider_scope_count', v_page_actionable_provider_scope_count,
        'summary_hash', v_page_summary_hash
      ), NULL, v_summary_count, v_summary_count,
      v_blocked_count + v_failed_count, v_now, v_now
    ) ON CONFLICT (operation_id, phase, chunk_type, sequence_no) DO NOTHING;

    IF NOT FOUND AND NOT EXISTS (
      SELECT 1 FROM public.banking_pay_operation_chunks AS existing_summary
      WHERE existing_summary.operation_id = v_operation.id
        AND existing_summary.phase = 'FINALISE'
        AND existing_summary.chunk_type = 'CANDIDATE_SCOPE'
        AND existing_summary.sequence_no = v_finalise_page_sequence
        AND existing_summary.result_json->>'summary_hash' = v_page_summary_hash
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_FINALISE_PAGE_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAGE_DIGEST_MISMATCH')::text;
    END IF;

    v_summary_has_more := EXISTS (
      SELECT 1 FROM public.pay_batch_candidates AS remaining_candidate
      WHERE remaining_candidate.pay_batch_id = v_request.pay_batch_id
        AND remaining_candidate.id > v_finalise_last_candidate_id
    );

    IF v_summary_has_more THEN
      UPDATE public.banking_pay_operations AS summary_operation
      SET progress_json = COALESCE(summary_operation.progress_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'last_finalised_candidate_id', v_finalise_last_candidate_id,
              'finalise_page_sequence_no', v_finalise_page_sequence,
              'finalise_unselected_chain_hash', v_page_unselected_chain_hash
            ),
          run_after_utc = v_now, updated_at_utc = v_now
      WHERE summary_operation.id = v_operation.id;
      RETURN pg_catalog.jsonb_build_object(
        'ok', true, 'phase', 'FINALISE', 'summary_count', v_summary_count,
        'last_finalised_candidate_id', v_finalise_last_candidate_id, 'complete', false,
        'processed', v_summary_count,
        'applied', v_applied_count,
        'skipped', v_total_cancelled,
        'blocked', v_blocked_count,
        'failed_retryable', 0,
        'failed_final', v_failed_count,
        'pending', 0,
        'processing', 0,
        'progress_completed', v_finalise_page_sequence * 100,
        'progress_total', (
          SELECT pg_catalog.count(*)::integer
          FROM public.pay_payment_correction_request_candidates AS all_member
          WHERE all_member.correction_request_id = p_correction_request_id
        ),
        'parent_status', v_request.status,
        'totals', pg_catalog.jsonb_build_object(
          'page_terminal', v_summary_count,
          'page_applied', v_applied_count,
          'page_blocked', v_blocked_count,
          'page_failed_final', v_failed_count,
          'page_cancelled', v_total_cancelled
        ),
        'requires_user_action', false,
        'processing_continues', true,
        'changed_scope_json', '{}'::jsonb,
        'live_signal_updates', '{}'::jsonb,
        'continuation', pg_catalog.jsonb_build_object(
          'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
          'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
          'phase', 'FINALISE', 'run_after_utc', v_now, 'reason', 'PAYMENT_CORRECTION_FINALISE_MORE_WORK',
          'successor_relation', 'SELF', 'requires_user_action', false, 'terminal', false
        ),
        'code', 'PAYMENT_CORRECTION_FINALISE_SUMMARY_COMPLETE'
      );
    END IF;

    SELECT
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'terminal_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'applied_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'blocked_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'failed_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'cancelled_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_item_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_candidate_count')::integer), 0)::integer,
      (COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_source_amount_pence')::bigint), 0)::numeric / 100)::numeric(14,2),
      (COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_net_amount_pence')::bigint), 0)::numeric / 100)::numeric(14,2),
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_paye_candidate_count')::integer), 0)::integer,
      (COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_paye_amount_pence')::bigint), 0)::numeric / 100)::numeric(14,2),
      (COALESCE(pg_catalog.sum((chunk_row.result_json->>'active_transfer_amount_pence')::bigint), 0)::numeric / 100)::numeric(14,2),
      COALESCE((pg_catalog.array_agg(chunk_row.result_json->>'unselected_chain_hash'
        ORDER BY chunk_row.sequence_no DESC))[1], NULL),
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'blocked_scope_mismatch_count')::integer), 0)::integer,
      COALESCE(pg_catalog.sum((chunk_row.result_json->>'actionable_cancelled_provider_scope_count')::integer), 0)::integer
    INTO v_total_terminal, v_total_applied, v_total_blocked, v_total_failed, v_total_cancelled,
         v_active_item_count, v_active_candidate_count, v_active_source_item_amount,
         v_active_net_bank_amount, v_active_paye_candidate_count,
         v_active_paye_schedule_amount, v_active_transfer_amount,
         v_unselected_scope_hash_after, v_blocked_scope_mismatch_count,
         v_actionable_cancelled_provider_scope_count
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = v_operation.id
      AND chunk_row.phase = 'FINALISE'
      AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
      AND chunk_row.status = 'COMPLETE';

    IF v_finalise_page_sequence > 100 OR (
      SELECT COALESCE(pg_catalog.sum((chunk_row.result_json->>'candidate_count')::integer), 0)
      FROM public.banking_pay_operation_chunks AS chunk_row
      WHERE chunk_row.operation_id = v_operation.id
        AND chunk_row.phase = 'FINALISE'
        AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
        AND chunk_row.status = 'COMPLETE'
    ) > 10000 THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_FINALISE_CAPACITY_EXCEEDED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'CAPACITY_EXCEEDED')::text;
    END IF;

    IF v_total_terminal = 0 THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_FINALISE_ZERO_WORK'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'WORK_MEMBERSHIP_MISMATCH')::text;
    END IF;

    v_request_result := CASE
      WHEN v_total_applied = v_total_terminal THEN 'APPLIED'
      WHEN v_total_applied > 0 THEN 'APPLIED_WITH_BLOCKERS'
      WHEN v_total_failed > 0 AND v_total_blocked = 0 AND v_total_cancelled = 0 THEN 'FAILED'
      WHEN v_total_cancelled = v_total_terminal THEN 'CANCELLED'
      ELSE 'BLOCKED'
    END;

    -- All active, PAYE and transfer totals and both integrity proofs were
    -- produced by the durable candidate-page summaries above.  This reducer
    -- reads summaries only and never reconstructs the full candidate scope.
    SELECT COALESCE(pg_catalog.array_agg(DISTINCT batch_candidate.candidate_id
             ORDER BY batch_candidate.candidate_id),ARRAY[]::uuid[])
    INTO v_finalise_candidate_ids
    FROM public.pay_payment_correction_request_candidates AS request_candidate
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=request_candidate.pay_batch_candidate_id
    WHERE request_candidate.correction_request_id=p_correction_request_id;

    -- Every FINALISE write remains ordinary dirty evidence, but it is stamped
    -- before the first batch/request mutation as correction-owned terminal
    -- orchestration.  The exact same held job is therefore parked until route
    -- election rather than misclassified as a new economic change.
    IF pg_catalog.cardinality(v_finalise_candidate_ids)>0 THEN
      PERFORM private.pay_workbench_correction_dirty_context_set_v1(
        p_correction_request_id,v_request.pay_batch_id,v_finalise_candidate_ids,
        'FINANCIAL_TERMINAL','PRE_DRAFT_LIVE_TRUTH',
        COALESCE(v_operation.input_json->'draft_overlay_fast_start_authorities','{}'::jsonb)
          || COALESCE(v_operation.input_json->'cancellation_reversion_start_authorities_v2','{}'::jsonb),
        v_operation.id,NULL::uuid,
        pg_catalog.jsonb_build_object('owner','pay_payment_correction_process_chunk')
      );
    END IF;

    v_unselected_scope_hash_before := v_request.plan_json->>'unselected_scope_hash_before';
    IF v_unselected_scope_hash_before IS NULL
       OR v_unselected_scope_hash_after IS DISTINCT FROM v_unselected_scope_hash_before
       OR v_blocked_scope_mismatch_count > 0
       OR v_actionable_cancelled_provider_scope_count > 0 THEN
      v_final_result := pg_catalog.jsonb_build_object(
        'request_status', 'FAILED',
        'code', 'PAYMENT_CORRECTION_SCOPE_INTEGRITY_CONFLICT',
        'unselected_scope_hash_before', v_unselected_scope_hash_before,
        'unselected_scope_hash_after', v_unselected_scope_hash_after,
        'unselected_unchanged', v_unselected_scope_hash_before IS NOT NULL
          AND v_unselected_scope_hash_after = v_unselected_scope_hash_before,
        'blocked_scope_mismatch_count', v_blocked_scope_mismatch_count,
        'applied_candidate_count', v_total_applied,
        'blocked_candidate_count', v_total_blocked,
        'failed_candidate_count', v_total_failed,
        'user_message', 'The remaining payment scope changed during cancellation. CloudTMS has stopped normal completion and requires review.'
      );
      v_final_result_hash := private.pay_payment_correction_sha256_v1(v_final_result);

      UPDATE public.pay_batches AS integrity_batch
      -- AWAITING_AUTHORISATION is the in-flight correction fence.  Once the
      -- correction is financially terminal, any intact remainder must return
      -- to the existing reviewable DRAFT execution contract.  Leaving a
      -- terminal remainder in AWAITING_AUTHORISATION creates a dead-end because
      -- operation-scoped prepare/auth deliberately accepts DRAFT only.
      SET status = CASE WHEN v_active_item_count = 0 THEN 'CANCELLED' ELSE 'DRAFT' END,
          total_bank_out = v_active_net_bank_amount,
          schedule_kind = NULL, scheduled_at_utc = NULL, scheduled_by_user_id = NULL,
          funding_account_ref = NULL, funds_warning_hours_json = NULL
      WHERE integrity_batch.id = v_request.pay_batch_id;

      UPDATE public.pay_payment_correction_requests AS integrity_request
      SET status = 'FAILED',
          applied_at_utc = CASE WHEN v_total_applied > 0 THEN COALESCE(integrity_request.applied_at_utc, v_now) ELSE integrity_request.applied_at_utc END,
          plan_json = COALESCE(integrity_request.plan_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'unselected_scope_hash_after', v_unselected_scope_hash_after,
              'blocked_scope_mismatch_count', v_blocked_scope_mismatch_count,
              'final_result', v_final_result,
              'final_result_hash', v_final_result_hash,
              'finalised_at_utc', v_now
            ),
          updated_at_utc = v_now
      WHERE integrity_request.id = p_correction_request_id;

      UPDATE public.banking_pay_operations AS integrity_operation
      SET phase = 'REFRESH_WORKBENCH', status = 'RUNNING', runner_state = 'RUNNABLE',
          requires_user_action = false, run_after_utc = v_now,
          result_json = COALESCE(integrity_operation.result_json, '{}'::jsonb) || v_final_result,
          error_json = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_SCOPE_INTEGRITY_CONFLICT'),
          progress_json = COALESCE(integrity_operation.progress_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object('financial_finalised', false, 'integrity_review_required', true),
          updated_at_utc = v_now
      WHERE integrity_operation.id = v_operation.id;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
        action_at_utc, note, before_json, after_json, metadata_json
      ) VALUES (
        p_correction_request_id, v_request.pay_batch_id, 'SYSTEM', p_actor_user_id,
        'APPLY', v_now, 'Correction scope integrity conflict.',
        pg_catalog.jsonb_build_object('unselected_scope_hash_before', v_unselected_scope_hash_before),
        v_final_result,
        pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_SCOPE_INTEGRITY_CONFLICT', 'final_result_hash', v_final_result_hash)
      );

      PERFORM public.pay_batch_display_summary_refresh(v_request.pay_batch_id);
      RETURN pg_catalog.jsonb_build_object(
        'ok', false, 'phase', 'REFRESH_WORKBENCH', 'financial_complete', false,
        'request_status', 'FAILED', 'result', v_final_result,
        'complete', false, 'requires_user_action', true,
        'processing_continues', true,
        'continuation', pg_catalog.jsonb_build_object(
          'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
          'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
          'phase', 'REFRESH_WORKBENCH', 'run_after_utc', v_now,
          'reason', 'PAYMENT_CORRECTION_INTEGRITY_REFRESH', 'successor_relation', 'SELF',
          'requires_user_action', false, 'terminal', false
        ),
        'code', 'PAYMENT_CORRECTION_SCOPE_INTEGRITY_CONFLICT'
      );
    END IF;

    UPDATE public.pay_batches AS reconciled_batch
    SET status = CASE
          WHEN v_active_item_count = 0 THEN 'CANCELLED'
          ELSE 'DRAFT'
        END,
        cancelled_at_utc = CASE WHEN v_active_item_count = 0 THEN COALESCE(reconciled_batch.cancelled_at_utc, v_now) ELSE reconciled_batch.cancelled_at_utc END,
        cancelled_by_user_id = CASE WHEN v_active_item_count = 0 THEN COALESCE(reconciled_batch.cancelled_by_user_id, p_actor_user_id) ELSE reconciled_batch.cancelled_by_user_id END,
        cancel_reason = CASE WHEN v_active_item_count = 0 THEN COALESCE(reconciled_batch.cancel_reason, v_request.reason) ELSE reconciled_batch.cancel_reason END,
        schedule_kind = CASE WHEN v_requested_action = 'DRAFT_CANCEL' THEN reconciled_batch.schedule_kind ELSE NULL END,
        scheduled_at_utc = CASE WHEN v_requested_action = 'DRAFT_CANCEL' THEN reconciled_batch.scheduled_at_utc ELSE NULL END,
        scheduled_by_user_id = CASE WHEN v_requested_action = 'DRAFT_CANCEL' THEN reconciled_batch.scheduled_by_user_id ELSE NULL END,
        funding_account_ref = CASE WHEN v_requested_action = 'DRAFT_CANCEL' THEN reconciled_batch.funding_account_ref ELSE NULL END,
        funds_warning_hours_json = CASE WHEN v_requested_action = 'DRAFT_CANCEL' THEN reconciled_batch.funds_warning_hours_json ELSE NULL END,
        total_bank_out = v_active_net_bank_amount
    WHERE reconciled_batch.id = v_request.pay_batch_id;

    v_final_result := pg_catalog.jsonb_build_object(
      'request_status', v_request_result, 'selected_candidate_count', v_total_terminal,
      'applied_candidate_count', v_total_applied, 'blocked_candidate_count', v_total_blocked,
      'failed_candidate_count', v_total_failed, 'cancelled_candidate_count', v_total_cancelled,
      'active_overview_candidate_count', v_active_candidate_count,
      'active_overview_amount_pence', pg_catalog.round(v_active_net_bank_amount * 100)::bigint,
      'active_candidate_net_bank_amount_pence', pg_catalog.round(v_active_net_bank_amount * 100)::bigint,
      'active_frozen_source_item_amount_pence', pg_catalog.round(v_active_source_item_amount * 100)::bigint,
      'active_paye_schedule_candidate_count', v_active_paye_candidate_count,
      'active_paye_schedule_amount_pence', pg_catalog.round(v_active_paye_schedule_amount * 100)::bigint,
      'active_transfer_amount_pence', pg_catalog.round(v_active_transfer_amount * 100)::bigint,
      'batch_total_bank_out_pence', pg_catalog.round(v_active_net_bank_amount * 100)::bigint,
      'active_paye_schedule_derived_from_unvoided_frozen_items', true,
      'unselected_scope_hash_before', v_unselected_scope_hash_before,
      'unselected_scope_hash_after', v_unselected_scope_hash_after,
      'unselected_unchanged', true,
      'blocked_scope_mismatch_count', 0,
      'reauthorisation_required', v_active_item_count > 0 AND v_requested_action <> 'DRAFT_CANCEL'
    );
    v_final_result_hash := private.pay_payment_correction_sha256_v1(v_final_result);

    UPDATE public.pay_payment_correction_requests AS final_request
    SET status = v_request_result,
        applied_at_utc = CASE WHEN v_total_applied > 0 THEN COALESCE(final_request.applied_at_utc, v_now) ELSE final_request.applied_at_utc END,
        cancelled_at_utc = CASE WHEN v_request_result = 'CANCELLED' THEN COALESCE(final_request.cancelled_at_utc, v_now) ELSE final_request.cancelled_at_utc END,
        plan_json = COALESCE(final_request.plan_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object('final_result', v_final_result, 'final_result_hash', v_final_result_hash, 'finalised_at_utc', v_now),
        updated_at_utc = v_now
    WHERE final_request.id = p_correction_request_id;

    UPDATE public.banking_pay_operations AS final_operation
    SET phase = 'REFRESH_WORKBENCH', status = 'RUNNING', runner_state = 'RUNNABLE',
        requires_user_action = false, run_after_utc = v_now,
        result_json = COALESCE(final_operation.result_json, '{}'::jsonb) || v_final_result,
        progress_json = COALESCE(final_operation.progress_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'last_finalised_candidate_id', v_finalise_last_candidate_id,
            'finalise_page_sequence_no', v_finalise_page_sequence,
            'finalise_unselected_chain_hash', v_unselected_scope_hash_after,
            'financial_finalised', true
          ),
        updated_at_utc = v_now
    WHERE final_operation.id = v_operation.id;

    PERFORM public.pay_batch_display_summary_refresh(v_request.pay_batch_id);
    PERFORM public.banking_pay_batch_signal_touch(
      p_pay_batch_id := v_request.pay_batch_id,
      p_change_reason := 'PAYMENT_CORRECTION_FINALISED',
      p_change_source := 'pay_payment_correction_process_chunk',
      p_change_scope_json := v_final_result,
      p_touch_payment_status := true,
      p_touch_correction_progress := true,
      p_touch_alerts := false,
      p_touch_overview := true
    );

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
      action_at_utc, note, before_json, after_json, metadata_json
    ) VALUES (
      p_correction_request_id, v_request.pay_batch_id, 'SYSTEM', p_actor_user_id,
      'APPLY', v_now, 'Correction financial finalisation complete.', NULL,
      v_final_result, pg_catalog.jsonb_build_object('final_result_hash', v_final_result_hash)
    );

    -- FINALISE can itself stage a deferred candidate-scope generation.  Do not
    -- claim that the pre-commit sequence/generation is terminal authority.
    -- Persist only the immutable financial result and exact causal token.  The
    -- first REFRESH_WORKBENCH transaction derives V3 authority after the
    -- deferred constraint trigger has committed its generation.
    FOR v_work IN
      SELECT DISTINCT applied_work.candidate_id
      FROM public.pay_payment_correction_work_items AS applied_work
      WHERE applied_work.correction_request_id=p_correction_request_id
        AND applied_work.status='APPLIED'
        AND applied_work.candidate_id IS NOT NULL
      ORDER BY applied_work.candidate_id
    LOOP
      v_execution_step:='FINALISE_CANDIDATE_SERIAL_LOCK';
      BEGIN
        PERFORM pg_catalog.pg_advisory_xact_lock(
          pg_catalog.hashtextextended(
            public._pay_workbench_candidate_serial_key(v_work.candidate_id),24062027
          )
        );
      EXCEPTION WHEN lock_not_available THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_FINALISE_STEP_FAILED'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'contract_version','PAYMENT_CORRECTION_FINALISE_ERROR_V1',
            'code','PAYMENT_CORRECTION_FINALISE_STEP_FAILED',
            'phase','FINALISE','step',v_execution_step,
            'database_error_class','LOCK_NOT_AVAILABLE',
            'logical_lock_resource','WORKBENCH_CANDIDATE_SERIAL',
            -- Stage 1 deliberately records the exact step and SQLSTATE while
            -- leaving retry classification inert.  The TEST contention harness
            -- must prove the observed boundary before this may be promoted to
            -- LOCK_CONTENTION_BEFORE_ROUTE.
            'retry_class','UNCLASSIFIED',
            'original_sqlstate',SQLSTATE,
            'correction_request_id',p_correction_request_id,
            'operation_id',v_operation.id,'pay_batch_id',v_request.pay_batch_id,
            'candidate_id',v_work.candidate_id,
            'financial_work_item_count',v_total_terminal,
            'financial_applied_count',v_total_applied,
            'financial_nonterminal_count',v_nonterminal_count,
            'route_input_committed',false,
            'route_result_committed',false
          )::text;
      END;
    END LOOP;

    WITH terminal_rows AS (
      SELECT
        applied_work.candidate_id,
        applied_work.id AS work_item_id,
        COALESCE(
          correction_operation.input_json->'cancellation_reversion_start_authorities_v3'
            ->applied_work.candidate_id::text,
          correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
            ->applied_work.candidate_id::text
        ) AS start_authority,
        pg_catalog.md5((COALESCE(applied_work.result_json,'{}'::jsonb)
          -'applied_at_utc'-'processed_at_utc')::text) AS financial_result_digest
      FROM public.pay_payment_correction_work_items AS applied_work
      JOIN public.banking_pay_operations AS correction_operation
        ON correction_operation.id=v_operation.id
      WHERE applied_work.correction_request_id=p_correction_request_id
        AND applied_work.status='APPLIED'
        AND applied_work.candidate_id IS NOT NULL
    )
    SELECT COALESCE(pg_catalog.jsonb_object_agg(
      terminal_rows.candidate_id::text,
      pg_catalog.jsonb_build_object(
        'contract_version','POST_FINANCIAL_TERMINAL_AWAITING_COMMIT_V3',
        'correction_request_id',p_correction_request_id,
        'operation_id',v_operation.id,
        'work_item_id',terminal_rows.work_item_id,
        'candidate_id',terminal_rows.candidate_id,
        'held_dirty_job_id',terminal_rows.start_authority->>'request_owned_dirty_job_id',
        'scope_change_tx_token',terminal_rows.start_authority->>'request_owned_scope_change_tx_token',
        'start_authority_digest',terminal_rows.start_authority->>'fence_digest',
        'financial_result_digest',terminal_rows.financial_result_digest,
        'authority_digest',pg_catalog.md5(
          p_correction_request_id::text||'|'||v_operation.id::text||'|'||
          terminal_rows.work_item_id::text||'|'||terminal_rows.candidate_id::text||'|'||
          COALESCE(terminal_rows.start_authority->>'request_owned_dirty_job_id','')||'|'||
          COALESCE(terminal_rows.start_authority->>'request_owned_scope_change_tx_token','')||'|'||
          COALESCE(terminal_rows.start_authority->>'fence_digest','')||'|'||
          terminal_rows.financial_result_digest||'|POST_FINANCIAL_TERMINAL_AWAITING_COMMIT_V3'
        )
      ) ORDER BY terminal_rows.candidate_id
    ),'{}'::jsonb)
    INTO v_terminal_authorities_v2
    FROM terminal_rows;

    SELECT pg_catalog.count(*)::integer
    INTO v_terminal_authority_count
    FROM pg_catalog.jsonb_object_keys(v_terminal_authorities_v2);

    UPDATE public.banking_pay_operations AS terminal_authority_operation
    SET input_json=COALESCE(terminal_authority_operation.input_json,'{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'cancellation_reversion_post_financial_terminal_awaiting_commit_v3',
            v_terminal_authorities_v2
          ),
        progress_json=COALESCE(terminal_authority_operation.progress_json,'{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'post_financial_terminal_awaiting_commit_v3',true,
            'post_financial_terminal_awaiting_commit_v3_candidate_count',
              v_terminal_authority_count
          ),
        updated_at_utc=pg_catalog.clock_timestamp()
    WHERE terminal_authority_operation.id=v_operation.id
    RETURNING terminal_authority_operation.* INTO v_operation;

    -- The grouped success alert belongs to durable financial success.  It is
    -- not delayed until Workbench publication, and one request still owns one
    -- alert regardless of candidate count.
    IF v_request_result IN ('APPLIED','APPLIED_WITH_BLOCKERS')
       AND EXISTS (
         SELECT 1 FROM public.pay_payment_correction_work_items AS successful_work
         WHERE successful_work.correction_request_id=p_correction_request_id
           AND successful_work.status='APPLIED'
       ) THEN
      INSERT INTO public.banking_alert_success_events (
        pay_batch_id,alert_kind,event_key,payload_json,occurred_at_utc,
        expires_at_utc,created_at_utc,updated_at_utc
      )
      SELECT v_request.pay_batch_id,'BATCH_CANCELLATION_SUCCESS',
        'CANCELLATION:'||p_correction_request_id::text,
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'contract_version','BANKING_ALERT_CANCELLATION_SUCCESS_V2',
          'correction_request_id',p_correction_request_id::text,
          'operation_id',v_operation.id::text,
          'pay_batch_id',v_request.pay_batch_id::text,
          'cancelled_payment_count',frozen_scope.payment_count,
          'cancelled_amount_pence',frozen_scope.amount_pence,
          'workbench_status','PENDING',
          'user_label',frozen_scope.payment_count::text||' payment'||
            CASE WHEN frozen_scope.payment_count=1 THEN '' ELSE 's' END||' cancelled',
          'user_description','Financial cancellation completed for '||
            frozen_scope.payment_count::text||' payment'||
            CASE WHEN frozen_scope.payment_count=1 THEN '' ELSE 's' END||
            '. Banking Pay is updating quietly.',
          'required_user_action',NULL,
          'stable_issue_key',v_request.pay_batch_id::text||
            ':BATCH_CANCELLATION_SUCCESS:'||p_correction_request_id::text,
          'dedupe_key',v_request.pay_batch_id::text||
            ':BATCH_CANCELLATION_SUCCESS:'||p_correction_request_id::text,
          'policy_x_source','FROZEN_CORRECTION_REQUEST_MEMBERSHIP'
        )),v_now,v_now+interval '365 days',v_now,v_now
      FROM (
        SELECT pg_catalog.count(*)::integer AS payment_count,
          pg_catalog.round(COALESCE(pg_catalog.sum(member.active_amount),0)*100)::bigint AS amount_pence
        FROM public.pay_payment_correction_request_candidates AS member
        WHERE member.correction_request_id=p_correction_request_id
      ) AS frozen_scope
      WHERE frozen_scope.payment_count>0
      ON CONFLICT (pay_batch_id,alert_kind,event_key) DO NOTHING;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'phase', 'REFRESH_WORKBENCH', 'financial_complete', true,
      'request_status', v_request_result, 'result', v_final_result,
      'processed', v_total_terminal,
      'applied', v_total_applied,
      'skipped', v_total_cancelled,
      'blocked', v_total_blocked,
      'failed_retryable', 0,
      'failed_final', v_total_failed,
      'pending', 0,
      'processing', 0,
      'progress_completed', v_total_terminal,
      'progress_total', v_total_terminal,
      'parent_status', v_request_result,
      'totals', v_final_result,
      'complete', false,
      'requires_user_action', v_request_result IN (
        'APPLIED_WITH_BLOCKERS', 'BLOCKED', 'FAILED'
      ),
      'processing_continues', true,
      'changed_scope_json', pg_catalog.jsonb_build_object(
        'pay_batch_id', v_request.pay_batch_id,
        'active_candidate_count', v_active_candidate_count,
        'active_item_count', v_active_item_count,
        'active_net_bank_amount', v_active_net_bank_amount,
        'active_frozen_source_item_amount', v_active_source_item_amount,
        'active_paye_schedule_amount', v_active_paye_schedule_amount,
        'active_transfer_amount', v_active_transfer_amount
      ),
      'live_signal_updates', pg_catalog.jsonb_build_object(
        'overview_updated', true,
        'payment_status_updated', true,
        'paye_schedule_updated',
          pg_catalog.upper(COALESCE(v_batch.batch_kind_fixed, '')) = 'PAYE'
      ),
      'continuation', pg_catalog.jsonb_build_object(
        'required', true, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', 'REFRESH_WORKBENCH', 'run_after_utc', v_now,
        'reason', 'PAYMENT_CORRECTION_FINANCIAL_FINALISED', 'successor_relation', 'SELF',
        'requires_user_action', false, 'terminal', false
      ),
      'code', 'PAYMENT_CORRECTION_FINALISED'
    );
  END IF;

  IF v_phase = 'REFRESH_WORKBENCH' THEN
    v_refresh_cursor := COALESCE(
      NULLIF(v_operation.progress_json->>'last_refreshed_selection_ordinal', '')::bigint, 0
    );

    WITH refresh_page AS (
      SELECT member_row.selection_ordinal, work_row.candidate_id, work_row.id AS work_item_id
      FROM public.pay_payment_correction_request_candidates AS member_row
      JOIN public.pay_payment_correction_work_items AS work_row
        ON work_row.correction_request_id = member_row.correction_request_id
       AND work_row.pay_batch_candidate_id = member_row.pay_batch_candidate_id
      WHERE member_row.correction_request_id = p_correction_request_id
        AND member_row.selection_ordinal > v_refresh_cursor
        AND work_row.status = 'APPLIED'
      ORDER BY member_row.selection_ordinal
      LIMIT 100
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate_id ORDER BY selection_ordinal), '[]'::jsonb),
           COALESCE(pg_catalog.array_agg(work_item_id ORDER BY selection_ordinal),ARRAY[]::uuid[]),
           pg_catalog.count(*)::integer,
           COALESCE(pg_catalog.max(selection_ordinal), v_refresh_cursor)
    INTO v_refresh_candidate_ids, v_refresh_work_item_ids, v_refresh_count, v_refresh_next
    FROM refresh_page;

    SELECT COALESCE(
             pg_catalog.jsonb_agg(item_scope.pay_batch_item_id::text ORDER BY item_scope.pay_batch_item_id),
             '[]'::jsonb
           )
    INTO v_refresh_pay_batch_item_ids
    FROM (
      SELECT DISTINCT correction_item.pay_batch_item_id
      FROM public.pay_payment_correction_items AS correction_item
      WHERE correction_item.correction_request_id = p_correction_request_id
        AND correction_item.status = 'APPLIED'
        AND correction_item.pay_batch_item_id IS NOT NULL
        AND correction_item.candidate_id IN (
          SELECT candidate_value.value::uuid
          FROM pg_catalog.jsonb_array_elements_text(v_refresh_candidate_ids) AS candidate_value(value)
        )
    ) AS item_scope;

    v_refresh_has_more := EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_request_candidates AS member_row
      JOIN public.pay_payment_correction_work_items AS work_row
        ON work_row.correction_request_id = member_row.correction_request_id
       AND work_row.pay_batch_candidate_id = member_row.pay_batch_candidate_id
      WHERE member_row.correction_request_id = p_correction_request_id
        AND member_row.selection_ordinal > v_refresh_next
        AND work_row.status = 'APPLIED'
    );
    v_refresh_sequence := (v_refresh_cursor / 100)::integer + 1;
    v_session_id := v_batch.source_workbench_session_id;
    IF v_session_id IS NOT NULL THEN
      SELECT session_row.actor_user_id,session_row.version
      INTO v_refresh_actor_user_id,v_session_version
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = v_session_id
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL;
    END IF;

    IF v_refresh_count>0 AND v_session_id IS NOT NULL
       AND v_requested_action IN ('DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT') THEN
      v_post_commit_authorities_v3:=private.pay_workbench_correction_post_commit_authority_page_v1(
        p_correction_request_id,v_operation.id,v_session_id,v_refresh_work_item_ids,
        pg_catalog.jsonb_build_object('owner','pay_payment_correction_process_chunk')
      );
      IF COALESCE((v_post_commit_authorities_v3->>'ok')::boolean,false) IS NOT TRUE
         OR COALESCE((v_post_commit_authorities_v3->>'all_finalized')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_POST_COMMIT_AUTHORITY_NOT_FINALIZED'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
           'code','REFRESH_RETRY','reason','POST_COMMIT_SCOPE_GENERATION_NOT_FINALIZED'
          )::text;
      END IF;

      -- Route election must consume authority that was committed by an earlier
      -- invocation.  The helper above re-reads the finalized scope under the
      -- candidate/held-job locks, but a PostgreSQL function cannot commit an
      -- internal transaction.  Persist a stable, timestamp-free route-input
      -- digest and return one bounded continuation before any publication or
      -- fallback owner can be elected.  The next invocation must reproduce the
      -- same digest before it may continue.
      SELECT COALESCE(
        pg_catalog.jsonb_object_agg(
          authority_entry.key,
          authority_entry.value-'captured_at_utc'
          ORDER BY authority_entry.key
        ),
        '{}'::jsonb
      )
      INTO v_route_authorities_v3
      FROM pg_catalog.jsonb_each(
        COALESCE(v_post_commit_authorities_v3->'candidate_authorities','{}'::jsonb)
      ) AS authority_entry(key,value);

      SELECT COALESCE(
        pg_catalog.jsonb_agg(candidate_value.value ORDER BY candidate_value.value),
        '[]'::jsonb
      )
      INTO v_route_candidate_ids
      FROM pg_catalog.jsonb_array_elements_text(v_refresh_candidate_ids)
        AS candidate_value(value);

      SELECT COALESCE(
        pg_catalog.jsonb_agg(requested_work_item.work_item_id::text
          ORDER BY requested_work_item.work_item_id),
        '[]'::jsonb
      )
      INTO v_route_work_item_ids
      FROM pg_catalog.unnest(v_refresh_work_item_ids)
        AS requested_work_item(work_item_id);

      -- A scheduled/executed-not-submitted cancellation may carry one exact
      -- Q-bound authority captured after PREPARE had durably selected the
      -- batch items but before REQUEST_START dirtied the financial lifecycle.
      -- Re-read the same frozen request-candidate rows through the one parent
      -- proof owner.  Missing, incomplete or changed evidence is not inferred
      -- from current Workbench state: it remains a normal safe-fallback case.
      v_q_bound_authority_set:=COALESCE(
        v_operation.input_json->'cancellation_reversion_q_bound_pre_request_start_v1',
        '{}'::jsonb
      );
      v_q_bound_candidate_authorities:=COALESCE(
        v_q_bound_authority_set->'candidate_authorities','{}'::jsonb
      );
      SELECT COALESCE(pg_catalog.array_agg(candidate_value.value::uuid
               ORDER BY candidate_value.value),ARRAY[]::uuid[])
      INTO v_q_bound_route_candidate_ids
      FROM pg_catalog.jsonb_array_elements_text(v_route_candidate_ids)
        AS candidate_value(value)
      WHERE pg_catalog.pg_input_is_valid(candidate_value.value,'uuid');

      v_q_bound_authority_set_digest_recomputed:=
        private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
          'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_SET_V1',
          'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
          'correction_request_id',p_correction_request_id,
          'correction_operation_id',v_operation.id,
          'execution_operation_id',CASE
            WHEN COALESCE(v_q_bound_authority_set->>'execution_operation_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (v_q_bound_authority_set->>'execution_operation_id')::uuid END,
          'pay_batch_id',v_request.pay_batch_id,
          'request_selection_hash',v_request.selection_hash,
          'request_plan_hash',v_request.plan_hash,
          'candidate_authorities',v_q_bound_candidate_authorities
        ));

      IF v_requested_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
         AND COALESCE(v_q_bound_authority_set->>'contract_version','')
               ='CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_SET_V1'
         AND COALESCE(v_q_bound_authority_set->>'boundary','')
               ='AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START'
         AND COALESCE(v_q_bound_authority_set->>'correction_request_id','')
               =p_correction_request_id::text
         AND COALESCE(v_q_bound_authority_set->>'correction_operation_id','')
               =v_operation.id::text
         AND COALESCE(v_q_bound_authority_set->>'pay_batch_id','')
               =v_request.pay_batch_id::text
         AND COALESCE(v_q_bound_authority_set->>'workbench_session_id','')
               =v_session_id::text
         AND COALESCE(v_q_bound_authority_set->>'workbench_session_version','')
               =v_session_version::text
         AND COALESCE(v_q_bound_authority_set->>'request_selection_hash','')
               =v_request.selection_hash
         AND COALESCE(v_q_bound_authority_set->>'request_plan_hash','')
               =v_request.plan_hash
         AND COALESCE(v_q_bound_authority_set->>'execution_operation_id','')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND COALESCE(v_q_bound_authority_set->>'execution_operation_resolution','')='EXACT'
         AND COALESCE(v_q_bound_authority_set->>'authority_set_digest','')
               =v_q_bound_authority_set_digest_recomputed
         AND pg_catalog.cardinality(v_q_bound_route_candidate_ids)=v_refresh_count
         AND NOT EXISTS (
           SELECT 1
           FROM pg_catalog.unnest(v_q_bound_route_candidate_ids) AS route_candidate(candidate_id)
           WHERE COALESCE(v_q_bound_candidate_authorities
             ->route_candidate.candidate_id::text->>'contract_version','')
               <>'CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_AUTHORITY_V1'
         ) THEN
        v_q_bound_execution_operation_id:=
          (v_q_bound_authority_set->>'execution_operation_id')::uuid;

        -- Admission is candidate-local.  A rejected authority remains bound
        -- into the full request authority-set digest, but cannot prevent a
        -- different, exact candidate from replaying its own proof.  Only
        -- candidates carrying the complete persisted digest chain are sent
        -- to the replay owner; every other candidate remains on the existing
        -- fail-closed fallback path.
        SELECT COALESCE(pg_catalog.array_agg(route_candidate.candidate_id
                 ORDER BY route_candidate.candidate_id),ARRAY[]::uuid[])
        INTO v_q_bound_route_eligible_candidate_ids
        FROM pg_catalog.unnest(v_q_bound_route_candidate_ids)
          AS route_candidate(candidate_id)
        WHERE COALESCE((v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'admitted')::boolean,false)
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'v2_chain_digest','')~'^[0-9a-f]{32}$'
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'authority_digest','')~'^[0-9a-f]{64}$'
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'selected_anchor_digest','')~'^[0-9a-f]{64}$'
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'affected_physical_closure_digest','')
                ~'^[0-9a-f]{64}$'
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'residual_proof_digest','')~'^[0-9a-f]{64}$'
          AND COALESCE(v_q_bound_candidate_authorities
                ->route_candidate.candidate_id::text->>'parent_proof_digest','')~'^[0-9a-f]{64}$';
        v_q_bound_route_eligible_candidate_count:=
          COALESCE(pg_catalog.cardinality(v_q_bound_route_eligible_candidate_ids),0);

        SELECT COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'v2_chain_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb),
               COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'selected_anchor_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb),
               COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'affected_physical_closure_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb),
               COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'residual_proof_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb),
               COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'parent_proof_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb),
               COALESCE(pg_catalog.jsonb_object_agg(
                 route_candidate.candidate_id::text,
                 v_q_bound_candidate_authorities->route_candidate.candidate_id::text->>'authority_digest'
                 ORDER BY route_candidate.candidate_id),'{}'::jsonb)
        INTO v_q_bound_chain_digest_by_candidate,
             v_q_bound_selected_anchor_digest_by_candidate,
             v_q_bound_affected_closure_digest_by_candidate,
             v_q_bound_residual_proof_digest_by_candidate,
             v_q_bound_parent_proof_digest_by_candidate,
             v_q_bound_pre_request_authority_digest_by_candidate
        FROM pg_catalog.unnest(v_q_bound_route_eligible_candidate_ids)
          AS route_candidate(candidate_id);

        IF v_q_bound_route_eligible_candidate_count>0 THEN
          v_q_bound_route_replay:=private.pay_workbench_execution_refresh_owner_proof_page_v1(
            v_q_bound_execution_operation_id,v_request.pay_batch_id,
            v_q_bound_route_eligible_candidate_ids,'ROUTE_REPLAY',
            pg_catalog.jsonb_build_object(
              'contract_version','2',
              'expected_chain_digest_by_candidate',v_q_bound_chain_digest_by_candidate,
              'expected_owner_by_candidate','{}'::jsonb,
              'expected_parent_proof_digest_by_candidate',v_q_bound_parent_proof_digest_by_candidate,
              'residual_selection_binding',pg_catalog.jsonb_build_object(
                'contract_version','EXECUTION_RESIDUAL_SELECTION_BINDING_V1',
                'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
                'correction_request_id',p_correction_request_id,
                'correction_operation_id',v_operation.id,
                'workbench_session_id',v_session_id,
                'workbench_session_version',v_session_version,
                'request_selection_hash',v_request.selection_hash,
                'request_plan_hash',v_request.plan_hash,
                'expected_selected_anchor_digest_by_candidate',
                  v_q_bound_selected_anchor_digest_by_candidate
              )
            )
          );
          v_q_bound_route_replay_complete:=
            COALESCE((v_q_bound_route_replay->>'ok')::boolean,false)
            AND COALESCE((v_q_bound_route_replay->>'candidate_count')::integer,0)
                  =v_q_bound_route_eligible_candidate_count
            AND pg_catalog.jsonb_array_length(
                  COALESCE(v_q_bound_route_replay->'candidate_results','[]'::jsonb)
                )=v_q_bound_route_eligible_candidate_count;
          v_q_bound_route_replay_exact:=v_q_bound_route_replay_complete
            AND COALESCE((v_q_bound_route_replay->>'admitted_count')::integer,0)
                  =v_q_bound_route_eligible_candidate_count;
        END IF;
      END IF;

      v_route_input:=pg_catalog.jsonb_build_object(
        'contract_version','CANCELLATION_ROUTE_INPUT_V1',
        'correction_request_id',p_correction_request_id,
        'operation_id',v_operation.id,
        'pay_batch_id',v_request.pay_batch_id,
        'requested_action',v_requested_action,
        'session_id',v_session_id,
        'session_version',v_session_version,
        'refresh_sequence_no',v_refresh_sequence,
        'candidate_ids',v_route_candidate_ids,
        'work_item_ids',v_route_work_item_ids,
        'post_commit_authorities_v3',v_route_authorities_v3,
        'route_observe_enabled',v_route_reversion_observe_enabled,
        'route_publish_enabled',v_route_reversion_publish_enabled,
        'held_dirty_absorption_enabled',v_held_dirty_absorption_enabled,
        'physical_currentness_contract_version','PAY_WORKBENCH_CANDIDATE_PHYSICAL_CURRENTNESS_V1',
        'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2'
      )||CASE WHEN v_requested_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT') THEN
        pg_catalog.jsonb_build_object(
          'authority_components_version',2,
          'request_selection_hash',v_request.selection_hash,
          'request_plan_hash',v_request.plan_hash,
          'pre_request_authority_digest_by_candidate',
            v_q_bound_pre_request_authority_digest_by_candidate,
          'pre_request_authority_set_digest',
            v_q_bound_authority_set->>'authority_set_digest',
          'selected_anchor_digest_by_candidate',
            v_q_bound_selected_anchor_digest_by_candidate,
          'affected_physical_closure_digest_by_candidate',
            v_q_bound_affected_closure_digest_by_candidate,
          'residual_proof_digest_by_candidate',
            v_q_bound_residual_proof_digest_by_candidate,
          'parent_proof_digest_by_candidate',
            v_q_bound_parent_proof_digest_by_candidate
        ) ELSE '{}'::jsonb END;
      v_route_input_digest:=private.pay_payment_correction_sha256_v1(v_route_input);
      v_route_input:=v_route_input||pg_catalog.jsonb_build_object(
        'route_input_digest',v_route_input_digest,
        'captured_at_utc',pg_catalog.clock_timestamp()
      );
      v_committed_route_input:=COALESCE(
        v_operation.input_json->'cancellation_route_inputs_v1'->v_refresh_sequence::text,
        '{}'::jsonb
      );
      v_committed_route_input_digest:=NULLIF(
        v_committed_route_input->>'route_input_digest',''
      );
    END IF;

    SELECT existing_refresh.result_json
    INTO v_existing_refresh_result
    FROM public.banking_pay_operation_chunks AS existing_refresh
    WHERE existing_refresh.operation_id = v_operation.id
      AND existing_refresh.phase = 'REFRESH_WORKBENCH'
      AND existing_refresh.chunk_type = 'CANDIDATE_SCOPE'
      AND existing_refresh.sequence_no = v_refresh_sequence
      AND existing_refresh.status = 'COMPLETE';
    v_existing_refresh_found:=FOUND;

    IF v_existing_refresh_found THEN
      IF v_refresh_count>0 AND v_session_id IS NOT NULL
         AND v_requested_action IN ('DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT')
         AND (
           NULLIF(v_existing_refresh_result->>'route_input_digest','') IS NULL
           OR NULLIF(v_existing_refresh_result->>'route_input_digest','')
                IS DISTINCT FROM v_route_input_digest
         ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_ROUTE_RESULT_AUTHORITY_MISMATCH'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAYMENT_CORRECTION_ROUTE_RESULT_AUTHORITY_MISMATCH',
            'refresh_sequence_no',v_refresh_sequence,
            'existing_route_input_digest',v_existing_refresh_result->>'route_input_digest',
            'current_route_input_digest',v_route_input_digest,
            'safe_historical_result_preserved',true
          )::text;
      END IF;
      v_refresh_result:=v_existing_refresh_result;
    ELSIF v_refresh_count>0 AND v_session_id IS NOT NULL
       AND v_requested_action IN ('DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT')
       AND v_committed_route_input_digest IS DISTINCT FROM v_route_input_digest THEN
      UPDATE public.banking_pay_operations AS authority_capture_operation
      SET input_json=pg_catalog.jsonb_set(
            COALESCE(authority_capture_operation.input_json,'{}'::jsonb),
            '{cancellation_route_inputs_v1}',
            COALESCE(
              authority_capture_operation.input_json->'cancellation_route_inputs_v1',
              '{}'::jsonb
            )||pg_catalog.jsonb_build_object(v_refresh_sequence::text,v_route_input),
            true
          ),
          progress_json=COALESCE(authority_capture_operation.progress_json,'{}'::jsonb)
            ||pg_catalog.jsonb_build_object(
              'post_commit_authority_capture_complete',true,
              'post_commit_authority_capture_sequence_no',v_refresh_sequence,
              'post_commit_authority_capture_digest',v_route_input_digest,
              'post_commit_authority_capture_completed_at_utc',pg_catalog.clock_timestamp()
            ),
          phase='REFRESH_WORKBENCH',status='RUNNING',runner_state='RUNNABLE',
          run_after_utc=pg_catalog.clock_timestamp(),updated_at_utc=pg_catalog.clock_timestamp()
      WHERE authority_capture_operation.id=v_operation.id
      RETURNING authority_capture_operation.* INTO v_operation;

      RETURN pg_catalog.jsonb_build_object(
        'ok',true,
        'phase','REFRESH_WORKBENCH',
        'financial_complete',true,
        'post_commit_authority_capture_complete',true,
        'route_election_pending',true,
        'route_input_contract_version','CANCELLATION_ROUTE_INPUT_V1',
        'route_input_digest',v_route_input_digest,
        'candidate_count',v_refresh_count,
        'complete',false,
        'processing_continues',true,
        'continuation',pg_catalog.jsonb_build_object(
          'required',true,'operation_id',v_operation.id,
          'operation_type','PAYMENT_CORRECTION','pay_batch_id',v_request.pay_batch_id,
          'root_operation_id',v_operation.root_operation_id,
          'phase','REFRESH_WORKBENCH','run_after_utc',pg_catalog.clock_timestamp(),
          'reason','PAYMENT_CORRECTION_POST_COMMIT_AUTHORITY_CAPTURED',
          'successor_relation','SELF','requires_user_action',false,'terminal',false
        ),
        'code','PAYMENT_CORRECTION_POST_COMMIT_AUTHORITY_CAPTURED'
      );
    ELSIF v_refresh_count = 0 THEN
      v_refresh_result := pg_catalog.jsonb_build_object('status', 'NOT_REQUIRED', 'candidate_count', 0);
    ELSIF v_session_id IS NULL THEN
      v_refresh_result := pg_catalog.jsonb_build_object(
        'status', 'NOT_REQUIRED_NO_SOURCE_SESSION',
        'candidate_count', v_refresh_count,
        'scope_signal_recorded', true
      );
    ELSIF v_refresh_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'REFRESH_RETRY',
          'session_id', v_session_id
        )::text;
    ELSIF v_requested_action IN ('DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT')
       AND COALESCE(v_route_reversion_observe_enabled,false) THEN
      v_standard_reversion_admission := private.pay_workbench_cancel_reversion_admission_page_v1(
        p_correction_request_id,
        v_operation.id,
        v_session_id,
        v_refresh_work_item_ids,
        pg_catalog.jsonb_build_object('mode',CASE
          WHEN v_route_reversion_publish_enabled THEN 'POST_FINANCIAL' ELSE 'OBSERVE_ONLY' END)
      );

      -- The existing admission engine remains authoritative.  The exact
      -- residual replay may replace only its known terminal-authority result:
      -- that result is expected when the legacy whole-publication comparison
      -- cannot express F - A = C = P.  Every other rejection remains closed.
      WITH standard_rows AS (
        SELECT standard.value AS result_json
        FROM pg_catalog.jsonb_array_elements(COALESCE(
          v_standard_reversion_admission->'candidate_results','[]'::jsonb
        )) AS standard(value)
      ), replay_rows AS (
        SELECT replay.value AS result_json
        FROM pg_catalog.jsonb_array_elements(COALESCE(
          v_q_bound_route_replay->'candidate_results','[]'::jsonb
        )) AS replay(value)
      ), composed AS (
        SELECT pg_catalog.jsonb_strip_nulls(
          standard_rows.result_json
          ||pg_catalog.jsonb_build_object(
            'admitted',
              COALESCE((standard_rows.result_json->>'admitted')::boolean,false)
              OR (
                v_q_bound_route_replay_complete
                AND COALESCE((replay_rows.result_json->>'admitted')::boolean,false)
                AND standard_rows.result_json->>'rejection_reason'
                      ='POST_FINANCIAL_TERMINAL_AUTHORITY_CHANGED'
              ),
            'fast_reversion_eligible',
              COALESCE((standard_rows.result_json->>'admitted')::boolean,false)
              OR (
                v_q_bound_route_replay_complete
                AND COALESCE((replay_rows.result_json->>'admitted')::boolean,false)
                AND standard_rows.result_json->>'rejection_reason'
                      ='POST_FINANCIAL_TERMINAL_AUTHORITY_CHANGED'
              ),
            'rejection_reason',CASE
              WHEN COALESCE((standard_rows.result_json->>'admitted')::boolean,false)
                OR (
                  v_q_bound_route_replay_complete
                  AND COALESCE((replay_rows.result_json->>'admitted')::boolean,false)
                  AND standard_rows.result_json->>'rejection_reason'
                        ='POST_FINANCIAL_TERMINAL_AUTHORITY_CHANGED'
                ) THEN NULL
              ELSE standard_rows.result_json->>'rejection_reason' END,
            'admission_authority',CASE
              WHEN COALESCE((standard_rows.result_json->>'admitted')::boolean,false)
                THEN 'STANDARD_CANCELLATION_REVERSION_ADMISSION_V1'
              WHEN v_q_bound_route_replay_complete
                AND COALESCE((replay_rows.result_json->>'admitted')::boolean,false)
                AND standard_rows.result_json->>'rejection_reason'
                      ='POST_FINANCIAL_TERMINAL_AUTHORITY_CHANGED'
                THEN 'Q_BOUND_RESIDUAL_ROUTE_REPLAY_V1'
              ELSE 'REJECTED' END,
            'q_bound_residual_route_replay',replay_rows.result_json
          )
        ) AS result_json
        FROM standard_rows
        LEFT JOIN replay_rows
          ON replay_rows.result_json->>'candidate_id'
             =standard_rows.result_json->>'candidate_id'
      )
      SELECT COALESCE(pg_catalog.jsonb_agg(composed.result_json
               ORDER BY composed.result_json->>'candidate_id'),'[]'::jsonb)
      INTO v_reversion_candidate_ids
      FROM composed;

      v_reversion_admission:=v_standard_reversion_admission
        ||pg_catalog.jsonb_build_object(
          'candidate_results',v_reversion_candidate_ids,
          'admitted_count',(SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_array_elements(v_reversion_candidate_ids) AS admitted(value)
            WHERE COALESCE((admitted.value->>'admitted')::boolean,false)),
          'q_bound_residual_route_replay',v_q_bound_route_replay,
          'q_bound_residual_route_replay_complete',v_q_bound_route_replay_complete,
          'q_bound_residual_route_replay_exact',v_q_bound_route_replay_exact
        );

      SELECT
        COALESCE(pg_catalog.jsonb_agg(result_row.value->>'candidate_id'
          ORDER BY result_row.value->>'candidate_id') FILTER (
            WHERE COALESCE((result_row.value->>'admitted')::boolean,false)
          ),'[]'::jsonb),
        COALESCE(pg_catalog.jsonb_agg(result_row.value->>'candidate_id'
          ORDER BY result_row.value->>'candidate_id') FILTER (
            WHERE COALESCE((result_row.value->>'admitted')::boolean,false) IS NOT TRUE
          ),'[]'::jsonb),
        pg_catalog.count(*) FILTER (
          WHERE COALESCE((result_row.value->>'admitted')::boolean,false)
        )::integer
      INTO v_reversion_candidate_ids,v_reversion_rejected_candidate_ids,v_reversion_admitted_count
      FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_reversion_admission->'candidate_results','[]'::jsonb)
      ) AS result_row(value);

      IF COALESCE(v_route_reversion_publish_enabled,false)
         AND v_reversion_admitted_count > 0 THEN
        WITH admitted AS (
          SELECT result_row.value,
                 pg_catalog.md5(
                   p_correction_request_id::text||':'||
                   (result_row.value->>'candidate_id')||':'||
                   (result_row.value->>'work_item_id')||':'||
                   (result_row.value->>'current_source_change_seq')||':'||
                   'CERTIFIED_CANCELLATION_REVERSION_V1'
                 ) AS run_hash
          FROM pg_catalog.jsonb_array_elements(
            COALESCE(v_reversion_admission->'candidate_results','[]'::jsonb)
          ) AS result_row(value)
          WHERE COALESCE((result_row.value->>'admitted')::boolean,false)
        ), descriptors AS (
          SELECT pg_catalog.jsonb_build_object(
            'candidate_id',admitted.value->>'candidate_id',
            'economic_build_id',admitted.value->>'original_economic_build_id',
            'source_build_run_id',pg_catalog.substr(admitted.run_hash,1,8)||'-'||
              pg_catalog.substr(admitted.run_hash,9,4)||'-'||
              pg_catalog.substr(admitted.run_hash,13,4)||'-'||
              pg_catalog.substr(admitted.run_hash,17,4)||'-'||
              pg_catalog.substr(admitted.run_hash,21,12),
            'source_change_seq',admitted.value->>'current_source_change_seq',
            'source_identity_digest',admitted.value->>'source_identity_digest',
            'session_version',admitted.value->>'session_version',
            'completion_job_id',admitted.value->>'work_item_id',
            'refresh_scope_kind','CANDIDATE_FULL_LIVE',
            'publication_options_json',pg_catalog.jsonb_build_object(
              'contract_version',3,
              'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2',
              'authority_kind','CERTIFIED_CANCELLATION_REVERSION',
              'invocation_kind','CANCELLATION_REVERSION_FINALISE',
              'final_state',CASE WHEN COALESCE((admitted.value->>'source_count')::integer,0)=0
                THEN 'SOURCE_EMPTY' ELSE 'READY' END,
              'source_session_id',v_session_id,
              'original_economic_build_id',admitted.value->>'original_economic_build_id',
              'original_source_build_run_id',admitted.value->>'original_source_build_run_id',
              'replay_source_build_run_id',admitted.value->>'replay_source_build_run_id',
              'original_source_publication_id',admitted.value->>'original_source_publication_id',
              'cancellation_request_id',p_correction_request_id,
              'cancellation_operation_id',v_operation.id,
              'cancellation_work_item_id',admitted.value->>'work_item_id',
              'pay_batch_id',v_request.pay_batch_id,
              'cancellation_reversion_run_id',pg_catalog.substr(admitted.run_hash,1,8)||'-'||
                pg_catalog.substr(admitted.run_hash,9,4)||'-'||
                pg_catalog.substr(admitted.run_hash,13,4)||'-'||
                pg_catalog.substr(admitted.run_hash,17,4)||'-'||
                pg_catalog.substr(admitted.run_hash,21,12),
              'financial_reversion_digest',admitted.value->>'financial_reversion_digest',
              'original_semantic_proof_digest',admitted.value->>'semantic_proof_digest',
              'source_count',admitted.value->>'source_count'
            )
          ) AS descriptor
          FROM admitted
        )
        SELECT COALESCE(pg_catalog.jsonb_agg(descriptors.descriptor
          ORDER BY descriptors.descriptor->>'candidate_id'),'[]'::jsonb)
        INTO v_reversion_descriptors
        FROM descriptors;

        v_reversion_publication := private.pay_workbench_publish_certified_source_preview_page_v1(
          v_session_id,v_reversion_descriptors,'{}'::jsonb
        );
      END IF;

      IF COALESCE(v_route_reversion_publish_enabled,false)
         AND pg_catalog.jsonb_array_length(COALESCE(v_reversion_rejected_candidate_ids,'[]'::jsonb))=0 THEN
        v_refresh_result := pg_catalog.jsonb_build_object(
          'ok',true,
          'status','CERTIFIED_CANCELLATION_REVERSION_COMPLETE',
          'candidate_count',v_refresh_count,
          'admission',v_reversion_admission,
          'publication',v_reversion_publication,
          'certified_cancellation_reversion_count',v_reversion_admitted_count,
          'full_candidate_refresh_enqueued_count',0,
          'job_ids','[]'::jsonb
        );
      ELSE
        v_refresh_result := public.pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1(
          v_session_id,v_request.pay_batch_id,'DRAFT_CANCEL',v_refresh_actor_user_id,
          pg_catalog.jsonb_build_object(
            'correction_request_id',p_correction_request_id,
            'correction_action',v_requested_action,
            'candidate_ids',CASE
              WHEN v_route_reversion_publish_enabled THEN v_reversion_rejected_candidate_ids
              ELSE v_refresh_candidate_ids END,
            'changed_pay_batch_item_ids',v_refresh_pay_batch_item_ids,
            'maximum_candidate_count',100,
            'defer_complex_enqueue',true,
            'post_commit_authorities_v3',v_post_commit_authorities_v3->'candidate_authorities'
          )
        ) || pg_catalog.jsonb_build_object(
          'cancellation_reversion_observe',v_reversion_admission,
          'cancellation_reversion_publication',v_reversion_publication,
          'certified_cancellation_reversion_count',CASE
            WHEN v_route_reversion_publish_enabled THEN v_reversion_admitted_count ELSE 0 END
        );
      END IF;
      IF COALESCE((v_refresh_result->>'ok')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_REVERSION_RETRY'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','REFRESH_RETRY','reason','CANCELLATION_REVERSION_OR_FALLBACK_FAILED',
            'session_id',v_session_id,'candidate_count',v_refresh_count
          )::text;
      END IF;
    ELSIF v_requested_action IN ('DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT','NO_MONEY_UNWIND') THEN
      -- This helper's DRAFT_CANCEL operation type names the Workbench overlay
      -- reversal (not the economic cancellation mode).  Every successfully
      -- cancelled batch must retire the same active-batch reservation overlay
      -- before the bounded live-truth refresh is queued, whether the frozen
      -- correction action was draft, pre-bank, or terminal-no-money release.
      v_refresh_result := public.pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1(
        v_session_id, v_request.pay_batch_id, 'DRAFT_CANCEL', v_refresh_actor_user_id,
        pg_catalog.jsonb_build_object(
          'correction_request_id', p_correction_request_id,
          'correction_action', v_requested_action,
          'candidate_ids', v_refresh_candidate_ids,
          'changed_pay_batch_item_ids', v_refresh_pay_batch_item_ids,
          'maximum_candidate_count', 100
        )
      );
      IF COALESCE((v_refresh_result->>'ok')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_OVERLAY_RESTORE_RETRY'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'REFRESH_RETRY',
            'reason', COALESCE(v_refresh_result->>'fallback_reason', 'WORKBENCH_OVERLAY_RESTORE_FAILED'),
            'session_id', v_session_id,
            'candidate_count', v_refresh_count
          )::text;
      END IF;
    ELSE
      v_refresh_result := public.pay_workbench_enqueue_candidate_refresh_many(
        v_session_id, v_refresh_candidate_ids, 'PAYMENT_CORRECTION_FINALISED', v_refresh_actor_user_id
      );
    END IF;

    IF v_route_input_digest IS NOT NULL THEN
      v_refresh_result:=COALESCE(v_refresh_result,'{}'::jsonb)
        ||pg_catalog.jsonb_build_object(
          'route_input_contract_version','CANCELLATION_ROUTE_INPUT_V1',
          'route_input_digest',v_route_input_digest,
          'post_commit_authority_set_digest',
            private.pay_payment_correction_sha256_v1(v_route_authorities_v3)
        );
    END IF;

    -- Normalize one database-owned, page-scoped Workbench wake contract.  The
    -- envelope is scheduling evidence only: it never changes the cancellation
    -- result and it never asks the Worker to infer financial scope.
    v_refresh_result := COALESCE(v_refresh_result, '{}'::jsonb) - 'workbench_refresh_nudge';

    SELECT COALESCE(pg_catalog.jsonb_agg(candidate_scope.candidate_id::text ORDER BY candidate_scope.candidate_id), '[]'::jsonb),
           pg_catalog.count(*)::integer
    INTO v_workbench_nudge_candidate_ids, v_workbench_nudge_candidate_count
    FROM (
      SELECT DISTINCT candidate_value.value::uuid AS candidate_id
      FROM pg_catalog.jsonb_array_elements_text(COALESCE(v_refresh_candidate_ids, '[]'::jsonb)) AS candidate_value(value)
      WHERE pg_catalog.pg_input_is_valid(candidate_value.value, 'uuid')
    ) AS candidate_scope;

    WITH page_candidates AS (
      SELECT candidate_value.value::uuid AS candidate_id
      FROM pg_catalog.jsonb_array_elements_text(v_workbench_nudge_candidate_ids) AS candidate_value(value)
    ),
    raw_job_ids AS (
      SELECT job_value.value AS job_id_text
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'job_ids') = 'array'
          THEN v_refresh_result->'job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'full_candidate_refresh_job_ids') = 'array'
          THEN v_refresh_result->'full_candidate_refresh_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'session_recompute_job_ids') = 'array'
          THEN v_refresh_result->'session_recompute_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'workbench_refresh_job_ids') = 'array'
          THEN v_refresh_result->'workbench_refresh_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT scope_row.pending_job_id::text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      JOIN page_candidates AS page_candidate ON page_candidate.candidate_id = scope_row.candidate_id
      WHERE scope_row.session_id = v_session_id
        AND scope_row.pending_job_id IS NOT NULL
    ),
    canonical_job_ids AS (
      SELECT DISTINCT raw_job.job_id_text::uuid AS job_id
      FROM raw_job_ids AS raw_job
      WHERE pg_catalog.pg_input_is_valid(raw_job.job_id_text, 'uuid')
    ),
    active_jobs AS (
      SELECT job_row.id
      FROM canonical_job_ids AS canonical_job
      JOIN public.banking_pay_workbench_jobs AS job_row ON job_row.id = canonical_job.job_id
      JOIN page_candidates AS page_candidate ON page_candidate.candidate_id = job_row.candidate_id
      JOIN public.banking_pay_workbench_session_scope AS scope_row
        ON scope_row.session_id = job_row.session_id
       AND scope_row.candidate_id = job_row.candidate_id
       AND scope_row.pending_job_id = job_row.id
      WHERE job_row.session_id = v_session_id
        AND job_row.status IN ('QUEUED', 'RUNNING')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(job_row.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        )
      ORDER BY job_row.id
      LIMIT 100
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(active_job.id::text ORDER BY active_job.id), '[]'::jsonb),
           pg_catalog.count(*)::integer
    INTO v_workbench_nudge_job_ids, v_workbench_nudge_job_count
    FROM active_jobs AS active_job;

    IF v_session_id IS NOT NULL AND v_workbench_nudge_candidate_count>0 THEN
      EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
        INTO v_physical_currentness
        USING v_session_id,ARRAY(
          SELECT candidate_value.value::uuid
          FROM pg_catalog.jsonb_array_elements_text(v_workbench_nudge_candidate_ids)
            AS candidate_value(value)
          ORDER BY candidate_value.value::uuid
        ),'TERMINAL_CURRENT',
          pg_catalog.jsonb_build_object('contract_version',1,'allow_active_owner',true);

      IF COALESCE((v_physical_currentness->>'all_current_or_active_owner')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_ROUTE_NOT_PHYSICALLY_CURRENT'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','REFRESH_RETRY','reason','NO_CURRENT_OR_ACTIVE_OWNER_AFTER_PATCH',
            'session_id',v_session_id,'candidate_count',v_workbench_nudge_candidate_count
          )::text;
      END IF;
    END IF;

    v_workbench_nudge_refresh_status := CASE
      WHEN v_refresh_count = 0 THEN 'NOT_REQUIRED'
      WHEN v_session_id IS NULL THEN 'NOT_REQUIRED_NO_SOURCE_SESSION'
      WHEN COALESCE((v_physical_currentness->>'all_terminal_current')::boolean,false) THEN 'CURRENT'
      WHEN v_workbench_nudge_job_count > 0 THEN 'STAGED'
      ELSE 'CURRENT'
    END;

    v_refresh_result:=COALESCE(v_refresh_result,'{}'::jsonb)||pg_catalog.jsonb_build_object(
      'physical_currentness_checked',v_session_id IS NOT NULL AND v_workbench_nudge_candidate_count>0,
      'physical_currentness_proven',COALESCE((v_physical_currentness->>'all_terminal_current')::boolean,false),
      'physical_currentness',v_physical_currentness
    );

    v_workbench_refresh_nudge := pg_catalog.jsonb_build_object(
      'contract_version', 'PAYMENT_CORRECTION_WORKBENCH_NUDGE_V1',
      'nudge_required', v_workbench_nudge_refresh_status = 'STAGED'
        AND v_session_id IS NOT NULL
        AND v_refresh_actor_user_id IS NOT NULL
        AND v_workbench_nudge_candidate_count > 0
        AND v_workbench_nudge_job_count > 0,
      'refresh_status', v_workbench_nudge_refresh_status,
      'reason', CASE
        WHEN v_workbench_nudge_refresh_status = 'STAGED' THEN 'PAYMENT_CORRECTION_WORKBENCH_JOBS_STAGED'
        WHEN v_workbench_nudge_refresh_status = 'NOT_REQUIRED_NO_SOURCE_SESSION' THEN 'PAYMENT_CORRECTION_WORKBENCH_NO_SOURCE_SESSION'
        WHEN v_workbench_nudge_refresh_status = 'CURRENT' THEN 'PAYMENT_CORRECTION_WORKBENCH_NO_ACTIVE_JOB'
        ELSE 'PAYMENT_CORRECTION_WORKBENCH_NOT_REQUIRED'
      END,
      'operation_id', v_operation.id,
      'correction_request_id', p_correction_request_id,
      'session_id', v_session_id,
      'actor_user_id', v_refresh_actor_user_id,
      'refresh_sequence_no', v_refresh_sequence,
      'refresh_has_more', v_refresh_has_more,
      'candidate_ids', v_workbench_nudge_candidate_ids,
      'candidate_count', v_workbench_nudge_candidate_count,
      'job_ids', v_workbench_nudge_job_ids,
      'job_count', v_workbench_nudge_job_count,
      'source', 'PAYMENT_CORRECTION_REFRESH_WORKBENCH'
    );

    IF COALESCE(v_held_dirty_absorption_enabled,false)
       AND v_session_id IS NOT NULL AND v_workbench_nudge_candidate_count>0 THEN
      v_held_dirty_resolution:=private.pay_workbench_correction_held_dirty_job_resolve_v1(
        p_correction_request_id,v_operation.id,v_session_id,
        pg_catalog.jsonb_build_object(
          'candidate_ids',v_workbench_nudge_candidate_ids,
          'route_status',COALESCE(v_refresh_result->>'status',v_workbench_nudge_refresh_status),
          'active_owner_job_ids',v_workbench_nudge_job_ids
          ,'post_commit_authorities_v3',v_post_commit_authorities_v3->'candidate_authorities'
        ),
        pg_catalog.jsonb_build_object('owner','pay_payment_correction_process_chunk')
      );
    ELSIF COALESCE(v_held_dirty_absorption_enabled,false) THEN
      v_held_dirty_resolution:=pg_catalog.jsonb_build_object(
        'ok',true,'status','NOT_REQUIRED','resolved_count',0
      );
    ELSE
      v_held_dirty_resolution:=pg_catalog.jsonb_build_object(
        'ok',true,'status','DISABLED','resolved_count',0
      );
    END IF;

    v_refresh_result := v_refresh_result
      || pg_catalog.jsonb_build_object(
        'workbench_refresh_nudge',v_workbench_refresh_nudge,
        'correction_held_dirty_job_resolution',v_held_dirty_resolution
      );

    INSERT INTO public.banking_pay_operation_chunks (
      operation_id, phase, chunk_type, sequence_no, status, payload_json, result_json,
      error_json, unit_count, completed_count, failed_count, started_at_utc, completed_at_utc
    ) VALUES (
      v_operation.id, 'REFRESH_WORKBENCH', 'CANDIDATE_SCOPE', v_refresh_sequence,
      'COMPLETE', pg_catalog.jsonb_build_object('candidate_ids', v_refresh_candidate_ids),
      COALESCE(v_refresh_result, '{}'::jsonb), NULL,
      v_refresh_count, v_refresh_count, 0, v_now, v_now
    ) ON CONFLICT (operation_id, phase, chunk_type, sequence_no) DO NOTHING;

    UPDATE public.banking_pay_operations AS refresh_operation
    SET progress_json = COALESCE(refresh_operation.progress_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'last_refreshed_selection_ordinal', v_refresh_next,
            'workbench_refresh_status', CASE
              WHEN v_refresh_count = 0
                OR COALESCE(v_refresh_result->>'status', '') LIKE 'NOT_REQUIRED%'
                THEN 'CURRENT'
              ELSE 'STAGED'
            END
          ),
        phase = CASE WHEN v_refresh_has_more THEN 'REFRESH_WORKBENCH' ELSE 'COMPLETE' END,
        status = CASE WHEN v_refresh_has_more THEN 'RUNNING' ELSE 'COMPLETE' END,
        runner_state = CASE WHEN v_refresh_has_more THEN 'RUNNABLE' ELSE 'COMPLETE' END,
        run_after_utc = CASE WHEN v_refresh_has_more THEN v_now ELSE NULL END,
        completed_at_utc = CASE WHEN v_refresh_has_more THEN refresh_operation.completed_at_utc ELSE v_now END,
        updated_at_utc = v_now
    WHERE refresh_operation.id = v_operation.id;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'phase', CASE WHEN v_refresh_has_more THEN 'REFRESH_WORKBENCH' ELSE 'COMPLETE' END,
      'candidate_count', v_refresh_count, 'complete', NOT v_refresh_has_more,
      'workbench_refresh', v_refresh_result,
      'workbench_refresh_nudge', v_workbench_refresh_nudge,
      'processed', v_refresh_count,
      'applied', 0,
      'skipped', 0,
      'blocked', 0,
      'failed_retryable', 0,
      'failed_final', 0,
      'pending', 0,
      'processing', 0,
      'progress_completed', v_refresh_next,
      'progress_total', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_payment_correction_work_items AS applied_work
        WHERE applied_work.correction_request_id = p_correction_request_id
          AND applied_work.status = 'APPLIED'
      ),
      'parent_status', v_request.status,
      'totals', pg_catalog.jsonb_build_object(
        'refresh_candidate_count', v_refresh_count,
        'refresh_has_more', v_refresh_has_more
      ),
      'requires_user_action', v_operation.requires_user_action,
      'processing_continues', v_refresh_has_more,
      'changed_scope_json', '{}'::jsonb,
      'live_signal_updates', pg_catalog.jsonb_build_object(
        'workbench_refresh', v_refresh_result
      ),
      'continuation', pg_catalog.jsonb_build_object(
        'required', v_refresh_has_more, 'operation_id', v_operation.id,
        'operation_type', 'PAYMENT_CORRECTION', 'pay_batch_id', v_request.pay_batch_id,
        'root_operation_id', v_operation.root_operation_id,
        'phase', CASE WHEN v_refresh_has_more THEN 'REFRESH_WORKBENCH' ELSE 'COMPLETE' END,
        'run_after_utc', CASE WHEN v_refresh_has_more THEN v_now ELSE NULL END,
        'reason', CASE WHEN v_refresh_has_more THEN 'PAYMENT_CORRECTION_REFRESH_MORE_WORK' ELSE 'PAYMENT_CORRECTION_COMPLETE' END,
        'successor_relation', CASE WHEN v_refresh_has_more THEN 'SELF' ELSE 'NONE' END,
        'requires_user_action', CASE WHEN v_refresh_has_more THEN false ELSE COALESCE(v_operation.requires_user_action, false) END,
        'terminal', NOT v_refresh_has_more
      ),
      'code', CASE WHEN v_refresh_has_more THEN 'PAYMENT_CORRECTION_WORKBENCH_PAGE_STAGED' ELSE 'PAYMENT_CORRECTION_COMPLETE' END
    );
  END IF;

  IF v_phase = 'COMPLETE' OR v_operation.status = 'COMPLETE' THEN
    -- Lost-response and terminal replay must be able to wake the latest
    -- committed refresh page without repeating any correction work.  Rebuild
    -- the scheduling decision from the durable page and current pending job.
    v_session_id := v_batch.source_workbench_session_id;
    v_refresh_actor_user_id := NULL;
    IF v_session_id IS NOT NULL THEN
      SELECT session_row.actor_user_id
      INTO v_refresh_actor_user_id
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = v_session_id
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL;
    END IF;

    SELECT completed_refresh.result_json,
           completed_refresh.payload_json,
           completed_refresh.sequence_no
    INTO v_refresh_result, v_latest_refresh_payload, v_refresh_sequence
    FROM public.banking_pay_operation_chunks AS completed_refresh
    WHERE completed_refresh.operation_id = v_operation.id
      AND completed_refresh.phase = 'REFRESH_WORKBENCH'
      AND completed_refresh.chunk_type = 'CANDIDATE_SCOPE'
      AND completed_refresh.status = 'COMPLETE'
    ORDER BY completed_refresh.sequence_no DESC
    LIMIT 1;

    IF NOT FOUND THEN
      v_refresh_result := '{}'::jsonb;
      v_latest_refresh_payload := '{}'::jsonb;
      v_refresh_sequence := 1;
      v_refresh_candidate_ids := '[]'::jsonb;
    ELSE
      v_refresh_result := COALESCE(v_refresh_result, '{}'::jsonb);
      v_latest_refresh_payload := COALESCE(v_latest_refresh_payload, '{}'::jsonb);
      v_refresh_sequence := GREATEST(COALESCE(v_refresh_sequence, 1), 1);
      v_refresh_candidate_ids := CASE
        WHEN pg_catalog.jsonb_typeof(v_latest_refresh_payload->'candidate_ids') = 'array'
          THEN v_latest_refresh_payload->'candidate_ids'
        ELSE '[]'::jsonb
      END;
    END IF;
    v_refresh_has_more := false;

    SELECT COALESCE(pg_catalog.jsonb_agg(candidate_scope.candidate_id::text ORDER BY candidate_scope.candidate_id), '[]'::jsonb),
           pg_catalog.count(*)::integer
    INTO v_workbench_nudge_candidate_ids, v_workbench_nudge_candidate_count
    FROM (
      SELECT DISTINCT candidate_value.value::uuid AS candidate_id
      FROM pg_catalog.jsonb_array_elements_text(COALESCE(v_refresh_candidate_ids, '[]'::jsonb)) AS candidate_value(value)
      WHERE pg_catalog.pg_input_is_valid(candidate_value.value, 'uuid')
    ) AS candidate_scope;

    WITH page_candidates AS (
      SELECT candidate_value.value::uuid AS candidate_id
      FROM pg_catalog.jsonb_array_elements_text(v_workbench_nudge_candidate_ids) AS candidate_value(value)
    ),
    raw_job_ids AS (
      SELECT job_value.value AS job_id_text
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'job_ids') = 'array'
          THEN v_refresh_result->'job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'full_candidate_refresh_job_ids') = 'array'
          THEN v_refresh_result->'full_candidate_refresh_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'session_recompute_job_ids') = 'array'
          THEN v_refresh_result->'session_recompute_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'workbench_refresh_job_ids') = 'array'
          THEN v_refresh_result->'workbench_refresh_job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT job_value.value
      FROM pg_catalog.jsonb_array_elements_text(
        CASE WHEN pg_catalog.jsonb_typeof(v_refresh_result->'workbench_refresh_nudge'->'job_ids') = 'array'
          THEN v_refresh_result->'workbench_refresh_nudge'->'job_ids' ELSE '[]'::jsonb END
      ) AS job_value(value)
      UNION ALL
      SELECT scope_row.pending_job_id::text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      JOIN page_candidates AS page_candidate ON page_candidate.candidate_id = scope_row.candidate_id
      WHERE scope_row.session_id = v_session_id
        AND scope_row.pending_job_id IS NOT NULL
    ),
    canonical_job_ids AS (
      SELECT DISTINCT raw_job.job_id_text::uuid AS job_id
      FROM raw_job_ids AS raw_job
      WHERE pg_catalog.pg_input_is_valid(raw_job.job_id_text, 'uuid')
    ),
    active_jobs AS (
      SELECT job_row.id
      FROM canonical_job_ids AS canonical_job
      JOIN public.banking_pay_workbench_jobs AS job_row ON job_row.id = canonical_job.job_id
      JOIN page_candidates AS page_candidate ON page_candidate.candidate_id = job_row.candidate_id
      JOIN public.banking_pay_workbench_session_scope AS scope_row
        ON scope_row.session_id = job_row.session_id
       AND scope_row.candidate_id = job_row.candidate_id
       AND scope_row.pending_job_id = job_row.id
      WHERE job_row.session_id = v_session_id
        AND job_row.status IN ('QUEUED', 'RUNNING')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(job_row.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        )
      ORDER BY job_row.id
      LIMIT 100
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(active_job.id::text ORDER BY active_job.id), '[]'::jsonb),
           pg_catalog.count(*)::integer
    INTO v_workbench_nudge_job_ids, v_workbench_nudge_job_count
    FROM active_jobs AS active_job;

    v_workbench_nudge_refresh_status := CASE
      WHEN v_workbench_nudge_candidate_count = 0 THEN 'NOT_REQUIRED'
      WHEN v_session_id IS NULL THEN 'NOT_REQUIRED_NO_SOURCE_SESSION'
      WHEN v_refresh_actor_user_id IS NULL THEN 'CURRENT'
      WHEN v_workbench_nudge_job_count > 0 THEN 'STAGED'
      ELSE 'CURRENT'
    END;

    v_workbench_refresh_nudge := pg_catalog.jsonb_build_object(
      'contract_version', 'PAYMENT_CORRECTION_WORKBENCH_NUDGE_V1',
      'nudge_required', v_workbench_nudge_refresh_status = 'STAGED'
        AND v_session_id IS NOT NULL
        AND v_refresh_actor_user_id IS NOT NULL
        AND v_workbench_nudge_candidate_count > 0
        AND v_workbench_nudge_job_count > 0,
      'refresh_status', v_workbench_nudge_refresh_status,
      'reason', CASE
        WHEN v_workbench_nudge_refresh_status = 'STAGED' THEN 'PAYMENT_CORRECTION_WORKBENCH_JOBS_STAGED'
        WHEN v_workbench_nudge_refresh_status = 'NOT_REQUIRED_NO_SOURCE_SESSION' THEN 'PAYMENT_CORRECTION_WORKBENCH_NO_SOURCE_SESSION'
        WHEN v_workbench_nudge_refresh_status = 'CURRENT' THEN 'PAYMENT_CORRECTION_WORKBENCH_NO_ACTIVE_JOB'
        ELSE 'PAYMENT_CORRECTION_WORKBENCH_NOT_REQUIRED'
      END,
      'operation_id', v_operation.id,
      'correction_request_id', p_correction_request_id,
      'session_id', v_session_id,
      'actor_user_id', v_refresh_actor_user_id,
      'refresh_sequence_no', v_refresh_sequence,
      'refresh_has_more', false,
      'candidate_ids', v_workbench_nudge_candidate_ids,
      'candidate_count', v_workbench_nudge_candidate_count,
      'job_ids', v_workbench_nudge_job_ids,
      'job_count', v_workbench_nudge_job_count,
      'source', 'PAYMENT_CORRECTION_REFRESH_WORKBENCH'
    );

    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'correction_request_id', p_correction_request_id,
      'operation_id', v_operation.id, 'phase', 'COMPLETE',
      'result', v_operation.result_json,
      'workbench_refresh_nudge', v_workbench_refresh_nudge,
      'processed', 0,
      'applied', COALESCE((v_operation.result_json->>'applied_candidate_count')::integer, 0),
      'skipped', 0,
      'blocked', COALESCE((v_operation.result_json->>'blocked_candidate_count')::integer, 0),
      'failed_retryable', 0,
      'failed_final', COALESCE((v_operation.result_json->>'failed_candidate_count')::integer, 0),
      'pending', 0,
      'processing', 0,
      'progress_completed', COALESCE(v_operation.completed_units, 0),
      'progress_total', COALESCE(v_operation.total_units, v_operation.completed_units, 0),
      'parent_status', v_request.status,
      'totals', COALESCE(v_operation.result_json, '{}'::jsonb),
      'complete', true,
      'requires_user_action', v_operation.requires_user_action,
      'processing_continues', false,
      'changed_scope_json', '{}'::jsonb,
      'live_signal_updates', pg_catalog.jsonb_build_object(
        'workbench_refresh_staging_complete', true,
        'workbench_freshness_must_be_read_from_jobs_and_candidate_state', true
      ),
      'continuation', pg_catalog.jsonb_build_object(
        'required', false, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', 'COMPLETE', 'run_after_utc', NULL, 'reason', 'PAYMENT_CORRECTION_COMPLETE',
        'successor_relation', 'NONE', 'requires_user_action', COALESCE(v_operation.requires_user_action, false),
        'terminal', true
      ),
      'code', 'PAYMENT_CORRECTION_ALREADY_COMPLETE'
    );
  END IF;

  RAISE EXCEPTION 'PAYMENT_CORRECTION_PHASE_NOT_RUNNABLE'
    USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
      'code', 'PAYMENT_CORRECTION_PHASE_NOT_RUNNABLE', 'phase', v_phase
    )::text;
END;
$function$;

-- pay_payment_correction_reauth_bind_v1(uuid,uuid,text,text,timestamp with time zone,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_reauth_bind_v1(p_correction_request_id uuid, p_actor_user_id uuid, p_session_hash text, p_proof_hash text, p_issued_at_utc timestamp with time zone, p_expires_at_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_request public.pay_payment_correction_requests%ROWTYPE;
    v_code text;
    v_previous_hash text;
    v_previous_expiry timestamptz;
BEGIN
    IF p_correction_request_id IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REQUEST_NOT_FOUND',
            'message', 'The payment-correction request was not found.'
        );
    END IF;

    SELECT request_row.*
    INTO v_request
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.id = p_correction_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REQUEST_NOT_FOUND',
            'message', 'The payment-correction request was not found.'
        );
    END IF;

    IF v_request.status <> 'PLANNED' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REQUEST_STATE_INVALID',
            'message', 'This payment-correction plan is no longer awaiting reauthentication.'
        );
    END IF;

    IF p_actor_user_id IS NULL
       OR p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'ACTOR_MISMATCH',
            'message', 'Only the requester can reauthenticate this payment correction.'
        );
    END IF;

    IF p_session_hash IS NULL
       OR p_session_hash !~ '^[0-9a-f]{64}$'
       OR p_proof_hash IS NULL
       OR p_proof_hash !~ '^[0-9a-f]{64}$' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'HASH_INVALID',
            'message', 'The reauthentication binding is invalid.'
        );
    END IF;

    IF p_issued_at_utc IS NULL
       OR p_issued_at_utc <> pg_catalog.date_trunc('second', p_issued_at_utc)
       OR p_issued_at_utc > v_now + interval '30 seconds'
       OR p_issued_at_utc < v_now - interval '2 minutes' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REAUTH_ISSUED_AT_INVALID',
            'message', 'The reauthentication proof issue time is invalid.'
        );
    END IF;

    IF p_expires_at_utc IS NULL
       OR p_expires_at_utc <> pg_catalog.date_trunc('second', p_expires_at_utc)
       OR p_expires_at_utc <= v_now THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REAUTH_EXPIRED',
            'message', 'The reauthentication proof has expired.'
        );
    END IF;

    IF p_expires_at_utc > v_now + interval '10 minutes' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REAUTH_EXPIRY_EXCEEDS_DATABASE_LIMIT',
            'message', 'The reauthentication proof expiry exceeds the permitted limit.'
        );
    END IF;

    IF p_expires_at_utc <= p_issued_at_utc
       OR p_expires_at_utc > p_issued_at_utc + interval '10 minutes' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REAUTH_EXPIRY_BINDING_INVALID',
            'message', 'The signed reauthentication interval is invalid.'
        );
    END IF;

    IF p_expires_at_utc > v_request.requested_at_utc + interval '24 hours' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'REAUTH_EXPIRY_EXCEEDS_REQUEST_EXPIRY',
            'message', 'The reauthentication proof exceeds the request expiry.'
        );
    END IF;

    IF v_request.reauth_consumed_at_utc IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'reauth_consumed_at_utc', v_request.reauth_consumed_at_utc,
            'code', 'REAUTH_ALREADY_CONSUMED',
            'message', 'This reauthentication proof has already been consumed.'
        );
    END IF;

    IF v_request.selection_hash IS NULL OR v_request.plan_hash IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'code', 'PAYMENT_CORRECTION_PLAN_STALE',
            'message', 'The payment-correction plan is incomplete. Refresh and start again.'
        );
    END IF;

    IF v_request.reauth_proof_hash = p_proof_hash
       AND v_request.reauth_expires_at_utc = p_expires_at_utc THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', true,
            'correction_request_id', p_correction_request_id,
            'actor_user_id', p_actor_user_id,
            'reauth_proof_hash', v_request.reauth_proof_hash,
            'signed_issued_at_utc', p_issued_at_utc,
            'reauth_expires_at_utc', v_request.reauth_expires_at_utc,
            'reauth_consumed_at_utc', v_request.reauth_consumed_at_utc,
            'plan_hash', v_request.plan_hash,
            'selection_hash', v_request.selection_hash,
            'code', 'REAUTH_BOUND_EXISTING',
            'message', NULL
        );
    END IF;

    v_previous_hash := v_request.reauth_proof_hash;
    v_previous_expiry := v_request.reauth_expires_at_utc;
    v_code := CASE
        WHEN v_previous_hash IS NULL THEN 'REAUTH_BOUND'
        ELSE 'REAUTH_REPLACED'
    END;

    UPDATE public.pay_payment_correction_requests AS request_to_bind
    SET reauth_proof_hash = p_proof_hash,
        reauth_expires_at_utc = p_expires_at_utc,
        reauth_consumed_at_utc = NULL,
        updated_at_utc = v_now
    WHERE request_to_bind.id = p_correction_request_id;

    INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
    )
    VALUES (
        p_correction_request_id,
        v_request.pay_batch_id,
        'USER',
        p_actor_user_id,
        'APPLY',
        v_now,
        NULL,
        pg_catalog.jsonb_build_object(
            'proof_bound', v_previous_hash IS NOT NULL,
            'expires_at_utc', v_previous_expiry
        ),
        pg_catalog.jsonb_build_object(
            'proof_bound', true,
            'expires_at_utc', p_expires_at_utc
        ),
        pg_catalog.jsonb_build_object(
            'audit_code', v_code,
            'session_bound', true,
            'signed_issued_at_utc', p_issued_at_utc,
            'signed_expires_at_utc', p_expires_at_utc
        )
    );

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'correction_request_id', p_correction_request_id,
        'actor_user_id', p_actor_user_id,
        'reauth_proof_hash', p_proof_hash,
        'signed_issued_at_utc', p_issued_at_utc,
        'reauth_expires_at_utc', p_expires_at_utc,
        'reauth_consumed_at_utc', NULL,
        'plan_hash', v_request.plan_hash,
        'selection_hash', v_request.selection_hash,
        'code', v_code,
        'message', NULL
    );
END
$function$;

-- pay_payment_correction_reauthorisation_overlay_reset_v1(uuid,uuid,uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_reauthorisation_overlay_reset_v1(p_correction_request_id uuid, p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '5000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_requested_action text := NULL::text;
  v_active_item_count integer := 0;
  v_linked_active_item_count integer := 0;
  v_transfer_count integer := 0;
  v_transfer_scope_count integer := 0;
  v_unsafe_transfer_count integer := 0;
  v_item_links_cleared integer := 0;
  v_bank_references_cleared integer := 0;
  v_transfer_scopes_deleted integer := 0;
  v_transfers_voided integer := 0;
  v_transfer_ids jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_correction_request_id IS NULL OR p_operation_id IS NULL OR p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_IDENTIFIERS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_IDENTIFIERS_REQUIRED'
            )::text;
  END IF;

  SELECT request_row.*
  INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;

  IF NOT FOUND OR v_request.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_REQUEST_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_REQUEST_BATCH_MISMATCH',
              'correction_request_id', p_correction_request_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.operation_type, ''))) <> 'PAYMENT_CORRECTION'
     OR v_operation.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR COALESCE(v_operation.input_json->>'correction_request_id', '') <> p_correction_request_id::text THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_OPERATION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OPERATION_MISMATCH',
              'correction_request_id', p_correction_request_id,
              'operation_id', p_operation_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_requested_action := pg_catalog.upper(pg_catalog.btrim(COALESCE(
    v_request.plan_json->>'requested_action',
    v_request.selection_json->>'requested_action',
    ''
  )));

  IF v_requested_action NOT IN ('PRE_BANK_CANCEL', 'CANCEL_PAYMENT') THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'required', false,
      'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_NOT_REQUIRED_FOR_ACTION',
      'requested_action', v_requested_action,
      'correction_request_id', p_correction_request_id,
      'operation_id', p_operation_id,
      'pay_batch_id', p_pay_batch_id
    );
  END IF;

  IF pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.status, ''))) <> 'DRAFT'
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR NULLIF(pg_catalog.btrim(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_BATCH_STATE_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_BATCH_STATE_UNSAFE',
              'pay_batch_id', p_pay_batch_id,
              'batch_status', v_batch.status,
              'execution_commit_state', v_batch.execution_commit_state,
              'execution_commit_ref_present', NULLIF(pg_catalog.btrim(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL,
              'execution_committed_at_present', v_batch.execution_committed_at_utc IS NOT NULL
            )::text;
  END IF;

  -- Serialize the exact active frozen remainder before resolving linked local
  -- transfers. This never reads live finance/timesheet truth.
  PERFORM 1
  FROM public.pay_batch_items AS item_lock
  JOIN public.pay_batch_candidates AS candidate_lock
    ON candidate_lock.id = item_lock.pay_batch_candidate_id
  WHERE candidate_lock.pay_batch_id = p_pay_batch_id
    AND COALESCE(item_lock.is_voided, false) = false
  ORDER BY item_lock.id
  FOR UPDATE OF item_lock;

  SELECT pg_catalog.count(*)::integer
  INTO v_active_item_count
  FROM public.pay_batch_items AS active_item
  JOIN public.pay_batch_candidates AS active_candidate
    ON active_candidate.id = active_item.pay_batch_candidate_id
  WHERE active_candidate.pay_batch_id = p_pay_batch_id
    AND COALESCE(active_item.is_voided, false) = false;

  IF COALESCE(v_active_item_count, 0) = 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'required', false,
      'code', 'PAYMENT_CORRECTION_REAUTHORISATION_NO_ACTIVE_REMAINDER',
      'correction_request_id', p_correction_request_id,
      'operation_id', p_operation_id,
      'pay_batch_id', p_pay_batch_id,
      'active_item_count', 0
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_correction_reauthorisation_transfers;
  CREATE TEMPORARY TABLE pg_temp._tmp_correction_reauthorisation_transfers ON COMMIT DROP AS
  SELECT DISTINCT
    transfer_row.id AS pay_bank_transfer_id,
    transfer_row.payment_reference
  FROM public.pay_batch_items AS active_item
  JOIN public.pay_batch_candidates AS active_candidate
    ON active_candidate.id = active_item.pay_batch_candidate_id
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = active_item.pay_bank_transfer_id
  WHERE active_candidate.pay_batch_id = p_pay_batch_id
    AND COALESCE(active_item.is_voided, false) = false
    AND active_item.pay_bank_transfer_id IS NOT NULL;

  SELECT pg_catalog.count(*)::integer,
         COALESCE(pg_catalog.jsonb_agg(
           transfer_scope.pay_bank_transfer_id::text
           ORDER BY transfer_scope.pay_bank_transfer_id
         ), '[]'::jsonb)
  INTO v_transfer_count, v_transfer_ids
  FROM pg_temp._tmp_correction_reauthorisation_transfers AS transfer_scope;

  -- A completed unsent execution retains its operation-local transfer scope.
  -- That scope is no longer authoritative after the correction has returned
  -- the remainder to Draft, and the table's batch/group uniqueness would
  -- otherwise reject the next legitimate execution attempt. Preserve the
  -- parent operation audit row, but retire only scopes tied to the exact local
  -- transfers proven safe below. Scope-item rows cascade from this exact set.
  DROP TABLE IF EXISTS pg_temp._tmp_correction_reauthorisation_transfer_scopes;
  CREATE TEMPORARY TABLE pg_temp._tmp_correction_reauthorisation_transfer_scopes ON COMMIT DROP AS
  SELECT execution_scope.id AS transfer_scope_id
  FROM public.banking_pay_operation_transfer_scope AS execution_scope
  JOIN pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
    ON target_transfer.pay_bank_transfer_id = execution_scope.pay_bank_transfer_id
  WHERE execution_scope.pay_batch_id = p_pay_batch_id;

  SELECT pg_catalog.count(*)::integer
  INTO v_transfer_scope_count
  FROM pg_temp._tmp_correction_reauthorisation_transfer_scopes;

  SELECT pg_catalog.count(*)::integer
  INTO v_linked_active_item_count
  FROM public.pay_batch_items AS linked_item
  JOIN public.pay_batch_candidates AS linked_candidate
    ON linked_candidate.id = linked_item.pay_batch_candidate_id
  JOIN pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
    ON target_transfer.pay_bank_transfer_id = linked_item.pay_bank_transfer_id
  WHERE linked_candidate.pay_batch_id = p_pay_batch_id
    AND COALESCE(linked_item.is_voided, false) = false;

  IF COALESCE(v_transfer_count, 0) = 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'required', false,
      'code', 'PAYMENT_CORRECTION_REAUTHORISATION_NO_TRANSFER_OVERLAY',
      'correction_request_id', p_correction_request_id,
      'operation_id', p_operation_id,
      'pay_batch_id', p_pay_batch_id,
      'active_item_count', v_active_item_count
    );
  END IF;

  IF v_transfer_count > 2000 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_SCOPE_TOO_LARGE',
              'transfer_count', v_transfer_count,
              'maximum_transfer_count', 2000
            )::text;
  END IF;

  IF v_transfer_scope_count > 2000 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_SCOPE_TOO_LARGE',
              'transfer_scope_count', v_transfer_scope_count,
              'maximum_transfer_scope_count', 2000
            )::text;
  END IF;

  PERFORM 1
  FROM public.pay_bank_transfers AS transfer_lock
  JOIN pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
    ON target_transfer.pay_bank_transfer_id = transfer_lock.id
  ORDER BY transfer_lock.id
  FOR UPDATE OF transfer_lock;

  PERFORM 1
  FROM public.banking_pay_operation_transfer_scope AS scope_lock
  JOIN pg_temp._tmp_correction_reauthorisation_transfer_scopes AS target_scope
    ON target_scope.transfer_scope_id = scope_lock.id
  ORDER BY scope_lock.id
  FOR UPDATE OF scope_lock;

  SELECT pg_catalog.count(*)::integer
  INTO v_unsafe_transfer_count
  FROM public.pay_bank_transfers AS transfer_row
  JOIN pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
    ON target_transfer.pay_bank_transfer_id = transfer_row.id
  WHERE transfer_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.status, ''))) <> 'PENDING'
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
     OR transfer_row.completed_at_utc IS NOT NULL
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.failed_reason, '')), '') IS NOT NULL
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', '')), '') IS NOT NULL
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', '')), '') IS NOT NULL
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') IS NOT NULL
     OR NULLIF(pg_catalog.btrim(COALESCE(transfer_row.rail_meta_json #>> '{provider_submission_id}', '')), '') IS NOT NULL
     OR EXISTS (
       SELECT 1
       FROM public.pay_bank_transfer_events AS transfer_event
       WHERE transfer_event.pay_bank_transfer_id = transfer_row.id
     )
     OR EXISTS (
       SELECT 1
       FROM public.banking_pay_operation_transfer_scope AS execution_scope
       WHERE execution_scope.pay_bank_transfer_id = transfer_row.id
         AND (
           COALESCE(execution_scope.provider_submit_attempt_count, 0) > 0
           OR NULLIF(pg_catalog.btrim(COALESCE(execution_scope.provider_transaction_id, '')), '') IS NOT NULL
           OR execution_scope.provider_request_sending_at_utc IS NOT NULL
           OR execution_scope.provider_request_sent_at_utc IS NOT NULL
           OR execution_scope.provider_response_at_utc IS NOT NULL
         )
     )
     OR EXISTS (
       SELECT 1
       FROM public.banking_pay_operation_provider_attempts AS provider_attempt
       JOIN public.banking_pay_operation_transfer_scope AS attempted_scope
         ON attempted_scope.id = provider_attempt.transfer_scope_id
       WHERE attempted_scope.pay_bank_transfer_id = transfer_row.id
     );

  IF COALESCE(v_unsafe_transfer_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_EVIDENCE_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_TRANSFER_EVIDENCE_UNSAFE',
              'unsafe_transfer_count', v_unsafe_transfer_count,
              'transfer_count', v_transfer_count,
              'correction_request_id', p_correction_request_id,
              'operation_id', p_operation_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  IF COALESCE(p_dry_run, false) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'required', true,
      'dry_run', true,
      'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_SAFE_TO_RESET',
      'correction_request_id', p_correction_request_id,
      'operation_id', p_operation_id,
      'pay_batch_id', p_pay_batch_id,
      'active_item_count', v_active_item_count,
      'linked_active_item_count', v_linked_active_item_count,
      'transfer_count', v_transfer_count,
      'transfer_scope_count', v_transfer_scope_count,
      'transfer_ids', v_transfer_ids
    );
  END IF;

  WITH item_rows_to_clear AS (
    SELECT active_item.id AS pay_batch_item_id,
           active_item.bank_reference AS previous_bank_reference,
           target_transfer.payment_reference AS transfer_payment_reference
    FROM public.pay_batch_items AS active_item
    JOIN public.pay_batch_candidates AS active_candidate
      ON active_candidate.id = active_item.pay_batch_candidate_id
    JOIN pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
      ON target_transfer.pay_bank_transfer_id = active_item.pay_bank_transfer_id
    WHERE active_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(active_item.is_voided, false) = false
  ), cleared_item_links AS (
    UPDATE public.pay_batch_items AS item_update
    SET pay_bank_transfer_id = NULL::uuid,
        bank_reference = CASE
          WHEN item_update.bank_reference = item_rows_to_clear.transfer_payment_reference THEN NULL::text
          ELSE item_update.bank_reference
        END,
        updated_at = v_now
    FROM item_rows_to_clear
    WHERE item_update.id = item_rows_to_clear.pay_batch_item_id
    RETURNING item_update.id,
              item_rows_to_clear.previous_bank_reference,
              item_rows_to_clear.transfer_payment_reference
  )
  SELECT pg_catalog.count(*)::integer,
         (pg_catalog.count(*) FILTER (
           WHERE cleared_item_links.previous_bank_reference = cleared_item_links.transfer_payment_reference
             AND NULLIF(pg_catalog.btrim(COALESCE(cleared_item_links.previous_bank_reference, '')), '') IS NOT NULL
         ))::integer
  INTO v_item_links_cleared, v_bank_references_cleared
  FROM cleared_item_links;

  WITH deleted_transfer_scopes AS (
    DELETE FROM public.banking_pay_operation_transfer_scope AS scope_delete
    USING pg_temp._tmp_correction_reauthorisation_transfer_scopes AS target_scope
    WHERE scope_delete.id = target_scope.transfer_scope_id
      AND scope_delete.pay_batch_id = p_pay_batch_id
      AND scope_delete.pay_bank_transfer_id IN (
        SELECT target_transfer.pay_bank_transfer_id
        FROM pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
      )
    RETURNING scope_delete.id
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_transfer_scopes_deleted
  FROM deleted_transfer_scopes;

  WITH voided_transfers AS (
    UPDATE public.pay_bank_transfers AS transfer_update
    SET amount = 0,
        status = 'VOIDED',
        failed_reason = COALESCE(
          NULLIF(pg_catalog.btrim(COALESCE(transfer_update.failed_reason, '')), ''),
          'CANCELLATION_REAUTHORISATION_OVERLAY_VOIDED'
        ),
        rail_meta_json = COALESCE(transfer_update.rail_meta_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'cancellation_reauthorisation_overlay_voided', true,
            'correction_request_id', p_correction_request_id,
            'correction_operation_id', p_operation_id,
            'voided_at_utc', v_now,
            'voided_by_user_id', p_actor_user_id
          )
    FROM pg_temp._tmp_correction_reauthorisation_transfers AS target_transfer
    WHERE transfer_update.id = target_transfer.pay_bank_transfer_id
      AND transfer_update.pay_batch_id = p_pay_batch_id
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_update.status, ''))) = 'PENDING'
      AND NULLIF(pg_catalog.btrim(COALESCE(transfer_update.rail_tx_id, '')), '') IS NULL
      AND transfer_update.completed_at_utc IS NULL
      AND NULLIF(pg_catalog.btrim(COALESCE(transfer_update.failed_reason, '')), '') IS NULL
    RETURNING transfer_update.id
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_transfers_voided
  FROM voided_transfers;

  IF v_transfer_scopes_deleted IS DISTINCT FROM v_transfer_scope_count
     OR v_transfers_voided IS DISTINCT FROM v_transfer_count
     OR v_item_links_cleared IS DISTINCT FROM v_linked_active_item_count THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_EFFECT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_EFFECT_MISMATCH',
              'expected_transfer_count', v_transfer_count,
              'transfers_voided', v_transfers_voided,
              'expected_transfer_scope_count', v_transfer_scope_count,
              'transfer_scopes_deleted', v_transfer_scopes_deleted,
              'expected_linked_active_item_count', v_linked_active_item_count,
              'item_links_cleared', v_item_links_cleared
            )::text;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'required', true,
    'dry_run', false,
    'code', 'PAYMENT_CORRECTION_REAUTHORISATION_OVERLAY_RESET',
    'correction_request_id', p_correction_request_id,
    'operation_id', p_operation_id,
    'pay_batch_id', p_pay_batch_id,
    'active_item_count', v_active_item_count,
    'linked_active_item_count', v_linked_active_item_count,
    'transfer_count', v_transfer_count,
    'transfer_scope_count', v_transfer_scope_count,
    'transfer_scopes_deleted', v_transfer_scopes_deleted,
    'item_links_cleared', v_item_links_cleared,
    'bank_references_cleared', v_bank_references_cleared,
    'transfers_voided', v_transfers_voided,
    'transfer_ids', v_transfer_ids,
    'policy_x_economics_changed', false
  );
END;
$function$;

-- pay_payment_correction_request_start(uuid,jsonb,text,uuid,uuid,boolean,jsonb)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_request_start(p_pay_batch_id uuid, p_selection_json jsonb, p_reason text, p_actor_user_id uuid, p_source_bank_event_id uuid DEFAULT NULL::uuid, p_auto_requested boolean DEFAULT false, p_accepted_resolution_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_command text;
  v_mode text;
  v_action text;
  v_filter jsonb;
  v_sort_key text;
  v_sort_direction text;
  v_snapshot_token text;
  v_active_scope_hash text;
  v_descriptor_hash text;
  v_plan_json jsonb;
  v_plan_hash text;
  v_selection jsonb;
  v_proof_hash text;
  v_correction_kind text;
  v_idempotency_key text;
  v_request_id uuid;
  v_operation_id uuid;
  v_request public.pay_payment_correction_requests%rowtype;
  v_batch public.pay_batches%rowtype;
  v_operation public.banking_pay_operations%rowtype;
  v_mutation_guard jsonb;
  v_operation_result jsonb;
  v_enabled boolean := false;
  v_actor_active boolean := false;
  v_required_quantity integer := 1;
  v_expected_snapshot_token text;
  v_old_auth_request_ids jsonb := '[]'::jsonb;
  v_old_schedule_kind text;
  v_old_scheduled_at_utc timestamptz;
  v_reason_hash text;
  v_evidence_hash text;
  v_outcome_hash text;
  v_explicit_tokens jsonb := '[]'::jsonb;
  v_canonical_explicit_tokens jsonb := '[]'::jsonb;
  v_requested_explicit_count integer := 0;
  v_unique_explicit_count integer := 0;
  v_requested_explicit_hash text;
  v_explicit_token text;
  v_max_candidates integer := 10000;
  v_auto_unwind_enabled boolean := false;
  v_source_event public.pay_bank_transfer_events%rowtype;
  v_auto_classification_result jsonb := '{}'::jsonb;
  v_existing_money_moved boolean := false;
  v_resume_reauthenticated_request boolean := false;
  v_candidate_id uuid;
  v_draft_overlay_pre_request_authorities jsonb := '{}'::jsonb;
  v_draft_overlay_start_admission jsonb := '{}'::jsonb;
  v_draft_overlay_start_authorities jsonb := '{}'::jsonb;
  v_cancel_reversion_pre_request_proof jsonb := '{}'::jsonb;
  v_cancel_reversion_pre_request_authorities_v2 jsonb := '{}'::jsonb;
  v_cancel_reversion_start_authorities_v2 jsonb := '{}'::jsonb;
  v_cancel_reversion_start_authorities_v3 jsonb := '{}'::jsonb;
  v_source_publication_identity_enforced boolean := false;
  v_scheduled_reversion_v2_observe_enabled boolean := false;
  v_q_bound_parent_proof jsonb := '{}'::jsonb;
  v_q_bound_authority jsonb := '{}'::jsonb;
  v_q_bound_candidate_authorities jsonb := '{}'::jsonb;
  v_q_bound_chain_digest_map jsonb := '{}'::jsonb;
  v_q_bound_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_q_bound_execution_operation_id uuid;
  v_q_bound_execution_operation_count integer := 0;
  v_q_bound_candidate_distinct_count integer := 0;
  v_q_bound_authority_set_digest text;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR pg_catalog.jsonb_typeof(p_selection_json) <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DESCRIPTOR_INVALID')::text;
  END IF;

  IF pg_catalog.octet_length(p_selection_json::text) > 524288 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_DESCRIPTOR_TOO_LARGE'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DESCRIPTOR_INVALID')::text;
  END IF;

  v_command := pg_catalog.upper(coalesce(p_selection_json->>'command', 'PREPARE'));
  IF v_command NOT IN ('PREPARE', 'START_PREPARED', 'START_AUTO') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_COMMAND_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DESCRIPTOR_INVALID')::text;
  END IF;

    SELECT settings_row.banking_pay_candidate_cancellation_enabled,
           least(coalesce(settings_row.banking_pay_correction_max_candidates, 10000), 10000),
           coalesce(settings_row.banking_pay_auto_unwind_terminal_no_money, false),
           coalesce(settings_row.banking_pay_source_publication_identity_enforce_v1_enabled, false),
           COALESCE((pg_catalog.to_jsonb(settings_row)
             ->>'banking_pay_scheduled_cancellation_reversion_v2_observe_enabled')::boolean,false)
    INTO v_enabled, v_max_candidates, v_auto_unwind_enabled,
         v_source_publication_identity_enforced,
         v_scheduled_reversion_v2_observe_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  -- Cancellation is authorised by exactly one authenticated user.  The
  -- organisation's payment_authoriser_quantity applies to creating/executing
  -- payments; it must never introduce a second-person cancellation approval.
  v_required_quantity := 1;

  IF coalesce(v_enabled, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_FEATURE_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_FEATURE_DISABLED')::text;
  END IF;

  IF v_command = 'PREPARE' THEN
    IF coalesce(p_auto_requested, false) IS NOT TRUE THEN
      IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_USER_ID_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'ACTOR_USER_ID_REQUIRED')::text;
      END IF;

      SELECT coalesce(actor_row.is_active, false)
      INTO v_actor_active
      FROM public.tms_users AS actor_row
      WHERE actor_row.id = p_actor_user_id;

      IF coalesce(v_actor_active, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'ACTOR_USER_INACTIVE'
          USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object('code', 'PERMISSION_DENIED')::text;
      END IF;
    ELSIF p_source_bank_event_id IS NULL THEN
      RAISE EXCEPTION 'SOURCE_BANK_EVENT_REQUIRED_FOR_AUTO_CORRECTION'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'SOURCE_BANK_EVENT_REQUIRED_FOR_AUTO_CORRECTION')::text;
    END IF;

    SELECT batch_row.*
    INTO v_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND')::text;
    END IF;

    IF pg_catalog.upper(pg_catalog.btrim(coalesce(v_batch.status, ''))) IN (
      'COMMITTED', 'COMPLETED', 'PAID', 'SETTLED', 'CANCELLED', 'CANCELED'
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_BATCH_TERMINAL'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_BATCH_TERMINAL',
          'batch_status', v_batch.status
        )::text;
    END IF;

    IF p_source_bank_event_id IS NOT NULL THEN
      SELECT event_row.*
      INTO v_source_event
      FROM public.pay_bank_transfer_events AS event_row
      WHERE event_row.id = p_source_bank_event_id
        AND event_row.pay_batch_id = p_pay_batch_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'SOURCE_BANK_EVENT_NOT_FOUND_FOR_BATCH'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'SOURCE_BANK_EVENT_NOT_FOUND_FOR_BATCH')::text;
      END IF;
    END IF;

    v_mode := pg_catalog.upper(coalesce(
      p_selection_json#>>'{selection,mode}', p_selection_json->>'mode', ''
    ));
    v_action := pg_catalog.upper(coalesce(
      p_selection_json#>>'{selection,action}', p_selection_json->>'requested_action', p_selection_json->>'action', ''
    ));
    v_filter := coalesce(
      p_selection_json#>'{selection,filter_json}', p_selection_json->'filter_json',
      p_selection_json#>'{selection,filter}', p_selection_json->'filter', '{}'::jsonb
    );
    v_sort_key := pg_catalog.upper(coalesce(
      p_selection_json#>>'{selection,sort_key}', p_selection_json->>'sort_key', 'STATUS'
    ));
    v_sort_direction := pg_catalog.upper(coalesce(
      p_selection_json#>>'{selection,sort_direction}', p_selection_json->>'sort_direction', 'ASC'
    ));

    IF v_mode NOT IN ('EXPLICIT', 'ALL_MATCHING')
       OR v_action NOT IN ('DRAFT_CANCEL', 'PRE_BANK_CANCEL', 'CANCEL_PAYMENT', 'NO_MONEY_RELEASE', 'NO_MONEY_UNWIND')
       OR pg_catalog.jsonb_typeof(v_filter) <> 'object'
       OR v_sort_key NOT IN ('STATUS', 'CANDIDATE', 'AMOUNT')
       OR v_sort_direction NOT IN ('ASC', 'DESC') THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_DESCRIPTOR_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DESCRIPTOR_INVALID')::text;
    END IF;

    IF v_action = 'DRAFT_CANCEL' AND NULLIF(pg_catalog.btrim(coalesce(p_reason, '')), '')
         IS DISTINCT FROM 'DRAFT_PAYMENT_CANCELLED_BY_USER' THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_DRAFT_REASON_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DRAFT_REASON_INVALID')::text;
    ELSIF v_action <> 'DRAFT_CANCEL'
       AND coalesce(p_auto_requested, false) IS NOT TRUE
       AND NULLIF(pg_catalog.btrim(coalesce(p_reason, '')), '') IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_REASON_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_REASON_REQUIRED')::text;
    END IF;

    IF coalesce(p_auto_requested, false) THEN
      v_auto_classification_result := public._pay_payment_movement_classify(
        p_pay_batch_id,
        p_selection_json
      );

      v_existing_money_moved := false;
      IF v_source_event.pay_bank_transfer_id IS NOT NULL THEN
        SELECT coalesce(movement_state.is_final_money_moved, false)
        INTO v_existing_money_moved
        FROM public.pay_bank_transfers AS transfer_row
        CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
          transfer_row.status,
          transfer_row.rail_state,
          coalesce(transfer_row.rail_meta_json, '{}'::jsonb),
          coalesce(transfer_row.rail_meta_json, '{}'::jsonb)
        ) AS movement_state
        WHERE transfer_row.id = v_source_event.pay_bank_transfer_id
        LIMIT 1;

        v_existing_money_moved := coalesce(v_existing_money_moved, false) OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS paid_event
          WHERE paid_event.pay_bank_transfer_id = v_source_event.pay_bank_transfer_id
            AND paid_event.id IS DISTINCT FROM v_source_event.id
            AND paid_event.normalised_state IN ('COMPLETED', 'PAID', 'SETTLED')
        );
      END IF;

      IF v_action IS DISTINCT FROM 'NO_MONEY_UNWIND'
         OR coalesce(v_auto_unwind_enabled, false) IS NOT TRUE
         OR v_source_event.id IS NULL
         OR v_source_event.pay_batch_id IS DISTINCT FROM p_pay_batch_id
         OR v_source_event.pay_bank_transfer_id IS NULL
         OR v_source_event.event_source NOT IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
         OR v_source_event.provider_event_transport NOT IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
         OR v_source_event.mapping_status IS DISTINCT FROM 'MATCHED'
         OR v_source_event.mapping_method NOT IN (
           'TRANSFER_ID', 'PROVIDER_EVENT_ID', 'PROVIDER_TRANSACTION_ID', 'REQUEST_ID',
           'PROVIDER_REFERENCE', 'RAIL_TX_ID', 'MATCHED_PROVIDER_EVENT', 'MANUAL_TRANSFER_SELECTION'
         )
         OR v_source_event.normalised_state NOT IN ('FAILED', 'REJECTED', 'CANCELLED')
         OR v_source_event.correction_disposition IS DISTINCT FROM 'AUTO_PROCESSING'
         OR coalesce((v_auto_classification_result->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
         OR (
           v_auto_classification_result->>'classification' NOT IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
           AND v_auto_classification_result->>'recommended_action' IS DISTINCT FROM 'NO_MONEY_UNWIND_AND_RECALCULATE'
         )
         OR coalesce(v_existing_money_moved, false)
         OR pg_catalog.jsonb_typeof(p_accepted_resolution_json) IS DISTINCT FROM 'object'
         OR p_accepted_resolution_json->>'contract_version' IS DISTINCT FROM '2'
         OR p_accepted_resolution_json->>'requested_action' IS DISTINCT FROM 'NO_MONEY_UNWIND'
         OR p_accepted_resolution_json->>'source_bank_event_id' IS DISTINCT FROM v_source_event.id::text
         OR p_accepted_resolution_json->>'source' IS DISTINCT FROM v_source_event.provider_event_transport
         OR p_accepted_resolution_json->>'event_source' IS DISTINCT FROM v_source_event.event_source
         OR p_accepted_resolution_json->>'provider_key' IS DISTINCT FROM v_source_event.provider_key
         OR p_accepted_resolution_json->>'provider_event_id' IS DISTINCT FROM v_source_event.provider_event_id
         OR p_accepted_resolution_json->>'provider_event_key' IS DISTINCT FROM v_source_event.provider_event_key
         OR p_accepted_resolution_json->>'provider_webhook_receipt_id'
              IS DISTINCT FROM (CASE WHEN v_source_event.provider_webhook_receipt_id IS NULL THEN NULL ELSE v_source_event.provider_webhook_receipt_id::text END)
         OR p_accepted_resolution_json->>'provider_transaction_id' IS DISTINCT FROM v_source_event.provider_transaction_id
         OR p_accepted_resolution_json->>'provider_request_id' IS DISTINCT FROM v_source_event.provider_request_id
         OR p_accepted_resolution_json->>'mapping_status' IS DISTINCT FROM v_source_event.mapping_status
         OR p_accepted_resolution_json->>'mapping_method' IS DISTINCT FROM v_source_event.mapping_method
         OR p_accepted_resolution_json->>'normalised_state' IS DISTINCT FROM v_source_event.normalised_state
         OR p_accepted_resolution_json->>'classification' IS DISTINCT FROM v_auto_classification_result->>'classification'
         OR p_accepted_resolution_json->>'recommended_action' IS DISTINCT FROM v_auto_classification_result->>'recommended_action'
         OR coalesce((p_accepted_resolution_json->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
         OR p_accepted_resolution_json->>'correction_disposition' IS DISTINCT FROM 'AUTO_PROCESSING'
         OR coalesce((p_accepted_resolution_json->>'terminal_no_money_evidence')::boolean, false) IS NOT TRUE
         OR coalesce((p_accepted_resolution_json->>'signature_valid')::boolean, false)
              IS DISTINCT FROM coalesce(v_source_event.provider_signature_valid, (
                SELECT receipt_row.signature_valid
                FROM public.bank_provider_webhook_receipts AS receipt_row
                WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
              ), false)
         OR (
           v_source_event.provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
           AND (
             v_source_event.provider_webhook_receipt_id IS NULL
             OR coalesce(v_source_event.provider_signature_valid, (
               SELECT receipt_row.signature_valid
               FROM public.bank_provider_webhook_receipts AS receipt_row
               WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
             ), false) IS NOT TRUE
             OR NOT EXISTS (
               SELECT 1
               FROM public.bank_provider_webhook_receipts AS receipt_row
               WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
                 AND receipt_row.signature_valid IS TRUE
                 AND receipt_row.provider_key IS NOT DISTINCT FROM v_source_event.provider_key
                 AND receipt_row.rail_env IS NOT DISTINCT FROM v_source_event.rail_env
                 AND pg_catalog.upper(coalesce(receipt_row.status, '')) IN (
                   'VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED'
                 )
             )
           )
         ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_AUTO_EVIDENCE_INVALID'
          USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'PAYMENT_CORRECTION_AUTO_EVIDENCE_INVALID',
            'source_bank_event_id', p_source_bank_event_id,
            'requested_action', v_action
          )::text;
      END IF;
    END IF;

    IF v_mode = 'EXPLICIT' THEN
      v_explicit_tokens := coalesce(
        p_selection_json#>'{selection,explicit_candidate_tokens}',
        p_selection_json->'explicit_candidate_tokens',
        p_selection_json->'pay_batch_candidate_ids',
        '[]'::jsonb
      );

      IF pg_catalog.jsonb_typeof(v_explicit_tokens) <> 'array' THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPLICIT_SELECTION_INVALID'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'DESCRIPTOR_INVALID')::text;
      END IF;

      IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(v_explicit_tokens) AS supplied_token(token_value)
        WHERE supplied_token.token_value
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPLICIT_SELECTION_INVALID'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'DESCRIPTOR_INVALID', 'reason', 'EXPLICIT_TOKEN_INVALID'
          )::text;
      END IF;

      SELECT pg_catalog.count(*)::integer,
             pg_catalog.count(DISTINCT token_value)::integer,
             coalesce(
               pg_catalog.jsonb_agg(token_value ORDER BY token_value),
               '[]'::jsonb
             )
      INTO v_requested_explicit_count, v_unique_explicit_count, v_canonical_explicit_tokens
      FROM (
        SELECT pg_catalog.lower(explicit_token.token_value) AS token_value
        FROM pg_catalog.jsonb_array_elements_text(v_explicit_tokens) AS explicit_token(token_value)
      ) AS canonical_tokens;

      IF v_requested_explicit_count <> pg_catalog.jsonb_array_length(v_explicit_tokens)
         OR v_requested_explicit_count < 1
         OR v_requested_explicit_count > v_max_candidates
         OR v_unique_explicit_count <> v_requested_explicit_count THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_EXPLICIT_SELECTION_INVALID'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'DESCRIPTOR_INVALID',
            'requested_explicit_count', v_requested_explicit_count,
            'maximum_candidate_count', v_max_candidates
          )::text;
      END IF;

      -- Boundary-independent ordered chain: final selection reconciliation can
      -- compare page summaries without rebuilding a 10,000-ID JSON value.
      v_requested_explicit_hash := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
          'version', 1, 'pay_batch_id', p_pay_batch_id, 'chain', 'EXPLICIT_IDS'
        )
      );
      FOR v_explicit_token IN
        SELECT token.value
        FROM pg_catalog.jsonb_array_elements_text(v_canonical_explicit_tokens) AS token(value)
        ORDER BY token.value
      LOOP
        v_requested_explicit_hash := private.pay_payment_correction_sha256_v1(
          pg_catalog.jsonb_build_object(
            'prior', v_requested_explicit_hash,
            'pay_batch_candidate_id', v_explicit_token
          )
        );
      END LOOP;
    END IF;

    v_active_scope_hash := private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'version', 2,
        'pay_batch_id', v_batch.id,
        'batch_status', v_batch.status,
        'total_bank_out_pence', pg_catalog.round(coalesce(v_batch.total_bank_out, 0) * 100)::bigint,
        'source_scope_change_generation', v_batch.source_scope_change_generation,
        'execution_commit_state', v_batch.execution_commit_state,
        'execution_commit_ref', v_batch.execution_commit_ref,
        'execution_committed_at_utc', v_batch.execution_committed_at_utc,
        'execution_intent_json', v_batch.execution_intent_json,
        'rail_provider_snapshot', v_batch.rail_provider_snapshot,
        'rail_env_snapshot', v_batch.rail_env_snapshot,
        'freshness_validation_status', v_batch.freshness_validation_status,
        'freshness_result_hash', v_batch.freshness_result_hash,
        'freshness_scope_hash', v_batch.freshness_scope_hash,
        'schedule_kind', v_batch.schedule_kind,
        'scheduled_at_utc', v_batch.scheduled_at_utc,
        'active_authorisation', (
          SELECT pg_catalog.jsonb_build_object(
            'auth_request_id', auth_row.id,
            'state', auth_row.state,
            'required_quantity', auth_row.required_quantity,
            'schedule_kind', auth_row.schedule_kind,
            'scheduled_at_utc', auth_row.scheduled_at_utc,
            'execution_intent_json', auth_row.execution_intent_json
          )
          FROM public.pay_batch_auth_requests AS auth_row
          WHERE auth_row.pay_batch_id = v_batch.id
            AND auth_row.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
          ORDER BY auth_row.created_at_utc DESC, auth_row.id DESC
          LIMIT 1
        ),
        'change_signal', (
          SELECT pg_catalog.jsonb_build_object(
            'version', coalesce(signal_row.version, 0),
            'payment_status_version', coalesce(signal_row.payment_status_version, 0),
            'correction_progress_version', coalesce(signal_row.correction_progress_version, 0),
            'overview_version', coalesce(signal_row.overview_version, 0),
            'last_changed_at_utc', signal_row.last_changed_at_utc
          )
          FROM public.banking_pay_batch_change_signals AS signal_row
          WHERE signal_row.pay_batch_id = v_batch.id
        ),
        'scope_version_authority', 'banking_pay_batch_change_signals'
      )
    );

    v_expected_snapshot_token := private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'version', 1,
        'active_batch_scope_hash', v_active_scope_hash,
        'filter', v_filter,
        'sort_key', v_sort_key,
        'sort_direction', v_sort_direction
      )
    );
    v_snapshot_token := coalesce(
      p_selection_json#>>'{selection,snapshot_token}', p_selection_json->>'snapshot_token',
      CASE WHEN v_action = 'DRAFT_CANCEL' OR coalesce(p_auto_requested, false)
           THEN v_expected_snapshot_token ELSE NULL END
    );

    IF v_snapshot_token IS NULL OR v_snapshot_token IS DISTINCT FROM v_expected_snapshot_token THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_SNAPSHOT_STALE'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'SELECTION_SNAPSHOT_STALE')::text;
    END IF;

    -- An untouched Draft cancellation is allowed to ignore only the dirtying
    -- caused by the cancellation request itself.  Capture the exact live
    -- candidate authority before the request/action/operation rows exist.
    -- Candidate advisory ownership prevents a genuine economic writer from
    -- racing this fence.  The later START_PREPARED call must prove this fence
    -- is still live before it performs any cancellation-control mutations.
    IF v_action = 'DRAFT_CANCEL' THEN
      FOR v_candidate_id IN
        SELECT DISTINCT batch_candidate.candidate_id
        FROM public.pay_batch_candidates AS batch_candidate
        WHERE batch_candidate.pay_batch_id = p_pay_batch_id
        ORDER BY batch_candidate.candidate_id
      LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
          pg_catalog.hashtextextended(
            public._pay_workbench_candidate_serial_key(v_candidate_id),
            24062027
          )
        );
      END LOOP;

      WITH authority_rows AS (
        SELECT
          batch_candidate.id AS pay_batch_candidate_id,
          batch_candidate.candidate_id,
          batch_row.source_workbench_session_id,
          batch_row.source_session_version,
          draft_operation.id AS draft_operation_id,
          draft_scope.allocation_basis_json->'post_draft_authority' AS post_draft_authority,
          COALESCE(candidate_counter.seq,0) AS live_source_change_seq,
          COALESCE(candidate_counter.scope_change_generation,0) AS live_dirty_generation,
          registry.current_source_change_seq AS registry_source_change_seq,
          registry.dirty_generation AS registry_dirty_generation,
          candidate_state.source_change_seq AS candidate_state_source_change_seq,
          candidate_state.session_version AS candidate_state_session_version
        FROM public.pay_batch_candidates AS batch_candidate
        JOIN public.pay_batches AS batch_row
          ON batch_row.id=batch_candidate.pay_batch_id
        LEFT JOIN LATERAL (
          SELECT operation_row.id
          FROM public.banking_pay_operations AS operation_row
          WHERE operation_row.operation_type='DRAFT_CREATE'
            AND operation_row.status='COMPLETE'
            AND (
              operation_row.pay_batch_id=batch_candidate.pay_batch_id
              OR EXISTS (
                SELECT 1
                FROM public.banking_pay_operation_candidate_scope AS operation_scope_link
                WHERE operation_scope_link.operation_id=operation_row.id
                  AND operation_scope_link.candidate_id=batch_candidate.candidate_id
                  AND operation_scope_link.pay_batch_id=batch_candidate.pay_batch_id
                  AND operation_scope_link.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
              )
            )
          ORDER BY operation_row.completed_at_utc DESC NULLS LAST,
                   operation_row.created_at_utc DESC
          LIMIT 1
        ) AS draft_operation ON true
        LEFT JOIN public.banking_pay_operation_candidate_scope AS draft_scope
          ON draft_scope.operation_id=draft_operation.id
         AND draft_scope.candidate_id=batch_candidate.candidate_id
         AND draft_scope.pay_batch_id=batch_candidate.pay_batch_id
         AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
        LEFT JOIN public.app_change_counters AS candidate_counter
          ON candidate_counter.entity_key='pay_candidate:'||batch_candidate.candidate_id::text
        LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
          ON registry.candidate_id=batch_candidate.candidate_id
        LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
          ON candidate_state.session_id=batch_row.source_workbench_session_id
         AND candidate_state.candidate_id=batch_candidate.candidate_id
        WHERE batch_candidate.pay_batch_id=p_pay_batch_id
      ), normalised AS (
        SELECT authority_rows.*,
          CASE WHEN COALESCE(post_draft_authority->>'source_change_seq','') ~ '^[0-9]{1,18}$'
            THEN (post_draft_authority->>'source_change_seq')::bigint ELSE NULL::bigint END
            AS frozen_source_change_seq,
          CASE WHEN COALESCE(post_draft_authority->>'dirty_generation','') ~ '^[0-9]{1,18}$'
            THEN (post_draft_authority->>'dirty_generation')::bigint ELSE NULL::bigint END
            AS frozen_dirty_generation
        FROM authority_rows
      ), classified AS (
        SELECT normalised.*,
          (
            COALESCE(post_draft_authority->>'contract_version','')='POST_DRAFT_LIVE_AUTHORITY_V2'
            AND COALESCE(post_draft_authority->>'draft_operation_id','')=draft_operation_id::text
            AND COALESCE(post_draft_authority->>'pay_batch_id','')=p_pay_batch_id::text
            AND COALESCE(post_draft_authority->>'workbench_session_id','')=source_workbench_session_id::text
            AND COALESCE(post_draft_authority->>'candidate_id','')=candidate_id::text
            AND COALESCE((post_draft_authority->>'fast_reversion_eligible')::boolean,false)
            AND COALESCE(post_draft_authority->>'original_source_publication_id','')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            AND frozen_source_change_seq IS NOT NULL
            AND frozen_dirty_generation IS NOT NULL
            AND live_source_change_seq=frozen_source_change_seq
            AND live_dirty_generation=frozen_dirty_generation
            AND registry_source_change_seq=live_source_change_seq
            AND registry_dirty_generation=live_dirty_generation
            AND candidate_state_source_change_seq=live_source_change_seq
            AND candidate_state_session_version=source_session_version
          ) AS pre_request_exact
        FROM normalised
      )
      SELECT COALESCE(pg_catalog.jsonb_object_agg(
        classified.candidate_id::text,
        pg_catalog.jsonb_build_object(
          'contract_version','DRAFT_OVERLAY_FAST_PRE_REQUEST_AUTHORITY_V1',
          'candidate_id',classified.candidate_id,
          'pay_batch_candidate_id',classified.pay_batch_candidate_id,
          'source_change_seq',classified.live_source_change_seq,
          'dirty_generation',classified.live_dirty_generation,
          'post_draft_authority_digest',classified.post_draft_authority->>'authority_digest',
          'original_source_publication_id',
            classified.post_draft_authority->>'original_source_publication_id',
          'fast_reversion_eligible',classified.pre_request_exact,
          'pre_request_exact',classified.pre_request_exact,
          'rejection_reason',CASE WHEN classified.pre_request_exact THEN NULL
            WHEN COALESCE((classified.post_draft_authority->>'fast_reversion_eligible')::boolean,false) IS NOT TRUE
              OR COALESCE(classified.post_draft_authority->>'original_source_publication_id','')
                   !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN 'LEGACY_PHYSICAL_PUBLICATION_MISSING'
            ELSE 'PRE_REQUEST_ECONOMIC_AUTHORITY_NOT_CURRENT' END,
          'fence_digest',pg_catalog.md5(
            classified.candidate_id::text||'|'||classified.live_source_change_seq::text||'|'||
            classified.live_dirty_generation::text||'|'||
            COALESCE(classified.post_draft_authority->>'authority_digest','')||'|'||
            COALESCE(classified.post_draft_authority->>'original_source_publication_id','')||'|'||
            COALESCE(classified.registry_source_change_seq::text,'')||'|'||
            COALESCE(classified.registry_dirty_generation::text,'')||'|'||
            COALESCE(classified.candidate_state_source_change_seq::text,'')||'|'||
            COALESCE(classified.candidate_state_session_version::text,'')||'|'||
            classified.pre_request_exact::text||'|DRAFT_OVERLAY_FAST_PRE_REQUEST_AUTHORITY_V1'
          )
        ) ORDER BY classified.candidate_id
      ),'{}'::jsonb)
      INTO v_draft_overlay_pre_request_authorities
      FROM classified;
    END IF;

    -- Scheduled/executed-not-submitted cancellation has a different safe
    -- baseline from an untouched Draft.  Prove, before the correction request
    -- writes anything, that the current certified source differs from the
    -- immutable Draft only by the closed unsent-payment overlay.  Explicit
    -- pages are bounded to 100 candidates; larger/all-matching requests retain
    -- the safe fallback until the operation's bounded page owner captures the
    -- same proof per page.
    IF COALESCE(v_scheduled_reversion_v2_observe_enabled,false)
       AND v_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
       AND v_mode='EXPLICIT'
       AND v_requested_explicit_count BETWEEN 1 AND 100 THEN
      v_cancel_reversion_pre_request_proof :=
        private.pay_workbench_cancel_reversion_proof_core_v1(
          NULL::uuid,NULL::uuid,NULL::uuid,ARRAY[]::uuid[],'PRE_REQUEST',
          pg_catalog.jsonb_build_object(
            'pay_batch_id',p_pay_batch_id,
            'candidate_ids',COALESCE((
              SELECT pg_catalog.jsonb_agg(batch_candidate.candidate_id ORDER BY batch_candidate.candidate_id)
              FROM public.pay_batch_candidates AS batch_candidate
              WHERE batch_candidate.pay_batch_id=p_pay_batch_id
                AND batch_candidate.id::text IN (
                  SELECT explicit_token.value
                  FROM pg_catalog.jsonb_array_elements_text(v_canonical_explicit_tokens)
                    AS explicit_token(value)
                )
            ),'[]'::jsonb)
          )
        );

      SELECT COALESCE(pg_catalog.jsonb_object_agg(
        result_row.value->>'candidate_id',
        pg_catalog.jsonb_build_object(
          'contract_version',COALESCE(result_row.value->>'contract_version',
            'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3'),
          'candidate_id',result_row.value->>'candidate_id',
          'pay_batch_candidate_id',result_row.value->>'pay_batch_candidate_id',
          'source_change_seq',result_row.value->>'source_change_seq',
          'dirty_generation',result_row.value->>'dirty_generation',
          'original_economic_build_id',result_row.value->>'original_economic_build_id',
          'current_economic_build_id',result_row.value->>'current_economic_build_id',
          'original_source_publication_id',result_row.value->>'original_source_publication_id',
          'current_source_publication_id',result_row.value->>'current_source_publication_id',
          'invariant_economic_digest',result_row.value->>'invariant_economic_digest',
          'currentness_basis',result_row.value->>'currentness_basis',
          'execution_overlay_authority',result_row.value->'execution_overlay_authority',
          'pre_request_exact',COALESCE((result_row.value->>'admitted')::boolean,false),
          'fast_reversion_eligible',COALESCE((result_row.value->>'admitted')::boolean,false),
          'rejection_reason',result_row.value->>'rejection_reason',
          'authority_digest',result_row.value->>'authority_digest'
        )
      ),'{}'::jsonb)
      INTO v_cancel_reversion_pre_request_authorities_v2
      FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_cancel_reversion_pre_request_proof->'candidate_results','[]'::jsonb)
      ) AS result_row(value);
    END IF;

    v_selection := p_selection_json || pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'mode', v_mode,
      'requested_action', v_action,
      'filter_json', v_filter,
      'sort_key', v_sort_key,
      'sort_direction', v_sort_direction,
      'snapshot_token', v_snapshot_token,
      'scope_fence_hash', v_active_scope_hash,
      'requested_explicit_count', v_requested_explicit_count,
      'requested_explicit_hash', v_requested_explicit_hash,
      'draft_overlay_fast_pre_request_authorities',
        CASE WHEN v_action='DRAFT_CANCEL'
          THEN v_draft_overlay_pre_request_authorities ELSE '{}'::jsonb END,
      'cancellation_reversion_pre_request_authorities_v2',
        CASE WHEN v_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
          THEN v_cancel_reversion_pre_request_authorities_v2 ELSE '{}'::jsonb END,
      'cancellation_reversion_pre_request_authorities_v3',
        CASE WHEN v_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
          THEN v_cancel_reversion_pre_request_authorities_v2 ELSE '{}'::jsonb END,
      'canonical_explicit_candidate_tokens', CASE
        WHEN v_mode = 'EXPLICIT' THEN v_canonical_explicit_tokens ELSE '[]'::jsonb END,
      'selection', coalesce(p_selection_json->'selection', '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'mode', v_mode,
        'action', v_action,
        'filter_json', v_filter,
        'sort_key', v_sort_key,
        'sort_direction', v_sort_direction,
        'snapshot_token', v_snapshot_token,
        'scope_fence_hash', v_active_scope_hash,
        'explicit_candidate_tokens', CASE WHEN v_mode = 'EXPLICIT' THEN v_canonical_explicit_tokens ELSE '[]'::jsonb END,
        'requested_explicit_count', v_requested_explicit_count,
        'requested_explicit_hash', v_requested_explicit_hash
      )
    );
    -- The pre-request authority is database-derived runtime evidence, not
    -- caller intent.  Keep it outside the descriptor/idempotency identity so
    -- a lost PREPARE response reuses the original request and its original
    -- fence instead of creating a second request after request-owned dirtying.
    v_descriptor_hash := private.pay_payment_correction_sha256_v1(
      v_selection - 'command' - 'draft_overlay_fast_pre_request_authorities'
        - 'cancellation_reversion_pre_request_authorities_v2'
        - 'cancellation_reversion_pre_request_authorities_v3'
    );
    v_correction_kind := CASE WHEN v_action IN ('NO_MONEY_RELEASE', 'NO_MONEY_UNWIND')
                              THEN 'NO_MONEY_UNWIND' ELSE 'PRE_BANK_CANCEL' END;
    v_idempotency_key := coalesce(NULLIF(v_selection->>'idempotency_key', ''),
      'payment-correction:' || p_pay_batch_id::text || ':' || v_descriptor_hash);
    v_reason_hash := private.pay_payment_correction_sha256_v1(
      coalesce(
        pg_catalog.to_jsonb(NULLIF(pg_catalog.btrim(p_reason), '')),
        'null'::jsonb
      )
    );
    v_evidence_hash := CASE
      WHEN p_source_bank_event_id IS NULL THEN NULL
      ELSE private.pay_payment_correction_sha256_v1(pg_catalog.to_jsonb(p_source_bank_event_id))
    END;
    v_outcome_hash := CASE
      WHEN p_accepted_resolution_json IS NULL THEN NULL
      ELSE private.pay_payment_correction_sha256_v1(p_accepted_resolution_json)
    END;

    SELECT existing_request.*
    INTO v_request
    FROM public.pay_payment_correction_requests AS existing_request
    WHERE existing_request.pay_batch_id = p_pay_batch_id
      AND existing_request.plan_json->>'idempotency_key' = v_idempotency_key
    ORDER BY existing_request.created_at_utc
    LIMIT 1;

    IF FOUND THEN
      IF v_request.plan_json ->> 'descriptor_hash' IS DISTINCT FROM v_descriptor_hash
         OR v_request.correction_kind IS DISTINCT FROM v_correction_kind
         OR v_request.plan_json ->> 'requested_action' IS DISTINCT FROM v_action
         OR v_request.plan_json ->> 'reason_hash' IS DISTINCT FROM v_reason_hash
         OR v_request.plan_json ->> 'evidence_hash' IS DISTINCT FROM v_evidence_hash
         OR v_request.plan_json ->> 'outcome_hash' IS DISTINCT FROM v_outcome_hash THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_IDEMPOTENCY_CONFLICT'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'IDEMPOTENCY_CONFLICT',
            'correction_request_id', v_request.id,
            'idempotency_key', v_idempotency_key
          )::text;
      END IF;

      SELECT operation_row.id INTO v_operation_id
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
        AND operation_row.input_json->>'correction_request_id' = v_request.id::text
      ORDER BY operation_row.created_at_utc LIMIT 1;
      RETURN pg_catalog.jsonb_build_object(
        'ok', true, 'existing_request', true, 'is_existing', true, 'correction_request_id', v_request.id,
        'operation_id', v_operation_id, 'request_status', v_request.status,
        'operation_status', (SELECT operation_row.status FROM public.banking_pay_operations AS operation_row WHERE operation_row.id = v_operation_id),
        'phase', (SELECT operation_row.phase FROM public.banking_pay_operations AS operation_row WHERE operation_row.id = v_operation_id),
        'selection_ready', v_request.status <> 'PLANNING',
        'gate_active', v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING'),
        'approved_count', coalesce(v_request.approved_count, 0),
        'required_quantity', greatest(coalesce(v_request.required_quantity, 1), 1),
        'requires_reauthentication', v_request.status = 'PLANNED' AND coalesce(v_request.auto_requested, false) IS NOT TRUE,
        'requires_authorisation', v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION'),
        'display_status', CASE WHEN v_request.status = 'PLANNING' THEN 'Preparing payment selection' ELSE 'Cancellation request already exists' END,
        'display_message', 'CloudTMS returned the existing request for this exact idempotency contract.',
        'continuation', pg_catalog.jsonb_build_object(
          'required', v_request.status = 'PLANNING', 'operation_id', v_operation_id,
          'operation_type', 'PAYMENT_CORRECTION', 'pay_batch_id', v_request.pay_batch_id,
          'root_operation_id', NULL, 'phase', (SELECT operation_row.phase FROM public.banking_pay_operations AS operation_row WHERE operation_row.id = v_operation_id),
          'run_after_utc', (SELECT operation_row.run_after_utc FROM public.banking_pay_operations AS operation_row WHERE operation_row.id = v_operation_id),
          'reason', 'PAYMENT_CORRECTION_PREPARE', 'successor_relation', CASE WHEN v_request.status = 'PLANNING' THEN 'SELF' ELSE 'NONE' END,
          'requires_user_action', v_request.status <> 'PLANNING', 'terminal', v_request.status IN ('APPLIED','APPLIED_WITH_BLOCKERS','BLOCKED','FAILED','REJECTED','CANCELLED')
        ),
        'code', 'PAYMENT_CORRECTION_REQUEST_EXISTING'
      );
    END IF;

    v_request_id := extensions.gen_random_uuid();
    v_plan_json := pg_catalog.jsonb_build_object(
      'contract_version', 1, 'descriptor_hash', v_descriptor_hash,
      'active_batch_scope_hash', v_active_scope_hash, 'requested_action', v_action,
      'scope_fence_hash', v_active_scope_hash,
      'requested_explicit_count', v_requested_explicit_count,
      'requested_explicit_hash', v_requested_explicit_hash,
      'snapshot_token', v_snapshot_token, 'idempotency_key', v_idempotency_key,
      'reason_hash', v_reason_hash,
      'evidence_hash', v_evidence_hash,
      'outcome_hash', v_outcome_hash,
      'approval_expires_at_utc', v_now + interval '24 hours'
    );
    v_plan_hash := private.pay_payment_correction_sha256_v1(v_plan_json);

    INSERT INTO public.pay_payment_correction_requests (
      id, pay_batch_id, correction_kind, status, requested_by_user_id, requested_at_utc,
      required_quantity, approved_count, golden_key_used, reason, selection_json,
      selection_hash, plan_json, plan_hash, accepted_resolution_json,
      accepted_resolution_hash, source_bank_event_id, auto_requested, created_at_utc, updated_at_utc
    ) VALUES (
      v_request_id, p_pay_batch_id, v_correction_kind, 'PLANNING',
      CASE WHEN coalesce(p_auto_requested, false) THEN NULL ELSE p_actor_user_id END,
      v_now, v_required_quantity, 0, false, NULLIF(pg_catalog.btrim(p_reason), ''), v_selection,
      v_descriptor_hash, v_plan_json, v_plan_hash, p_accepted_resolution_json,
      CASE WHEN p_accepted_resolution_json IS NULL THEN NULL ELSE private.pay_payment_correction_sha256_v1(p_accepted_resolution_json) END,
      p_source_bank_event_id, coalesce(p_auto_requested, false), v_now, v_now
    ) RETURNING * INTO v_request;

    SELECT pg_catalog.to_jsonb(start_result), start_result.operation_id
    INTO v_operation_result, v_operation_id
    FROM public.banking_pay_operation_start(
      'PAYMENT_CORRECTION', p_actor_user_id, v_idempotency_key, NULL::uuid,
      p_pay_batch_id, NULL::uuid,
      pg_catalog.jsonb_build_object(
        'correction_request_id', v_request_id,
        'requested_action', v_action,
        'auto_requested', coalesce(p_auto_requested, false),
        'source_bank_event_id', p_source_bank_event_id
      ),
      pg_catalog.jsonb_build_object('contract_version', 1)
    ) AS start_result
    LIMIT 1;

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
      action_at_utc, note, before_json, after_json, metadata_json
    ) VALUES (
      v_request_id, p_pay_batch_id,
      CASE WHEN coalesce(p_auto_requested, false) THEN 'SYSTEM' ELSE 'USER' END,
      CASE WHEN coalesce(p_auto_requested, false) THEN NULL ELSE p_actor_user_id END,
      'REQUEST', v_now, NULLIF(pg_catalog.btrim(p_reason), ''), NULL, pg_catalog.to_jsonb(v_request),
      pg_catalog.jsonb_build_object('descriptor_hash', v_descriptor_hash, 'operation_id', v_operation_id, 'planning_only', true)
    );

    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'existing_request', false, 'is_existing', false, 'correction_request_id', v_request_id,
      'operation_id', v_operation_id, 'request_status', 'PLANNING',
      'operation_status', coalesce(v_operation_result->>'status', 'RUNNING'),
      'phase', 'PREPARE_SELECTION',
      'selection_ready', false, 'gate_active', false, 'approved_count', 0,
      'required_quantity', v_required_quantity,
      'requires_reauthentication', false, 'requires_authorisation', false,
      'display_status', 'Preparing payment selection',
      'display_message', 'CloudTMS is preparing the exact payment selection for review.',
      'continuation', pg_catalog.jsonb_build_object(
        'required', true, 'operation_id', v_operation_id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', p_pay_batch_id, 'root_operation_id', NULL, 'phase', 'PREPARE_SELECTION',
        'run_after_utc', v_now, 'reason', 'PAYMENT_CORRECTION_PREPARE', 'successor_relation', 'SELF',
        'requires_user_action', false, 'terminal', false
      ),
      'code', 'PAYMENT_CORRECTION_PLANNING_STARTED'
    );
  END IF;

  v_request_id := NULLIF(p_selection_json->>'correction_request_id', '')::uuid;
  IF v_request_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  SELECT request_row.* INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = v_request_id AND request_row.pay_batch_id = p_pay_batch_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  v_proof_hash := NULLIF(p_selection_json->>'proof_hash', '');
  v_resume_reauthenticated_request :=
    v_command = 'START_PREPARED'
    AND coalesce(v_request.auto_requested, false) IS NOT TRUE
    AND v_request.status IN ('REQUESTED', 'AWAITING_AUTHORISATION')
    AND v_request.requested_by_user_id IS NOT DISTINCT FROM p_actor_user_id
    AND greatest(coalesce(v_request.required_quantity, 1), 1) = 1
    AND coalesce(v_request.approved_count, 0) = 0
    AND v_request.reauth_consumed_at_utc IS NOT NULL
    AND v_request.reauth_proof_hash IS NOT DISTINCT FROM v_proof_hash
    AND coalesce(v_request.plan_json->>'requested_action', '') IN (
      'DRAFT_CANCEL', 'PRE_BANK_CANCEL', 'CANCEL_PAYMENT',
      'NO_MONEY_RELEASE', 'NO_MONEY_UNWIND'
    );

  -- Recheck the pre-request fence before START_PREPARED performs any
  -- cancellation-owned updates.  This catches a genuine economic change
  -- during the user's reauthentication interval.  The result remains
  -- candidate-specific so mixed batches can safely fall back per candidate.
  IF v_command='START_PREPARED'
     AND COALESCE(v_request.plan_json->>'requested_action','') IN (
       'DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT'
     )
     AND (
       COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL'
       OR COALESCE(v_scheduled_reversion_v2_observe_enabled,false)
     ) THEN
    FOR v_candidate_id IN
      SELECT DISTINCT batch_candidate.candidate_id
      FROM public.pay_payment_correction_request_candidates AS request_candidate
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=request_candidate.pay_batch_candidate_id
      WHERE request_candidate.correction_request_id=v_request_id
      ORDER BY batch_candidate.candidate_id
    LOOP
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          public._pay_workbench_candidate_serial_key(v_candidate_id),
          24062027
        )
      );
    END LOOP;

    WITH selected_candidates AS (
      SELECT batch_candidate.candidate_id,
             CASE
               WHEN COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL'
                 THEN v_request.selection_json->'draft_overlay_fast_pre_request_authorities'
                        ->batch_candidate.candidate_id::text
                ELSE COALESCE(
                  v_request.selection_json->'cancellation_reversion_pre_request_authorities_v3'
                    ->batch_candidate.candidate_id::text,
                  v_request.selection_json->'cancellation_reversion_pre_request_authorities_v2'
                    ->batch_candidate.candidate_id::text
                )
             END AS pre_request_authority,
             COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL' AS is_draft_overlay,
             COALESCE(candidate_counter.seq,0) AS live_source_change_seq,
             COALESCE(candidate_counter.scope_change_generation,0) AS live_dirty_generation,
             request_owned_dirty.job_id AS request_owned_dirty_job_id
      FROM public.pay_payment_correction_request_candidates AS request_candidate
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=request_candidate.pay_batch_candidate_id
      LEFT JOIN public.app_change_counters AS candidate_counter
        ON candidate_counter.entity_key='pay_candidate:'||batch_candidate.candidate_id::text
      LEFT JOIN LATERAL (
        SELECT dirty_job.id AS job_id
        FROM public.banking_pay_workbench_jobs AS dirty_job
        WHERE dirty_job.candidate_id=batch_candidate.candidate_id
          -- Finance/correction transition dirty jobs are canonical
          -- candidate-global owners and therefore legitimately carry a NULL
          -- session_id.  Session-scoped recovery jobs must still match the
          -- Draft's source Workbench session exactly.
          AND (
            dirty_job.session_id IS NULL
            OR dirty_job.session_id=v_batch.source_workbench_session_id
          )
          AND dirty_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
          AND (
            dirty_job.status IN ('QUEUED','RUNNING')
            OR (
              dirty_job.status='SUCCEEDED'
              AND COALESCE(
                (dirty_job.payload_json->>'coalesced_to_current_refresh_authority')::boolean,
                false
              )
              AND COALESCE(dirty_job.payload_json->>'coalesced_owner_resolution','')
                    ='COMPLETE_CURRENT_AUTHORITY'
              AND COALESCE(dirty_job.payload_json->>'actual_refresh_scope_status','')
                    ='MATERIALISED'
            )
          )
          -- The canonical dirty job can be reused across merged invalidations.
          -- Use the time it last received durable payload, not only its original
          -- creation time, after the exact causal request/token proof below.
          AND GREATEST(
                dirty_job.created_at_utc,
                COALESCE(dirty_job.updated_at_utc,dirty_job.created_at_utc)
              )>=v_request.created_at_utc
          AND dirty_job.scope_change_generation=COALESCE(candidate_counter.scope_change_generation,0)
          AND COALESCE(dirty_job.payload_json->>'source_change_seq','')
                =COALESCE(candidate_counter.seq,0)::text
          AND COALESCE((dirty_job.payload_json->>'policy_x_dirtying_only')::boolean,false)
          AND COALESCE((dirty_job.payload_json->>'economic_truth_mutation_allowed')::boolean,true) IS FALSE
          AND (
            (
              pg_catalog.jsonb_typeof(COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb))='array'
              AND pg_catalog.jsonb_array_length(COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb))>0
              AND NOT EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements_text(
                  COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb)
                ) AS dirty_reason(value)
                WHERE pg_catalog.upper(pg_catalog.btrim(dirty_reason.value)) NOT IN (
                  'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
                  'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE',
                  'DIRTY_TRIGGER:PAY_BATCHES:UPDATE'
                )
              )
            )
            OR (
              COALESCE(dirty_job.payload_json->>'correction_dirty_causal_contract_version','')
                ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
              AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
                    ->batch_candidate.candidate_id::text->>'correction_request_id','')
                    =v_request_id::text
              AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
                    ->batch_candidate.candidate_id::text->>'pay_batch_id','')
                    =v_request.pay_batch_id::text
              AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
                    =COALESCE(dirty_job.payload_json->>'scope_change_tx_token','')
            )
          )
        ORDER BY dirty_job.created_at_utc,dirty_job.id
        LIMIT 1
      ) AS request_owned_dirty ON true
      WHERE request_candidate.correction_request_id=v_request_id
    ), classified AS (
      SELECT selected_candidates.*,
        (
          CASE WHEN is_draft_overlay THEN
            COALESCE(pre_request_authority->>'contract_version','')='DRAFT_OVERLAY_FAST_PRE_REQUEST_AUTHORITY_V1'
          ELSE COALESCE(pre_request_authority->>'contract_version','') IN (
            'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
            'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3') END
          AND COALESCE(pre_request_authority->>'candidate_id','')=candidate_id::text
          AND COALESCE((pre_request_authority->>'pre_request_exact')::boolean,false)
          AND COALESCE(pre_request_authority->>'source_change_seq','') ~ '^[0-9]{1,18}$'
          AND COALESCE(pre_request_authority->>'dirty_generation','') ~ '^[0-9]{1,18}$'
          AND (
            (
              live_source_change_seq=(pre_request_authority->>'source_change_seq')::bigint
              AND live_dirty_generation=(pre_request_authority->>'dirty_generation')::bigint
            )
            OR request_owned_dirty_job_id IS NOT NULL
          )
        ) AS start_exact
      FROM selected_candidates
    )
    SELECT COALESCE(pg_catalog.jsonb_object_agg(
      classified.candidate_id::text,
      pg_catalog.jsonb_build_object(
        'candidate_id',classified.candidate_id,
        'start_exact',classified.start_exact,
        'rejection_reason',CASE WHEN classified.start_exact THEN NULL
          ELSE 'ECONOMIC_AUTHORITY_CHANGED_BEFORE_CANCELLATION_START' END,
        'pre_request_fence_digest',COALESCE(
          classified.pre_request_authority->>'fence_digest',
          classified.pre_request_authority->>'authority_digest'
        ),
        'request_owned_dirty_job_id',classified.request_owned_dirty_job_id,
        'request_owned_dirty_proven',classified.request_owned_dirty_job_id IS NOT NULL
      ) ORDER BY classified.candidate_id
    ),'{}'::jsonb)
    INTO v_draft_overlay_start_admission
    FROM classified;
  END IF;

  IF v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING')
     AND coalesce(v_resume_reauthenticated_request, false) IS NOT TRUE
     AND (
       (
         v_command = 'START_AUTO'
         AND coalesce(v_request.auto_requested, false)
         AND v_request.source_bank_event_id IS NOT NULL
       )
       OR (
         v_request.reauth_consumed_at_utc IS NOT NULL
         AND v_request.reauth_proof_hash IS NOT DISTINCT FROM v_proof_hash
       )
     ) THEN
    SELECT operation_row.* INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
      AND operation_row.input_json->>'correction_request_id' = v_request_id::text
    ORDER BY operation_row.created_at_utc LIMIT 1;
    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'is_existing', true, 'correction_request_id', v_request_id, 'operation_id', v_operation.id,
      'request_status', v_request.status, 'operation_status', v_operation.status,
      'phase', v_operation.phase,
      'selection_ready', true, 'gate_active', true,
      'approved_count', coalesce(v_request.approved_count, 0),
      'required_quantity', greatest(coalesce(v_request.required_quantity, 1), 1),
      'requires_reauthentication', false,
      'requires_authorisation', v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION'),
      'display_status', 'Cancellation request already started',
      'display_message', 'CloudTMS returned the already-committed cancellation request.',
      'continuation', pg_catalog.jsonb_build_object(
        'required', v_request.status IN ('AUTHORISED','EXPANDED','PROCESSING'),
        'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', v_operation.phase, 'run_after_utc', v_operation.run_after_utc,
        'reason', 'PAYMENT_CORRECTION_ALREADY_STARTED',
        'successor_relation', CASE WHEN v_request.status IN ('AUTHORISED','EXPANDED','PROCESSING') THEN 'SELF' ELSE 'NONE' END,
        'requires_user_action', v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION'),
        'terminal', v_request.status IN ('APPLIED','APPLIED_WITH_BLOCKERS','BLOCKED','FAILED','REJECTED','CANCELLED')
      ),
      'code', 'REQUEST_ALREADY_STARTED'
    );
  END IF;

  IF coalesce(v_resume_reauthenticated_request, false) IS NOT TRUE THEN
    v_mutation_guard := private.pay_payment_mutation_guard_v1(p_pay_batch_id, NULL::uuid, 'NEW_PAYMENT_ACTION');
    IF coalesce((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION '%', coalesce(v_mutation_guard->>'code', 'PAYMENT_CHANGE_IN_PROGRESS')
        USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
    END IF;
  END IF;

  SELECT request_row.* INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = v_request_id AND request_row.pay_batch_id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  SELECT batch_row.* INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND')::text;
  END IF;

  IF pg_catalog.upper(pg_catalog.btrim(coalesce(v_batch.status, ''))) IN (
    'COMMITTED', 'COMPLETED', 'PAID', 'SETTLED', 'CANCELLED', 'CANCELED'
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_BATCH_TERMINAL'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_BATCH_TERMINAL',
        'batch_status', v_batch.status
      )::text;
  END IF;

  SELECT operation_row.* INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND operation_row.input_json->>'correction_request_id' = v_request_id::text
  ORDER BY operation_row.created_at_utc LIMIT 1
  FOR UPDATE;

  IF v_operation.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_STATE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_STATE_INVALID')::text;
  END IF;

  IF v_request.status IS DISTINCT FROM 'PLANNED'
     AND NOT coalesce(v_resume_reauthenticated_request, false) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_STATE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_STATE_INVALID')::text;
  END IF;

  v_active_scope_hash := private.pay_payment_correction_sha256_v1(
    pg_catalog.jsonb_build_object(
      'version', 2,
      'pay_batch_id', v_batch.id,
      'batch_status', v_batch.status,
      'total_bank_out_pence', pg_catalog.round(coalesce(v_batch.total_bank_out, 0) * 100)::bigint,
      'source_scope_change_generation', v_batch.source_scope_change_generation,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', v_batch.execution_committed_at_utc,
      'execution_intent_json', v_batch.execution_intent_json,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot,
      'rail_env_snapshot', v_batch.rail_env_snapshot,
      'freshness_validation_status', v_batch.freshness_validation_status,
      'freshness_result_hash', v_batch.freshness_result_hash,
      'freshness_scope_hash', v_batch.freshness_scope_hash,
      'schedule_kind', v_batch.schedule_kind,
      'scheduled_at_utc', v_batch.scheduled_at_utc,
      'active_authorisation', (
        SELECT pg_catalog.jsonb_build_object(
          'auth_request_id', auth_row.id,
          'state', auth_row.state,
          'required_quantity', auth_row.required_quantity,
          'schedule_kind', auth_row.schedule_kind,
          'scheduled_at_utc', auth_row.scheduled_at_utc,
          'execution_intent_json', auth_row.execution_intent_json
        )
        FROM public.pay_batch_auth_requests AS auth_row
        WHERE auth_row.pay_batch_id = v_batch.id
          AND auth_row.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
        ORDER BY auth_row.created_at_utc DESC, auth_row.id DESC
        LIMIT 1
      ),
      'change_signal', (
        SELECT pg_catalog.jsonb_build_object(
          'version', coalesce(signal_row.version, 0),
          'payment_status_version', coalesce(signal_row.payment_status_version, 0),
          'correction_progress_version', coalesce(signal_row.correction_progress_version, 0),
          'overview_version', coalesce(signal_row.overview_version, 0),
          'last_changed_at_utc', signal_row.last_changed_at_utc
        )
        FROM public.banking_pay_batch_change_signals AS signal_row
        WHERE signal_row.pay_batch_id = v_batch.id
      ),
      'scope_version_authority', 'banking_pay_batch_change_signals'
    )
  );

  IF v_request.plan_json ->> 'active_batch_scope_hash'
       IS DISTINCT FROM v_active_scope_hash THEN
    UPDATE public.pay_payment_correction_requests AS stale_request
    SET status = 'CANCELLED',
        cancelled_at_utc = v_now,
        reauth_proof_hash = NULL,
        reauth_expires_at_utc = NULL,
        reauth_consumed_at_utc = NULL,
        updated_at_utc = v_now,
        plan_json = coalesce(stale_request.plan_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'stale_code', 'SELECTION_SCOPE_CHANGED',
            'observed_active_batch_scope_hash', v_active_scope_hash
          )
    WHERE stale_request.id = v_request_id;

    UPDATE public.banking_pay_operations AS stale_operation
    SET status = 'CANCELLED',
        phase = 'COMPLETE',
        runner_state = 'CANCELLED',
        requires_user_action = false,
        result_json = coalesce(stale_operation.result_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'code', 'SELECTION_SCOPE_CHANGED',
            'active_batch_scope_hash', v_active_scope_hash
          ),
        completed_at_utc = v_now,
        run_after_utc = NULL,
        lease_owner = NULL,
        lease_expires_at_utc = NULL,
        locked_by = NULL,
        lock_expires_at_utc = NULL,
        updated_at_utc = v_now
    WHERE stale_operation.id = v_operation.id;

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
      action_at_utc, note, before_json, after_json, metadata_json
    ) VALUES (
      v_request_id,
      p_pay_batch_id,
      CASE WHEN v_command = 'START_AUTO' THEN 'SYSTEM' ELSE 'USER' END,
      CASE WHEN v_command = 'START_AUTO' THEN NULL ELSE p_actor_user_id END,
      'CANCEL',
      v_now,
      'The reviewed payment scope changed before the correction gate was installed.',
      pg_catalog.jsonb_build_object(
        'active_batch_scope_hash', v_request.plan_json ->> 'active_batch_scope_hash'
      ),
      pg_catalog.jsonb_build_object('active_batch_scope_hash', v_active_scope_hash),
      pg_catalog.jsonb_build_object('code', 'SELECTION_SCOPE_CHANGED')
    );

    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'is_existing', true,
      'correction_request_id', v_request_id,
      'operation_id', v_operation.id,
      'request_status', 'CANCELLED',
      'operation_status', 'CANCELLED',
      'phase', 'COMPLETE',
      'selection_ready', false, 'gate_active', false,
      'approved_count', coalesce(v_request.approved_count, 0),
      'required_quantity', greatest(coalesce(v_request.required_quantity, 1), 1),
      'requires_reauthentication', false, 'requires_authorisation', false,
      'display_status', 'Payment status changed',
      'display_message', 'Payment status changed. Refresh and select the payments again.',
      'continuation', pg_catalog.jsonb_build_object(
        'required', false, 'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
        'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
        'phase', 'COMPLETE', 'run_after_utc', NULL, 'reason', 'SELECTION_SCOPE_CHANGED',
        'successor_relation', 'NONE', 'requires_user_action', true, 'terminal', true
      ),
      'code', 'SELECTION_SCOPE_CHANGED',
      'message', 'Payment status changed. Refresh and select the payments again.'
    );
  END IF;

  IF v_command = 'START_AUTO' THEN
    SELECT coalesce(settings_row.banking_pay_auto_unwind_terminal_no_money, false)
    INTO v_auto_unwind_enabled
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    SELECT event_row.*
    INTO v_source_event
    FROM public.pay_bank_transfer_events AS event_row
    WHERE event_row.id = v_request.source_bank_event_id
      AND event_row.pay_batch_id = v_batch.id;

    v_auto_classification_result := public._pay_payment_movement_classify(
      v_batch.id,
      v_request.selection_json
    );

    v_existing_money_moved := false;
    IF v_source_event.pay_bank_transfer_id IS NOT NULL THEN
      SELECT coalesce(movement_state.is_final_money_moved, false)
      INTO v_existing_money_moved
      FROM public.pay_bank_transfers AS transfer_row
      CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
        transfer_row.status,
        transfer_row.rail_state,
        coalesce(transfer_row.rail_meta_json, '{}'::jsonb),
        coalesce(transfer_row.rail_meta_json, '{}'::jsonb)
      ) AS movement_state
      WHERE transfer_row.id = v_source_event.pay_bank_transfer_id
      LIMIT 1;

      v_existing_money_moved := coalesce(v_existing_money_moved, false) OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS paid_event
        WHERE paid_event.pay_bank_transfer_id = v_source_event.pay_bank_transfer_id
          AND paid_event.id IS DISTINCT FROM v_source_event.id
          AND paid_event.normalised_state IN ('COMPLETED', 'PAID', 'SETTLED')
      );
    END IF;

    IF coalesce(v_request.auto_requested, false) IS NOT TRUE
       OR v_request.source_bank_event_id IS NULL
       OR v_request.selection_json->>'requested_action' IS DISTINCT FROM 'NO_MONEY_UNWIND'
       OR coalesce(v_auto_unwind_enabled, false) IS NOT TRUE
       OR v_source_event.id IS NULL
       OR v_source_event.pay_bank_transfer_id IS NULL
       OR v_source_event.event_source NOT IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
       OR v_source_event.provider_event_transport NOT IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
       OR v_source_event.mapping_status IS DISTINCT FROM 'MATCHED'
       OR v_source_event.mapping_method NOT IN (
         'TRANSFER_ID', 'PROVIDER_EVENT_ID', 'PROVIDER_TRANSACTION_ID', 'REQUEST_ID',
         'PROVIDER_REFERENCE', 'RAIL_TX_ID', 'MATCHED_PROVIDER_EVENT', 'MANUAL_TRANSFER_SELECTION'
       )
       OR v_source_event.normalised_state NOT IN ('FAILED', 'REJECTED', 'CANCELLED')
       OR v_source_event.correction_disposition IS DISTINCT FROM 'AUTO_PROCESSING'
       OR coalesce((v_auto_classification_result->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
       OR (
         v_auto_classification_result->>'classification' NOT IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
         AND v_auto_classification_result->>'recommended_action' IS DISTINCT FROM 'NO_MONEY_UNWIND_AND_RECALCULATE'
       )
       OR coalesce(v_existing_money_moved, false)
       OR pg_catalog.jsonb_typeof(v_request.accepted_resolution_json) IS DISTINCT FROM 'object'
       OR v_request.accepted_resolution_json->>'contract_version' IS DISTINCT FROM '2'
       OR v_request.accepted_resolution_json->>'requested_action' IS DISTINCT FROM 'NO_MONEY_UNWIND'
       OR v_request.accepted_resolution_json->>'source_bank_event_id' IS DISTINCT FROM v_source_event.id::text
       OR v_request.accepted_resolution_json->>'source' IS DISTINCT FROM v_source_event.provider_event_transport
       OR v_request.accepted_resolution_json->>'event_source' IS DISTINCT FROM v_source_event.event_source
       OR v_request.accepted_resolution_json->>'provider_key' IS DISTINCT FROM v_source_event.provider_key
       OR v_request.accepted_resolution_json->>'provider_event_id' IS DISTINCT FROM v_source_event.provider_event_id
       OR v_request.accepted_resolution_json->>'provider_event_key' IS DISTINCT FROM v_source_event.provider_event_key
       OR v_request.accepted_resolution_json->>'provider_webhook_receipt_id'
            IS DISTINCT FROM (CASE WHEN v_source_event.provider_webhook_receipt_id IS NULL THEN NULL ELSE v_source_event.provider_webhook_receipt_id::text END)
       OR v_request.accepted_resolution_json->>'provider_transaction_id' IS DISTINCT FROM v_source_event.provider_transaction_id
       OR v_request.accepted_resolution_json->>'provider_request_id' IS DISTINCT FROM v_source_event.provider_request_id
       OR v_request.accepted_resolution_json->>'mapping_status' IS DISTINCT FROM v_source_event.mapping_status
       OR v_request.accepted_resolution_json->>'mapping_method' IS DISTINCT FROM v_source_event.mapping_method
       OR v_request.accepted_resolution_json->>'normalised_state' IS DISTINCT FROM v_source_event.normalised_state
       OR v_request.accepted_resolution_json->>'classification' IS DISTINCT FROM v_auto_classification_result->>'classification'
       OR v_request.accepted_resolution_json->>'recommended_action' IS DISTINCT FROM v_auto_classification_result->>'recommended_action'
       OR coalesce((v_request.accepted_resolution_json->>'safe_to_auto_apply')::boolean, false) IS NOT TRUE
       OR v_request.accepted_resolution_json->>'correction_disposition' IS DISTINCT FROM 'AUTO_PROCESSING'
       OR coalesce((v_request.accepted_resolution_json->>'terminal_no_money_evidence')::boolean, false) IS NOT TRUE
       OR coalesce((v_request.accepted_resolution_json->>'signature_valid')::boolean, false)
            IS DISTINCT FROM coalesce(v_source_event.provider_signature_valid, (
              SELECT receipt_row.signature_valid
              FROM public.bank_provider_webhook_receipts AS receipt_row
              WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
            ), false)
       OR (
         v_source_event.provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
         AND (
           v_source_event.provider_webhook_receipt_id IS NULL
           OR coalesce(v_source_event.provider_signature_valid, (
             SELECT receipt_row.signature_valid
             FROM public.bank_provider_webhook_receipts AS receipt_row
             WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
           ), false) IS NOT TRUE
           OR NOT EXISTS (
             SELECT 1
             FROM public.bank_provider_webhook_receipts AS receipt_row
             WHERE receipt_row.id = v_source_event.provider_webhook_receipt_id
               AND receipt_row.signature_valid IS TRUE
               AND receipt_row.provider_key IS NOT DISTINCT FROM v_source_event.provider_key
               AND receipt_row.rail_env IS NOT DISTINCT FROM v_source_event.rail_env
               AND pg_catalog.upper(coalesce(receipt_row.status, '')) IN (
                 'VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED'
               )
           )
         )
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_AUTO_START_NOT_ALLOWED'
        USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_AUTO_EVIDENCE_INVALID',
          'source_bank_event_id', v_request.source_bank_event_id
        )::text;
    END IF;
  ELSE
    IF p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id
       OR v_proof_hash IS NULL OR v_proof_hash !~ '^[0-9a-f]{64}$'
       OR v_request.reauth_proof_hash IS DISTINCT FROM v_proof_hash
       OR (
         coalesce(v_resume_reauthenticated_request, false) IS NOT TRUE
         AND v_request.reauth_consumed_at_utc IS NOT NULL
       )
       OR (
         coalesce(v_resume_reauthenticated_request, false) IS NOT TRUE
         AND (
           v_request.reauth_expires_at_utc IS NULL
           OR v_request.reauth_expires_at_utc <= v_now
         )
       )
       OR p_selection_json->>'selection_hash' IS DISTINCT FROM v_request.selection_hash
       OR p_selection_json->>'plan_hash' IS DISTINCT FROM v_request.plan_hash
       OR NULLIF(pg_catalog.btrim(coalesce(p_reason, '')), '') IS DISTINCT FROM v_request.reason THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_REAUTH_PROOF_INVALID'
        USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object('code', 'REAUTH_PROOF_INVALID')::text;
    END IF;
  END IF;

  -- Definitive selection-bound residual proof.  The two earlier PRE_REQUEST
  -- observations deliberately remain non-gating because durable item-level Q
  -- does not exist at those points.  Here the request, batch and correction
  -- operation are locked, reauthentication/selection/plan hashes have been
  -- rechecked, Q is durable, and REQUEST_START/financial mutation has not yet
  -- begun.
  IF v_command='START_PREPARED'
     AND COALESCE(v_request.plan_json->>'requested_action','') IN (
       'PRE_BANK_CANCEL','CANCEL_PAYMENT'
     )
     AND COALESCE(v_scheduled_reversion_v2_observe_enabled,false) THEN
    SELECT pg_catalog.array_agg(batch_candidate.candidate_id
             ORDER BY request_candidate.selection_ordinal),
           pg_catalog.count(DISTINCT batch_candidate.candidate_id)::integer
    INTO v_q_bound_candidate_ids,v_q_bound_candidate_distinct_count
    FROM public.pay_payment_correction_request_candidates AS request_candidate
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=request_candidate.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id=v_request.pay_batch_id
    WHERE request_candidate.correction_request_id=v_request.id;

    IF COALESCE(pg_catalog.cardinality(v_q_bound_candidate_ids),0) BETWEEN 1 AND 100
       AND v_q_bound_candidate_distinct_count=pg_catalog.cardinality(v_q_bound_candidate_ids) THEN
      WITH matching_execution AS (
        SELECT execution_operation.id,
          COALESCE(
            execution_operation.progress_json->'execution_unsent_overlay_chain_v2',
            execution_operation.result_json->'execution_unsent_overlay_chain_v2'
          ) AS chain_set
        FROM public.banking_pay_operations AS execution_operation
        WHERE execution_operation.operation_type='PAYMENT_EXECUTE'
          AND execution_operation.pay_batch_id=v_request.pay_batch_id
          AND execution_operation.status='COMPLETE'
          AND execution_operation.phase='COMPLETE'
          AND COALESCE(
            execution_operation.progress_json#>>'{execution_unsent_overlay_chain_v2,contract_version}',
            execution_operation.result_json#>>'{execution_unsent_overlay_chain_v2,contract_version}',''
          )='EXECUTION_UNSENT_OVERLAY_CHAIN_V2'
          AND COALESCE(
            execution_operation.progress_json#>>'{execution_unsent_overlay_chain_v2,execution_operation_id}',
            execution_operation.result_json#>>'{execution_unsent_overlay_chain_v2,execution_operation_id}',''
          )=execution_operation.id::text
          AND COALESCE(
            execution_operation.progress_json#>>'{execution_unsent_overlay_chain_v2,pay_batch_id}',
            execution_operation.result_json#>>'{execution_unsent_overlay_chain_v2,pay_batch_id}',''
          )=v_request.pay_batch_id::text
          AND NOT EXISTS (
            SELECT 1 FROM pg_catalog.unnest(v_q_bound_candidate_ids) AS selected(candidate_id)
            WHERE COALESCE(
              execution_operation.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
                ->selected.candidate_id::text->>'closed',
              execution_operation.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
                ->selected.candidate_id::text->>'closed','false'
            )<>'true'
          )
      )
      SELECT pg_catalog.count(*)::integer,
        CASE WHEN pg_catalog.count(*)=1 THEN pg_catalog.min(id::text)::uuid END
      INTO v_q_bound_execution_operation_count,v_q_bound_execution_operation_id
      FROM matching_execution;

      IF v_q_bound_execution_operation_count=1 THEN
        SELECT COALESCE(pg_catalog.jsonb_object_agg(
          selected.candidate_id::text,
          COALESCE(
            execution_operation.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
              ->selected.candidate_id::text->>'chain_digest',
            execution_operation.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
              ->selected.candidate_id::text->>'chain_digest'
          ) ORDER BY selected.candidate_id
        ),'{}'::jsonb)
        INTO v_q_bound_chain_digest_map
        FROM pg_catalog.unnest(v_q_bound_candidate_ids) AS selected(candidate_id)
        JOIN public.banking_pay_operations AS execution_operation
          ON execution_operation.id=v_q_bound_execution_operation_id;

        v_q_bound_parent_proof:=private.pay_workbench_execution_refresh_owner_proof_page_v1(
          v_q_bound_execution_operation_id,v_request.pay_batch_id,
          v_q_bound_candidate_ids,'PRE_REQUEST',
          pg_catalog.jsonb_build_object(
            'contract_version','2',
            'expected_chain_digest_by_candidate',v_q_bound_chain_digest_map,
            'expected_owner_by_candidate','{}'::jsonb,
            'expected_parent_proof_digest_by_candidate','{}'::jsonb,
            'residual_selection_binding',pg_catalog.jsonb_build_object(
              'contract_version','EXECUTION_RESIDUAL_SELECTION_BINDING_V1',
              'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
              'correction_request_id',v_request.id,
              'correction_operation_id',v_operation.id,
              'workbench_session_id',v_batch.source_workbench_session_id,
              'workbench_session_version',v_batch.source_session_version,
              'request_selection_hash',v_request.selection_hash,
              'request_plan_hash',v_request.plan_hash,
              'expected_selected_anchor_digest_by_candidate','{}'::jsonb
            )
          )
        );

        SELECT COALESCE(pg_catalog.jsonb_object_agg(
          result.value->>'candidate_id',
          pg_catalog.jsonb_build_object(
            'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_AUTHORITY_V1',
            'pay_batch_candidate_id',result.value#>>'{residual_identity_authority,pay_batch_candidate_id}',
            'v2_chain_digest',result.value->>'execution_overlay_chain_digest',
            'selected_anchor_digest',result.value#>>'{residual_identity_authority,selected_anchor_digest}',
            'affected_physical_closure_digest',
              result.value#>>'{residual_identity_authority,affected_physical_closure_digest}',
            'residual_proof_digest',result.value#>>'{residual_identity_authority,residual_proof_digest}',
            'parent_proof_digest',result.value->>'proof_digest',
            'authority_digest',result.value#>>'{residual_identity_authority,authority_digest}',
            'admitted',COALESCE((result.value->>'admitted')::boolean,false),
            'rejection_reason',result.value->>'rejection_reason'
          ) ORDER BY result.value->>'candidate_id'
        ),'{}'::jsonb)
        INTO v_q_bound_candidate_authorities
        FROM pg_catalog.jsonb_array_elements(
          COALESCE(v_q_bound_parent_proof->'candidate_results','[]'::jsonb)
        ) AS result(value);
      END IF;
    END IF;

    v_q_bound_authority_set_digest:=private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_SET_V1',
        'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
        'correction_request_id',v_request.id,'correction_operation_id',v_operation.id,
        'execution_operation_id',v_q_bound_execution_operation_id,
        'pay_batch_id',v_request.pay_batch_id,
        'request_selection_hash',v_request.selection_hash,
        'request_plan_hash',v_request.plan_hash,
        'candidate_authorities',v_q_bound_candidate_authorities
      )
    );
    v_q_bound_authority:=pg_catalog.jsonb_build_object(
      'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_SET_V1',
      'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
      'correction_request_id',v_request.id,'correction_operation_id',v_operation.id,
      'execution_operation_id',v_q_bound_execution_operation_id,
      'pay_batch_id',v_request.pay_batch_id,
      'workbench_session_id',v_batch.source_workbench_session_id,
      'workbench_session_version',v_batch.source_session_version,
      'request_selection_hash',v_request.selection_hash,'request_plan_hash',v_request.plan_hash,
      'execution_operation_resolution',CASE
        WHEN COALESCE(pg_catalog.cardinality(v_q_bound_candidate_ids),0)>100
          THEN 'EXECUTION_RESIDUAL_REQUEST_SCOPE_EXCEEDS_BOUND'
        WHEN v_q_bound_candidate_distinct_count
               IS DISTINCT FROM COALESCE(pg_catalog.cardinality(v_q_bound_candidate_ids),0)
          THEN 'EXECUTION_RESIDUAL_REQUEST_CANDIDATE_SET_AMBIGUOUS'
        WHEN v_q_bound_execution_operation_count=1 THEN 'EXACT'
        WHEN v_q_bound_execution_operation_count=0 THEN 'EXECUTION_RESIDUAL_EXECUTION_OPERATION_MISSING'
        ELSE 'EXECUTION_RESIDUAL_EXECUTION_OPERATION_AMBIGUOUS' END,
      'candidate_authorities',v_q_bound_candidate_authorities,
      'all_admitted',v_q_bound_execution_operation_count=1
        AND COALESCE((v_q_bound_parent_proof->>'admitted_count')::integer,0)
            =COALESCE(pg_catalog.cardinality(v_q_bound_candidate_ids),0),
      'authority_set_digest',v_q_bound_authority_set_digest
    );

    UPDATE public.banking_pay_operations AS q_bound_operation
    SET input_json=COALESCE(q_bound_operation.input_json,'{}'::jsonb)
          ||pg_catalog.jsonb_build_object(
            'cancellation_reversion_q_bound_pre_request_start_v1',v_q_bound_authority
          ),
        updated_at_utc=pg_catalog.clock_timestamp()
    WHERE q_bound_operation.id=v_operation.id
    RETURNING q_bound_operation.* INTO v_operation;
  END IF;

  IF v_command IN ('START_AUTO', 'START_PREPARED') THEN
    SELECT coalesce(
             pg_catalog.jsonb_agg(auth_request.id ORDER BY auth_request.created_at_utc),
             '[]'::jsonb
           )
    INTO v_old_auth_request_ids
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.pay_batch_id = v_request.pay_batch_id
      AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

    v_old_schedule_kind := v_batch.schedule_kind;
    v_old_scheduled_at_utc := v_batch.scheduled_at_utc;

    UPDATE public.pay_batch_auth_requests AS old_auth
    SET state = 'CANCELLED',
        finalised_at_utc = coalesce(old_auth.finalised_at_utc, v_now),
        finalised_by_user_id = p_actor_user_id
    WHERE old_auth.pay_batch_id = v_request.pay_batch_id
      AND old_auth.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

    UPDATE public.pay_batch_auth_tokens AS old_token
    SET used_at_utc = coalesce(old_token.used_at_utc, v_now)
    WHERE old_token.auth_request_id IN (
      SELECT auth_id.value::uuid
      FROM pg_catalog.jsonb_array_elements_text(v_old_auth_request_ids) AS auth_id(value)
    )
      AND old_token.used_at_utc IS NULL;

    UPDATE public.pay_batches AS correction_batch
    SET status = CASE
          WHEN coalesce(v_request.plan_json->>'requested_action', '') = 'DRAFT_CANCEL'
            THEN correction_batch.status
          ELSE 'AWAITING_AUTHORISATION'
        END,
        schedule_kind = NULL,
        scheduled_at_utc = NULL,
        scheduled_by_user_id = NULL,
        funding_account_ref = NULL,
        funds_warning_hours_json = NULL,
        execution_intent_json = coalesce(correction_batch.execution_intent_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'correction_request_id', v_request.id,
            'old_authorisation_invalidated_at_utc', v_now,
            'old_schedule_invalidated_at_utc', v_now,
            'reauthorisation_required',
              coalesce(v_request.plan_json->>'requested_action', '') <> 'DRAFT_CANCEL',
            'automatic_provider_no_money', v_command = 'START_AUTO',
            'requester_reauthenticated_cancellation', v_command = 'START_PREPARED'
          )
    WHERE correction_batch.id = v_request.pay_batch_id;
  END IF;

  UPDATE public.pay_payment_correction_requests AS started_request
  SET status = 'AUTHORISED',
      required_quantity = 1,
      reauth_consumed_at_utc = CASE
        WHEN v_command = 'START_AUTO' THEN NULL
        WHEN coalesce(v_resume_reauthenticated_request, false) THEN started_request.reauth_consumed_at_utc
        ELSE v_now
      END,
      authorised_at_utc = coalesce(started_request.authorised_at_utc, v_now),
      approved_count = 1,
      plan_json = coalesce(started_request.plan_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'old_authorisation_request_ids', v_old_auth_request_ids,
          'old_schedule_kind', v_old_schedule_kind,
          'old_scheduled_at_utc', v_old_scheduled_at_utc,
          'old_authorisation_invalidated_at_utc', v_now,
          'old_schedule_invalidated_at_utc', v_now,
          'single_user_cancellation_authority', true
        ),
      updated_at_utc = v_now
  WHERE started_request.id = v_request_id
  RETURNING * INTO v_request;

  UPDATE public.banking_pay_operations AS started_operation
  SET status = 'RUNNING',
      phase = 'EXPAND_WORK',
      runner_state = 'RUNNABLE',
      requires_user_action = false,
      run_after_utc = v_now,
      lease_owner = NULL, lease_expires_at_utc = NULL, locked_by = NULL, lock_expires_at_utc = NULL,
      updated_at_utc = v_now
  WHERE started_operation.id = v_operation.id
  RETURNING * INTO v_operation;

  INSERT INTO public.pay_payment_correction_actions (
    correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
    action_at_utc, note, before_json, after_json, metadata_json
  ) VALUES (
    v_request_id, p_pay_batch_id, CASE WHEN v_command = 'START_AUTO' THEN 'SYSTEM' ELSE 'USER' END,
    CASE WHEN v_command = 'START_AUTO' THEN NULL ELSE p_actor_user_id END,
    CASE WHEN coalesce(v_resume_reauthenticated_request, false) THEN 'AUTHORISE' ELSE 'REQUEST' END,
    v_now,
    CASE
      WHEN v_command = 'START_AUTO' THEN 'Immutable automatic correction request started.'
      ELSE 'Requester reauthenticated and authorised the single-user cancellation.'
    END,
    NULL, pg_catalog.to_jsonb(v_request),
    pg_catalog.jsonb_build_object(
      'code', CASE
        WHEN v_command = 'START_AUTO' THEN 'AUTO_REQUEST_STARTED'
        WHEN coalesce(v_resume_reauthenticated_request, false) THEN 'LEGACY_REQUESTER_REAUTHORISED_CANCELLATION_RESUMED'
        ELSE 'REQUESTER_REAUTHORISED_CANCELLATION'
      END
    )
  );

  PERFORM public.banking_pay_batch_signal_touch(
    p_pay_batch_id := v_request.pay_batch_id,
    p_change_reason := CASE
      WHEN v_command = 'START_AUTO' THEN 'PAYMENT_CORRECTION_AUTO_AUTHORISED'
      ELSE 'PAYMENT_CORRECTION_REQUESTER_AUTHORISED'
    END,
    p_change_source := 'pay_payment_correction_request_start',
    p_change_scope_json := pg_catalog.jsonb_build_object(
      'correction_request_id', v_request.id,
      'operation_id', v_operation.id,
      'source_bank_event_id', v_request.source_bank_event_id,
      'requested_action', v_request.plan_json ->> 'requested_action',
      'single_user_cancellation_authority', v_command = 'START_PREPARED'
    )
  );

  IF v_command='START_PREPARED'
     AND COALESCE(v_request.plan_json->>'requested_action','') IN (
       'DRAFT_CANCEL','PRE_BANK_CANCEL','CANCEL_PAYMENT'
     ) THEN
    WITH selected_candidates AS (
      SELECT batch_candidate.candidate_id,
             v_draft_overlay_start_admission->batch_candidate.candidate_id::text
               AS start_admission,
             COALESCE(candidate_counter.seq,0) AS live_source_change_seq,
             COALESCE(candidate_counter.scope_change_generation,0) AS live_dirty_generation
      FROM public.pay_payment_correction_request_candidates AS request_candidate
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=request_candidate.pay_batch_candidate_id
      LEFT JOIN public.app_change_counters AS candidate_counter
        ON candidate_counter.entity_key='pay_candidate:'||batch_candidate.candidate_id::text
      WHERE request_candidate.correction_request_id=v_request_id
    )
    SELECT COALESCE(pg_catalog.jsonb_object_agg(
      selected_candidates.candidate_id::text,
      pg_catalog.jsonb_build_object(
        'contract_version',CASE
          WHEN COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL'
            THEN 'DRAFT_OVERLAY_FAST_START_AUTHORITY_V1'
          ELSE 'CANCELLATION_REVERSION_START_AUTHORITY_V2' END,
        'correction_request_id',v_request_id,
        'operation_id',v_operation.id,
        'candidate_id',selected_candidates.candidate_id,
        'source_change_seq',selected_candidates.live_source_change_seq,
        'dirty_generation',selected_candidates.live_dirty_generation,
        'start_exact',COALESCE((selected_candidates.start_admission->>'start_exact')::boolean,false),
        'rejection_reason',selected_candidates.start_admission->>'rejection_reason',
        'pre_request_fence_digest',selected_candidates.start_admission->>'pre_request_fence_digest',
        'request_owned_dirty_job_id',selected_candidates.start_admission->>'request_owned_dirty_job_id',
        'request_owned_dirty_proven',COALESCE(
          (selected_candidates.start_admission->>'request_owned_dirty_proven')::boolean,false
        ),
        'fence_digest',pg_catalog.md5(
          v_request_id::text||'|'||v_operation.id::text||'|'||
          selected_candidates.candidate_id::text||'|'||
          selected_candidates.live_source_change_seq::text||'|'||
          selected_candidates.live_dirty_generation::text||'|'||
          COALESCE(selected_candidates.start_admission->>'pre_request_fence_digest','')||'|'||
          COALESCE(selected_candidates.start_admission->>'request_owned_dirty_job_id','')||'|'||
          COALESCE((selected_candidates.start_admission->>'request_owned_dirty_proven')::boolean,false)::text||'|'||
          COALESCE((selected_candidates.start_admission->>'start_exact')::boolean,false)::text||
          CASE WHEN COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL'
            THEN '|DRAFT_OVERLAY_FAST_START_AUTHORITY_V1'
            ELSE '|CANCELLATION_REVERSION_START_AUTHORITY_V2' END
        )
      ) ORDER BY selected_candidates.candidate_id
    ),'{}'::jsonb)
    INTO v_draft_overlay_start_authorities
    FROM selected_candidates;

    IF COALESCE(v_request.plan_json->>'requested_action','') IN (
      'PRE_BANK_CANCEL','CANCEL_PAYMENT'
    ) THEN
      WITH selected_candidates AS (
        SELECT batch_candidate.candidate_id,
          v_draft_overlay_start_authorities->batch_candidate.candidate_id::text AS v2_start,
          v_q_bound_candidate_authorities->batch_candidate.candidate_id::text AS q_authority
        FROM public.pay_payment_correction_request_candidates AS request_candidate
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id=request_candidate.pay_batch_candidate_id
        WHERE request_candidate.correction_request_id=v_request_id
      )
      SELECT COALESCE(pg_catalog.jsonb_object_agg(
        selected_candidates.candidate_id::text,
        pg_catalog.jsonb_build_object(
          'contract_version','CANCELLATION_REVERSION_START_AUTHORITY_V3',
          'correction_request_id',v_request_id,'operation_id',v_operation.id,
          'candidate_id',selected_candidates.candidate_id,
          'source_change_seq',selected_candidates.v2_start->'source_change_seq',
          'dirty_generation',selected_candidates.v2_start->'dirty_generation',
          'start_exact',COALESCE((selected_candidates.q_authority->>'admitted')::boolean,false),
          'rejection_reason',CASE
            WHEN COALESCE((selected_candidates.q_authority->>'admitted')::boolean,false) THEN NULL
            ELSE COALESCE(selected_candidates.q_authority->>'rejection_reason',
              'EXECUTION_RESIDUAL_SELECTION_AUTHORITY_REQUIRED') END,
          'pre_request_fence_digest',selected_candidates.v2_start->>'pre_request_fence_digest',
          'request_owned_dirty_job_id',selected_candidates.v2_start->>'request_owned_dirty_job_id',
          'request_owned_scope_change_tx_token',
            selected_candidates.v2_start->>'request_owned_scope_change_tx_token',
          'request_owned_dirty_proven',COALESCE(
            (selected_candidates.v2_start->>'request_owned_dirty_proven')::boolean,false
          ),
          'q_bound_pre_request_start_authority_digest',
            selected_candidates.q_authority->>'authority_digest',
          'selected_anchor_digest',selected_candidates.q_authority->>'selected_anchor_digest',
          'residual_proof_digest',selected_candidates.q_authority->>'residual_proof_digest',
          'parent_proof_digest',selected_candidates.q_authority->>'parent_proof_digest',
          'q_bound_authority_set_digest',v_q_bound_authority_set_digest,
          'fence_digest',private.pay_payment_correction_sha256_v1(
            pg_catalog.jsonb_build_object(
              'contract_version','CANCELLATION_REVERSION_START_AUTHORITY_V3',
              'correction_request_id',v_request_id,'operation_id',v_operation.id,
              'candidate_id',selected_candidates.candidate_id,
              'source_change_seq',selected_candidates.v2_start->'source_change_seq',
              'dirty_generation',selected_candidates.v2_start->'dirty_generation',
              'q_bound_pre_request_start_authority_digest',
                selected_candidates.q_authority->>'authority_digest',
              'selected_anchor_digest',selected_candidates.q_authority->>'selected_anchor_digest',
              'residual_proof_digest',selected_candidates.q_authority->>'residual_proof_digest',
              'parent_proof_digest',selected_candidates.q_authority->>'parent_proof_digest',
              'q_bound_authority_set_digest',v_q_bound_authority_set_digest,
              'request_owned_scope_change_tx_token',
                selected_candidates.v2_start->>'request_owned_scope_change_tx_token',
              'start_exact',COALESCE((selected_candidates.q_authority->>'admitted')::boolean,false)
            )
          )
        ) ORDER BY selected_candidates.candidate_id
      ),'{}'::jsonb)
      INTO v_cancel_reversion_start_authorities_v3
      FROM selected_candidates;
    END IF;

    UPDATE public.banking_pay_operations AS authority_operation
    SET input_json=COALESCE(authority_operation.input_json,'{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'draft_overlay_fast_start_authorities',CASE
              WHEN COALESCE(v_request.plan_json->>'requested_action','')='DRAFT_CANCEL'
                THEN v_draft_overlay_start_authorities ELSE '{}'::jsonb END,
            'cancellation_reversion_start_authorities_v2',CASE
              WHEN COALESCE(v_request.plan_json->>'requested_action','') IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
                THEN v_draft_overlay_start_authorities ELSE '{}'::jsonb END
            ,'cancellation_reversion_start_authorities_v3',CASE
              WHEN COALESCE(v_request.plan_json->>'requested_action','') IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
                THEN v_cancel_reversion_start_authorities_v3 ELSE '{}'::jsonb END
          ),
        updated_at_utc=pg_catalog.clock_timestamp()
    WHERE authority_operation.id=v_operation.id
    RETURNING authority_operation.* INTO v_operation;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true, 'is_existing', false, 'correction_request_id', v_request_id, 'operation_id', v_operation.id,
    'request_status', v_request.status, 'operation_status', v_operation.status,
    'phase', v_operation.phase,
    'selection_ready', true,
    'gate_active', v_request.status IN ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING'),
    'approved_count', coalesce(v_request.approved_count, 0),
    'required_quantity', greatest(coalesce(v_request.required_quantity, 1), 1),
    'requires_reauthentication', false,
    'requires_authorisation', false,
    'display_status', CASE WHEN v_command = 'START_AUTO' THEN 'Failed payment release authorised' ELSE 'Cancellation authorised' END,
    'display_message', CASE WHEN v_command = 'START_AUTO' THEN 'CloudTMS is processing the provider-confirmed failed-payment release.' ELSE 'CloudTMS is processing the authorised cancellation.' END,
    'continuation', pg_catalog.jsonb_build_object(
      'required', v_request.status IN ('AUTHORISED','EXPANDED','PROCESSING'),
      'operation_id', v_operation.id, 'operation_type', 'PAYMENT_CORRECTION',
      'pay_batch_id', v_request.pay_batch_id, 'root_operation_id', v_operation.root_operation_id,
      'phase', v_operation.phase, 'run_after_utc', v_operation.run_after_utc,
      'reason', CASE WHEN v_command = 'START_AUTO' THEN 'AUTO_NO_MONEY_START' ELSE 'PAYMENT_CORRECTION_START' END,
      'successor_relation', CASE WHEN v_request.status IN ('AUTHORISED','EXPANDED','PROCESSING') THEN 'SELF' ELSE 'NONE' END,
      'requires_user_action', false,
      'terminal', false
    ),
    'code', CASE WHEN v_command = 'START_AUTO' THEN 'AUTO_REQUEST_STARTED' ELSE 'PAYMENT_CORRECTION_AUTHORISED' END
  );
END;
$function$;

-- pay_payment_correction_retry_planning_v1(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_retry_planning_v1(p_correction_request_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '5000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_enabled boolean := false;
  v_actor public.tms_users%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_is_admin boolean := false;
  v_retry_count integer := 0;
  v_error_code text := NULL::text;
  v_retry_mode text := NULL::text;
  v_retry_reason text := NULL::text;
  v_retry_counter_key text := NULL::text;
BEGIN
  IF p_correction_request_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_RETRY_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_RETRY_REQUEST_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'ACTOR_USER_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'ACTOR_USER_ID_REQUIRED')::text;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_candidate_cancellation_enabled, false)
  INTO v_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF v_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_FEATURE_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_FEATURE_DISABLED')::text;
  END IF;

  SELECT actor_row.*
  INTO v_actor
  FROM public.tms_users AS actor_row
  WHERE actor_row.id = p_actor_user_id
    AND COALESCE(actor_row.is_active, false);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTOR_USER_INACTIVE'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object('code', 'PERMISSION_DENIED')::text;
  END IF;

  v_is_admin := pg_catalog.lower(COALESCE(v_actor.role, '')) = 'admin';

  -- Canonical correction lock order: request -> batch -> operation.
  SELECT request_row.*
  INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id = p_correction_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_NOT_FOUND')::text;
  END IF;

  IF p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id AND v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_RETRY_REQUEST_OWNER_OR_ADMIN_REQUIRED'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object('code', 'REQUEST_OWNER_OR_ADMIN_REQUIRED')::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_request.pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND operation_row.pay_batch_id = v_request.pay_batch_id
    AND operation_row.input_json ->> 'correction_request_id' = p_correction_request_id::text
  ORDER BY operation_row.created_at_utc DESC, operation_row.id DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'PAYMENT_CORRECTION_OPERATION_NOT_FOUND')::text;
  END IF;

  v_error_code := pg_catalog.upper(COALESCE(
    v_operation.error_json ->> 'code',
    v_operation.error_json ->> 'error_code',
    ''
  ));
  IF pg_catalog.upper(COALESCE(v_request.status, '')) = 'PLANNING'
     AND pg_catalog.upper(COALESCE(v_operation.phase, '')) = 'PREPARE_SELECTION' THEN
    v_retry_mode := 'PLANNING';
    v_retry_reason := 'EXPLICIT_SAFE_PLANNING_RETRY';
    v_retry_counter_key := 'planning_retry_count';
  ELSIF pg_catalog.upper(COALESCE(v_request.status, '')) IN ('AUTHORISED', 'AUTHORIZED')
     AND pg_catalog.upper(COALESCE(v_operation.phase, '')) = 'EXPAND_WORK'
     AND pg_catalog.upper(COALESCE(v_request.plan_json ->> 'requested_action', '')) = 'DRAFT_CANCEL'
     AND pg_catalog.upper(COALESCE(v_batch.status, '')) = 'DRAFT' THEN
    v_retry_mode := 'DRAFT_EXPAND';
    v_retry_reason := 'EXPLICIT_SAFE_DRAFT_EXPAND_RETRY';
    v_retry_counter_key := 'processing_retry_count';
  ELSIF pg_catalog.upper(COALESCE(v_request.status, '')) IN ('PROCESSING', 'APPLIED')
     AND pg_catalog.upper(COALESCE(v_operation.phase, '')) IN ('FINALISE', 'REFRESH_WORKBENCH')
     AND (
       pg_catalog.upper(COALESCE(v_request.status, '')) = 'PROCESSING'
       OR pg_catalog.upper(COALESCE(v_operation.phase, '')) = 'REFRESH_WORKBENCH'
     )
     AND pg_catalog.upper(COALESCE(v_request.plan_json ->> 'requested_action', '')) = 'PRE_BANK_CANCEL' THEN
    v_retry_mode := 'POST_FINANCIAL';
    v_retry_reason := 'EXPLICIT_SAFE_POST_FINANCIAL_RETRY';
    v_retry_counter_key := 'processing_retry_count';
  END IF;

  v_retry_count := CASE
    WHEN v_retry_counter_key IS NOT NULL
      AND COALESCE(v_operation.progress_json ->> v_retry_counter_key, '') ~ '^[0-9]+$'
      THEN GREATEST((v_operation.progress_json ->> v_retry_counter_key)::integer, 0)
    ELSE 0
  END;

  IF v_retry_mode IS NULL
     OR pg_catalog.upper(COALESCE(v_operation.status, '')) <> 'REVIEW_REQUIRED'
     OR pg_catalog.upper(COALESCE(v_operation.runner_state, '')) <> 'WAITING_USER_REVIEW'
     OR COALESCE(v_operation.requires_user_action, false) IS NOT TRUE
     OR v_error_code <> 'BANKING_PAY_OPERATION_ADVANCE_FAILED'
     OR v_retry_count >= 3 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SAFE_RETRY_NOT_ALLOWED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_SAFE_RETRY_NOT_ALLOWED',
        'request_status', v_request.status,
        'operation_status', v_operation.status,
        'operation_phase', v_operation.phase
      )::text;
  END IF;

  IF v_retry_mode = 'PLANNING' THEN
    IF EXISTS (
         SELECT 1 FROM public.banking_pay_operation_chunks AS chunk_row
         WHERE chunk_row.operation_id = v_operation.id
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_request_candidates AS membership_row
         WHERE membership_row.correction_request_id = p_correction_request_id
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_work_items AS work_row
         WHERE work_row.correction_request_id = p_correction_request_id
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_items AS correction_row
         WHERE correction_row.correction_request_id = p_correction_request_id
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_actions AS action_row
         WHERE action_row.correction_request_id = p_correction_request_id
           AND action_row.action IS DISTINCT FROM 'REQUEST'
       )
       OR EXISTS (
         SELECT 1 FROM public.banking_pay_operation_provider_attempts AS provider_attempt
         WHERE provider_attempt.operation_id = v_operation.id
            OR provider_attempt.pay_batch_id = v_request.pay_batch_id
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_PLANNING_RETRY_EVIDENCE_EXISTS'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_PLANNING_RETRY_EVIDENCE_EXISTS'
        )::text;
    END IF;
  ELSIF v_retry_mode = 'DRAFT_EXPAND' THEN
    -- EXPAND_WORK is one PostgreSQL transaction.  A failure before these
    -- durable owners exist therefore leaves no financial work to repeat.
    IF EXISTS (
         SELECT 1 FROM public.pay_payment_correction_work_items AS work_row
         WHERE work_row.correction_request_id = p_correction_request_id
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_items AS correction_row
         WHERE correction_row.correction_request_id = p_correction_request_id
       )
       OR EXISTS (
         SELECT 1 FROM public.banking_pay_operation_provider_attempts AS provider_attempt
         WHERE provider_attempt.operation_id = v_operation.id
            OR provider_attempt.pay_batch_id = v_request.pay_batch_id
       )
       OR EXISTS (
         SELECT 1 FROM public.banking_pay_operation_transfer_scope AS transfer_scope
         WHERE transfer_scope.operation_id = v_operation.id
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_DRAFT_EXPAND_RETRY_EVIDENCE_EXISTS'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_DRAFT_EXPAND_RETRY_EVIDENCE_EXISTS'
        )::text;
    END IF;
  ELSE
    -- FINALISE and REFRESH_WORKBENCH are post-financial, idempotent route
    -- phases.  Resume only the same pre-bank request after at least one exact
    -- financial work item was applied and every work item is already terminal.
    -- The retry never rewinds to PROCESS_CHUNKS and never repeats financial DML.
    IF NOT EXISTS (
         SELECT 1 FROM public.pay_payment_correction_work_items AS applied_work
         WHERE applied_work.correction_request_id = p_correction_request_id
           AND applied_work.status = 'APPLIED'
       )
       OR EXISTS (
         SELECT 1 FROM public.pay_payment_correction_work_items AS unfinished_work
         WHERE unfinished_work.correction_request_id = p_correction_request_id
           AND unfinished_work.status NOT IN ('APPLIED', 'BLOCKED', 'CANCELLED', 'FAILED')
       )
       OR EXISTS (
         SELECT 1 FROM public.banking_pay_operation_provider_attempts AS provider_attempt
         WHERE provider_attempt.operation_id = v_operation.id
            OR provider_attempt.pay_batch_id = v_request.pay_batch_id
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_POST_FINANCIAL_RETRY_EVIDENCE_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_POST_FINANCIAL_RETRY_EVIDENCE_INVALID'
        )::text;
    END IF;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = 'RUNNING',
      runner_state = 'RUNNABLE',
      requires_user_action = false,
      run_after_utc = v_now,
      lease_owner = NULL,
      lease_expires_at_utc = NULL,
      locked_by = NULL,
      lock_expires_at_utc = NULL,
      error_json = NULL,
      resume_reason = v_retry_reason,
      progress_json = pg_catalog.jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          v_retry_counter_key, v_retry_count + 1,
          CASE WHEN v_retry_mode = 'PLANNING' THEN 'planning_retry_at_utc' ELSE 'processing_retry_at_utc' END, v_now::text,
          CASE WHEN v_retry_mode = 'PLANNING' THEN 'planning_retry_previous_error_code' ELSE 'processing_retry_previous_error_code' END, v_error_code,
          'safe_retry_mode', v_retry_mode,
          'status', 'RUNNING',
          'phase', v_operation.phase,
          'runner_state', 'RUNNABLE',
          'requires_user_action', false,
          'review_required', false,
          'resume_reason', v_retry_reason
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = v_operation.id;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'code', CASE WHEN v_retry_mode = 'PLANNING'
      THEN 'PAYMENT_CORRECTION_PLANNING_RETRY_QUEUED'
      ELSE 'PAYMENT_CORRECTION_PROCESSING_RETRY_QUEUED' END,
    'retry_mode', v_retry_mode,
    'correction_request_id', p_correction_request_id,
    'pay_batch_id', v_request.pay_batch_id,
    'operation_id', v_operation.id,
    'continuation', pg_catalog.jsonb_build_object(
      'required', true,
      'operation_id', v_operation.id,
      'operation_type', 'PAYMENT_CORRECTION',
      'pay_batch_id', v_request.pay_batch_id,
      'root_operation_id', v_operation.root_operation_id,
      'phase', v_operation.phase,
      'run_after_utc', v_now,
      'reason', v_retry_reason,
      'successor_relation', 'SELF',
      'requires_user_action', false,
      'terminal', false
    )
  );
END
$function$;

-- pay_payment_correction_selection_prepare_chunk_v1(uuid,uuid,jsonb,integer,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_selection_prepare_chunk_v1(p_correction_request_id uuid, p_operation_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50, p_worker_id text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
    v_request public.pay_payment_correction_requests%ROWTYPE;
    v_operation public.banking_pay_operations%ROWTYPE;
    v_batch public.pay_batches%ROWTYPE;
    v_settings public.settings_defaults%ROWTYPE;
    v_selection jsonb;
    v_filter jsonb;
    v_mode text;
    v_requested_action text;
    v_snapshot_token text;
    v_expected_snapshot_token text;
    v_active_batch_scope_hash text;
    v_cursor_candidate_id uuid;
    v_next_cursor_json jsonb;
    v_page_candidate_count integer := 0;
    v_page_active_item_count integer := 0;
    v_page_source_row_count integer := 0;
    v_page_matching_queued_count integer := 0;
    v_page_amount_pence bigint := 0;
    v_page_hash text;
    v_selection_hash text;
    v_plan_json jsonb;
    v_plan_hash text;
    v_complete boolean := false;
    v_sequence_no integer;
    v_start_ordinal bigint;
    v_last_candidate_id uuid;
    v_total_candidate_count integer;
    v_total_active_item_count integer;
    v_total_source_row_count integer;
    v_total_matching_queued_count integer;
    v_total_amount numeric(14,2);
    v_has_more boolean := false;
    v_candidate record;
    v_diagnostic jsonb;
    v_item_ids uuid[];
    v_item_count integer;
    v_source_row_count integer;
    v_matching_queued_count integer := 0;
    v_amount numeric(14,2);
    v_candidate_scope_hash text;
    v_shared_instruction_scope_hash text;
    v_eligibility_code text;
    v_effective_display_state text;
    v_action_allowed boolean;
    v_max_candidates integer;
    v_max_active_items integer;
    v_max_items_per_candidate integer;
    v_max_source_rows_per_candidate integer;
    v_actor_user_id uuid;
    v_status_page jsonb := '{}'::jsonb;
    v_status_filter jsonb := '{}'::jsonb;
    v_status_snapshot_token text;
    v_status_read_limit integer;
    v_scan_candidate_tokens jsonb := '[]'::jsonb;
    v_scan_last_candidate_id uuid;
    v_scan_candidate_count integer := 0;
    v_candidate_selection_json jsonb := '{}'::jsonb;
    v_candidate_selected_scope_json jsonb := '{}'::jsonb;
    v_unselected_scope_hash_before text;
    v_page_sequence_no integer := 1;
    v_prior_page_hash text;
    v_first_scanned_candidate_id uuid;
    v_scanned_candidate_count integer := 0;
    v_selected_chain_hash text;
    v_unselected_chain_hash text;
    v_explicit_id_chain_hash text;
    v_candidate_audit_hash text;
    v_existing_chunk public.banking_pay_operation_chunks%ROWTYPE;
    v_requested_explicit_count integer := 0;
    v_requested_explicit_hash text;
    v_actual_explicit_count integer := 0;
    v_actual_explicit_hash text;
    v_explicit_missing_count integer := 0;
    v_explicit_extra_count integer := 0;
    v_page_chain_mismatch_count integer := 0;
    v_cancel_reversion_page_proof jsonb := '{}'::jsonb;
    v_cancel_reversion_page_authorities_v3 jsonb := '{}'::jsonb;
    v_cancel_reversion_page_authority_hash text;
    v_candidate_pre_request_authority jsonb := '{}'::jsonb;
    v_candidate_scope_contract_version integer := 1;
    v_candidate_scope_hash_version integer := 1;
    v_source_row_count_semantics text := 'FINANCIAL_AND_QUEUED_COMMUNICATIONS';
    v_communication_cleanup_contract_version integer := NULL::integer;
    v_candidate_scope_contract_raw text;
BEGIN
    IF p_correction_request_id IS NULL OR p_operation_id IS NULL THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_IDENTIFIERS_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'DESCRIPTOR_INVALID'
                  )::text;
    END IF;

    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_LIMIT_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'DESCRIPTOR_INVALID',
                      'limit', p_limit
                  )::text;
    END IF;

    IF p_cursor_json IS NOT NULL
       AND (
           pg_catalog.jsonb_typeof(p_cursor_json) <> 'object'
           OR p_cursor_json->>'page_sequence_no' !~ '^[0-9]+$'
           OR CASE WHEN p_cursor_json->>'page_sequence_no' ~ '^[0-9]+$'
                   THEN (p_cursor_json->>'page_sequence_no')::integer < 2 ELSE true END
           OR p_cursor_json ->> 'last_scanned_candidate_id'
                !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR p_cursor_json ->> 'prior_page_hash' !~ '^[0-9a-f]{64}$'
           OR p_cursor_json ->> 'scope_fence' !~ '^[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_CURSOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'DESCRIPTOR_INVALID'
                  )::text;
    END IF;

    IF p_worker_id IS NULL OR pg_catalog.btrim(p_worker_id) = '' THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_LEASE_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'LEASE_REQUIRED',
                      'operation_id', p_operation_id
                  )::text;
    END IF;

    -- Non-gating planning order: request -> batch -> operation.
    SELECT request_row.*
    INTO v_request
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.id = p_correction_request_id
    FOR UPDATE;

    IF NOT FOUND OR v_request.status NOT IN ('PLANNING', 'PLANNED') THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_PLANNING'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'REQUEST_NOT_PLANNING',
                      'correction_request_id', p_correction_request_id
                  )::text;
    END IF;

    -- Candidate-scope V2 is explicit durable authority for newly prepared
    -- requests. A request that already has materialised membership but no
    -- marker remains legacy V1; it is never reinterpreted by deployment date.
    v_candidate_scope_contract_raw := NULLIF(
        pg_catalog.btrim(COALESCE(v_request.plan_json->>'candidate_scope_contract_version', '')),
        ''
    );

    IF v_candidate_scope_contract_raw IS NULL THEN
        IF v_request.status = 'PLANNING'
           AND NOT EXISTS (
               SELECT 1
               FROM public.pay_payment_correction_request_candidates AS existing_member
               WHERE existing_member.correction_request_id = v_request.id
           )
           AND NOT EXISTS (
               SELECT 1
               FROM public.banking_pay_operation_chunks AS existing_chunk
               WHERE existing_chunk.operation_id = p_operation_id
                 AND existing_chunk.phase = 'PREPARE_SELECTION'
                 AND existing_chunk.chunk_type = 'CANDIDATE_SCOPE'
           ) THEN
            v_candidate_scope_contract_version := 2;
        ELSE
            v_candidate_scope_contract_version := 1;
        END IF;
    ELSIF v_candidate_scope_contract_raw IN ('1', '2') THEN
        v_candidate_scope_contract_version := v_candidate_scope_contract_raw::integer;
    ELSE
        RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED',
                      'candidate_scope_contract_version', v_candidate_scope_contract_raw,
                      'correction_request_id', v_request.id
                  )::text;
    END IF;

    v_candidate_scope_hash_version := v_candidate_scope_contract_version;
    v_source_row_count_semantics := CASE
        WHEN v_candidate_scope_contract_version = 2 THEN 'FINANCIAL_ONLY'
        ELSE 'FINANCIAL_AND_QUEUED_COMMUNICATIONS'
    END;
    v_communication_cleanup_contract_version := CASE
        WHEN v_candidate_scope_contract_version = 2 THEN 1
        ELSE NULL::integer
    END;

    IF v_request.status = 'PLANNING'
       AND v_request.plan_json->>'candidate_scope_contract_version' IS NULL THEN
        UPDATE public.pay_payment_correction_requests AS versioned_request
        SET plan_json = COALESCE(versioned_request.plan_json, '{}'::jsonb)
              || pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                   'candidate_scope_contract_version', v_candidate_scope_contract_version,
                   'candidate_scope_hash_version', v_candidate_scope_hash_version,
                   'source_row_count_semantics', v_source_row_count_semantics,
                   'communication_cleanup_contract_version', v_communication_cleanup_contract_version
                 )),
            updated_at_utc = pg_catalog.clock_timestamp()
        WHERE versioned_request.id = v_request.id
        RETURNING versioned_request.* INTO v_request;
    END IF;

    v_actor_user_id := COALESCE(p_actor_user_id, v_request.requested_by_user_id);
    IF p_actor_user_id IS NOT NULL
       AND p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_ACTOR_MISMATCH'
            USING ERRCODE = '42501',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'PERMISSION_DENIED'
                  )::text;
    END IF;

    SELECT batch_row.*
    INTO v_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = v_request.pay_batch_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_BATCH_NOT_FOUND'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'SELECTION_STALE'
                  )::text;
    END IF;

    IF pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.status, ''))) IN (
        'COMMITTED', 'COMPLETED', 'PAID', 'SETTLED', 'CANCELLED', 'CANCELED'
    ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_BATCH_TERMINAL'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'PAYMENT_CORRECTION_BATCH_TERMINAL',
                      'batch_status', v_batch.status
                  )::text;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_operation.operation_type IS DISTINCT FROM 'PAYMENT_CORRECTION'
       OR (v_request.status = 'PLANNING' AND v_operation.phase IS DISTINCT FROM 'PREPARE_SELECTION')
       OR (v_request.status = 'PLANNED' AND v_operation.phase IS DISTINCT FROM 'AWAITING_REAUTHENTICATION')
       OR v_operation.input_json ->> 'correction_request_id'
            IS DISTINCT FROM p_correction_request_id::text
       OR v_operation.pay_batch_id IS DISTINCT FROM v_request.pay_batch_id THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_OPERATION_MISMATCH'
            USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
                'code', 'OPERATION_MISMATCH', 'operation_id', p_operation_id
            )::text;
    END IF;

    -- A committed final page may have moved the request and operation forward
    -- before the Worker received the response.  Return that exact durable page
    -- without requiring a now-released lease; a different cursor still fails.
    IF v_request.status = 'PLANNED' THEN
        v_page_sequence_no := COALESCE((p_cursor_json->>'page_sequence_no')::integer, 1);
        v_prior_page_hash := COALESCE(
          p_cursor_json->>'prior_page_hash',
          private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
            'version', 1, 'correction_request_id', v_request.id, 'chain', 'PREPARE_SELECTION'
          ))
        );
        SELECT chunk_row.* INTO v_existing_chunk
        FROM public.banking_pay_operation_chunks AS chunk_row
        WHERE chunk_row.operation_id = v_operation.id
          AND chunk_row.phase = 'PREPARE_SELECTION'
          AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
          AND chunk_row.sequence_no = v_page_sequence_no
          AND chunk_row.status = 'COMPLETE';
        IF NOT FOUND
           OR v_existing_chunk.payload_json->>'cursor_hash'
                IS DISTINCT FROM private.pay_payment_correction_sha256_v1(COALESCE(p_cursor_json, '{}'::jsonb))
           OR v_existing_chunk.result_json->>'prior_page_hash' IS DISTINCT FROM v_prior_page_hash
           OR COALESCE((v_existing_chunk.result_json->>'complete')::boolean, false) IS NOT TRUE THEN
          RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
            USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAGE_DIGEST_MISMATCH', 'page_sequence_no', v_page_sequence_no
            )::text;
        END IF;
        RETURN v_existing_chunk.result_json || pg_catalog.jsonb_build_object(
          'ok', true, 'correction_request_id', v_request.id,
          'operation_id', v_operation.id, 'phase', 'AWAITING_REAUTHENTICATION',
          'selection_hash', v_request.selection_hash, 'complete', true,
          'replayed', true, 'code', 'SELECTION_READY'
        );
    END IF;

    IF COALESCE(v_operation.lease_owner, v_operation.locked_by) IS NULL
       OR COALESCE(v_operation.lease_owner, v_operation.locked_by) IS DISTINCT FROM p_worker_id
       OR COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc) IS NULL
       OR COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc)
            <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_LEASE_MISMATCH'
            USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
                'code', 'LEASE_MISMATCH', 'operation_id', p_operation_id
            )::text;
    END IF;

    SELECT settings_row.*
    INTO v_settings
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    v_max_candidates := LEAST(
        COALESCE(v_settings.banking_pay_correction_max_candidates, 10000),
        10000
    );
    v_max_active_items := LEAST(
        COALESCE(v_settings.banking_pay_correction_max_active_items, 250000),
        250000
    );
    v_max_items_per_candidate := LEAST(
        COALESCE(v_settings.banking_pay_correction_max_active_items_per_candidate, 128),
        128
    );
    v_max_source_rows_per_candidate := LEAST(
        COALESCE(v_settings.banking_pay_correction_max_source_rows_per_candidate, 512),
        512
    );

    v_selection := COALESCE(v_request.selection_json, '{}'::jsonb);
    IF pg_catalog.jsonb_typeof(v_selection) <> 'object'
       OR pg_catalog.octet_length(v_selection::text) > 524288 THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_DESCRIPTOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'DESCRIPTOR_INVALID'
                  )::text;
    END IF;

    v_mode := pg_catalog.upper(COALESCE(
        v_selection #>> '{selection,mode}',
        v_selection ->> 'mode',
        ''
    ));
    v_requested_action := pg_catalog.upper(COALESCE(
        v_selection ->> 'requested_action',
        v_selection ->> 'action',
        v_selection #>> '{selection,action}',
        ''
    ));
    v_snapshot_token := COALESCE(
        v_selection #>> '{selection,snapshot_token}',
        v_selection ->> 'snapshot_token'
    );
    v_filter := COALESCE(
        v_selection -> 'filter_json',
        v_selection #> '{selection,filter_json}',
        '{}'::jsonb
    );

    IF v_mode NOT IN ('EXPLICIT', 'ALL_MATCHING')
       OR v_requested_action NOT IN (
           'DRAFT_CANCEL',
           'PRE_BANK_CANCEL',
           'CANCEL_PAYMENT',
           'NO_MONEY_RELEASE',
           'NO_MONEY_UNWIND'
       )
       OR pg_catalog.jsonb_typeof(v_filter) <> 'object' THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_DESCRIPTOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'DESCRIPTOR_INVALID'
                  )::text;
    END IF;

    -- Constant-size scope fence.  Exact candidate/item identity is frozen by
    -- bounded pages and never materialised here as a whole-batch JSON value.
    v_active_batch_scope_hash := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 2,
            'pay_batch_id', v_batch.id,
            'batch_status', v_batch.status,
            'total_bank_out_pence', pg_catalog.round(COALESCE(v_batch.total_bank_out, 0) * 100)::bigint,
            'source_scope_change_generation', v_batch.source_scope_change_generation,
            'execution_commit_state', v_batch.execution_commit_state,
            'execution_commit_ref', v_batch.execution_commit_ref,
            'execution_committed_at_utc', v_batch.execution_committed_at_utc,
            'execution_intent_json', v_batch.execution_intent_json,
            'rail_provider_snapshot', v_batch.rail_provider_snapshot,
            'rail_env_snapshot', v_batch.rail_env_snapshot,
            'freshness_validation_status', v_batch.freshness_validation_status,
            'freshness_result_hash', v_batch.freshness_result_hash,
            'freshness_scope_hash', v_batch.freshness_scope_hash,
            'schedule_kind', v_batch.schedule_kind,
            'scheduled_at_utc', v_batch.scheduled_at_utc,
            'active_authorisation', (
                SELECT pg_catalog.jsonb_build_object(
                    'auth_request_id', auth_row.id, 'state', auth_row.state,
                    'required_quantity', auth_row.required_quantity,
                    'schedule_kind', auth_row.schedule_kind,
                    'scheduled_at_utc', auth_row.scheduled_at_utc,
                    'execution_intent_json', auth_row.execution_intent_json
                )
                FROM public.pay_batch_auth_requests AS auth_row
                WHERE auth_row.pay_batch_id = v_batch.id
                  AND auth_row.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
                ORDER BY auth_row.created_at_utc DESC, auth_row.id DESC LIMIT 1
            ),
            'change_signal', (
                SELECT pg_catalog.jsonb_build_object(
                    'version', COALESCE(signal_row.version, 0),
                    'payment_status_version', COALESCE(signal_row.payment_status_version, 0),
                    'correction_progress_version', COALESCE(signal_row.correction_progress_version, 0),
                    'overview_version', COALESCE(signal_row.overview_version, 0),
                    'last_changed_at_utc', signal_row.last_changed_at_utc
                )
                FROM public.banking_pay_batch_change_signals AS signal_row
                WHERE signal_row.pay_batch_id = v_batch.id
            ),
            'scope_version_authority', 'banking_pay_batch_change_signals'
        )
    );

    v_expected_snapshot_token := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 1,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'filter', v_filter,
            'sort_key', pg_catalog.upper(COALESCE(
                v_selection #>> '{selection,sort_key}',
                v_selection ->> 'sort_key',
                'STATUS'
            )),
            'sort_direction', pg_catalog.upper(COALESCE(
                v_selection #>> '{selection,sort_direction}',
                v_selection ->> 'sort_direction',
                'ASC'
            ))
        )
    );

    IF v_snapshot_token IS NULL
       OR v_snapshot_token IS DISTINCT FROM v_expected_snapshot_token
       OR (
           v_request.plan_json ->> 'active_batch_scope_hash' IS NOT NULL
           AND v_request.plan_json ->> 'active_batch_scope_hash'
               IS DISTINCT FROM v_active_batch_scope_hash
       ) THEN
        UPDATE public.pay_payment_correction_requests AS stale_request
        SET status = 'CANCELLED',
            cancelled_at_utc = pg_catalog.clock_timestamp(),
            reauth_proof_hash = NULL,
            reauth_expires_at_utc = NULL,
            reauth_consumed_at_utc = NULL,
            updated_at_utc = pg_catalog.clock_timestamp(),
            plan_json = COALESCE(stale_request.plan_json, '{}'::jsonb)
                || pg_catalog.jsonb_build_object(
                    'stale_code', 'SELECTION_STALE',
                    'observed_active_batch_scope_hash', v_active_batch_scope_hash
                )
        WHERE stale_request.id = v_request.id;

        UPDATE public.banking_pay_operations AS stale_operation
        SET status = 'CANCELLED',
            phase = 'COMPLETE',
            runner_state = 'CANCELLED',
            requires_user_action = false,
            result_json = COALESCE(stale_operation.result_json, '{}'::jsonb)
                || pg_catalog.jsonb_build_object(
                    'code', 'SELECTION_STALE',
                    'stale', true
                ),
            completed_at_utc = pg_catalog.clock_timestamp(),
            lease_owner = NULL,
            lease_expires_at_utc = NULL,
            locked_by = NULL,
            lock_expires_at_utc = NULL,
            run_after_utc = NULL,
            updated_at_utc = pg_catalog.clock_timestamp()
        WHERE stale_operation.id = v_operation.id;

        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', v_request.id,
            'operation_id', v_operation.id,
            'phase', 'COMPLETE',
            'page_candidate_count', 0,
            'page_active_item_count', 0,
            'page_source_row_count', 0,
            'page_amount_pence', 0,
            'page_hash', NULL,
            'selection_hash', NULL,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'next_cursor_json', NULL,
            'complete', true,
            'stale', true,
            'code', 'SELECTION_STALE',
            'message', 'Payment status changed. Refresh and select the payments again.'
        );
    END IF;

    v_page_sequence_no := COALESCE((p_cursor_json->>'page_sequence_no')::integer, 1);
    v_cursor_candidate_id := NULLIF(p_cursor_json->>'last_scanned_candidate_id', '')::uuid;
    v_prior_page_hash := COALESCE(
        p_cursor_json->>'prior_page_hash',
        private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
            'version', 1, 'correction_request_id', v_request.id, 'chain', 'PREPARE_SELECTION'
        ))
    );

    IF p_cursor_json IS NOT NULL
       AND p_cursor_json->>'scope_fence' IS DISTINCT FROM v_active_batch_scope_hash THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_SNAPSHOT_STALE'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'SELECTION_STALE')::text;
    END IF;

    SELECT chunk_row.* INTO v_existing_chunk
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = v_operation.id
      AND chunk_row.phase = 'PREPARE_SELECTION'
      AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
      AND chunk_row.sequence_no = v_page_sequence_no;

    IF FOUND THEN
        IF v_existing_chunk.payload_json->>'cursor_hash'
             IS DISTINCT FROM private.pay_payment_correction_sha256_v1(COALESCE(p_cursor_json, '{}'::jsonb))
           OR v_existing_chunk.payload_json->>'scope_fence' IS DISTINCT FROM v_active_batch_scope_hash
           OR v_existing_chunk.result_json->>'prior_page_hash' IS DISTINCT FROM v_prior_page_hash THEN
            RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
              USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
                'code', 'PAGE_DIGEST_MISMATCH', 'page_sequence_no', v_page_sequence_no
              )::text;
        END IF;
        RETURN v_existing_chunk.result_json || pg_catalog.jsonb_build_object(
          'ok', true, 'correction_request_id', v_request.id, 'operation_id', v_operation.id,
          'replayed', true, 'code', CASE WHEN COALESCE((v_existing_chunk.result_json->>'complete')::boolean, false)
            THEN 'SELECTION_READY' ELSE 'SELECTION_PAGE_PREPARED' END
        );
    END IF;

    IF v_page_sequence_no > 1 AND NOT EXISTS (
        SELECT 1 FROM public.banking_pay_operation_chunks AS prior_chunk
        WHERE prior_chunk.operation_id = v_operation.id
          AND prior_chunk.phase = 'PREPARE_SELECTION'
          AND prior_chunk.chunk_type = 'CANDIDATE_SCOPE'
          AND prior_chunk.sequence_no = v_page_sequence_no - 1
          AND prior_chunk.status = 'COMPLETE'
          AND prior_chunk.result_json->>'page_hash' = v_prior_page_hash
          AND prior_chunk.result_json->>'last_scanned_candidate_id' = v_cursor_candidate_id::text
    ) THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'PAGE_DIGEST_MISMATCH', 'page_sequence_no', v_page_sequence_no
          )::text;
    END IF;

    SELECT COALESCE(pg_catalog.sum((prior_chunk.result_json->>'page_candidate_count')::integer), 0)::bigint,
           COALESCE((pg_catalog.array_agg(prior_chunk.result_json->>'selected_chain_hash'
                    ORDER BY prior_chunk.sequence_no DESC))[1],
                    private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
                      'version', 1, 'correction_request_id', v_request.id, 'chain', 'SELECTED'
                    ))),
           COALESCE((pg_catalog.array_agg(prior_chunk.result_json->>'unselected_chain_hash'
                    ORDER BY prior_chunk.sequence_no DESC))[1],
                    private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
                      'version', 1, 'correction_request_id', v_request.id, 'chain', 'UNSELECTED'
                    ))),
           COALESCE((pg_catalog.array_agg(prior_chunk.result_json->>'explicit_id_chain_hash'
                    ORDER BY prior_chunk.sequence_no DESC))[1],
                    private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
                      'version', 1, 'pay_batch_id', v_batch.id, 'chain', 'EXPLICIT_IDS'
                    )))
    INTO v_start_ordinal, v_selected_chain_hash, v_unselected_chain_hash,
         v_explicit_id_chain_hash
    FROM public.banking_pay_operation_chunks AS prior_chunk
    WHERE prior_chunk.operation_id = v_operation.id
      AND prior_chunk.phase = 'PREPARE_SELECTION'
      AND prior_chunk.chunk_type = 'CANDIDATE_SCOPE'
      AND prior_chunk.status = 'COMPLETE'
      AND prior_chunk.sequence_no < v_page_sequence_no;

    SELECT COALESCE(pg_catalog.jsonb_agg(scan_row.id::text ORDER BY scan_row.id), '[]'::jsonb),
           pg_catalog.min(scan_row.id::text)::uuid,
           pg_catalog.max(scan_row.id::text)::uuid,
           pg_catalog.count(*)::integer
    INTO v_scan_candidate_tokens, v_first_scanned_candidate_id,
         v_scan_last_candidate_id, v_scan_candidate_count
    FROM (
        SELECT candidate_row.id
        FROM public.pay_batch_candidates AS candidate_row
        WHERE candidate_row.pay_batch_id = v_batch.id
          AND (v_cursor_candidate_id IS NULL OR candidate_row.id > v_cursor_candidate_id)
          AND (v_mode = 'ALL_MATCHING' OR candidate_row.id::text IN (
            SELECT explicit_token.value
            FROM pg_catalog.jsonb_array_elements_text(
              COALESCE(v_selection->'canonical_explicit_candidate_tokens', '[]'::jsonb)
            ) AS explicit_token(value)
          ))
        ORDER BY candidate_row.id
        LIMIT p_limit
    ) AS scan_row;
    v_scanned_candidate_count := v_scan_candidate_count;

    IF v_requested_action IN ('PRE_BANK_CANCEL','CANCEL_PAYMENT')
       AND v_scan_candidate_count>0 THEN
      v_cancel_reversion_page_proof:=private.pay_workbench_cancel_reversion_proof_core_v1(
        v_request.id,NULL::uuid,NULL::uuid,ARRAY[]::uuid[],'PRE_REQUEST',
        pg_catalog.jsonb_build_object(
          'pay_batch_id',v_batch.id,
          'overlay_proof_mode','REQUEST_OWNED_CONTINUITY',
          'candidate_ids',COALESCE((
            SELECT pg_catalog.jsonb_agg(candidate_row.candidate_id ORDER BY candidate_row.id)
            FROM public.pay_batch_candidates AS candidate_row
            WHERE candidate_row.pay_batch_id=v_batch.id
              AND candidate_row.id::text IN (
                SELECT scan_token.value
                FROM pg_catalog.jsonb_array_elements_text(v_scan_candidate_tokens) AS scan_token(value)
              )
          ),'[]'::jsonb)
        )
      );
      SELECT COALESCE(pg_catalog.jsonb_object_agg(
               proof_row.value->>'candidate_id',proof_row.value
               ORDER BY proof_row.value->>'candidate_id'),'{}'::jsonb)
      INTO v_cancel_reversion_page_authorities_v3
      FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_cancel_reversion_page_proof->'candidate_results','[]'::jsonb)
      ) AS proof_row(value);
      v_cancel_reversion_page_authority_hash:=private.pay_payment_correction_sha256_v1(
        v_cancel_reversion_page_authorities_v3);
    ELSE
      v_cancel_reversion_page_authorities_v3:='{}'::jsonb;
      v_cancel_reversion_page_authority_hash:=private.pay_payment_correction_sha256_v1('{}'::jsonb);
    END IF;

    FOR v_candidate IN
        SELECT candidate_row.id AS pay_batch_candidate_id,
               candidate_row.candidate_id,
               candidate_row.candidate_display_name,
               candidate_row.net_bank_amount,
               candidate_row.settlement_status,
               (
                 SELECT work_row.status
                 FROM public.pay_payment_correction_work_items AS work_row
                 WHERE work_row.pay_batch_id = v_batch.id
                   AND work_row.pay_batch_candidate_id = candidate_row.id
                 ORDER BY work_row.created_at_utc DESC, work_row.id DESC
                 LIMIT 1
               ) AS latest_work_status
        FROM public.pay_batch_candidates AS candidate_row
        WHERE candidate_row.pay_batch_id = v_batch.id
          AND candidate_row.id::text IN (
            SELECT scan_token.value
            FROM pg_catalog.jsonb_array_elements_text(v_scan_candidate_tokens) AS scan_token(value)
          )
        ORDER BY candidate_row.id
    LOOP
        v_last_candidate_id := v_candidate.pay_batch_candidate_id;
        v_candidate_pre_request_authority:=COALESCE(
          v_cancel_reversion_page_authorities_v3->v_candidate.candidate_id::text,
          '{}'::jsonb);
        SELECT
            pg_catalog.array_agg(item_row.id ORDER BY item_row.id),
            pg_catalog.count(*)::integer,
            COALESCE(pg_catalog.sum(item_row.amount_inc_vat), 0)::numeric(14,2),
            private.pay_payment_correction_sha256_v1(
                pg_catalog.jsonb_build_object(
                    'transfer_ids',
                    COALESCE(
                        pg_catalog.jsonb_agg(
                            DISTINCT item_row.pay_bank_transfer_id
                        ) FILTER (WHERE item_row.pay_bank_transfer_id IS NOT NULL),
                        '[]'::jsonb
                    )
                )
            )
        INTO v_item_ids, v_item_count, v_amount, v_shared_instruction_scope_hash
        FROM public.pay_batch_items AS item_row
        WHERE item_row.pay_batch_candidate_id = v_candidate.pay_batch_candidate_id
          AND COALESCE(item_row.is_voided, false) IS NOT TRUE;

        -- The reviewed payment amount is the frozen candidate bank payment,
        -- not a gross sum of PAYE source items. The item identities and their
        -- frozen values remain independently bound into candidate_scope_hash.
        v_amount := pg_catalog.round(
            GREATEST(COALESCE(v_candidate.net_bank_amount, 0), 0),
            2
        )::numeric(14,2);

        IF v_item_count < 1 AND v_mode = 'EXPLICIT' THEN
            RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_EMPTY_CANDIDATE'
                USING ERRCODE = 'P0001',
                      DETAIL = pg_catalog.jsonb_build_object(
                          'code', 'SELECTION_STALE',
                          'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id
                      )::text;
        END IF;

        IF v_item_count < 1 THEN
            v_candidate_audit_hash := private.pay_payment_correction_sha256_v1(
              pg_catalog.jsonb_build_object(
                'version', 1, 'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id,
                'candidate_id', v_candidate.candidate_id,
                'net_bank_amount_pence', pg_catalog.round(COALESCE(v_candidate.net_bank_amount, 0) * 100)::bigint,
                'settlement_status', v_candidate.settlement_status, 'pay_batch_item_ids', '[]'::jsonb
              )
            );
            v_unselected_chain_hash := private.pay_payment_correction_sha256_v1(
              pg_catalog.jsonb_build_object('prior', v_unselected_chain_hash,
                                             'candidate_hash', v_candidate_audit_hash)
            );
            CONTINUE;
        END IF;

        v_candidate_selection_json := pg_catalog.jsonb_build_object(
            'scope_type', 'CANDIDATES',
            'work_unit', 'CANDIDATE',
            'pay_batch_candidate_ids', pg_catalog.jsonb_build_array(v_candidate.pay_batch_candidate_id),
            'pay_batch_item_ids', pg_catalog.to_jsonb(v_item_ids)
        );

        v_candidate_selected_scope_json := pg_catalog.jsonb_build_object(
            'scope_type', 'CANDIDATES',
            'work_unit', 'CANDIDATE',
            'pay_batch_ids', pg_catalog.jsonb_build_array(v_batch.id),
            'pay_batch_candidate_ids', pg_catalog.jsonb_build_array(v_candidate.pay_batch_candidate_id),
            'candidate_ids', pg_catalog.jsonb_build_array(v_candidate.candidate_id),
            'pay_batch_item_ids', pg_catalog.to_jsonb(v_item_ids),
            'umbrella_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT item_scope.umbrella_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.umbrella_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'finance_case_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT item_scope.finance_case_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.finance_case_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'finance_component_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT item_scope.finance_component_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.finance_component_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'reservation_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT item_scope.reservation_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.reservation_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'pay_bank_transfer_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT item_scope.pay_bank_transfer_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.pay_bank_transfer_id IS NOT NULL
                    UNION
                    SELECT DISTINCT advance_scope.payout_transfer_id::text AS value_text
                    FROM public.pay_advances AS advance_scope
                    JOIN public.pay_batch_items AS item_scope ON item_scope.finance_case_id = advance_scope.id
                    WHERE item_scope.id = ANY(v_item_ids) AND advance_scope.payout_transfer_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'payout_transfer_ids', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT advance_scope.payout_transfer_id::text AS value_text
                    FROM public.pay_advances AS advance_scope
                    JOIN public.pay_batch_items AS item_scope ON item_scope.finance_case_id = advance_scope.id
                    WHERE item_scope.id = ANY(v_item_ids) AND advance_scope.payout_transfer_id IS NOT NULL
                    UNION
                    SELECT DISTINCT item_scope.pay_bank_transfer_id::text AS value_text
                    FROM public.pay_batch_items AS item_scope
                    WHERE item_scope.id = ANY(v_item_ids) AND item_scope.pay_bank_transfer_id IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb),
            'transfer_group_keys', COALESCE((
                SELECT pg_catalog.jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
                FROM (
                    SELECT DISTINCT transfer_scope.transfer_group_key AS value_text
                    FROM public.pay_bank_transfers AS transfer_scope
                    WHERE transfer_scope.id IN (
                        SELECT item_scope.pay_bank_transfer_id
                        FROM public.pay_batch_items AS item_scope
                        WHERE item_scope.id = ANY(v_item_ids) AND item_scope.pay_bank_transfer_id IS NOT NULL
                    )
                      AND NULLIF(pg_catalog.btrim(COALESCE(transfer_scope.transfer_group_key, '')), '') IS NOT NULL
                ) AS scope_value
            ), '[]'::jsonb)
        );

        WITH selected_items AS (
            SELECT item_scope.*
            FROM public.pay_batch_items AS item_scope
            WHERE item_scope.id = ANY(v_item_ids)
        ), transfer_ids AS (
            SELECT selected_item.pay_bank_transfer_id AS id
            FROM selected_items AS selected_item
            WHERE selected_item.pay_bank_transfer_id IS NOT NULL
            UNION
            SELECT advance_scope.payout_transfer_id
            FROM public.pay_advances AS advance_scope
            JOIN selected_items AS selected_item ON selected_item.finance_case_id = advance_scope.id
            WHERE advance_scope.payout_transfer_id IS NOT NULL
        ), transfer_groups AS (
            SELECT DISTINCT transfer_scope.transfer_group_key
            FROM public.pay_bank_transfers AS transfer_scope
            WHERE transfer_scope.id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id)
              AND NULLIF(pg_catalog.btrim(COALESCE(transfer_scope.transfer_group_key, '')), '') IS NOT NULL
        ), financial_scope_items AS (
            SELECT DISTINCT item_scope.id
            FROM public.pay_batch_items AS item_scope
            LEFT JOIN public.pay_bank_transfers AS item_transfer
              ON item_transfer.id = item_scope.pay_bank_transfer_id
            WHERE item_scope.id = ANY(v_item_ids)
               OR item_scope.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id)
               OR item_transfer.transfer_group_key IN (
                    SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group
               )
        ), source_counts AS (
            SELECT 1::bigint AS row_count
            UNION ALL SELECT pg_catalog.count(*) FROM financial_scope_items
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_batch_item_breakdowns AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_batch_timesheet_snapshots AS source_row WHERE source_row.pay_batch_id = v_batch.id AND source_row.candidate_id = v_candidate.candidate_id
            UNION ALL SELECT pg_catalog.count(*) FROM public.timesheet_pay_state_history AS source_row WHERE source_row.pay_batch_id = v_batch.id AND source_row.timesheet_id IN (SELECT selected_item.timesheet_id FROM selected_items AS selected_item WHERE selected_item.timesheet_id IS NOT NULL)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_advance_reservations AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_finance_case_components AS source_row WHERE source_row.id IN (SELECT selected_item.finance_component_id FROM selected_items AS selected_item WHERE selected_item.finance_component_id IS NOT NULL)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_manual_adjustment_carry_forwards AS source_row WHERE source_row.source_pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item) OR source_row.target_pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_advances AS source_row WHERE source_row.id IN (SELECT selected_item.finance_case_id FROM selected_items AS selected_item WHERE selected_item.finance_case_id IS NOT NULL)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_bank_transfers AS source_row WHERE source_row.id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.transfer_group_key IN (SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_bank_transfer_events AS source_row WHERE source_row.pay_batch_id = v_batch.id AND (source_row.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.candidate_id = v_candidate.candidate_id)
            UNION ALL SELECT pg_catalog.count(*) FROM public.banking_pay_operation_transfer_scope AS source_row WHERE source_row.pay_batch_id = v_batch.id AND (source_row.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.transfer_group_key IN (SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group))
            UNION ALL SELECT pg_catalog.count(*) FROM public.banking_pay_operation_transfer_scope_items AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
            UNION ALL SELECT pg_catalog.count(*) FROM public.pay_batch_paye_net_inputs AS source_row WHERE source_row.pay_batch_candidate_id = v_candidate.pay_batch_candidate_id
        )
        SELECT COALESCE(pg_catalog.sum(source_count.row_count), 0)::integer
        INTO v_source_row_count
        FROM source_counts AS source_count;

        -- Communications are observed independently. V1 retains the exact
        -- historical combined-count/hash semantics. V2 deliberately keeps
        -- volatile delivery state outside the financial scope contract.
        SELECT pg_catalog.count(*)::integer
        INTO v_matching_queued_count
        FROM public.mail_outbox AS source_row
        CROSS JOIN LATERAL (
            SELECT public._pay_payment_correction_mail_scope_match(
                source_row.id, v_batch.id, v_candidate_selection_json,
                v_candidate_selected_scope_json, false
            ) AS match_result
        ) AS mail_match
        WHERE pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status::text, ''))) = 'QUEUED'
          AND pg_catalog.lower(pg_catalog.concat_ws('|', source_row.type, source_row.email_type, source_row.context_kind, source_row.reference, COALESCE(source_row.payment_scope_json::text, '{}'))) LIKE ANY (ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%'])
          AND COALESCE(NULLIF(mail_match.match_result->>'matched', '')::boolean, false);

        IF v_candidate_scope_contract_version = 1 THEN
            v_source_row_count := v_source_row_count + v_matching_queued_count;
        END IF;

        IF v_item_count > v_max_items_per_candidate
           OR v_source_row_count > v_max_source_rows_per_candidate THEN
            RAISE EXCEPTION 'PAYMENT_CORRECTION_CANDIDATE_SCOPE_TOO_LARGE'
                USING ERRCODE = 'P0001',
                      DETAIL = pg_catalog.jsonb_build_object(
                          'code', 'CANDIDATE_SCOPE_TOO_LARGE',
                          'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id,
                          'active_item_count', v_item_count,
                          'source_row_count', v_source_row_count
                      )::text;
        END IF;

        v_diagnostic := public.pay_payment_cancelability_diagnostic(
            v_batch.id,
            v_candidate_selection_json || pg_catalog.jsonb_build_object(
                'requested_action', v_requested_action
            ),
            v_actor_user_id,
            'PAYMENT_CORRECTION_PLAN'
        );

        v_eligibility_code := COALESCE(
            v_diagnostic ->> 'payment_lifecycle_state',
            'UNKNOWN'
        );
        v_action_allowed := CASE
            WHEN v_requested_action = 'DRAFT_CANCEL' THEN
                v_batch.status = 'DRAFT'
                AND COALESCE(
                    (v_diagnostic ->> 'can_pre_provider_cancel')::boolean,
                    false
                )
                -- A terminal outcome from an older Draft-cancellation attempt is
                -- historical evidence, not current payment authority.  The exact
                -- candidate diagnostic above has just re-proved the complete
                -- frozen scope and every provider/rail/settlement fence.  Let that
                -- current proof govern a fresh Draft retry.  Scheduled and
                -- executed-not-paid cancellation retain their historical-work
                -- fences in the next branch.
            WHEN v_requested_action IN ('PRE_BANK_CANCEL', 'CANCEL_PAYMENT') THEN
                COALESCE(
                    (v_diagnostic ->> 'can_pre_provider_cancel')::boolean,
                    false
                )
                AND v_candidate.latest_work_status IS DISTINCT FROM 'BLOCKED'
                AND v_candidate.latest_work_status IS DISTINCT FROM 'FAILED_FINAL'
                AND v_candidate.latest_work_status IS DISTINCT FROM 'FAILED_RETRYABLE'
            WHEN v_requested_action IN ('NO_MONEY_RELEASE', 'NO_MONEY_UNWIND') THEN
                COALESCE(
                    (v_diagnostic ->> 'can_no_money_unwind')::boolean,
                    false
                )
                AND v_candidate.latest_work_status IS DISTINCT FROM 'BLOCKED'
                AND v_candidate.latest_work_status IS DISTINCT FROM 'FAILED_FINAL'
                AND v_candidate.latest_work_status IS DISTINCT FROM 'FAILED_RETRYABLE'
            ELSE false
        END;

        -- Current Payment Status and immutable preparation must interpret the
        -- reviewed status filter identically.  A fresh Draft retry uses the
        -- exact current diagnostic above; other actions preserve historical
        -- correction outcomes before no-money eligibility.
        v_effective_display_state := CASE
            WHEN v_requested_action = 'DRAFT_CANCEL' AND v_action_allowed THEN 'ACTIVE'
            WHEN v_candidate.latest_work_status = 'BLOCKED' THEN 'BLOCKED'
            WHEN v_candidate.latest_work_status IN ('FAILED_FINAL', 'FAILED_RETRYABLE') THEN 'FAILED'
            WHEN COALESCE((v_diagnostic ->> 'can_no_money_unwind')::boolean, false) THEN 'NOT_PAID'
            ELSE 'ACTIVE'
        END;

        IF v_action_allowed IS NOT TRUE AND v_mode = 'EXPLICIT' THEN
            RAISE EXCEPTION 'PAYMENT_CORRECTION_ACTION_NOT_COMMON'
                USING ERRCODE = 'P0001',
                      DETAIL = pg_catalog.jsonb_build_object(
                          'code', 'ACTION_NOT_COMMON',
                          'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id,
                          'eligibility_code', v_eligibility_code
                      )::text;
        END IF;

        v_candidate_scope_hash := private.pay_payment_correction_sha256_v1(
            pg_catalog.jsonb_build_object(
                'version', v_candidate_scope_hash_version,
                'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id,
                'candidate_id', v_candidate.candidate_id,
                'requested_action', v_requested_action,
                'pay_batch_item_ids', pg_catalog.to_jsonb(v_item_ids),
                'item_count', v_item_count,
                'source_row_count', v_source_row_count,
                'active_amount_pence', pg_catalog.round(v_amount * 100)::bigint,
                'item_contract', (
                    SELECT pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'id', item_row.id,
                            'item_type', item_row.item_type,
                            'amount_ex_vat_pence', pg_catalog.round(
                                COALESCE(item_row.amount_ex_vat, 0) * 100
                            )::bigint,
                            'amount_vat_pence', pg_catalog.round(
                                COALESCE(item_row.amount_vat, 0) * 100
                            )::bigint,
                            'amount_inc_vat_pence', pg_catalog.round(
                                COALESCE(item_row.amount_inc_vat, 0) * 100
                            )::bigint,
                            'reservation_id', item_row.reservation_id,
                            'finance_component_id', item_row.finance_component_id,
                            'pay_bank_transfer_id', item_row.pay_bank_transfer_id,
                            'operation_source_key', item_row.operation_source_key,
                            'frozen_component_snapshot_json', item_row.frozen_component_snapshot_json,
                            'frozen_source_basis_json', item_row.frozen_source_basis_json
                        )
                        ORDER BY item_row.id
                    )
                    FROM public.pay_batch_items AS item_row
                    WHERE item_row.id = ANY(v_item_ids)
                ),
                'shared_instruction_scope_hash', v_shared_instruction_scope_hash,
                'eligibility_code', v_eligibility_code,
                'cancellation_reversion_pre_request_authority_digest',
                  v_candidate_pre_request_authority->>'authority_digest'
            ) || CASE
                WHEN v_candidate_scope_contract_version = 2 THEN
                    pg_catalog.jsonb_build_object(
                        'contract', 'PAYMENT_CORRECTION_CANDIDATE_SCOPE_V2',
                        'source_row_count_semantics', 'FINANCIAL_ONLY'
                    )
                ELSE '{}'::jsonb
            END
        );

        -- Boundary-independent audit chain.  Each candidate contributes one
        -- digest, so replay/finalisation may use different bounded page sizes
        -- without reconstructing a whole-request JSON value.
        v_candidate_audit_hash := private.pay_payment_correction_sha256_v1(
          pg_catalog.jsonb_build_object(
            'version', 1,
            'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id,
            'candidate_id', v_candidate.candidate_id,
            'net_bank_amount_pence', pg_catalog.round(COALESCE(v_candidate.net_bank_amount, 0) * 100)::bigint,
            'settlement_status', v_candidate.settlement_status,
            'item_state', COALESCE((
              SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
                item_row.id, item_row.item_type, COALESCE(item_row.is_voided, false),
                pg_catalog.round(COALESCE(item_row.amount_ex_vat, 0) * 100)::bigint,
                pg_catalog.round(COALESCE(item_row.amount_vat, 0) * 100)::bigint,
                pg_catalog.round(COALESCE(item_row.amount_inc_vat, 0) * 100)::bigint,
                item_row.reservation_id, item_row.finance_component_id,
                item_row.pay_bank_transfer_id, item_row.operation_source_key
              ) ORDER BY item_row.id)
              FROM public.pay_batch_items AS item_row
              WHERE item_row.pay_batch_candidate_id = v_candidate.pay_batch_candidate_id
            ), '[]'::jsonb),
            'reservation_state', COALESCE((
              SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
                reservation_row.id, reservation_row.pay_batch_item_id,
                reservation_row.status, reservation_row.committed_at_utc,
                reservation_row.settled_at_utc, reservation_row.released_at_utc
              ) ORDER BY reservation_row.id)
              FROM public.pay_advance_reservations AS reservation_row
              WHERE reservation_row.pay_batch_item_id = ANY(v_item_ids)
            ), '[]'::jsonb),
            'transfer_state', COALESCE((
              SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
                transfer_row.id, transfer_row.status, transfer_row.rail_state,
                transfer_row.request_id, transfer_row.rail_tx_id,
                transfer_row.transfer_group_key
              ) ORDER BY transfer_row.id)
              FROM public.pay_bank_transfers AS transfer_row
              WHERE transfer_row.id IN (
                SELECT item_row.pay_bank_transfer_id
                FROM public.pay_batch_items AS item_row
                WHERE item_row.id = ANY(v_item_ids)
                  AND item_row.pay_bank_transfer_id IS NOT NULL
              )
            ), '[]'::jsonb)
          )
        );

        IF v_mode = 'ALL_MATCHING' AND (
             v_action_allowed IS NOT TRUE
             OR EXISTS (
               SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
                 COALESCE(v_selection#>'{selection,exclusions}', v_selection->'exclusions', '[]'::jsonb)
               ) AS excluded_token(value)
               WHERE excluded_token.value = v_candidate.pay_batch_candidate_id::text
             )
             OR (
               NULLIF(pg_catalog.btrim(v_filter->>'search'), '') IS NOT NULL
               AND pg_catalog.lower(v_candidate.candidate_display_name)
                   NOT LIKE '%' || pg_catalog.lower(pg_catalog.btrim(v_filter->>'search')) || '%'
             )
             OR (
               NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter->>'pay_channel')), '') = 'PAYE'
               AND NOT EXISTS (
                 SELECT 1 FROM public.pay_batch_items AS channel_item
                 WHERE channel_item.id = ANY(v_item_ids)
                   AND pg_catalog.upper(COALESCE(channel_item.pay_channel, '')) = 'PAYE'
               )
             )
              OR (
                NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter->>'status')), '') IS NOT NULL
                AND pg_catalog.upper(pg_catalog.btrim(v_filter->>'status'))
                    IS DISTINCT FROM v_effective_display_state
              )
           ) THEN
            v_unselected_chain_hash := private.pay_payment_correction_sha256_v1(
              pg_catalog.jsonb_build_object('prior', v_unselected_chain_hash,
                                             'candidate_hash', v_candidate_audit_hash)
            );
            CONTINUE;
        END IF;

        v_selected_chain_hash := private.pay_payment_correction_sha256_v1(
          pg_catalog.jsonb_build_object('prior', v_selected_chain_hash,
                                         'candidate_hash', v_candidate_scope_hash)
        );
        IF v_mode = 'EXPLICIT' THEN
          v_explicit_id_chain_hash := private.pay_payment_correction_sha256_v1(
            pg_catalog.jsonb_build_object(
              'prior', v_explicit_id_chain_hash,
              'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id::text
            )
          );
        END IF;

        INSERT INTO public.pay_payment_correction_request_candidates (
            correction_request_id,
            selection_ordinal,
            pay_batch_candidate_id,
            candidate_scope_hash,
            active_item_count,
            source_row_count,
            active_amount,
            pay_batch_item_ids,
            shared_instruction_scope_hash,
            eligibility_code_at_plan,
            created_at_utc
        )
        VALUES (
            v_request.id,
            v_start_ordinal + v_page_candidate_count + 1,
            v_candidate.pay_batch_candidate_id,
            v_candidate_scope_hash,
            v_item_count,
            v_source_row_count,
            v_amount,
            v_item_ids,
            v_shared_instruction_scope_hash,
            v_eligibility_code,
            pg_catalog.clock_timestamp()
        )
        ON CONFLICT (correction_request_id, pay_batch_candidate_id)
        DO NOTHING;

        IF NOT FOUND THEN
            IF NOT EXISTS (
                SELECT 1
                FROM public.pay_payment_correction_request_candidates AS existing_member
                WHERE existing_member.correction_request_id = v_request.id
                  AND existing_member.pay_batch_candidate_id = v_candidate.pay_batch_candidate_id
                  AND existing_member.candidate_scope_hash = v_candidate_scope_hash
                  AND existing_member.active_item_count = v_item_count
                  AND existing_member.source_row_count = v_source_row_count
                  AND existing_member.active_amount = v_amount
                  AND existing_member.pay_batch_item_ids = v_item_ids
            ) THEN
                RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
                    USING ERRCODE = 'P0001',
                          DETAIL = pg_catalog.jsonb_build_object(
                              'code', 'PAGE_DIGEST_MISMATCH',
                              'pay_batch_candidate_id', v_candidate.pay_batch_candidate_id
                          )::text;
            END IF;
        ELSE
            v_page_candidate_count := v_page_candidate_count + 1;
            v_page_active_item_count := v_page_active_item_count + v_item_count;
            v_page_source_row_count := v_page_source_row_count + v_source_row_count;
            v_page_matching_queued_count := v_page_matching_queued_count + v_matching_queued_count;
            v_page_amount_pence := v_page_amount_pence
                + pg_catalog.round(v_amount * 100)::bigint;
        END IF;

        v_last_candidate_id := v_candidate.pay_batch_candidate_id;
    END LOOP;

    IF v_mode = 'ALL_MATCHING' THEN
        -- The durable cursor advances over the bounded identity scan, including
        -- filtered or excluded candidates. Membership still contains only rows
        -- returned by the canonical status/action classifier.
        v_last_candidate_id := COALESCE(
            v_scan_last_candidate_id,
            v_cursor_candidate_id
            );
        END IF;

    v_page_hash := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 1,
            'correction_request_id', v_request.id,
            'operation_id', v_operation.id,
            'page_sequence_no', v_page_sequence_no,
            'prior_page_hash', v_prior_page_hash,
            'scope_fence', v_active_batch_scope_hash,
            'first_scanned_candidate_id', v_first_scanned_candidate_id,
            'last_scanned_candidate_id', v_scan_last_candidate_id,
            'scanned_candidate_count', v_scanned_candidate_count,
            'selected_chain_hash', v_selected_chain_hash,
            'unselected_chain_hash', v_unselected_chain_hash,
            'explicit_id_chain_hash', v_explicit_id_chain_hash,
            'cancellation_reversion_page_authority_hash',v_cancel_reversion_page_authority_hash,
            'page_members', (
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_build_array(
                        member_row.selection_ordinal,
                        member_row.pay_batch_candidate_id,
                        member_row.candidate_scope_hash,
                        member_row.active_item_count,
                        member_row.source_row_count,
                        pg_catalog.round(member_row.active_amount * 100)::bigint,
                        member_row.shared_instruction_scope_hash,
                        member_row.eligibility_code_at_plan
                    )
                    ORDER BY member_row.selection_ordinal
                )
                FROM public.pay_payment_correction_request_candidates AS member_row
                WHERE member_row.correction_request_id = v_request.id
                  AND member_row.selection_ordinal > v_start_ordinal
            )
        ) || CASE
            WHEN v_candidate_scope_contract_version = 2 THEN
                pg_catalog.jsonb_build_object(
                    'candidate_scope_contract_version', 2,
                    'candidate_scope_hash_version', 2,
                    'source_row_count_semantics', 'FINANCIAL_ONLY',
                    'communication_cleanup_contract_version', 1,
                    'page_matching_queued_count_observed', v_page_matching_queued_count
                )
            ELSE '{}'::jsonb
        END
    );
    v_sequence_no := v_page_sequence_no;

    INSERT INTO public.banking_pay_operation_chunks (
        operation_id,
        phase,
        chunk_type,
        sequence_no,
        status,
        payload_json,
        result_json,
        error_json,
        unit_count,
        completed_count,
        failed_count,
        locked_by,
        lock_expires_at_utc,
        started_at_utc,
        completed_at_utc
    )
    VALUES (
        v_operation.id,
        'PREPARE_SELECTION',
        'CANDIDATE_SCOPE',
        v_sequence_no,
        'COMPLETE',
        pg_catalog.jsonb_build_object(
            'cursor_json', p_cursor_json,
            'cursor_hash', private.pay_payment_correction_sha256_v1(COALESCE(p_cursor_json, '{}'::jsonb)),
            'scope_fence', v_active_batch_scope_hash,
            'prior_page_hash', v_prior_page_hash,
            'limit', p_limit
        ),
        pg_catalog.jsonb_build_object(
            'page_sequence_no', v_page_sequence_no,
            'prior_page_hash', v_prior_page_hash,
            'first_scanned_candidate_id', v_first_scanned_candidate_id,
            'last_scanned_candidate_id', v_scan_last_candidate_id,
            'page_candidate_count', v_page_candidate_count,
            'scanned_candidate_count', v_scanned_candidate_count,
            'page_active_item_count', v_page_active_item_count,
            'page_source_row_count', v_page_source_row_count,
            'page_matching_queued_count_observed', v_page_matching_queued_count,
            'candidate_scope_contract_version', v_candidate_scope_contract_version,
            'candidate_scope_hash_version', v_candidate_scope_hash_version,
            'source_row_count_semantics', v_source_row_count_semantics,
            'communication_cleanup_contract_version', v_communication_cleanup_contract_version,
            'page_amount_pence', v_page_amount_pence,
            'selected_chain_hash', v_selected_chain_hash,
            'unselected_chain_hash', v_unselected_chain_hash,
            'explicit_id_chain_hash', v_explicit_id_chain_hash,
            'cancellation_reversion_pre_request_authorities_v3',
              v_cancel_reversion_page_authorities_v3,
            'cancellation_reversion_page_authority_hash',
              v_cancel_reversion_page_authority_hash,
            'page_hash', v_page_hash,
            'last_pay_batch_candidate_id', v_scan_last_candidate_id
        ),
        NULL,
        v_page_candidate_count,
        v_page_candidate_count,
        0,
        p_worker_id,
        NULL,
        pg_catalog.clock_timestamp(),
        pg_catalog.clock_timestamp()
    )
    ON CONFLICT (operation_id, phase, chunk_type, sequence_no) DO NOTHING;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'PAGE_DIGEST_MISMATCH', 'page_sequence_no', v_page_sequence_no
        )::text;
    END IF;

    IF v_mode = 'ALL_MATCHING' THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.pay_batch_candidates AS remaining_candidate
            WHERE remaining_candidate.pay_batch_id = v_batch.id
              AND (
                  v_last_candidate_id IS NULL
                  OR remaining_candidate.id > v_last_candidate_id
              )
        )
        INTO v_has_more;
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.pay_batch_candidates AS remaining_candidate
        WHERE remaining_candidate.pay_batch_id = v_batch.id
          AND (v_scan_last_candidate_id IS NULL OR remaining_candidate.id > v_scan_last_candidate_id)
          AND remaining_candidate.id::text IN (
            SELECT explicit_token.value
            FROM pg_catalog.jsonb_array_elements_text(
              COALESCE(v_selection->'canonical_explicit_candidate_tokens', '[]'::jsonb)
            ) AS explicit_token(value)
          )
      ) INTO v_has_more;
    END IF;

    v_complete := NOT v_has_more;
    v_next_cursor_json := CASE
        WHEN v_complete OR v_scan_last_candidate_id IS NULL THEN NULL
        ELSE pg_catalog.jsonb_build_object(
            'page_sequence_no', v_page_sequence_no + 1,
            'last_scanned_candidate_id', v_scan_last_candidate_id,
            'prior_page_hash', v_page_hash,
            'scope_fence', v_active_batch_scope_hash
        )
    END;

    UPDATE public.banking_pay_operation_chunks AS completed_page
    SET result_json = completed_page.result_json || pg_catalog.jsonb_build_object(
          'next_cursor_json', v_next_cursor_json,
          'complete', v_complete
        )
    WHERE completed_page.operation_id = v_operation.id
      AND completed_page.phase = 'PREPARE_SELECTION'
      AND completed_page.chunk_type = 'CANDIDATE_SCOPE'
      AND completed_page.sequence_no = v_page_sequence_no;

    -- Totals are reduced from at most 200 durable page summaries.  The final
    -- page does not scan or aggregate the complete membership identity set.
    SELECT
        COALESCE(pg_catalog.sum((page_chunk.result_json->>'page_candidate_count')::integer), 0)::integer,
        COALESCE(pg_catalog.sum((page_chunk.result_json->>'page_active_item_count')::integer), 0)::integer,
        COALESCE(pg_catalog.sum((page_chunk.result_json->>'page_source_row_count')::integer), 0)::integer,
        COALESCE(pg_catalog.sum(COALESCE((page_chunk.result_json->>'page_matching_queued_count_observed')::integer, 0)), 0)::integer,
        (COALESCE(pg_catalog.sum((page_chunk.result_json->>'page_amount_pence')::bigint), 0)::numeric / 100)::numeric(14,2)
    INTO
        v_total_candidate_count,
        v_total_active_item_count,
        v_total_source_row_count,
        v_total_matching_queued_count,
        v_total_amount
    FROM public.banking_pay_operation_chunks AS page_chunk
    WHERE page_chunk.operation_id = v_operation.id
      AND page_chunk.phase = 'PREPARE_SELECTION'
      AND page_chunk.chunk_type = 'CANDIDATE_SCOPE'
      AND page_chunk.status = 'COMPLETE';

    IF v_total_candidate_count > v_max_candidates
       OR v_total_active_item_count > v_max_active_items THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_CAPACITY_EXCEEDED'
            USING ERRCODE = 'P0001',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'SELECTION_CAPACITY_EXCEEDED',
                      'selected_candidate_count', v_total_candidate_count,
                      'selected_active_item_count', v_total_active_item_count
                  )::text;
    END IF;

    IF v_complete THEN
        IF v_total_candidate_count < 1 THEN
            RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_EMPTY'
                USING ERRCODE = 'P0001',
                      DETAIL = pg_catalog.jsonb_build_object(
                          'code', 'DESCRIPTOR_INVALID'
                      )::text;
        END IF;

        -- The final reducer reads only the bounded page summaries.  It proves a
        -- contiguous page/hash chain and never rebuilds all item identities.
        WITH ordered_prepare_pages AS (
          SELECT chunk_row.sequence_no,
                 chunk_row.result_json,
                 pg_catalog.row_number() OVER (ORDER BY chunk_row.sequence_no)::integer
                   AS expected_sequence_no,
                 pg_catalog.lag(chunk_row.result_json->>'page_hash')
                   OVER (ORDER BY chunk_row.sequence_no) AS previous_page_hash
          FROM public.banking_pay_operation_chunks AS chunk_row
          WHERE chunk_row.operation_id = v_operation.id
            AND chunk_row.phase = 'PREPARE_SELECTION'
            AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
            AND chunk_row.status = 'COMPLETE'
        )
        SELECT pg_catalog.count(*) FILTER (
                 WHERE ordered_prepare_pages.sequence_no
                         <> ordered_prepare_pages.expected_sequence_no
                    OR (ordered_prepare_pages.sequence_no > 1
                        AND ordered_prepare_pages.result_json->>'prior_page_hash'
                          IS DISTINCT FROM ordered_prepare_pages.previous_page_hash)
               )::integer
        INTO v_page_chain_mismatch_count
        FROM ordered_prepare_pages;

        IF v_page_sequence_no > 200 OR v_page_chain_mismatch_count <> 0 OR (
          SELECT pg_catalog.count(*) FROM public.banking_pay_operation_chunks AS chunk_row
          WHERE chunk_row.operation_id = v_operation.id
            AND chunk_row.phase = 'PREPARE_SELECTION'
            AND chunk_row.chunk_type = 'CANDIDATE_SCOPE'
            AND chunk_row.status = 'COMPLETE'
        ) <> v_page_sequence_no THEN
          RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_PAGE_DIGEST_MISMATCH'
            USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAGE_DIGEST_MISMATCH', 'page_sequence_no', v_page_sequence_no
            )::text;
        END IF;

        v_unselected_scope_hash_before := v_unselected_chain_hash;

        IF v_mode = 'EXPLICIT' THEN
          v_requested_explicit_count := COALESCE((v_selection->>'requested_explicit_count')::integer, 0);
          v_requested_explicit_hash := v_selection->>'requested_explicit_hash';
          SELECT pg_catalog.count(*)::integer
          INTO v_actual_explicit_count
          FROM public.pay_payment_correction_request_candidates AS member_row
          WHERE member_row.correction_request_id = v_request.id;
          v_actual_explicit_hash := v_explicit_id_chain_hash;

          SELECT pg_catalog.count(*)::integer INTO v_explicit_missing_count
          FROM (
            SELECT explicit_token.value::uuid AS id
            FROM pg_catalog.jsonb_array_elements_text(
              COALESCE(v_selection->'canonical_explicit_candidate_tokens', '[]'::jsonb)
            ) AS explicit_token(value)
            EXCEPT
            SELECT member_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_request_candidates AS member_row
            WHERE member_row.correction_request_id = v_request.id
          ) AS missing_member;

          SELECT pg_catalog.count(*)::integer INTO v_explicit_extra_count
          FROM (
            SELECT member_row.pay_batch_candidate_id
            FROM public.pay_payment_correction_request_candidates AS member_row
            WHERE member_row.correction_request_id = v_request.id
            EXCEPT
            SELECT explicit_token.value::uuid
            FROM pg_catalog.jsonb_array_elements_text(
              COALESCE(v_selection->'canonical_explicit_candidate_tokens', '[]'::jsonb)
            ) AS explicit_token(value)
          ) AS extra_member;

          IF v_requested_explicit_count <> v_actual_explicit_count
             OR v_requested_explicit_hash IS DISTINCT FROM v_actual_explicit_hash
             OR v_explicit_missing_count <> 0 OR v_explicit_extra_count <> 0 THEN
            UPDATE public.pay_payment_correction_requests AS invalid_request
            SET status = 'CANCELLED', cancelled_at_utc = pg_catalog.clock_timestamp(),
                plan_json = COALESCE(invalid_request.plan_json, '{}'::jsonb)
                  || pg_catalog.jsonb_build_object(
                    'stale_code', 'EXPLICIT_SELECTION_MISMATCH',
                    'requested_explicit_count', v_requested_explicit_count,
                    'materialised_explicit_count', v_actual_explicit_count
                  ),
                updated_at_utc = pg_catalog.clock_timestamp()
            WHERE invalid_request.id = v_request.id;
            UPDATE public.banking_pay_operations AS invalid_operation
            SET status = 'CANCELLED', phase = 'COMPLETE', runner_state = 'CANCELLED',
                requires_user_action = false, run_after_utc = NULL,
                result_json = COALESCE(invalid_operation.result_json, '{}'::jsonb)
                  || pg_catalog.jsonb_build_object('code', 'EXPLICIT_SELECTION_MISMATCH'),
                completed_at_utc = pg_catalog.clock_timestamp(),
                lease_owner = NULL, lease_expires_at_utc = NULL,
                locked_by = NULL, lock_expires_at_utc = NULL,
                updated_at_utc = pg_catalog.clock_timestamp()
            WHERE invalid_operation.id = v_operation.id;
            RETURN pg_catalog.jsonb_build_object(
              'ok', false, 'correction_request_id', v_request.id,
              'operation_id', v_operation.id, 'phase', 'COMPLETE',
              'complete', true, 'stale', true, 'code', 'EXPLICIT_SELECTION_MISMATCH',
              'message', 'The exact requested payments could not be frozen. Refresh and select them again.'
            );
          END IF;
        END IF;

        v_selection_hash := private.pay_payment_correction_sha256_v1(
            pg_catalog.jsonb_build_object(
                'version', 2, 'pay_batch_id', v_batch.id,
                'requested_action', v_requested_action,
                'active_batch_scope_hash', v_active_batch_scope_hash,
                'selected_candidate_count', v_total_candidate_count,
                'selected_active_item_count', v_total_active_item_count,
                'selected_source_row_count', v_total_source_row_count,
                'selected_amount_pence', pg_catalog.round(v_total_amount * 100)::bigint,
                'selected_chain_hash', v_selected_chain_hash,
                'unselected_chain_hash', v_unselected_chain_hash,
                'prepare_page_count', v_page_sequence_no
            ) || CASE
                WHEN v_candidate_scope_contract_version = 2 THEN
                    pg_catalog.jsonb_build_object(
                        'candidate_scope_contract_version', 2,
                        'candidate_scope_hash_version', 2,
                        'source_row_count_semantics', 'FINANCIAL_ONLY',
                        'communication_cleanup_contract_version', 1
                    )
                ELSE '{}'::jsonb
            END
        );

        v_plan_json := pg_catalog.jsonb_build_object(
            'contract_version', 2,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'scope_fence_hash', v_active_batch_scope_hash,
            'requested_action', v_requested_action,
            'selected_candidate_count', v_total_candidate_count,
            'selected_active_item_count', v_total_active_item_count,
            'selected_source_row_count', v_total_source_row_count,
            'selected_amount_pence', pg_catalog.round(v_total_amount * 100)::bigint,
            'selection_hash', v_selection_hash,
            'selected_chain_hash', v_selected_chain_hash,
            'unselected_chain_hash', v_unselected_chain_hash,
            'prepare_page_count', v_page_sequence_no,
            'requested_explicit_count', v_requested_explicit_count,
            'requested_explicit_hash', v_requested_explicit_hash,
            'unselected_scope_hash_before', v_unselected_scope_hash_before,
            'selection_ready_at_utc', pg_catalog.clock_timestamp()
        ) || CASE
            WHEN v_candidate_scope_contract_version = 2 THEN
                pg_catalog.jsonb_build_object(
                    'candidate_scope_contract_version', 2,
                    'candidate_scope_hash_version', 2,
                    'source_row_count_semantics', 'FINANCIAL_ONLY',
                    'communication_cleanup_contract_version', 1,
                    'matching_queued_count_observed', v_total_matching_queued_count
                )
            ELSE '{}'::jsonb
        END;
        v_plan_hash := private.pay_payment_correction_sha256_v1(v_plan_json);

        UPDATE public.pay_payment_correction_requests AS ready_request
        SET status = 'PLANNED',
            selection_hash = v_selection_hash,
            plan_json = v_plan_json,
            plan_hash = v_plan_hash,
            updated_at_utc = pg_catalog.clock_timestamp()
        WHERE ready_request.id = v_request.id;

        UPDATE public.banking_pay_operations AS ready_operation
        SET status = 'WAITING_AUTHORISATION',
            phase = 'AWAITING_REAUTHENTICATION',
            progress_json = COALESCE(ready_operation.progress_json, '{}'::jsonb)
                || pg_catalog.jsonb_build_object(
                    'last_scanned_candidate_id', v_scan_last_candidate_id,
                    'selection_cursor_json', NULL,
                    'last_prepare_page_hash', v_page_hash,
                    'selected_candidate_count', v_total_candidate_count,
                    'selected_active_item_count', v_total_active_item_count,
                    'selected_source_row_count', v_total_source_row_count,
                    'matching_queued_count_observed', v_total_matching_queued_count,
                    'candidate_scope_contract_version', v_candidate_scope_contract_version,
                    'source_row_count_semantics', v_source_row_count_semantics,
                    'selected_amount_pence', pg_catalog.round(v_total_amount * 100)::bigint,
                    'selection_hash', v_selection_hash,
                    'phase', 'AWAITING_REAUTHENTICATION'
                ),
            total_units = v_total_candidate_count,
            completed_units = 0,
            current_chunk_index = v_sequence_no,
            chunk_count = v_sequence_no,
            run_after_utc = NULL,
            requires_user_action = true,
            runner_state = 'WAITING_USER',
            resume_reason = 'AWAITING_REAUTHENTICATION',
            lease_owner = NULL,
            lease_expires_at_utc = NULL,
            locked_by = NULL,
            lock_expires_at_utc = NULL,
            updated_at_utc = pg_catalog.clock_timestamp()
        WHERE ready_operation.id = v_operation.id;
    ELSE
        UPDATE public.banking_pay_operations AS paging_operation
        SET progress_json = COALESCE(paging_operation.progress_json, '{}'::jsonb)
                || pg_catalog.jsonb_build_object(
                    'last_scanned_candidate_id', v_scan_last_candidate_id,
                    'selection_cursor_json', v_next_cursor_json,
                    'last_prepare_page_hash', v_page_hash,
                    'prepared_candidate_count', v_total_candidate_count,
                    'prepared_active_item_count', v_total_active_item_count,
                    'prepared_source_row_count', v_total_source_row_count,
                    'matching_queued_count_observed', v_total_matching_queued_count,
                    'candidate_scope_contract_version', v_candidate_scope_contract_version,
                    'source_row_count_semantics', v_source_row_count_semantics,
                    'prepared_amount_pence', pg_catalog.round(v_total_amount * 100)::bigint,
                    'phase', 'PREPARE_SELECTION'
                ),
            current_chunk_index = v_sequence_no,
            chunk_count = v_sequence_no,
            run_after_utc = pg_catalog.clock_timestamp(),
            requires_user_action = false,
            updated_at_utc = pg_catalog.clock_timestamp()
        WHERE paging_operation.id = v_operation.id;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'correction_request_id', v_request.id,
        'operation_id', v_operation.id,
        'phase', CASE
            WHEN v_complete THEN 'AWAITING_REAUTHENTICATION'
            ELSE 'PREPARE_SELECTION'
        END,
        'page_candidate_count', v_page_candidate_count,
        'page_active_item_count', v_page_active_item_count,
        'page_source_row_count', v_page_source_row_count,
        'page_matching_queued_count_observed', v_page_matching_queued_count,
        'candidate_scope_contract_version', v_candidate_scope_contract_version,
        'candidate_scope_hash_version', v_candidate_scope_hash_version,
        'source_row_count_semantics', v_source_row_count_semantics,
        'communication_cleanup_contract_version', v_communication_cleanup_contract_version,
        'page_amount_pence', v_page_amount_pence,
        'page_hash', v_page_hash,
        'selection_hash', v_selection_hash,
        'active_batch_scope_hash', v_active_batch_scope_hash,
        'next_cursor_json', v_next_cursor_json,
        'complete', v_complete,
        'stale', false,
        'code', CASE
            WHEN v_complete THEN 'SELECTION_READY'
            ELSE 'SELECTION_PAGE_PREPARED'
        END,
        'message', CASE
            WHEN v_complete THEN 'The exact payment selection is ready to review.'
            ELSE 'The payment selection is still being prepared.'
        END
    );
EXCEPTION
    WHEN lock_not_available OR query_canceled THEN
        RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_LOCK_TIMEOUT'
            USING ERRCODE = '55P03',
                  DETAIL = pg_catalog.jsonb_build_object(
                      'code', 'SELECTION_LOCK_TIMEOUT',
                      'correction_request_id', p_correction_request_id,
                      'operation_id', p_operation_id
                  )::text;
END;
$function$;

-- pay_payment_correction_status_get_v1(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_payment_correction_status_get_v1(p_correction_request_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '3000ms'
AS $function$
DECLARE
    v_request public.pay_payment_correction_requests%ROWTYPE;
    v_operation public.banking_pay_operations%ROWTYPE;
    v_actor public.tms_users%ROWTYPE;
    v_batch_status text;
    v_operation_envelope jsonb := '{}'::jsonb;
    v_candidate_counts jsonb := '{}'::jsonb;
    v_workbench_refresh jsonb := '{}'::jsonb;
    v_progress jsonb := '{}'::jsonb;
    v_available_actions text[] := ARRAY[]::text[];
    v_user_title text;
    v_user_message text;
    v_request_expired boolean := false;
    v_workbench_session_id uuid;
    v_refresh_group_total integer := 0;
    v_refresh_group_complete integer := 0;
    v_refresh_candidate_count integer := 0;
    v_refresh_failed_count integer := 0;
    v_refresh_pending_count integer := 0;
    v_refresh_ready_count integer := 0;
    v_workbench_status text := 'NOT_STAGED';
    v_progress_stage text := 'PLANNING';
    v_poll_after_ms integer := 1000;
    v_financial_complete boolean := false;
    v_terminal boolean := false;
    v_blockers jsonb := '[]'::jsonb;
    v_is_requester boolean := false;
    v_is_admin boolean := false;
    v_can_authorise boolean := false;
    v_can_use_golden_key boolean := false;
    v_selected_count integer := 0;
    v_completed_count integer := 0;
    v_applied_count integer := 0;
    v_blocked_count integer := 0;
    v_remaining_count integer := 0;
    v_selected_amount_pence bigint := 0;
    v_removed_amount_pence bigint := 0;
    v_remaining_amount_pence bigint := 0;
    v_request_kind text := 'CANCEL_PAYMENT';
    v_refresh_candidate_ids uuid[] := ARRAY[]::uuid[];
    v_physical_currentness jsonb := '{}'::jsonb;
BEGIN
    SELECT request_row.*
    INTO v_request
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.id = p_correction_request_id;

    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'correction_request_id', p_correction_request_id,
            'code', 'REQUEST_NOT_FOUND'
        );
    END IF;

    IF p_actor_user_id IS NOT NULL THEN
        SELECT actor_row.*
        INTO v_actor
        FROM public.tms_users AS actor_row
        WHERE actor_row.id = p_actor_user_id
          AND COALESCE(actor_row.is_active, false);

        IF NOT FOUND THEN
            RETURN pg_catalog.jsonb_build_object(
                'ok', false,
                'correction_request_id', p_correction_request_id,
                'code', 'PERMISSION_DENIED'
            );
        END IF;

        v_is_requester := p_actor_user_id = v_request.requested_by_user_id;
        v_is_admin := pg_catalog.lower(COALESCE(v_actor.role, '')) = 'admin';
        v_can_authorise := COALESCE(v_actor.payment_authoriser, false)
          AND p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id;
        v_can_use_golden_key := COALESCE(v_actor.payment_golden_key, false)
          AND p_actor_user_id IS DISTINCT FROM v_request.requested_by_user_id;

        IF NOT (v_is_requester OR v_is_admin OR v_can_authorise OR v_can_use_golden_key) THEN
            RETURN pg_catalog.jsonb_build_object(
                'ok', false,
                'correction_request_id', p_correction_request_id,
                'code', 'PERMISSION_DENIED'
            );
        END IF;
    END IF;

    v_request_kind := CASE
        WHEN pg_catalog.upper(COALESCE(
            v_request.selection_json->>'requested_action',
            v_request.plan_json->>'requested_action',
            v_request.correction_kind,
            ''
        )) = 'DRAFT_CANCEL' THEN 'DRAFT_CANCEL'
        WHEN pg_catalog.upper(COALESCE(
            v_request.selection_json->>'requested_action',
            v_request.plan_json->>'requested_action',
            v_request.correction_kind,
            ''
        )) IN ('NO_MONEY_RELEASE', 'NO_MONEY_UNWIND') THEN 'RELEASE_FAILED_PAYMENT'
        ELSE 'CANCEL_PAYMENT'
    END;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
      AND operation_row.input_json ->> 'correction_request_id' = p_correction_request_id::text
    ORDER BY operation_row.created_at_utc DESC, operation_row.id DESC
    LIMIT 1;

    IF v_operation.id IS NOT NULL THEN
        v_operation_envelope := public.banking_pay_operation_get(
            v_operation.id,
            p_actor_user_id,
            'PROGRESS_LIGHT'
        );
    END IF;

    SELECT batch_row.status
    INTO v_batch_status
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = v_request.pay_batch_id;

    SELECT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_actions AS expiry_action
        WHERE expiry_action.correction_request_id = p_correction_request_id
          AND expiry_action.action = 'CANCEL'
          AND expiry_action.metadata_json ->> 'audit_code' = 'UNAPPROVED_REQUEST_EXPIRED'
    ) INTO v_request_expired;

    WITH selected_membership AS MATERIALIZED (
        SELECT membership.pay_batch_candidate_id,
               COALESCE(membership.active_amount, 0)::numeric AS active_amount
        FROM public.pay_payment_correction_request_candidates AS membership
        WHERE membership.correction_request_id = p_correction_request_id
    ), latest_work AS MATERIALIZED (
        SELECT DISTINCT ON (work_item.pay_batch_candidate_id)
               work_item.pay_batch_candidate_id,
               work_item.status
        FROM public.pay_payment_correction_work_items AS work_item
        WHERE work_item.correction_request_id = p_correction_request_id
        ORDER BY work_item.pay_batch_candidate_id,
                 work_item.created_at_utc DESC,
                 work_item.id DESC
    )
    SELECT pg_catalog.jsonb_build_object(
               'total', pg_catalog.count(*)::integer,
               'pending', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status IS NULL OR latest_work.status = 'PENDING'
               )::integer,
               'processing', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'PROCESSING'
               )::integer,
               'applied', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'APPLIED'
               )::integer,
               'blocked', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'BLOCKED'
               )::integer,
               'failed_retryable', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'FAILED_RETRYABLE'
               )::integer,
               'failed_final', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'FAILED_FINAL'
               )::integer,
               'cancelled', pg_catalog.count(*) FILTER (
                   WHERE latest_work.status = 'CANCELLED'
               )::integer
           ),
           pg_catalog.count(*)::integer,
           pg_catalog.count(*) FILTER (
               WHERE latest_work.status IN ('APPLIED', 'BLOCKED', 'FAILED_FINAL', 'CANCELLED')
           )::integer,
           pg_catalog.count(*) FILTER (WHERE latest_work.status = 'APPLIED')::integer,
           pg_catalog.count(*) FILTER (WHERE latest_work.status = 'BLOCKED')::integer,
           greatest(
               pg_catalog.count(*) - pg_catalog.count(*) FILTER (
                   WHERE latest_work.status IN ('APPLIED', 'BLOCKED', 'FAILED_FINAL', 'CANCELLED')
               ),
               0
           )::integer,
           COALESCE(pg_catalog.round(pg_catalog.sum(selected_membership.active_amount) * 100), 0)::bigint,
           COALESCE(pg_catalog.round(pg_catalog.sum(selected_membership.active_amount) FILTER (
               WHERE latest_work.status = 'APPLIED'
           ) * 100), 0)::bigint,
           COALESCE(pg_catalog.round(pg_catalog.sum(selected_membership.active_amount) FILTER (
               WHERE latest_work.status IS DISTINCT FROM 'APPLIED'
           ) * 100), 0)::bigint
    INTO v_candidate_counts,
         v_selected_count,
         v_completed_count,
         v_applied_count,
         v_blocked_count,
         v_remaining_count,
         v_selected_amount_pence,
         v_removed_amount_pence,
         v_remaining_amount_pence
    FROM selected_membership
    LEFT JOIN latest_work
      ON latest_work.pay_batch_candidate_id = selected_membership.pay_batch_candidate_id;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'label', blocker_summary.label,
                'count', blocker_summary.blocker_count
            )
            ORDER BY blocker_summary.blocker_count DESC, blocker_summary.label
        ),
        '[]'::jsonb
    )
    INTO v_blockers
    FROM (
        SELECT blocker_source.label, pg_catalog.count(*)::integer AS blocker_count
        FROM (
            SELECT CASE
                WHEN work_item.status = 'BLOCKED'
                    THEN 'Some selected payments are no longer safe to change.'
                WHEN work_item.status = 'FAILED_FINAL'
                    THEN 'CloudTMS could not safely complete some selected payments.'
                ELSE 'Some selected payments require review.'
            END AS label
            FROM public.pay_payment_correction_work_items AS work_item
            WHERE work_item.correction_request_id = p_correction_request_id
              AND work_item.status IN ('BLOCKED', 'FAILED_FINAL')
        ) AS blocker_source
        GROUP BY blocker_source.label
        ORDER BY pg_catalog.count(*) DESC, blocker_source.label
        LIMIT 20
    ) AS blocker_summary;

    IF v_operation.id IS NOT NULL THEN
        SELECT pg_catalog.count(*)::integer,
               pg_catalog.count(*) FILTER (WHERE chunk_row.status = 'COMPLETE')::integer
        INTO v_refresh_group_total, v_refresh_group_complete
        FROM public.banking_pay_operation_chunks AS chunk_row
        WHERE chunk_row.operation_id = v_operation.id
          AND chunk_row.phase = 'REFRESH_WORKBENCH'
          AND chunk_row.chunk_type = 'CANDIDATE_SCOPE';

        v_workbench_session_id := COALESCE(
            v_operation.workbench_session_id,
            (SELECT batch_row.source_workbench_session_id FROM public.pay_batches AS batch_row WHERE batch_row.id = v_request.pay_batch_id)
        );

        WITH refresh_candidates AS (
            SELECT DISTINCT (candidate_token.value #>> '{}')::uuid AS candidate_id
            FROM public.banking_pay_operation_chunks AS refresh_chunk
            CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
                COALESCE(refresh_chunk.payload_json->'candidate_ids', '[]'::jsonb)
            ) AS candidate_token(value)
            WHERE refresh_chunk.operation_id = v_operation.id
              AND refresh_chunk.phase = 'REFRESH_WORKBENCH'
              AND refresh_chunk.chunk_type = 'CANDIDATE_SCOPE'
              AND (candidate_token.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ), candidate_freshness AS (
            SELECT refresh_candidate.candidate_id,
                   pg_catalog.upper(COALESCE(candidate_state.status, 'MISSING')) AS candidate_state,
                   candidate_state.pending_job_id,
                   COALESCE(candidate_state.source_change_seq, 0) AS source_change_seq,
                   pg_catalog.upper(COALESCE(latest_job.status, 'NONE')) AS job_status,
                   COALESCE(latest_job.scope_change_generation, 0) AS job_generation
            FROM refresh_candidates AS refresh_candidate
            LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
              ON candidate_state.session_id = v_workbench_session_id
             AND candidate_state.candidate_id = refresh_candidate.candidate_id
            LEFT JOIN LATERAL (
                SELECT job_row.status, job_row.scope_change_generation
                FROM public.banking_pay_workbench_jobs AS job_row
                WHERE job_row.session_id = v_workbench_session_id
                  AND job_row.candidate_id = refresh_candidate.candidate_id
                ORDER BY job_row.updated_at_utc DESC, job_row.id DESC
                LIMIT 1
            ) AS latest_job ON true
        )
        SELECT pg_catalog.count(*)::integer,
               0::integer,
               0::integer,
               pg_catalog.count(*)::integer
        INTO v_refresh_candidate_count, v_refresh_failed_count, v_refresh_ready_count, v_refresh_pending_count
        FROM candidate_freshness;

        -- Source sequence and scope generation are independent domains; never
        -- compare one to the other.  Re-derive the exact frozen request
        -- membership and ask the shared physical-currentness authority once.
        SELECT COALESCE(pg_catalog.array_agg(DISTINCT work_row.candidate_id ORDER BY work_row.candidate_id),ARRAY[]::uuid[]),
               pg_catalog.count(DISTINCT work_row.candidate_id)::integer
        INTO v_refresh_candidate_ids,v_refresh_candidate_count
        FROM public.pay_payment_correction_request_candidates AS member_row
        JOIN public.pay_payment_correction_work_items AS work_row
          ON work_row.correction_request_id=member_row.correction_request_id
         AND work_row.pay_batch_candidate_id=member_row.pay_batch_candidate_id
        WHERE member_row.correction_request_id=p_correction_request_id
          AND work_row.status='APPLIED' AND work_row.candidate_id IS NOT NULL;

        IF v_workbench_session_id IS NOT NULL AND v_refresh_candidate_count BETWEEN 1 AND 100 THEN
            v_physical_currentness:=private.pay_workbench_candidate_physical_currentness_page_v1(
              v_workbench_session_id,v_refresh_candidate_ids,'TERMINAL_CURRENT',
              pg_catalog.jsonb_build_object('contract_version',1,'allow_active_owner',true)
            );
            v_refresh_ready_count:=COALESCE((v_physical_currentness->>'terminal_current_count')::integer,0);
            v_refresh_pending_count:=COALESCE((v_physical_currentness->>'current_or_active_owner_count')::integer,0)
              -v_refresh_ready_count;
            v_refresh_failed_count:=CASE
              WHEN v_refresh_ready_count+v_refresh_pending_count<v_refresh_candidate_count
                AND v_operation.status IN ('FAILED','REVIEW_REQUIRED','CANCELLED')
              THEN v_refresh_candidate_count-v_refresh_ready_count-v_refresh_pending_count ELSE 0 END;
        END IF;

        v_workbench_status := CASE
            -- The untouched-Draft fast route deliberately creates no
            -- REFRESH_WORKBENCH chunks.  Its final bounded page nevertheless
            -- owns a certified V3 reversion publication and a whole-session
            -- READY proof.  Treat that persisted terminal contract as CURRENT
            -- so the read-only status owner does not leave the UI waiting on
            -- a stage which this route never creates.
            WHEN v_refresh_group_total = 0
              AND v_operation.status = 'COMPLETE'
              AND COALESCE((v_operation.progress_json->>'draft_overlay_fast')::boolean, false)
              AND COALESCE(v_operation.progress_json#>>'{last_fast_draft_page,status}', '') = 'DRAFT_OVERLAY_FAST_COMPLETE'
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,reversion_publication,ok}')::boolean, false)
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,reversion_publication,progress,ready}')::boolean, false)
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,reversion_publication,progress,still_running}')::boolean, false) IS NOT TRUE
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,reversion_publication,progress,pending_refresh}')::boolean, false) IS NOT TRUE
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,full_build_count}')::integer, 0) = 0
              AND COALESCE((v_operation.progress_json#>>'{last_fast_draft_page,reconciliation_count}')::integer, 0) = 0
              THEN 'CURRENT'
            WHEN v_refresh_candidate_count<=100
              AND COALESCE((v_physical_currentness->>'all_terminal_current')::boolean,false)
              THEN 'CURRENT'
            WHEN v_refresh_candidate_count<=100
              AND COALESCE((v_physical_currentness->>'all_current_or_active_owner')::boolean,false)
              THEN 'PENDING'
            WHEN v_refresh_candidate_count>100 AND v_refresh_group_total>0
              AND v_refresh_group_complete=v_refresh_group_total
              AND NOT EXISTS (
                SELECT 1 FROM public.banking_pay_operation_chunks AS current_chunk
                WHERE current_chunk.operation_id=v_operation.id
                  AND current_chunk.phase='REFRESH_WORKBENCH'
                  AND current_chunk.chunk_type='CANDIDATE_SCOPE'
                  AND current_chunk.status='COMPLETE'
                  AND COALESCE((current_chunk.result_json->>'physical_currentness_proven')::boolean,false) IS NOT TRUE
                  AND COALESCE(current_chunk.result_json->>'status','') NOT LIKE 'NOT_REQUIRED%'
              ) THEN 'CURRENT'
            WHEN v_refresh_group_total = 0 THEN 'NOT_STAGED'
            WHEN EXISTS (
                SELECT 1 FROM public.banking_pay_operation_chunks AS failed_chunk
                WHERE failed_chunk.operation_id = v_operation.id
                  AND failed_chunk.phase = 'REFRESH_WORKBENCH'
                  AND failed_chunk.status IN ('FAILED', 'FAILED_FINAL', 'CANCELLED')
            ) OR v_refresh_failed_count > 0 THEN 'FAILED'
            WHEN v_refresh_group_complete < v_refresh_group_total THEN 'STAGED'
            WHEN v_refresh_candidate_count = 0
              OR NOT EXISTS (
                  SELECT 1 FROM public.banking_pay_operation_chunks AS required_chunk
                  WHERE required_chunk.operation_id = v_operation.id
                    AND required_chunk.phase = 'REFRESH_WORKBENCH'
                    AND COALESCE(required_chunk.result_json->>'status', '') NOT LIKE 'NOT_REQUIRED%'
              ) THEN 'CURRENT'
            ELSE 'STAGED'
        END;
    END IF;

    v_workbench_refresh := pg_catalog.jsonb_build_object(
        'status', v_workbench_status,
        'group_total', v_refresh_group_total,
        'group_complete', v_refresh_group_complete,
        'candidate_total', v_refresh_candidate_count,
        'candidate_ready', v_refresh_ready_count,
        'candidate_pending', v_refresh_pending_count,
        'candidate_failed', v_refresh_failed_count
    );

    v_progress := pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
            'total_units', v_operation.total_units,
            'completed_units', v_operation.completed_units,
            'failed_units', v_operation.failed_units,
            'selected_count', v_selected_count,
            'completed_count', v_completed_count,
            'applied_count', v_applied_count,
            'blocked_count', v_blocked_count,
            'remaining_count', v_remaining_count,
            'denominator', v_selected_count,
            'percent', CASE
                WHEN v_request.status IN (
                    'APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED',
                    'FAILED', 'REJECTED', 'CANCELLED'
                ) THEN 100
                WHEN v_selected_count > 0 THEN least(
                    99,
                    pg_catalog.floor(
                        (v_completed_count::numeric * 100) / v_selected_count::numeric
                    )::integer
                )
                ELSE 0
            END,
            'phase_message', v_operation_envelope ->> 'status_text',
            'requires_user_action', COALESCE(v_operation.requires_user_action, false)
        )
    );

    CASE v_request.status
        WHEN 'PLANNING' THEN
            v_user_title := 'Preparing cancellation';
            v_user_message := 'CloudTMS is preparing the exact payments for review.';
            v_available_actions := ARRAY['CANCEL_REQUEST']::text[];
        WHEN 'PLANNED' THEN
            v_user_title := 'Ready to review';
            v_user_message := 'Review the exact payments, then confirm your identity.';
            v_available_actions := ARRAY['REAUTHENTICATE', 'CANCEL_REQUEST']::text[];
        WHEN 'REQUESTED' THEN
            v_user_title := 'Cancellation requested';
            v_user_message := 'The cancellation is awaiting authorisation.';
            v_available_actions := ARRAY['CANCEL_REQUEST']::text[];
        WHEN 'AWAITING_AUTHORISATION' THEN
            v_user_title := 'Awaiting authorisation';
            v_user_message := 'The cancellation is awaiting the configured financial approval.';
            v_available_actions := ARRAY['AUTHORISE', 'REJECT']::text[];
        WHEN 'AUTHORISED' THEN
            v_user_title := 'Cancellation approved and queued';
            v_user_message := 'CloudTMS will process the cancellation safely.';
        WHEN 'EXPANDED' THEN
            v_user_title := 'Cancellation ready to process';
            v_user_message := 'CloudTMS has prepared the cancellation work.';
        WHEN 'PROCESSING' THEN
            v_user_title := CASE
                WHEN v_request_kind = 'RELEASE_FAILED_PAYMENT' THEN 'Releasing failed payments'
                ELSE 'Cancelling payments'
            END;
            v_user_message := CASE
                WHEN v_request_kind = 'RELEASE_FAILED_PAYMENT'
                    THEN 'CloudTMS is releasing the selected failed payments.'
                ELSE 'CloudTMS is processing the selected payments.'
            END;
        WHEN 'APPLIED' THEN
            v_user_title := 'Cancellation complete';
            v_user_message := CASE
                WHEN v_workbench_refresh ->> 'status' = 'CURRENT'
                    THEN 'Payment availability is up to date.'
                ELSE 'Payment availability is refreshing.'
            END;
            IF v_batch_status = 'AWAITING_AUTHORISATION' THEN
                v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
            END IF;
        WHEN 'APPLIED_WITH_BLOCKERS' THEN
            v_user_title := 'Cancellation complete with blockers';
            v_user_message := 'Some selected payments were cancelled. Review the payments that remain active.';
            v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
        WHEN 'BLOCKED' THEN
            v_user_title := 'No payment was cancelled';
            v_user_message := 'Review the payment status and reauthorise the intact batch where permitted.';
            v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
        WHEN 'FAILED' THEN
            v_user_title := 'CloudTMS safely stopped this request';
            v_user_message := 'No further automatic action will be taken. Review the remaining payment scope.';
        WHEN 'REJECTED' THEN
            v_user_title := 'Cancellation rejected';
            v_user_message := 'No payment was changed by this request.';
        WHEN 'CANCELLED' THEN
            v_user_title := 'Cancellation request ended';
            v_user_message := CASE
                WHEN v_request_expired
                    THEN 'This request expired. Refresh Current Payment Status and start again.'
                ELSE 'No further cancellation work will be performed.'
            END;
        ELSE
            v_user_title := 'Payment correction';
            v_user_message := 'Review the current payment status.';
    END CASE;

    -- The status reader is the sole UI action authority.  Build actions for
    -- this actor only; never expose requester proof controls to an authoriser
    -- or approval controls to the maker.
    v_available_actions := ARRAY[]::text[];
    IF p_actor_user_id IS NOT NULL THEN
        CASE v_request.status
            WHEN 'PLANNING' THEN
                IF v_is_requester OR v_is_admin THEN
                    v_available_actions := ARRAY['CANCEL_REQUEST']::text[];
                END IF;
            WHEN 'PLANNED' THEN
                IF v_is_requester THEN
                    v_available_actions := ARRAY['REAUTHENTICATE', 'CANCEL_REQUEST']::text[];
                ELSIF v_is_admin THEN
                    v_available_actions := ARRAY['CANCEL_REQUEST']::text[];
                END IF;
            WHEN 'REQUESTED' THEN
                IF v_can_authorise THEN
                    v_available_actions := v_available_actions || ARRAY['AUTHORISE']::text[];
                END IF;
                IF v_can_use_golden_key THEN
                    v_available_actions := v_available_actions || ARRAY['USE_GOLDEN_KEY']::text[];
                END IF;
                IF v_is_requester OR v_is_admin THEN
                    v_available_actions := v_available_actions || ARRAY['CANCEL_REQUEST']::text[];
                END IF;
                IF v_is_admin AND NOT v_is_requester THEN
                    v_available_actions := v_available_actions || ARRAY['REJECT']::text[];
                END IF;
            WHEN 'AWAITING_AUTHORISATION' THEN
                IF v_can_authorise THEN
                    v_available_actions := v_available_actions || ARRAY['AUTHORISE']::text[];
                END IF;
                IF v_can_use_golden_key THEN
                    v_available_actions := v_available_actions || ARRAY['USE_GOLDEN_KEY']::text[];
                END IF;
                IF v_is_requester OR v_is_admin THEN
                    v_available_actions := v_available_actions || ARRAY['CANCEL_REQUEST']::text[];
                END IF;
                IF v_is_admin AND NOT v_is_requester THEN
                    v_available_actions := v_available_actions || ARRAY['REJECT']::text[];
                END IF;
            WHEN 'APPLIED' THEN
                IF v_batch_status = 'AWAITING_AUTHORISATION'
                   AND (v_is_requester OR v_is_admin OR v_can_authorise) THEN
                    v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
                END IF;
            WHEN 'APPLIED_WITH_BLOCKERS' THEN
                IF v_is_requester OR v_is_admin OR v_can_authorise THEN
                    v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
                END IF;
            WHEN 'BLOCKED' THEN
                IF v_is_requester OR v_is_admin OR v_can_authorise THEN
                    v_available_actions := ARRAY['REAUTHORISE_REMAINING']::text[];
                END IF;
            ELSE
                NULL;
        END CASE;
    END IF;

    v_financial_complete := v_request.status IN (
        'APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED', 'FAILED', 'REJECTED', 'CANCELLED'
    );

    IF v_financial_complete
       AND v_workbench_status='FAILED'
       AND v_operation.status='REVIEW_REQUIRED'
       AND v_operation.runner_state='WAITING_USER_REVIEW'
       AND COALESCE(v_operation.requires_user_action,false)
       AND (v_is_requester OR v_is_admin) THEN
        v_available_actions:=ARRAY['RETRY_PROCESSING']::text[];
        v_user_title:='Payment cancelled — Banking Pay update needs attention';
        v_user_message:='The financial cancellation is complete. Retry only the Banking Pay update.';
    END IF;

    v_progress_stage := CASE
        WHEN v_request.status = 'PLANNING' THEN 'PLANNING'
        WHEN v_request.status = 'PLANNED' THEN 'REVIEW'
        WHEN v_request.status = 'REQUESTED' THEN 'AUTHORISATION'
        WHEN v_request.status = 'AWAITING_AUTHORISATION' THEN 'AUTHORISATION'
        WHEN v_request.status = 'AUTHORISED' THEN 'EXPANDING'
        WHEN v_request.status = 'EXPANDED' THEN 'PROCESSING'
        WHEN v_request.status = 'PROCESSING' AND v_operation.phase = 'FINALISE' THEN 'FINALISING'
        WHEN v_request.status = 'PROCESSING' AND v_operation.phase = 'REFRESH_WORKBENCH' THEN 'REFRESHING_AVAILABILITY'
        WHEN v_request.status = 'PROCESSING' THEN 'PROCESSING'
        WHEN v_request.status = 'APPLIED' AND v_workbench_status <> 'CURRENT' THEN 'REFRESHING_AVAILABILITY'
        WHEN v_request.status = 'APPLIED' THEN 'COMPLETE'
        WHEN v_request.status = 'APPLIED_WITH_BLOCKERS' THEN 'COMPLETE_WITH_BLOCKERS'
        WHEN v_request.status = 'BLOCKED' THEN 'BLOCKED'
        WHEN v_request.status = 'FAILED' THEN 'FAILED'
        WHEN v_request.status = 'REJECTED' THEN 'REJECTED'
        WHEN v_request.status = 'CANCELLED' THEN 'CANCELLED'
        ELSE 'PROCESSING'
    END;

    v_terminal := v_financial_complete
      AND (v_operation.id IS NULL OR v_operation.status IN ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED'))
      AND v_workbench_status IN ('CURRENT', 'FAILED', 'NOT_STAGED');

    v_poll_after_ms := CASE
        WHEN v_terminal THEN NULL
        WHEN v_progress_stage IN ('REVIEW', 'AUTHORISATION', 'REFRESHING_AVAILABILITY') THEN 5000
        ELSE 1000
    END;

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'correction_request_id', v_request.id,
        'pay_batch_id', v_request.pay_batch_id,
        'request_kind', v_request_kind,
        'request_status', v_request.status,
        'progress_stage', v_progress_stage,
        'poll_after_ms', v_poll_after_ms,
        'financial_complete', v_financial_complete,
        'terminal', v_terminal,
        'progress', COALESCE(v_progress, '{}'::jsonb),
        'candidate_counts', COALESCE(v_candidate_counts, '{}'::jsonb),
        'selected_count', v_selected_count,
        'completed_count', v_completed_count,
        'applied_count', v_applied_count,
        'blocked_count', v_blocked_count,
        'remaining_count', v_remaining_count,
        'selected_amount_pence', v_selected_amount_pence,
        'removed_amount_pence', v_removed_amount_pence,
        'remaining_amount_pence', v_remaining_amount_pence,
        'blockers', COALESCE(v_blockers, '[]'::jsonb),
        'workbench_refresh', COALESCE(v_workbench_refresh, '{}'::jsonb),
        'available_actions', v_available_actions,
        'user_title', v_user_title,
        'user_message', v_user_message,
        'continuation', pg_catalog.jsonb_build_object(
            'required', false,
            'reason', 'STATUS_READ_ONLY',
            'successor_relation', 'NONE',
            'requires_user_action', false,
            'terminal', v_terminal
        ),
        'code', 'PAYMENT_CORRECTION_STATUS_OK'
    );
END
$function$;

-- pay_payment_return_admin_notice_dispatch_due(integer)
CREATE OR REPLACE FUNCTION public.pay_payment_return_admin_notice_dispatch_due(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_now timestamptz := now();
  v_recipient_role text := 'ADMIN';
  v_claimed_count integer := 0;
  v_sent_count integer := 0;
  v_failed_count integer := 0;
  v_no_recipient_count integer := 0;
  v_mail_outbox_id uuid;
  v_to_emails text;
  v_subject text;
  v_body_text text;
  v_body_html text;
  v_group_row record;
  v_notice_summary text;
  v_result jsonb := '{}'::jsonb;
  v_notice_reference text;
  v_pay_batch_short text;
  v_blocked_provider text;
  v_blocked_env text;
  v_blocked_account text;
  v_blocked_required text;
  v_blocked_available text;
  v_blocked_status text;
  v_blocked_execution_state text;
  v_blocked_pay_date text;
  v_blocked_bulk_reference text;
  v_blocked_last_funds_checked text;
  v_insert_context_kind text;
  v_insert_context_id uuid;
BEGIN
  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_RETURN_ADMIN_NOTICE_DISPATCH_DUE_START',
    jsonb_build_object(
      'requested_limit', p_limit,
      'effective_limit', v_limit
    ),
    'pay_payment_correction',
    'admin_notice_dispatch_due',
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_return_admin_recipient_role), ''), 'ADMIN')
  INTO v_recipient_role
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_recipient_role := COALESCE(NULLIF(btrim(v_recipient_role), ''), 'ADMIN');

  DROP TABLE IF EXISTS pg_temp._tmp_payment_return_notice_due;
  CREATE TEMP TABLE _tmp_payment_return_notice_due ON COMMIT DROP AS
  WITH due_groups AS (
    SELECT public.pay_payment_return_notice_groups.id
    FROM public.pay_payment_return_notice_groups
    WHERE public.pay_payment_return_notice_groups.status IN ('OPEN', 'READY')
      AND (
        public.pay_payment_return_notice_groups.quiet_until_utc <= v_now
        OR public.pay_payment_return_notice_groups.max_send_at_utc <= v_now
      )
    ORDER BY
      public.pay_payment_return_notice_groups.max_send_at_utc ASC,
      public.pay_payment_return_notice_groups.quiet_until_utc ASC,
      public.pay_payment_return_notice_groups.created_at_utc ASC,
      public.pay_payment_return_notice_groups.id ASC
    FOR UPDATE SKIP LOCKED
    LIMIT v_limit
  ),
  claimed_groups AS (
    UPDATE public.pay_payment_return_notice_groups AS notice_group_to_claim
    SET
      status = 'READY',
      updated_at_utc = v_now
    FROM due_groups
    WHERE notice_group_to_claim.id = due_groups.id
    RETURNING notice_group_to_claim.*
  )
  SELECT
    claimed_groups.id,
    claimed_groups.pay_batch_id,
    claimed_groups.execution_commit_ref,
    claimed_groups.provider_key,
    claimed_groups.event_source,
    claimed_groups.notice_kind,
    claimed_groups.status,
    claimed_groups.quiet_until_utc,
    claimed_groups.max_send_at_utc,
    claimed_groups.summary_json,
    claimed_groups.mail_outbox_ids,
    claimed_groups.created_at_utc,
    claimed_groups.updated_at_utc,
    claimed_groups.sent_at_utc,
    claimed_groups.alert_fingerprint
  FROM claimed_groups;

  SELECT count(*)::integer
  INTO v_claimed_count
  FROM pg_temp._tmp_payment_return_notice_due AS due_count;

  IF v_claimed_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'claimed', 0,
      'sent', 0,
      'failed', 0,
      'no_recipient', 0,
      'recipient_role', v_recipient_role
    );
  END IF;

  FOR v_group_row IN
    SELECT due_groups.*
    FROM pg_temp._tmp_payment_return_notice_due AS due_groups
    ORDER BY due_groups.created_at_utc ASC, due_groups.id ASC
  LOOP
    v_mail_outbox_id := NULL::uuid;
    v_to_emails := NULL::text;
    v_notice_reference := NULL::text;
    v_insert_context_kind := 'pay_payment_return_notice_groups';
    v_insert_context_id := v_group_row.id;
    v_pay_batch_short := CASE WHEN v_group_row.pay_batch_id IS NULL THEN '' ELSE left(v_group_row.pay_batch_id::text, 8) END;

    SELECT string_agg(admin_recipients.email, ',' ORDER BY admin_recipients.email)
    INTO v_to_emails
    FROM (
      SELECT DISTINCT public.tms_users.email AS email
      FROM public.tms_users
      WHERE COALESCE(public.tms_users.is_active, false) = true
        AND NULLIF(btrim(COALESCE(public.tms_users.email, '')), '') IS NOT NULL
        AND (
          upper(btrim(COALESCE(public.tms_users.role, ''))) = upper(btrim(v_recipient_role))
          OR (
            upper(btrim(coalesce(v_group_row.notice_kind, ''))) = 'BLOCKED_FUNDS'
            AND (
              COALESCE(public.tms_users.payment_authoriser, false) = true
              OR COALESCE(public.tms_users.payment_golden_key, false) = true
            )
          )
        )
    ) AS admin_recipients;

    IF NULLIF(btrim(COALESCE(v_to_emails, '')), '') IS NULL THEN
      UPDATE public.pay_payment_return_notice_groups AS no_recipient_group
      SET
        status = 'FAILED',
        updated_at_utc = v_now,
        summary_json = COALESCE(no_recipient_group.summary_json, '{}'::jsonb) || jsonb_build_object(
          'dispatch_error', jsonb_build_object(
            'code', 'NO_ADMIN_NOTICE_RECIPIENTS_FOR_ROLE',
            'recipient_role', v_recipient_role,
            'failed_at_utc', v_now,
            'failed_at_display', public.cloudtms_format_london_datetime(v_now)
          )
        )
      WHERE no_recipient_group.id = v_group_row.id;

      v_failed_count := v_failed_count + 1;
      v_no_recipient_count := v_no_recipient_count + 1;
      CONTINUE;
    END IF;

    v_notice_summary := left(COALESCE(v_group_row.summary_json::text, '{}'), 12000);

    IF upper(btrim(coalesce(v_group_row.notice_kind, ''))) = 'BLOCKED_FUNDS' THEN
      v_insert_context_kind := 'pay_batches';
      v_insert_context_id := v_group_row.pay_batch_id;
      v_blocked_provider := COALESCE(
        v_group_row.summary_json #>> '{rail_provider}',
        v_group_row.summary_json #>> '{provider}',
        v_group_row.summary_json #>> '{latest_summary_json,rail_provider}',
        v_group_row.summary_json #>> '{latest_summary_json,provider}',
        v_group_row.provider_key,
        ''
      );
      v_blocked_env := COALESCE(
        v_group_row.summary_json #>> '{rail_env}',
        v_group_row.summary_json #>> '{env}',
        v_group_row.summary_json #>> '{latest_summary_json,rail_env}',
        v_group_row.summary_json #>> '{latest_summary_json,env}',
        ''
      );
      v_blocked_account := COALESCE(
        v_group_row.summary_json #>> '{funding_account_ref}',
        v_group_row.summary_json #>> '{latest_summary_json,funding_account_ref}',
        v_group_row.summary_json #>> '{blocked_funds,funding_account_ref}',
        ''
      );
      v_blocked_required := COALESCE(
        v_group_row.summary_json #>> '{required_gbp}',
        v_group_row.summary_json #>> '{required}',
        v_group_row.summary_json #>> '{latest_summary_json,required_gbp}',
        v_group_row.summary_json #>> '{latest_summary_json,required}',
        v_group_row.summary_json #>> '{blocked_funds,required_gbp}',
        ''
      );
      v_blocked_available := COALESCE(
        v_group_row.summary_json #>> '{available_gbp}',
        v_group_row.summary_json #>> '{available}',
        v_group_row.summary_json #>> '{latest_summary_json,available_gbp}',
        v_group_row.summary_json #>> '{latest_summary_json,available}',
        v_group_row.summary_json #>> '{blocked_funds,available_gbp}',
        ''
      );
      v_blocked_required := CASE
        WHEN NULLIF(BTRIM(COALESCE(v_blocked_required, '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN public.cloudtms_format_gbp(v_blocked_required::numeric)
        ELSE COALESCE(NULLIF(BTRIM(COALESCE(v_blocked_required, '')), ''), '')
      END;
      v_blocked_available := CASE
        WHEN NULLIF(BTRIM(COALESCE(v_blocked_available, '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN public.cloudtms_format_gbp(v_blocked_available::numeric)
        ELSE COALESCE(NULLIF(BTRIM(COALESCE(v_blocked_available, '')), ''), '')
      END;
      v_blocked_status := COALESCE(
        v_group_row.summary_json #>> '{status}',
        v_group_row.summary_json #>> '{batch_status}',
        v_group_row.summary_json #>> '{latest_summary_json,status}',
        'BLOCKED_FUNDS'
      );
      v_blocked_execution_state := COALESCE(
        v_group_row.summary_json #>> '{execution_commit_state}',
        v_group_row.summary_json #>> '{latest_summary_json,execution_commit_state}',
        ''
      );
      v_blocked_pay_date := COALESCE(
        v_group_row.summary_json #>> '{pay_date_display}',
        CASE
          WHEN NULLIF(BTRIM(COALESCE(v_group_row.summary_json #>> '{pay_date}', v_group_row.summary_json #>> '{latest_summary_json,pay_date}', '')), '') IS NULL THEN NULL
          ELSE public.cloudtms_format_london_date((COALESCE(v_group_row.summary_json #>> '{pay_date}', v_group_row.summary_json #>> '{latest_summary_json,pay_date}'))::date)
        END,
        ''
      );
      v_blocked_last_funds_checked := COALESCE(
        v_group_row.summary_json #>> '{last_funds_check_display}',
        CASE
          WHEN NULLIF(BTRIM(COALESCE(v_group_row.summary_json #>> '{last_funds_check_at_utc}', v_group_row.summary_json #>> '{latest_summary_json,last_funds_check_at_utc}', '')), '') IS NULL THEN NULL
          ELSE public.cloudtms_format_london_datetime((COALESCE(v_group_row.summary_json #>> '{last_funds_check_at_utc}', v_group_row.summary_json #>> '{latest_summary_json,last_funds_check_at_utc}'))::timestamptz)
        END,
        'Not recorded'
      );
      v_blocked_bulk_reference := COALESCE(
        v_group_row.summary_json #>> '{bulk_reference}',
        v_group_row.summary_json #>> '{latest_summary_json,bulk_reference}',
        ''
      );

      v_subject := 'Bank rejected payment — blocked funds — Pay batch ' || COALESCE(NULLIF(v_pay_batch_short, ''), COALESCE(v_group_row.pay_batch_id::text, ''));
      v_body_text := concat_ws(E'\n',
        'CloudTMS could not submit this payment because the funding account did not have enough funds.',
        '',
        'Pay batch: ' || COALESCE(v_group_row.pay_batch_id::text, ''),
        'Batch reference: ' || COALESCE(v_blocked_bulk_reference, ''),
        'Pay date: ' || COALESCE(v_blocked_pay_date, ''),
        'Provider: ' || COALESCE(v_blocked_provider, '') || CASE WHEN NULLIF(v_blocked_env, '') IS NULL THEN '' ELSE ' / ' || v_blocked_env END,
        'Funding account: ' || COALESCE(v_blocked_account, ''),
        'Required: ' || COALESCE(NULLIF(v_blocked_required, ''), ''),
        'Available: ' || COALESCE(NULLIF(v_blocked_available, ''), ''),
        'Status: ' || COALESCE(v_blocked_status, 'BLOCKED_FUNDS'),
        'Execution state: ' || COALESCE(v_blocked_execution_state, ''),
        'Last funds checked: ' || COALESCE(v_blocked_last_funds_checked, 'Not recorded'),
        'Bank submission happened: No',
        'Action required: fund the account and retry, or cancel/release the batch.',
        '',
        'This is a blocked-funds bank rejection before submission. It is not a returned or reversed payment.'
      );
      v_body_html := '<div style="font-family:Arial,sans-serif;color:#111827;line-height:1.45;">'
        || '<h2 style="margin:0 0 12px 0;color:#991b1b;">Bank rejected payment — blocked funds</h2>'
        || '<p>CloudTMS could not submit this payment because the funding account did not have enough funds.</p>'
        || '<table style="border-collapse:collapse;width:100%;max-width:760px;">'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Pay batch</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_group_row.pay_batch_id::text, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Batch reference</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_bulk_reference, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Pay date</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_pay_date, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Provider</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_provider, '') || CASE WHEN NULLIF(v_blocked_env, '') IS NULL THEN '' ELSE ' / ' || v_blocked_env END, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Funding account</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_account, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Required</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(NULLIF(v_blocked_required, ''), ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Available</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(NULLIF(v_blocked_available, ''), ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Status</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_status, 'BLOCKED_FUNDS'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Last funds checked</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_blocked_last_funds_checked, 'Not recorded'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Bank submission happened</th><td style="border:1px solid #e5e7eb;padding:8px;">No</td></tr>'
        || '</table>'
        || '<p style="margin-top:14px;"><strong>Action required:</strong> fund the account and retry, or cancel/release the batch.</p>'
        || '<p style="font-size:12px;color:#6b7280;">This is a blocked-funds bank rejection before submission. It is not a returned or reversed payment.</p>'
        || '</div>';
      v_notice_reference := 'banking_alert:pay_batch:' || COALESCE(v_group_row.pay_batch_id::text, 'NO_BATCH') || ':BLOCKED_FUNDS:' || md5(COALESCE(v_group_row.alert_fingerprint, v_group_row.id::text));
    ELSE
      v_subject := 'CloudTMS payment correction notice: ' || COALESCE(v_group_row.notice_kind, 'PAYMENT_RETURN_NOTICE');
      v_body_text := concat_ws(E'\n',
        'CloudTMS payment correction/admin notice',
        '',
        'Notice kind: ' || COALESCE(v_group_row.notice_kind, ''),
        'Pay batch ID: ' || COALESCE(v_group_row.pay_batch_id::text, ''),
        'Provider: ' || COALESCE(v_group_row.provider_key, ''),
        'Execution reference: ' || COALESCE(v_group_row.execution_commit_ref, ''),
        'Created: ' || public.cloudtms_format_london_datetime(v_group_row.created_at_utc),
        'Quiet window until: ' || public.cloudtms_format_london_datetime(v_group_row.quiet_until_utc),
        'Latest send by: ' || public.cloudtms_format_london_datetime(v_group_row.max_send_at_utc),
        '',
        'Action required: open CloudTMS Banking Pay and review the Payment Issues tab for this batch.',
        '',
        'The detailed audit payload is stored against the payment notice group in CloudTMS.'
      );
      v_body_html := '<div style="font-family:Arial,sans-serif;color:#111827;line-height:1.45;">'
        || '<h2 style="margin:0 0 12px 0;color:#991b1b;">CloudTMS payment correction/admin notice</h2>'
        || '<table style="border-collapse:collapse;width:100%;max-width:760px;">'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Notice kind</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_group_row.notice_kind, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Pay batch ID</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_group_row.pay_batch_id::text, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Provider</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_group_row.provider_key, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Execution reference</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(COALESCE(v_group_row.execution_commit_ref, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Created</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(public.cloudtms_format_london_datetime(v_group_row.created_at_utc), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Quiet window until</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(public.cloudtms_format_london_datetime(v_group_row.quiet_until_utc), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '<tr><th style="text-align:left;border:1px solid #e5e7eb;padding:8px;background:#f9fafb;">Latest send by</th><td style="border:1px solid #e5e7eb;padding:8px;">' || replace(replace(replace(public.cloudtms_format_london_datetime(v_group_row.max_send_at_utc), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</td></tr>'
        || '</table>'
        || '<p style="margin-top:14px;"><strong>Action required:</strong> open CloudTMS Banking Pay and review the Payment Issues tab for this batch.</p>'
        || '<p style="font-size:12px;color:#6b7280;">The detailed audit payload is stored against the payment notice group in CloudTMS.</p>'
        || '</div>';
      v_notice_reference := 'payment_return_notice_group:' || v_group_row.id::text;
    END IF;

    INSERT INTO public.mail_outbox(
      type,
      "to",
      cc,
      bcc,
      reply_to,
      importance,
      email_type,
      subject,
      body_html,
      body_text,
      attachments,
      status,
      reference,
      created_at_utc,
      created_by,
      recipient_kind,
      recipient_id,
      context_kind,
      context_id,
      scheduled_for_utc,
      next_attempt_at_utc
    )
    SELECT
      'BROADCAST',
      v_to_emails,
      NULL::text,
      NULL::text,
      NULL::text,
      'High',
      'payment_return_admin_notice',
      v_subject,
      v_body_html,
      v_body_text,
      NULL::jsonb,
      'QUEUED',
      v_notice_reference,
      v_now,
      NULL::uuid,
      'ROLE',
      NULL::uuid,
      v_insert_context_kind,
      v_insert_context_id,
      NULL::timestamptz,
      v_now
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.mail_outbox AS existing_notice_mail
      WHERE existing_notice_mail.reference = v_notice_reference
        AND existing_notice_mail.email_type = 'payment_return_admin_notice'
    )
    RETURNING public.mail_outbox.id
    INTO v_mail_outbox_id;

    IF v_mail_outbox_id IS NULL THEN
      SELECT public.mail_outbox.id
      INTO v_mail_outbox_id
      FROM public.mail_outbox
      WHERE public.mail_outbox.reference = v_notice_reference
        AND public.mail_outbox.email_type = 'payment_return_admin_notice'
      ORDER BY public.mail_outbox.created_at_utc ASC, public.mail_outbox.id ASC
      LIMIT 1;
    END IF;

    IF v_mail_outbox_id IS NULL THEN
      UPDATE public.pay_payment_return_notice_groups AS failed_insert_group
      SET
        status = 'FAILED',
        updated_at_utc = v_now,
        summary_json = COALESCE(failed_insert_group.summary_json, '{}'::jsonb) || jsonb_build_object(
          'dispatch_error', jsonb_build_object(
            'code', 'ADMIN_NOTICE_MAIL_OUTBOX_INSERT_FAILED',
            'failed_at_utc', v_now,
            'failed_at_display', public.cloudtms_format_london_datetime(v_now)
          )
        )
      WHERE failed_insert_group.id = v_group_row.id;

      v_failed_count := v_failed_count + 1;
    ELSE
      UPDATE public.pay_payment_return_notice_groups AS sent_group
      SET
        status = 'SENT',
        sent_at_utc = COALESCE(sent_group.sent_at_utc, v_now),
        updated_at_utc = v_now,
        mail_outbox_ids = COALESCE(sent_group.mail_outbox_ids, '[]'::jsonb) || jsonb_build_array(v_mail_outbox_id::text),
        summary_json = COALESCE(sent_group.summary_json, '{}'::jsonb) || jsonb_build_object(
          'dispatch', jsonb_build_object(
            'mail_outbox_id', v_mail_outbox_id,
            'recipient_role', v_recipient_role,
            'to', v_to_emails,
            'reference', v_notice_reference,
            'dispatched_at_utc', v_now,
            'dispatched_at_display', public.cloudtms_format_london_datetime(v_now),
            'context_kind', v_insert_context_kind,
            'context_id', v_insert_context_id
          )
        )
      WHERE sent_group.id = v_group_row.id;

      v_sent_count := v_sent_count + 1;
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'ok', true,
    'claimed', v_claimed_count,
    'sent', v_sent_count,
    'failed', v_failed_count,
    'no_recipient', v_no_recipient_count,
    'recipient_role', v_recipient_role
  );

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_RETURN_ADMIN_NOTICE_DISPATCH_DUE_RESULT',
    v_result,
    'pay_payment_correction',
    'admin_notice_dispatch_due',
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_result;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      NULL::uuid,
      'PAYMENT_RETURN_ADMIN_NOTICE_DISPATCH_DUE_ERROR',
      jsonb_build_object(
        'limit', p_limit,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      'admin_notice_dispatch_due',
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_payment_return_admin_notice_queue(text,uuid,text,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_payment_return_admin_notice_queue(p_notice_kind text, p_pay_batch_id uuid DEFAULT NULL::uuid, p_provider_key text DEFAULT NULL::text, p_execution_commit_ref text DEFAULT NULL::text, p_summary_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_notice_kind text;
  v_provider_key text;
  v_execution_commit_ref text;
  v_summary_json jsonb := '{}'::jsonb;
  v_alert_fingerprint text := NULL::text;
  v_supplied_alert_fingerprint text := NULL::text;
  v_canonical_alert_payload jsonb := '{}'::jsonb;
  v_canonical_alert_fingerprint text := NULL::text;
  v_recipient_role text := 'ADMIN';
  v_quiet_minutes integer := 10;
  v_max_wait_minutes integer := 60;
  v_payroll_testing boolean := false;
  v_now timestamptz := now();
  v_existing_group public.pay_payment_return_notice_groups%rowtype;
  v_notice_group_id uuid := NULL::uuid;
  v_quiet_until_utc timestamptz;
  v_max_send_at_utc timestamptz;
  v_merge_count integer := 1;
  v_return_json jsonb := '{}'::jsonb;
  v_blocked_batch record;
  v_required_gbp_text text := NULL::text;
  v_available_gbp_text text := NULL::text;
  v_funding_account_ref text := NULL::text;
  v_rail_provider text := NULL::text;
  v_rail_env text := NULL::text;
BEGIN
  v_notice_kind := upper(nullif(btrim(COALESCE(p_notice_kind, '')), ''));
  v_provider_key := upper(nullif(btrim(COALESCE(p_provider_key, '')), ''));
  v_execution_commit_ref := nullif(btrim(COALESCE(p_execution_commit_ref, '')), '');

  IF v_notice_kind = 'BANKING_BLOCKED_FUNDS' THEN
    v_notice_kind := 'BLOCKED_FUNDS';
  END IF;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_RETURN_ADMIN_NOTICE_QUEUE_START',
    jsonb_build_object(
      'notice_kind', v_notice_kind,
      'pay_batch_id', p_pay_batch_id,
      'provider_key', v_provider_key,
      'execution_commit_ref', v_execution_commit_ref,
      'summary_json_keys', CASE
        WHEN p_summary_json IS NULL OR jsonb_typeof(p_summary_json) <> 'object' THEN '[]'::jsonb
        ELSE COALESCE((
          SELECT jsonb_agg(summary_keys.key_name ORDER BY summary_keys.key_name)
          FROM jsonb_object_keys(p_summary_json) AS summary_keys(key_name)
        ), '[]'::jsonb)
      END
    ),
    'pay_payment_correction',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF v_notice_kind IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAYMENT_RETURN_ADMIN_NOTICE_KIND_REQUIRED')::text;
  END IF;

  IF v_notice_kind NOT IN (
    'BANK_FAILURE_DETECTED',
    'BLOCKED_FUNDS',
    'NO_MONEY_UNWIND_REQUIRED',
    'NO_MONEY_UNWIND_APPLIED',
    'SETTLED_RETURN_DETECTED',
    'SETTLED_REVERSAL_REQUIRED',
    'SETTLED_REVERSAL_APPLIED',
    'AUTO_CORRECTION_BLOCKED',
    'MANUAL_CORRECTION_APPLIED',
    'PAYMENT_CANCELLED_BEFORE_BANK_SUBMISSION',
    'PROVIDER_FAILED_NO_MONEY',
    'FINANCIALS_REWOUND',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'PROVIDER_OUTAGE_RETRY_LATER',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'PROVIDER_WEBHOOK_RECEIVED',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED',
    'AUTO_UNWIND_STARTED',
    'AUTO_UNWIND_COMPLETED',
    'BANKING_ALERT_SUPPRESSED_BY_USER_PREFERENCE'
  ) THEN
    RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_KIND_UNSUPPORTED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_RETURN_ADMIN_NOTICE_KIND_UNSUPPORTED',
              'notice_kind', v_notice_kind
            )::text;
  END IF;

  IF p_summary_json IS NOT NULL AND COALESCE(jsonb_typeof(p_summary_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_SUMMARY_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_RETURN_ADMIN_NOTICE_SUMMARY_MUST_BE_OBJECT',
              'notice_kind', v_notice_kind
            )::text;
  END IF;

  v_summary_json := COALESCE(p_summary_json, '{}'::jsonb);

  IF v_notice_kind IN (
    'PROVIDER_WEBHOOK_RECEIVED',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED',
    'AUTO_UNWIND_STARTED',
    'AUTO_UNWIND_COMPLETED',
    'BANKING_ALERT_SUPPRESSED_BY_USER_PREFERENCE'
  ) THEN
    v_summary_json := v_summary_json || jsonb_strip_nulls(jsonb_build_object(
      'notice_kind', v_notice_kind,
      'admin_notice_only', true,
      'user_banking_alert_generated', CASE
        WHEN v_notice_kind IN ('WEBHOOK_UNMATCHED_REVIEW_REQUIRED') THEN NULL::boolean
        ELSE false
      END,
      'provider_webhook_received', v_notice_kind = 'PROVIDER_WEBHOOK_RECEIVED',
      'unmatched_webhook_review_required', v_notice_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED',
      'auto_unwind_started', v_notice_kind = 'AUTO_UNWIND_STARTED',
      'auto_unwind_completed', v_notice_kind = 'AUTO_UNWIND_COMPLETED',
      'no_alert_generated_due_to_user_preference', v_notice_kind = 'BANKING_ALERT_SUPPRESSED_BY_USER_PREFERENCE',
      'pay_batch_id', CASE WHEN p_pay_batch_id IS NULL THEN NULL ELSE p_pay_batch_id::text END,
      'provider_key', v_provider_key,
      'execution_commit_ref', v_execution_commit_ref,
      'provider_webhook_receipt_id', COALESCE(v_summary_json->>'provider_webhook_receipt_id', v_summary_json#>>'{webhook,receipt_id}'),
      'provider_event_key', COALESCE(v_summary_json->>'provider_event_key', v_summary_json#>>'{webhook,event_key}'),
      'provider_transaction_id', COALESCE(v_summary_json->>'provider_transaction_id', v_summary_json#>>'{webhook,transaction_id}'),
      'provider_request_id', COALESCE(v_summary_json->>'provider_request_id', v_summary_json#>>'{webhook,request_id}')
    ));
  END IF;

  SELECT
    COALESCE(NULLIF(btrim(public.settings_defaults.payment_return_admin_recipient_role), ''), 'ADMIN'),
    COALESCE(public.settings_defaults.payment_return_admin_notice_quiet_minutes, 10),
    COALESCE(public.settings_defaults.payment_return_admin_notice_max_wait_minutes, 60),
    COALESCE(public.settings_defaults.payroll_testing, false)
  INTO
    v_recipient_role,
    v_quiet_minutes,
    v_max_wait_minutes,
    v_payroll_testing
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_recipient_role := COALESCE(NULLIF(btrim(v_recipient_role), ''), 'ADMIN');
  v_quiet_minutes := LEAST(GREATEST(COALESCE(v_quiet_minutes, 10), 0), 1440);
  v_max_wait_minutes := LEAST(GREATEST(COALESCE(v_max_wait_minutes, 60), v_quiet_minutes), 1440);
  v_payroll_testing := COALESCE(v_payroll_testing, false);

  IF v_notice_kind = 'BLOCKED_FUNDS' THEN
    IF p_pay_batch_id IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_BATCH_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_BATCH_REQUIRED',
                'notice_kind', v_notice_kind
              )::text;
    END IF;

    SELECT
      public.pay_batches.id,
      public.pay_batches.status,
      public.pay_batches.execution_commit_state,
      public.pay_batches.execution_commit_ref,
      public.pay_batches.execution_committed_at_utc,
      public.pay_batches.last_funds_check_at_utc,
      public.pay_batches.last_funds_check_json,
      public.pay_batches.funding_account_ref,
      public.pay_batches.rail_provider_snapshot,
      public.pay_batches.rail_env_snapshot,
      public.pay_batches.pay_date,
      public.pay_batches.bulk_reference
    INTO v_blocked_batch
    FROM public.pay_batches
    WHERE public.pay_batches.id = p_pay_batch_id;

    IF v_blocked_batch.id IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_BATCH_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_BATCH_NOT_FOUND',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;

    v_canonical_alert_payload := public.banking_alert_payload_for_pay_batch('BLOCKED_FUNDS', p_pay_batch_id);
    v_canonical_alert_fingerprint := public.banking_alert_fingerprint(
      'BLOCKED_FUNDS',
      'pay_batch',
      p_pay_batch_id,
      v_canonical_alert_payload
    );

    v_supplied_alert_fingerprint := nullif(btrim(coalesce(
      v_summary_json ->> 'alert_fingerprint',
      v_summary_json #>> '{banking_alert,alert_fingerprint}',
      v_summary_json #>> '{alert,alert_fingerprint}',
      ''
    )), '');

    IF v_supplied_alert_fingerprint IS NOT NULL AND v_supplied_alert_fingerprint <> v_canonical_alert_fingerprint THEN
      IF v_payroll_testing THEN
        RAISE EXCEPTION 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_FINGERPRINT_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAYMENT_RETURN_ADMIN_NOTICE_BLOCKED_FUNDS_FINGERPRINT_MISMATCH',
                  'pay_batch_id', p_pay_batch_id::text,
                  'supplied_alert_fingerprint', v_supplied_alert_fingerprint,
                  'canonical_alert_fingerprint', v_canonical_alert_fingerprint
                )::text;
      END IF;

      v_summary_json := v_summary_json || jsonb_build_object(
        'supplied_alert_fingerprint', v_supplied_alert_fingerprint,
        'canonical_fingerprint_used', true
      );
    END IF;

    v_alert_fingerprint := v_canonical_alert_fingerprint;

    v_required_gbp_text := COALESCE(
      v_canonical_alert_payload ->> 'required_gbp',
      v_summary_json #>> '{required_gbp}',
      v_summary_json #>> '{required}',
      v_summary_json #>> '{required_amount_gbp}',
      v_summary_json #>> '{required_amount}',
      v_summary_json #>> '{blocked_funds,required_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{required_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{required}',
      v_blocked_batch.last_funds_check_json #>> '{required_amount_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{required_amount}'
    );

    v_available_gbp_text := COALESCE(
      v_canonical_alert_payload ->> 'available_gbp',
      v_summary_json #>> '{available_gbp}',
      v_summary_json #>> '{available}',
      v_summary_json #>> '{available_amount_gbp}',
      v_summary_json #>> '{available_amount}',
      v_summary_json #>> '{blocked_funds,available_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{available_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{available}',
      v_blocked_batch.last_funds_check_json #>> '{available_amount_gbp}',
      v_blocked_batch.last_funds_check_json #>> '{available_amount}'
    );

    v_funding_account_ref := COALESCE(
      v_canonical_alert_payload ->> 'funding_account_ref',
      v_summary_json #>> '{funding_account_ref}',
      v_summary_json #>> '{blocked_funds,funding_account_ref}',
      v_blocked_batch.last_funds_check_json #>> '{funding_account_ref}',
      v_blocked_batch.last_funds_check_json #>> '{account_ref}',
      v_blocked_batch.funding_account_ref
    );

    v_rail_provider := COALESCE(
      v_canonical_alert_payload ->> 'rail_provider',
      v_summary_json #>> '{rail_provider}',
      v_summary_json #>> '{provider}',
      v_summary_json #>> '{blocked_funds,rail_provider}',
      v_blocked_batch.last_funds_check_json #>> '{rail_provider}',
      v_blocked_batch.last_funds_check_json #>> '{provider}',
      v_blocked_batch.rail_provider_snapshot,
      v_provider_key
    );

    v_rail_env := COALESCE(
      v_canonical_alert_payload ->> 'rail_env',
      v_summary_json #>> '{rail_env}',
      v_summary_json #>> '{env}',
      v_summary_json #>> '{blocked_funds,rail_env}',
      v_blocked_batch.last_funds_check_json #>> '{rail_env}',
      v_blocked_batch.last_funds_check_json #>> '{env}',
      v_blocked_batch.rail_env_snapshot
    );

    v_provider_key := upper(nullif(btrim(coalesce(v_provider_key, v_rail_provider, '')), ''));
    v_execution_commit_ref := nullif(btrim(coalesce(v_execution_commit_ref, v_blocked_batch.execution_commit_ref, '')), '');

    v_summary_json := v_summary_json || jsonb_strip_nulls(jsonb_build_object(
      'notice_kind', 'BLOCKED_FUNDS',
      'pay_batch_id', p_pay_batch_id::text,
      'pay_date', CASE WHEN v_blocked_batch.pay_date IS NULL THEN NULL ELSE v_blocked_batch.pay_date::text END,
      'pay_date_display', public.cloudtms_format_london_date(v_blocked_batch.pay_date),
      'bulk_reference', v_blocked_batch.bulk_reference,
      'provider_key', v_provider_key,
      'rail_provider', v_rail_provider,
      'rail_env', v_rail_env,
      'funding_account_ref', v_funding_account_ref,
      'required_gbp', v_required_gbp_text,
      'available_gbp', v_available_gbp_text,
      'sufficient', false,
      'status', v_blocked_batch.status,
      'execution_commit_state', v_blocked_batch.execution_commit_state,
      'execution_commit_ref', v_blocked_batch.execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_blocked_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_blocked_batch.execution_committed_at_utc::text END,
      'last_funds_check_at_utc', CASE WHEN v_blocked_batch.last_funds_check_at_utc IS NULL THEN NULL ELSE v_blocked_batch.last_funds_check_at_utc::text END,
      'last_funds_check_display', public.cloudtms_format_london_datetime(v_blocked_batch.last_funds_check_at_utc),
      'bank_submission_happened', false,
      'action_guidance', 'Fund the account and retry, or cancel/release the batch.',
      'canonical_alert_payload', v_canonical_alert_payload,
      'alert_fingerprint', v_alert_fingerprint
    ));
  ELSE
    v_alert_fingerprint := nullif(btrim(coalesce(
      v_summary_json ->> 'alert_fingerprint',
      v_summary_json #>> '{banking_alert,alert_fingerprint}',
      v_summary_json #>> '{alert,alert_fingerprint}',
      ''
    )), '');
  END IF;

  IF v_alert_fingerprint IS NOT NULL AND btrim(v_alert_fingerprint) = '' THEN
    v_alert_fingerprint := NULL::text;
  END IF;

  IF v_notice_kind IN (
    'PAYMENT_CANCELLED_BEFORE_BANK_SUBMISSION',
    'PROVIDER_FAILED_NO_MONEY',
    'FINANCIALS_REWOUND',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'PROVIDER_OUTAGE_RETRY_LATER',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED',
    'AUTO_UNWIND_STARTED',
    'AUTO_UNWIND_COMPLETED'
  ) AND p_pay_batch_id IS NOT NULL THEN
    v_canonical_alert_payload := public.banking_alert_payload_for_pay_batch(
      CASE v_notice_kind
        WHEN 'PAYMENT_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'WHOLE_BATCH_CANCELLATION_PROGRESS'
        WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
        WHEN 'FINANCIALS_REWOUND' THEN 'AUTO_UNWIND_PROGRESS'
        WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
        WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
        WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
        WHEN 'AUTO_UNWIND_STARTED' THEN 'AUTO_UNWIND_PROGRESS'
        WHEN 'AUTO_UNWIND_COMPLETED' THEN 'AUTO_UNWIND_PROGRESS'
        ELSE v_notice_kind
      END,
      p_pay_batch_id
    );

    IF v_alert_fingerprint IS NULL THEN
      v_alert_fingerprint := public.banking_alert_fingerprint(
        COALESCE(NULLIF(v_canonical_alert_payload->>'alert_kind', ''), v_notice_kind),
        'pay_batch',
        p_pay_batch_id,
        v_canonical_alert_payload
      );
    END IF;

    v_summary_json := v_summary_json
      || v_canonical_alert_payload
      || jsonb_strip_nulls(jsonb_build_object(
        'notice_kind', v_notice_kind,
        'pay_batch_id', p_pay_batch_id::text,
        'affected_payment_count', COALESCE((v_canonical_alert_payload->>'affected_payment_count')::integer, NULL),
        'affected_candidate_count', COALESCE((v_canonical_alert_payload->>'affected_candidate_count')::integer, NULL),
        'affected_transfer_count', COALESCE((v_canonical_alert_payload->>'affected_transfer_count')::integer, NULL),
        'affected_timesheet_count', COALESCE((v_canonical_alert_payload->>'affected_timesheet_count')::integer, NULL),
        'carry_forward_count', COALESCE((v_canonical_alert_payload->>'carry_forward_count')::integer, COALESCE((v_canonical_alert_payload->>'manual_adjustments_carried_forward_count')::integer, NULL)),
        'remittance_or_advice_already_sent', lower(btrim(COALESCE(v_canonical_alert_payload->>'remittance_already_sent', v_canonical_alert_payload->>'advice_already_sent', 'false'))) IN ('true','1','yes','y','on'),
        'action_surface_link_target', COALESCE(v_canonical_alert_payload->>'link_target', 'banking_pay_batch'),
        'action_surface_link_tab', COALESCE(v_canonical_alert_payload->>'link_tab', 'overview'),
        'required_user_action', v_canonical_alert_payload->>'required_user_action',
        'user_label', v_canonical_alert_payload->>'user_label',
        'user_description', v_canonical_alert_payload->>'user_description',
        'alert_fingerprint', v_alert_fingerprint
      ));
  END IF;

  SELECT public.pay_payment_return_notice_groups.*
  INTO v_existing_group
  FROM public.pay_payment_return_notice_groups
  WHERE public.pay_payment_return_notice_groups.notice_kind = v_notice_kind
    AND (
      (
        v_alert_fingerprint IS NOT NULL
        AND public.pay_payment_return_notice_groups.alert_fingerprint = v_alert_fingerprint
      )
      OR (
        v_alert_fingerprint IS NULL
        AND public.pay_payment_return_notice_groups.status = 'OPEN'
        AND public.pay_payment_return_notice_groups.alert_fingerprint IS NULL
        AND public.pay_payment_return_notice_groups.pay_batch_id IS NOT DISTINCT FROM p_pay_batch_id
        AND public.pay_payment_return_notice_groups.provider_key IS NOT DISTINCT FROM v_provider_key
        AND public.pay_payment_return_notice_groups.execution_commit_ref IS NOT DISTINCT FROM v_execution_commit_ref
      )
    )
  ORDER BY
    CASE upper(btrim(coalesce(public.pay_payment_return_notice_groups.status, '')))
      WHEN 'OPEN' THEN 0
      WHEN 'READY' THEN 1
      WHEN 'FAILED' THEN 2
      WHEN 'SENT' THEN 3
      ELSE 4
    END,
    public.pay_payment_return_notice_groups.created_at_utc ASC,
    public.pay_payment_return_notice_groups.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_group.id IS NOT NULL THEN
    v_notice_group_id := v_existing_group.id;

    IF upper(btrim(coalesce(v_existing_group.status, ''))) = 'SENT' AND v_alert_fingerprint IS NOT NULL THEN
      v_return_json := jsonb_build_object(
        'ok', true,
        'created', false,
        'already_dispatched', true,
        'notice_group_id', v_notice_group_id,
        'notice_kind', v_notice_kind,
        'pay_batch_id', p_pay_batch_id,
        'provider_key', v_provider_key,
        'execution_commit_ref', v_execution_commit_ref,
        'alert_fingerprint', v_alert_fingerprint,
        'recipient_role', v_recipient_role,
        'quiet_until_utc', v_existing_group.quiet_until_utc,
        'max_send_at_utc', v_existing_group.max_send_at_utc,
        'merge_count', COALESCE((v_existing_group.summary_json#>>'{notice_queue_meta,merge_count}')::integer, 1)
      );
    ELSE
      v_merge_count := COALESCE((v_existing_group.summary_json#>>'{notice_queue_meta,merge_count}')::integer, 1) + 1;
      v_quiet_until_utc := LEAST(
        v_existing_group.max_send_at_utc,
        GREATEST(v_existing_group.quiet_until_utc, v_now + make_interval(mins => v_quiet_minutes))
      );

      UPDATE public.pay_payment_return_notice_groups AS existing_notice_group
      SET
        status = CASE
          WHEN upper(btrim(coalesce(existing_notice_group.status, ''))) = 'FAILED' THEN 'OPEN'
          ELSE existing_notice_group.status
        END,
        quiet_until_utc = v_quiet_until_utc,
        alert_fingerprint = COALESCE(existing_notice_group.alert_fingerprint, v_alert_fingerprint),
        summary_json = COALESCE(existing_notice_group.summary_json, '{}'::jsonb)
          || v_summary_json
          || jsonb_build_object(
            'notice_queue_meta', jsonb_build_object(
              'merge_count', v_merge_count,
              'last_queued_at_utc', v_now,
              'recipient_role', v_recipient_role,
              'quiet_minutes', v_quiet_minutes,
              'max_wait_minutes', v_max_wait_minutes,
              'alert_fingerprint', v_alert_fingerprint
            ),
            'latest_summary_json', v_summary_json
          ),
        updated_at_utc = v_now
      WHERE existing_notice_group.id = v_existing_group.id
      RETURNING existing_notice_group.id
      INTO v_notice_group_id;

      v_return_json := jsonb_build_object(
        'ok', true,
        'created', false,
        'reopened_failed_notice', upper(btrim(coalesce(v_existing_group.status, ''))) = 'FAILED',
        'notice_group_id', v_notice_group_id,
        'notice_kind', v_notice_kind,
        'pay_batch_id', p_pay_batch_id,
        'provider_key', v_provider_key,
        'execution_commit_ref', v_execution_commit_ref,
        'alert_fingerprint', v_alert_fingerprint,
        'recipient_role', v_recipient_role,
        'quiet_until_utc', v_quiet_until_utc,
        'max_send_at_utc', v_existing_group.max_send_at_utc,
        'merge_count', v_merge_count
      );
    END IF;
  ELSE
    v_quiet_until_utc := v_now + make_interval(mins => v_quiet_minutes);
    v_max_send_at_utc := v_now + make_interval(mins => v_max_wait_minutes);

    INSERT INTO public.pay_payment_return_notice_groups(
      pay_batch_id,
      execution_commit_ref,
      provider_key,
      event_source,
      notice_kind,
      status,
      quiet_until_utc,
      max_send_at_utc,
      summary_json,
      mail_outbox_ids,
      created_at_utc,
      updated_at_utc,
      sent_at_utc,
      alert_fingerprint
    )
    VALUES (
      p_pay_batch_id,
      v_execution_commit_ref,
      v_provider_key,
      'SYSTEM',
      v_notice_kind,
      'OPEN',
      v_quiet_until_utc,
      v_max_send_at_utc,
      v_summary_json || jsonb_build_object(
        'notice_queue_meta', jsonb_build_object(
          'merge_count', 1,
          'created_at_utc', v_now,
          'recipient_role', v_recipient_role,
          'quiet_minutes', v_quiet_minutes,
          'max_wait_minutes', v_max_wait_minutes,
          'alert_fingerprint', v_alert_fingerprint
        )
      ),
      '[]'::jsonb,
      v_now,
      v_now,
      NULL::timestamptz,
      v_alert_fingerprint
    )
    RETURNING public.pay_payment_return_notice_groups.id
    INTO v_notice_group_id;

    v_return_json := jsonb_build_object(
      'ok', true,
      'created', true,
      'notice_group_id', v_notice_group_id,
      'notice_kind', v_notice_kind,
      'pay_batch_id', p_pay_batch_id,
      'provider_key', v_provider_key,
      'execution_commit_ref', v_execution_commit_ref,
      'alert_fingerprint', v_alert_fingerprint,
      'recipient_role', v_recipient_role,
      'quiet_until_utc', v_quiet_until_utc,
      'max_send_at_utc', v_max_send_at_utc,
      'merge_count', 1
    );
  END IF;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_RETURN_ADMIN_NOTICE_QUEUE_RESULT',
    v_return_json,
    'pay_payment_correction',
    COALESCE(v_notice_group_id::text, COALESCE(p_pay_batch_id::text, 'NO_NOTICE_GROUP_ID')),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_return_json;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      NULL::uuid,
      'PAYMENT_RETURN_ADMIN_NOTICE_QUEUE_ERROR',
      jsonb_build_object(
        'notice_kind', p_notice_kind,
        'pay_batch_id', p_pay_batch_id,
        'provider_key', p_provider_key,
        'execution_commit_ref', p_execution_commit_ref,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_pre_bank_cancel_apply_work_item(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_pre_bank_cancel_apply_work_item(p_work_item_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_work_item public.pay_payment_correction_work_items%rowtype;
  v_request public.pay_payment_correction_requests%rowtype;
  v_batch public.pay_batches%rowtype;
  v_operation public.banking_pay_operations%rowtype;
  v_membership public.pay_payment_correction_request_candidates%rowtype;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_now timestamptz := now();
  v_classification_result jsonb := '{}'::jsonb;
  v_classification text := NULL;
  v_blocker jsonb := NULL::jsonb;
  v_result jsonb := '{}'::jsonb;
  v_selected_item_count integer := 0;
  v_selected_candidate_count integer := 0;
  v_selected_transfer_count integer := 0;
  v_selected_reservation_count integer := 0;
  v_selected_finance_component_count integer := 0;
  v_voided_item_count integer := 0;
  v_inserted_correction_item_count integer := 0;
  v_released_reservation_count integer := 0;
  v_restored_component_count integer := 0;
  v_reset_payout_count integer := 0;
  v_cancelled_mail_count integer := 0;
  v_recalculated_transfer_count integer := 0;
  v_dirty_candidate_count integer := 0;
  v_has_settlement_evidence boolean := false;
  v_has_bank_submission_evidence boolean := false;
  v_has_authorised_partial_transfer_change boolean := false;
  v_batch_execution_commit_state text := 'NOT_SUBMITTED';
  v_is_authorised_or_scheduled_batch boolean := false;
  v_candidate_id uuid;
  v_refresh_result jsonb;
  v_scope_type text := NULL::text;
  v_work_unit text := NULL::text;
  v_is_whole_batch_work_item boolean := false;
  v_total_active_batch_item_count integer := 0;
  v_expected_item_count integer := NULL::integer;
  v_expected_item_id_count integer := 0;
  v_expected_item_mismatch_count integer := 0;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_batch_cancel_result jsonb := NULL::jsonb;
  v_mail_selected_scope_json jsonb := '{}'::jsonb;
  v_communications_review_required_count integer := 0;
  v_mail_scope_matching jsonb := '{}'::jsonb;
  v_summary_refresh_candidate_count integer := 0;
  v_active_batch_item_count_after integer := 0;
  v_active_batch_amount_inc_vat_after numeric := 0;
  v_batch_empty_after boolean := false;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_manual_adjustment_result jsonb := '{}'::jsonb;
  v_carry_forward_create_result jsonb := '{}'::jsonb;
  v_carry_forward_release_result jsonb := '{}'::jsonb;
  v_carry_forward_created_count integer := 0;
  v_carry_forward_existing_count integer := 0;
  v_carry_forward_released_count integer := 0;
  v_changed_scope_json jsonb := '{}'::jsonb;
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_same_request_partial_continuation boolean := false;
  v_original_expected_json_count integer := 0;
  v_original_expected_valid_count integer := 0;
  v_original_expected_belongs_count integer := 0;
  v_original_expected_active_count integer := 0;
  v_original_expected_same_request_voided_count integer := 0;
  v_original_expected_disallowed_state_count integer := 0;
  v_active_outside_original_count integer := 0;
  v_current_expected_outside_original_count integer := 0;
  v_applied_sibling_count integer := 0;
  v_membership_item_mismatch_count integer := 0;
  v_current_active_item_count integer := 0;
  v_current_source_row_count integer := 0;
  v_capacity_selected_scope_json jsonb := '{}'::jsonb;
  v_current_candidate_scope_hash text;
  v_candidate_scope_contract_version integer := 1;
  v_candidate_scope_contract_raw text;
  v_candidate_scope_hash_version integer := 1;
  v_source_row_count_semantics text := 'FINANCIAL_AND_QUEUED_COMMUNICATIONS';
  v_matching_queued_count integer := 0;
  v_unsafe_queued_count integer := 0;
  v_already_sent_untouched_count integer := 0;
  v_other_terminal_untouched_count integer := 0;
BEGIN
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PRE_BANK_CANCEL_WORK_START',
    jsonb_build_object(
      'work_item_id', p_work_item_id,
      'actor_user_id', p_actor_user_id
    ),
    'pay_payment_correction',
    COALESCE(p_work_item_id::text, 'NO_WORK_ITEM_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_work_item_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAYMENT_CORRECTION_WORK_ITEM_ID_REQUIRED')::text;
  END IF;

  SELECT public.pay_payment_correction_work_items.*
  INTO v_work_item
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.id = p_work_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND',
              'work_item_id', p_work_item_id
            )::text;
  END IF;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    v_work_item.pay_batch_id,
    v_work_item.correction_request_id,
    'CORRECTION_APPLY'
  );

  IF COALESCE((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_mutation_guard->>'code', 'PAYMENT_CORRECTION_GATE_OWNER_MISMATCH')
      USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
  END IF;

  SELECT public.pay_payment_correction_requests.*
  INTO v_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.id = v_work_item.correction_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND_FOR_WORK_ITEM'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND_FOR_WORK_ITEM',
              'work_item_id', p_work_item_id,
              'correction_request_id', v_work_item.correction_request_id
            )::text;
  END IF;

  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_request.requested_by_user_id);

  SELECT public.pay_batches.*
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = v_work_item.pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND_FOR_WORK_ITEM'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND_FOR_WORK_ITEM',
              'work_item_id', p_work_item_id,
              'pay_batch_id', v_work_item.pay_batch_id
            )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
    AND operation_row.input_json->>'correction_request_id' = v_request.id::text
  ORDER BY operation_row.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_operation.pay_batch_id IS DISTINCT FROM v_batch.id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_OPERATION_NOT_FOUND_FOR_WORK_ITEM'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'OPERATION_MISMATCH', 'work_item_id', p_work_item_id
      )::text;
  END IF;

  SELECT public.pay_payment_correction_work_items.*
  INTO v_work_item
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.id = p_work_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND', 'work_item_id', p_work_item_id
      )::text;
  END IF;

  IF v_work_item.correction_request_id IS DISTINCT FROM v_request.id
     OR v_work_item.pay_batch_id IS DISTINCT FROM v_batch.id THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_SCOPE_CHANGED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'SELECTION_STALE')::text;
  END IF;

  IF v_work_item.work_kind <> 'PRE_BANK_CANCEL' THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_ITEM_KIND_NOT_PRE_BANK_CANCEL',
      'message', 'This work item is not a pre-bank cancellation work item.',
      'work_kind', v_work_item.work_kind
    );

    UPDATE public.pay_payment_correction_work_items AS blocked_work_kind
    SET status = 'BLOCKED', locked_at_utc = NULL, locked_by = NULL,
        processed_at_utc = v_now, last_error = v_blocker->>'message',
        result_json = COALESCE(blocked_work_kind.result_json, '{}'::jsonb)
          || jsonb_build_object('ok', false, 'status', 'BLOCKED',
                                'blocker', v_blocker, 'processed_at_utc', v_now)
    WHERE blocked_work_kind.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  v_candidate_scope_contract_raw := NULLIF(BTRIM(COALESCE(
    v_work_item.selection_json->>'candidate_scope_contract_version',
    v_request.plan_json->>'candidate_scope_contract_version',
    ''
  )), '');
  IF v_candidate_scope_contract_raw IS NULL OR v_candidate_scope_contract_raw = '1' THEN
    v_candidate_scope_contract_version := 1;
    v_candidate_scope_hash_version := 1;
    v_source_row_count_semantics := 'FINANCIAL_AND_QUEUED_COMMUNICATIONS';
  ELSIF v_candidate_scope_contract_raw = '2' THEN
    v_candidate_scope_contract_version := 2;
    v_candidate_scope_hash_version := 2;
    v_source_row_count_semantics := 'FINANCIAL_ONLY';
    IF v_request.plan_json->>'candidate_scope_contract_version' IS DISTINCT FROM '2'
       OR v_work_item.selection_json->>'candidate_scope_contract_version' IS DISTINCT FROM '2'
       OR v_request.plan_json->>'candidate_scope_hash_version' IS DISTINCT FROM '2'
       OR v_work_item.selection_json->>'candidate_scope_hash_version' IS DISTINCT FROM '2'
       OR v_request.plan_json->>'source_row_count_semantics' IS DISTINCT FROM 'FINANCIAL_ONLY'
       OR v_work_item.selection_json->>'source_row_count_semantics' IS DISTINCT FROM 'FINANCIAL_ONLY'
       OR v_request.plan_json->>'communication_cleanup_contract_version' IS DISTINCT FROM '1'
       OR v_work_item.selection_json->>'communication_cleanup_contract_version' IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
          'code', 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH',
          'work_item_id', p_work_item_id,
          'correction_request_id', v_request.id
        )::text;
    END IF;
  ELSE
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED',
        'work_item_id', p_work_item_id,
        'candidate_scope_contract_version', v_candidate_scope_contract_raw
      )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_selected;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_selected ON COMMIT DROP AS
  SELECT
    selected_rows.pay_batch_id,
    selected_rows.pay_batch_candidate_id,
    selected_rows.candidate_id,
    selected_rows.pay_batch_item_id,
    selected_rows.item_type,
    selected_rows.timesheet_id,
    selected_rows.pay_bank_transfer_id,
    selected_rows.transfer_group_key,
    selected_rows.umbrella_id,
    selected_rows.finance_case_id,
    selected_rows.finance_component_id,
    selected_rows.reservation_id,
    selected_pay_advances.payout_transfer_id,
    selected_rows.economic_key_type,
    selected_rows.economic_key_value,
    selected_rows.source_amount_ex_vat,
    selected_rows.amount_ex_vat,
    selected_rows.amount_vat,
    selected_rows.amount_inc_vat,
    selected_rows.is_voided,
    selected_rows.already_corrected,
    selected_rows.key_resolution_failure_reason
  FROM public._pay_payment_correction_selected_items(
    v_work_item.pay_batch_id,
    v_work_item.selection_json,
    false
  ) AS selected_rows
  LEFT JOIN public.pay_advances AS selected_pay_advances
    ON selected_pay_advances.id = selected_rows.finance_case_id;

  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (pay_batch_item_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (pay_batch_candidate_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (candidate_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (umbrella_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (transfer_group_key);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (reservation_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (payout_transfer_id);
  CREATE INDEX ON pg_temp._tmp_pre_bank_cancel_selected (finance_component_id);

  SELECT
    count(*)::integer,
    count(DISTINCT pre_bank_selected.candidate_id) FILTER (WHERE pre_bank_selected.candidate_id IS NOT NULL)::integer,
    count(DISTINCT pre_bank_selected.pay_bank_transfer_id) FILTER (WHERE pre_bank_selected.pay_bank_transfer_id IS NOT NULL)::integer,
    count(DISTINCT pre_bank_selected.reservation_id) FILTER (WHERE pre_bank_selected.reservation_id IS NOT NULL)::integer,
    count(DISTINCT pre_bank_selected.finance_component_id) FILTER (WHERE pre_bank_selected.finance_component_id IS NOT NULL)::integer
  INTO
    v_selected_item_count,
    v_selected_candidate_count,
    v_selected_transfer_count,
    v_selected_reservation_count,
    v_selected_finance_component_count
  FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected;

  SELECT immutable_membership.*
  INTO v_membership
  FROM public.pay_payment_correction_request_candidates AS immutable_membership
  WHERE immutable_membership.correction_request_id = v_work_item.correction_request_id
    AND immutable_membership.pay_batch_candidate_id = v_work_item.pay_batch_candidate_id;

  IF NOT FOUND THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_MEMBERSHIP_MISMATCH',
      'message', 'The correction work item does not have immutable request membership.'
    );
  ELSIF v_membership.active_item_count NOT BETWEEN 1 AND 128
     OR v_membership.source_row_count NOT BETWEEN 1 AND 512
     OR v_membership.active_item_count <> v_selected_item_count
     OR v_work_item.selection_hash IS DISTINCT FROM v_membership.candidate_scope_hash THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_MEMBERSHIP_MISMATCH',
      'message', 'The correction work item no longer matches its immutable request membership.',
      'expected_item_count', v_membership.active_item_count,
      'resolved_item_count', v_selected_item_count
    );
  ELSE
    SELECT count(*)::integer
    INTO v_membership_item_mismatch_count
    FROM (
      (
        SELECT unnest(v_membership.pay_batch_item_ids) AS pay_batch_item_id
        EXCEPT
        SELECT selected_membership_items.pay_batch_item_id
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_membership_items
      )
      UNION ALL
      (
        SELECT selected_membership_items.pay_batch_item_id
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_membership_items
        EXCEPT
        SELECT unnest(v_membership.pay_batch_item_ids) AS pay_batch_item_id
      )
    ) AS membership_difference;

    IF v_membership_item_mismatch_count > 0 THEN
      v_blocker := jsonb_build_object(
        'code', 'WORK_MEMBERSHIP_MISMATCH',
        'message', 'The frozen payment-item membership differs from the reviewed selection.',
        'mismatch_count', v_membership_item_mismatch_count
      );
    END IF;
  END IF;

  IF v_blocker IS NOT NULL THEN
    UPDATE public.pay_payment_correction_work_items AS membership_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(membership_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE membership_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  IF v_selected_item_count = 0 THEN
    v_blocker := jsonb_build_object(
      'code', 'NO_SELECTED_PAYMENT_ITEMS_FOR_PRE_BANK_CANCEL',
      'message', 'No selectable pay_batch_items were resolved for the pre-bank cancellation work item.'
    );

    UPDATE public.pay_payment_correction_work_items AS no_items_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(no_items_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE no_items_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;
v_scope_type := upper(btrim(COALESCE(v_work_item.selection_json->>'scope_type', '')));
v_work_unit := upper(btrim(COALESCE(v_work_item.selection_json->>'work_unit', '')));

SELECT count(*)::integer
INTO v_total_active_batch_item_count
FROM public.pay_batch_items AS total_batch_items
JOIN public.pay_batch_candidates AS total_batch_candidates
  ON total_batch_candidates.id = total_batch_items.pay_batch_candidate_id
WHERE total_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
  AND COALESCE(total_batch_items.is_voided, false) = false;

v_is_whole_batch_work_item := (
  v_scope_type = 'BATCH'
  AND COALESCE(NULLIF(v_work_unit, ''), 'BATCH') = 'BATCH'
  AND v_selected_item_count = COALESCE(v_total_active_batch_item_count, 0)
);

IF v_work_item.selection_json ? 'expected_item_count' THEN
  IF COALESCE(v_work_item.selection_json->>'expected_item_count', '') !~ '^[0-9]+$' THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_SELECTION_DRIFT',
      'message', 'Correction work item expected_item_count is not a valid non-negative integer.',
      'expected_item_count_raw', v_work_item.selection_json->>'expected_item_count'
    );

    UPDATE public.pay_payment_correction_work_items AS pre_bank_cancel_invalid_expected_count_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(pre_bank_cancel_invalid_expected_count_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE pre_bank_cancel_invalid_expected_count_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  v_expected_item_count := (v_work_item.selection_json->>'expected_item_count')::integer;

  IF v_expected_item_count <> v_selected_item_count THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_SELECTION_DRIFT',
      'message', 'Correction work item selection no longer resolves to the expected selected pay_batch_item count.',
      'expected_item_count', v_expected_item_count,
      'resolved_item_count', v_selected_item_count
    );

    UPDATE public.pay_payment_correction_work_items AS pre_bank_cancel_expected_count_drift_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(pre_bank_cancel_expected_count_drift_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE pre_bank_cancel_expected_count_drift_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;
END IF;

IF v_work_item.selection_json ? 'expected_pay_batch_item_ids'
   AND COALESCE(jsonb_typeof(v_work_item.selection_json->'expected_pay_batch_item_ids'), 'null') <> 'array' THEN
  v_blocker := jsonb_build_object(
    'code', 'WORK_SELECTION_DRIFT',
    'message', 'Correction work item expected_pay_batch_item_ids must be a JSON array.'
  );

  UPDATE public.pay_payment_correction_work_items AS pre_bank_cancel_expected_ids_type_work
  SET
    status = 'BLOCKED',
    locked_at_utc = NULL,
    locked_by = NULL,
    processed_at_utc = v_now,
    last_error = v_blocker->>'message',
    result_json = COALESCE(pre_bank_cancel_expected_ids_type_work.result_json, '{}'::jsonb) || jsonb_build_object(
      'ok', false,
      'status', 'BLOCKED',
      'blocker', v_blocker,
      'processed_at_utc', v_now
    )
  WHERE pre_bank_cancel_expected_ids_type_work.id = p_work_item_id;

  RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
END IF;

DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_expected_items;
CREATE TEMP TABLE _tmp_pre_bank_cancel_expected_items ON COMMIT DROP AS
WITH raw_expected_item_ids AS (
  SELECT jsonb_array_elements_text(
    CASE
      WHEN COALESCE(jsonb_typeof(v_work_item.selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
        THEN v_work_item.selection_json->'expected_pay_batch_item_ids'
      ELSE '[]'::jsonb
    END
  ) AS raw_pay_batch_item_id
)
SELECT DISTINCT
  raw_expected_item_ids.raw_pay_batch_item_id,
  CASE
    WHEN raw_expected_item_ids.raw_pay_batch_item_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN raw_expected_item_ids.raw_pay_batch_item_id::uuid
    ELSE NULL::uuid
  END AS pay_batch_item_id
FROM raw_expected_item_ids;

SELECT count(*)::integer
INTO v_expected_item_mismatch_count
FROM pg_temp._tmp_pre_bank_cancel_expected_items AS invalid_expected_items
WHERE invalid_expected_items.pay_batch_item_id IS NULL;

IF v_expected_item_mismatch_count > 0 THEN
  v_blocker := jsonb_build_object(
    'code', 'WORK_SELECTION_DRIFT',
    'message', 'Correction work item expected_pay_batch_item_ids contains invalid UUID values.',
    'invalid_expected_item_count', v_expected_item_mismatch_count
  );

  UPDATE public.pay_payment_correction_work_items AS pre_bank_cancel_invalid_expected_ids_work
  SET
    status = 'BLOCKED',
    locked_at_utc = NULL,
    locked_by = NULL,
    processed_at_utc = v_now,
    last_error = v_blocker->>'message',
    result_json = COALESCE(pre_bank_cancel_invalid_expected_ids_work.result_json, '{}'::jsonb) || jsonb_build_object(
      'ok', false,
      'status', 'BLOCKED',
      'blocker', v_blocker,
      'processed_at_utc', v_now
    )
  WHERE pre_bank_cancel_invalid_expected_ids_work.id = p_work_item_id;

  RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
END IF;

SELECT count(*)::integer
INTO v_expected_item_id_count
FROM pg_temp._tmp_pre_bank_cancel_expected_items AS expected_item_count
WHERE expected_item_count.pay_batch_item_id IS NOT NULL;

IF v_expected_item_id_count > 0 THEN
  SELECT count(*)::integer
  INTO v_expected_item_mismatch_count
  FROM (
    (
      SELECT expected_items.pay_batch_item_id
      FROM pg_temp._tmp_pre_bank_cancel_expected_items AS expected_items
      WHERE expected_items.pay_batch_item_id IS NOT NULL
      EXCEPT
      SELECT selected_items.pay_batch_item_id
      FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_items
    )
    UNION ALL
    (
      SELECT selected_items.pay_batch_item_id
      FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_items
      EXCEPT
      SELECT expected_items.pay_batch_item_id
      FROM pg_temp._tmp_pre_bank_cancel_expected_items AS expected_items
      WHERE expected_items.pay_batch_item_id IS NOT NULL
    )
  ) AS expected_item_drift;

  IF v_expected_item_mismatch_count > 0 THEN
    v_blocker := jsonb_build_object(
      'code', 'WORK_SELECTION_DRIFT',
      'message', 'Correction work item selection no longer resolves to the expected selected pay_batch_items.',
      'expected_item_count', v_expected_item_id_count,
      'resolved_item_count', v_selected_item_count,
      'mismatch_count', v_expected_item_mismatch_count
    );

    UPDATE public.pay_payment_correction_work_items AS pre_bank_cancel_expected_ids_drift_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(pre_bank_cancel_expected_ids_drift_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE pre_bank_cancel_expected_ids_drift_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;
END IF;


  PERFORM 1
  FROM public.pay_batch_candidates AS locked_batch_candidates
  WHERE locked_batch_candidates.id IN (
    SELECT DISTINCT lock_selected_candidates.pay_batch_candidate_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_candidates
    WHERE lock_selected_candidates.pay_batch_candidate_id IS NOT NULL
  )
  FOR UPDATE OF locked_batch_candidates;

  PERFORM 1
  FROM public.pay_batch_items AS locked_batch_items
  JOIN pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_items
    ON lock_selected_items.pay_batch_item_id = locked_batch_items.id
  ORDER BY locked_batch_items.id
  FOR UPDATE OF locked_batch_items;

  PERFORM 1
  FROM public.pay_bank_transfers AS locked_bank_transfers
  WHERE locked_bank_transfers.id IN (
    SELECT DISTINCT lock_selected_transfers.pay_bank_transfer_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_transfers
    WHERE lock_selected_transfers.pay_bank_transfer_id IS NOT NULL
  )
  FOR UPDATE OF locked_bank_transfers;

  PERFORM 1
  FROM public.pay_advance_reservations AS locked_advance_reservations
  WHERE locked_advance_reservations.id IN (
    SELECT DISTINCT lock_selected_reservations.reservation_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_reservations
    WHERE lock_selected_reservations.reservation_id IS NOT NULL
  )
  FOR UPDATE OF locked_advance_reservations;

  PERFORM 1
  FROM public.pay_finance_case_components AS locked_finance_case_components
  WHERE locked_finance_case_components.id IN (
    SELECT DISTINCT lock_selected_components.finance_component_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_components
    WHERE lock_selected_components.finance_component_id IS NOT NULL
  )
  FOR UPDATE OF locked_finance_case_components;

  PERFORM 1
  FROM public.pay_advances AS locked_pay_advances
  WHERE locked_pay_advances.id IN (
    SELECT DISTINCT lock_selected_cases.finance_case_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS lock_selected_cases
    WHERE lock_selected_cases.finance_case_id IS NOT NULL
  )
  FOR UPDATE OF locked_pay_advances;

  -- Rebuild and lock the complete candidate-owned financial/source scope after
  -- acquiring the mutation guard and before the first financial write. The
  -- planning count is an immutable promise, not execution-time authority.
  v_capacity_selected_scope_json := jsonb_build_object(
    'scope_type', 'CANDIDATES',
    'work_unit', 'CANDIDATE',
    'pay_batch_ids', jsonb_build_array(v_work_item.pay_batch_id),
    'pay_batch_candidate_ids', jsonb_build_array(v_work_item.pay_batch_candidate_id),
    'candidate_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.candidate_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.candidate_id IS NOT NULL) AS scope_value
    ), '[]'::jsonb),
    'pay_batch_item_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.pay_batch_item_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope) AS scope_value
    ), '[]'::jsonb),
    'umbrella_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.umbrella_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.umbrella_id IS NOT NULL) AS scope_value
    ), '[]'::jsonb),
    'finance_case_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.finance_case_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.finance_case_id IS NOT NULL) AS scope_value
    ), '[]'::jsonb),
    'finance_component_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.finance_component_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.finance_component_id IS NOT NULL) AS scope_value
    ), '[]'::jsonb),
    'reservation_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.reservation_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.reservation_id IS NOT NULL) AS scope_value
    ), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (
        SELECT DISTINCT selected_scope.pay_bank_transfer_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.pay_bank_transfer_id IS NOT NULL
        UNION SELECT DISTINCT selected_scope.payout_transfer_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.payout_transfer_id IS NOT NULL
      ) AS scope_value
    ), '[]'::jsonb),
    'payout_transfer_ids', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (
        SELECT DISTINCT selected_scope.payout_transfer_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.payout_transfer_id IS NOT NULL
        UNION SELECT DISTINCT selected_scope.pay_bank_transfer_id::text AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.pay_bank_transfer_id IS NOT NULL
      ) AS scope_value
    ), '[]'::jsonb),
    'transfer_group_keys', COALESCE((
      SELECT jsonb_agg(scope_value.value_text ORDER BY scope_value.value_text)
      FROM (SELECT DISTINCT selected_scope.transfer_group_key AS value_text FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE NULLIF(btrim(COALESCE(selected_scope.transfer_group_key, '')), '') IS NOT NULL) AS scope_value
    ), '[]'::jsonb)
  );

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_capacity_mail_scope;
  CREATE TEMP TABLE _tmp_pre_bank_capacity_mail_scope ON COMMIT DROP AS
  SELECT
    mail_row.id AS mail_outbox_id,
    mail_match.match_result,
    COALESCE(NULLIF(mail_match.match_result->>'safe_to_cancel', '')::boolean, false) AS safe_to_cancel,
    COALESCE(NULLIF(mail_match.match_result->>'requires_review', '')::boolean, false) AS requires_review,
    COALESCE(mail_match.match_result->>'match_kind', 'NONE') AS match_kind,
    COALESCE(mail_match.match_result->>'match_confidence', 'NONE') AS match_confidence
  FROM public.mail_outbox AS mail_row
  CROSS JOIN LATERAL (
    SELECT public._pay_payment_correction_mail_scope_match(
      mail_row.id, v_work_item.pay_batch_id, v_work_item.selection_json,
      v_capacity_selected_scope_json, false
    ) AS match_result
  ) AS mail_match
  WHERE upper(btrim(COALESCE(mail_row.status::text, ''))) = 'QUEUED'
    AND lower(concat_ws('|', mail_row.type, mail_row.email_type, mail_row.context_kind, mail_row.reference, COALESCE(mail_row.payment_scope_json::text, '{}'))) LIKE ANY (ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%'])
    AND COALESCE(NULLIF(mail_match.match_result->>'matched', '')::boolean, false);

  PERFORM 1
  FROM public.mail_outbox AS locked_mail
  JOIN pg_temp._tmp_pre_bank_capacity_mail_scope AS capacity_mail
    ON capacity_mail.mail_outbox_id = locked_mail.id
  FOR UPDATE OF locked_mail;

  -- Recheck status after any row-lock wait. Sender-wins rows are now SENT and
  -- are deliberately outside the V2 financial hash; cancellation-wins rows
  -- remain locked QUEUED until the atomic communications phase below.
  SELECT
    pg_catalog.count(*) FILTER (
      WHERE upper(btrim(COALESCE(locked_mail.status::text, ''))) = 'QUEUED'
    )::integer,
    pg_catalog.count(*) FILTER (
      WHERE upper(btrim(COALESCE(locked_mail.status::text, ''))) = 'QUEUED'
        AND NOT (
          COALESCE(capacity_mail.safe_to_cancel, false)
          AND (
            capacity_mail.match_confidence = 'EXACT'
            OR (v_is_whole_batch_work_item AND capacity_mail.match_kind = 'WHOLE_BATCH')
          )
        )
    )::integer
  INTO v_matching_queued_count, v_unsafe_queued_count
  FROM pg_temp._tmp_pre_bank_capacity_mail_scope AS capacity_mail
  JOIN public.mail_outbox AS locked_mail
    ON locked_mail.id = capacity_mail.mail_outbox_id;

  IF v_candidate_scope_contract_version = 2 THEN
    SELECT
      pg_catalog.count(*) FILTER (
        WHERE upper(btrim(COALESCE(mail_row.status::text, ''))) = 'SENT'
      )::integer,
      pg_catalog.count(*) FILTER (
        WHERE upper(btrim(COALESCE(mail_row.status::text, ''))) NOT IN ('QUEUED', 'SENT')
      )::integer
    INTO v_already_sent_untouched_count, v_other_terminal_untouched_count
    FROM public.mail_outbox AS mail_row
    CROSS JOIN LATERAL (
      SELECT public._pay_payment_correction_mail_scope_match(
        mail_row.id, v_work_item.pay_batch_id, v_work_item.selection_json,
        v_capacity_selected_scope_json, false
      ) AS match_result
    ) AS mail_match
    WHERE lower(concat_ws('|', mail_row.type, mail_row.email_type, mail_row.context_kind, mail_row.reference, COALESCE(mail_row.payment_scope_json::text, '{}'))) LIKE ANY (ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%'])
      AND COALESCE(NULLIF(mail_match.match_result->>'matched', '')::boolean, false);

    IF v_unsafe_queued_count > 0 THEN
      v_blocker := jsonb_build_object(
        'code', 'COMMUNICATION_CLEANUP_UNSAFE',
        'message', 'Queued payment communications could not be bound safely to the reviewed cancellation scope.',
        'unsafe_queued_count', v_unsafe_queued_count
      );
      UPDATE public.pay_payment_correction_work_items AS communication_blocked_work
      SET status = 'BLOCKED', locked_at_utc = NULL, locked_by = NULL,
          processed_at_utc = v_now, last_error = v_blocker->>'message',
          result_json = COALESCE(communication_blocked_work.result_json, '{}'::jsonb)
            || jsonb_build_object(
              'ok', false,
              'status', 'BLOCKED',
              'blocker', v_blocker,
              'candidate_scope_contract_version', 2,
              'communication_cleanup_contract_version', 1,
              'processed_at_utc', v_now
            )
      WHERE communication_blocked_work.id = p_work_item_id;
      RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
    END IF;
  END IF;

  PERFORM 1
  FROM public.pay_batch_items AS locked_instruction_items
  LEFT JOIN public.pay_bank_transfers AS instruction_transfer
    ON instruction_transfer.id = locked_instruction_items.pay_bank_transfer_id
  WHERE locked_instruction_items.id IN (SELECT selected_scope.pay_batch_item_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope)
     OR locked_instruction_items.pay_bank_transfer_id IN (
          SELECT selected_scope.pay_bank_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.pay_bank_transfer_id IS NOT NULL
          UNION SELECT selected_scope.payout_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.payout_transfer_id IS NOT NULL
     )
     OR instruction_transfer.transfer_group_key IN (
          SELECT selected_scope.transfer_group_key FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE NULLIF(btrim(COALESCE(selected_scope.transfer_group_key, '')), '') IS NOT NULL
     )
  FOR SHARE OF locked_instruction_items;

  PERFORM 1 FROM public.pay_batch_item_breakdowns AS locked_source WHERE locked_source.pay_batch_item_id IN (SELECT selected_scope.pay_batch_item_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope) FOR SHARE OF locked_source;
  PERFORM 1 FROM public.pay_batch_timesheet_snapshots AS locked_source WHERE locked_source.pay_batch_id = v_work_item.pay_batch_id AND locked_source.candidate_id = v_work_item.candidate_id FOR SHARE OF locked_source;
  PERFORM 1 FROM public.timesheet_pay_state_history AS locked_source WHERE locked_source.pay_batch_id = v_work_item.pay_batch_id AND locked_source.timesheet_id IN (SELECT selected_scope.timesheet_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.timesheet_id IS NOT NULL) FOR SHARE OF locked_source;
  PERFORM 1 FROM public.pay_manual_adjustment_carry_forwards AS locked_source WHERE locked_source.source_pay_batch_item_id IN (SELECT selected_scope.pay_batch_item_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope) OR locked_source.target_pay_batch_item_id IN (SELECT selected_scope.pay_batch_item_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope) FOR UPDATE OF locked_source;
  PERFORM 1 FROM public.pay_bank_transfer_events AS locked_source WHERE locked_source.pay_batch_id = v_work_item.pay_batch_id AND (locked_source.pay_bank_transfer_id IN (SELECT selected_scope.pay_bank_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.pay_bank_transfer_id IS NOT NULL UNION SELECT selected_scope.payout_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.payout_transfer_id IS NOT NULL) OR locked_source.candidate_id = v_work_item.candidate_id) FOR SHARE OF locked_source;
  PERFORM 1 FROM public.banking_pay_operation_transfer_scope AS locked_source WHERE locked_source.pay_batch_id = v_work_item.pay_batch_id AND (locked_source.pay_bank_transfer_id IN (SELECT selected_scope.pay_bank_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.pay_bank_transfer_id IS NOT NULL UNION SELECT selected_scope.payout_transfer_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE selected_scope.payout_transfer_id IS NOT NULL) OR locked_source.transfer_group_key IN (SELECT selected_scope.transfer_group_key FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope WHERE NULLIF(btrim(COALESCE(selected_scope.transfer_group_key, '')), '') IS NOT NULL)) FOR SHARE OF locked_source;
  PERFORM 1 FROM public.banking_pay_operation_transfer_scope_items AS locked_source WHERE locked_source.pay_batch_item_id IN (SELECT selected_scope.pay_batch_item_id FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope) FOR SHARE OF locked_source;
  PERFORM 1 FROM public.pay_batch_paye_net_inputs AS locked_source WHERE locked_source.pay_batch_candidate_id = v_work_item.pay_batch_candidate_id FOR SHARE OF locked_source;

  -- Obtain the two independent authorities without multiplying source rows by
  -- item rows.
  SELECT count(*)::integer INTO v_current_active_item_count
  FROM public.pay_batch_items AS current_item
  WHERE current_item.id = ANY(v_membership.pay_batch_item_ids)
    AND COALESCE(current_item.is_voided, false) IS NOT TRUE;
  WITH selected_items AS (SELECT selected_scope.* FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope),
  transfer_ids AS (SELECT selected_item.pay_bank_transfer_id AS id FROM selected_items AS selected_item WHERE selected_item.pay_bank_transfer_id IS NOT NULL UNION SELECT selected_item.payout_transfer_id FROM selected_items AS selected_item WHERE selected_item.payout_transfer_id IS NOT NULL),
  transfer_groups AS (SELECT DISTINCT selected_item.transfer_group_key FROM selected_items AS selected_item WHERE NULLIF(btrim(COALESCE(selected_item.transfer_group_key, '')), '') IS NOT NULL),
  financial_scope_items AS (SELECT DISTINCT item_scope.id FROM public.pay_batch_items AS item_scope LEFT JOIN public.pay_bank_transfers AS item_transfer ON item_transfer.id = item_scope.pay_bank_transfer_id WHERE item_scope.id IN (SELECT selected_item.pay_batch_item_id FROM selected_items AS selected_item) OR item_scope.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR item_transfer.transfer_group_key IN (SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group)),
  source_counts AS (
    SELECT 1::bigint AS row_count UNION ALL SELECT count(*) FROM financial_scope_items
    UNION ALL SELECT count(*) FROM public.pay_batch_item_breakdowns AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
    UNION ALL SELECT count(*) FROM public.pay_batch_timesheet_snapshots AS source_row WHERE source_row.pay_batch_id = v_work_item.pay_batch_id AND source_row.candidate_id = v_work_item.candidate_id
    UNION ALL SELECT count(*) FROM public.timesheet_pay_state_history AS source_row WHERE source_row.pay_batch_id = v_work_item.pay_batch_id AND source_row.timesheet_id IN (SELECT selected_item.timesheet_id FROM selected_items AS selected_item WHERE selected_item.timesheet_id IS NOT NULL)
    UNION ALL SELECT count(*) FROM public.pay_advance_reservations AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
    UNION ALL SELECT count(*) FROM public.pay_finance_case_components AS source_row WHERE source_row.id IN (SELECT selected_item.finance_component_id FROM selected_items AS selected_item WHERE selected_item.finance_component_id IS NOT NULL)
    UNION ALL SELECT count(*) FROM public.pay_manual_adjustment_carry_forwards AS source_row WHERE source_row.source_pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item) OR source_row.target_pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
    UNION ALL SELECT count(*) FROM public.pay_advances AS source_row WHERE source_row.id IN (SELECT selected_item.finance_case_id FROM selected_items AS selected_item WHERE selected_item.finance_case_id IS NOT NULL)
    UNION ALL SELECT count(*) FROM public.pay_bank_transfers AS source_row WHERE source_row.id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.transfer_group_key IN (SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group)
    UNION ALL SELECT count(*) FROM public.pay_bank_transfer_events AS source_row WHERE source_row.pay_batch_id = v_work_item.pay_batch_id AND (source_row.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.candidate_id = v_work_item.candidate_id)
    UNION ALL SELECT count(*) FROM public.banking_pay_operation_transfer_scope AS source_row WHERE source_row.pay_batch_id = v_work_item.pay_batch_id AND (source_row.pay_bank_transfer_id IN (SELECT transfer_id.id FROM transfer_ids AS transfer_id) OR source_row.transfer_group_key IN (SELECT transfer_group.transfer_group_key FROM transfer_groups AS transfer_group))
    UNION ALL SELECT count(*) FROM public.banking_pay_operation_transfer_scope_items AS source_row WHERE source_row.pay_batch_item_id IN (SELECT scope_item.id FROM financial_scope_items AS scope_item)
    UNION ALL SELECT count(*) FROM public.pay_batch_paye_net_inputs AS source_row WHERE source_row.pay_batch_candidate_id = v_work_item.pay_batch_candidate_id
  ) SELECT COALESCE(sum(source_count.row_count), 0)::integer INTO v_current_source_row_count FROM source_counts AS source_count;

  IF v_candidate_scope_contract_version = 1 THEN
    v_current_source_row_count := v_current_source_row_count + v_matching_queued_count;
  END IF;

  SELECT private.pay_payment_correction_sha256_v1(
    jsonb_build_object(
      'version', v_candidate_scope_hash_version,
      'pay_batch_candidate_id', v_work_item.pay_batch_candidate_id,
      'candidate_id', v_work_item.candidate_id,
      'requested_action', COALESCE(v_request.plan_json->>'requested_action', v_request.selection_json->>'requested_action'),
      'pay_batch_item_ids', to_jsonb(v_membership.pay_batch_item_ids),
      'item_count', v_current_active_item_count,
      'source_row_count', v_current_source_row_count,
      'active_amount_pence', round(COALESCE(candidate_scope.net_bank_amount, 0) * 100)::bigint,
      'item_contract', (
        SELECT jsonb_agg(jsonb_build_object(
          'id', item_scope.id, 'item_type', item_scope.item_type,
          'amount_ex_vat_pence', round(COALESCE(item_scope.amount_ex_vat, 0) * 100)::bigint,
          'amount_vat_pence', round(COALESCE(item_scope.amount_vat, 0) * 100)::bigint,
          'amount_inc_vat_pence', round(COALESCE(item_scope.amount_inc_vat, 0) * 100)::bigint,
          'reservation_id', item_scope.reservation_id,
          'finance_component_id', item_scope.finance_component_id,
          'pay_bank_transfer_id', item_scope.pay_bank_transfer_id,
          'operation_source_key', item_scope.operation_source_key,
          'frozen_component_snapshot_json', item_scope.frozen_component_snapshot_json,
          'frozen_source_basis_json', item_scope.frozen_source_basis_json
        ) ORDER BY item_scope.id)
        FROM public.pay_batch_items AS item_scope
        WHERE item_scope.id = ANY(v_membership.pay_batch_item_ids)
          AND COALESCE(item_scope.is_voided, false) IS NOT TRUE
      ),
      'shared_instruction_scope_hash', v_membership.shared_instruction_scope_hash,
      'eligibility_code', v_membership.eligibility_code_at_plan,
      'cancellation_reversion_pre_request_authority_digest',
        COALESCE(
          v_work_item.selection_json->>'candidate_scope_hash_pre_request_authority_digest',
          v_work_item.selection_json->'cancellation_reversion_pre_request_authority'->>'authority_digest'
        )
    ) || CASE WHEN v_candidate_scope_contract_version = 2 THEN
      jsonb_build_object(
        'contract', 'PAYMENT_CORRECTION_CANDIDATE_SCOPE_V2',
        'source_row_count_semantics', 'FINANCIAL_ONLY'
      )
    ELSE '{}'::jsonb END
  ) INTO v_current_candidate_scope_hash
  FROM public.pay_batch_candidates AS candidate_scope
  WHERE candidate_scope.id = v_work_item.pay_batch_candidate_id;

  IF v_current_active_item_count <> v_membership.active_item_count
     OR v_current_active_item_count > 128
     OR v_current_source_row_count <> v_membership.source_row_count
     OR v_current_source_row_count > 512
     OR v_current_candidate_scope_hash IS DISTINCT FROM v_membership.candidate_scope_hash THEN
    v_blocker := jsonb_build_object(
      'code', CASE WHEN v_current_active_item_count > 128 OR v_current_source_row_count > 512 THEN 'CANDIDATE_SCOPE_TOO_LARGE' ELSE 'SOURCE_SCOPE_CHANGED' END,
      'message', 'The payment source scope changed after review. Refresh and start again.',
      'expected_item_count', v_membership.active_item_count,
      'actual_item_count', v_current_active_item_count,
      'expected_source_row_count', v_membership.source_row_count,
      'actual_source_row_count', v_current_source_row_count,
      'candidate_scope_hash_matches', v_current_candidate_scope_hash = v_membership.candidate_scope_hash
    );
    UPDATE public.pay_payment_correction_work_items AS capacity_blocked_work
    SET status = 'BLOCKED', locked_at_utc = NULL, locked_by = NULL,
        processed_at_utc = v_now, last_error = v_blocker->>'message',
        result_json = COALESCE(capacity_blocked_work.result_json, '{}'::jsonb)
          || jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker, 'processed_at_utc', v_now)
    WHERE capacity_blocked_work.id = p_work_item_id;
    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  v_resolved_scope_json := public._pay_resolve_payment_scope_for_cancel_rewind(
    v_work_item.pay_batch_id,
    COALESCE(v_work_item.selection_json, '{}'::jsonb),
    true,
    v_effective_actor_user_id
  );

  IF COALESCE((v_resolved_scope_json->>'is_full_scope')::boolean, false) IS NOT TRUE
     OR jsonb_array_length(COALESCE(v_resolved_scope_json->'partial_scope_blockers', '[]'::jsonb)) > 0 THEN
    v_blocker := jsonb_build_object(
      'code', 'SELECT_FULL_UNPAID_PAYMENT_SCOPE_REQUIRED',
      'message', 'Pre-bank cancellation requires the full frozen payment scope so linked finance, reservations, transfers, and manual adjustment lines are not left behind.',
      'resolved_scope', v_resolved_scope_json,
      'partial_scope_blockers', COALESCE(v_resolved_scope_json->'partial_scope_blockers', '[]'::jsonb)
    );

    UPDATE public.pay_payment_correction_work_items AS partial_scope_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(partial_scope_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'resolved_scope', v_resolved_scope_json,
        'processed_at_utc', v_now
      )
    WHERE partial_scope_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker, 'resolved_scope', v_resolved_scope_json);
  END IF;
  v_classification_result := public._pay_payment_movement_classify(
    v_work_item.pay_batch_id,
    COALESCE(v_work_item.selection_json, '{}'::jsonb) || jsonb_build_object(
      'requested_action', 'CANCEL_PAYMENT_ATTEMPT',
      'source_context', 'WORK_ITEM_APPLY'
    )
  );

  v_classification := COALESCE(v_classification_result->>'classification', COALESCE(v_classification_result->>'payment_lifecycle_state', 'AMBIGUOUS_REVIEW_REQUIRED'));

  IF v_classification IN ('PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION', 'CANCELLED_BEFORE_BANK_SUBMISSION') THEN
    WITH original_expected_raw AS (
      SELECT original_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(v_request.selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
            THEN v_request.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS original_values(raw_value)
    ),
    original_expected AS (
      SELECT DISTINCT
        original_expected_raw.raw_value,
        CASE
          WHEN original_expected_raw.raw_value ~* v_uuid_regex
            THEN original_expected_raw.raw_value::uuid
          ELSE NULL::uuid
        END AS pay_batch_item_id
      FROM original_expected_raw
    ),
    original_expected_valid AS (
      SELECT original_expected.pay_batch_item_id
      FROM original_expected
      WHERE original_expected.pay_batch_item_id IS NOT NULL
    ),
    original_item_state AS (
      SELECT
        original_expected_valid.pay_batch_item_id,
        batch_items.id IS NOT NULL
          AND batch_candidates.pay_batch_id = v_work_item.pay_batch_id AS belongs_to_batch,
        COALESCE(batch_items.is_voided, false) AS is_voided,
        EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS same_request_correction_items
          WHERE same_request_correction_items.correction_request_id = v_work_item.correction_request_id
            AND same_request_correction_items.pay_batch_item_id = original_expected_valid.pay_batch_item_id
            AND same_request_correction_items.correction_item_kind = 'PRE_BANK_CANCEL'
            AND same_request_correction_items.status = 'APPLIED'
        ) AS voided_by_same_request,
        EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS any_applied_correction_items
          WHERE any_applied_correction_items.pay_batch_item_id = original_expected_valid.pay_batch_item_id
            AND any_applied_correction_items.status = 'APPLIED'
        ) AS has_any_applied_correction
      FROM original_expected_valid
      LEFT JOIN public.pay_batch_items AS batch_items
        ON batch_items.id = original_expected_valid.pay_batch_item_id
      LEFT JOIN public.pay_batch_candidates AS batch_candidates
        ON batch_candidates.id = batch_items.pay_batch_candidate_id
    )
    SELECT
      jsonb_array_length(
        CASE
          WHEN COALESCE(jsonb_typeof(v_request.selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
            THEN v_request.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      )::integer,
      (SELECT count(*)::integer FROM original_expected_valid),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch AND NOT original_item_state.is_voided),
      (SELECT count(*)::integer FROM original_item_state WHERE original_item_state.belongs_to_batch AND original_item_state.is_voided AND original_item_state.voided_by_same_request),
      (
        SELECT count(*)::integer
        FROM original_item_state
        WHERE original_item_state.belongs_to_batch
          AND NOT (
            (
              NOT original_item_state.is_voided
              AND NOT original_item_state.has_any_applied_correction
            )
            OR (
              original_item_state.is_voided
              AND original_item_state.voided_by_same_request
            )
          )
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_batch_items AS active_outside_items
        JOIN public.pay_batch_candidates AS active_outside_candidates
          ON active_outside_candidates.id = active_outside_items.pay_batch_candidate_id
        WHERE active_outside_candidates.pay_batch_id = v_work_item.pay_batch_id
          AND COALESCE(active_outside_items.is_voided, false) = false
          AND NOT EXISTS (
            SELECT 1
            FROM original_expected_valid
            WHERE original_expected_valid.pay_batch_item_id = active_outside_items.id
          )
      ),
      (
        SELECT count(*)::integer
        FROM pg_temp._tmp_pre_bank_cancel_expected_items AS current_expected_items
        WHERE current_expected_items.pay_batch_item_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM original_expected_valid
            WHERE original_expected_valid.pay_batch_item_id = current_expected_items.pay_batch_item_id
          )
      ),
      (
        SELECT count(*)::integer
        FROM public.pay_payment_correction_work_items AS applied_sibling_items
        WHERE applied_sibling_items.correction_request_id = v_work_item.correction_request_id
          AND applied_sibling_items.id <> p_work_item_id
          AND applied_sibling_items.work_kind = 'PRE_BANK_CANCEL'
          AND applied_sibling_items.status = 'APPLIED'
      )
    INTO
      v_original_expected_json_count,
      v_original_expected_valid_count,
      v_original_expected_belongs_count,
      v_original_expected_active_count,
      v_original_expected_same_request_voided_count,
      v_original_expected_disallowed_state_count,
      v_active_outside_original_count,
      v_current_expected_outside_original_count,
      v_applied_sibling_count;

    v_same_request_partial_continuation := (
      v_request.correction_kind = 'PRE_BANK_CANCEL'
      AND UPPER(BTRIM(COALESCE(v_request.selection_json->>'scope_type', ''))) IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH')
      AND NULLIF(BTRIM(COALESCE(v_work_item.selection_json->>'source_correction_request_id', '')), '') = v_work_item.correction_request_id::text
      AND v_original_expected_json_count > 0
      AND v_original_expected_valid_count = v_original_expected_json_count
      AND v_original_expected_belongs_count = v_original_expected_json_count
      AND v_original_expected_active_count > 0
      AND v_original_expected_same_request_voided_count > 0
      AND v_original_expected_active_count + v_original_expected_same_request_voided_count = v_original_expected_json_count
      AND v_original_expected_disallowed_state_count = 0
      AND v_active_outside_original_count = 0
      AND v_current_expected_outside_original_count = 0
      AND v_applied_sibling_count > 0
    );
  END IF;

  IF NOT (
    v_classification IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
    OR COALESCE((v_classification_result->>'can_pre_provider_cancel')::boolean, false) = true
    OR COALESCE(v_classification_result->>'recommended_action', '') = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
    OR (
      v_classification IN ('PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION', 'CANCELLED_BEFORE_BANK_SUBMISSION')
      AND v_same_request_partial_continuation
    )
  ) THEN
    v_blocker := jsonb_build_object(
      'code', 'PRE_BANK_CANCEL_CLASSIFICATION_REQUIRED',
      'message', 'Selected scope is no longer classified as local/pre-provider cancellation.',
      'classification', v_classification,
      'classification_result', v_classification_result,
      'same_request_partial_continuation', v_same_request_partial_continuation,
      'same_request_continuation_proof', jsonb_build_object(
        'original_expected_json_count', v_original_expected_json_count,
        'original_expected_valid_count', v_original_expected_valid_count,
        'original_expected_belongs_count', v_original_expected_belongs_count,
        'original_expected_active_count', v_original_expected_active_count,
        'original_expected_same_request_voided_count', v_original_expected_same_request_voided_count,
        'original_expected_disallowed_state_count', v_original_expected_disallowed_state_count,
        'active_outside_original_count', v_active_outside_original_count,
        'current_expected_outside_original_count', v_current_expected_outside_original_count,
        'applied_sibling_count', v_applied_sibling_count
      )
    );

    UPDATE public.pay_payment_correction_work_items AS classification_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(classification_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'classification_result', v_classification_result,
        'processed_at_utc', v_now
      )
    WHERE classification_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker, 'classification_result', v_classification_result);
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_batch_candidates
    JOIN pg_temp._tmp_pre_bank_cancel_selected AS settled_selected
      ON settled_selected.pay_batch_candidate_id = public.pay_batch_candidates.id
    WHERE upper(btrim(COALESCE(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
       OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.pay_bank_transfers
    JOIN pg_temp._tmp_pre_bank_cancel_selected AS settled_transfer_selected
      ON settled_transfer_selected.pay_bank_transfer_id = public.pay_bank_transfers.id
    WHERE upper(btrim(COALESCE(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
       OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.timesheet_pay_state_history
    JOIN pg_temp._tmp_pre_bank_cancel_selected AS settled_history_selected
      ON settled_history_selected.timesheet_id = public.timesheet_pay_state_history.timesheet_id
    WHERE public.timesheet_pay_state_history.pay_batch_id = v_work_item.pay_batch_id
  ) OR EXISTS (
    SELECT 1
    FROM public.pay_advance_reservations
    JOIN pg_temp._tmp_pre_bank_cancel_selected AS settled_reservation_selected
      ON settled_reservation_selected.reservation_id = public.pay_advance_reservations.id
    WHERE upper(btrim(COALESCE(public.pay_advance_reservations.status, ''))) = 'SETTLED'
       OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
  )
  INTO v_has_settlement_evidence;

  IF v_has_settlement_evidence THEN
    v_blocker := jsonb_build_object(
      'code', 'SELECTED_SCOPE_HAS_SETTLEMENT_EVIDENCE',
      'message', 'Pre-bank cancellation cannot apply because selected scope has settlement evidence.'
    );

    UPDATE public.pay_payment_correction_work_items AS settled_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(settled_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE settled_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  v_batch_execution_commit_state := upper(btrim(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED')));

  SELECT EXISTS (
    SELECT 1
    FROM public._pay_bank_transfer_provider_evidence_classify(
      v_work_item.pay_batch_id,
      NULL::uuid,
      v_resolved_scope_json,
      NULL::uuid
    ) AS provider_evidence
    WHERE COALESCE(provider_evidence.provider_submitted, false) = true
       OR COALESCE(provider_evidence.provider_request_sent, false) = true
       OR COALESCE(provider_evidence.provider_response_present, false) = true
       OR COALESCE(provider_evidence.provider_event_present, false) = true
       OR COALESCE(provider_evidence.provider_external_id_present, false) = true
       OR provider_evidence.evidence_class IN (
         'PROVIDER_REQUEST_SENT',
         'PROVIDER_RESPONSE_PRESENT',
         'PROVIDER_EVENT_PRESENT',
         'PROVIDER_EXTERNAL_ID_PRESENT',
         'PROVIDER_SUBMITTED',
         'PROVIDER_OUTCOME_UNKNOWN'
       )
  ) OR v_batch_execution_commit_state <> 'NOT_SUBMITTED'
    OR NULLIF(btrim(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL
    OR v_batch.execution_committed_at_utc IS NOT NULL
  INTO v_has_bank_submission_evidence;

  IF v_has_bank_submission_evidence THEN
    v_blocker := jsonb_build_object(
      'code', 'BANK_SUBMISSION_EVIDENCE_PRESENT',
      'message', 'Pre-bank cancellation cannot apply because bank/provider submission evidence exists.'
    );

    UPDATE public.pay_payment_correction_work_items AS submission_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(submission_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE submission_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;

  -- A scheduled no-bank/local-manual execution remains RUNNING only so its
  -- durable runner can wake at the scheduled time. Once this work item has
  -- re-proved that no provider or execution-commit evidence exists, retire
  -- that exact wait before changing any frozen payment scope. Provider-bound
  -- phases and every ambiguous execution state remain untouched.
  UPDATE public.banking_pay_operations AS scheduled_local_operation
  SET status = 'CANCELLED',
      phase = 'COMPLETE',
      runner_state = 'CANCELLED',
      requires_user_action = false,
      result_json = COALESCE(scheduled_local_operation.result_json, '{}'::jsonb)
        || jsonb_build_object(
          'code', 'SCHEDULED_LOCAL_EXECUTION_CANCELLED_BEFORE_APPLY',
          'correction_request_id', v_work_item.correction_request_id,
          'work_item_id', p_work_item_id,
          'provider_submission_attempted', false,
          'submitted_to_bank', false
        ),
      completed_at_utc = COALESCE(scheduled_local_operation.completed_at_utc, v_now),
      lease_owner = NULL,
      lease_expires_at_utc = NULL,
      locked_by = NULL,
      lock_expires_at_utc = NULL,
      run_after_utc = NULL,
      updated_at_utc = v_now,
      resume_reason = 'SCHEDULED_LOCAL_EXECUTION_CANCELLED_BEFORE_APPLY'
  WHERE scheduled_local_operation.pay_batch_id = v_work_item.pay_batch_id
    AND scheduled_local_operation.operation_type = 'PAYMENT_EXECUTE'
    AND scheduled_local_operation.status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS')
    AND scheduled_local_operation.phase = 'SCHEDULE_PAYMENT'
    AND scheduled_local_operation.resume_reason IN (
      'WAIT_FOR_SCHEDULED_NO_BANK_PAYMENT',
      'WAIT_FOR_SCHEDULED_LOCAL_MANUAL_SETTLEMENT'
    );

  v_is_authorised_or_scheduled_batch := upper(btrim(COALESCE(v_batch.status, ''))) IN (
    'AWAITING_AUTHORISATION',
    'AUTHORISED_FOR_PAYMENT',
    'SCHEDULED',
    'EXECUTING',
    'WAITING_BANK_CONFIRM'
  );

  SELECT EXISTS (
    WITH affected_transfers AS (
      SELECT DISTINCT partial_selected.pay_bank_transfer_id
      FROM pg_temp._tmp_pre_bank_cancel_selected AS partial_selected
      WHERE partial_selected.pay_bank_transfer_id IS NOT NULL
    ),
    selected_transfer_items AS (
      SELECT
        affected_transfers.pay_bank_transfer_id,
        count(public.pay_batch_items.id)::integer AS selected_count
      FROM affected_transfers
      JOIN public.pay_batch_items
        ON public.pay_batch_items.pay_bank_transfer_id = affected_transfers.pay_bank_transfer_id
      JOIN pg_temp._tmp_pre_bank_cancel_selected AS partial_selected_items
        ON partial_selected_items.pay_batch_item_id = public.pay_batch_items.id
      GROUP BY affected_transfers.pay_bank_transfer_id
    ),
    all_transfer_items AS (
      SELECT
        affected_transfers.pay_bank_transfer_id,
        count(public.pay_batch_items.id)::integer AS total_count
      FROM affected_transfers
      JOIN public.pay_batch_items
        ON public.pay_batch_items.pay_bank_transfer_id = affected_transfers.pay_bank_transfer_id
      JOIN public.pay_batch_candidates
        ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
      WHERE public.pay_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
        AND COALESCE(public.pay_batch_items.is_voided, false) = false
      GROUP BY affected_transfers.pay_bank_transfer_id
    )
    SELECT 1
    FROM selected_transfer_items
    JOIN all_transfer_items
      ON all_transfer_items.pay_bank_transfer_id = selected_transfer_items.pay_bank_transfer_id
    WHERE selected_transfer_items.selected_count < all_transfer_items.total_count
  )
  INTO v_has_authorised_partial_transfer_change;

  IF v_is_authorised_or_scheduled_batch AND v_has_authorised_partial_transfer_change THEN
    v_blocker := jsonb_build_object(
      'code', 'AUTHORISED_TRANSFER_PARTIAL_CANCEL_BLOCKED',
      'message', 'Selected items are part of an authorised/scheduled transfer that still has remaining items. Cancel the whole transfer/whole batch or recreate the batch.'
    );

    UPDATE public.pay_payment_correction_work_items AS partial_transfer_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(partial_transfer_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'processed_at_utc', v_now
      )
    WHERE partial_transfer_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker);
  END IF;


IF v_is_whole_batch_work_item THEN
  PERFORM public._imp_debug_audit(
    v_effective_actor_user_id,
    'PAYMENT_CORRECTION_PRE_BANK_CANCEL_WHOLE_BATCH_SCOPE_APPLY_IN_PLACE',
    jsonb_build_object(
      'work_item_id', p_work_item_id,
      'correction_request_id', v_work_item.correction_request_id,
      'pay_batch_id', v_work_item.pay_batch_id,
      'selected_item_count', v_selected_item_count,
      'message', 'Whole-batch cancellation work item is applied in-place against its resolved payment scope; it must not delegate back to pay_batch_cancel.'
    ),
    'pay_payment_correction',
    p_work_item_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );
END IF;

  v_manual_adjustment_result := public._pay_detect_manual_adjustments_for_carry_forward(
    v_work_item.pay_batch_id,
    v_resolved_scope_json,
    v_effective_actor_user_id
  );

  IF jsonb_array_length(COALESCE(v_manual_adjustment_result->'carry_forward_blockers', '[]'::jsonb)) > 0
     OR COALESCE((v_manual_adjustment_result->>'can_carry_forward_automatically')::boolean, true) IS NOT TRUE THEN
    v_blocker := jsonb_build_object(
      'code', 'SOURCE_LESS_MANUAL_ADJUSTMENT_AMBIGUOUS',
      'message', 'Pre-bank cancellation is blocked because one or more source-less manual adjustments cannot be safely carried forward.',
      'manual_adjustment_support_details_json', v_manual_adjustment_result
    );

    UPDATE public.pay_payment_correction_work_items AS manual_adjustment_blocked_work
    SET
      status = 'BLOCKED',
      locked_at_utc = NULL,
      locked_by = NULL,
      processed_at_utc = v_now,
      last_error = v_blocker->>'message',
      result_json = COALESCE(manual_adjustment_blocked_work.result_json, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'status', 'BLOCKED',
        'blocker', v_blocker,
        'manual_adjustment_support_details_json', v_manual_adjustment_result,
        'processed_at_utc', v_now
      )
    WHERE manual_adjustment_blocked_work.id = p_work_item_id;

    RETURN jsonb_build_object('ok', false, 'status', 'BLOCKED', 'blocker', v_blocker, 'manual_adjustment_support_details_json', v_manual_adjustment_result);
  END IF;

  v_carry_forward_create_result := public._pay_manual_adjustment_carry_forward_create(
    NULL::uuid[],
    v_resolved_scope_json,
    v_work_item.correction_request_id,
    p_work_item_id,
    v_effective_actor_user_id
  );

  v_carry_forward_release_result := public._pay_manual_adjustment_carry_forward_release_for_scope(
    v_work_item.pay_batch_id,
    v_resolved_scope_json,
    NULL::uuid[],
    v_effective_actor_user_id,
    'PRE_BANK_CANCEL'
  );

  v_carry_forward_created_count := COALESCE(NULLIF(v_carry_forward_create_result->>'created_count', '')::integer, 0);
  v_carry_forward_existing_count := COALESCE(NULLIF(v_carry_forward_create_result->>'existing_count', '')::integer, 0);
  v_carry_forward_released_count := COALESCE(NULLIF(v_carry_forward_release_result->>'released_count', '')::integer, 0);

  INSERT INTO public.pay_payment_correction_items(
    correction_request_id,
    pay_batch_id,
    pay_batch_candidate_id,
    candidate_id,
    pay_batch_item_id,
    pay_bank_transfer_id,
    timesheet_id,
    finance_case_id,
    finance_component_id,
    reservation_id,
    item_type,
    correction_item_kind,
    source_amount,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    economic_key_type,
    economic_key_value,
    before_snapshot_json,
    after_snapshot_json,
    status,
    created_at_utc,
    applied_at_utc
  )
  SELECT
    v_work_item.correction_request_id,
    selected_for_ledger.pay_batch_id,
    selected_for_ledger.pay_batch_candidate_id,
    selected_for_ledger.candidate_id,
    selected_for_ledger.pay_batch_item_id,
    selected_for_ledger.pay_bank_transfer_id,
    selected_for_ledger.timesheet_id,
    selected_for_ledger.finance_case_id,
    selected_for_ledger.finance_component_id,
    selected_for_ledger.reservation_id,
    selected_for_ledger.item_type,
    'PRE_BANK_CANCEL',
    selected_for_ledger.source_amount_ex_vat,
    selected_for_ledger.amount_ex_vat,
    selected_for_ledger.amount_vat,
    selected_for_ledger.amount_inc_vat,
    selected_for_ledger.economic_key_type,
    selected_for_ledger.economic_key_value,
    to_jsonb(ledger_items),
    to_jsonb(ledger_items) || jsonb_build_object('is_voided', true, 'updated_at', v_now),
    'APPLIED',
    v_now,
    v_now
  FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_for_ledger
  JOIN public.pay_batch_items AS ledger_items
    ON ledger_items.id = selected_for_ledger.pay_batch_item_id
  ON CONFLICT (pay_batch_item_id, correction_item_kind) WHERE status = 'APPLIED' AND pay_batch_item_id IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS v_inserted_correction_item_count = ROW_COUNT;

  UPDATE public.pay_batch_items AS items_to_void
  SET
    is_voided = true,
    updated_at = v_now
  WHERE items_to_void.id IN (
    SELECT selected_to_void.pay_batch_item_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_to_void
  )
    AND COALESCE(items_to_void.is_voided, false) = false;

  GET DIAGNOSTICS v_voided_item_count = ROW_COUNT;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_released_reservations;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_released_reservations ON COMMIT DROP AS
  WITH release_candidates AS (
    SELECT DISTINCT
      public.pay_advance_reservations.id,
      public.pay_advance_reservations.finance_case_id,
      public.pay_advance_reservations.finance_component_id,
      public.pay_advance_reservations.pay_batch_item_id,
      public.pay_advance_reservations.reserved_amount,
      public.pay_advance_reservations.reserved_source_amount
    FROM public.pay_advance_reservations
    JOIN pg_temp._tmp_pre_bank_cancel_selected AS selected_reservation_items
      ON selected_reservation_items.reservation_id = public.pay_advance_reservations.id
      OR selected_reservation_items.pay_batch_item_id = public.pay_advance_reservations.pay_batch_item_id
    WHERE public.pay_advance_reservations.pay_batch_id = v_work_item.pay_batch_id
      AND (
        upper(btrim(COALESCE(public.pay_advance_reservations.status, ''))) = 'RESERVED'
        OR (
          upper(btrim(COALESCE(public.pay_advance_reservations.status, ''))) = 'COMMITTED'
          AND public.pay_advance_reservations.settled_at_utc IS NULL
        )
      )
  ),
  released_rows AS (
    UPDATE public.pay_advance_reservations AS reservations_to_release
    SET
      status = 'RELEASED',
      released_at_utc = COALESCE(reservations_to_release.released_at_utc, v_now),
      released_reason = 'PRE_BANK_CANCEL',
      updated_by_user_id = p_actor_user_id
    FROM release_candidates
    WHERE reservations_to_release.id = release_candidates.id
    RETURNING
      reservations_to_release.id,
      reservations_to_release.finance_case_id,
      reservations_to_release.finance_component_id,
      reservations_to_release.pay_batch_item_id,
      reservations_to_release.reserved_amount,
      reservations_to_release.reserved_source_amount
  )
  SELECT
    released_rows.id AS reservation_id,
    released_rows.finance_case_id,
    released_rows.finance_component_id,
    released_rows.pay_batch_item_id,
    released_rows.reserved_amount,
    released_rows.reserved_source_amount
  FROM released_rows;

  SELECT count(*)::integer
  INTO v_released_reservation_count
  FROM pg_temp._tmp_pre_bank_cancel_released_reservations AS released_reservation_count;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_component_restore;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_component_restore ON COMMIT DROP AS
  SELECT
    restore_source.finance_component_id,
    restore_source.finance_case_id,
    round(sum(restore_source.restore_source_amount), 2)::numeric AS restore_source_amount
  FROM (
    SELECT
      COALESCE(released_reservations.finance_component_id, public.pay_batch_items.finance_component_id) AS finance_component_id,
      COALESCE(released_reservations.finance_case_id, public.pay_batch_items.finance_case_id) AS finance_case_id,
      round(abs(COALESCE(
        released_reservations.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id),
        public.pay_batch_items.frozen_source_amount,
        released_reservations.reserved_amount,
        public.pay_batch_items.amount_ex_vat,
        public.pay_batch_items.amount_inc_vat,
        0
      )), 2)::numeric AS restore_source_amount
    FROM pg_temp._tmp_pre_bank_cancel_released_reservations AS released_reservations
    LEFT JOIN public.pay_batch_items
      ON public.pay_batch_items.id = released_reservations.pay_batch_item_id
  ) AS restore_source
  WHERE restore_source.finance_component_id IS NOT NULL
    AND restore_source.restore_source_amount > 0
  GROUP BY restore_source.finance_component_id, restore_source.finance_case_id;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_component_restore_apply;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_component_restore_apply ON COMMIT DROP AS
  SELECT
    public.pay_finance_case_components.id AS finance_component_id,
    public.pay_finance_case_components.finance_case_id,
    public.pay_finance_case_components.remaining_source_amount AS remaining_before,
    /* Draft reservations are tracked separately and do not decrement the
       component's live outstanding balance.  Releasing a pre-bank reservation
       must therefore leave remaining_source_amount unchanged; adding the
       reservation here would resurrect already-settled recovery value. */
    COALESCE(public.pay_finance_case_components.remaining_source_amount, 0) AS remaining_after,
    component_restore.restore_source_amount
  FROM pg_temp._tmp_pre_bank_cancel_component_restore AS component_restore
  JOIN public.pay_finance_case_components
    ON public.pay_finance_case_components.id = component_restore.finance_component_id;

  UPDATE public.pay_finance_case_components AS components_to_restore
  SET
    remaining_source_amount = component_restore_apply.remaining_after,
    resolved_at_utc = CASE WHEN component_restore_apply.remaining_after > 0 THEN NULL ELSE components_to_restore.resolved_at_utc END,
    closed_at_utc = NULL,
    updated_at_utc = v_now
  FROM pg_temp._tmp_pre_bank_cancel_component_restore_apply AS component_restore_apply
  WHERE components_to_restore.id = component_restore_apply.finance_component_id;

  GET DIAGNOSTICS v_restored_component_count = ROW_COUNT;

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    component_restore_apply.finance_case_id,
    component_restore_apply.finance_component_id,
    'COMPONENT_RESTORED',
    v_now,
    p_actor_user_id,
    v_work_item.pay_batch_id,
    NULL::uuid,
    jsonb_build_object('remaining_source_amount', component_restore_apply.remaining_before),
    jsonb_build_object(
      'remaining_source_amount', component_restore_apply.remaining_after,
      'restored_source_amount', component_restore_apply.restore_source_amount,
      'correction_kind', 'PRE_BANK_CANCEL',
      'work_item_id', p_work_item_id
    ),
    'PRE_BANK_CANCEL',
    'Payment correction pre-bank cancellation released the reservation without changing the live component outstanding balance.'
  FROM pg_temp._tmp_pre_bank_cancel_component_restore_apply AS component_restore_apply;

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    released_reservations.finance_case_id,
    released_reservations.finance_component_id,
    'RESERVATION_RELEASED',
    v_now,
    p_actor_user_id,
    v_work_item.pay_batch_id,
    released_reservations.reservation_id,
    jsonb_build_object('reservation_status', 'RESERVED_OR_COMMITTED'),
    jsonb_build_object(
      'reservation_status', 'RELEASED',
      'released_reason', 'PRE_BANK_CANCEL',
      'work_item_id', p_work_item_id
    ),
    'PRE_BANK_CANCEL',
    'Payment correction pre-bank cancellation released reservation.'
  FROM pg_temp._tmp_pre_bank_cancel_released_reservations AS released_reservations
  WHERE released_reservations.finance_case_id IS NOT NULL;

  UPDATE public.pay_advances AS payout_cases_to_reset
  SET
    payout_status = 'PENDING',
    payout_pay_batch_id = NULL,
    payout_transfer_id = NULL,
    updated_at = v_now
  WHERE payout_cases_to_reset.id IN (
    SELECT DISTINCT selected_payout_cases.finance_case_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_payout_cases
    WHERE selected_payout_cases.finance_case_id IS NOT NULL
  )
    AND COALESCE(payout_cases_to_reset.payout_status::text, '') <> 'PAID'
    AND (
      payout_cases_to_reset.payout_pay_batch_id = v_work_item.pay_batch_id
      OR payout_cases_to_reset.payout_transfer_id IN (
        SELECT DISTINCT selected_payout_transfers.pay_bank_transfer_id
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_payout_transfers
        WHERE selected_payout_transfers.pay_bank_transfer_id IS NOT NULL
      )
    );

  GET DIAGNOSTICS v_reset_payout_count = ROW_COUNT;

  SELECT jsonb_build_object(
    'scope_type', v_scope_type,
    'work_unit', COALESCE(NULLIF(v_work_unit, ''), v_scope_type, 'UNKNOWN'),
    'pay_batch_id', v_work_item.pay_batch_id::text,
    'pay_batch_ids', jsonb_build_array(v_work_item.pay_batch_id::text),
    'is_whole_batch', v_is_whole_batch_work_item,
    'selected_candidate_scope_complete', (
      v_scope_type = 'CANDIDATES'
      AND NOT (COALESCE(v_work_item.selection_json, '{}'::jsonb) ?| ARRAY[
        'pay_batch_item_id',
        'pay_batch_item_ids',
        'selected_pay_batch_item_ids',
        'expected_pay_batch_item_ids',
        'pay_bank_transfer_id',
        'pay_bank_transfer_ids',
        'selected_pay_bank_transfer_ids',
        'finance_case_id',
        'finance_case_ids',
        'selected_finance_case_ids',
        'finance_component_id',
        'finance_component_ids',
        'selected_finance_component_ids',
        'reservation_id',
        'reservation_ids',
        'selected_reservation_ids',
        'payout_transfer_id',
        'payout_transfer_ids',
        'selected_payout_transfer_ids',
        'transfer_group_key',
        'transfer_group_keys',
        'selected_transfer_group_keys'
      ]::text[])
    ),
    'pay_batch_item_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.pay_batch_item_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.pay_batch_item_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_batch_candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.pay_batch_candidate_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.pay_batch_candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.candidate_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'umbrella_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.umbrella_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.umbrella_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_case_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.finance_case_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.finance_case_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_component_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.finance_component_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.finance_component_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'reservation_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.reservation_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.reservation_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'payout_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.payout_transfer_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.payout_transfer_id IS NOT NULL
        UNION
        SELECT DISTINCT pre_bank_selected.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE pre_bank_selected.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'transfer_group_keys', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT pre_bank_selected.transfer_group_key AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS pre_bank_selected
        WHERE NULLIF(btrim(COALESCE(pre_bank_selected.transfer_group_key, '')), '') IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb)
  )
  INTO v_mail_selected_scope_json;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_mail_scope_matches;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_mail_scope_matches ON COMMIT DROP AS
  WITH candidate_mail AS (
    SELECT
      public.mail_outbox.id,
      public.mail_outbox.status::text AS status,
      public.mail_outbox.type,
      public.mail_outbox.email_type,
      public.mail_outbox.context_kind,
      public.mail_outbox.context_id,
      public.mail_outbox.recipient_kind,
      public.mail_outbox.recipient_id,
      public.mail_outbox.reference,
      COALESCE(public.mail_outbox.payment_scope_json, '{}'::jsonb) AS payment_scope_json
    FROM public.mail_outbox
    WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'QUEUED'
      AND lower(concat_ws('|', public.mail_outbox.type, public.mail_outbox.email_type, public.mail_outbox.context_kind, public.mail_outbox.reference, COALESCE(public.mail_outbox.payment_scope_json::text, '{}'))) LIKE ANY (
        ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%']
      )
  ), matched_mail AS (
    SELECT
      candidate_mail.id AS mail_outbox_id,
      candidate_mail.status,
      candidate_mail.type,
      candidate_mail.email_type,
      candidate_mail.context_kind,
      candidate_mail.context_id,
      candidate_mail.recipient_kind,
      candidate_mail.recipient_id,
      candidate_mail.reference,
      candidate_mail.payment_scope_json,
      mail_match.match_result
    FROM candidate_mail
    CROSS JOIN LATERAL (
      SELECT public._pay_payment_correction_mail_scope_match(
        candidate_mail.id,
        v_work_item.pay_batch_id,
        v_work_item.selection_json,
        v_mail_selected_scope_json,
        false
      ) AS match_result
    ) AS mail_match
  )
  SELECT
    matched_mail.mail_outbox_id,
    matched_mail.status,
    matched_mail.type,
    matched_mail.email_type,
    matched_mail.context_kind,
    matched_mail.context_id,
    matched_mail.recipient_kind,
    matched_mail.recipient_id,
    matched_mail.reference,
    matched_mail.payment_scope_json,
    COALESCE(matched_mail.match_result->>'match_kind', 'NONE') AS match_kind,
    COALESCE(matched_mail.match_result->>'match_confidence', 'NONE') AS match_confidence,
    COALESCE(NULLIF(matched_mail.match_result->>'safe_to_cancel', '')::boolean, false) AS safe_to_cancel,
    COALESCE(NULLIF(matched_mail.match_result->>'requires_review', '')::boolean, false) AS requires_review,
    COALESCE(matched_mail.match_result->>'reason', 'NO_SCOPE_MATCH') AS match_reason,
    matched_mail.match_result
  FROM matched_mail
  WHERE COALESCE(NULLIF(matched_mail.match_result->>'matched', '')::boolean, false);

  UPDATE public.mail_outbox AS queued_mail_to_cancel
  SET
    status = 'FAILED',
    failed_at = COALESCE(queued_mail_to_cancel.failed_at, v_now),
    last_error = 'CANCELLED_INTERNAL_PAYMENT_CORRECTION'
  FROM pg_temp._tmp_pre_bank_cancel_mail_scope_matches AS mail_scope_match
  WHERE queued_mail_to_cancel.id = mail_scope_match.mail_outbox_id
    AND upper(btrim(COALESCE(queued_mail_to_cancel.status::text, ''))) = 'QUEUED'
    AND COALESCE(mail_scope_match.safe_to_cancel, false)
    AND (
      mail_scope_match.match_confidence = 'EXACT'
      OR (
        v_is_whole_batch_work_item
        AND mail_scope_match.match_kind = 'WHOLE_BATCH'
      )
    );

  GET DIAGNOSTICS v_cancelled_mail_count = ROW_COUNT;

  SELECT count(*)::integer
  INTO v_communications_review_required_count
  FROM pg_temp._tmp_pre_bank_cancel_mail_scope_matches AS mail_scope_match
  WHERE upper(btrim(COALESCE(mail_scope_match.status, ''))) = 'QUEUED'
    AND COALESCE(mail_scope_match.requires_review, false);

  v_mail_scope_matching := jsonb_build_object(
    'exact_cancelled', v_cancelled_mail_count,
    'legacy_review', v_communications_review_required_count,
    'selected_scope_json', v_mail_selected_scope_json,
    'matches', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', mail_scope_match.mail_outbox_id,
        'match_kind', mail_scope_match.match_kind,
        'match_confidence', mail_scope_match.match_confidence,
        'safe_to_cancel', mail_scope_match.safe_to_cancel,
        'requires_review', mail_scope_match.requires_review,
        'reason', mail_scope_match.match_reason,
        'status', mail_scope_match.status,
        'type', mail_scope_match.type,
        'email_type', mail_scope_match.email_type,
        'context_kind', mail_scope_match.context_kind,
        'context_id', mail_scope_match.context_id,
        'recipient_kind', mail_scope_match.recipient_kind,
        'recipient_id', mail_scope_match.recipient_id,
        'reference', mail_scope_match.reference,
        'payment_scope_json', mail_scope_match.payment_scope_json
      ) ORDER BY mail_scope_match.mail_outbox_id)
      FROM pg_temp._tmp_pre_bank_cancel_mail_scope_matches AS mail_scope_match
    ), '[]'::jsonb)
  );

  WITH affected_transfers AS (
    SELECT DISTINCT selected_transfer_amounts.pay_bank_transfer_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_transfer_amounts
    WHERE selected_transfer_amounts.pay_bank_transfer_id IS NOT NULL
  ),
  recalculated_transfers AS (
    SELECT
      affected_transfers.pay_bank_transfer_id,
      round(COALESCE(sum(COALESCE(public.pay_batch_items.amount_inc_vat, 0)), 0), 2)::numeric AS remaining_amount
    FROM affected_transfers
    LEFT JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_bank_transfer_id = affected_transfers.pay_bank_transfer_id
     AND COALESCE(public.pay_batch_items.is_voided, false) = false
    GROUP BY affected_transfers.pay_bank_transfer_id
  )
  UPDATE public.pay_bank_transfers AS transfer_to_recalculate
  SET
    amount = recalculated_transfers.remaining_amount,
    status = CASE
      WHEN recalculated_transfers.remaining_amount = 0
           AND upper(btrim(COALESCE(transfer_to_recalculate.status, ''))) NOT IN ('COMPLETED')
        THEN 'VOIDED'
      ELSE transfer_to_recalculate.status
    END,
    failed_reason = CASE
      WHEN recalculated_transfers.remaining_amount = 0
           AND upper(btrim(COALESCE(transfer_to_recalculate.status, ''))) NOT IN ('COMPLETED')
        THEN COALESCE(transfer_to_recalculate.failed_reason, 'PRE_BANK_CANCEL_VOIDED')
      ELSE transfer_to_recalculate.failed_reason
    END,
    rail_meta_json = CASE
      WHEN recalculated_transfers.remaining_amount = 0
           AND upper(btrim(COALESCE(transfer_to_recalculate.status, ''))) NOT IN ('COMPLETED')
        THEN COALESCE(transfer_to_recalculate.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'pre_bank_cancel_applied', true,
          'pre_bank_cancel_work_item_id', p_work_item_id::text,
          'pre_bank_cancel_at_utc', v_now,
          'pre_bank_cancel_status_note', 'Transfer amount became zero after selected pre-bank cancellation; status set to VOIDED.'
        )
      ELSE transfer_to_recalculate.rail_meta_json
    END
  FROM recalculated_transfers
  WHERE transfer_to_recalculate.id = recalculated_transfers.pay_bank_transfer_id;

  GET DIAGNOSTICS v_recalculated_transfer_count = ROW_COUNT;

  DROP TABLE IF EXISTS pg_temp._tmp_pre_bank_cancel_affected_candidates;
  CREATE TEMP TABLE _tmp_pre_bank_cancel_affected_candidates ON COMMIT DROP AS
  SELECT DISTINCT
    selected_affected_candidates.pay_batch_candidate_id,
    selected_affected_candidates.candidate_id
  FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_affected_candidates
  WHERE selected_affected_candidates.pay_batch_candidate_id IS NOT NULL;

  WITH affected_candidate_sums AS (
    SELECT
      public.pay_batch_candidates.id AS pay_batch_candidate_id,
      count(public.pay_batch_items.id) FILTER (
        WHERE COALESCE(public.pay_batch_items.is_voided, false) = false
      )::integer AS active_item_count,
      bool_or(
        COALESCE(public.pay_batch_items.is_voided, false) = false
        AND upper(btrim(COALESCE(public.pay_batch_items.pay_channel, ''))) = 'PAYE'
      ) AS has_active_paye_item,
      bool_or(
        COALESCE(public.pay_batch_items.is_voided, false) = false
        AND upper(btrim(COALESCE(public.pay_batch_items.pay_channel, ''))) = 'UMBRELLA'
      ) AS has_active_umbrella_item,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND public.pay_batch_items.item_type NOT IN ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT', 'LOAN_REPAYMENT', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_PAYOUT', 'LOAN_PAYOUT', 'DEBT_CREATED')
          THEN COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS earnings_ex,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND public.pay_batch_items.item_type <> 'DEBT_CREATED'
          THEN COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS earnings_inc,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND COALESCE(public.pay_batch_items.paye_treatment, 'NONE') IN ('GROSS_ADD', 'GROSS_DEDUCT')
          THEN COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS gross_adjustments_ex_sum,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND COALESCE(public.pay_batch_items.paye_treatment, 'NONE') IN ('NET_ADD', 'NET_DEDUCT')
          THEN COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS net_adjustments_ex_sum,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND public.pay_batch_items.item_type = 'OVERPAYMENT_RECOVERY'
          THEN -COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS overpayment_recovery_taken_ex,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND public.pay_batch_items.item_type = 'LOAN_REPAYMENT'
          THEN -COALESCE(public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS loan_repayment_taken_ex,
      round(COALESCE(sum(
        CASE
          WHEN COALESCE(public.pay_batch_items.is_voided, false) = false
           AND public.pay_batch_items.item_type = 'DEBT_CREATED'
          THEN COALESCE(public.pay_batch_items.amount_inc_vat, public.pay_batch_items.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(12,2) AS debt_created_sum
    FROM pg_temp._tmp_pre_bank_cancel_affected_candidates AS affected_candidates
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = affected_candidates.pay_batch_candidate_id
     AND public.pay_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
    LEFT JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = public.pay_batch_candidates.id
    GROUP BY public.pay_batch_candidates.id
  ),
  paye_net AS (
    SELECT
      public.pay_batch_paye_net_inputs.pay_batch_candidate_id,
      public.pay_batch_paye_net_inputs.net_amount::numeric(12,2) AS net_amount
    FROM public.pay_batch_paye_net_inputs
    WHERE public.pay_batch_paye_net_inputs.pay_batch_candidate_id IN (
      SELECT affected_candidates.pay_batch_candidate_id
      FROM pg_temp._tmp_pre_bank_cancel_affected_candidates AS affected_candidates
    )
  ),
  candidate_summary_update AS (
    UPDATE public.pay_batch_candidates AS candidates_to_refresh
    SET
      awaiting_net_amount = CASE
        WHEN COALESCE(affected_candidate_sums.active_item_count, 0) = 0 THEN false
        WHEN COALESCE(affected_candidate_sums.has_active_paye_item, false) = true
          THEN NOT EXISTS (
            SELECT 1
            FROM public.pay_batch_paye_net_inputs AS paye_net_input_check
            WHERE paye_net_input_check.pay_batch_candidate_id = candidates_to_refresh.id
          )
        ELSE false
      END,
      gross_preview = CASE
        WHEN COALESCE(affected_candidate_sums.active_item_count, 0) = 0 THEN 0::numeric(12,2)
        WHEN COALESCE(affected_candidate_sums.has_active_paye_item, false) = true
          THEN round(COALESCE(affected_candidate_sums.earnings_ex, 0) + COALESCE(affected_candidate_sums.gross_adjustments_ex_sum, 0), 2)::numeric(12,2)
        ELSE greatest(COALESCE(affected_candidate_sums.earnings_inc, 0), 0)::numeric(12,2)
      END,
      net_bank_amount = CASE
        WHEN COALESCE(affected_candidate_sums.active_item_count, 0) = 0 THEN 0::numeric(12,2)
        WHEN COALESCE(affected_candidate_sums.has_active_paye_item, false) = true THEN
          CASE
            WHEN NOT EXISTS (
              SELECT 1
              FROM public.pay_batch_paye_net_inputs AS paye_net_input_check
              WHERE paye_net_input_check.pay_batch_candidate_id = candidates_to_refresh.id
            ) THEN NULL::numeric
            ELSE greatest(round(COALESCE(paye_net.net_amount, 0) + COALESCE(affected_candidate_sums.net_adjustments_ex_sum, 0), 2), 0)::numeric(12,2)
          END
        ELSE greatest(COALESCE(affected_candidate_sums.earnings_inc, 0), 0)::numeric(12,2)
      END,
      debt_created = COALESCE(affected_candidate_sums.debt_created_sum, 0)::numeric(12,2),
      overpayment_recovery_taken = COALESCE(affected_candidate_sums.overpayment_recovery_taken_ex, 0)::numeric(12,2),
      loan_repayment_taken = COALESCE(affected_candidate_sums.loan_repayment_taken_ex, 0)::numeric(12,2),
      mismatch_settlement_choice = NULL,
      updated_at = v_now
    FROM affected_candidate_sums
    LEFT JOIN paye_net
      ON paye_net.pay_batch_candidate_id = affected_candidate_sums.pay_batch_candidate_id
    WHERE candidates_to_refresh.id = affected_candidate_sums.pay_batch_candidate_id
      AND candidates_to_refresh.pay_batch_id = v_work_item.pay_batch_id
    RETURNING candidates_to_refresh.id
  )
  SELECT count(*)::integer
  INTO v_summary_refresh_candidate_count
  FROM candidate_summary_update;

  SELECT
    count(public.pay_batch_items.id)::integer,
    round(COALESCE(sum(COALESCE(public.pay_batch_items.amount_inc_vat, 0)), 0), 2)::numeric
  INTO
    v_active_batch_item_count_after,
    v_active_batch_amount_inc_vat_after
  FROM public.pay_batch_items
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
  WHERE public.pay_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
    AND COALESCE(public.pay_batch_items.is_voided, false) = false;

  v_batch_empty_after := COALESCE(v_active_batch_item_count_after, 0) = 0;

  UPDATE public.pay_batches AS batch_to_refresh
  SET
    total_bank_out = COALESCE((
      SELECT round(COALESCE(sum(COALESCE(public.pay_batch_candidates.net_bank_amount, 0)), 0), 2)::numeric
      FROM public.pay_batch_candidates
      WHERE public.pay_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
    ), 0)::numeric,
    total_debt_created = COALESCE((
      SELECT round(COALESCE(sum(COALESCE(public.pay_batch_candidates.debt_created, 0)), 0), 2)::numeric
      FROM public.pay_batch_candidates
      WHERE public.pay_batch_candidates.pay_batch_id = v_work_item.pay_batch_id
    ), 0)::numeric
  WHERE batch_to_refresh.id = v_work_item.pay_batch_id;

  INSERT INTO public.app_change_counters(entity_key, seq, updated_at)
  SELECT
    'pay_candidate:' || dirty_candidates.candidate_id::text,
    1,
    v_now
  FROM (
    SELECT DISTINCT selected_dirty_candidates.candidate_id
    FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_dirty_candidates
    WHERE selected_dirty_candidates.candidate_id IS NOT NULL
  ) AS dirty_candidates
  ON CONFLICT (entity_key)
  DO UPDATE
  SET
    seq = public.app_change_counters.seq + 1,
    updated_at = v_now;

  GET DIAGNOSTICS v_dirty_candidate_count = ROW_COUNT;
  -- Workbench refresh is staged once by PROCESS_CHUNK/REFRESH_WORKBENCH.
  v_refresh_result := jsonb_build_object(
    'status', 'PENDING_OPERATION_REFRESH',
    'owner', 'pay_payment_correction_process_chunk'
  );

  v_changed_scope_json := jsonb_build_object(
    'pay_batch_id', v_work_item.pay_batch_id::text,
    'correction_request_id', v_work_item.correction_request_id::text,
    'work_item_id', p_work_item_id::text,
    'change_kind', 'PRE_BANK_CANCEL',
    'changed_pay_batch_item_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.pay_batch_item_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.pay_batch_item_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_pay_batch_candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.pay_batch_candidate_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.pay_batch_candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.candidate_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_finance_case_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.finance_case_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.finance_case_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_finance_component_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.finance_component_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.finance_component_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'changed_reservation_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT selected_scope.reservation_id::text AS value_text
        FROM pg_temp._tmp_pre_bank_cancel_selected AS selected_scope
        WHERE selected_scope.reservation_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'voided_item_count', COALESCE(v_voided_item_count, 0),
    'released_reservation_count', COALESCE(v_released_reservation_count, 0),
    'restored_component_count', COALESCE(v_restored_component_count, 0),
    'carry_forward_created_count', COALESCE(v_carry_forward_created_count, 0),
    'carry_forward_existing_count', COALESCE(v_carry_forward_existing_count, 0),
    'carry_forward_released_count', COALESCE(v_carry_forward_released_count, 0)
  );


  v_result := jsonb_build_object(
    'ok', true,
    'status', 'APPLIED',
    'result_code', 'APPLIED',
    'work_item_id', p_work_item_id,
    'candidate_id', v_work_item.candidate_id,
    'expected_item_count', v_selected_item_count,
    'applied_item_count', v_inserted_correction_item_count,
    'released_reservations', v_released_reservation_count,
    'restored_finance_components', v_restored_component_count,
    'carry_forward_created', COALESCE(v_carry_forward_created_count, 0),
    'carry_forward_existing', COALESCE(v_carry_forward_existing_count, 0),
    'carry_forward_released', COALESCE(v_carry_forward_released_count, 0),
    'blocker', NULL,
    'correction_request_id', v_work_item.correction_request_id,
    'pay_batch_id', v_work_item.pay_batch_id,
    'correction_item_kind', 'PRE_BANK_CANCEL',
    'selected_item_count', v_selected_item_count,
    'selected_candidate_count', v_selected_candidate_count,
    'selected_transfer_count', v_selected_transfer_count,
    'voided_item_count', v_voided_item_count,
    'inserted_correction_item_count', v_inserted_correction_item_count,
    'released_reservation_count', v_released_reservation_count,
    'restored_component_count', v_restored_component_count,
    'reset_payout_count', v_reset_payout_count,
    'cancelled_mail_count', v_cancelled_mail_count,
    'communications_cancelled', v_cancelled_mail_count,
    'communications_review_required', v_communications_review_required_count
  )
  || jsonb_build_object(
    'candidate_scope_contract_version', v_candidate_scope_contract_version,
    'candidate_scope_hash_version', v_candidate_scope_hash_version,
    'source_row_count_semantics', v_source_row_count_semantics,
    'communication_cleanup_contract_version', CASE
      WHEN v_candidate_scope_contract_version = 2 THEN 1 ELSE NULL::integer END,
    'matching_queued_count', v_matching_queued_count,
    'cancelled_queued_count', v_cancelled_mail_count,
    'already_sent_untouched_count', v_already_sent_untouched_count,
    'other_terminal_untouched_count', v_other_terminal_untouched_count,
    'unsafe_queued_count', v_unsafe_queued_count,
    'communication_review_required', v_unsafe_queued_count > 0,
    'mail_scope_matching', v_mail_scope_matching,
    'recalculated_transfer_count', v_recalculated_transfer_count,
    'summary_refresh_candidate_count', v_summary_refresh_candidate_count,
    'active_batch_item_count_after', COALESCE(v_active_batch_item_count_after, 0),
    'active_batch_amount_inc_vat_after', COALESCE(v_active_batch_amount_inc_vat_after, 0),
    'batch_empty_after', COALESCE(v_batch_empty_after, false),
    'dirty_candidate_count', v_dirty_candidate_count,
    'manual_adjustment_support_details_json', COALESCE(v_manual_adjustment_result, '{}'::jsonb),
    'carry_forward_created_count', COALESCE(v_carry_forward_created_count, 0),
    'carry_forward_existing_count', COALESCE(v_carry_forward_existing_count, 0),
    'carry_forward_released_count', COALESCE(v_carry_forward_released_count, 0),
    'carry_forward_create_result', COALESCE(v_carry_forward_create_result, '{}'::jsonb),
    'carry_forward_release_result', COALESCE(v_carry_forward_release_result, '{}'::jsonb),
    'changed_scope_json', COALESCE(v_changed_scope_json, '{}'::jsonb),
    'resolved_scope', COALESCE(v_resolved_scope_json, '{}'::jsonb),
    'classification_result', v_classification_result,
    'same_request_partial_continuation', v_same_request_partial_continuation,
    'same_request_continuation_proof', jsonb_build_object(
      'original_expected_json_count', v_original_expected_json_count,
      'original_expected_valid_count', v_original_expected_valid_count,
      'original_expected_belongs_count', v_original_expected_belongs_count,
      'original_expected_active_count', v_original_expected_active_count,
      'original_expected_same_request_voided_count', v_original_expected_same_request_voided_count,
      'original_expected_disallowed_state_count', v_original_expected_disallowed_state_count,
      'active_outside_original_count', v_active_outside_original_count,
      'current_expected_outside_original_count', v_current_expected_outside_original_count,
      'applied_sibling_count', v_applied_sibling_count
    ),
    'applied_at_utc', v_now
  );

  UPDATE public.pay_payment_correction_work_items AS applied_work_item
  SET
    status = 'APPLIED',
    locked_at_utc = NULL,
    locked_by = NULL,
    processed_at_utc = COALESCE(applied_work_item.processed_at_utc, v_now),
    last_error = NULL,
    result_json = COALESCE(applied_work_item.result_json, '{}'::jsonb) || v_result
  WHERE applied_work_item.id = p_work_item_id;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PRE_BANK_CANCEL_WORK_RESULT',
    v_result,
    'pay_payment_correction',
    p_work_item_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_result;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_PRE_BANK_CANCEL_WORK_ERROR',
      jsonb_build_object(
        'work_item_id', p_work_item_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_work_item_id::text, 'NO_WORK_ITEM_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_preview_apply_candidate_overlay(jsonb,jsonb,jsonb)
CREATE OR REPLACE FUNCTION public.pay_preview_apply_candidate_overlay(p_candidate_baseline_json jsonb, p_case_resolutions_json jsonb DEFAULT NULL::jsonb, p_overrides_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_candidate_baseline_root jsonb := coalesce(p_candidate_baseline_json, '{}'::jsonb);
  v_case_resolutions_input jsonb := coalesce(p_case_resolutions_json, '{}'::jsonb);
  v_overrides_input jsonb := coalesce(p_overrides_json, '{}'::jsonb);
  v_candidate_id text := '';
  v_candidate_row jsonb := '{}'::jsonb;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_case_states jsonb := '[]'::jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_do_not_pay_items jsonb := '[]'::jsonb;
  v_snoozed_items jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_timesheet_snapshots_json jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines_input jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_hidden_recovery_template_line_count integer := 0;
  v_case_resolutions jsonb := '{}'::jsonb;
  v_exclude_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_map jsonb := '{}'::jsonb;
  v_bucket_applied_component_rows jsonb := '[]'::jsonb;
  v_final_component_rows jsonb := '[]'::jsonb;
  v_updated_case_states jsonb := '[]'::jsonb;
  v_case_state_map jsonb := '{}'::jsonb;
  v_updated_lines jsonb := '[]'::jsonb;
  v_updated_itemisation jsonb := '[]'::jsonb;
  v_case_resolution_entry record;
  v_case_resolution_json jsonb := '{}'::jsonb;
  v_resolution_case_key text := '';
  v_resolution_family text := '';
  v_resolve_all_linked_timesheets boolean := false;
  v_component_row jsonb := '{}'::jsonb;
  v_updated_component_row jsonb := '{}'::jsonb;
  v_component_scope text := '';
  v_component_case_key text := '';
  v_component_timesheet_id text := '';
  v_component_source_family_key text := '';
  v_component_key_type text := '';
  v_component_key_value text := '';
  v_component_bucket_code text := '';
  v_component_source_basis_fingerprint text := '';
  v_component_fingerprint text := '';
  v_component_source_units numeric := null::numeric;
  v_component_source_rate numeric := null::numeric;
  v_component_source_charge_rate numeric := null::numeric;
  v_case_state jsonb := '{}'::jsonb;
  v_line jsonb := '{}'::jsonb;
  v_case_state_case_key text := '';
  v_case_state_case_scope text := '';
  v_case_state_timesheet_id text := '';
  v_case_state_components jsonb := '[]'::jsonb;
  v_case_state_updated_components jsonb := '[]'::jsonb;
  v_case_state_updated jsonb := '{}'::jsonb;
  v_case_state_updated_components_count integer := 0;
  v_case_state_open_taxable_count integer := 0;
  v_case_state_open_reimbursement_count integer := 0;
  v_case_state_unresolved_taxable_count integer := 0;
  v_case_state_needs_resolution boolean := false;
  v_case_state_satisfied_now boolean := true;
  v_case_state_existing_blocked_reasons_count integer := 0;
  v_case_state_total_preview_amount_ex_vat numeric := 0;
  v_case_state_safe_amount_ex_vat numeric := 0;
  v_case_state_blocked_amount_ex_vat numeric := 0;
  v_case_state_unresolved_taxable_amount_ex_vat numeric := 0;
  v_case_state_taxable_manual_debt_resolution jsonb := null::jsonb;
  v_case_state_summary jsonb := '{}'::jsonb;
  v_case_state_resolved_detail_rows jsonb := '[]'::jsonb;
  v_template_base_line jsonb := null::jsonb;
  v_template_ready_line jsonb := null::jsonb;
  v_template_blocked_line jsonb := null::jsonb;
  v_template_do_not_pay_line jsonb := null::jsonb;
  v_case_ready_amount_ex_vat numeric := 0;
  v_case_blocked_amount_ex_vat numeric := 0;
  v_case_total_amount_ex_vat numeric := 0;
  v_case_is_excluded boolean := false;
  v_new_line jsonb := '{}'::jsonb;
  v_line_id_base text := '';
  v_line_preview_row_id text := '';
  v_item jsonb := '{}'::jsonb;
  v_component_match_found boolean := false;
  v_component_case_applies boolean := false;
  v_component_direct_case_match boolean := false;
  v_component_linked_case_match boolean := false;
  v_component_linked_ids jsonb := '[]'::jsonb;
  v_bucket_resolution_json jsonb := '{}'::jsonb;
  v_bucket_source_family_key text := '';
  v_bucket_component_key_type text := '';
  v_bucket_component_key_value text := '';
  v_bucket_source_basis_fingerprint text := '';
  v_bucket_bucket_code text := '';
  v_bucket_resolution_mode text := '';
  v_bucket_target_rate numeric := null::numeric;
  v_bucket_source_units numeric := null::numeric;
  v_bucket_source_rate numeric := null::numeric;
  v_bucket_source_charge_rate numeric := null::numeric;
  v_bucket_target_pay_ex_vat numeric := null::numeric;
  v_bucket_target_charge_ex_vat numeric := null::numeric;
  v_bucket_target_margin_ex_vat numeric := null::numeric;
  v_bucket_margin_delta_ex_vat numeric := null::numeric;
  v_nonbucket_resolution_entry record;
  v_nonbucket_resolution_mode text := '';
  v_nonbucket_target_amount_ex_vat numeric := null::numeric;
  v_nonbucket_case_row_count integer := 0;
  v_nonbucket_case_total_basis numeric := 0;
  v_nonbucket_case_allocated_so_far numeric := 0;
  v_nonbucket_case_row_index integer := 0;
  v_nonbucket_case_row_basis numeric := 0;
  v_nonbucket_case_row_target_amount_ex_vat numeric := 0;
  v_nonbucket_case_row_key text := '';
  v_nonbucket_case_row_match_key text := '';
  v_nonbucket_allocations jsonb := '{}'::jsonb;
  v_nonbucket_case_payload jsonb := '{}'::jsonb;
  v_nonbucket_case_row_allocations jsonb := '{}'::jsonb;
  v_component_lookup_key text := '';
  v_component_source_charge_ex_vat numeric := null::numeric;
  v_component_source_pay_ex_vat numeric := null::numeric;
  v_component_target_pay_ex_vat numeric := null::numeric;
  v_component_target_charge_ex_vat numeric := null::numeric;
  v_component_target_margin_ex_vat numeric := null::numeric;
  v_component_margin_delta_ex_vat numeric := null::numeric;
  v_component_preview_amount_ex_vat numeric := null::numeric;
  v_component_ready_preview_amount_ex_vat numeric := null::numeric;
  v_component_blocked_preview_amount_ex_vat numeric := null::numeric;
  v_component_requires_resolution boolean := false;
  v_component_is_actionable_resolution_row boolean := false;
  v_line_case_key text := '';
  v_line_case_scope text := '';
  v_line_timesheet_id text := '';
  v_line_presentation_section text := '';
  v_line_existing_blocked_reason_codes jsonb := '[]'::jsonb;
  v_line_existing_preview_row_id text := '';
  v_line_existing_line_id text := '';
  v_line_existing_presentation_parent_line_id text := '';
  v_excluded_timesheet_entry jsonb;
  v_excluded_timesheet_id text := '';
  v_case_state_component jsonb := '{}'::jsonb;
  v_component_requires_resolution_text text := '';
  v_component_preview_amount_text text := '';
  v_component_ready_amount_text text := '';
  v_component_blocked_amount_text text := '';
  v_case_state_exists boolean := false;
  v_case_state_from_map jsonb := '{}'::jsonb;
  v_case_state_summary_source jsonb := '{}'::jsonb;
  v_case_state_existing_due_amount_ex_vat numeric := 0;
  v_line_amount_ex_vat numeric := 0;
  v_do_not_pay_reason_codes jsonb := '[]'::jsonb;
  v_case_line_count integer := 0;
  v_case_ready_line_present boolean := false;
  v_case_blocked_line_present boolean := false;
  v_case_first_line jsonb := null::jsonb;
  v_case_component_row jsonb := '{}'::jsonb;
  v_component_order integer := 0;
  v_case_component_order integer := 0;
  v_component_sort_key text := '';
  v_case_scope_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_is_component_match boolean := false;
  v_line_blocked_reason_codes jsonb := '[]'::jsonb;
  v_existing_case_state_summary jsonb := '{}'::jsonb;
  v_nonbucket_resolution_applied boolean := false;
  v_nonbucket_case_allowed boolean := false;
  v_bucket_resolution_applied boolean := false;
  v_case_state_is_timesheet_scope boolean := false;
  v_itemisation_match_found boolean := false;
  v_itemisation_append_json jsonb := '{}'::jsonb;
  v_selected_case_line jsonb := null::jsonb;
  v_overlay_session_id uuid := NULL::uuid;
  v_overlay_session_id_text text := NULL::text;
  v_overlay_candidate_uuid uuid := NULL::uuid;
  v_overlay_now timestamptz := now();
  v_overlay_excluded_count integer := 0;
  v_overlay_preview_row_count integer := 0;
  v_overlay_draftable_row_count integer := 0;
  v_overlay_blocked_row_count integer := 0;
  v_overlay_do_not_pay_row_count integer := 0;
  v_overlay_total_amount_ex_vat numeric := 0;
  v_overlay_draftable_amount_ex_vat numeric := 0;
begin
  if jsonb_typeof(v_candidate_baseline_root) <> 'object' then
    raise exception 'p_candidate_baseline_json must be a JSON object';
  end if;

  if jsonb_typeof(v_case_resolutions_input) <> 'object' then
    v_case_resolutions_input := '{}'::jsonb;
  end if;

  if jsonb_typeof(v_overrides_input) <> 'object' then
    v_overrides_input := '{}'::jsonb;
  end if;

  v_candidate_id := btrim(coalesce(
    v_candidate_baseline_root->>'candidate_id',
    v_candidate_baseline_root #>> '{candidate_row,candidate_id}',
    ''
  ));

  if v_candidate_id = '' then
    raise exception 'candidate_id is required on p_candidate_baseline_json';
  end if;

  v_candidate_row := case when jsonb_typeof(v_candidate_baseline_root->'candidate_row') = 'object' then coalesce(v_candidate_baseline_root->'candidate_row', '{}'::jsonb) else '{}'::jsonb end;
  v_summary_fragment := case when jsonb_typeof(v_candidate_baseline_root->'summary_fragment') = 'object' then coalesce(v_candidate_baseline_root->'summary_fragment', '{}'::jsonb) else '{}'::jsonb end;
  v_case_states := case when jsonb_typeof(v_candidate_baseline_root->'case_resolution_states') = 'array' then coalesce(v_candidate_baseline_root->'case_resolution_states', '[]'::jsonb) else '[]'::jsonb end;
  v_lines := case when jsonb_typeof(v_candidate_baseline_root->'canonical_preview_lines') = 'array' then coalesce(v_candidate_baseline_root->'canonical_preview_lines', '[]'::jsonb) else '[]'::jsonb end;
  v_payees := case when jsonb_typeof(v_candidate_baseline_root->'payees') = 'array' then coalesce(v_candidate_baseline_root->'payees', '[]'::jsonb) else '[]'::jsonb end;
  v_itemisation := case when jsonb_typeof(v_candidate_baseline_root->'itemisation') = 'array' then coalesce(v_candidate_baseline_root->'itemisation', '[]'::jsonb) else '[]'::jsonb end;
  v_blocked_items := case when jsonb_typeof(v_candidate_baseline_root->'blocked_items') = 'array' then coalesce(v_candidate_baseline_root->'blocked_items', '[]'::jsonb) else '[]'::jsonb end;
  v_do_not_pay_items := case when jsonb_typeof(v_candidate_baseline_root->'do_not_pay_items') = 'array' then coalesce(v_candidate_baseline_root->'do_not_pay_items', '[]'::jsonb) else '[]'::jsonb end;
  v_snoozed_items := case when jsonb_typeof(v_candidate_baseline_root->'snoozed_items') = 'array' then coalesce(v_candidate_baseline_root->'snoozed_items', '[]'::jsonb) else '[]'::jsonb end;
  v_baseline_component_rows := case when jsonb_typeof(v_candidate_baseline_root->'baseline_component_rows') = 'array' then coalesce(v_candidate_baseline_root->'baseline_component_rows', '[]'::jsonb) else '[]'::jsonb end;
  v_timesheet_snapshots_json := case when jsonb_typeof(v_candidate_baseline_root->'timesheet_snapshots_json') = 'array' then coalesce(v_candidate_baseline_root->'timesheet_snapshots_json', '[]'::jsonb) else '[]'::jsonb end;
  v_hidden_recovery_template_lines_input := case
    when jsonb_typeof(v_candidate_baseline_root->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_baseline_root->'hidden_recovery_template_lines', '[]'::jsonb)
    when jsonb_typeof(v_candidate_row->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_row->'hidden_recovery_template_lines', '[]'::jsonb)
    else '[]'::jsonb
  end;

  select coalesce(jsonb_agg(elem.value order by elem.ord), '[]'::jsonb)
  into v_hidden_recovery_template_lines
  from jsonb_array_elements(v_hidden_recovery_template_lines_input) with ordinality as elem(value, ord)
  where jsonb_typeof(elem.value) = 'object';

  v_hidden_recovery_template_line_count := jsonb_array_length(v_hidden_recovery_template_lines);

  v_case_resolutions := case
    when jsonb_typeof(v_case_resolutions_input->'case_resolutions') = 'object' then coalesce(v_case_resolutions_input->'case_resolutions', '{}'::jsonb)
    when jsonb_typeof(v_case_resolutions_input) = 'object' then coalesce(v_case_resolutions_input, '{}'::jsonb)
    else '{}'::jsonb
  end;

  v_exclude_timesheet_ids := case
    when jsonb_typeof(v_overrides_input->'exclude_timesheet_ids') = 'array' then coalesce(v_overrides_input->'exclude_timesheet_ids', '[]'::jsonb)
    when jsonb_typeof(v_overrides_input->'timesheet_exclusions') = 'array' then coalesce(v_overrides_input->'timesheet_exclusions', '[]'::jsonb)
    else '[]'::jsonb
  end;

  v_overlay_session_id_text := NULLIF(BTRIM(COALESCE(
    v_candidate_baseline_root->>'workbench_session_id',
    v_candidate_baseline_root->>'session_id',
    v_candidate_baseline_root#>>'{workbench,session_id}',
    v_candidate_row->>'workbench_session_id',
    v_candidate_row->>'session_id',
    ''
  )), '');

  IF v_overlay_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_overlay_session_id := v_overlay_session_id_text::uuid;
  END IF;

  IF v_candidate_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_overlay_candidate_uuid := v_candidate_id::uuid;
  END IF;

  IF v_overlay_session_id IS NOT NULL THEN
    IF v_overlay_candidate_uuid IS NULL THEN
      RAISE EXCEPTION 'PAY_PREVIEW_OVERLAY_CANDIDATE_ID_NOT_UUID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_OVERLAY_CANDIDATE_ID_NOT_UUID',
                'candidate_id', v_candidate_id
              )::text;
    END IF;

    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_overlay_session_id
      AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_OVERLAY_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_OVERLAY_SESSION_NOT_OPEN',
                'session_id', v_overlay_session_id::text,
                'candidate_id', v_overlay_candidate_uuid::text
              )::text;
    END IF;

    IF jsonb_typeof(v_exclude_timesheet_ids) = 'array'
       AND jsonb_array_length(v_exclude_timesheet_ids) > 0 THEN
      WITH excluded_timesheets AS (
        SELECT DISTINCT NULLIF(BTRIM(excluded_id.value), '')::uuid AS timesheet_id
        FROM jsonb_array_elements_text(v_exclude_timesheet_ids) AS excluded_id(value)
        WHERE NULLIF(BTRIM(excluded_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), updated_preview_rows AS (
        UPDATE public.banking_pay_workbench_preview_rows AS preview_row
        SET selected = false,
            selection_state = 'EXCLUDED',
            row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'is_excluded_from_allocation', true,
                'is_do_not_pay', true,
                'presentation_section', 'DO_NOT_PAY',
                'readiness_state', 'DO_NOT_PAY',
                'draftable', false,
                'is_ready_for_draft', false,
                'overlay_applied_at_utc', v_overlay_now::text,
                'overlay_reason', 'SESSION_TIMESHEET_EXCLUSION'
              ),
            updated_at_utc = v_overlay_now
        FROM excluded_timesheets
        WHERE preview_row.session_id = v_overlay_session_id
          AND preview_row.candidate_id = v_overlay_candidate_uuid
          AND preview_row.timesheet_id = excluded_timesheets.timesheet_id
        RETURNING preview_row.id
      )
      SELECT COUNT(*)::integer
      INTO v_overlay_excluded_count
      FROM updated_preview_rows;
    ELSE
      v_overlay_excluded_count := 0;
    END IF;

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (
        WHERE COALESCE(preview_row.selected, false) = true
          AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY', 'CASES_RESOLUTIONS')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) = 'DO_NOT_PAY'
           OR LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_do_not_pay', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )::integer,
      COALESCE(SUM(CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric),
      COALESCE(SUM(CASE WHEN COALESCE(preview_row.selected, false) = true AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED') AND COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric)
    INTO
      v_overlay_preview_row_count,
      v_overlay_draftable_row_count,
      v_overlay_blocked_row_count,
      v_overlay_do_not_pay_row_count,
      v_overlay_total_amount_ex_vat,
      v_overlay_draftable_amount_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_overlay_session_id
      AND preview_row.candidate_id = v_overlay_candidate_uuid;

    v_summary_fragment := COALESCE(v_summary_fragment, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_count', 1,
        'canonical_preview_line_count', COALESCE(v_overlay_preview_row_count, 0),
        'ready_preview_line_count', COALESCE(v_overlay_draftable_row_count, 0),
        'blocked_preview_line_count', COALESCE(v_overlay_blocked_row_count, 0),
        'do_not_pay_line_count', COALESCE(v_overlay_do_not_pay_row_count, 0),
        'overlay_excluded_preview_row_count', COALESCE(v_overlay_excluded_count, 0),
        'total_amount_ex_vat', round(COALESCE(v_overlay_total_amount_ex_vat, 0), 2),
        'draftable_amount_ex_vat', round(COALESCE(v_overlay_draftable_amount_ex_vat, 0), 2),
        'row_backed', true
      );

    v_candidate_row := COALESCE(v_candidate_row, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_id', v_candidate_id,
        'row_backed', true,
        'preview_row_count', COALESCE(v_overlay_preview_row_count, 0),
        'draftable_preview_row_count', COALESCE(v_overlay_draftable_row_count, 0),
        'blocked_preview_line_count', COALESCE(v_overlay_blocked_row_count, 0),
        'do_not_pay_line_count', COALESCE(v_overlay_do_not_pay_row_count, 0),
        'is_ready_for_draft', (COALESCE(v_overlay_draftable_row_count, 0) > 0),
        'is_review_required', (COALESCE(v_overlay_blocked_row_count, 0) > 0 OR COALESCE(v_overlay_do_not_pay_row_count, 0) > 0)
      );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'workbench_session_id', v_overlay_session_id::text,
      'row_backed_overlay', true,
      'overlay_excluded_preview_row_count', COALESCE(v_overlay_excluded_count, 0),
      'candidate_row', COALESCE(v_candidate_row, '{}'::jsonb),
      'summary_fragment', COALESCE(v_summary_fragment, '{}'::jsonb),
      'case_resolution_states', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'hidden_recovery_template_lines', COALESCE(v_hidden_recovery_template_lines, '[]'::jsonb),
      'hidden_recovery_template_line_count', COALESCE(v_hidden_recovery_template_line_count, 0),
      'payees', COALESCE(v_payees, '[]'::jsonb),
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'timesheet_snapshots_json', '[]'::jsonb
    );
  END IF;


  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    if upper(btrim(coalesce(v_case_state->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
      v_case_scope_linked_timesheet_ids := case
        when jsonb_typeof(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}') = 'array'
          then coalesce(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}', '[]'::jsonb)
        when nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), '') is not null
          then jsonb_build_array(v_case_state->>'timesheet_id')
        else '[]'::jsonb
      end;

      v_linked_timesheet_map := v_linked_timesheet_map || jsonb_build_object(v_case_state_case_key, v_case_scope_linked_timesheet_ids);
    end if;
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_baseline_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_bucket_resolution_applied := false;

    v_component_scope := upper(btrim(coalesce(v_component_row->>'component_scope', '')));
    v_component_case_key := btrim(coalesce(v_component_row->>'case_key', ''));
    v_component_timesheet_id := btrim(coalesce(v_component_row->>'timesheet_id', ''));
    v_component_source_family_key := btrim(coalesce(v_component_row->>'source_family_key', ''));
    v_component_key_type := upper(btrim(coalesce(v_component_row->>'component_key_type', '')));
    v_component_key_value := btrim(coalesce(v_component_row->>'component_key_value', ''));
    v_component_bucket_code := upper(btrim(coalesce(v_component_row->>'bucket_code', '')));
    v_component_source_basis_fingerprint := btrim(coalesce(v_component_row->>'source_basis_fingerprint', ''));
    v_component_fingerprint := btrim(coalesce(v_component_row->>'component_fingerprint', ''));

    v_component_source_units := case when coalesce(v_component_row->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_units')::numeric, 6) else null::numeric end;
    v_component_source_rate := case when coalesce(v_component_row->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_rate := case when coalesce(v_component_row->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
    v_component_source_pay_ex_vat := case
      when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_entitlement_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_reservation_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
      else null::numeric
    end;

    for v_case_resolution_entry in
      select preview_resolution.key as case_key, preview_resolution.value as resolution_json
      from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
      where jsonb_typeof(preview_resolution.value) = 'object'
    loop
      v_case_resolution_json := v_case_resolution_entry.resolution_json;
      v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_case_resolution_entry.case_key, ''));
      v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));
      v_resolve_all_linked_timesheets := coalesce((v_case_resolution_json->>'resolve_all_linked_timesheets')::boolean, false);

      if v_resolution_family <> 'BUCKETED' then
        continue;
      end if;

      v_component_direct_case_match := (v_resolution_case_key <> '' and v_resolution_case_key = v_component_case_key);
      v_component_linked_case_match := false;

      if v_component_direct_case_match = false and v_resolve_all_linked_timesheets = true and v_component_scope = 'TIMESHEET' and v_component_timesheet_id <> '' then
        v_component_linked_ids := coalesce(v_linked_timesheet_map->v_resolution_case_key, '[]'::jsonb);
        if exists (
          select 1
          from jsonb_array_elements_text(v_component_linked_ids) as linked_id(value)
          where btrim(linked_id.value) = v_component_timesheet_id
        ) then
          v_component_linked_case_match := true;
        end if;
      end if;

      v_component_case_applies := (v_component_direct_case_match or v_component_linked_case_match);

      if v_component_case_applies = false then
        continue;
      end if;

      for v_bucket_resolution_json in
        select bucket_elem.value
        from jsonb_array_elements(coalesce(v_case_resolution_json->'bucket_resolutions', '[]'::jsonb)) as bucket_elem(value)
        where jsonb_typeof(bucket_elem.value) = 'object'
      loop
        v_bucket_source_family_key := btrim(coalesce(v_bucket_resolution_json->>'source_family_key', ''));
        v_bucket_component_key_type := upper(btrim(coalesce(v_bucket_resolution_json->>'component_key_type', '')));
        v_bucket_component_key_value := btrim(coalesce(v_bucket_resolution_json->>'component_key_value', ''));
        v_bucket_source_basis_fingerprint := btrim(coalesce(v_bucket_resolution_json->>'source_basis_fingerprint', ''));
        v_bucket_bucket_code := upper(btrim(coalesce(v_bucket_resolution_json->>'bucket_code', '')));
        v_bucket_resolution_mode := upper(btrim(coalesce(v_bucket_resolution_json->>'resolution_mode', '')));
        v_bucket_target_rate := case when coalesce(v_bucket_resolution_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'target_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_units := case when coalesce(v_bucket_resolution_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_units')::numeric, 6) else null::numeric end;
        v_bucket_source_rate := case when coalesce(v_bucket_resolution_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_charge_rate := case when coalesce(v_bucket_resolution_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_charge_rate')::numeric, 6) else null::numeric end;

        v_is_component_match := false;

        if v_bucket_source_family_key = v_component_source_family_key
           and v_bucket_component_key_type = v_component_key_type
           and v_bucket_component_key_value = v_component_key_value then
          if v_bucket_source_basis_fingerprint <> '' then
            v_is_component_match := (v_bucket_source_basis_fingerprint = v_component_source_basis_fingerprint);
          else
            v_is_component_match := true;

            if v_bucket_bucket_code <> '' then
              v_is_component_match := v_is_component_match and (v_bucket_bucket_code = v_component_bucket_code);
            end if;

            if v_bucket_source_units is not null then
              v_is_component_match := v_is_component_match and (v_component_source_units is not null and round(v_component_source_units, 6) = v_bucket_source_units);
            end if;

            if v_bucket_source_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_rate is not null and round(v_component_source_rate, 6) = v_bucket_source_rate);
            end if;

            if v_bucket_source_charge_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_charge_rate is not null and round(v_component_source_charge_rate, 6) = v_bucket_source_charge_rate);
            end if;
          end if;
        end if;

        if v_is_component_match = false then
          continue;
        end if;

        if v_component_key_type = 'TS_DAY' and not (v_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key for resolved component: %', v_component_key_value;
        end if;

        if v_bucket_component_key_type = 'TS_DAY' and not (v_bucket_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key in bucket resolution: %', v_bucket_component_key_value;
        end if;

        if v_bucket_target_rate is null or v_component_source_units is null or v_component_source_units = 0 then
          continue;
        end if;

        v_bucket_target_pay_ex_vat := round(v_bucket_target_rate * v_component_source_units, 2);
        v_bucket_target_charge_ex_vat := v_component_source_charge_ex_vat;
        v_bucket_target_margin_ex_vat := case when v_bucket_target_charge_ex_vat is null then null::numeric else round(v_bucket_target_charge_ex_vat - v_bucket_target_pay_ex_vat, 2) end;
        v_bucket_margin_delta_ex_vat := case when v_component_source_pay_ex_vat is null then null::numeric else round(v_component_source_pay_ex_vat - v_bucket_target_pay_ex_vat, 2) end;

        v_updated_component_row := (v_updated_component_row
          - 'approved_resolution_mode'
          - 'approved_target_rate'
          - 'requires_resolution'
          - 'case_resolution_satisfied_now_component'
          - 'suggestion_provenance'
          - 'is_fresh_suggested_resolution'
          - 'preview_component_amount_ex_vat'
          - 'ready_preview_amount_ex_vat'
          - 'blocked_preview_amount_ex_vat'
          - 'target_pay_ex_vat'
          - 'target_charge_ex_vat'
          - 'target_margin_ex_vat'
          - 'margin_delta_ex_vat'
          - 'resolution_state'
          - 'target_rate')
          || jsonb_build_object(
            'approved_resolution_mode', v_bucket_resolution_mode,
            'approved_target_rate', round(v_bucket_target_rate, 6),
            'requires_resolution', false,
            'case_resolution_satisfied_now_component', true,
            'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
            'is_fresh_suggested_resolution', false,
            'preview_component_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'ready_preview_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'blocked_preview_amount_ex_vat', 0,
            'source_pay_ex_vat', v_component_source_pay_ex_vat,
            'source_entitlement_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_reservation_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_units', v_component_source_units,
            'source_rate', v_component_source_rate,
            'source_charge_rate', v_component_source_charge_rate,
            'source_charge_ex_vat', v_component_source_charge_ex_vat,
            'target_units', v_component_source_units,
            'target_pay_ex_vat', v_bucket_target_pay_ex_vat,
            'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
            'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
            'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat,
            'resolution_state', 'RESOLVED',
            'target_rate', round(v_bucket_target_rate, 6),
            'resolution_mode', v_bucket_resolution_mode,
            'resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            )),
            'suggested_resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'suggested_resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            ))
          );

        v_bucket_resolution_applied := true;
        exit;
      end loop;

      if v_bucket_resolution_applied = true then
        exit;
      end if;
    end loop;

    v_bucket_applied_component_rows := v_bucket_applied_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_nonbucket_allocations := '{}'::jsonb;

  for v_nonbucket_resolution_entry in
    select preview_resolution.key as case_key, preview_resolution.value as resolution_json
    from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
    where jsonb_typeof(preview_resolution.value) = 'object'
  loop
    v_case_resolution_json := v_nonbucket_resolution_entry.resolution_json;
    v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_nonbucket_resolution_entry.case_key, ''));
    v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));

    if v_resolution_family <> 'NON_BUCKET' or v_resolution_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(v_case_states) as case_state_elem(value)
      where jsonb_typeof(case_state_elem.value) = 'object'
        and btrim(coalesce(case_state_elem.value->>'case_key', '')) = v_resolution_case_key
        and upper(btrim(coalesce(case_state_elem.value->>'case_scope', ''))) = 'FINANCE_CASE'
        and upper(btrim(coalesce(case_state_elem.value->>'case_type', ''))) = 'MANUAL_DEBT_ADJUSTMENT'
    ) into v_nonbucket_case_allowed;

    if v_nonbucket_case_allowed = false then
      continue;
    end if;

    v_nonbucket_resolution_mode := upper(btrim(coalesce(v_case_resolution_json->>'resolution_mode', '')));
    v_nonbucket_target_amount_ex_vat := case when coalesce(v_case_resolution_json->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_resolution_json->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

    if v_nonbucket_target_amount_ex_vat is null then
      continue;
    end if;

    v_nonbucket_case_row_count := 0;
    v_nonbucket_case_total_basis := 0;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_count := v_nonbucket_case_row_count + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;
        v_nonbucket_case_total_basis := v_nonbucket_case_total_basis + greatest(v_nonbucket_case_row_basis, 0);
      end if;
    end loop;

    if v_nonbucket_case_row_count <= 0 then
      continue;
    end if;

    v_nonbucket_case_row_index := 0;
    v_nonbucket_case_allocated_so_far := 0;
    v_nonbucket_case_row_allocations := '{}'::jsonb;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_index := v_nonbucket_case_row_index + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;

        if v_nonbucket_case_row_index < v_nonbucket_case_row_count and v_nonbucket_case_total_basis > 0 then
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat * (greatest(v_nonbucket_case_row_basis, 0) / v_nonbucket_case_total_basis), 2);
        elsif v_nonbucket_case_row_index < v_nonbucket_case_row_count then
          v_nonbucket_case_row_target_amount_ex_vat := 0;
        else
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat - v_nonbucket_case_allocated_so_far, 2);
        end if;

        v_nonbucket_case_allocated_so_far := v_nonbucket_case_allocated_so_far + v_nonbucket_case_row_target_amount_ex_vat;
        v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
        end if;
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_key_type', '')) || '|' || btrim(coalesce(v_component_row->>'component_key_value', '')) || '|' || v_nonbucket_case_row_index::text;
        end if;

        v_nonbucket_case_row_allocations := v_nonbucket_case_row_allocations || jsonb_build_object(v_nonbucket_case_row_key, jsonb_build_object(
          'resolution_mode', v_nonbucket_resolution_mode,
          'target_amount_ex_vat', v_nonbucket_case_row_target_amount_ex_vat
        ));
      end if;
    end loop;

    v_nonbucket_allocations := v_nonbucket_allocations || jsonb_build_object(v_resolution_case_key, v_nonbucket_case_row_allocations);
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_nonbucket_resolution_applied := false;
    v_resolution_case_key := btrim(coalesce(v_component_row->>'case_key', ''));

    if jsonb_typeof(v_nonbucket_allocations->v_resolution_case_key) = 'object' then
      v_component_lookup_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
      if v_component_lookup_key = '' then
        v_component_lookup_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
      end if;

      if v_component_lookup_key <> '' and jsonb_typeof((v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key) = 'object' then
        v_nonbucket_case_payload := (v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key;
        v_nonbucket_resolution_mode := upper(btrim(coalesce(v_nonbucket_case_payload->>'resolution_mode', '')));
        v_nonbucket_target_amount_ex_vat := case when coalesce(v_nonbucket_case_payload->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_nonbucket_case_payload->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

        if v_nonbucket_target_amount_ex_vat is not null then
          v_component_target_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
          v_component_target_margin_ex_vat := case when v_component_target_charge_ex_vat is null then null::numeric else round(v_component_target_charge_ex_vat - v_nonbucket_target_amount_ex_vat, 2) end;
          v_component_margin_delta_ex_vat := case when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric - v_nonbucket_target_amount_ex_vat, 2) else null::numeric end;

          v_updated_component_row := (v_updated_component_row
            - 'approved_nonbucket_resolution_mode'
            - 'approved_nonbucket_target_amount_ex_vat'
            - 'requires_resolution'
            - 'case_resolution_satisfied_now_component'
            - 'suggestion_provenance'
            - 'is_fresh_suggested_resolution'
            - 'preview_component_amount_ex_vat'
            - 'ready_preview_amount_ex_vat'
            - 'blocked_preview_amount_ex_vat'
            - 'target_pay_ex_vat'
            - 'target_charge_ex_vat'
            - 'target_margin_ex_vat'
            - 'margin_delta_ex_vat'
            - 'resolution_state')
            || jsonb_build_object(
              'approved_nonbucket_resolution_mode', v_nonbucket_resolution_mode,
              'approved_nonbucket_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'requires_resolution', false,
              'case_resolution_satisfied_now_component', true,
              'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
              'is_fresh_suggested_resolution', false,
              'preview_component_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'ready_preview_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'blocked_preview_amount_ex_vat', 0,
              'target_pay_ex_vat', v_nonbucket_target_amount_ex_vat,
              'target_charge_ex_vat', v_component_target_charge_ex_vat,
              'target_margin_ex_vat', v_component_target_margin_ex_vat,
              'margin_delta_ex_vat', v_component_margin_delta_ex_vat,
              'resolution_state', 'RESOLVED'
            );

          v_nonbucket_resolution_applied := true;
        end if;
      end if;
    end if;

    v_final_component_rows := v_final_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_updated_case_states := '[]'::jsonb;
  v_case_state_map := '{}'::jsonb;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_updated_components := '[]'::jsonb;
    v_case_state_updated_components_count := 0;
    v_case_state_open_taxable_count := 0;
    v_case_state_open_reimbursement_count := 0;
    v_case_state_unresolved_taxable_count := 0;
    v_case_state_total_preview_amount_ex_vat := 0;
    v_case_state_safe_amount_ex_vat := 0;
    v_case_state_blocked_amount_ex_vat := 0;
    v_case_state_unresolved_taxable_amount_ex_vat := 0;

    for v_case_component_row in
      select elem.value
      from jsonb_array_elements(v_final_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_case_component_row->>'case_key', '')) = v_case_state_case_key then
        v_case_state_updated_components := v_case_state_updated_components || jsonb_build_array(v_case_component_row);
        v_case_state_updated_components_count := v_case_state_updated_components_count + 1;

        if upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
          v_case_state_open_taxable_count := v_case_state_open_taxable_count + 1;
        elsif upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' then
          v_case_state_open_reimbursement_count := v_case_state_open_reimbursement_count + 1;
        end if;

        if coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        if coalesce(v_case_component_row->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'ready_preview_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        v_component_requires_resolution := coalesce((v_case_component_row->>'requires_resolution')::boolean, false);
        if v_component_requires_resolution then
          v_case_state_unresolved_taxable_count := v_case_state_unresolved_taxable_count + 1;
          if coalesce(v_case_component_row->>'blocked_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'blocked_preview_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
          end if;
        end if;
      end if;
    end loop;

    v_case_state_needs_resolution := (v_case_state_unresolved_taxable_count > 0);
    v_case_state_satisfied_now := not v_case_state_needs_resolution;
    if v_case_state_needs_resolution then
      v_case_state_blocked_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
      v_case_state_safe_amount_ex_vat := 0;
    else
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_safe_amount_ex_vat, 2);
    end if;

    v_case_is_excluded := false;
    if v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT') and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    if v_case_is_excluded then
      v_case_state_needs_resolution := false;
      v_case_state_satisfied_now := true;
      v_case_state_unresolved_taxable_count := 0;
      v_case_state_unresolved_taxable_amount_ex_vat := 0;
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
    end if;

    select count(*)::int
    into v_case_state_existing_blocked_reasons_count
    from jsonb_array_elements_text(
      case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end
    ) as blocker(value);

    v_existing_case_state_summary := case when jsonb_typeof(v_case_state->'case_resolution_summary') = 'object' then coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb) else '{}'::jsonb end;

    v_case_state_summary := (v_existing_case_state_summary
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'is_blocked'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'excluded_from_pay', v_case_is_excluded
      );

    v_case_state_taxable_manual_debt_resolution := case when jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then coalesce(v_case_state->'taxable_manual_debt_resolution', '{}'::jsonb) else null::jsonb end;
    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      if exists (
        select 1
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
      ) then
        select upper(btrim(coalesce(comp.value->>'approved_nonbucket_resolution_mode', ''))),
               case when coalesce(comp.value->>'approved_nonbucket_target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((comp.value->>'approved_nonbucket_target_amount_ex_vat')::numeric, 2) else null::numeric end
        into v_nonbucket_resolution_mode, v_nonbucket_target_amount_ex_vat
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
        limit 1;

        v_case_state_taxable_manual_debt_resolution := v_case_state_taxable_manual_debt_resolution
          || jsonb_build_object(
            'approved_resolution_mode', v_nonbucket_resolution_mode,
            'approved_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
            'case_resolution_satisfied_now', v_case_state_satisfied_now
          );
      end if;
    end if;

    v_case_state_updated := (v_case_state
      - 'components'
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'is_blocked'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'case_resolution_summary'
      - 'taxable_manual_debt_resolution'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'components', coalesce(v_case_state_updated_components, '[]'::jsonb),
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'case_resolution_summary', v_case_state_summary,
        'excluded_from_pay', v_case_is_excluded
      );

    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_taxable_manual_debt_resolution);
    end if;

    if coalesce(v_case_state_updated->>'due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('due_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    if coalesce(v_case_state_updated->>'payment_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('payment_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    v_updated_case_states := v_updated_case_states || jsonb_build_array(v_case_state_updated);
    if v_case_state_case_key <> '' then
      v_case_state_map := v_case_state_map || jsonb_build_object(v_case_state_case_key, v_case_state_updated);
    end if;
  end loop;

  v_updated_lines := '[]'::jsonb;

  for v_line in
    select elem.value
    from jsonb_array_elements(v_lines) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));
    if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
      continue;
    end if;
    v_updated_lines := v_updated_lines || jsonb_build_array(v_line);
  end loop;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_needs_resolution := coalesce(nullif(v_case_state->>'case_needs_resolution', '')::boolean, false);
    v_case_state_is_timesheet_scope := (v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT'));
    v_case_ready_amount_ex_vat := case when coalesce(v_case_state->>'safe_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'safe_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_blocked_amount_ex_vat := case when coalesce(v_case_state->>'blocked_case_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'blocked_case_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_total_amount_ex_vat := round(v_case_ready_amount_ex_vat + v_case_blocked_amount_ex_vat, 2);

    select coalesce(jsonb_agg(detail_component.value order by coalesce(detail_component.value->>'component_key_type', ''), coalesce(detail_component.value->>'component_key_value', ''), coalesce(detail_component.value->>'bucket_code', '')), '[]'::jsonb)
    into v_case_state_resolved_detail_rows
    from jsonb_array_elements(coalesce(v_case_state->'components', '[]'::jsonb)) as detail_component(value)
    where jsonb_typeof(detail_component.value) = 'object'
      and coalesce(detail_component.value->>'case_resolution_satisfied_now_component', '') in ('true', 'TRUE')
      and upper(btrim(coalesce(detail_component.value->>'component_key_type', ''))) in ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'ADJUSTMENT_CODE', 'EXPENSE_CODE');

    if v_case_state_resolved_detail_rows is null then
      v_case_state_resolved_detail_rows := '[]'::jsonb;
    end if;

    v_case_is_excluded := false;
    if v_case_state_is_timesheet_scope = true and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    v_template_base_line := null::jsonb;
    v_template_ready_line := null::jsonb;
    v_template_blocked_line := null::jsonb;
    v_template_do_not_pay_line := null::jsonb;

    for v_line in
      select elem.value
      from jsonb_array_elements(v_lines) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_line->>'case_key', '')) = v_case_state_case_key then
        if v_template_base_line is null then
          v_template_base_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'READY_TO_PAY' and v_template_ready_line is null then
          v_template_ready_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY' and v_template_blocked_line is null then
          v_template_blocked_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'DO_NOT_PAY' and v_template_do_not_pay_line is null then
          v_template_do_not_pay_line := v_line;
        end if;
      end if;
    end loop;

    if v_template_base_line is null and v_case_state_is_timesheet_scope = true then
      v_template_base_line := jsonb_build_object(
        'candidate_id', v_candidate_id,
        'tms_ref', nullif(btrim(coalesce(v_candidate_row->>'tms_ref', '')), ''),
        'display_name', nullif(btrim(coalesce(v_candidate_row->>'display_name', v_candidate_row->>'candidate_name', '')), ''),
        'line_type', 'TIMESHEET_PAYMENT',
        'finance_case_id', null,
        'case_key', v_case_state_case_key,
        'case_type', coalesce(nullif(btrim(coalesce(v_case_state->>'case_type', '')), ''), 'TIMESHEET_PAYMENT')
      )
      || jsonb_build_object(
        'case_is_blocked', true,
        'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
        'case_components', coalesce(v_case_state->'components', '[]'::jsonb),
        'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
        'booking_id', null,
        'client_id', nullif(btrim(coalesce(v_case_state->>'client_id', '')), ''),
        'client_name', nullif(btrim(coalesce(v_case_state->>'client_name', '')), ''),
        'week_ending_date', nullif(btrim(coalesce(v_case_state->>'week_ending_date', '')), ''))
      || jsonb_build_object(
        'role', null,
        'band', null,
        'linked_shift_date', null,
        'pay_channel', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', '')), ''),
        'paye_treatment', case when upper(btrim(coalesce(v_case_state->>'candidate_pay_method', ''))) = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
        'route_type', 'NORMAL_PAYMENT',
        'adjustment_comment', null
      )
      || jsonb_build_object(
        'has_active_timesheet_snooze', false,
        'has_active_segment_snoozes', false,
        'active_segment_snooze_count', 0,
        'active_segment_dated_snooze_count', 0,
        'active_segment_indefinite_snooze_count', 0,
        'whole_timesheet_snooze_action_blocked', false,
        'whole_timesheet_snooze_action_block_reason', null,
        'segment_snooze_action_blocked', false,
        'segment_snooze_action_block_reason', null
      )
      || jsonb_build_object(
        'snooze_identity', jsonb_build_object(
          'identity_type', 'TIMESHEET',
          'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
          'booking_id', null,
          'segment_id', null,
          'segment_stable_key', null,
          'source_ref', null
        ),
        'snooze_state', jsonb_build_object('state', 'NONE')
      );
    end if;

    if v_template_base_line is null then
      continue;
    end if;

    if v_template_ready_line is null then
      v_template_ready_line := v_template_base_line;
    end if;
    if v_template_blocked_line is null then
      v_template_blocked_line := v_template_base_line;
    end if;
    if v_template_do_not_pay_line is null then
      v_template_do_not_pay_line := v_template_base_line;
    end if;

    if v_case_is_excluded = true and round(v_case_total_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_do_not_pay_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;
      if right(v_line_existing_line_id, 11) <> ':do_not_pay' then
        v_line_existing_line_id := v_line_existing_line_id || ':do_not_pay';
      end if;

      v_do_not_pay_reason_codes := case
        when jsonb_typeof(v_template_do_not_pay_line->'blocked_reason_codes') = 'array' then coalesce(v_template_do_not_pay_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_do_not_pay_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'DO_NOT_PAY'
      ) then
        v_do_not_pay_reason_codes := v_do_not_pay_reason_codes || jsonb_build_array('DO_NOT_PAY');
      end if;

      v_new_line := (v_template_do_not_pay_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_section', 'DO_NOT_PAY',
          'presentation_reason', 'SESSION_TIMESHEET_EXCLUSION',
          'readiness_state', 'DO_NOT_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', true,
          'is_excluded_from_allocation', true,
          'blocked_reason_codes', v_do_not_pay_reason_codes,
          'amount_ex_vat', round(v_case_total_amount_ex_vat, 2),
          'amount_display', round(v_case_total_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = true and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := nullif(btrim(coalesce(v_case_state_timesheet_id, '')), '');
      if v_line_existing_line_id is not null then
        v_line_existing_line_id := v_line_existing_line_id || ':03:case';
      else
        v_line_existing_line_id := btrim(coalesce(v_template_base_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := 'case_resolution_required';
        end if;
        if right(v_line_existing_line_id, 8) <> ':03:case' then
          v_line_existing_line_id := v_line_existing_line_id || ':03:case';
        end if;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_case_state #> '{case_resolution_summary,blocked_reason_codes}') = 'array' then coalesce(v_case_state #> '{case_resolution_summary,blocked_reason_codes}', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_line_blocked_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'RESOLUTION_REQUIRED'
      ) then
        v_line_blocked_reason_codes := v_line_blocked_reason_codes || jsonb_build_array('RESOLUTION_REQUIRED');
      end if;

      v_new_line := (v_template_base_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'segment_rows'
        - 'segment_count'
        - 'section_amount_ex_vat'
        - 'section_amount_display'
        - 'section_segment_rows'
        - 'section_segment_count'
        - 'section_non_segment_amount_ex_vat'
        - 'presentation_advisory_text'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_parent_line_id', coalesce(nullif(v_case_state_timesheet_id, ''), v_line_existing_line_id),
          'real_business_timesheet_id', nullif(v_case_state_timesheet_id, ''),
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'is_excluded_from_allocation', false,
          'is_ready_for_draft', false,
          'draftable', false
        )
        || jsonb_build_object(
          'segment_rows', '[]'::jsonb,
          'segment_count', 0,
          'presentation_section', 'CASES_RESOLUTIONS',
          'presentation_role', 'PARENT',
          'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
          'presentation_advisory_text', 'Resolve this case before draft',
          'readiness_state', 'CASES_RESOLUTIONS'
        )
        || jsonb_build_object(
          'section_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'section_amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'section_segment_rows', '[]'::jsonb,
          'section_segment_count', 0,
          'section_non_segment_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = false and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_template_base_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;

      v_new_line := ((coalesce(v_template_blocked_line, v_template_base_line))
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'preview_row_id', '')), ''), v_line_existing_line_id),
          'line_id', v_line_existing_line_id,
          'presentation_line_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'presentation_line_id', '')), ''), v_line_existing_line_id),
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'CASE_BLOCKED',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', false,
          'is_excluded_from_allocation', false,
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    else
      if round(v_case_ready_amount_ex_vat, 2) <> 0 then
        v_line_existing_line_id := btrim(coalesce(v_template_ready_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key;
        end if;

        v_new_line := (v_template_ready_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'segment_rows'
          - 'segment_count'
          - 'section_amount_ex_vat'
          - 'section_amount_display'
          - 'section_segment_rows'
          - 'section_segment_count'
          - 'section_non_segment_amount_ex_vat'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'READY_TO_PAY',
            'presentation_reason', 'READY_TO_PAY',
            'readiness_state', 'READY_TO_PAY',
            'draftable', true,
            'is_ready_for_draft', true,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', '[]'::jsonb,
            'amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'amount_display', round(v_case_ready_amount_ex_vat, 2),
            'payment_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'source_pay_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_entitlement_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_reservation_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_reservation_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'section_amount_display', round(v_case_ready_amount_ex_vat, 2),
            'section_segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'section_segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_non_segment_amount_ex_vat', 0,
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;

      if round(v_case_blocked_amount_ex_vat, 2) <> 0 and v_case_state_needs_resolution = false then
        v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key || ':blocked';
        end if;
        if v_line_existing_line_id = btrim(coalesce(v_template_ready_line->>'line_id', '')) then
          v_line_existing_line_id := v_line_existing_line_id || ':blocked';
        end if;

        v_line_blocked_reason_codes := case
          when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
          when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
          else '[]'::jsonb
        end;

        v_new_line := (v_template_blocked_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'BLOCKED_FOR_PAY',
            'presentation_reason', 'CASE_BLOCKED',
            'readiness_state', 'BLOCKED_FOR_PAY',
            'draftable', false,
            'is_ready_for_draft', false,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', v_line_blocked_reason_codes,
            'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
            'amount_display', round(v_case_blocked_amount_ex_vat, 2),
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;
    end if;
  end loop;

  for v_line in
    select baseline_line.value
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));

    if v_line_case_key <> '' then
      if not exists (
        select 1
        from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
        where jsonb_typeof(rebuilt_line.value) = 'object'
          and btrim(coalesce(rebuilt_line.value->>'case_key', '')) = v_line_case_key
      ) then
        v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
      end if;
    elsif not exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
      where jsonb_typeof(rebuilt_line.value) = 'object'
        and btrim(coalesce(rebuilt_line.value->>'line_id', '')) = btrim(coalesce(v_line->>'line_id', ''))
    ) then
      v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
    end if;
  end loop;

  if jsonb_array_length(v_itemisation) > 0 then
    for v_item in
      select elem.value
      from jsonb_array_elements(v_itemisation) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      v_line_case_key := btrim(coalesce(v_item->>'case_key', ''));
      if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
        v_case_state_from_map := v_case_state_map->v_line_case_key;
        v_selected_case_line := null::jsonb;

        select line_choice.value
        into v_selected_case_line
        from (
          select
            line_elem.value,
            case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
              when 'CASES_RESOLUTIONS' then 0
              when 'READY_TO_PAY' then 1
              when 'BLOCKED_FOR_PAY' then 2
              when 'DO_NOT_PAY' then 3
              else 9
            end as sort_ord
          from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
          where jsonb_typeof(line_elem.value) = 'object'
            and btrim(coalesce(line_elem.value->>'case_key', '')) = v_line_case_key
        ) line_choice
        order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
        limit 1;

        if v_selected_case_line is not null then
          v_line_presentation_section := upper(btrim(coalesce(v_selected_case_line->>'presentation_section', '')));
          v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

          v_item := (v_item
            - 'preview_row_id'
            - 'line_id'
            - 'timesheet_id'
            - 'week_ending_date'
            - 'client_id'
            - 'client_name'
            - 'payment_amount_ex_vat'
            - 'payment_amount_inc_vat'
            - 'payment_amount'
            - 'source_pay_method'
            - 'candidate_pay_method'
            - 'segment_deltas'
            - 'presentation_section'
            - 'presentation_role'
            - 'total_segment_count'
            - 'ready_segment_count'
            - 'blocked_visible_segment_count'
            - 'hidden_indefinite_segment_count'
            - 'is_partially_ready'
            - 'is_partially_blocked'
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution'
            - 'excluded_from_pay'
            - 'is_do_not_pay')
            || jsonb_build_object(
              'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
              'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
              'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state_from_map->>'timesheet_id', '')), ''),
              'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state_from_map->>'week_ending_date', '')), ''),
              'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state_from_map->>'client_id', '')), ''),
              'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state_from_map->>'client_name', '')), ''),
              'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
              'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'source_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
              'candidate_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
              'segment_deltas', case
                when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
                when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            )
            || jsonb_build_object(
              'presentation_section', coalesce(v_selected_case_line->>'presentation_section', v_item->>'presentation_section'),
              'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
              'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
              'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
              'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
              'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
              'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
              'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false),
              'excluded_from_pay', (v_line_presentation_section = 'DO_NOT_PAY'),
              'is_do_not_pay', (v_line_presentation_section = 'DO_NOT_PAY')
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        else
          v_item := (v_item
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution')
            || jsonb_build_object(
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        end if;

        if upper(btrim(coalesce(v_case_state_from_map->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
          v_case_state_timesheet_id := btrim(coalesce(v_case_state_from_map->>'timesheet_id', ''));
          if v_case_state_timesheet_id <> '' and exists (
            select 1
            from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
            where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
          ) then
            v_item := v_item || jsonb_build_object('excluded_from_pay', true, 'is_do_not_pay', true);
          end if;
        end if;
      end if;
      v_updated_itemisation := v_updated_itemisation || jsonb_build_array(v_item);
    end loop;
  else
    v_updated_itemisation := v_itemisation;
  end if;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
      and upper(btrim(coalesce(elem.value->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT')
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_itemisation, '[]'::jsonb)) as item_elem(value)
      where jsonb_typeof(item_elem.value) = 'object'
        and btrim(coalesce(item_elem.value->>'case_key', '')) = v_case_state_case_key
    ) into v_itemisation_match_found;

    if v_itemisation_match_found then
      continue;
    end if;

    select line_choice.value
    into v_selected_case_line
    from (
      select
        line_elem.value,
        case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
          when 'CASES_RESOLUTIONS' then 0
          when 'READY_TO_PAY' then 1
          when 'BLOCKED_FOR_PAY' then 2
          when 'DO_NOT_PAY' then 3
          else 9
        end as sort_ord
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
      where jsonb_typeof(line_elem.value) = 'object'
        and btrim(coalesce(line_elem.value->>'case_key', '')) = v_case_state_case_key
    ) line_choice
    order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
    limit 1;

    if v_selected_case_line is null then
      continue;
    end if;

    v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

    v_itemisation_append_json := jsonb_build_object(
      'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
      'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
      'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state->>'timesheet_id', '')), ''),
      'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state->>'week_ending_date', '')), ''),
      'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state->>'client_id', '')), ''),
      'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state->>'client_name', '')), ''),
      'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
      'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'source_pay_method', nullif(btrim(coalesce(v_case_state->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
      'candidate_pay_method', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
      'segment_deltas', case
        when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
        when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
        else '[]'::jsonb
      end,
      'adjustment_deltas', '[]'::jsonb,
      'delta_additional_pay_ex_vat', 0,
      'additional_unit_deltas', '[]'::jsonb,
      'reservation_overrun_detected', false,
      'delta_expenses_pay_ex_vat', 0,
      'delta_travel_pay_ex_vat', 0,
      'delta_accommodation_pay_ex_vat', 0,
      'delta_other_pay_ex_vat', 0,
      'delta_mileage_pay_ex_vat', 0,
      'case_key', v_case_state_case_key,
      'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
      'components', coalesce(v_case_state->'components', '[]'::jsonb),
      'presentation_section', coalesce(v_selected_case_line->>'presentation_section', 'CASES_RESOLUTIONS'),
      'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
      'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
      'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
      'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
      'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
      'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
      'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false)
    );

    if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
      v_itemisation_append_json := v_itemisation_append_json || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
    end if;

    v_updated_itemisation := coalesce(v_updated_itemisation, '[]'::jsonb) || jsonb_build_array(v_itemisation_append_json);
  end loop;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'display_name', ''), coalesce(elem.value->>'line_type', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_updated_lines
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      (coalesce(elem.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((elem.value->>'amount_ex_vat')::numeric, 2) <> 0)
      or upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
    );


  if jsonb_array_length(coalesce(v_updated_lines, '[]'::jsonb)) = 0 and jsonb_array_length(coalesce(v_lines, '[]'::jsonb)) > 0 then
    select coalesce(jsonb_agg(baseline_line.value order by coalesce(baseline_line.value->>'candidate_id', ''), coalesce(baseline_line.value->>'display_name', ''), coalesce(baseline_line.value->>'line_type', ''), coalesce(baseline_line.value->>'line_id', '')), '[]'::jsonb)
    into v_updated_lines
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
      and (
        (coalesce(baseline_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((baseline_line.value->>'amount_ex_vat')::numeric, 2) <> 0)
        or upper(btrim(coalesce(baseline_line.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      );
  end if;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_blocked_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY';

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_do_not_pay_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      or coalesce((elem.value->>'is_do_not_pay')::boolean, false) = true
    );

  v_candidate_row := (coalesce(v_candidate_row, '{}'::jsonb)
    - 'case_resolution_states'
    - 'canonical_preview_lines'
    - 'itemisation'
    - 'blocked_items'
    - 'do_not_pay_items'
    - 'snoozed_items'
    - 'hidden_recovery_template_lines'
    - 'hidden_recovery_template_line_count')
    || jsonb_build_object(
      'candidate_id', v_candidate_id,
      'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
      'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
      'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
      'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
      'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
      'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
      'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count
    );

  return jsonb_build_object(
    'candidate_id', v_candidate_id,
    'candidate_row', coalesce(v_candidate_row, '{}'::jsonb),
    'summary_fragment', coalesce(v_summary_fragment, '{}'::jsonb),
    'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
    'canonical_preview_lines', coalesce(v_updated_lines, '[]'::jsonb),
    'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'payees', coalesce(v_payees, '[]'::jsonb),
    'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
    'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
    'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
    'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
    'baseline_component_rows', coalesce(v_final_component_rows, '[]'::jsonb),
    'timesheet_snapshots_json', coalesce(v_timesheet_snapshots_json, '[]'::jsonb)
  );
end;
$function$;

-- pay_preview_assemble_payload(jsonb,jsonb)
CREATE OR REPLACE FUNCTION public.pay_preview_assemble_payload(p_context_json jsonb, p_candidate_rollups_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_rollups_root jsonb := COALESCE(p_candidate_rollups_json, '[]'::jsonb);
  v_session_id_text text := NULL::text;
  v_session_id uuid := NULL::uuid;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_rollup_count integer := 0;
  v_tiny_compat_threshold integer := 25;
  v_tiny_compat_allowed boolean := false;
  v_rollup_sample jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_available_sections_json jsonb := '[]'::jsonb;
  v_ready_preview_line_count integer := 0;
  v_selected_preview_line_count integer := 0;
  v_case_resolution_state_count integer := 0;
  v_blocked_preview_line_count integer := 0;
  v_materialised_preview_row_count integer := 0;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_rollups_root) <> 'array' THEN
    RAISE EXCEPTION 'p_candidate_rollups_json must be a JSON array';
  END IF;

  v_candidate_rollup_count := jsonb_array_length(v_candidate_rollups_root);
  v_tiny_compat_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'allow_tiny_compat',
    v_context_json->>'tiny_compat',
    v_context_json->>'explicit_tiny_compat',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{session,id}',
    ''
  )), '');

  IF v_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_session_id := v_session_id_text::uuid;
  END IF;

  IF v_session_id IS NOT NULL THEN
    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_session_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error_code', 'WORKBENCH_SESSION_NOT_FOUND',
        'code', 'WORKBENCH_SESSION_NOT_FOUND',
        'session_id', v_session_id::text,
        'requires_paging', true,
        'ready', false,
        'ready_flag', false,
        'progress_only', true,
        'phase', 'REBASE_REQUIRED',
        'status_text', 'Payment preview needs refreshing.'
      );
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error_code', 'OBSOLETE_SESSION',
        'code', 'OBSOLETE_SESSION',
        'session_id', v_session_id::text,
        'requires_paging', true,
        'ready', false,
        'ready_flag', false,
        'progress_only', true,
        'phase', 'REBASE_REQUIRED',
        'status_text', 'Payment preview needs refreshing.'
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_preview_assemble_sections;
    CREATE TEMPORARY TABLE pg_temp._tmp_pay_preview_assemble_sections ON COMMIT DROP AS
    SELECT
      preview_row.id,
      preview_row.candidate_id,
      preview_row.section,
      preview_row.row_json,
      preview_row.selected,
      preview_row.selection_state,
      public.pay_workbench_preview_section_from_line_json(preview_row.row_json) AS resolved_section
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_session_id
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY';

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'canonical_preview_lines')::integer,
           COUNT(*) FILTER (
             WHERE section_rows.resolved_section = 'canonical_preview_lines'
               AND COALESCE(section_rows.selected, false) = true
               AND UPPER(BTRIM(COALESCE(section_rows.selection_state, ''))) = 'SELECTED'
               AND UPPER(BTRIM(COALESCE(section_rows.row_json->>'presentation_section', section_rows.row_json->>'readiness_state', ''))) = 'READY_TO_PAY'
               AND LOWER(BTRIM(COALESCE(section_rows.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           )::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'cases_resolutions')::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'blocked_for_pay')::integer
    INTO v_materialised_preview_row_count,
         v_ready_preview_line_count,
         v_selected_preview_line_count,
         v_case_resolution_state_count,
         v_blocked_preview_line_count
    FROM pg_temp._tmp_pay_preview_assemble_sections AS section_rows;

    SELECT COALESCE(jsonb_object_agg(section_counts.section_key, to_jsonb(section_counts.section_count) ORDER BY section_counts.section_key), '{}'::jsonb)
    INTO v_section_counts_json
    FROM (
      SELECT section_rows.resolved_section AS section_key,
             COUNT(*)::integer AS section_count
      FROM pg_temp._tmp_pay_preview_assemble_sections AS section_rows
      WHERE section_rows.resolved_section IN ('canonical_preview_lines', 'cases_resolutions', 'blocked_for_pay')
      GROUP BY section_rows.resolved_section
    ) AS section_counts;

    SELECT COALESCE(jsonb_agg(section_keys.section_key ORDER BY section_keys.section_key), '[]'::jsonb)
    INTO v_available_sections_json
    FROM (
      SELECT jsonb_object_keys(COALESCE(v_section_counts_json, '{}'::jsonb)) AS section_key
    ) AS section_keys;

    v_summary := jsonb_build_object(
      'candidate_count', COALESCE(v_session_row.scope_total_count, 0),
      'scope_rows_seeded', COALESCE(v_session_row.scope_seeded_count, 0),
      'scope_rows_ready', COALESCE(v_session_row.scope_ready_count, 0),
      'scope_rows_pending', COALESCE(v_session_row.scope_pending_count, 0),
      'scope_rows_failed', COALESCE(v_session_row.scope_failed_count, 0),
      'canonical_preview_line_count', COALESCE(v_ready_preview_line_count, 0),
      'ready_preview_line_count', COALESCE(v_ready_preview_line_count, 0),
      'selected_preview_line_count', COALESCE(v_selected_preview_line_count, 0),
      'case_resolution_state_count', COALESCE(v_case_resolution_state_count, 0),
      'blocked_preview_line_count', COALESCE(v_blocked_preview_line_count, 0),
      'preview_row_count', COALESCE(v_materialised_preview_row_count, 0)
    ) || jsonb_build_object(
      'section_counts', COALESCE(v_section_counts_json, '{}'::jsonb),
      'available_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'requires_paging', true
    );

    RETURN jsonb_build_object(
      'ok', true,
      'ready', COALESCE(v_session_row.scope_pending_count, 0) = 0
        AND COALESCE(v_session_row.scope_failed_count, 0) = 0
        AND COALESCE(v_session_row.line_units_pending, 0) = 0
        AND COALESCE(v_session_row.line_units_ready, 0) = 0
        AND COALESCE(v_session_row.line_units_failed, 0) = 0,
      'ready_flag', COALESCE(v_session_row.scope_pending_count, 0) = 0
        AND COALESCE(v_session_row.scope_failed_count, 0) = 0
        AND COALESCE(v_session_row.line_units_pending, 0) = 0
        AND COALESCE(v_session_row.line_units_ready, 0) = 0
        AND COALESCE(v_session_row.line_units_failed, 0) = 0,
      'requires_paging', true,
      'large_session_safe', true,
      'progress_only', false,
      'preview_page_rpc', 'pay_workbench_session_get_preview_page',
      'candidate_preview_rpc', 'pay_workbench_session_get_candidate_preview',
      'session_id', v_session_id::text,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'summary', v_summary,
      'progress', COALESCE(v_session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'candidate_count', COALESCE(v_session_row.scope_total_count, 0),
          'seeded_count', COALESCE(v_session_row.scope_seeded_count, 0),
          'ready_count', COALESCE(v_session_row.scope_ready_count, 0),
          'pending_count', COALESCE(v_session_row.scope_pending_count, 0),
          'failed_count', COALESCE(v_session_row.scope_failed_count, 0),
          'line_units_total', COALESCE(v_session_row.line_units_total, 0),
          'line_units_pending', COALESCE(v_session_row.line_units_pending, 0),
          'line_units_ready', COALESCE(v_session_row.line_units_ready, 0),
          'line_units_complete', GREATEST(COALESCE(v_session_row.line_units_total, 0) - COALESCE(v_session_row.line_units_pending, 0) - COALESCE(v_session_row.line_units_ready, 0) - COALESCE(v_session_row.line_units_failed, 0), 0),
          'line_units_error', COALESCE(v_session_row.line_units_failed, 0)
        ),
      'section_counts', COALESCE(v_section_counts_json, '{}'::jsonb),
      'section_cursors', '{}'::jsonb,
      'available_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'pageable_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'samples', jsonb_build_object('scope', COALESCE(v_session_row.candidate_sample_rows_json, '[]'::jsonb)),
      'paye_candidates', '[]'::jsonb,
      'non_paye_payees', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb
    );
  END IF;

  IF v_tiny_compat_allowed IS NOT TRUE OR v_candidate_rollup_count > v_tiny_compat_threshold THEN
    SELECT COALESCE(jsonb_agg(v_candidate_rollups_root -> bounded_sample.sample_index ORDER BY bounded_sample.sample_index), '[]'::jsonb)
    INTO v_rollup_sample
    FROM generate_series(0, GREATEST(LEAST(v_candidate_rollup_count, 25) - 1, -1)) AS bounded_sample(sample_index)
    WHERE jsonb_typeof(v_candidate_rollups_root -> bounded_sample.sample_index) = 'object';

    RETURN jsonb_build_object(
      'ok', true,
      'requires_paging', true,
      'large_session_safe', true,
      'candidate_rollup_count', v_candidate_rollup_count,
      'tiny_compat_allowed', v_tiny_compat_allowed,
      'summary', jsonb_build_object(
        'candidate_count', v_candidate_rollup_count,
        'requires_paging', true,
        'tiny_compat_required_for_full_payload', true
      ),
      'samples', jsonb_build_object('candidate_rollups', COALESCE(v_rollup_sample, '[]'::jsonb)),
      'paye_candidates', '[]'::jsonb,
      'non_paye_payees', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb
    );
  END IF;

  SELECT jsonb_build_object(
    'candidate_count', v_candidate_rollup_count,
    'requires_paging', false,
    'tiny_compat', true,
    'tiny_compat_explicit', true
  )
  INTO v_summary;

  RETURN jsonb_build_object(
    'pay_date', v_context_json->'pay_date',
    'pay_week_start', v_context_json->'pay_week_start',
    'week_ending_cutoff_date', v_context_json->'week_ending_cutoff_date',
    'eligibility', COALESCE(v_context_json->'eligibility', '{}'::jsonb),
    'filters', COALESCE(v_context_json->'filters', '{}'::jsonb),
    'finance', COALESCE(v_context_json->'finance', '{}'::jsonb),
    'settings', COALESCE(v_context_json->'settings', '{}'::jsonb),
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'paye_guardrails', COALESCE(v_context_json->'paye_guardrails', '{}'::jsonb),
    'payees', '[]'::jsonb,
    'canonical_preview_lines', '[]'::jsonb,
    'case_resolution_states', '[]'::jsonb,
    'itemisation', '[]'::jsonb,
    'paye_candidates', '[]'::jsonb,
    'non_paye_payees', '[]'::jsonb,
    'blocked_items', '[]'::jsonb,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'hidden_recovery_template_lines', '[]'::jsonb,
    'hidden_recovery_template_line_count', 0
  );
END;
$function$;

-- pay_preview_build_candidate_baseline(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_baseline(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_candidate_uuid uuid := p_candidate_id;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_candidate_state_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_candidate_fragment_json jsonb := '{}'::jsonb;
  v_summary_fragment_json jsonb := '{}'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_scope_status text := 'PENDING';
  v_ready_state text := 'PENDING';
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF v_candidate_uuid IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF v_workbench_session_id IS NULL THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_uuid::text,
      'row_backed_candidate_baseline', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_uuid::text,
        'row_backed', false,
        'requires_workbench_session', true,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'requires_paging', true,
        'status_text', 'Candidate preview requires a row-backed workbench session.'
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PENDING',
      'ready_state', 'PENDING'
    );
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_workbench_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_FOUND',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_OPEN',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = v_workbench_session_id
    AND scope_row.candidate_id = v_candidate_uuid
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_CANDIDATE_NOT_IN_SCOPE',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  SELECT candidate_state.*
  INTO v_candidate_state_row
  FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
  WHERE candidate_state.session_id = v_workbench_session_id
    AND candidate_state.candidate_id = v_candidate_uuid
  ORDER BY candidate_state.updated_at_utc DESC, candidate_state.id DESC
  LIMIT 1;

  v_scope_status := UPPER(BTRIM(COALESCE(v_scope_row.status, 'PENDING')));
  v_candidate_fragment_json := COALESCE(v_candidate_state_row.effective_candidate_fragment_json, '{}'::jsonb);
  v_summary_fragment_json := COALESCE(v_candidate_state_row.effective_summary_fragment_json, '{}'::jsonb);
  v_case_resolution_states_json := COALESCE(v_candidate_state_row.effective_case_resolution_states_json, '[]'::jsonb);
  v_canonical_preview_lines_json := COALESCE(v_candidate_state_row.effective_canonical_preview_lines_json, '[]'::jsonb);
  v_ready_state := CASE
    WHEN v_scope_status IN ('ERROR', 'FAILED') THEN 'ERROR'
    WHEN v_scope_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 'READY'
    ELSE 'PENDING'
  END;

  SELECT COALESCE(jsonb_agg(blocked_rows.row_json ORDER BY blocked_rows.row_ordinal, blocked_rows.id), '[]'::jsonb)
  INTO v_blocked_items_json
  FROM (
    SELECT preview_row.id, preview_row.row_ordinal, preview_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_workbench_session_id
      AND preview_row.candidate_id = v_candidate_uuid
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND lower(COALESCE(NULLIF(BTRIM(preview_row.section), ''), '')) = 'blocked_for_pay'
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    ORDER BY preview_row.row_ordinal, preview_row.id
    LIMIT 100
  ) AS blocked_rows;

  RETURN jsonb_build_object(
    'candidate_id', v_candidate_uuid::text,
    'workbench_session_id', v_workbench_session_id::text,
    'row_backed_candidate_baseline', true,
    'large_candidate_safe', true,
    'requires_paging', true,
    'candidate_row', jsonb_build_object(
      'candidate_id', v_candidate_uuid::text,
      'row_backed', true,
      'scope_status', v_scope_status,
      'is_ready_for_draft', CASE WHEN COALESCE(v_summary_fragment_json->>'selected_preview_line_count', '') ~ '^[0-9]+$' THEN (v_summary_fragment_json->>'selected_preview_line_count')::integer ELSE 0 END > 0 AND v_ready_state = 'READY',
      'is_review_required', v_ready_state = 'ERROR',
      'error_json', v_scope_row.error_json
    ) || CASE WHEN jsonb_typeof(v_candidate_fragment_json) = 'object' THEN v_candidate_fragment_json ELSE '{}'::jsonb END,
    'summary_fragment', jsonb_build_object(
      'candidate_count', 1,
      'row_backed', true,
      'requires_paging', true,
      'scope_status', v_scope_status,
      'session_version', COALESCE(v_session_row.version, 1),
      'pending_state', CASE WHEN v_ready_state = 'READY' THEN 'READY' ELSE 'PENDING' END
    ) || CASE WHEN jsonb_typeof(v_summary_fragment_json) = 'object' THEN v_summary_fragment_json ELSE '{}'::jsonb END,
    'case_resolution_states', CASE WHEN jsonb_typeof(v_case_resolution_states_json) = 'array' THEN v_case_resolution_states_json ELSE '[]'::jsonb END,
    'canonical_preview_lines', CASE WHEN jsonb_typeof(v_canonical_preview_lines_json) = 'array' THEN v_canonical_preview_lines_json ELSE '[]'::jsonb END,
    'payees', COALESCE(v_candidate_state_row.effective_payees_json, '[]'::jsonb)
  )
  || jsonb_build_object(
    'itemisation', '[]'::jsonb,
    'blocked_items', CASE WHEN jsonb_typeof(v_blocked_items_json) = 'array' THEN v_blocked_items_json ELSE '[]'::jsonb END,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'materialise_required', v_scope_status IN ('LINE_WORK_READY', 'PENDING', 'LINE_WORK_PENDING'),
    'pending_state', CASE WHEN v_ready_state = 'READY' THEN 'READY' WHEN v_ready_state = 'ERROR' THEN 'ERROR' ELSE 'PENDING' END,
    'ready_state', v_ready_state
  );
END;
$function$;

-- pay_preview_build_candidate_rollup(jsonb,jsonb)
CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_rollup(p_context_json jsonb, p_candidate_effective_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_effective_root jsonb := COALESCE(p_candidate_effective_json, '{}'::jsonb);
  v_candidate_row_source jsonb := '{}'::jsonb;
  v_candidate_id text := '';
  v_candidate_uuid uuid := NULL::uuid;
  v_session_id_text text := NULL::text;
  v_session_id uuid := NULL::uuid;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_candidate_state_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_candidate_row jsonb := '{}'::jsonb;
  v_lines_input jsonb := '[]'::jsonb;
  v_lines_input_count integer := 0;
  v_payees_input jsonb := '[]'::jsonb;
  v_display_name text := '';
  v_tms_ref text := '';
  v_inserted_preview_row_count integer := 0;
  v_tiny_compat_allowed boolean := false;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_ready_items_json jsonb := '[]'::jsonb;
  v_ready_count integer := 0;
  v_selected_count integer := 0;
  v_case_count integer := 0;
  v_blocked_count integer := 0;
  v_ready_amount numeric := 0;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_effective_root) <> 'object' THEN
    RAISE EXCEPTION 'p_candidate_effective_json must be a JSON object';
  END IF;

  v_candidate_row_source := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'candidate_row') = 'object'
      THEN COALESCE(v_candidate_effective_root->'candidate_row', '{}'::jsonb)
    ELSE v_candidate_effective_root
  END;

  v_candidate_id := BTRIM(COALESCE(
    v_candidate_row_source->>'candidate_id',
    v_candidate_effective_root->>'candidate_id',
    ''
  ));

  IF v_candidate_id = '' THEN
    RAISE EXCEPTION 'candidate_id is required on p_candidate_effective_json';
  END IF;

  IF v_candidate_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_ID_NOT_UUID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_ID_NOT_UUID',
              'candidate_id', v_candidate_id
            )::text;
  END IF;

  v_candidate_uuid := v_candidate_id::uuid;

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_candidate_effective_root->>'workbench_session_id',
    v_candidate_effective_root->>'session_id',
    v_candidate_effective_root#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_session_id := v_session_id_text::uuid;
  END IF;

  v_display_name := BTRIM(COALESCE(
    v_candidate_row_source->>'display_name',
    v_candidate_row_source->>'candidate_name',
    v_candidate_row_source->>'candidate_display_name',
    v_candidate_effective_root->>'display_name',
    v_candidate_effective_root->>'candidate_name',
    v_candidate_effective_root->>'candidate_display_name',
    ''
  ));

  v_tms_ref := BTRIM(COALESCE(
    v_candidate_row_source->>'tms_ref',
    v_candidate_row_source->>'candidate_tms_ref',
    v_candidate_effective_root->>'tms_ref',
    v_candidate_effective_root->>'candidate_tms_ref',
    ''
  ));

  v_payees_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'payees') = 'array' THEN COALESCE(v_candidate_effective_root->'payees', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'payees') = 'array' THEN COALESCE(v_candidate_row_source->'payees', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_tiny_compat_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'allow_tiny_compat',
    v_context_json->>'tiny_compat',
    v_context_json->>'explicit_tiny_compat',
    v_candidate_effective_root->>'allow_tiny_compat',
    v_candidate_effective_root->>'tiny_compat',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_session_id IS NOT NULL THEN
    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_FOUND',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_OPEN',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    SELECT scope_row.*
    INTO v_scope_row
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = v_session_id
      AND scope_row.candidate_id = v_candidate_uuid
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_NOT_IN_SCOPE',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    SELECT candidate_state.*
    INTO v_candidate_state_row
    FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
    WHERE candidate_state.session_id = v_session_id
      AND candidate_state.candidate_id = v_candidate_uuid
    ORDER BY candidate_state.updated_at_utc DESC, candidate_state.id DESC
    LIMIT 1;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_candidate_rollup_rows;
    CREATE TEMP TABLE _tmp_pay_candidate_rollup_rows ON COMMIT DROP AS
    SELECT
      preview_row.id,
      preview_row.section,
      preview_row.row_ordinal,
      preview_row.row_json,
      preview_row.selected,
      preview_row.selection_state,
      public.pay_workbench_preview_section_from_line_json(preview_row.row_json) AS resolved_section,
      CASE
        WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((preview_row.row_json->>'amount_ex_vat')::numeric, 2)
        WHEN COALESCE(preview_row.row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((preview_row.row_json->>'preview_amount_ex_vat')::numeric, 2)
        ELSE 0::numeric
      END AS amount_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_session_id
      AND preview_row.candidate_id = v_candidate_uuid
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY';

    SELECT COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'canonical_preview_lines')::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'canonical_preview_lines' AND COALESCE(rollup_rows.selected, false))::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'cases_resolutions')::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'blocked_for_pay')::integer,
           ROUND(COALESCE(SUM(CASE WHEN rollup_rows.resolved_section = 'canonical_preview_lines' THEN rollup_rows.amount_ex_vat ELSE 0 END), 0), 2)
    INTO v_ready_count,
         v_selected_count,
         v_case_count,
         v_blocked_count,
         v_ready_amount
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS rollup_rows;

    SELECT COALESCE(jsonb_agg(case_rows.row_json ORDER BY case_rows.row_ordinal, case_rows.id), '[]'::jsonb)
    INTO v_case_resolution_states_json
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS case_rows
    WHERE case_rows.resolved_section = 'cases_resolutions';

    SELECT COALESCE(jsonb_agg(blocked_rows.row_json ORDER BY blocked_rows.row_ordinal, blocked_rows.id), '[]'::jsonb)
    INTO v_blocked_items_json
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS blocked_rows
    WHERE blocked_rows.resolved_section = 'blocked_for_pay';

    SELECT COALESCE(jsonb_agg(ready_rows.row_json ORDER BY ready_rows.row_ordinal, ready_rows.id), '[]'::jsonb)
    INTO v_ready_items_json
    FROM (
      SELECT rollup_rows.*
      FROM pg_temp._tmp_pay_candidate_rollup_rows AS rollup_rows
      WHERE rollup_rows.resolved_section = 'canonical_preview_lines'
      ORDER BY rollup_rows.row_ordinal, rollup_rows.id
      LIMIT 100
    ) AS ready_rows;

    v_summary_fragment := COALESCE(v_candidate_state_row.effective_summary_fragment_json, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_count', 1,
        'row_backed', true,
        'requires_paging', true,
        'session_version', COALESCE(v_session_row.version, 1),
        'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
        'ready_preview_line_count', COALESCE(v_ready_count, 0),
        'selected_preview_line_count', COALESCE(v_selected_count, 0),
        'case_resolution_state_count', COALESCE(v_case_count, 0),
        'blocked_preview_line_count', COALESCE(v_blocked_count, 0),
        'ready_amount_ex_vat', COALESCE(v_ready_amount, 0)
      )
      || jsonb_build_object(
        'section_counts', jsonb_build_object(
          'canonical_preview_lines', COALESCE(v_ready_count, 0),
          'cases_resolutions', COALESCE(v_case_count, 0),
          'blocked_for_pay', COALESCE(v_blocked_count, 0)
        )
      );

    v_candidate_row := (v_candidate_row_source - 'canonical_preview_lines' - 'itemisation' - 'baseline_component_rows')
      || COALESCE(v_candidate_state_row.effective_candidate_fragment_json, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', true,
        'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
        'ready_preview_line_count', COALESCE(v_ready_count, 0),
        'selected_preview_line_count', COALESCE(v_selected_count, 0),
        'case_resolution_state_count', COALESCE(v_case_count, 0),
        'blocked_preview_line_count', COALESCE(v_blocked_count, 0),
        'is_ready_for_draft', COALESCE(v_selected_count, 0) > 0 AND UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED'),
        'is_review_required', UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('ERROR', 'FAILED')
      );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'workbench_session_id', v_session_id::text,
      'row_backed_candidate_rollup', true,
      'display_rows_written', 0,
      'summary_fragment', v_summary_fragment,
      'candidate_row', v_candidate_row,
      'case_resolution_states', COALESCE(v_case_resolution_states_json, '[]'::jsonb),
      'canonical_preview_lines', COALESCE(v_ready_items_json, '[]'::jsonb),
      'payees', COALESCE(v_candidate_state_row.effective_payees_json, v_payees_input, '[]'::jsonb),
      'itemisation', COALESCE(v_ready_items_json, '[]'::jsonb),
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0
    )
    || jsonb_build_object(
      'blocked_items', COALESCE(v_blocked_items_json, '[]'::jsonb),
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', CASE
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('ERROR', 'FAILED') THEN 'ERROR'
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 'READY'
        ELSE 'PENDING'
      END
    );
  END IF;

  IF v_tiny_compat_allowed IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'row_backed_candidate_rollup', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'tiny_compat_required_for_full_payload', true,
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'requires_paging', true,
        'tiny_compat_required_for_full_payload', true
      ),
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', false,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', COALESCE(v_payees_input, '[]'::jsonb),
      'itemisation', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PAGING_REQUIRED'
    );
  END IF;

  v_lines_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_effective_root->'canonical_preview_lines', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_row_source->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_lines_input_count := jsonb_array_length(COALESCE(v_lines_input, '[]'::jsonb));

  IF v_lines_input_count > 100 THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'row_backed_candidate_rollup', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'input_line_count', v_lines_input_count,
        'requires_paging', true
      ),
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', false,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PAGING_REQUIRED'
    );
  END IF;

  v_summary_fragment := jsonb_build_object(
    'candidate_count', 1,
    'canonical_preview_line_count', COALESCE(v_lines_input_count, 0),
    'ready_preview_line_count', COALESCE(v_lines_input_count, 0),
    'requires_paging', false,
    'tiny_compat', true
  );

  v_candidate_row := (v_candidate_row_source - 'canonical_preview_lines' - 'itemisation' - 'baseline_component_rows')
    || jsonb_build_object(
      'candidate_id', v_candidate_id,
      'display_name', v_display_name,
      'candidate_name', v_display_name,
      'tms_ref', v_tms_ref,
      'row_backed', false,
      'tiny_compat', true,
      'tiny_compat_explicit', true,
      'is_ready_for_draft', COALESCE(v_lines_input_count, 0) > 0,
      'is_review_required', false
    );

  RETURN jsonb_build_object(
    'candidate_id', v_candidate_id,
    'summary_fragment', v_summary_fragment,
    'candidate_row', v_candidate_row,
    'case_resolution_states', CASE WHEN jsonb_typeof(v_candidate_effective_root->'case_resolution_states') = 'array' THEN COALESCE(v_candidate_effective_root->'case_resolution_states', '[]'::jsonb) ELSE '[]'::jsonb END,
    'canonical_preview_lines', COALESCE(v_lines_input, '[]'::jsonb),
    'payees', COALESCE(v_payees_input, '[]'::jsonb),
    'itemisation', CASE WHEN jsonb_typeof(v_candidate_effective_root->'itemisation') = 'array' THEN COALESCE(v_candidate_effective_root->'itemisation', '[]'::jsonb) ELSE '[]'::jsonb END,
    'hidden_recovery_template_lines', '[]'::jsonb,
    'hidden_recovery_template_line_count', 0,
    'blocked_items', '[]'::jsonb,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'paye_candidate', v_candidate_row,
    'non_paye_payee', NULL::jsonb
  );
END;
$function$;

-- pay_preview_build_context(date,date,uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_preview_build_context(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_preview_decisions_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
DECLARE
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
  v_effective_week_ending_cutoff date := COALESCE(p_week_ending_cutoff, DATE '9999-12-31');
  v_pay_week_start date;
  v_pay_eligibility_months_back integer := 6;
  v_pay_eligibility_weeks_ahead integer := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_last_candidate_id uuid := NULL::uuid;
  v_page_limit integer := 100;
  v_preview_decisions_root jsonb := '{}'::jsonb;
  v_preview_case_resolutions jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL::text;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_raw jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_raw jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_requested jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_requested jsonb := '[]'::jsonb;
  v_timesheet_rotation_scope_json jsonb := '[]'::jsonb;
  v_targeted_timesheet_input_count integer := 0;
  v_linked_timesheet_input_count integer := 0;
  v_distinct_timesheet_scope_input_count integer := 0;
  v_context_mode text := 'SUMMARY';
  v_effective_candidate_id uuid := p_candidate_id;
  v_effective_client_id uuid := p_client_id;
  v_full_compat_requested boolean := false;
  v_full_compat_downgraded boolean := false;
  v_source_build_internal_requested boolean := false;
  v_overpayment_sync_internal_requested boolean := false;
  v_internal_reconciliation_flags_requested boolean := false;
  v_internal_reconciliation_authorised boolean := false;
  v_source_build_authority_token text := NULL::text;
  v_current_overpayment_sync_authority_token text := NULL::text;
  v_lifecycle_mutation_context text := NULL::text;
  v_lifecycle_reconciliation_mode boolean := false;
  v_historic_metadata_allowed boolean := false;
  v_signed_finance_reconciliation boolean := false;
  v_exclude_lifecycle_ineligible_current_payability boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_scope_admission_authorised boolean := false;
  v_scope_admission_mode boolean := false;
  v_scope_admission_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('PREVIEW_PROGRESS');

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PREVIEW_BUILD_CONTEXT_PAY_DATE_REQUIRED')::text;
  END IF;

  IF to_regclass('public.settings_finance_windows') IS NULL THEN
    RAISE EXCEPTION 'settings_finance_windows missing';
  END IF;

  v_pay_week_start := public._pay_week_start_monday(p_pay_date);

  SELECT
    finance_window.vat_rate_pct,
    finance_window.erni_pct
  INTO
    v_vat_rate_pct,
    v_erni_pct
  FROM public.settings_finance_windows AS finance_window
  WHERE p_pay_date >= finance_window.date_from
    AND p_pay_date <= COALESCE(finance_window.date_to, 'infinity'::date)
  ORDER BY finance_window.date_from DESC, finance_window.id DESC
  LIMIT 1;

  IF v_vat_rate_pct IS NULL OR v_erni_pct IS NULL THEN
    RAISE EXCEPTION 'No finance window found for pay_date %', p_pay_date;
  END IF;

  SELECT
    settings_defaults.rail_provider_default,
    settings_defaults.rail_env_default,
    settings_defaults.rail_supports_scheduling,
    settings_defaults.rail_supports_name_check,
    settings_defaults.rail_supports_auto_execute,
    settings_defaults.default_schedule_umbrella_local,
    settings_defaults.default_schedule_paye_local,
    settings_defaults.funds_warning_hours_json,
    settings_defaults.pay_eligibility_months_back,
    settings_defaults.pay_eligibility_weeks_ahead
  INTO
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead
  FROM public.settings_defaults AS settings_defaults
  ORDER BY settings_defaults.id ASC
  LIMIT 1;

  IF v_rail_provider_default IS NULL OR v_rail_env_default IS NULL THEN
    RAISE EXCEPTION 'settings_defaults missing or not populated';
  END IF;

  v_pay_eligibility_months_back := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_months_back, 6), 120));
  v_pay_eligibility_weeks_ahead := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_weeks_ahead, 2), 52));
  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;
  v_need_name_check := COALESCE(v_rail_supports_name_check, false) AND UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV';
  v_requires_payee_map := UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV';

  v_preview_decisions_root := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  -- Internal continuous-scope admission is a bounded shortlist applied as an
  -- additional predicate to the normal broad-session eligibility authority.
  -- It deliberately does not use p_candidate_id, whose existing semantics are
  -- a hard explicit-filter boundary.
  v_scope_admission_authorised := LOWER(BTRIM(COALESCE(
    current_setting('cloudtms.banking_pay_scope_admission', true),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_preview_decisions_root ? 'scope_admission_candidate_ids' THEN
    IF NOT v_scope_admission_authorised THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_NOT_AUTHORISED'
        USING ERRCODE = '42501';
    END IF;

    IF jsonb_typeof(v_preview_decisions_root->'scope_admission_candidate_ids') <> 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_INPUT_INVALID'
        USING ERRCODE = '22023';
    END IF;

    v_scope_admission_mode := true;
    IF jsonb_array_length(v_preview_decisions_root->'scope_admission_candidate_ids') > 50 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_INPUT_TOO_LARGE'
        USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preview_decisions_root->'scope_admission_candidate_ids') AS admission_value(value)
      WHERE NULLIF(BTRIM(admission_value.value), '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_CANDIDATE_ID_INVALID'
        USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT admission_value.value::uuid ORDER BY admission_value.value::uuid), ARRAY[]::uuid[])
    INTO v_scope_admission_candidate_ids
    FROM jsonb_array_elements_text(v_preview_decisions_root->'scope_admission_candidate_ids') AS admission_value(value);
  END IF;

  v_preview_decisions_root := v_preview_decisions_root - 'scope_admission_candidate_ids';

  IF v_effective_candidate_id IS NULL
     AND NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'candidate_id', v_preview_decisions_root->>'candidateId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_effective_candidate_id := NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'candidate_id', v_preview_decisions_root->>'candidateId', '')), '')::uuid;
  END IF;

  IF v_effective_client_id IS NULL
     AND NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'client_id', v_preview_decisions_root->>'clientId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_effective_client_id := NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'client_id', v_preview_decisions_root->>'clientId', '')), '')::uuid;
  END IF;

  v_source_build_internal_requested :=
    LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'workbench_source_build_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'source_build_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_preview_decisions_root->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD';

  v_overpayment_sync_internal_requested :=
    LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'overpayment_sync_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_source_build_authority_token := NULLIF(BTRIM(COALESCE(
    v_preview_decisions_root->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_overpayment_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  v_internal_reconciliation_flags_requested :=
    v_source_build_internal_requested
    OR v_overpayment_sync_internal_requested
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'lifecycle_reconciliation_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'historic_metadata_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'signed_finance_reconciliation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'exclude_lifecycle_ineligible_current_payability', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'authoritative_timesheet_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_internal_reconciliation_authorised :=
    (
      v_source_build_internal_requested IS TRUE
      AND v_source_build_authority_token IS NOT NULL
      AND v_current_overpayment_sync_authority_token IS NOT NULL
      AND v_source_build_authority_token = v_current_overpayment_sync_authority_token
    )
    OR (
      v_overpayment_sync_internal_requested IS TRUE
      AND v_current_overpayment_sync_authority_token IS NOT NULL
    );

  IF v_internal_reconciliation_flags_requested IS TRUE
     AND v_internal_reconciliation_authorised IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_INTERNAL_AUTHORITY_REQUIRED'
      USING ERRCODE = '42501',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_BUILD_CONTEXT_INTERNAL_AUTHORITY_REQUIRED',
              'source_build_requested', v_source_build_internal_requested,
              'overpayment_sync_requested', v_overpayment_sync_internal_requested,
              'source_build_authority_present', v_source_build_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_overpayment_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_lifecycle_mutation_context := UPPER(BTRIM(COALESCE(
    v_preview_decisions_root->>'mutation_context',
    v_preview_decisions_root->>'lifecycle_mutation_context',
    v_preview_decisions_root->>'lifecycle_context',
    ''
  )));

  v_preview_decisions_root := v_preview_decisions_root
    - 'overpayment_sync_authority_token'
    - 'lifecycle_reconciliation_mode'
    - 'historic_metadata_allowed'
    - 'signed_finance_reconciliation'
    - 'exclude_lifecycle_ineligible_current_payability'
    - 'authoritative_timesheet_scope';

  v_context_mode := UPPER(NULLIF(BTRIM(COALESCE(
    v_preview_decisions_root->>'preview_context_mode',
    v_preview_decisions_root->>'context_mode',
    v_preview_decisions_root->>'mode',
    'SUMMARY'
  )), ''));

  IF v_context_mode NOT IN ('SUMMARY', 'PAGE', 'FULL_COMPAT') THEN
    v_context_mode := 'SUMMARY';
  END IF;

  v_full_compat_requested := v_context_mode = 'FULL_COMPAT';

  IF v_context_mode = 'FULL_COMPAT' AND v_effective_candidate_id IS NULL THEN
    v_context_mode := 'PAGE';
    v_full_compat_downgraded := true;
  END IF;

  IF COALESCE(v_preview_decisions_root->>'scope_limit', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_preview_decisions_root->>'scope_limit')::integer, 1), 100);
  ELSIF COALESCE(v_preview_decisions_root#>>'{scope_page,limit}', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_preview_decisions_root#>>'{scope_page,limit}')::integer, 1), 100);
  ELSE
    v_page_limit := 100;
  END IF;

  IF NULLIF(BTRIM(COALESCE(
       v_preview_decisions_root#>>'{scope_cursor,last_candidate_id}',
       v_preview_decisions_root#>>'{scope_cursor,candidate_id}',
       v_preview_decisions_root->>'last_candidate_id',
       v_preview_decisions_root->>'cursor_candidate_id',
       ''
     )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_candidate_id := NULLIF(BTRIM(COALESCE(
       v_preview_decisions_root#>>'{scope_cursor,last_candidate_id}',
       v_preview_decisions_root#>>'{scope_cursor,candidate_id}',
       v_preview_decisions_root->>'last_candidate_id',
       v_preview_decisions_root->>'cursor_candidate_id',
       ''
     )), '')::uuid;
  END IF;

  v_preview_case_resolutions := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'case_resolutions') = 'object' THEN COALESCE(v_preview_decisions_root->'case_resolutions', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_preview_decisions_root->>'refresh_scope_kind', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL::text;
  END IF;

  v_targeted_timesheet_ids_raw := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'array' THEN v_preview_decisions_root->'targeted_timesheet_ids'
    WHEN jsonb_typeof(v_preview_decisions_root->'targetedTimesheetIds') = 'array' THEN v_preview_decisions_root->'targetedTimesheetIds'
    WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'targeted_timesheet_ids')
    WHEN jsonb_typeof(v_preview_decisions_root->'targetedTimesheetIds') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'targetedTimesheetIds')
    ELSE '[]'::jsonb
  END;

  v_linked_timesheet_ids_raw := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'array' THEN v_preview_decisions_root->'linked_timesheet_ids'
    WHEN jsonb_typeof(v_preview_decisions_root->'linkedTimesheetIds') = 'array' THEN v_preview_decisions_root->'linkedTimesheetIds'
    WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'linked_timesheet_ids')
    WHEN jsonb_typeof(v_preview_decisions_root->'linkedTimesheetIds') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'linkedTimesheetIds')
    ELSE '[]'::jsonb
  END;

  v_targeted_timesheet_input_count := jsonb_array_length(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb));
  v_linked_timesheet_input_count := jsonb_array_length(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb));

  SELECT COUNT(DISTINCT NULLIF(BTRIM(scope_input.timesheet_id_text), ''))::integer
  INTO v_distinct_timesheet_scope_input_count
  FROM (
    SELECT targeted_scope_input.value AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb)) AS targeted_scope_input(value)
    UNION ALL
    SELECT linked_scope_input.value AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb)) AS linked_scope_input(value)
  ) AS scope_input
  WHERE NULLIF(BTRIM(scope_input.timesheet_id_text), '') IS NOT NULL;

  IF COALESCE(v_targeted_timesheet_input_count, 0) > 100
     OR COALESCE(v_linked_timesheet_input_count, 0) > 100
     OR COALESCE(v_distinct_timesheet_scope_input_count, 0) > 100 THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_TIMESHEET_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_BUILD_CONTEXT_TIMESHEET_SCOPE_TOO_LARGE',
              'context_mode', v_context_mode,
              'targeted_timesheet_count', COALESCE(v_targeted_timesheet_input_count, 0),
              'linked_timesheet_count', COALESCE(v_linked_timesheet_input_count, 0),
              'combined_timesheet_count', COALESCE(v_distinct_timesheet_scope_input_count, 0),
              'raw_combined_timesheet_count', COALESCE(v_targeted_timesheet_input_count, 0) + COALESCE(v_linked_timesheet_input_count, 0),
              'max_timesheet_scope_ids', 100,
              'row_backed_scope_required', true,
              'message', 'Caller-supplied timesheet scope arrays are capped at 100 for preview context. Use the row-backed workbench session scope instead.'
            )::text;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_array.value), '') AS targeted_timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb)) AS targeted_scope_array(value)
    WHERE NULLIF(BTRIM(targeted_scope_array.value), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_array.value), '') AS linked_timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb)) AS linked_scope_array(value)
    WHERE NULLIF(BTRIM(linked_scope_array.value), '') IS NOT NULL
  ) AS linked_scope_ids;


  v_targeted_timesheet_ids_requested := COALESCE(v_targeted_timesheet_ids, '[]'::jsonb);
  v_linked_timesheet_ids_requested := COALESCE(v_linked_timesheet_ids, '[]'::jsonb);

  WITH requested_scope_values AS (
    SELECT
      'TARGETED'::text AS scope_kind,
      requested_targeted_values.timesheet_id_text AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_requested, '[]'::jsonb)) AS requested_targeted_values(timesheet_id_text)

    UNION ALL

    SELECT
      'LINKED'::text AS scope_kind,
      requested_linked_values.timesheet_id_text AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_requested, '[]'::jsonb)) AS requested_linked_values(timesheet_id_text)
  ),
  requested_scope_ids AS (
    SELECT DISTINCT
      requested_scope_values.scope_kind,
      NULLIF(BTRIM(COALESCE(requested_scope_values.timesheet_id_text, '')), '')::uuid AS requested_timesheet_id
    FROM requested_scope_values
    WHERE NULLIF(BTRIM(COALESCE(requested_scope_values.timesheet_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  rotation_scope_rows AS (
    SELECT
      requested_scope_ids.scope_kind,
      requested_scope_ids.requested_timesheet_id,
      rotation_scope.requested_timesheet_id AS scope_requested_timesheet_id,
      rotation_scope.booking_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM requested_scope_ids
    JOIN public._pay_timesheet_rotation_scope(
      (
        SELECT COALESCE(
          array_agg(DISTINCT requested_scope_ids_for_array.requested_timesheet_id ORDER BY requested_scope_ids_for_array.requested_timesheet_id),
          ARRAY[]::uuid[]
        )
        FROM requested_scope_ids AS requested_scope_ids_for_array
      )
    ) AS rotation_scope
      ON rotation_scope.requested_timesheet_id = requested_scope_ids.requested_timesheet_id
  ),
  resolved_requested_scope AS (
    SELECT DISTINCT ON (rotation_scope_rows.scope_kind, rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.scope_kind,
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      rotation_scope_rows.booking_id,
      COALESCE(rotation_scope_rows.requested_is_canonical, false) AS requested_is_canonical
    FROM rotation_scope_rows
    ORDER BY
      rotation_scope_rows.scope_kind,
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  )
  SELECT
    COALESCE(
      jsonb_agg(DISTINCT resolved_requested_scope.canonical_timesheet_id::text ORDER BY resolved_requested_scope.canonical_timesheet_id::text)
        FILTER (WHERE resolved_requested_scope.scope_kind = 'TARGETED'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(DISTINCT resolved_requested_scope.canonical_timesheet_id::text ORDER BY resolved_requested_scope.canonical_timesheet_id::text)
        FILTER (WHERE resolved_requested_scope.scope_kind = 'LINKED'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'scope_kind', resolved_requested_scope.scope_kind,
          'requested_timesheet_id', resolved_requested_scope.requested_timesheet_id::text,
          'canonical_timesheet_id', resolved_requested_scope.canonical_timesheet_id::text,
          'booking_id', resolved_requested_scope.booking_id,
          'requested_is_canonical', resolved_requested_scope.requested_is_canonical
        )
        ORDER BY resolved_requested_scope.scope_kind, resolved_requested_scope.requested_timesheet_id
      ),
      '[]'::jsonb
    )
  INTO
    v_targeted_timesheet_ids,
    v_linked_timesheet_ids,
    v_timesheet_rotation_scope_json
  FROM resolved_requested_scope;

  v_lifecycle_reconciliation_mode := v_internal_reconciliation_authorised IS TRUE
    AND (
      v_overpayment_sync_internal_requested IS TRUE
      OR v_lifecycle_mutation_context IN (
        'TIMESHEET_AUTHORISE',
        'AUTHORISE_TIMESHEET',
        'TIMESHEET_UNAUTHORISE',
        'UNAUTHORISE_TIMESHEET',
        'TIMESHEET_ARCHIVE',
        'ARCHIVE_TIMESHEET',
        'TIMESHEET_UNARCHIVE',
        'UNARCHIVE_TIMESHEET'
      )
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'archive_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'unarchive_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    );

  v_signed_finance_reconciliation := v_internal_reconciliation_authorised IS TRUE
    AND (v_source_build_internal_requested IS TRUE OR v_overpayment_sync_internal_requested IS TRUE);
  v_authoritative_timesheet_scope := v_internal_reconciliation_authorised IS TRUE
    AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS';
  v_historic_metadata_allowed := v_signed_finance_reconciliation IS TRUE
    AND v_authoritative_timesheet_scope IS TRUE;
  v_exclude_lifecycle_ineligible_current_payability := v_lifecycle_reconciliation_mode IS TRUE;

  v_preview_decisions_root := v_preview_decisions_root || jsonb_build_object(
    'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
    'historic_metadata_allowed', v_historic_metadata_allowed,
    'signed_finance_reconciliation', v_signed_finance_reconciliation,
    'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
    'authoritative_timesheet_scope', v_authoritative_timesheet_scope
  );

  v_paye_guardrails := public.pay_paye_guardrails(
    p_pay_date => p_pay_date,
    p_ignore_pay_batch_id => NULL::uuid,
    p_actor_user_id => p_actor_user_id
  );

  IF v_context_mode IN ('PAGE', 'FULL_COMPAT') THEN
    /*
      Section 2 cutover: PAGE/FULL_COMPAT scope is keyset driven from
      public.candidates and uses EXISTS probes for eligibility.  This avoids
      constructing a full candidate-scope temp/list before applying LIMIT.
      SUMMARY mode deliberately skips this block and remains fixed-cost.
    */
    WITH targeted_scope_timesheet_ids AS (
      SELECT DISTINCT NULLIF(BTRIM(scope_timesheet_values.timesheet_id_text), '')::uuid AS timesheet_id
      FROM (
        SELECT jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids, '[]'::jsonb)) AS timesheet_id_text
        UNION ALL
        SELECT jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids, '[]'::jsonb)) AS timesheet_id_text
      ) AS scope_timesheet_values
      WHERE NULLIF(BTRIM(scope_timesheet_values.timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    page_rows AS (
      SELECT
        candidate_scope_row.id AS candidate_id,
        ROW_NUMBER() OVER (ORDER BY candidate_scope_row.id) AS page_ordinal
      FROM public.candidates AS candidate_scope_row
      WHERE (v_last_candidate_id IS NULL OR candidate_scope_row.id > v_last_candidate_id)
        AND (
          v_scope_admission_mode IS NOT TRUE
          OR candidate_scope_row.id = ANY(v_scope_admission_candidate_ids)
        )
        -- A selected candidate is a hard scope boundary, not merely another
        -- way for a candidate to qualify.  Without this outer predicate an
        -- unrelated candidate with an eligible finance case could enter a
        -- candidate-filtered workbench session through a later OR branch.
        AND (
          v_effective_candidate_id IS NULL
          OR candidate_scope_row.id = v_effective_candidate_id
        )
        AND (
          (
            v_effective_candidate_id IS NOT NULL
            AND candidate_scope_row.id = v_effective_candidate_id
          )
          OR EXISTS (
            SELECT 1
            FROM targeted_scope_timesheet_ids AS targeted_timesheet_scope
            JOIN public.timesheets AS targeted_timesheet_row
              ON targeted_timesheet_row.timesheet_id = targeted_timesheet_scope.timesheet_id
            LEFT JOIN public.timesheets_financials AS targeted_financials
              ON targeted_financials.timesheet_id = targeted_timesheet_row.timesheet_id
             AND targeted_financials.is_current = true
            LEFT JOIN public.contracts AS targeted_contract
              ON targeted_contract.id = targeted_timesheet_row.contract_id
            WHERE COALESCE(targeted_financials.candidate_id, targeted_contract.candidate_id) = candidate_scope_row.id
          )
          OR EXISTS (
            SELECT 1
            FROM public.timesheets_financials AS current_financials
            JOIN public.timesheets AS timesheet_row
              ON timesheet_row.timesheet_id = current_financials.timesheet_id
            LEFT JOIN public.timesheet_pay_state AS pay_state_row
              ON pay_state_row.timesheet_id = current_financials.timesheet_id
            WHERE current_financials.is_current = true
              AND current_financials.candidate_id = candidate_scope_row.id
              AND COALESCE(current_financials.pay_on_hold, false) = false
              AND COALESCE(current_financials.has_rate_issue, false) = false
              AND COALESCE(current_financials.has_pay_channel_issue, false) = false
              AND UPPER(COALESCE(current_financials.processing_status::text, '')) NOT IN ('UNASSIGNED', 'CLIENT_UNRESOLVED', 'RATE_MISSING', 'PAY_CHANNEL_MISSING')
              AND UPPER(COALESCE(candidate_scope_row.pay_method, '')) IN ('PAYE', 'UMBRELLA')
              AND (v_effective_client_id IS NULL OR current_financials.client_id = v_effective_client_id)
              AND (
                (
                  timesheet_row.authorised_at_server IS NOT NULL
                  AND timesheet_row.revoked_at IS NULL
                  AND timesheet_row.archived_at_utc IS NULL
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) >= v_eligibility_from_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_eligibility_to_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_effective_week_ending_cutoff
                )
                OR EXISTS (
                  SELECT 1
                  FROM public.timesheet_payment_overrides AS forced_override
                  WHERE forced_override.timesheet_id = current_financials.timesheet_id
                    AND forced_override.cleared_at_utc IS NULL
                    AND forced_override.consumed_at_utc IS NULL
                    AND forced_override.consumed_by_pay_batch_id IS NULL
                    AND UPPER(COALESCE(forced_override.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
                )
                OR (
                  pay_state_row.last_settled_snapshot_json IS NOT NULL
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) >= v_eligibility_from_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_effective_week_ending_cutoff
                )
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.v_finance_cases_register AS finance_case_row
            WHERE finance_case_row.candidate_id = candidate_scope_row.id
              AND finance_case_row.case_type IN (
                'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              AND UPPER(COALESCE(finance_case_row.status::text, '')) = 'ACTIVE'
              AND COALESCE(finance_case_row.outstanding_amount, 0) > 0
              AND UPPER(COALESCE(candidate_scope_row.pay_method, '')) IN ('PAYE', 'UMBRELLA')
              AND (v_effective_client_id IS NULL OR finance_case_row.client_id = v_effective_client_id)
              AND (
                (
                  finance_case_row.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
                  AND (
                    UPPER(COALESCE(finance_case_row.payout_status::text, '')) <> 'PAID'
                    OR finance_case_row.next_due_week_start IS NULL
                    OR finance_case_row.next_due_week_start <= v_pay_week_start
                  )
                )
                OR (
                  finance_case_row.case_type IN (
                    'OVERPAYMENT'::public.pay_finance_case_type_enum,
                    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
                  )
                  AND (
                    finance_case_row.next_due_week_start IS NULL
                    OR finance_case_row.next_due_week_start <= v_pay_week_start
                  )
                )
              )
          )
        )
      ORDER BY candidate_scope_row.id
      LIMIT (v_page_limit + 1)
    ),
    selected_rows AS (
      SELECT page_rows.candidate_id,
             page_rows.page_ordinal
      FROM page_rows
      WHERE page_rows.page_ordinal <= v_page_limit
    )
    SELECT
      COALESCE(jsonb_agg(to_jsonb(selected_rows.candidate_id::text) ORDER BY selected_rows.candidate_id), '[]'::jsonb),
      COUNT(*)::integer,
      EXISTS (SELECT 1 FROM page_rows WHERE page_rows.page_ordinal > v_page_limit),
      CASE
        WHEN EXISTS (SELECT 1 FROM page_rows WHERE page_rows.page_ordinal > v_page_limit) THEN
          jsonb_build_object(
            'last_candidate_id',
            (SELECT selected_cursor.candidate_id::text FROM selected_rows AS selected_cursor ORDER BY selected_cursor.candidate_id DESC LIMIT 1)
          )
        ELSE NULL::jsonb
      END
    INTO
      v_candidate_ids,
      v_page_count,
      v_has_more,
      v_next_cursor_json
    FROM selected_rows;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_date', p_pay_date::text,
    'pay_week_start', v_pay_week_start::text,
    'week_ending_cutoff_date', v_effective_week_ending_cutoff::text,
    'context_mode_requested', CASE WHEN v_full_compat_requested THEN 'FULL_COMPAT' ELSE v_context_mode END,
    'context_mode', v_context_mode,
    'full_compat_downgraded_to_page', v_full_compat_downgraded,
    'pre_draft', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  )
  || jsonb_build_object(
    'eligibility', jsonb_build_object(
      'today_uk', v_today_uk::text,
      'from_date', v_eligibility_from_date::text,
      'to_date', v_eligibility_to_date::text,
      'months_back', v_pay_eligibility_months_back,
      'weeks_ahead', v_pay_eligibility_weeks_ahead
    ),
    'filters', jsonb_build_object(
      'candidate_id', CASE WHEN v_effective_candidate_id IS NULL THEN NULL ELSE v_effective_candidate_id::text END,
      'client_id', CASE WHEN v_effective_client_id IS NULL THEN NULL ELSE v_effective_client_id::text END,
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
    ),
    'finance', jsonb_build_object(
      'vat_rate_pct', v_vat_rate_pct,
      'erni_pct', v_erni_pct
    )
  )
  || jsonb_build_object(
    'settings', jsonb_build_object(
      'rail', jsonb_build_object(
        'provider_default', v_rail_provider_default,
        'env_default', v_rail_env_default,
        'supports_scheduling', v_rail_supports_scheduling,
        'supports_name_check', v_rail_supports_name_check,
        'supports_auto_execute', v_rail_supports_auto_execute,
        'need_name_check', v_need_name_check,
        'requires_payee_map', v_requires_payee_map
      ),
      'schedule_defaults', jsonb_build_object(
        'umbrella_local', v_default_schedule_umbrella_local,
        'paye_local', v_default_schedule_paye_local
      ),
      'funds_warning_hours_json', COALESCE(v_funds_warning_hours_json, '[]'::jsonb)
    ),
    'paye_guardrails', COALESCE(v_paye_guardrails, '{}'::jsonb)
  )
  || jsonb_build_object(
    'candidate_ids', COALESCE(v_candidate_ids, '[]'::jsonb),
    'candidate_ids_are_page_only', true,
    'count_unknown', v_context_mode = 'SUMMARY',
    'scope_count_unknown', v_context_mode = 'SUMMARY',
    'known_total_count', NULL::integer,
    'candidate_count', NULL::integer,
    'page_count', COALESCE(v_page_count, 0),
    'limit', v_page_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor_json', v_next_cursor_json,
    'next_cursor', v_next_cursor_json
  )
  || jsonb_build_object(
    'preview_decisions_json', v_preview_decisions_root,
    'preview_case_resolutions', v_preview_case_resolutions,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids, '[]'::jsonb)
  )
  || jsonb_build_object(
    'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_requested, '[]'::jsonb),
    'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_requested, '[]'::jsonb),
    'timesheet_rotation_scope', COALESCE(v_timesheet_rotation_scope_json, '[]'::jsonb)
  )
  || jsonb_build_object(
    'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
    'historic_metadata_allowed', v_historic_metadata_allowed,
    'signed_finance_reconciliation', v_signed_finance_reconciliation,
    'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
    'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
    'internal_reconciliation_scope', jsonb_build_object(
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids, '[]'::jsonb),
      'timesheet_rotation_scope', COALESCE(v_timesheet_rotation_scope_json, '[]'::jsonb)
    )
  );
END;
$function$;

-- pay_preview_candidate_build_canonical_lines(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_canonical_lines(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;

  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_line_materialise_limit integer := 100;
  v_line_materialise_result jsonb := '{}'::jsonb;
  v_workbench_line_source_mode text := NULL::text;
  v_workbench_classifier_only boolean := false;
  v_source_build_mode boolean := false;
  v_source_build_context_required boolean := false;
  v_collect_called_inside_canonical boolean := false;
  v_collect_recollect_attempted boolean := false;
  v_collect_recollect_blocked boolean := false;
  v_canonical_started_at timestamptz := clock_timestamp();
  v_canonical_elapsed_ms numeric := 0;
  v_semantic_ready_observe_enabled boolean := false;
  v_semantic_ready_publication_enabled boolean := false;
  v_allocation_segment_failure jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  SELECT
    COALESCE(settings_row.banking_pay_workbench_semantic_ready_observe_v2_enabled,false),
    COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled,false)
  INTO v_semantic_ready_observe_enabled,v_semantic_ready_publication_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;


  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_source_build_context_required := COALESCE(v_source_build_mode, false);


  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_line_materialise_limit := LEAST(GREATEST(COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit')::integer, 1), 100);
  ELSE
    v_line_materialise_limit := 100;
  END IF;

  v_workbench_line_source_mode := UPPER(NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_line_source_mode',
    v_context_json->>'line_source_mode',
    v_context_json#>>'{line_work,source_mode}',
    v_context_json#>>'{workbench,line_source_mode}',
    ''
  )), ''));

  v_workbench_classifier_only := COALESCE(v_workbench_line_source_mode, '') IN (
    'CLASSIFY_ONLY',
    'CLASSIFIER_ONLY',
    'LINE_SOURCE_CLASSIFY_ONLY',
    'CANONICAL_CLASSIFY_ONLY'
  );

  IF v_workbench_session_id IS NOT NULL AND COALESCE(v_workbench_classifier_only, false) IS NOT TRUE AND COALESCE(v_source_build_mode, false) IS NOT TRUE THEN
    v_line_materialise_result := public.pay_workbench_preview_rows_materialise_chunk(
      p_session_id => v_workbench_session_id,
      p_candidate_id => v_candidate_id,
      p_cursor_json => COALESCE(
        v_context_json->'line_materialise_cursor',
        v_context_json->'line_work_cursor',
        v_context_json#>'{line_work,cursor}',
        NULL::jsonb
      ),
      p_limit => v_line_materialise_limit
    );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'session_id', v_workbench_session_id::text,
      'row_backed_line_work', true,
      'canonical_display_rows_written', true,
      'canonical_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'ready_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'blocked_preview_line_count', 0,
      'hidden_recovery_template_line_count', 0,
      'manual_adjustment_carry_forward_line_count', 0,
      'next_cursor', v_line_materialise_result->'next_cursor',
      'has_more', COALESCE(NULLIF(v_line_materialise_result->>'has_more', '')::boolean, false),
      'materialise_result', COALESCE(v_line_materialise_result, '{}'::jsonb)
    );
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    v_collect_recollect_attempted := true;

    IF COALESCE(v_source_build_context_required, false) = true THEN
      v_collect_recollect_blocked := true;
      RAISE EXCEPTION 'SOURCE_BUILD_CANONICAL_REQUIRES_PRECOLLECTED_CONTEXT'
        USING DETAIL = 'WORKBENCH_CANDIDATE_SOURCE_BUILD canonical mode refuses to call pay_preview_candidate_collect_scope implicitly. Call pay_preview_candidate_collect_scope first with the bounded source-build payload.';
    END IF;

    v_collect_called_inside_canonical := true;
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.finance_case_resolution_rollup') is null then
    perform public.pay_preview_candidate_build_finance_case_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.hidden_recovery_template_lines, pg_temp.manual_adjustment_carry_forward_lines, pg_temp.timesheet_allocation_component_lines, pg_temp.semantic_finance_case_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup;

  create temporary table canonical_timesheet_lines on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tb.ts_booking_id as booking_id,
          tb.ts_role,
          tb.ts_band,
          tcr.client_id,
          tcr.ts_client_name as client_name,
          tcr.ts_week_ending_date as week_ending_date,
          tcr.ts_pay_method as source_pay_method,
          tcr.umb_vat_chargeable,
          cp.cand_pay_method as candidate_pay_method,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          cp.payee_bank_hash,
          cp.payee_name_check_status,
          cp.payee_name_check_has_override,
          cp.payee_map_present,
          coalesce(cp.blockers, '[]'::jsonb) as payee_blockers,
          (jsonb_array_length(coalesce(cp.blockers, '[]'::jsonb)) > 0) as has_payee_readiness_block,
          (cp.is_ready_for_draft and coalesce(tcr.is_blocked, false) = false) as is_ready_for_draft,
          ato.override_id,
          ato.override_reason,
          ats.snooze_id,
          ats.snooze_until_date,
          ats.note as snooze_note,
          round(coalesce(tcr.payment_amount_ex_vat,0),2) as amount_ex_vat,
          round(coalesce(tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, 0),2) as amount_display,
          coalesce(tcr.is_blocked, false) as case_is_blocked,
          coalesce(tcr.case_resolution_summary_json, '{}'::jsonb) as case_resolution_summary_json,
          coalesce(expense_components.expense_aware_case_components_json, tcr.case_components_json, '[]'::jsonb) as case_components_json,
          coalesce(expense_components.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(expense_components.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(expense_components.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(expense_components.ready_expense_count, 0) as ready_expense_count,
          coalesce(expense_components.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(expense_components.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(expense_components.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(expense_components.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                'segment_key', nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                'segment_stable_key', coalesce(
                  nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                ),
                'date', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')),
                'client_name', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'client_name','')), ''), tcr.ts_client_name),
                'role', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'role','')), ''), tb.ts_role),
                'band', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'band','')), ''), tb.ts_band),
                'start', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')),
                'finish', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'end_hhmm','')), '')),
                'start_utc', nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), ''),
                'end_utc', nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), ''),
                'break_start', nullif(btrim(coalesce(cur_seg.seg->>'break_start','')), ''),
                'break_end', nullif(btrim(coalesce(cur_seg.seg->>'break_end','')), ''),
                'break_mins', coalesce(nullif(cur_seg.seg->>'break_mins','')::numeric, nullif(cur_seg.seg->>'break_minutes','')::numeric),
                'breaks', coalesce(cur_seg.seg->'breaks', '[]'::jsonb),
                'ref_num', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')),
                'nhsp_shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'external_row_key', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'external_row_key','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'external_row_key','')), '')
                ),
                'hr_request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'source_system', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'source_system','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'source_system','')), '')
                ),
                'latest_import_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'latest_import_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'latest_import_id','')), '')
                ),
                'pay_amount_ex_vat', round(coalesce(nullif(delta_seg.seg->>'delta_pay_ex_vat','')::numeric,0),2),
                'snooze_identity', jsonb_build_object(
                  'identity_type', 'TIMESHEET_SEGMENT',
                  'timesheet_id', tcr.timesheet_id::text,
                  'booking_id', tb.ts_booking_id,
                  'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                  ),
                  'source_ref', null
                ),
                'snooze_state', case
                  when ass.snooze_id is null then jsonb_build_object('state','NONE')
                  when ass.snooze_until_date is null then jsonb_build_object(
                    'state', 'INDEFINITE_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', null,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                  else jsonb_build_object(
                    'state', 'DATED_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', ass.snooze_until_date::text,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                end
              )
              order by
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), '')) nulls last,
                nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') nulls last
            )
            from jsonb_array_elements(coalesce(tcr.segment_deltas_json, '[]'::jsonb)) as delta_seg(seg)
            left join lateral (
              select seg.value as seg
              from jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) as seg(value)
              where coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'date','')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num','')), '')
                    ) is not distinct from coalesce(
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_id','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')
                    )
              order by 1
              limit 1
            ) cur_seg on true
            left join active_segment_snoozes ass
              on ass.candidate_id = tcr.candidate_id
             and (
               (ass.booking_id is not null and ass.booking_id = tb.ts_booking_id and ass.segment_stable_key is not distinct from coalesce(
                 nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
               ))
               or (ass.booking_id is null and ass.timesheet_id = tcr.timesheet_id and ass.segment_id is not distinct from nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''))
             )
          ), '[]'::jsonb) as segment_rows_json
        from timesheet_case_rollup_effective tcr
        join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
        join ts_baseline tb
          on tb.timesheet_id = tcr.timesheet_id
         and tb.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_overrides ato
          on ato.timesheet_id = tcr.timesheet_id
         and ato.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_snoozes ats
          on ats.candidate_id = tcr.candidate_id
         and (
           (ats.booking_id is not null and ats.booking_id = tb.ts_booking_id)
           or (ats.booking_id is null and ats.timesheet_id = tcr.timesheet_id)
         )
        left join lateral (
          with component_rows as (
            select
              component_element.value as component_json,
              component_element.ordinality::integer as component_ordinal,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_type', '')), '')) as component_key_type,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_value', component_element.value#>>'{source_basis_json,expense_code}', '')), '')) as expense_code,
              case
                when jsonb_typeof(component_element.value->'source_basis_json') = 'object'
                  then coalesce(component_element.value->'source_basis_json', '{}'::jsonb)
                else '{}'::jsonb
              end as source_basis_json,
              lower(coalesce(
                nullif(btrim(coalesce(component_element.value->>'source_basis_fingerprint', '')), ''),
                md5(coalesce(component_element.value->'source_basis_json', '{}'::jsonb)::text)
              )) as source_basis_fingerprint,
              round(coalesce(
                case when coalesce(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'target_pay_ex_vat')::numeric else null::numeric end,
                0::numeric
              ), 2) as component_amount_ex_vat
            from jsonb_array_elements(
              case
                when jsonb_typeof(tcr.case_components_json) = 'array' then coalesce(tcr.case_components_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) with ordinality as component_element(value, ordinality)
          ), expense_identity_rows as (
            select
              component_rows.*,
              (
                component_rows.component_key_type = 'EXPENSE_CODE'
                and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
              ) as is_expense_component,
              case
                when component_rows.component_key_type = 'EXPENSE_CODE'
                 and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                 and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
                then lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  component_rows.expense_code || ':' || component_rows.source_basis_fingerprint
                )
                else null::text
              end as expense_source_ref,
              case component_rows.expense_code
                when 'EXPENSES' then 'Expenses'
                when 'TRAVEL' then 'Travel'
                when 'ACCOMMODATION' then 'Accommodation'
                when 'OTHER' then 'Other'
                when 'MILEAGE' then 'Mileage'
                else null::text
              end as expense_label
            from component_rows
          ), enriched_rows as (
            select
              expense_identity_rows.*,
              exact_snooze.snooze_id as exact_snooze_id,
              exact_snooze.snooze_until_date as exact_snooze_until_date,
              exact_snooze.note as exact_snooze_note,
              exact_snooze.snooze_kind as exact_snooze_kind,
              stale_snooze.snooze_id as stale_snooze_id,
              stale_snooze.source_ref as stale_source_ref,
              stale_snooze.snooze_until_date as stale_snooze_until_date,
              stale_snooze.note as stale_snooze_note
            from expense_identity_rows
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.snooze_until_date,
                active_snooze.note,
                active_snooze.snooze_kind
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) = expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as exact_snooze on true
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.source_ref,
                active_snooze.snooze_until_date,
                active_snooze.note
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and exact_snooze.snooze_id is null
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.timesheet_id = tcr.timesheet_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) like lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  expense_identity_rows.expense_code || ':%'
                )
                and lower(active_snooze.source_ref) is distinct from expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as stale_snooze on true
          ), state_rows as (
            select
              enriched_rows.*,
              case
                when not enriched_rows.is_expense_component then 'NOT_EXPENSE'
                when enriched_rows.exact_snooze_id is not null and enriched_rows.exact_snooze_until_date is null then 'HIDDEN_INDEFINITE'
                when enriched_rows.exact_snooze_id is not null then 'BLOCKED_DATED'
                when enriched_rows.stale_snooze_id is not null then 'BLOCKED_STALE_IDENTITY'
                else 'READY'
              end as expense_presentation_state
            from enriched_rows
          )
          select
            coalesce(
              jsonb_agg(
                case
                  when state_rows.is_expense_component then
                    state_rows.component_json
                    || jsonb_build_object(
                      'expense_code', state_rows.expense_code,
                      'expense_label', state_rows.expense_label,
                      'expense_item_type', case when state_rows.expense_code = 'MILEAGE' then 'MILEAGE_DELTA' else 'EXPENSE_DELTA' end,
                      'source_ref', state_rows.expense_source_ref,
                      'source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_json', state_rows.source_basis_json
                    )
                    || jsonb_build_object(
                      'presentation_section', case
                        when state_rows.expense_presentation_state = 'READY' then 'READY_TO_PAY'
                        when state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY') then 'BLOCKED_FOR_PAY'
                        else 'INTERNAL_ONLY'
                      end,
                      'expense_presentation_state', state_rows.expense_presentation_state,
                      'draftable', (state_rows.expense_presentation_state = 'READY'),
                      'is_ready_for_draft', (state_rows.expense_presentation_state = 'READY'),
                      'is_excluded_from_allocation', (state_rows.expense_presentation_state <> 'READY'),
                      'selection_allowed', (state_rows.expense_presentation_state = 'READY'),
                      'expense_identity_stale', (state_rows.expense_presentation_state = 'BLOCKED_STALE_IDENTITY')
                    )
                    || jsonb_build_object(
                      'snooze_identity', jsonb_build_object(
                        'identity_type', 'TIMESHEET_EXPENSE',
                        'timesheet_id', tcr.timesheet_id::text,
                        'booking_id', tb.ts_booking_id,
                        'segment_id', null,
                        'segment_stable_key', null,
                        'source_ref', state_rows.expense_source_ref,
                        'expense_code', state_rows.expense_code,
                        'source_basis_fingerprint', state_rows.source_basis_fingerprint
                      ),
                      'snooze_state', case
                        when state_rows.exact_snooze_id is null and state_rows.stale_snooze_id is null
                          then jsonb_build_object('state', 'NONE')
                        when state_rows.exact_snooze_id is not null and state_rows.exact_snooze_until_date is null
                          then jsonb_build_object(
                            'state', 'INDEFINITE_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', null,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        when state_rows.exact_snooze_id is not null
                          then jsonb_build_object(
                            'state', 'DATED_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', state_rows.exact_snooze_until_date::text,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        else jsonb_build_object(
                          'state', 'STALE_SOURCE_IDENTITY',
                          'snooze_id', state_rows.stale_snooze_id::text,
                          'snooze_until_date', case when state_rows.stale_snooze_until_date is null then null else state_rows.stale_snooze_until_date::text end,
                          'note', state_rows.stale_snooze_note,
                          'stale_source_ref', state_rows.stale_source_ref,
                          'refresh_required', true
                        )
                      end
                    )
                  else state_rows.component_json
                end
                order by state_rows.component_ordinal
              ),
              '[]'::jsonb
            ) as expense_aware_case_components_json,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            ), 0), 2) as ready_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            ), 0), 2) as blocked_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            ), 0), 2) as hidden_expense_amount_ex_vat,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            )::integer as ready_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            )::integer as blocked_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            )::integer as hidden_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.exact_snooze_id is not null
            )::integer as active_expense_snooze_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.stale_snooze_id is not null
            )::integer as stale_expense_identity_count
          from state_rows
        ) as expense_components on true
        -- Protected presentation authority is built for every authoritative
        -- target. Public eligibility is applied only when final lines are
        -- emitted below, so zero-net and indefinitely snoozed targets remain
        -- attestable without becoming public economic rows.

  ;

  create temporary table timesheet_active_segment_snooze_meta on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          count(*)::int as active_segment_snooze_count,
          count(*) filter (where ass.snooze_until_date is not null)::int as active_segment_dated_snooze_count,
          count(*) filter (where ass.snooze_until_date is null)::int as active_segment_indefinite_snooze_count
        from canonical_timesheet_lines ctl
        join active_segment_snoozes ass
          on ass.candidate_id = ctl.candidate_id
         and (
           (ass.booking_id is not null and ctl.booking_id is not null and ass.booking_id = ctl.booking_id)
           or (ass.booking_id is null and ass.timesheet_id = ctl.timesheet_id)
         )
        group by ctl.candidate_id, ctl.timesheet_id, ctl.booking_id

  ;

  create temporary table canonical_timesheet_segment_rows on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          cur_seg_norm.seg_ord,
          cur_seg_norm.segment_id,
          cur_seg_norm.segment_key,
          cur_seg_norm.segment_stable_key,
          cur_seg_norm.segment_date,
          cur_seg_norm.client_name,
          cur_seg_norm.role,
          cur_seg_norm.band,
          cur_seg_norm.start_hhmm,
          cur_seg_norm.finish_hhmm,
          cur_seg_norm.start_utc,
          cur_seg_norm.end_utc,
          cur_seg_norm.break_start,
          cur_seg_norm.break_end,
          cur_seg_norm.break_mins,
          cur_seg_norm.breaks,
          coalesce(cur_seg_norm.ref_num, ss_match.ref_num) as ref_num,
          round(
            case
              when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
              when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
              else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
            end,
            2
          ) as presentation_amount_ex_vat,
          round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) as raw_delta_ex_vat,
          round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) as effective_delta_ex_vat,
          coalesce(ss_match.is_blocked, false) as status_is_blocked,
          coalesce(ss_match.is_do_not_pay, false) as status_is_do_not_pay,
          ass_match.snooze_id as segment_snooze_id,
          ass_match.snooze_until_date as segment_snooze_until_date,
          ass_match.note as segment_snooze_note,
          ass_match.snooze_kind as segment_snooze_kind,
          case
            when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
            when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_blocked, false) = true
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'BLOCKED_VISIBLE'
            when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'READY'
            else 'IGNORED'
          end as presentation_segment_state,
          jsonb_build_object(
            'timesheet_id', ctl.timesheet_id::text,
            'booking_id', ctl.booking_id,
            'segment_id', cur_seg_norm.segment_id,
            'segment_key', cur_seg_norm.segment_key,
            'segment_stable_key', cur_seg_norm.segment_stable_key,
            'date', cur_seg_norm.segment_date,
            'client_name', cur_seg_norm.client_name,
            'role', cur_seg_norm.role,
            'band', cur_seg_norm.band,
            'start', cur_seg_norm.start_hhmm,
            'finish', cur_seg_norm.finish_hhmm,
            'start_utc', cur_seg_norm.start_utc,
            'end_utc', cur_seg_norm.end_utc,
            'break_start', cur_seg_norm.break_start,
            'break_end', cur_seg_norm.break_end,
            'break_mins', cur_seg_norm.break_mins,
            'breaks', cur_seg_norm.breaks,
            'ref_num', coalesce(cur_seg_norm.ref_num, ss_match.ref_num),
            'nhsp_shift_id', cur_seg_norm.nhsp_shift_id,
            'shift_id', cur_seg_norm.shift_id,
            'external_row_key', cur_seg_norm.external_row_key,
            'hr_request_id', cur_seg_norm.hr_request_id,
            'request_id', cur_seg_norm.request_id,
            'source_system', cur_seg_norm.source_system,
            'latest_import_id', cur_seg_norm.latest_import_id,
            'pay_amount_ex_vat', round(
              case
                when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
                when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
                else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
              end,
              2
            ),
            'raw_delta_ex_vat', round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2),
            'effective_delta_ex_vat', round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2),
            'is_blocked', coalesce(ss_match.is_blocked, false),
            'is_do_not_pay', coalesce(ss_match.is_do_not_pay, false),
            'presentation_segment_state', case
              when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
              when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_blocked, false) = true
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'BLOCKED_VISIBLE'
              when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'READY'
              else 'IGNORED'
            end,
            'is_ready_segment', (
              ass_match.snooze_id is null
              and coalesce(ss_match.is_blocked, false) = false
              and coalesce(ss_match.is_do_not_pay, false) = false
              and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              and round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
            ),
            'is_blocked_visible_segment', (
              (ass_match.snooze_id is not null and ass_match.snooze_until_date is not null)
              or (
                coalesce(ss_match.is_blocked, false) = true
                and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              )
              or coalesce(ss_match.is_do_not_pay, false) = true
            ),
            'is_hidden_indefinite_segment', (ass_match.snooze_id is not null and ass_match.snooze_until_date is null),
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', ctl.timesheet_id::text,
              'booking_id', ctl.booking_id,
              'segment_id', cur_seg_norm.segment_id,
              'segment_stable_key', cur_seg_norm.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', case
              when ass_match.snooze_id is null then jsonb_build_object('state', 'NONE')
              when ass_match.snooze_until_date is null then jsonb_build_object(
                'state', 'INDEFINITE_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', null,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
              else jsonb_build_object(
                'state', 'DATED_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', ass_match.snooze_until_date::text,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
            end
          ) as segment_base_json
        from canonical_timesheet_lines ctl
        join ts_baseline tb
          on tb.timesheet_id = ctl.timesheet_id
         and tb.candidate_id = ctl.candidate_id
        cross join lateral jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg_json, seg_ord)
        cross join lateral (
          select
            cur_seg.seg_ord,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), '') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), '') as segment_key,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_stable_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '')
            ) as segment_stable_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), '') as segment_date,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'client_name','')), ''), ctl.client_name) as client_name,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'role','')), ''), ctl.ts_role) as role,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'band','')), ''), ctl.ts_band) as band,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'start_hhmm','')), '')) as start_hhmm,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'end_hhmm','')), '')) as finish_hhmm,
            nullif(btrim(coalesce(cur_seg.seg_json->>'start_utc','')), '') as start_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'end_utc','')), '') as end_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_start','')), '') as break_start,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_end','')), '') as break_end,
            coalesce(nullif(cur_seg.seg_json->>'break_mins','')::numeric, nullif(cur_seg.seg_json->>'break_minutes','')::numeric) as break_mins,
            case when jsonb_typeof(cur_seg.seg_json->'breaks') = 'array' then cur_seg.seg_json->'breaks' else '[]'::jsonb end as breaks,
            nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '') as ref_num,
            nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '') as nhsp_shift_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'shift_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '')
            ) as shift_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'external_row_key','')), '') as external_row_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '') as hr_request_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'request_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '')
            ) as request_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'source_system','')), '') as source_system,
            nullif(btrim(coalesce(cur_seg.seg_json->>'latest_import_id','')), '') as latest_import_id
        ) cur_seg_norm
        left join lateral (
          select
            ss.segment_id,
            ss.segment_stable_key,
            ss.ref_num,
            ss.work_date,
            ss.delta_pay_ex_vat,
            ss.eff_delta_ex,
            ss.is_blocked,
            ss.is_do_not_pay
          from segment_status ss
          where ss.candidate_id = ctl.candidate_id
            and ss.timesheet_id = ctl.timesheet_id
            and (
              (cur_seg_norm.segment_stable_key is not null and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and ss.segment_id is not distinct from cur_seg_norm.segment_id
              )
            )
          order by
            case
              when cur_seg_norm.segment_stable_key is not null
               and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key
              then 0 else 1
            end,
            case
              when cur_seg_norm.segment_id is not null
               and ss.segment_id is not distinct from cur_seg_norm.segment_id
              then 0 else 1
            end,
            ss.segment_stable_key nulls last,
            ss.segment_id nulls last
          limit 1
        ) ss_match on true
        left join lateral (
          select
            round(sum(coalesce(ttre.preview_component_amount_ex_vat, 0)), 2) as preview_component_amount_ex_vat,
            round(sum(coalesce(ttre.ready_preview_amount_ex_vat, ttre.preview_component_amount_ex_vat, 0)), 2) as ready_preview_amount_ex_vat,
            bool_or(coalesce(ttre.requires_resolution, false)) as requires_resolution,
            bool_or(coalesce(ttre.is_actionable_resolution_row, false)) as is_actionable_resolution_row
          from transient_timesheet_component_review_rows_effective ttre
          where ttre.candidate_id = ctl.candidate_id
            and ttre.timesheet_id = ctl.timesheet_id
            and ttre.component_key_type in ('TS_DAY','TS_TOTAL')
            and (
              (
                cur_seg_norm.segment_stable_key is not null
                and coalesce(
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'work_date','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'ref_num','')), '')
                ) is not distinct from cur_seg_norm.segment_stable_key
              )
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), '') is not distinct from cur_seg_norm.segment_id
              )
            )
        ) ttre_match on true
        left join lateral (
          select
            ass.snooze_id,
            ass.snooze_until_date,
            ass.note,
            ass.snooze_kind,
            ass.segment_id,
            ass.segment_stable_key
          from active_segment_snoozes ass
          where ass.candidate_id = ctl.candidate_id
            and (
              (
                ass.booking_id is not null
                and ctl.booking_id is not null
                and ass.booking_id = ctl.booking_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
              or (
                ass.booking_id is null
                and ass.timesheet_id = ctl.timesheet_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
            )
          order by
            case when ass.segment_stable_key is not null then 0 else 1 end,
            ass.snooze_id
          limit 1
        ) ass_match on true
        where (
          ass_match.snooze_id is not null
          or coalesce(ss_match.is_blocked, false) = true
          or coalesce(ss_match.is_do_not_pay, false) = true
          or round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
          or round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) <> 0
        )

  ;

  create temporary table canonical_timesheet_segment_rollup on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          coalesce(tasm.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(tasm.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(tasm.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          count(*) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE'))::int as total_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'READY')::int as ready_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE')::int as blocked_visible_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE')::int as hidden_indefinite_segment_count,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'READY' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as ready_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'BLOCKED_VISIBLE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as blocked_visible_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'READY'),
            '[]'::jsonb
          ) as ready_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE'),
            '[]'::jsonb
          ) as blocked_visible_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE')),
            '[]'::jsonb
          ) as visible_segment_rows_json
        from canonical_timesheet_lines ctl
        left join timesheet_active_segment_snooze_meta tasm
          on tasm.candidate_id = ctl.candidate_id
         and tasm.timesheet_id = ctl.timesheet_id
         and tasm.booking_id is not distinct from ctl.booking_id
        left join canonical_timesheet_segment_rows ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
        group by
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.snooze_id,
          tasm.active_segment_snooze_count,
          tasm.active_segment_dated_snooze_count,
          tasm.active_segment_indefinite_snooze_count

  ;

  create temporary table canonical_timesheet_presentation_seed on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.ts_role,
          ctl.ts_band,
          ctl.client_id,
          ctl.client_name,
          ctl.week_ending_date,
          ctl.source_pay_method,
          ctl.umb_vat_chargeable,
          ctl.candidate_pay_method,
          ctl.cand_tms_ref,
          ctl.cand_display_name,
          ctl.payee_entity_kind,
          ctl.payee_entity_id,
          ctl.payee_bank_hash,
          ctl.payee_name_check_status,
          ctl.payee_name_check_has_override,
          ctl.payee_map_present,
          coalesce(ctl.payee_blockers, '[]'::jsonb) as payee_blockers,
          coalesce(ctl.has_payee_readiness_block, false) as has_payee_readiness_block,
          ctl.is_ready_for_draft,
          ctl.override_id,
          ctl.override_reason,
          ctl.snooze_id,
          ctl.snooze_until_date,
          ctl.snooze_note,
          ctl.amount_ex_vat,
          ctl.amount_display,
          ctl.case_is_blocked,
          ctl.case_resolution_summary_json,
          ctl.case_components_json,
          coalesce(ctl.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(ctl.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(ctl.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(ctl.ready_expense_count, 0) as ready_expense_count,
          coalesce(ctl.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(ctl.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(ctl.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(ctl.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce(ctsr.total_segment_count, 0) as total_segment_count,
          coalesce(ctsr.ready_segment_count, 0) as ready_segment_count,
          coalesce(ctsr.blocked_visible_segment_count, 0) as blocked_visible_segment_count,
          coalesce(ctsr.hidden_indefinite_segment_count, 0) as hidden_indefinite_segment_count,
          coalesce(ctsr.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(ctsr.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(ctsr.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          coalesce(ctsr.ready_segment_amount_ex_vat, 0) as ready_segment_amount_ex_vat,
          coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0) as blocked_visible_segment_amount_ex_vat,
          coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(ctsr.ready_segment_rows_json, '[]'::jsonb) as ready_segment_rows_json,
          coalesce(ctsr.blocked_visible_segment_rows_json, '[]'::jsonb) as blocked_visible_segment_rows_json,
          coalesce(ctsr.visible_segment_rows_json, '[]'::jsonb) as visible_segment_rows_json,
          (
            coalesce(ctsr.total_segment_count, 0) > 0
            and (
              lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or (
                coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
              )
            )
          ) as resolved_segment_rows_replace_source_total,
          case
            when coalesce(ctsr.total_segment_count, 0) > 0
             and (
               lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or (
                 coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                 and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
               )
             ) then round(coalesce(ctl.ready_expense_amount_ex_vat, 0), 2)
            else round(
              coalesce(ctl.amount_ex_vat, 0)
              - coalesce(ctsr.ready_segment_amount_ex_vat, 0)
              - coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0)
              - coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0)
              - coalesce(ctl.blocked_expense_amount_ex_vat, 0)
              - coalesce(ctl.hidden_expense_amount_ex_vat, 0),
              2
            )
          end as non_segment_amount_ex_vat,
          (ctl.snooze_id is not null) as has_active_timesheet_snooze,
          (coalesce(ctsr.active_segment_snooze_count, 0) > 0) as has_active_segment_snoozes
        from canonical_timesheet_lines ctl
        left join canonical_timesheet_segment_rollup ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
         and ctsr.booking_id is not distinct from ctl.booking_id

  ;

  create temporary table canonical_timesheet_presentation_state on commit drop as
        select
          ctps.*,
          coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) as case_needs_resolution,
          exists (
            select 1
            from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as case_component(value)
            where coalesce(nullif(case_component.value->>'requires_resolution','')::boolean, false) = true
              and coalesce(nullif(case_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
          ) as has_actionable_resolution_component,
          round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) as ready_section_amount_ex_vat,
          round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2) as blocked_section_amount_ex_vat,
          round(
            coalesce(
              nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
              0::numeric
            ),
            2
          ) as case_resolution_section_amount_ex_vat,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2),
                  v_vat_rate_pct,
                  ctps.umb_vat_chargeable
                )->>'inc')::numeric
              else round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2)
            end,
            2
          ) as ready_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2), v_vat_rate_pct, ctps.umb_vat_chargeable)->>'inc')::numeric
              else round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2)
            end,
            2
          ) as blocked_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(
                round(
                  coalesce(
                    nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                    0::numeric
                  ),
                  2
                ),
                v_vat_rate_pct,
                ctps.umb_vat_chargeable
              )->>'inc')::numeric
              else round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              )
            end,
            2
          ) as case_resolution_section_amount_display,
          (
            round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
            or coalesce(ctps.ready_segment_count, 0) > 0
          ) as has_ready_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.is_ready_for_draft = false
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
            and (
              ctps.case_is_blocked = false
              or coalesce(ctps.has_payee_readiness_block, false) = true
            )
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
          ) as has_non_resolution_readiness_block,
          (
            ctps.has_active_timesheet_snooze = true
            or coalesce(ctps.blocked_visible_segment_count, 0) > 0
            or coalesce(ctps.blocked_expense_count, 0) > 0
            or (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_blocked_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = true
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = true
            and (
              round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              ) <> 0
              or exists (
                select 1
                from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as actionable_component(value)
                where coalesce(nullif(actionable_component.value->>'requires_resolution','')::boolean, false) = true
                  and coalesce(nullif(actionable_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
              )
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) = 0
            and not (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_case_resolution_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_ready,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_blocked
        from canonical_timesheet_presentation_seed ctps

  ;

  create temporary table canonical_timesheet_presentation_rows on commit drop as
        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'amount_display', ctpp.ready_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', ctpp.is_ready_for_draft,
              'segment_rows', ctpp.ready_segment_rows_json,
              'segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb))
            )
            || jsonb_build_object(
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'section_amount_display', ctpp.ready_section_amount_display,
              'section_segment_rows', ctpp.ready_segment_rows_json,
              'section_segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)),
              'section_non_segment_amount_ex_vat', ctpp.non_segment_amount_ex_vat,
              'resolved_segment_rows_replace_source_total', coalesce(ctpp.resolved_segment_rows_replace_source_total, false)
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.is_partially_ready then 'PARTIAL_READY_TO_PAY'
                when ctpp.hidden_indefinite_segment_count > 0 then 'READY_WITH_HIDDEN_INDEFINITE_SEGMENTS'
                else 'READY_TO_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_ready and ctpp.blocked_visible_segment_count > 0 and ctpp.blocked_expense_count > 0 then 'Some segments and expenses are blocked'
                when ctpp.is_partially_ready and ctpp.blocked_expense_count > 0 then 'Some expenses are blocked'
                when ctpp.is_partially_ready then 'Some segments are blocked'
                when ctpp.hidden_indefinite_segment_count > 0 and ctpp.hidden_expense_count > 0 then 'Some segments and expenses are snoozed indefinitely'
                when ctpp.hidden_expense_count > 0 then 'Some expenses are snoozed indefinitely'
                when ctpp.hidden_indefinite_segment_count > 0 then 'Some segments are snoozed indefinitely'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.ready_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_active_timesheet_snooze = false
          and ctpp.case_is_blocked = false
          and ctpp.has_ready_presentation = true
          and ctpp.is_ready_for_draft = true
          and round(coalesce(ctpp.amount_ex_vat,0),2) <> 0
        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', (ctpp.timesheet_id::text || ':03:case'),
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'amount_display', ctpp.case_resolution_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', case
                when jsonb_typeof(ctpp.case_resolution_summary_json->'blocked_reason_codes') = 'array'
                then coalesce(ctpp.case_resolution_summary_json->'blocked_reason_codes', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', false,
              'segment_rows', '[]'::jsonb,
              'segment_count', 0
            )
            || jsonb_build_object(
              'presentation_section', 'CASES_RESOLUTIONS',
              'presentation_role', 'PARENT',
              'presentation_line_id', (ctpp.timesheet_id::text || ':03:case'),
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', false,
              'is_partially_blocked', false,
              'section_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'section_amount_display', ctpp.case_resolution_section_amount_display,
              'section_segment_rows', '[]'::jsonb,
              'section_segment_count', 0,
              'section_non_segment_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
              'presentation_advisory_text', 'Resolve this case before draft'
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.case_resolution_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_case_resolution_presentation = true


        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'payee_entity_kind', ctpp.payee_entity_kind,
              'payee_entity_id', case when ctpp.payee_entity_id is null then null else ctpp.payee_entity_id::text end,
              'payee_bank_hash', ctpp.payee_bank_hash,
              'bank_details_hash', ctpp.payee_bank_hash,
              'name_check_status', ctpp.payee_name_check_status,
              'name_check_has_override', ctpp.payee_name_check_has_override,
              'payee_map_present', ctpp.payee_map_present,
              'blockers', coalesce(ctpp.payee_blockers, '[]'::jsonb),
              'payee_blockers', coalesce(ctpp.payee_blockers, '[]'::jsonb)
            )
            || jsonb_build_object(
              'amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', (
                coalesce(ctpp.payee_blockers, '[]'::jsonb)
                ||
                (case
                  when ctpp.has_active_timesheet_snooze = true then jsonb_build_array('BLOCKED_DATED_SNOOZE')
                  else '[]'::jsonb
                end)
              ),
              'is_excluded_from_allocation', (ctpp.has_active_timesheet_snooze = true),
              'is_ready_for_draft', case
                when ctpp.has_active_timesheet_snooze = true then ctpp.is_ready_for_draft
                else false
              end,
              'segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end
            )
            || jsonb_build_object(
              'presentation_section', 'BLOCKED_FOR_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'section_amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'section_segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'section_segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end,
              'section_non_segment_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.non_segment_amount_ex_vat
                else coalesce(ctpp.blocked_expense_amount_ex_vat, 0)
              end
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.has_active_timesheet_snooze = true then 'WHOLE_TIMESHEET_SNOOZED'
                when ctpp.is_partially_blocked then 'PARTIAL_BLOCKED_FOR_PAY'
                else 'BLOCKED_FOR_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_blocked and ctpp.ready_segment_count > 0 and ctpp.ready_expense_count > 0 then 'Some segments and expenses are ready to pay'
                when ctpp.is_partially_blocked and ctpp.ready_expense_count > 0 then 'Some expenses are ready to pay'
                when ctpp.is_partially_blocked then 'Some segments are ready to pay'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          case
            when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
            else ctpp.blocked_section_amount_ex_vat
          end as amount_ex_vat,
          (ctpp.has_active_timesheet_snooze = true) as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_blocked_presentation = true
          and round(coalesce(ctpp.amount_ex_vat,0),2) <> 0
          and not (ctpp.snooze_id is not null and ctpp.snooze_until_date is null)
          and (
            ctpp.has_active_timesheet_snooze = true
            or ctpp.has_non_resolution_readiness_block = true
            or ctpp.blocked_visible_segment_count > 0
            or ctpp.blocked_expense_count > 0
          )


  ;

  -- An aggregate ordinary timesheet parent is presentation evidence, not an
  -- independently payable economic component.  Negative parents without an
  -- actionable case were previously left under READY_TO_PAY and only made
  -- non-selectable later by the strict line contract.  That was structurally
  -- safe but visually false: a negative payment cannot be paid.  Move the
  -- single parent row to Blocked while retaining its exact amount and lineage.
  UPDATE canonical_timesheet_presentation_rows AS presentation_row
  SET
    line_json = presentation_row.line_json
      || pg_catalog.jsonb_build_object(
        'presentation_section', 'BLOCKED_FOR_PAY',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NEGATIVE_ORDINARY_PRESENTATION_ONLY',
        'presentation_advisory_text', 'Negative ordinary entitlement cannot be paid directly',
        'blocked_reason_codes', COALESCE(presentation_row.line_json->'blocked_reason_codes', '[]'::jsonb)
          || pg_catalog.jsonb_build_array('NEGATIVE_ORDINARY_PRESENTATION_ONLY'),
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true
      ),
    is_excluded_from_allocation = true
  WHERE pg_catalog.upper(COALESCE(presentation_row.line_json->>'line_type', '')) = 'TIMESHEET_PAYMENT'
    AND pg_catalog.upper(COALESCE(presentation_row.line_json->>'presentation_role', '')) = 'PARENT'
    AND pg_catalog.upper(COALESCE(presentation_row.line_json->>'presentation_section', '')) = 'READY_TO_PAY'
    AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
      presentation_row.line_json->'case_resolution_summary'->>'case_needs_resolution',
      'false'
    ))) NOT IN ('true','t','1','yes','y','on')
    AND pg_catalog.round(COALESCE(presentation_row.amount_ex_vat, 0), 2) < 0;

  create temporary table finance_case_lines on commit drop as
        select
          fcrr.candidate_id,
          fcrr.finance_case_id,
          fcrr.client_id,
          fcrr.client_name,
          fcrr.candidate_pay_method,
          fcrr.cand_tms_ref,
          fcrr.cand_display_name,
          fcrr.payee_entity_kind,
          fcrr.payee_entity_id,
          fcrr.candidate_ready_for_draft,
          fcrr.case_type,
          fcrr.taxability,
          fcrr.routing_kind,
          fcrr.destination_label,
          fcrr.beneficiary_name,
          fcrr.masked_bank_account,
          fcrr.payee_bank_hash,
          fcrr.adjustment_comment,
          fcrr.linked_timesheet_id,
          fcrr.linked_shift_date,
          fcrr.next_due_week_start,
          fcrr.active_snooze_id,
          fcrr.active_snooze_kind,
          fcrr.active_snooze_until_date,
          fcrr.active_snooze_note,
          round(coalesce(fcrr.due_amount_ex_vat, 0), 2) as due_amount_ex_vat,
          coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) as nominal_due_amount_ex_vat,
          round(coalesce(finance_case_baseline.outstanding_amount, 0), 2)
            as recovery_source_outstanding_ex_vat,
          round(coalesce(finance_case_baseline.active_reserved_amount, 0), 2)
            as recovery_active_reserved_ex_vat,
          finance_due_meta.recovery_created_at_utc as semantic_recovery_sort_at_utc,
          fcrr.is_blocked as case_is_blocked,
          (
            coalesce(fcrr.blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is null then jsonb_build_array('BLOCKED_INDEFINITE_SNOOZE')
              when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then jsonb_build_array('BLOCKED_DATED_SNOOZE')
              else '[]'::jsonb
            end)
            ||
            (case
              when round(coalesce(fcrr.due_amount_ex_vat, 0), 2) = 0
               and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0
               and fcrr.case_type in (
                 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                 'OVERPAYMENT'::public.pay_finance_case_type_enum,
                 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
               ) then jsonb_build_array('NO_PAY_HEADROOM')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          fcrr.case_resolution_summary_json,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'finance_resolution_clearability_state', 'NOT_REQUIRED'))) as finance_resolution_clearability_state,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_family', ''))) as current_saved_resolution_family,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_owner_kind', 'NONE'))) as current_saved_resolution_owner_kind,
          nullif(btrim(coalesce(fcrr.case_resolution_summary_json->>'finance_resolution_clear_block_reason', '')), '') as finance_resolution_clear_block_reason,
          case
            when coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_linked_timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (fcrr.case_resolution_summary_json->>'current_saved_resolution_linked_timesheet_id')::uuid
            else null::uuid
          end as current_saved_resolution_linked_timesheet_id,
          fcrr.taxable_manual_debt_resolution_json,
          fcrr.case_components_json,
          fcrr.oneoff_bank_details_present,
          fcrr.is_candidate_directed_oneoff_payout,
          fcrr.appears_on_umbrella_remittance,
          fcrr.generates_candidate_payment_advice,
          fcrr.snooze_allowed,
          fcrr.lifecycle_status_display,
          component_identity.component_count,
          component_identity.finance_component_id,
          component_identity.component_key_type,
          component_identity.component_key_value,
          component_identity.component_classification,
          component_identity.component_source_basis_json,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'LOAN_PAYOUT'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'PAYMENT_ADVANCE_REPAYMENT'
            when fcrr.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrr.case_type = 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrr.case_type::text
          end as line_type,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'Loan payment'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'Loan repayment'
            when fcrr.case_type = 'OVERPAYMENT' then 'Overpayment recovery'
            when fcrr.case_type = 'UNDERPAYMENT' then 'Underpayment payment'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual credit adjustment payment'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            else replace(fcrr.case_type::text, '_', ' ')
          end as item_type_label,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'PAYMENT'
            when fcrr.case_type = 'UNDERPAYMENT' then 'PAYMENT'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'PAYMENT'
            else 'DEDUCTION'
          end as item_direction,
          case
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
             and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID'
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'UNDERPAYMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'UNDERPAYMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            else 'NONE'
          end as paye_treatment,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            when fcrr.case_type = 'UNDERPAYMENT' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            else round(-coalesce(fcrr.due_amount_ex_vat,0),2)
          end as signed_amount_ex_vat,
          case
            when fcrr.active_snooze_id is not null then 'BLOCKED_FOR_PAY'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASES_RESOLUTIONS'
            when fcrr.is_blocked then 'BLOCKED_FOR_PAY'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 then 'BLOCKED_FOR_PAY'
            else 'READY_TO_PAY'
          end as readiness_state,
          case
            when fcrr.active_snooze_id is not null then 'BLOCKED_FOR_PAY'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASES_RESOLUTIONS'
            when fcrr.is_blocked then 'BLOCKED_FOR_PAY'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 then 'BLOCKED_FOR_PAY'
            else 'READY_TO_PAY'
          end as presentation_section,
          case
            when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
            when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then 'DATED_SNOOZE'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASE_RESOLUTION_REQUIRED'
            when fcrr.is_blocked then 'CASE_BLOCKED'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0 then 'NO_PAY_HEADROOM'
            else 'READY_TO_PAY'
          end as presentation_reason,
          lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_resolution_satisfied_now', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') as is_case_resolution_satisfied,
          lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') as case_needs_resolution_now,
          (
            fcrr.is_blocked = false
            and fcrr.active_snooze_id is null
            and lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) not in ('true', 't', '1', 'yes', 'y', 'on')
            and round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
          ) as draftable
        from finance_case_resolution_rollup fcrr
        left join finance_case_baseline_scope finance_case_baseline
          on finance_case_baseline.finance_case_id = fcrr.finance_case_id
         and finance_case_baseline.candidate_id = fcrr.candidate_id
        left join lateral (
          select
            round(coalesce(max(fcrrb.nominal_due_amount), 0), 2) as nominal_due_amount_ex_vat,
            min(fcrrb.created_at) as recovery_created_at_utc
          from finance_case_recovery_rows_base fcrrb
          where fcrrb.finance_case_id = fcrr.finance_case_id
        ) finance_due_meta on true
        left join lateral (
          with component_rows as (
            select
              component_element.value as component_json,
              component_element.ordinality
            from jsonb_array_elements(
              case
                when jsonb_typeof(coalesce(fcrr.case_components_json, '[]'::jsonb)) = 'array' then coalesce(fcrr.case_components_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) with ordinality as component_element(value, ordinality)
            where component_element.value is not null
              and jsonb_typeof(component_element.value) = 'object'
          )
          select
            count(*)::integer as component_count,
            case
              when count(*) = 1
               and (array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'finance_component_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then ((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'finance_component_id')::uuid
              else null::uuid
            end as finance_component_id,
            coalesce(
              case when count(*) = 1 then upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'component_key_type', '')), '')) else null::text end,
              case when fcrr.linked_timesheet_id is not null then 'TS_TOTAL' else 'ADJUSTMENT_CODE' end
            ) as component_key_type,
            coalesce(
              case when count(*) = 1 then nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'component_key_value', '')), '') else null::text end,
              case when fcrr.linked_timesheet_id is not null then 'TOTAL' else fcrr.finance_case_id::text end
            ) as component_key_value,
            case
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'TAXABLE_CHANNEL_SENSITIVE'
                then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
                then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'NET_PAY_FIXED_RECOVERY'
                then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              else null::public.pay_finance_component_classification_enum
            end as component_classification,
            case
              when count(*) = 1 and jsonb_typeof((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->'source_basis_json') = 'object'
                then (array_agg(component_rows.component_json order by component_rows.ordinality))[1]->'source_basis_json'
              else '{}'::jsonb
            end as component_source_basis_json
          from component_rows
        ) component_identity on true
        where (
          round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
          or fcrr.active_snooze_id is not null
          or coalesce(fcrr.is_blocked, false) = true
          or lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or (
            round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0
            and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0
            and fcrr.case_type in (
              'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
              'OVERPAYMENT'::public.pay_finance_case_type_enum,
              'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
            )
          )
        )


  ;

  create temporary table hidden_recovery_template_lines on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          case
            when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
            when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrrb.case_type::text
          end as recovery_family,
          ('advance:' || fcrrb.finance_case_id::text) as source_ref,
          row_number() over (
            partition by fcrrb.candidate_id,
                         case
                           when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                           when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                           when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                           else fcrrb.case_type::text
                         end
            order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
          )::integer as sort_order,
          jsonb_strip_nulls(
            jsonb_build_object(
              'template_state', 'HIDDEN_ZERO_TAKE',
              'candidate_id', fcrrb.candidate_id::text,
              'finance_case_id', fcrrb.finance_case_id::text,
              'recovery_family', case
                when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                else fcrrb.case_type::text
              end,
              'case_type', fcrrb.case_type::text,
              'source_ref', ('advance:' || fcrrb.finance_case_id::text),
              'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'umbrella_id', case when c.umbrella_id is null then null else c.umbrella_id::text end,
              'paye_treatment', case
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'PAYMENT_ADVANCE'
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                else 'NONE'
              end,
              'finance_component_id', null,
              'frozen_component_key_type', 'CASE_TOTAL',
              'frozen_component_key_value', 'TOTAL',
              'frozen_component_classification', null,
              'frozen_component_snapshot_json', null,
              'frozen_source_basis_json', jsonb_strip_nulls(
                jsonb_build_object(
                  'case_type', fcrrb.case_type::text,
                  'recovery_family', case
                    when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                    when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                    when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                    else fcrrb.case_type::text
                  end,
                  'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'taxability', case when fcbs.taxability is null then null else fcbs.taxability::text end,
                  'routing_kind', case when fcbs.routing_kind is null then null else fcbs.routing_kind::text end,
                  'nominal_due_amount_ex_vat', round(coalesce(fcrrb.nominal_due_amount, 0), 2),
                  'current_due_amount_ex_vat', round(coalesce(fcrr.due_amount_ex_vat, 0), 2),
                  'outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
                  'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
                  'active_reserved_amount', round(coalesce(fcbs.active_reserved_amount, 0), 2),
                  'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
                  'take_home_floor_override', fcrrb.take_home_floor_override,
                  'default_take_home_floor', fcrrb.default_take_home_floor,
                  'run_earnings_headroom_ex', round(coalesce(fcrrb.run_earnings_headroom_ex, 0), 2),
                  'run_take_home_before', round(coalesce(fcrrb.run_take_home_before, 0), 2),
                  'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
                  'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
                  'sort_order', row_number() over (
                    partition by fcrrb.candidate_id,
                                 case
                                   when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                                   when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                                   when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                                   else fcrrb.case_type::text
                                 end
                    order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
                  )
                )
              ),
              'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_source_amount', round(coalesce(fcbs.outstanding_amount, fcrrb.nominal_due_amount, 0), 2),
              'frozen_outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
              'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
              'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
              'take_home_floor_override', fcrrb.take_home_floor_override,
              'default_take_home_floor', fcrrb.default_take_home_floor,
              'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
              'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
              'sort_order', row_number() over (
                partition by fcrrb.candidate_id,
                             case
                               when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                               when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                               when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                               else fcrrb.case_type::text
                             end
                order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
              ),
              'frozen_resolution_mode', coalesce(
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'mode', '')), '')
              ),
              'frozen_resolution_payload_json', case
                when fcrr.taxable_manual_debt_resolution_json is not null then fcrr.taxable_manual_debt_resolution_json
                when jsonb_typeof(fcrr.case_resolution_summary_json->'non_bucket_resolution') = 'object' then fcrr.case_resolution_summary_json->'non_bucket_resolution'
                else null
              end,
              'frozen_resolution_result_json', fcrr.case_resolution_summary_json,
              'case_components_json', coalesce(fcrr.case_components_json, '[]'::jsonb),
              'case_resolution_summary_json', coalesce(fcrr.case_resolution_summary_json, '{}'::jsonb),
              'taxable_manual_debt_resolution_json', fcrr.taxable_manual_debt_resolution_json,
              'eligibility_state', jsonb_build_object(
                'candidate_ready_for_draft', coalesce(fcrr.candidate_ready_for_draft, false),
                'case_is_blocked', coalesce(fcrr.is_blocked, false),
                'has_active_dated_snooze', (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
              )
            )
          ) as template_json
        from finance_case_recovery_rows_base fcrrb
        join finance_case_baseline_scope fcbs
          on fcbs.finance_case_id = fcrrb.finance_case_id
        join finance_case_resolution_rollup fcrr
          on fcrr.finance_case_id = fcrrb.finance_case_id
        left join public.candidates c
          on c.id = fcrrb.candidate_id
        where fcrrb.case_type in (
            'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
          and round(coalesce(fcrrb.nominal_due_amount, 0), 2) > 0
          and round(coalesce(fcrr.due_amount_ex_vat, 0), 2) = 0
          and coalesce(fcrr.candidate_ready_for_draft, false) = true
          and coalesce(fcrr.is_blocked, false) = false
          and not (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
          and (
            fcrrb.case_type <> 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
            or upper(coalesce(fcrr.lifecycle_status_display, '')) = 'PAID'
          )
  ;



  CREATE TEMPORARY TABLE IF NOT EXISTS manual_adjustment_carry_forward_scope (
    id uuid,
    source_pay_batch_id uuid,
    source_pay_batch_item_id uuid,
    source_pay_bank_transfer_id uuid,
    source_pay_batch_candidate_id uuid,
    source_correction_request_id uuid,
    source_correction_work_item_id uuid,
    candidate_id uuid,
    umbrella_id uuid,
    client_id uuid,
    timesheet_id uuid,
    pay_channel text,
    adjustment_direction text,
    amount_ex_vat numeric,
    amount_vat numeric,
    amount_inc_vat numeric,
    amount_basis text,
    paye_treatment text,
    tax_treatment_json jsonb,
    description text,
    reason text,
    source_ref text,
    source_operation_source_key text,
    source_snapshot_json jsonb,
    status text,
    target_pay_batch_id uuid,
    target_pay_batch_item_id uuid,
    target_operation_source_key text,
    created_at_utc timestamptz,
    updated_at_utc timestamptz,
    reserved_at_utc timestamptz,
    consumed_at_utc timestamptz,
    released_at_utc timestamptz,
    cancelled_at_utc timestamptz,
    status_reason text,
    source_batch_ref text
  ) ON COMMIT DROP;

  create temporary table manual_adjustment_carry_forward_lines on commit drop as
        select
          carry_forward_scope.candidate_id,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          carry_forward_scope.id as manual_adjustment_carry_forward_id,
          carry_forward_scope.source_pay_batch_id,
          carry_forward_scope.source_pay_batch_item_id,
          carry_forward_scope.source_pay_bank_transfer_id,
          carry_forward_scope.source_pay_batch_candidate_id,
          carry_forward_scope.source_correction_request_id,
          carry_forward_scope.source_correction_work_item_id,
          carry_forward_scope.umbrella_id,
          carry_forward_scope.client_id,
          carry_forward_scope.timesheet_id,
          upper(btrim(coalesce(carry_forward_scope.pay_channel, ''))) as pay_channel,
          carry_forward_scope.adjustment_direction,
          round(coalesce(carry_forward_scope.amount_ex_vat, 0), 2)::numeric as amount_ex_vat,
          round(coalesce(carry_forward_scope.amount_vat, 0), 2)::numeric as amount_vat,
          round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2)::numeric as amount_inc_vat,
          carry_forward_scope.amount_basis,
          carry_forward_scope.paye_treatment,
          coalesce(carry_forward_scope.tax_treatment_json, '{}'::jsonb) as tax_treatment_json,
          nullif(btrim(coalesce(carry_forward_scope.description, '')), '') as original_description,
          carry_forward_scope.reason,
          carry_forward_scope.source_ref,
          carry_forward_scope.source_operation_source_key,
          coalesce(carry_forward_scope.source_snapshot_json, '{}'::jsonb) as source_snapshot_json,
          carry_forward_scope.status,
          carry_forward_scope.target_pay_batch_id,
          carry_forward_scope.target_pay_batch_item_id,
          carry_forward_scope.target_operation_source_key,
          coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text) as source_batch_ref,
          ('carry_forward:' || carry_forward_scope.id::text) as preview_row_id,
          ('carry_forward:' || carry_forward_scope.id::text) as operation_source_key,
          ('Carried forward from cancelled payment '
            || coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text)
            || ': '
            || coalesce(nullif(btrim(carry_forward_scope.description), ''), nullif(btrim(carry_forward_scope.reason), ''), 'Manual adjustment')
          ) as display_description
        from manual_adjustment_carry_forward_scope as carry_forward_scope
        join cand_payee cp
          on cp.candidate_id = carry_forward_scope.candidate_id
        where carry_forward_scope.candidate_id = p_candidate_id
          and upper(btrim(coalesce(carry_forward_scope.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2) <> 0
  ;

  -- Aggregate timesheet rows are presentation parents only.  Exact economic
  -- allocation authority already exists in case_components_json; promote each
  -- positive, resolved component as its own top-level Ready-to-Pay row instead
  -- of making the aggregate parent selectable.  This preserves Policy X's
  -- existing TS_DAY / expense / correction identities and prevents a recovery
  -- row from becoming the only selectable row for a candidate.
  create temporary table timesheet_allocation_component_lines on commit drop as
        with component_rows as (
          select
            ctl.*,
            component.value as component_json,
            upper(nullif(btrim(coalesce(component.value->>'component_key_type','')), '')) as component_key_type,
            nullif(btrim(coalesce(component.value->>'component_key_value','')), '') as component_key_value,
            round(case
              when exists (
                select 1
                from canonical_timesheet_segment_rows resolved_segment
                where resolved_segment.candidate_id=ctl.candidate_id
                  and resolved_segment.timesheet_id=ctl.timesheet_id
              )
              and (
                lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate','false'))) in ('true','t','1','yes','y','on')
                or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied','false'))) in ('true','t','1','yes','y','on')
                or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active','false'))) in ('true','t','1','yes','y','on')
                or (
                  coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count','') ~ '^[0-9]+$'
                  and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
                )
              ) then coalesce(
                nullif(component.value->>'ready_preview_amount_ex_vat','')::numeric,
                nullif(component.value->>'target_pay_ex_vat','')::numeric,
                nullif(component.value->>'preview_component_amount_ex_vat','')::numeric
              )
              else coalesce(
                nullif(component.value->>'component_amount_ex_vat','')::numeric,
                nullif(component.value->>'authoritative_outstanding_ex_vat','')::numeric,
                nullif(component.value->>'preview_due_amount_ex_vat','')::numeric,
                nullif(component.value->>'ready_preview_amount_ex_vat','')::numeric,
                nullif(component.value->>'target_pay_ex_vat','')::numeric,
                nullif(component.value->>'preview_component_amount_ex_vat','')::numeric,
                0::numeric
              )
            end, 2) as component_amount_ex_vat,
            coalesce(nullif(btrim(coalesce(component.value->>'component_fingerprint','')), ''), md5(component.value::text)) as component_fingerprint,
            coalesce(
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_stable_key}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_id}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_key}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,work_date}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,date}','')), ''),
              nullif(btrim(coalesce(component.value->>'component_key_value','')), '')
            ) as stable_component_identity,
            lower(btrim(coalesce(component.value->>'requires_resolution','false'))) in ('true','t','1','yes','y','on') as requires_resolution
          from canonical_timesheet_lines ctl
          cross join lateral jsonb_array_elements(
            case when jsonb_typeof(ctl.case_components_json)='array'
              then ctl.case_components_json else '[]'::jsonb end
          ) component(value)
        ), eligible_components as (
          select
            component_rows.*,
            coalesce(segment_match.segment_match_count, 0)::integer as segment_match_count,
            segment_match.segment_json as matched_segment_json,
            count(*) over (
              partition by component_rows.candidate_id,
                component_rows.timesheet_id,
                component_rows.component_key_type,
                component_rows.stable_component_identity
            ) as stable_component_identity_count,
            case
              when component_rows.component_key_type='TS_DAY' then
                component_rows.timesheet_id::text || ':segment:' || component_rows.stable_component_identity
                || case
                  when count(*) over (
                    partition by component_rows.candidate_id,
                      component_rows.timesheet_id,
                      component_rows.component_key_type,
                      component_rows.stable_component_identity
                  ) > 1 then ':bucket:' || lower(coalesce(
                    nullif(btrim(coalesce(component_rows.component_json->>'bucket_code','')), ''),
                    nullif(btrim(coalesce(component_rows.component_json#>>'{source_basis_json,bucket_code}','')), ''),
                    '~'
                  ))
                  else ''
                end
              when component_rows.component_key_type='EXPENSE_CODE' then
                component_rows.timesheet_id::text || ':component:expense:' || component_rows.component_fingerprint
              when lower(coalesce(component_rows.component_json->>'source_family_key','')) like 'correction%'
              then 'correction-chain:'
                || coalesce(
                  nullif(btrim(coalesce(component_rows.component_json->>'source_family_key','')), ''),
                  component_rows.timesheet_id::text
                )
                || ':' || lower(component_rows.component_key_type)
                || ':' || component_rows.component_key_value
              else component_rows.timesheet_id::text
                || ':component:' || lower(component_rows.component_key_type)
                || ':' || component_rows.component_fingerprint
            end as allocation_line_key
          from component_rows
          left join lateral (
            select
              count(*)::integer as segment_match_count,
              (jsonb_agg(
                matched_segment.segment_json
                order by matched_segment.match_rank,
                         matched_segment.seg_ord,
                         matched_segment.segment_stable_key
              )->0) as segment_json
            from (
              select
                segment_row.seg_ord,
                segment_row.segment_stable_key,
                segment_row.segment_base_json as segment_json,
                case
                  when nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                   and segment_row.segment_stable_key is not distinct from component_rows.stable_component_identity
                    then 10
                  else 20
                end as match_rank
              from canonical_timesheet_segment_rows as segment_row
              where component_rows.component_key_type = 'TS_DAY'
                and segment_row.candidate_id = component_rows.candidate_id
                and segment_row.timesheet_id = component_rows.timesheet_id
                and segment_row.presentation_segment_state = 'READY'
                and (
                  (
                    nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                    and segment_row.segment_stable_key is not distinct from component_rows.stable_component_identity
                  )
                  or (
                    not exists (
                      select 1
                      from canonical_timesheet_segment_rows as exact_segment
                      where exact_segment.candidate_id = component_rows.candidate_id
                        and exact_segment.timesheet_id = component_rows.timesheet_id
                        and exact_segment.presentation_segment_state = 'READY'
                        and nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                        and exact_segment.segment_stable_key is not distinct from component_rows.stable_component_identity
                    )
                    and segment_row.segment_date::text is not distinct from component_rows.component_key_value
                  )
                )
            ) as matched_segment
          ) as segment_match on true
          where component_rows.component_key_type in ('TS_DAY','EXPENSE_CODE','ADDITIONAL_CODE','ADJUSTMENT_CODE')
            and component_rows.component_key_value is not null
            and component_rows.stable_component_identity is not null
            and (
              component_rows.component_key_type <> 'TS_DAY'
              or not exists (
                select 1
                from canonical_timesheet_segment_rows as exact_non_ready_segment
                where exact_non_ready_segment.candidate_id = component_rows.candidate_id
                  and exact_non_ready_segment.timesheet_id = component_rows.timesheet_id
                  and exact_non_ready_segment.segment_stable_key is not distinct from component_rows.stable_component_identity
                  and exact_non_ready_segment.presentation_segment_state in ('BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE')
              )
            )
            and component_rows.component_amount_ex_vat > 0
            and component_rows.requires_resolution is not true
            and component_rows.is_ready_for_draft is true
            and component_rows.case_is_blocked is false
            and component_rows.snooze_id is null
            and coalesce(jsonb_array_length(component_rows.payee_blockers),0)=0
        )
        select
          eligible_components.candidate_id,
          jsonb_strip_nulls(
            jsonb_build_object(
              'preview_row_id', eligible_components.allocation_line_key,
              'line_id', eligible_components.allocation_line_key,
              'line_key', eligible_components.allocation_line_key,
              'row_key', eligible_components.allocation_line_key,
              'source_ref', eligible_components.allocation_line_key,
              'parent_line_key', eligible_components.timesheet_id::text,
              'candidate_id', eligible_components.candidate_id::text,
              'tms_ref', eligible_components.cand_tms_ref,
              'display_name', eligible_components.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'case_type', 'TIMESHEET_PAYMENT',
              'case_key', 'timesheet:' || eligible_components.timesheet_id::text
            )
            || jsonb_build_object(
              'finance_case_id', null,
              'finance_component_id', nullif(eligible_components.component_json->>'finance_component_id',''),
              'timesheet_id', eligible_components.timesheet_id::text,
              'real_business_timesheet_id', eligible_components.timesheet_id::text,
              'booking_id', eligible_components.booking_id,
              'client_id', case when eligible_components.client_id is null then null else eligible_components.client_id::text end,
              'client_name', eligible_components.client_name,
              'week_ending_date', case when eligible_components.week_ending_date is null then null else eligible_components.week_ending_date::text end,
              'linked_shift_date', case when eligible_components.component_key_type='TS_DAY' then eligible_components.component_key_value else null end,
              'component_key_type', eligible_components.component_key_type,
              'component_key_value', eligible_components.component_key_value,
              'key_type', eligible_components.component_key_type,
              'key_value', eligible_components.component_key_value,
              'economic_key', jsonb_build_object(
                'timesheet_id', eligible_components.timesheet_id::text,
                'key_type', eligible_components.component_key_type,
                'key_value', eligible_components.component_key_value
              ),
              'component_fingerprint', eligible_components.component_fingerprint,
              'bucket_code', nullif(btrim(coalesce(eligible_components.component_json->>'bucket_code','')), ''),
              'physical_bucket_key', eligible_components.component_json->'physical_bucket_key',
              'physical_bucket_digest', eligible_components.component_json->'physical_bucket_digest',
              'source_family_key', eligible_components.component_json->'source_family_key',
              'source_basis_fingerprint', eligible_components.component_json->'source_basis_fingerprint',
              'source_basis_json', eligible_components.component_json->'source_basis_json',
              'source_units', eligible_components.component_json->'source_units',
              'source_rate', eligible_components.component_json->'source_rate',
              'source_charge_rate', eligible_components.component_json->'source_charge_rate',
              'source_pay_ex_vat', eligible_components.component_json->'source_pay_ex_vat',
              'source_charge_ex_vat', eligible_components.component_json->'source_charge_ex_vat',
              'target_rate', eligible_components.component_json->'target_rate',
              'target_pay_ex_vat', eligible_components.component_json->'target_pay_ex_vat',
              'source_pay_method', eligible_components.component_json->'source_pay_method',
              'current_target_pay_method', eligible_components.component_json->'current_target_pay_method',
              'segment_id', eligible_components.matched_segment_json->'segment_id',
              'segment_key', eligible_components.matched_segment_json->'segment_key',
              'segment_stable_key', eligible_components.matched_segment_json->'segment_stable_key',
              'date', eligible_components.matched_segment_json->'date',
              'work_date', coalesce(
                eligible_components.matched_segment_json->'work_date',
                eligible_components.matched_segment_json->'date'
              ),
              'role', eligible_components.matched_segment_json->'role',
              'band', eligible_components.matched_segment_json->'band',
              'start', eligible_components.matched_segment_json->'start',
              'finish', eligible_components.matched_segment_json->'finish',
              'start_utc', eligible_components.matched_segment_json->'start_utc',
              'end_utc', eligible_components.matched_segment_json->'end_utc',
              'break_start', eligible_components.matched_segment_json->'break_start',
              'break_end', eligible_components.matched_segment_json->'break_end',
              'break_mins', eligible_components.matched_segment_json->'break_mins',
              'breaks', eligible_components.matched_segment_json->'breaks',
              'ref_num', eligible_components.matched_segment_json->'ref_num'
            )
            || jsonb_build_object(
              'case_resolution_summary', coalesce(eligible_components.case_resolution_summary_json, '{}'::jsonb),
              'case_resolution_summary_json', coalesce(eligible_components.case_resolution_summary_json, '{}'::jsonb),
              'has_resolved_rate', eligible_components.case_resolution_summary_json->'has_resolved_rate',
              'resolved_rate_applied', eligible_components.case_resolution_summary_json->'resolved_rate_applied',
              'resolved_rate_active', eligible_components.case_resolution_summary_json->'resolved_rate_active',
              'case_resolution_satisfied_now', eligible_components.case_resolution_summary_json->'case_resolution_satisfied_now',
              'resolved_rate_family', eligible_components.case_resolution_summary_json->'resolved_rate_family',
              'resolved_rate_component_count', eligible_components.case_resolution_summary_json->'resolved_rate_component_count',
              'resolved_rate_candidate_id', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_candidate_id',
                eligible_components.case_resolution_summary_json->'resolution_candidate_id'
              ),
              'resolved_rate_timesheet_id', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_timesheet_id',
                eligible_components.case_resolution_summary_json->'resolution_timesheet_id'
              ),
              'resolved_rate_case_key', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_case_key',
                eligible_components.case_resolution_summary_json->'resolution_case_key'
              ),
              'resolution_candidate_id', eligible_components.case_resolution_summary_json->'resolution_candidate_id',
              'resolution_timesheet_id', eligible_components.case_resolution_summary_json->'resolution_timesheet_id',
              'resolution_case_key', eligible_components.case_resolution_summary_json->'resolution_case_key',
              'case_resolution_id', eligible_components.case_resolution_summary_json->'case_resolution_id',
              'case_resolution_ids', eligible_components.case_resolution_summary_json->'case_resolution_ids',
              'resolution_identity_keys', eligible_components.case_resolution_summary_json->'resolution_identity_keys',
              'resolved_rate_clear_payload_json', eligible_components.case_resolution_summary_json->'resolved_rate_clear_payload_json',
              'case_components', jsonb_build_array(eligible_components.component_json),
              'amount_ex_vat', eligible_components.component_amount_ex_vat,
              'amount_display', eligible_components.component_amount_ex_vat,
              'item_direction', 'PAYMENT',
              'pay_channel', eligible_components.candidate_pay_method,
              'paye_treatment', case when eligible_components.candidate_pay_method='PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'payee_entity_kind', eligible_components.payee_entity_kind,
              'payee_entity_id', case when eligible_components.payee_entity_id is null then null else eligible_components.payee_entity_id::text end,
              'payee_bank_hash', eligible_components.payee_bank_hash,
              'bank_details_hash', eligible_components.payee_bank_hash,
              'name_check_status', eligible_components.payee_name_check_status,
              'name_check_has_override', eligible_components.payee_name_check_has_override,
              'payee_map_present', eligible_components.payee_map_present,
              'blockers', eligible_components.payee_blockers,
              'payee_blockers', eligible_components.payee_blockers,
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'ALLOCATION_COMPONENT',
              'presentation_parent_line_id', eligible_components.timesheet_id::text,
              'readiness_state', 'READY_TO_PAY',
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', true,
              'draftable', true,
              'selection_allowed', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ) as line_json,
          eligible_components.candidate_pay_method as pay_channel,
          case when eligible_components.candidate_pay_method='PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          eligible_components.component_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation,
          eligible_components.component_key_type,
          eligible_components.segment_match_count
        from eligible_components

  ;

  if exists (
    select 1
    from timesheet_allocation_component_lines as component_line
    where component_line.component_key_type = 'TS_DAY'
      and component_line.segment_match_count = 0
  ) then
    SELECT pg_catalog.jsonb_build_object(
      'code', 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_MISSING',
      'candidate_id', component_line.candidate_id,
      'timesheet_id', component_line.timesheet_id,
      'component_key_type', component_line.component_key_type,
      'component_key_value', component_line.key_value,
      'source_basis_fingerprint', component_line.line_json->>'source_basis_fingerprint',
      'match_count', component_line.segment_match_count
    )
    INTO v_allocation_segment_failure
    FROM timesheet_allocation_component_lines AS component_line
    WHERE component_line.component_key_type = 'TS_DAY'
      AND component_line.segment_match_count = 0
    ORDER BY component_line.candidate_id, component_line.timesheet_id,
      component_line.key_value, component_line.line_key
    LIMIT 1;

    raise exception 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_MISSING'
      using errcode = 'P0001', detail = v_allocation_segment_failure::text;
  end if;

  if exists (
    select 1
    from timesheet_allocation_component_lines as component_line
    where component_line.component_key_type = 'TS_DAY'
      and component_line.segment_match_count > 1
  ) then
    SELECT pg_catalog.jsonb_build_object(
      'code', 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_AMBIGUOUS',
      'candidate_id', component_line.candidate_id,
      'timesheet_id', component_line.timesheet_id,
      'component_key_type', component_line.component_key_type,
      'component_key_value', component_line.key_value,
      'source_basis_fingerprint', component_line.line_json->>'source_basis_fingerprint',
      'match_count', component_line.segment_match_count
    )
    INTO v_allocation_segment_failure
    FROM timesheet_allocation_component_lines AS component_line
    WHERE component_line.component_key_type = 'TS_DAY'
      AND component_line.segment_match_count > 1
    ORDER BY component_line.candidate_id, component_line.timesheet_id,
      component_line.key_value, component_line.line_key
    LIMIT 1;

    raise exception 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_AMBIGUOUS'
      using errcode = 'P0001', detail = v_allocation_segment_failure::text;
  end if;

  -- The finance resolver's run-level headroom predates semantic allocation
  -- children and therefore used aggregate presentation parents.  V3 replaces
  -- that display-only basis with exact positive keyed allocation authority.
  -- Nominal debt is never changed: only the amount recoverable in this pay run
  -- is capped, in the existing oldest-case order, to same-candidate headroom.
  create temporary table semantic_finance_case_lines on commit drop as
        with allocation_headroom as (
          select
            component_line.candidate_id,
            round(coalesce(sum(component_line.amount_ex_vat),0),2) as ordinary_positive_headroom
          from timesheet_allocation_component_lines component_line
          where component_line.amount_ex_vat > 0
          group by component_line.candidate_id
        ), ranked as (
          select
            finance_line.*,
            coalesce(headroom.ordinary_positive_headroom,0)::numeric as ordinary_positive_headroom,
            coalesce(
              sum(
                case
                  when finance_line.draftable is true
                   and finance_line.item_direction='DEDUCTION'
                   and finance_line.signed_amount_ex_vat < 0
                  then abs(finance_line.signed_amount_ex_vat)
                  else 0
                end
              ) over (
                partition by finance_line.candidate_id
                order by finance_line.semantic_recovery_sort_at_utc nulls last,
                         finance_line.finance_case_id
                rows between unbounded preceding and 1 preceding
              ),
              0
            )::numeric as prior_semantic_recovery_amount,
            (
              finance_line.draftable is true
              and finance_line.item_direction='DEDUCTION'
              and finance_line.signed_amount_ex_vat < 0
            ) as is_semantic_recovery
          from finance_case_lines finance_line
          left join allocation_headroom headroom
            on headroom.candidate_id=finance_line.candidate_id
        ), capped as (
          select
            ranked.*,
            case
              when v_semantic_ready_publication_enabled and ranked.is_semantic_recovery
              then round(least(
                abs(ranked.signed_amount_ex_vat),
                greatest(ranked.ordinary_positive_headroom-ranked.prior_semantic_recovery_amount,0)
              ),2)
              else round(abs(ranked.signed_amount_ex_vat),2)
            end as semantic_recovery_due_amount
          from ranked
        )
        select
          capped.*,
          case
            when v_semantic_ready_publication_enabled and capped.is_semantic_recovery
            then -capped.semantic_recovery_due_amount
            else capped.signed_amount_ex_vat
          end as semantic_signed_amount_ex_vat,
          case
            when v_semantic_ready_publication_enabled and capped.is_semantic_recovery
            then capped.draftable and capped.semantic_recovery_due_amount > 0
            else capped.draftable
          end as semantic_draftable,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'BLOCKED_FOR_PAY'
            else capped.readiness_state
          end as semantic_readiness_state,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'BLOCKED_FOR_PAY'
            else capped.presentation_section
          end as semantic_presentation_section,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'NO_PAY_HEADROOM'
            else capped.presentation_reason
          end as semantic_presentation_reason,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then capped.blocked_reason_codes || jsonb_build_array('NO_PAY_HEADROOM')
            else capped.blocked_reason_codes
          end as semantic_blocked_reason_codes,
          (
            v_semantic_ready_publication_enabled
            and capped.is_semantic_recovery
            and capped.semantic_recovery_due_amount < abs(capped.signed_amount_ex_vat)
          ) as semantic_recovery_headroom_capped
        from capped

  ;

  create temporary table timesheet_canonical_preview_lines on commit drop as
        select
          ctpr.candidate_id,
          (
            ctpr.line_json
            || jsonb_build_object(
              'preview_row_id', coalesce(nullif(btrim(coalesce(ctpr.line_json->>'line_id','')), ''), md5(ctpr.line_json::text)),
              'readiness_state', case
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'CASES_RESOLUTIONS'
                then 'CASES_RESOLUTIONS'
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
                  or coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = false
                then 'BLOCKED_FOR_PAY'
                else 'READY_TO_PAY'
              end,
              'draftable', CASE WHEN v_semantic_ready_publication_enabled THEN false ELSE (
                upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'READY_TO_PAY'
                and coalesce(nullif(ctpr.line_json->>'is_excluded_from_allocation','')::boolean, false) = false
                and coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = true
              ) END,
              'is_ready_for_draft', CASE WHEN v_semantic_ready_publication_enabled THEN false
                ELSE coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean,false) END,
              'selection_allowed', CASE WHEN v_semantic_ready_publication_enabled THEN false
                ELSE coalesce(nullif(ctpr.line_json->>'selection_allowed','')::boolean,
                  coalesce(nullif(ctpr.line_json->>'draftable','')::boolean,false)) END,
              'is_excluded_from_allocation', CASE WHEN v_semantic_ready_publication_enabled THEN true
                ELSE coalesce(nullif(ctpr.line_json->>'is_excluded_from_allocation','')::boolean,false) END
            )
          ) as line_json,
          ctpr.pay_channel,
          ctpr.paye_treatment,
          ctpr.amount_ex_vat,
          CASE WHEN v_semantic_ready_publication_enabled THEN true
            ELSE ctpr.is_excluded_from_allocation END as is_excluded_from_allocation
        from canonical_timesheet_presentation_rows ctpr

        union all

        select
          component_line.candidate_id,
          component_line.line_json,
          component_line.pay_channel,
          component_line.paye_treatment,
          component_line.amount_ex_vat,
          component_line.is_excluded_from_allocation
        from timesheet_allocation_component_lines component_line
        where v_semantic_ready_publication_enabled

  ;

  create temporary table canonical_preview_lines on commit drop as
        select
          tcpl.candidate_id,
          tcpl.line_json,
          tcpl.pay_channel,
          tcpl.paye_treatment,
          tcpl.amount_ex_vat,
          tcpl.is_excluded_from_allocation
        from timesheet_canonical_preview_lines tcpl

        union all

        select
          fcl.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'candidate_id', fcl.candidate_id::text,
              'tms_ref', fcl.cand_tms_ref,
              'display_name', fcl.cand_display_name,
              'line_type', fcl.line_type,
              'item_type_label', fcl.item_type_label,
              'item_direction', fcl.item_direction,
              'finance_case_id', fcl.finance_case_id::text,
              'case_key', ('finance:' || fcl.finance_case_id::text),
              'case_type', fcl.case_type::text,
              'case_is_blocked', (
                fcl.case_is_blocked
                or (v_semantic_ready_publication_enabled
                  and fcl.is_semantic_recovery
                  and fcl.semantic_recovery_due_amount = 0)
              )
            )
            || jsonb_build_object(
              'case_resolution_summary', fcl.case_resolution_summary_json,
              'case_components', fcl.case_components_json,
              'finance_component_id', case when fcl.finance_component_id is null then null else fcl.finance_component_id::text end,
              'component_key_type', fcl.component_key_type,
              'component_key_value', fcl.component_key_value,
              'key_type', fcl.component_key_type,
              'key_value', fcl.component_key_value,
              'economic_key', jsonb_strip_nulls(jsonb_build_object(
                'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                'key_type', fcl.component_key_type,
                'key_value', fcl.component_key_value
              )),
              'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
              'client_id', case when fcl.client_id is null then null else fcl.client_id::text end,
              'client_name', fcl.client_name,
              'week_ending_date', null,
              'linked_shift_date', case when fcl.linked_shift_date is null then null else fcl.linked_shift_date::text end,
              'pay_channel', fcl.candidate_pay_method,
              'paye_treatment', fcl.paye_treatment,
              'route_type', case when fcl.routing_kind is null then 'NORMAL_PAYMENT' else fcl.routing_kind::text end,
              'routing_kind', case when fcl.routing_kind is null then null else fcl.routing_kind::text end,
              'destination_label', fcl.destination_label,
              'taxability', case when fcl.taxability is null then null else fcl.taxability::text end
            )
            || jsonb_strip_nulls(
              jsonb_build_object(
                'taxable_manual_debt_resolution', fcl.taxable_manual_debt_resolution_json
              )
            )
            || jsonb_build_object(
              'beneficiary_name', fcl.beneficiary_name,
              'masked_bank_account', fcl.masked_bank_account,
              'bank_details_hash', fcl.payee_bank_hash,
              'blocked_reason_codes', fcl.semantic_blocked_reason_codes,
              'readiness_state', fcl.semantic_readiness_state,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'draftable', fcl.semantic_draftable,
              'snooze_allowed', fcl.snooze_allowed,
              'oneoff_bank_details_present', fcl.oneoff_bank_details_present,
              'is_candidate_directed_oneoff_payout', fcl.is_candidate_directed_oneoff_payout,
              'appears_on_umbrella_remittance', fcl.appears_on_umbrella_remittance,
              'generates_candidate_payment_advice', fcl.generates_candidate_payment_advice,
              'adjustment_comment', fcl.adjustment_comment,
              'amount_ex_vat', fcl.semantic_signed_amount_ex_vat,
              'amount_display', fcl.semantic_signed_amount_ex_vat,
              'nominal_due_amount_ex_vat', round(coalesce(fcl.nominal_due_amount_ex_vat, 0), 2),
              'recoverable_this_pay_run_ex_vat', case
                when v_semantic_ready_publication_enabled and fcl.is_semantic_recovery
                then fcl.semantic_recovery_due_amount
                else round(greatest(coalesce(fcl.due_amount_ex_vat, 0), 0), 2)
              end,
              'semantic_ordinary_positive_headroom_ex_vat', case
                when v_semantic_ready_publication_enabled then fcl.ordinary_positive_headroom
                else null end,
              'semantic_recovery_headroom_capped', fcl.semantic_recovery_headroom_capped,
              'next_due_week_start', case when fcl.next_due_week_start is null then null else fcl.next_due_week_start::text end,
              'is_advanced', false,
              'advanced_override_id', null,
              'advanced_reason', null
            )
            || case
              when fcl.line_type = 'OVERPAYMENT_RECOVERY' then jsonb_build_object(
                'recovery_residual_contract_version', 1,
                'recovery_source_outstanding_ex_vat', round(
                  coalesce(fcl.recovery_source_outstanding_ex_vat, 0),
                  2
                ),
                'recovery_active_reserved_ex_vat', round(
                  coalesce(fcl.recovery_active_reserved_ex_vat, 0),
                  2
                ),
                'recovery_residual_outstanding_ex_vat', round(
                  coalesce(fcl.nominal_due_amount_ex_vat, 0),
                  2
                )
              )
              else '{}'::jsonb
            end
            || jsonb_build_object(
              'resolution_state', case
                when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE' then 'RESOLVED'
                when fcl.finance_resolution_clearability_state = 'REQUIRES_RESOLUTION' then 'REQUIRES_RESOLUTION'
                when fcl.finance_resolution_clearability_state = 'STALE_OR_AMBIGUOUS' then 'STALE'
                else 'NOT_REQUIRED'
              end,
              'resolution_badge', case when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE' then 'RESOLVED' else null end,
              'is_case_resolution_satisfied', fcl.is_case_resolution_satisfied,
              'case_needs_resolution_now', fcl.case_needs_resolution_now,
              'finance_resolution_clearability_state', fcl.finance_resolution_clearability_state,
              'finance_resolution_clear_block_reason', fcl.finance_resolution_clear_block_reason,
              'current_saved_resolution_family', nullif(fcl.current_saved_resolution_family, ''),
              'current_saved_resolution_owner_kind', fcl.current_saved_resolution_owner_kind,
              'case_resolution_actions', jsonb_strip_nulls(jsonb_build_object(
                'apply', case when fcl.case_needs_resolution_now then jsonb_strip_nulls(jsonb_build_object(
                  'enabled', true,
                  'action', 'APPLY_CASE_RESOLUTION',
                  'candidate_id', fcl.candidate_id::text,
                  'finance_case_id', fcl.finance_case_id::text,
                  'case_key', ('finance:' || fcl.finance_case_id::text),
                  'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                  'resolution_family', fcl.case_resolution_summary_json->>'resolution_family',
                  'label', nullif(btrim(coalesce(fcl.case_resolution_summary_json->>'resolution_action_label','')), '')
                )) else null end,
                'clear', case
                  when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE'
                   and fcl.current_saved_resolution_family in ('TAXABLE_CHANNEL_RESTRUCTURE', 'NON_BUCKET')
                  then jsonb_strip_nulls(jsonb_build_object(
                  'enabled', true,
                  'action', 'CLEAR_CASE_RESOLUTION',
                  'candidate_id', fcl.candidate_id::text,
                  'finance_case_id', fcl.finance_case_id::text,
                  'case_key', ('finance:' || fcl.finance_case_id::text),
                  'linked_timesheet_id', case
                    when fcl.current_saved_resolution_family = 'NON_BUCKET'
                     and fcl.current_saved_resolution_linked_timesheet_id is not null
                      then fcl.current_saved_resolution_linked_timesheet_id::text
                    else null
                  end,
                  'resolution_family', fcl.current_saved_resolution_family,
                  'label', case
                    when fcl.current_saved_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' then 'Cancel Resolved Pay Channel'
                    when fcl.current_saved_resolution_family = 'NON_BUCKET' then 'Cancel Resolved Gross Total'
                    else null
                  end
                )) else null end
              )),
              'apply_case_resolution_action', case when fcl.case_needs_resolution_now then jsonb_strip_nulls(jsonb_build_object(
                'enabled', true,
                'action', 'APPLY_CASE_RESOLUTION',
                'candidate_id', fcl.candidate_id::text,
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                'resolution_family', fcl.case_resolution_summary_json->>'resolution_family',
                'label', nullif(btrim(coalesce(fcl.case_resolution_summary_json->>'resolution_action_label','')), '')
              )) else null end,
              'clear_case_resolution_action', case
                when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE'
                 and fcl.current_saved_resolution_family in ('TAXABLE_CHANNEL_RESTRUCTURE', 'NON_BUCKET')
                then jsonb_strip_nulls(jsonb_build_object(
                'enabled', true,
                'action', 'CLEAR_CASE_RESOLUTION',
                'candidate_id', fcl.candidate_id::text,
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'linked_timesheet_id', case
                  when fcl.current_saved_resolution_family = 'NON_BUCKET'
                   and fcl.current_saved_resolution_linked_timesheet_id is not null
                    then fcl.current_saved_resolution_linked_timesheet_id::text
                  else null
                end,
                'resolution_family', fcl.current_saved_resolution_family,
                'label', case
                  when fcl.current_saved_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' then 'Cancel Resolved Pay Channel'
                  when fcl.current_saved_resolution_family = 'NON_BUCKET' then 'Cancel Resolved Gross Total'
                  else null
                end
              )) else null end
            )
            || jsonb_build_object(
              'is_excluded_from_allocation', (fcl.semantic_draftable is not true),
              'selection_allowed', fcl.semantic_draftable,
              'is_ready_for_draft', fcl.semantic_draftable,
              'presentation_section', fcl.semantic_presentation_section,
              'presentation_role', 'PARENT',
              'presentation_line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'presentation_parent_line_id', ('finance:' || fcl.finance_case_id::text),
              'presentation_reason', fcl.semantic_presentation_reason,
              'source_ref', ('advance:' || fcl.finance_case_id::text),
              'snooze_kind', case
                when fcl.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcl.lifecycle_status_display,'')) = 'PAID' then 'PAYMENT_ADVANCE_REPAYMENT'
                when fcl.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                when fcl.case_type = 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT'
                else ''
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'FINANCE_CASE',
                'timesheet_id', null,
                'booking_id', null,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', ('advance:' || fcl.finance_case_id::text)
              ),
              'snooze_state', case
                when fcl.active_snooze_id is null then jsonb_build_object('state','NONE')
                when fcl.active_snooze_until_date is null then jsonb_build_object(
                  'state', 'INDEFINITE_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', null,
                  'note', fcl.active_snooze_note
                )
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', fcl.active_snooze_until_date::text,
                  'note', fcl.active_snooze_note
                )
              end
            )
          ) as line_json,
          fcl.candidate_pay_method as pay_channel,
          fcl.paye_treatment,
          fcl.semantic_signed_amount_ex_vat as amount_ex_vat,
          (fcl.semantic_draftable is not true) as is_excluded_from_allocation
        from semantic_finance_case_lines fcl

        union all

        select
          cf_lines.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', cf_lines.preview_row_id,
              'line_id', cf_lines.preview_row_id,
              'candidate_id', cf_lines.candidate_id::text,
              'tms_ref', cf_lines.cand_tms_ref,
              'display_name', cf_lines.cand_display_name,
              'payee_entity_kind', cf_lines.payee_entity_kind,
              'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
              'payee_context', jsonb_build_object(
                'payee_entity_kind', cf_lines.payee_entity_kind,
                'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
                'pay_channel', cf_lines.pay_channel,
                'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END
              ),
              'line_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_key', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'case_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_is_blocked', false
            )
            || jsonb_build_object(
              'case_resolution_summary', '{}'::jsonb,
              'case_components', '[]'::jsonb,
              'item_type_label', 'Manual adjustment carry-forward',
              'item_direction', CASE WHEN coalesce(cf_lines.amount_inc_vat, 0) < 0 THEN 'DEBIT' ELSE 'CREDIT' END,
              'manual_adjustment_carry_forward_id', cf_lines.manual_adjustment_carry_forward_id::text,
              'source_ref', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'operation_source_key', cf_lines.operation_source_key,
              'source_operation_source_key', cf_lines.source_operation_source_key,
              'description', cf_lines.display_description,
              'adjustment_comment', cf_lines.display_description,
              'original_description', cf_lines.original_description,
              'reason', cf_lines.reason
            )
            || jsonb_build_object(
              'source_pay_batch_id', CASE WHEN cf_lines.source_pay_batch_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_id::text END,
              'source_pay_batch_item_id', CASE WHEN cf_lines.source_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_item_id::text END,
              'source_pay_bank_transfer_id', CASE WHEN cf_lines.source_pay_bank_transfer_id IS NULL THEN NULL ELSE cf_lines.source_pay_bank_transfer_id::text END,
              'source_pay_batch_candidate_id', CASE WHEN cf_lines.source_pay_batch_candidate_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_candidate_id::text END,
              'source_correction_request_id', CASE WHEN cf_lines.source_correction_request_id IS NULL THEN NULL ELSE cf_lines.source_correction_request_id::text END,
              'source_correction_work_item_id', CASE WHEN cf_lines.source_correction_work_item_id IS NULL THEN NULL ELSE cf_lines.source_correction_work_item_id::text END,
              'source_batch_ref', cf_lines.source_batch_ref,
              'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END,
              'client_id', CASE WHEN cf_lines.client_id IS NULL THEN NULL ELSE cf_lines.client_id::text END,
              'timesheet_id', CASE WHEN cf_lines.timesheet_id IS NULL THEN NULL ELSE cf_lines.timesheet_id::text END,
              'pay_channel', cf_lines.pay_channel,
              'candidate_pay_method', cf_lines.pay_channel
            )
            || jsonb_build_object(
              'paye_treatment', cf_lines.paye_treatment,
              'tax_treatment_json', cf_lines.tax_treatment_json,
              'taxability', cf_lines.tax_treatment_json->>'taxability',
              'amount_basis', cf_lines.amount_basis,
              'adjustment_direction', cf_lines.adjustment_direction,
              'amount_ex_vat', cf_lines.amount_ex_vat,
              'amount_vat', cf_lines.amount_vat,
              'amount_inc_vat', cf_lines.amount_inc_vat,
              'amount_display', cf_lines.amount_inc_vat,
              'payment_amount_ex_vat', cf_lines.amount_ex_vat,
              'payment_amount_vat', cf_lines.amount_vat,
              'payment_amount_inc_vat', cf_lines.amount_inc_vat
            )
            || jsonb_build_object(
              'payment_amount', cf_lines.amount_inc_vat,
              'source_snapshot_json', cf_lines.source_snapshot_json,
              'manual_adjustment_carry_forward_status', cf_lines.status,
              'target_pay_batch_id', CASE WHEN cf_lines.target_pay_batch_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_id::text END,
              'target_pay_batch_item_id', CASE WHEN cf_lines.target_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_item_id::text END,
              'target_operation_source_key', cf_lines.target_operation_source_key,
              'readiness_state', 'READY_TO_PAY',
              'draftable', true,
              'is_ready_for_draft', true,
              'is_excluded_from_allocation', false,
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT'
            )
            || jsonb_build_object(
              'presentation_line_id', cf_lines.preview_row_id,
              'presentation_parent_line_id', cf_lines.preview_row_id,
              'presentation_reason', 'READY_TO_PAY',
              'route_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'routing_kind', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'appears_on_umbrella_remittance', (cf_lines.pay_channel = 'UMBRELLA'),
              'generates_candidate_payment_advice', true
            )
          ) as line_json,
          cf_lines.pay_channel,
          cf_lines.paye_treatment,
          cf_lines.amount_ex_vat,
          false as is_excluded_from_allocation
        from manual_adjustment_carry_forward_lines cf_lines

  ;

  create temporary table candidate_preview_line_rollup on commit drop as
        select
          cpl.candidate_id,
          count(*) filter (
            where coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          )::int as ready_preview_line_count,
          count(*) filter (
            where upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
          )::int as blocked_preview_line_count,
          bool_or(
            coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          ) as has_ready_preview_line
        from canonical_preview_lines cpl
        group by cpl.candidate_id

  ;

  create temporary table candidate_preview_timesheet_rollup on commit drop as
        with emitted_public_timesheets as (
          select
            tcpl.candidate_id,
            (tcpl.line_json->>'real_business_timesheet_id')::uuid as timesheet_id,
            bool_or(
              upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'READY_TO_PAY'
              and coalesce(nullif(tcpl.line_json->>'draftable','')::boolean, false) = true
            ) as has_ready_public_line,
            bool_or(
              upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
            ) as has_blocked_public_line,
            round(
              coalesce(sum(tcpl.amount_ex_vat) filter (
                where upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'READY_TO_PAY'
                  and coalesce(nullif(tcpl.line_json->>'draftable','')::boolean, false) = true
              ), 0),
              2
            ) as ready_public_amount_ex_vat
          from timesheet_canonical_preview_lines tcpl
          where upper(coalesce(tcpl.line_json->>'line_type','')) = 'TIMESHEET_PAYMENT'
            and nullif(btrim(coalesce(tcpl.line_json->>'real_business_timesheet_id','')), '') is not null
            and upper(coalesce(tcpl.line_json->>'presentation_section','')) in ('READY_TO_PAY','BLOCKED_FOR_PAY')
          group by
            tcpl.candidate_id,
            (tcpl.line_json->>'real_business_timesheet_id')::uuid
        )
        select
          ctpp.candidate_id,
          round(
            coalesce(sum(ept.ready_public_amount_ex_vat), 0),
            2
          ) as ready_timesheet_total_ex_vat,
          count(*) filter (
            where coalesce(ept.has_blocked_public_line, false) = true
          )::int as blocked_timesheet_preview_count,
          count(*) filter (
            where coalesce(ept.has_ready_public_line, false) = true
          )::int as ready_timesheet_preview_count,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'timesheet_id', ctpp.timesheet_id::text,
                'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
                'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
                'client_name', ctpp.client_name,
                'payment_amount_ex_vat', ept.ready_public_amount_ex_vat,
                'payment_amount_inc_vat', ctpp.ready_section_amount_display,
                'payment_amount', ctpp.ready_section_amount_display,
                'source_pay_method', ctpp.source_pay_method,
                'candidate_pay_method', ctpp.candidate_pay_method,
                'segment_deltas', (
                  select coalesce(
                    jsonb_agg(
                      jsonb_build_object(
                        'segment_id', rs->>'segment_id',
                        'segment_key', rs->>'segment_key',
                        'segment_stable_key', rs->>'segment_stable_key',
                        'work_date', rs->>'date',
                        'ref_num', rs->>'ref_num',
                        'delta_pay_ex_vat', round(coalesce(nullif(rs->>'pay_amount_ex_vat','')::numeric, 0), 2),
                        'raw_delta_ex_vat', round(coalesce(nullif(rs->>'raw_delta_ex_vat','')::numeric, 0), 2),
                        'effective_delta_ex_vat', round(coalesce(nullif(rs->>'effective_delta_ex_vat','')::numeric, 0), 2)
                      )
                      order by
                        nullif(btrim(coalesce(rs->>'date','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'start','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_stable_key','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_id','')), '') nulls last
                    ),
                    '[]'::jsonb
                  )
                  from jsonb_array_elements(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)) rs
                ),
                'adjustment_deltas', coalesce(tcr.adjustment_deltas_json, '[]'::jsonb),
                'delta_additional_pay_ex_vat', coalesce(tcr.delta_additional_pay_ex_vat, 0),
                'additional_unit_deltas', coalesce(tcr.additional_unit_deltas_json, '[]'::jsonb),
                'reservation_overrun_detected', coalesce(tcr.reservation_overrun_detected, false),
                'delta_expenses_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'EXPENSES'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_travel_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'TRAVEL'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_accommodation_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'ACCOMMODATION'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_other_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'OTHER'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_mileage_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'MILEAGE'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'case_key', ('timesheet:' || ctpp.timesheet_id::text),
                'case_resolution_summary', coalesce(ctpp.case_resolution_summary_json, '{}'::jsonb),
                'components', coalesce(ctpp.case_components_json, '[]'::jsonb),
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'PARENT',
                'total_segment_count', ctpp.total_segment_count,
                'ready_segment_count', ctpp.ready_segment_count,
                'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
                'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
                'is_partially_ready', ctpp.is_partially_ready,
                'is_partially_blocked', ctpp.is_partially_blocked
              )
              order by ctpp.week_ending_date, ctpp.client_name, ctpp.timesheet_id
            ) filter (where coalesce(ept.has_ready_public_line, false) = true),
            '[]'::jsonb
          ) as ready_timesheets_itemisation
        from canonical_timesheet_presentation_state ctpp
        left join emitted_public_timesheets ept
          on ept.candidate_id = ctpp.candidate_id
         and ept.timesheet_id = ctpp.timesheet_id
        left join timesheet_case_rollup_effective tcr
          on tcr.timesheet_id = ctpp.timesheet_id
         and tcr.candidate_id = ctpp.candidate_id
        group by ctpp.candidate_id

  ;

  v_canonical_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_canonical_started_at)) * 1000.0)::numeric, 3);

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'canonical_preview_line_count', (select count(*)::int from canonical_preview_lines),
    'ready_preview_line_count', coalesce((select sum(case when coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'blocked_preview_line_count', coalesce((select sum(case when upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY' then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'hidden_recovery_template_line_count', (select count(*)::int from hidden_recovery_template_lines),
    'manual_adjustment_carry_forward_line_count', (select count(*)::int from manual_adjustment_carry_forward_lines),
    'hidden_recovery_template_lines', coalesce(
      (
        select jsonb_agg(
                 hrtl.template_json
                 order by hrtl.candidate_id, hrtl.recovery_family, hrtl.sort_order, hrtl.finance_case_id
               )
        from hidden_recovery_template_lines hrtl
      ),
      '[]'::jsonb
    ),
    'source_build_canonical_diagnostics', jsonb_build_object(
      'source_build_mode', COALESCE(v_source_build_mode, false),
      'precollected_context_required', COALESCE(v_source_build_context_required, false),
      'collect_called_inside_canonical', COALESCE(v_collect_called_inside_canonical, false),
      'recollect_attempted', COALESCE(v_collect_recollect_attempted, false),
      'recollect_blocked', COALESCE(v_collect_recollect_blocked, false),
      'source_rows_seen', COALESCE((select count(*)::int from ts_baseline), 0),
      'canonical_preview_line_count', (select count(*)::int from canonical_preview_lines),
      'ready_preview_line_count', coalesce((select sum(case when coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
      'blocked_preview_line_count', coalesce((select sum(case when upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY' then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
      'canonical_elapsed_ms', v_canonical_elapsed_ms,
      'semantic_ready_observe_enabled',v_semantic_ready_observe_enabled,
      'semantic_ready_publication_enabled',v_semantic_ready_publication_enabled,
      'proposed_semantic_allocation_component_count',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN (SELECT count(*)::integer FROM timesheet_allocation_component_lines)
        ELSE 0 END,
      'proposed_semantic_allocation_component_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(component_line.amount_ex_vat),2)
          FROM timesheet_allocation_component_lines AS component_line),0)
        ELSE 0 END,
      'proposed_semantic_recovery_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(
          CASE WHEN finance_line.is_semantic_recovery
            THEN -least(
              abs(finance_line.signed_amount_ex_vat),
              greatest(finance_line.ordinary_positive_headroom-finance_line.prior_semantic_recovery_amount,0)
            ) ELSE 0 END
        ),2) FROM semantic_finance_case_lines AS finance_line),0)
        ELSE 0 END,
      'proposed_semantic_ready_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(component_line.amount_ex_vat),2)
          FROM timesheet_allocation_component_lines AS component_line),0)
          + COALESCE((SELECT round(sum(
            CASE WHEN finance_line.is_semantic_recovery
              THEN -least(
                abs(finance_line.signed_amount_ex_vat),
                greatest(finance_line.ordinary_positive_headroom-finance_line.prior_semantic_recovery_amount,0)
              ) ELSE 0 END
          ),2) FROM semantic_finance_case_lines AS finance_line),0)
        ELSE 0 END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )
  );
end;
$function$;

-- pay_preview_candidate_build_case_component_rows(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_case_component_rows(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_overpayment_sync_mode boolean := false;
  v_workbench_resolution_session_id uuid := null::uuid;
  v_workbench_resolution_session_id_text text := null::text;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_workbench_resolution_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_resolution_session_id',
    v_context_json#>>'{workbench,resolution_session_id}',
    ''
  )), '');

  IF v_workbench_resolution_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_resolution_session_id := v_workbench_resolution_session_id_text::uuid;

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS resolution_session
    WHERE resolution_session.id = v_workbench_resolution_session_id
      AND UPPER(BTRIM(COALESCE(resolution_session.status, ''))) = 'OPEN'
      AND resolution_session.discarded_at_utc IS NULL
      AND (
        v_candidate_id = ANY(COALESCE(resolution_session.scope_candidate_ids, ARRAY[]::uuid[]))
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS resolution_scope
          WHERE resolution_scope.session_id = resolution_session.id
            AND resolution_scope.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS resolution_preview_row
          WHERE resolution_preview_row.session_id = resolution_session.id
            AND resolution_preview_row.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS resolution_line_work
          WHERE resolution_line_work.session_id = resolution_session.id
            AND resolution_line_work.candidate_id = v_candidate_id
        )
      );

    IF NOT FOUND THEN
      v_workbench_resolution_session_id := NULL::uuid;
    END IF;
  ELSE
    v_workbench_resolution_session_id := NULL::uuid;
  END IF;

  v_overpayment_sync_mode := LOWER(BTRIM(COALESCE(v_context_json->>'overpayment_sync_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json#>>'{preview_decisions_json,overpayment_sync_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json->>'emit_raw_overpayment_components', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json#>>'{preview_decisions_json,emit_raw_overpayment_components}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.ts_itemised') is null then
    perform public.pay_preview_candidate_build_entitlement_rows(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.worked_time_current_segment_rows, pg_temp.worked_time_baseline_segment_rows, pg_temp.worked_time_current_ranked, pg_temp.worked_time_baseline_ranked, pg_temp.worked_time_bucket_ids, pg_temp.worked_time_bucket_agg, pg_temp.worked_time_bucket_calc, pg_temp.worked_time_bucket_alloc, pg_temp.worked_time_bucket_effective, pg_temp.worked_time_bucket_component_rows, pg_temp.worked_time_key_totals, pg_temp.worked_time_bucket_component_sums, pg_temp.worked_time_amount_fallback_rows, pg_temp.timesheet_component_rows, pg_temp.timesheet_component_match_rows, pg_temp.transient_timesheet_component_rows, pg_temp.transient_timesheet_component_review_rows, pg_temp.timesheet_case_actionable_basis, pg_temp.timesheet_live_scope, pg_temp.timesheet_linked_scope_counts, pg_temp.transient_timesheet_component_review_rows_effective, pg_temp.workbench_bucket_resolution_overlay, pg_temp.timesheet_case_rollup;

  create temporary table worked_time_current_segment_rows on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          cur_seg.seg_ord as segment_sort_ord,
          nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') as segment_id,
          nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), '') as segment_key,
          coalesce(
            nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
          ) as segment_stable_key,
          nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') as work_date,
          nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '') as ref_num,
          case
            when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null
              then nullif(btrim(coalesce(cur_seg.seg->>'date','')), '')
            else 'TOTAL'
          end as component_key_value,
          bucket.bucket_code,
          bucket.bucket_sort_ord,
          round(bucket.source_units, 6) as source_units,
          case bucket.bucket_code
            when 'DAY' then b.cur_pay_day
            when 'NIGHT' then b.cur_pay_night
            when 'SAT' then b.cur_pay_sat
            when 'SUN' then b.cur_pay_sun
            when 'BH' then b.cur_pay_bh
            else null::numeric
          end as source_rate,
          case bucket.bucket_code
            when 'DAY' then b.cur_charge_day
            when 'NIGHT' then b.cur_charge_night
            when 'SAT' then b.cur_charge_sat
            when 'SUN' then b.cur_charge_sun
            when 'BH' then b.cur_charge_bh
            else null::numeric
          end as source_charge_rate
        from ts_baseline b
        join lateral jsonb_array_elements(coalesce(b.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg, seg_ord) on true
        join lateral (
          values
            ('DAY'::text, 1::int, coalesce(nullif(cur_seg.seg->>'hours_day','')::numeric, 0)),
            ('NIGHT'::text, 2::int, coalesce(nullif(cur_seg.seg->>'hours_night','')::numeric, 0)),
            ('SAT'::text, 3::int, coalesce(nullif(cur_seg.seg->>'hours_sat','')::numeric, 0)),
            ('SUN'::text, 4::int, coalesce(nullif(cur_seg.seg->>'hours_sun','')::numeric, 0)),
            ('BH'::text, 5::int, coalesce(nullif(cur_seg.seg->>'hours_bh','')::numeric, 0))
        ) as bucket(bucket_code, bucket_sort_ord, source_units) on true
        where cur_seg.seg is not null
          and jsonb_typeof(cur_seg.seg) = 'object'
          and coalesce(bucket.source_units, 0) <> 0
  
  ;

  create temporary table worked_time_baseline_segment_rows on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          bas_seg.seg_ord as segment_sort_ord,
          nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')), '') as segment_id,
          nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')), '') as segment_key,
          coalesce(
            nullif(btrim(coalesce(bas_seg.seg->>'segment_stable_key','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'date','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')), '')
          ) as segment_stable_key,
          nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') as work_date,
          nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')), '') as ref_num,
          case
            when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null
              then nullif(btrim(coalesce(bas_seg.seg->>'date','')), '')
            else 'TOTAL'
          end as component_key_value,
          bucket.bucket_code,
          bucket.bucket_sort_ord,
          round(bucket.source_units, 6) as source_units,
          case bucket.bucket_code
            when 'DAY' then b.bas_pay_day
            when 'NIGHT' then b.bas_pay_night
            when 'SAT' then b.bas_pay_sat
            when 'SUN' then b.bas_pay_sun
            when 'BH' then b.bas_pay_bh
            else null::numeric
          end as source_rate,
          case bucket.bucket_code
            when 'DAY' then b.bas_charge_day
            when 'NIGHT' then b.bas_charge_night
            when 'SAT' then b.bas_charge_sat
            when 'SUN' then b.bas_charge_sun
            when 'BH' then b.bas_charge_bh
            else null::numeric
          end as source_charge_rate
        from ts_baseline b
        join lateral jsonb_array_elements(
          case
            when jsonb_typeof(b.base_json->'segments') = 'array'
             and jsonb_array_length(coalesce(b.base_json->'segments', '[]'::jsonb)) > 0
              then coalesce(b.base_json->'segments', '[]'::jsonb)
            else jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || b.timesheet_id::text),
                'segment_key', ('ts:' || b.timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(b.ts_booking_id, b.timesheet_id::text)),
                'date', null,
                'ref_num', null,
                'hours_day', b.bas_hours_day,
                'hours_night', b.bas_hours_night,
                'hours_sat', b.bas_hours_sat,
                'hours_sun', b.bas_hours_sun,
                'hours_bh', b.bas_hours_bh
              )
            )
          end
        ) with ordinality as bas_seg(seg, seg_ord) on true
        join lateral (
          values
            ('DAY'::text, 1::int, coalesce(nullif(bas_seg.seg->>'hours_day','')::numeric, 0)),
            ('NIGHT'::text, 2::int, coalesce(nullif(bas_seg.seg->>'hours_night','')::numeric, 0)),
            ('SAT'::text, 3::int, coalesce(nullif(bas_seg.seg->>'hours_sat','')::numeric, 0)),
            ('SUN'::text, 4::int, coalesce(nullif(bas_seg.seg->>'hours_sun','')::numeric, 0)),
            ('BH'::text, 5::int, coalesce(nullif(bas_seg.seg->>'hours_bh','')::numeric, 0))
        ) as bucket(bucket_code, bucket_sort_ord, source_units) on true
        where bas_seg.seg is not null
          and jsonb_typeof(bas_seg.seg) = 'object'
          and coalesce(bucket.source_units, 0) <> 0
  
  ;

  create temporary table worked_time_current_ranked on commit drop as
        select
          wcsr.*,
          row_number() over (
            partition by wcsr.timesheet_id, wcsr.candidate_id, wcsr.component_key_type, wcsr.component_key_value, wcsr.bucket_code
            order by wcsr.segment_sort_ord nulls last, wcsr.segment_id nulls last, wcsr.ref_num nulls last
          ) as bucket_row_ord
        from worked_time_current_segment_rows wcsr
  
  ;

  create temporary table worked_time_baseline_ranked on commit drop as
        select
          wbsr.*,
          row_number() over (
            partition by wbsr.timesheet_id, wbsr.candidate_id, wbsr.component_key_type, wbsr.component_key_value, wbsr.bucket_code
            order by wbsr.segment_sort_ord nulls last, wbsr.segment_id nulls last, wbsr.ref_num nulls last
          ) as bucket_row_ord
        from worked_time_baseline_segment_rows wbsr
  
  ;

  create temporary table worked_time_bucket_ids on commit drop as
        select distinct
          wcr.timesheet_id,
          wcr.candidate_id,
          wcr.component_key_type,
          wcr.component_key_value,
          wcr.bucket_code,
          wcr.bucket_sort_ord,
          wcr.bucket_row_ord
        from worked_time_current_ranked wcr
        union
        select distinct
          wbr.timesheet_id,
          wbr.candidate_id,
          wbr.component_key_type,
          wbr.component_key_value,
          wbr.bucket_code,
          wbr.bucket_sort_ord,
          wbr.bucket_row_ord
        from worked_time_baseline_ranked wbr
  
  ;

  create temporary table worked_time_bucket_agg on commit drop as
        select
          wbi.timesheet_id,
          wbi.candidate_id,
          wbi.component_key_type,
          wbi.component_key_value,
          wbi.bucket_code,
          max(wbi.bucket_sort_ord) as bucket_sort_ord,
          wbi.bucket_row_ord,
          max(wcr.segment_id) as cur_segment_id,
          max(wbr.segment_id) as bas_segment_id,
          max(coalesce(wcr.segment_key, wbr.segment_key)) as segment_key,
          max(coalesce(wcr.segment_stable_key, wbr.segment_stable_key)) as segment_stable_key,
          max(coalesce(wcr.ref_num, wbr.ref_num)) as ref_num,
          max(coalesce(wcr.work_date, wbr.work_date)) as work_date,
          max(wcr.segment_sort_ord) as cur_segment_sort_ord,
          max(wbr.segment_sort_ord) as bas_segment_sort_ord,
          max(wcr.source_rate) as cur_source_rate,
          max(wcr.source_charge_rate) as cur_source_charge_rate,
          round(sum(case when wcr.bucket_row_ord = wbi.bucket_row_ord then coalesce(wcr.source_units,0) else 0 end), 6) as cur_source_units,
          round(sum(case when wbr.bucket_row_ord = wbi.bucket_row_ord then coalesce(wbr.source_units,0) else 0 end), 6) as bas_source_units,
          round(sum(
            case
              when wcr.bucket_row_ord = wbi.bucket_row_ord and wcr.source_rate is not null
                then coalesce(wcr.source_units,0) * wcr.source_rate
              else 0
            end
          ), 2) as cur_pay_amount_ex_vat,
          round(sum(
            case
              when wbr.bucket_row_ord = wbi.bucket_row_ord and wbr.source_rate is not null
                then coalesce(wbr.source_units,0) * wbr.source_rate
              else 0
            end
          ), 2) as bas_pay_amount_ex_vat,
          round(sum(
            case
              when wcr.bucket_row_ord = wbi.bucket_row_ord and wcr.source_charge_rate is not null
                then coalesce(wcr.source_units,0) * wcr.source_charge_rate
              else 0
            end
          ), 2) as cur_charge_amount_ex_vat,
          round(sum(
            case
              when wbr.bucket_row_ord = wbi.bucket_row_ord and wbr.source_charge_rate is not null
                then coalesce(wbr.source_units,0) * wbr.source_charge_rate
              else 0
            end
          ), 2) as bas_charge_amount_ex_vat
        from worked_time_bucket_ids wbi
        left join worked_time_current_ranked wcr
          on wcr.timesheet_id = wbi.timesheet_id
         and wcr.candidate_id = wbi.candidate_id
         and wcr.component_key_type = wbi.component_key_type
         and wcr.component_key_value = wbi.component_key_value
         and wcr.bucket_code = wbi.bucket_code
         and wcr.bucket_row_ord = wbi.bucket_row_ord
        left join worked_time_baseline_ranked wbr
          on wbr.timesheet_id = wbi.timesheet_id
         and wbr.candidate_id = wbi.candidate_id
         and wbr.component_key_type = wbi.component_key_type
         and wbr.component_key_value = wbi.component_key_value
         and wbr.bucket_code = wbi.bucket_code
         and wbr.bucket_row_ord = wbi.bucket_row_ord
        group by
          wbi.timesheet_id,
          wbi.candidate_id,
          wbi.component_key_type,
          wbi.component_key_value,
          wbi.bucket_code,
          wbi.bucket_row_ord
  
  ;

  create temporary table worked_time_bucket_calc on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          b.ts_booking_id as booking_id,
          coalesce(wba.cur_segment_id, wba.bas_segment_id) as segment_id,
          coalesce(wba.segment_key, coalesce(wba.cur_segment_id, wba.bas_segment_id)) as segment_key,
          wba.segment_stable_key,
          wba.component_key_type,
          wba.component_key_value,
          wba.bucket_code,
          wba.bucket_sort_ord,
          wba.bucket_row_ord,
          coalesce(wba.cur_segment_sort_ord, wba.bas_segment_sort_ord) as segment_sort_ord,
          wba.work_date,
          wba.ref_num,
          wba.cur_source_rate as source_rate,
          wba.cur_source_charge_rate as source_charge_rate,
          round(coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0), 6) as raw_delta_source_units,
          coalesce(b.has_active_overpayment_case,false) as has_active_overpayment_case,
          b.require_reference_to_pay,
          coalesce(b.is_forced_advance,false) as is_forced_advance,
          round(
            case
              when wba.cur_source_rate is null then 0
              else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
            end,
            2
          ) as raw_delta_before_reservation_ex,
          round(
            case
              when wba.cur_source_charge_rate is null then 0
              else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_charge_rate, 2)
            end,
            2
          ) as raw_delta_charge_ex_vat,
          round(
            case
              when coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) < 0
                then 0
              when b.require_reference_to_pay = true
               and coalesce(b.is_forced_advance,false) = false
               and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) > 0
                then 0
              else round(
                case
                  when wba.cur_source_rate is null then 0
                  else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                end,
                2
              )
            end,
            2
          ) as preview_base_eff_delta_ex,
          round(
            case
              when coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) < 0
                then 0
              when round(
                case
                  when wba.cur_source_rate is null then 0
                  else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                end,
                2
              ) > 0
                then round(
                  case
                    when wba.cur_source_rate is null then 0
                    else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                  end,
                  2
                )
              else 0
            end,
            2
          ) as allocatable_delta_ex,
          coalesce(rss.reserved_amount_ex_vat, 0) as reserved_key_amount_ex_vat
        from ts_baseline b
        join worked_time_bucket_agg wba
          on wba.timesheet_id = b.timesheet_id
         and wba.candidate_id = b.candidate_id
        left join reserved_segment_sums rss
          on rss.timesheet_id = b.timesheet_id
         and rss.component_key_type = wba.component_key_type
         and rss.component_key_value = wba.component_key_value
  
  ;

  create temporary table worked_time_bucket_alloc on commit drop as
        select
          wbc.*,
          round(
            case
              when coalesce(wbc.allocatable_delta_ex,0) <= 0 then 0
              else greatest(
                least(
                  coalesce(wbc.reserved_key_amount_ex_vat,0)
                  - coalesce(
                      sum(coalesce(wbc.allocatable_delta_ex,0)) over (
                        partition by wbc.timesheet_id, wbc.component_key_type, wbc.component_key_value
                        order by wbc.segment_sort_ord nulls last, wbc.bucket_sort_ord, wbc.bucket_row_ord, wbc.segment_id nulls last
                        rows between unbounded preceding and 1 preceding
                      ),
                      0
                    ),
                  wbc.allocatable_delta_ex
                ),
                0
              )
            end,
            2
          ) as allocated_reserved_amount_ex_vat
        from worked_time_bucket_calc wbc
  
  ;

  create temporary table worked_time_bucket_effective on commit drop as
        select
          wba.candidate_id,
          wba.timesheet_id,
          wba.client_id,
          wba.ts_week_ending_date,
          wba.ts_client_name,
          wba.ts_pay_method,
          wba.cand_pay_method,
          wba.cand_tms_ref,
          wba.cand_display_name,
          wba.cand_umbrella_id,
          wba.umb_enabled,
          wba.umb_vat_chargeable,
          wba.cand_bank_hash,
          wba.umb_bank_hash,
          wba.booking_id,
          wba.segment_id,
          wba.segment_key,
          wba.segment_stable_key,
          wba.component_key_type,
          wba.component_key_value,
          wba.bucket_code,
          wba.bucket_sort_ord,
          wba.bucket_row_ord,
          wba.segment_sort_ord,
          wba.work_date,
          wba.ref_num,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when round(
              round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
              2
            ) <> round(
              case
                when wba.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                  then 0
                when wba.require_reference_to_pay = true
                 and wba.is_forced_advance = false
                 and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                  then 0
                else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
              end,
              2
            ) then null::numeric
            else wba.source_rate
          end as source_rate,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when wba.source_charge_rate is not null then wba.source_charge_rate
            when round(coalesce(wba.raw_delta_charge_ex_vat,0), 2) = 0 then null::numeric
            else round(
              round(coalesce(wba.raw_delta_charge_ex_vat,0), 2)
              / nullif(round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6), 0),
              6
            )
          end as source_charge_rate,
          round(
            case
              when wba.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
               and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                then 0
              when wba.require_reference_to_pay = true
               and wba.is_forced_advance = false
               and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
               and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                then 0
              else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
            end,
            2
          ) as component_amount_ex_vat,
          round(
            case
              when wba.source_charge_rate is not null
               and wba.source_rate is not null
               and wba.source_rate <> 0
               and round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) > 0
               and round(
                 round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
                 2
               ) = round(
                 case
                   when wba.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                     then 0
                   when wba.require_reference_to_pay = true
                    and wba.is_forced_advance = false
                    and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                    and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                     then 0
                   else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
                 end,
                 2
               )
                then round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_charge_rate, 2)
              when round(coalesce(wba.raw_delta_before_reservation_ex,0), 2) = 0 then round(coalesce(wba.raw_delta_charge_ex_vat,0), 2)
              else round(
                coalesce(wba.raw_delta_charge_ex_vat,0)
                * (
                    (
                      case
                        when wba.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                         and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                          then 0
                        when wba.require_reference_to_pay = true
                         and wba.is_forced_advance = false
                         and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                         and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                          then 0
                        else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
                      end
                    ) / nullif(round(coalesce(wba.raw_delta_before_reservation_ex,0), 2), 0)
                  ),
                2
              )
            end,
            2
          ) as source_charge_ex_vat,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when round(
              round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
              2
            ) <> round(
              case
                when wba.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                  then 0
                when wba.require_reference_to_pay = true
                 and wba.is_forced_advance = false
                 and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                  then 0
                else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
              end,
              2
            ) then null::numeric
            else round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6)
          end as source_units
        from worked_time_bucket_alloc wba
  
  ;

  create temporary table worked_time_bucket_component_rows on commit drop as
        select
          wtbe.candidate_id,
          wtbe.timesheet_id,
          wtbe.client_id,
          wtbe.ts_week_ending_date,
          wtbe.ts_client_name,
          wtbe.ts_pay_method,
          wtbe.cand_pay_method,
          wtbe.cand_tms_ref,
          wtbe.cand_display_name,
          wtbe.cand_umbrella_id,
          wtbe.umb_enabled,
          wtbe.umb_vat_chargeable,
          wtbe.cand_bank_hash,
          wtbe.umb_bank_hash,
          ('timesheet:' || wtbe.timesheet_id::text) as source_family_key,
          wtbe.component_key_type,
          wtbe.component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(wtbe.component_amount_ex_vat,0), 2) as component_amount_ex_vat,
          round(coalesce(wtbe.source_charge_ex_vat,0), 2) as source_charge_ex_vat,
          case when wtbe.source_units is null then null else round(wtbe.source_units, 6) end as source_units,
          case when wtbe.source_rate is null then null else round(wtbe.source_rate, 6) end as source_rate,
          case when wtbe.source_charge_rate is null then null else round(wtbe.source_charge_rate, 6) end as source_charge_rate,
          upper(coalesce(wtbe.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(wtbe.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', wtbe.timesheet_id::text,
              'segment_id', wtbe.segment_id,
              'segment_key', wtbe.segment_key,
              'segment_stable_key', wtbe.segment_stable_key,
              'work_date', wtbe.work_date,
              'ref_num', wtbe.ref_num,
              'bucket_code', wtbe.bucket_code,
              'source_units', case when wtbe.source_units is null then null else round(wtbe.source_units, 6) end,
              'source_rate', case when wtbe.source_rate is null then null else round(wtbe.source_rate, 6) end,
              'source_charge_rate', case when wtbe.source_charge_rate is null then null else round(wtbe.source_charge_rate, 6) end,
              'source_charge_ex_vat', round(coalesce(wtbe.source_charge_ex_vat,0), 2),
              'source_pay_ex_vat', round(coalesce(wtbe.component_amount_ex_vat,0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || wtbe.timesheet_id::text),
            wtbe.component_key_type,
            wtbe.component_key_value,
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(wtbe.ts_pay_method, '')),
            upper(coalesce(wtbe.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', wtbe.timesheet_id::text,
                'segment_id', wtbe.segment_id,
                'segment_key', wtbe.segment_key,
                'segment_stable_key', wtbe.segment_stable_key,
                'work_date', wtbe.work_date,
                'ref_num', wtbe.ref_num,
                'bucket_code', wtbe.bucket_code
              )
            ),
            round(coalesce(wtbe.component_amount_ex_vat,0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(wtbe.cand_pay_method, '')))
          ) as component_fingerprint
        from worked_time_bucket_effective wtbe
        where round(coalesce(wtbe.component_amount_ex_vat,0), 2) <> 0
  
  ;

  create temporary table worked_time_key_totals on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null
              then nullif(btrim(coalesce(seg->>'work_date','')), '')
            else 'TOTAL'
          end as component_key_value,
          round(sum(coalesce(nullif(seg->>'delta_pay_ex_vat','')::numeric, 0)), 2) as total_pay_ex_vat,
          round(sum(coalesce(nullif(seg->>'delta_charge_ex_vat','')::numeric, 0)), 2) as total_charge_ex_vat
        from ts_itemised d
        cross join lateral jsonb_array_elements(coalesce(d.segment_deltas_json, '[]'::jsonb)) seg
        group by
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null
              then nullif(btrim(coalesce(seg->>'work_date','')), '')
            else 'TOTAL'
          end
        having round(sum(coalesce(nullif(seg->>'delta_pay_ex_vat','')::numeric, 0)), 2) <> 0
  
  ;

  create temporary table worked_time_bucket_component_sums on commit drop as
        select
          wtcr.candidate_id,
          wtcr.timesheet_id,
          wtcr.component_key_type,
          wtcr.component_key_value,
          round(sum(coalesce(wtcr.component_amount_ex_vat,0)), 2) as total_bucket_pay_ex_vat,
          round(sum(coalesce(wtcr.source_charge_ex_vat,0)), 2) as total_bucket_charge_ex_vat
        from worked_time_bucket_component_rows wtcr
        group by
          wtcr.candidate_id,
          wtcr.timesheet_id,
          wtcr.component_key_type,
          wtcr.component_key_value
  
  ;

  create temporary table worked_time_amount_fallback_rows on commit drop as
        select
          wkt.candidate_id,
          wkt.timesheet_id,
          wkt.client_id,
          wkt.ts_week_ending_date,
          wkt.ts_client_name,
          wkt.ts_pay_method,
          wkt.cand_pay_method,
          wkt.cand_tms_ref,
          wkt.cand_display_name,
          wkt.cand_umbrella_id,
          wkt.umb_enabled,
          wkt.umb_vat_chargeable,
          wkt.cand_bank_hash,
          wkt.umb_bank_hash,
          ('timesheet:' || wkt.timesheet_id::text) as source_family_key,
          wkt.component_key_type,
          wkt.component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2) as component_amount_ex_vat,
          round(coalesce(wkt.total_charge_ex_vat,0) - coalesce(wbcs.total_bucket_charge_ex_vat,0), 2) as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(wkt.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(wkt.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', wkt.timesheet_id::text,
              'work_date', case when wkt.component_key_type = 'TS_DAY' then wkt.component_key_value else null end,
              'component_fallback', 'WORKED_TIME_AMOUNT',
              'source_charge_ex_vat', round(coalesce(wkt.total_charge_ex_vat,0) - coalesce(wbcs.total_bucket_charge_ex_vat,0), 2),
              'source_pay_ex_vat', round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || wkt.timesheet_id::text),
            wkt.component_key_type,
            wkt.component_key_value,
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(wkt.ts_pay_method, '')),
            upper(coalesce(wkt.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', wkt.timesheet_id::text,
                'work_date', case when wkt.component_key_type = 'TS_DAY' then wkt.component_key_value else null end,
                'component_fallback', 'WORKED_TIME_AMOUNT'
              )
            ),
            round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(wkt.cand_pay_method, '')))
          ) as component_fingerprint
        from worked_time_key_totals wkt
        left join worked_time_bucket_component_sums wbcs
          on wbcs.candidate_id = wkt.candidate_id
         and wbcs.timesheet_id = wkt.timesheet_id
         and wbcs.component_key_type = wkt.component_key_type
         and wbcs.component_key_value = wkt.component_key_value
        where round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2) <> 0
  
  ;

  create temporary table timesheet_component_rows on commit drop as
        select
          wt.candidate_id,
          wt.timesheet_id,
          wt.client_id,
          wt.ts_week_ending_date,
          wt.ts_client_name,
          wt.ts_pay_method,
          wt.cand_pay_method,
          wt.cand_tms_ref,
          wt.cand_display_name,
          wt.cand_umbrella_id,
          wt.umb_enabled,
          wt.umb_vat_chargeable,
          wt.cand_bank_hash,
          wt.umb_bank_hash,
          wt.source_family_key,
          wt.component_key_type,
          wt.component_key_value,
          wt.classification,
          wt.component_amount_ex_vat,
          wt.source_charge_ex_vat,
          wt.source_units,
          wt.source_rate,
          wt.source_charge_rate,
          wt.source_pay_method,
          wt.current_target_pay_method,
          wt.source_basis_json,
          wt.component_fingerprint
        from worked_time_bucket_component_rows wt

        union all

        select
          wf.candidate_id,
          wf.timesheet_id,
          wf.client_id,
          wf.ts_week_ending_date,
          wf.ts_client_name,
          wf.ts_pay_method,
          wf.cand_pay_method,
          wf.cand_tms_ref,
          wf.cand_display_name,
          wf.cand_umbrella_id,
          wf.umb_enabled,
          wf.umb_vat_chargeable,
          wf.cand_bank_hash,
          wf.umb_bank_hash,
          wf.source_family_key,
          wf.component_key_type,
          wf.component_key_value,
          wf.classification,
          wf.component_amount_ex_vat,
          wf.source_charge_ex_vat,
          wf.source_units,
          wf.source_rate,
          wf.source_charge_rate,
          wf.source_pay_method,
          wf.current_target_pay_method,
          wf.source_basis_json,
          wf.component_fingerprint
        from worked_time_amount_fallback_rows wf
        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'ADDITIONAL_CODE'::text as component_key_type,
          coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL') as component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2) as component_amount_ex_vat,
          round(coalesce(nullif(au->>'delta_charge_ex_vat','')::numeric, 0), 2) as source_charge_ex_vat,
          nullif(au->>'source_units','')::numeric as source_units,
          nullif(au->>'source_rate','')::numeric as source_rate,
          nullif(au->>'source_charge_rate','')::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'additional_code', coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL'),
              'source_units', nullif(au->>'source_units','')::numeric,
              'source_rate', nullif(au->>'source_rate','')::numeric,
              'source_charge_rate', nullif(au->>'source_charge_rate','')::numeric,
              'source_charge_ex_vat', round(coalesce(nullif(au->>'delta_charge_ex_vat','')::numeric, 0), 2),
              'source_pay_ex_vat', round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'ADDITIONAL_CODE',
            coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL'),
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'additional_code', coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL')
              )
            ),
            round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral jsonb_array_elements(
          case
            when jsonb_array_length(coalesce(d.additional_unit_deltas_json, '[]'::jsonb)) > 0 then coalesce(d.additional_unit_deltas_json, '[]'::jsonb)
            when round(coalesce(d.delta_additional_pay_ex_vat, 0), 2) <> 0 then jsonb_build_array(jsonb_build_object('code', 'TOTAL', 'delta_pay_ex_vat', d.delta_additional_pay_ex_vat))
            else '[]'::jsonb
          end
        ) au
        where round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2) <> 0

        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'ADJUSTMENT_CODE'::text as component_key_type,
          coalesce(nullif(btrim(coalesce(adj->>'adj_id','')), ''), 'TOTAL') as component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2) as component_amount_ex_vat,
          null::numeric as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'adjustment_id', nullif(btrim(coalesce(adj->>'adj_id','')), ''),
              'source_pay_ex_vat', round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'ADJUSTMENT_CODE',
            coalesce(nullif(btrim(coalesce(adj->>'adj_id','')), ''), 'TOTAL'),
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'adjustment_id', nullif(btrim(coalesce(adj->>'adj_id','')), '')
              )
            ),
            round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral jsonb_array_elements(coalesce(d.adjustment_deltas_json, '[]'::jsonb)) adj
        where round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2) <> 0

        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'EXPENSE_CODE'::text as component_key_type,
          x.component_key_value,
          'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum as classification,
          x.component_amount_ex_vat,
          case x.component_key_value
            when 'EXPENSES' then round(coalesce(d.delta_expenses_charge_ex_vat,0),2)
            when 'TRAVEL' then round(coalesce(d.delta_travel_charge_ex_vat,0),2)
            when 'ACCOMMODATION' then round(coalesce(d.delta_accommodation_charge_ex_vat,0),2)
            when 'OTHER' then round(coalesce(d.delta_other_charge_ex_vat,0),2)
            when 'MILEAGE' then round(coalesce(d.delta_mileage_charge_ex_vat,0),2)
            else null::numeric
          end as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'expense_code', x.component_key_value,
              'source_charge_ex_vat', case x.component_key_value
                when 'EXPENSES' then round(coalesce(d.delta_expenses_charge_ex_vat,0),2)
                when 'TRAVEL' then round(coalesce(d.delta_travel_charge_ex_vat,0),2)
                when 'ACCOMMODATION' then round(coalesce(d.delta_accommodation_charge_ex_vat,0),2)
                when 'OTHER' then round(coalesce(d.delta_other_charge_ex_vat,0),2)
                when 'MILEAGE' then round(coalesce(d.delta_mileage_charge_ex_vat,0),2)
                else null::numeric
              end,
              'source_pay_ex_vat', x.component_amount_ex_vat
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'EXPENSE_CODE',
            x.component_key_value,
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'expense_code', x.component_key_value
              )
            ),
            x.component_amount_ex_vat,
            NULL::numeric,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral (
          values
            (
              'EXPENSES',
              case
                when round(coalesce(d.delta_travel_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_accommodation_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_other_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_mileage_pay_ex_vat, 0), 2) <> 0
                then 0::numeric
                else round(coalesce(d.delta_expenses_pay_ex_vat, 0), 2)
              end
            ),
            ('TRAVEL', round(coalesce(d.delta_travel_pay_ex_vat, 0), 2)),
            ('ACCOMMODATION', round(coalesce(d.delta_accommodation_pay_ex_vat, 0), 2)),
            ('OTHER', round(coalesce(d.delta_other_pay_ex_vat, 0), 2)),
            ('MILEAGE', round(coalesce(d.delta_mileage_pay_ex_vat, 0), 2))
        ) as x(component_key_value, component_amount_ex_vat)
        where x.component_amount_ex_vat <> 0
  
  ;



  WITH policy_x_component_rows AS (
    SELECT
      component_row.ctid AS row_ctid,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM timesheet_component_rows AS component_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => component_row.timesheet_id,
      p_live_source_json => COALESCE(component_row.source_basis_json, '{}'::jsonb)
        || jsonb_build_object(
          'timesheet_id', component_row.timesheet_id::text,
          'existing_component_key_type', component_row.component_key_type,
          'existing_component_key_value', component_row.component_key_value,
          'item_type', CASE
            WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE' AND UPPER(COALESCE(component_row.component_key_value, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
            ELSE 'ADJUSTMENT_DELTA'
          END,
          'additional_code', CASE WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN component_row.component_key_value ELSE NULL END,
          'adjustment_id', CASE WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN component_row.component_key_value ELSE NULL END,
          'expense_code', CASE WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN component_row.component_key_value ELSE NULL END
        ),
      p_item_type => CASE
        WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE' AND UPPER(COALESCE(component_row.component_key_value, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        ELSE 'ADJUSTMENT_DELTA'
      END,
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '')::date
        ELSE NULL::date
      END
    ) AS policy_key ON true
  )
  UPDATE timesheet_component_rows AS component_row
  SET component_key_type = policy_x_component_rows.resolved_key_type,
      component_key_value = policy_x_component_rows.resolved_key_value,
      component_fingerprint = public.pay_finance_component_fingerprint(
        component_row.source_family_key,
        policy_x_component_rows.resolved_key_type,
        policy_x_component_rows.resolved_key_value,
        component_row.classification,
        component_row.source_pay_method,
        component_row.current_target_pay_method,
        COALESCE(component_row.source_basis_json, '{}'::jsonb),
        round(coalesce(component_row.component_amount_ex_vat, 0), 2),
        v_erni_pct,
        jsonb_build_object('candidate_pay_method', upper(coalesce(component_row.current_target_pay_method, '')))
      )
  FROM policy_x_component_rows
  WHERE component_row.ctid = policy_x_component_rows.row_ctid
    AND policy_x_component_rows.resolved_key_type IS NOT NULL
    AND policy_x_component_rows.resolved_key_value IS NOT NULL;

  create temporary table timesheet_component_match_rows on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tcr.client_id,
          tcr.ts_week_ending_date,
          tcr.ts_client_name,
          tcr.ts_pay_method,
          tcr.cand_pay_method,
          tcr.cand_tms_ref,
          tcr.cand_display_name,
          tcr.cand_umbrella_id,
          tcr.umb_enabled,
          tcr.umb_vat_chargeable,
          tcr.cand_bank_hash,
          tcr.umb_bank_hash,
          tcr.source_family_key,
          tcr.component_key_type,
          tcr.component_key_value,
          tcr.classification,
          tcr.component_amount_ex_vat,
          tcr.source_charge_ex_vat,
          tcr.source_units,
          tcr.source_rate,
          tcr.source_charge_rate,
          tcr.source_pay_method,
          tcr.current_target_pay_method,
          tcr.source_basis_json,
          tcr.component_fingerprint,
          mdc.finance_case_id as matched_finance_case_id,
          mdc.finance_component_id as matched_finance_component_id,
          mdc.saved_target_pay_method as matched_saved_target_pay_method,
          mdc.saved_resolution_mode as matched_saved_resolution_mode,
          mdc.saved_resolution_payload_json as matched_saved_resolution_payload_json,
          mdc.saved_resolution_result_json as matched_saved_resolution_result_json,
          mdc.resolution_fingerprint as matched_resolution_fingerprint,
          mdc.is_resolution_stale as matched_is_resolution_stale,
          mdc.stale_reason as matched_stale_reason
        from timesheet_component_rows tcr
        left join lateral (
          select
            pfc.finance_case_id,
            pfc.id as finance_component_id,
            pfc.saved_target_pay_method,
            pfc.saved_resolution_mode,
            pfc.saved_resolution_payload_json,
            pfc.saved_resolution_result_json,
            pfc.resolution_fingerprint,
            pfc.is_resolution_stale,
            pfc.stale_reason
          from public.pay_finance_case_components pfc
          join finance_case_baseline_scope vfcr_m
            on vfcr_m.finance_case_id = pfc.finance_case_id
           and vfcr_m.candidate_id = tcr.candidate_id
           and vfcr_m.case_type in (
             'OVERPAYMENT'::public.pay_finance_case_type_enum,
             'UNDERPAYMENT'::public.pay_finance_case_type_enum
           )
          where pfc.closed_at_utc is null
            and coalesce(pfc.remaining_source_amount, 0) > 0
            and pfc.candidate_id = tcr.candidate_id
            and pfc.linked_timesheet_id = tcr.timesheet_id
            and pfc.source_family_key = tcr.source_family_key
            and pfc.component_key_type = tcr.component_key_type
            and pfc.component_key_value = tcr.component_key_value
            and pfc.classification = tcr.classification
            and coalesce(pfc.source_basis_json, '{}'::jsonb) = coalesce(tcr.source_basis_json, '{}'::jsonb)
          order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
          limit 1
        ) mdc on true
  
  ;

  create temporary table transient_timesheet_component_rows on commit drop as
        select
          tmr.candidate_id,
          tmr.timesheet_id,
          tmr.client_id,
          tmr.ts_week_ending_date,
          tmr.ts_client_name,
          tmr.ts_pay_method,
          tmr.cand_pay_method,
          tmr.cand_tms_ref,
          tmr.cand_display_name,
          tmr.cand_umbrella_id,
          tmr.umb_enabled,
          tmr.umb_vat_chargeable,
          tmr.cand_bank_hash,
          tmr.umb_bank_hash,
          tmr.source_family_key,
          tmr.component_key_type,
          tmr.component_key_value,
          tmr.classification,
          tmr.component_amount_ex_vat,
          tmr.source_charge_ex_vat,
          tmr.source_units,
          tmr.source_rate,
          tmr.source_charge_rate,
          tmr.source_pay_method,
          tmr.current_target_pay_method,
          tmr.source_basis_json,
          tmr.component_fingerprint
        from timesheet_component_match_rows tmr
        where tmr.matched_finance_component_id is null
           or COALESCE(v_overpayment_sync_mode, false) = true
  
  ;

  create temporary table transient_timesheet_component_review_rows on commit drop as
        select
          ttr.candidate_id,
          ttr.timesheet_id,
          ttr.client_id,
          ttr.ts_week_ending_date,
          ttr.ts_client_name,
          ttr.ts_pay_method,
          ttr.cand_pay_method,
          ttr.cand_tms_ref,
          ttr.cand_display_name,
          ttr.cand_umbrella_id,
          ttr.umb_enabled,
          ttr.umb_vat_chargeable,
          ttr.cand_bank_hash,
          ttr.umb_bank_hash,
          ttr.source_family_key,
          ttr.component_key_type,
          ttr.component_key_value,
          ttr.classification,
          ttr.component_amount_ex_vat,
          ttr.source_charge_ex_vat,
          ttr.source_units,
          ttr.source_rate,
          ttr.source_charge_rate,
          ttr.source_pay_method,
          ttr.current_target_pay_method,
          ttr.source_basis_json,
          ttr.component_fingerprint,
          (
            ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and ttr.source_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method <> ''
            and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
          ) as has_suggested_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and ttr.source_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method <> ''
            and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
          ) as is_fresh_suggested_resolution,
          false as is_reusable_saved_resolution,
          false as is_stale_saved_resolution,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', ttr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'suggested_target_rate', case when ttr.source_units is not null and ttr.source_units <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.source_units, 2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else null::jsonb
          end as suggested_resolution_payload_json,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', ttr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2),
                'target_amount_vat', round(coalesce((ttrs.target_amounts_json->>'vat')::numeric,0),2),
                'target_amount_inc_vat', round(coalesce((ttrs.target_amounts_json->>'inc')::numeric,0),2),
                'basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'replacement_rate', case when ttr.source_units is not null and ttr.source_units <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.source_units, 2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'vat')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'inc')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_units_per_source_ex_vat', case when ttr.source_units is not null and coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(ttr.source_units / ttr.component_amount_ex_vat, 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'source_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2),
                'target_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'target_margin_ex_vat', case when ttr.source_charge_ex_vat is null or ttrs.target_amounts_json is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'margin_delta_ex_vat', case when ttr.source_charge_ex_vat is null or ttrs.target_amounts_json is null then null else 0::numeric end
              )
            )
            else null::jsonb
          end as suggested_resolution_result_json,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end as source_charge_component_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end as source_margin_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttrs.target_amounts_json is not null then round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) else null end as target_pay_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null then round(ttr.source_charge_ex_vat,2) else null end as target_charge_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null and ttrs.target_amounts_json is not null then round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) else null end as target_margin_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null and ttrs.target_amounts_json is not null then 0::numeric else null end as margin_delta_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
          end as suggestion_explanation_text
        from transient_timesheet_component_rows ttr
        left join lateral (
          select
            case
              when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when ttr.source_pay_method = 'PAYE' and ttr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(ttr.component_amount_ex_vat, v_erni_pct, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              when ttr.source_pay_method = 'UMBRELLA' and ttr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(ttr.component_amount_ex_vat, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(ttr.component_amount_ex_vat, v_erni_pct))
              when ttr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(ttr.component_amount_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(ttr.component_amount_ex_vat,0),2))
              when ttr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(ttr.component_amount_ex_vat, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) ttrs on true
  
  ;

  create temporary table transient_timesheet_component_review_rows_effective on commit drop as
        select
          ttr.candidate_id,
          ttr.timesheet_id,
          ttr.client_id,
          ttr.ts_week_ending_date,
          ttr.ts_client_name,
          ttr.ts_pay_method,
          ttr.cand_pay_method,
          ttr.cand_tms_ref,
          ttr.cand_display_name,
          ttr.cand_umbrella_id,
          ttr.umb_enabled,
          ttr.umb_vat_chargeable,
          ttr.cand_bank_hash,
          ttr.umb_bank_hash,
          ttr.source_family_key,
          ttr.component_key_type,
          ttr.component_key_value,
          ttr.classification,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as component_amount_ex_vat,
          round(coalesce(ttr.source_charge_ex_vat,0),2) as source_charge_ex_vat,
          ttr.source_units,
          ttr.source_rate,
          ttr.source_charge_rate,
          ttr.source_pay_method,
          ttr.current_target_pay_method,
          ttr.source_basis_json,
          ttr.component_fingerprint,
          ttrx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          ttrx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          null::jsonb as approved_resolution_payload_json,
          null::jsonb as approved_resolution_result_json,
          null::uuid as resolved_rate_resolution_id,
          false::boolean as resolved_rate_applied_via_linked_scope,
          null::text as resolved_rate_source_anchor_case_key,
          null::uuid as resolved_rate_source_anchor_timesheet_id,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then false
            when ttrx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then true
            when ttrx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then true
            else false
          end as has_suggested_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when ttrx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (ttrx.is_actionable_bucket_resolution = true) as is_fresh_suggested_resolution,
          false as is_reusable_saved_resolution,
          false as is_stale_saved_resolution,
          case
            when ttrx.is_actionable_bucket_resolution = true then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', ttr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'suggested_target_rate', case when tts.suggested_target_rate is null then null else round(tts.suggested_target_rate,2) end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else null::jsonb
          end as suggested_resolution_payload_json,
          case
            when ttrx.is_actionable_bucket_resolution = true then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', ttr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'inc','')::numeric, coalesce(tts.suggested_target_pay_ex_vat,0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'replacement_rate', case when tts.suggested_target_rate is null then null else round(tts.suggested_target_rate,2) end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'inc','')::numeric, coalesce(tts.suggested_target_pay_ex_vat,0), 0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when ttr.source_units is not null and round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(ttr.source_units / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'source_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'target_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'margin_delta_ex_vat', case when ttr.source_charge_ex_vat is null then null else 0::numeric end
              )
            )
            else null::jsonb
          end as suggested_resolution_result_json,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end as source_charge_component_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null then round(ttr.source_charge_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null
              then round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat, 2)
            else null::numeric
          end as target_margin_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null
              then 0::numeric
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when ttrx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when ttrx.is_actionable_bucket_resolution = true then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as preview_component_amount_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when ttrx.is_actionable_bucket_resolution = true then 0::numeric
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as ready_preview_amount_ex_vat,
          case
            when ttrx.is_actionable_bucket_resolution = true then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else 0::numeric
          end as blocked_preview_amount_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'FIXED'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NOT_REQUIRED'
            when ttrx.is_actionable_bucket_resolution = true then 'REQUIRED'
            else 'FIXED'
          end as resolution_state,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::numeric
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then null::numeric
            when ttrx.is_actionable_bucket_resolution = true then round(tts.suggested_target_rate,2)
            else null::numeric
          end as target_rate
        from transient_timesheet_component_review_rows ttr
        left join lateral (
          select
            (
              ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and ttr.source_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method <> ''
              and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
              and round(coalesce(ttr.component_amount_ex_vat,0),2) > 0
              and ttr.source_units is not null
              and coalesce(ttr.source_units,0) <> 0
              and ttr.source_rate is not null
              and ttr.source_charge_rate is not null
              and ttr.component_key_type <> 'ADJUSTMENT_CODE'
            ) as is_actionable_bucket_resolution,
            (
              ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and ttr.source_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method <> ''
              and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
              and not (
                ttr.source_units is not null
                and coalesce(ttr.source_units,0) <> 0
                and ttr.source_rate is not null
                and ttr.source_charge_rate is not null
                and ttr.component_key_type <> 'ADJUSTMENT_CODE'
              )
            ) as is_fixed_taxable_conversion
        ) ttrx on true
        left join lateral (
          select
            case
              when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
              when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
              when ttr.source_pay_method = 'PAYE' and ttr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(ttr.component_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when ttr.source_pay_method = 'UMBRELLA' and ttr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(ttr.component_amount_ex_vat,0),2), v_erni_pct),2)
              when ttr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(ttr.component_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(ttr.component_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) ttb on true
        left join lateral (
          select
            case
              when ttrx.is_actionable_bucket_resolution = true and ttr.source_units is not null and ttr.source_units <> 0
                then round(ttb.target_ex_before_rate / ttr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when ttrx.is_actionable_bucket_resolution = true and ttr.source_units is not null and ttr.source_units <> 0
                then round(round(ttb.target_ex_before_rate / ttr.source_units, 2) * ttr.source_units, 2)
              else round(ttb.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) tts on true
        left join lateral (
          select
            case
              when tts.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(ttr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(tts.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(tts.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(tts.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) ttam on true
  
  ;

  IF v_workbench_resolution_session_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE workbench_bucket_resolution_overlay ON COMMIT DROP AS
    WITH stored_resolution_components AS (
      SELECT
        stored_resolution.id AS resolution_id,
        stored_resolution.case_key,
        stored_resolution.timesheet_id,
        stored_resolution.source_basis_fingerprint,
        stored_resolution.source_family_key,
        stored_resolution.bucket_code,
        stored_resolution.component_key_type,
        stored_resolution.component_key_value,
        stored_resolution.payload_json,
        stored_resolution.updated_at_utc,
        bucket_element.ordinality::integer AS bucket_ordinal,
        bucket_element.value AS bucket_json
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(stored_resolution.payload_json->'bucket_resolutions') = 'array'
            THEN stored_resolution.payload_json->'bucket_resolutions'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS bucket_element(value, ordinality)
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND stored_resolution.resolution_family = 'BUCKETED'
        AND jsonb_typeof(bucket_element.value) = 'object'
    )
    SELECT DISTINCT ON (
      stored_component.case_key,
      stored_component.timesheet_id,
      stored_component.source_basis_fingerprint,
      stored_component.source_family_key,
      COALESCE(stored_component.bucket_code, ''),
      stored_component.component_key_type,
      stored_component.component_key_value
    )
      stored_component.resolution_id,
      stored_component.case_key,
      stored_component.timesheet_id,
      stored_component.source_basis_fingerprint,
      stored_component.source_family_key,
      stored_component.bucket_code,
      stored_component.component_key_type,
      stored_component.component_key_value,
      stored_component.payload_json,
      stored_component.bucket_json,
      UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'classification', ''))) AS classification,
      UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'source_pay_method', ''))) AS source_pay_method,
      UPPER(BTRIM(COALESCE(
        stored_component.bucket_json->>'target_pay_method',
        stored_component.bucket_json->>'current_target_pay_method',
        ''
      ))) AS target_pay_method,
      CASE
        WHEN COALESCE(stored_component.bucket_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN round((stored_component.bucket_json->>'source_units')::numeric, 6)
        ELSE NULL::numeric
      END AS source_units,
      CASE
        WHEN COALESCE(stored_component.bucket_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN round((stored_component.bucket_json->>'source_rate')::numeric, 6)
        ELSE NULL::numeric
      END AS source_rate,
      CASE
        WHEN COALESCE(stored_component.bucket_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN round((stored_component.bucket_json->>'source_charge_rate')::numeric, 6)
        ELSE NULL::numeric
      END AS source_charge_rate,
      UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'resolution_mode', ''))) AS resolution_mode,
      CASE
        WHEN COALESCE(stored_component.bucket_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN round((stored_component.bucket_json->>'target_rate')::numeric, 2)
        ELSE NULL::numeric
      END AS target_rate,
      LOWER(BTRIM(COALESCE(stored_component.payload_json->>'applied_via_linked_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS applied_via_linked_scope,
      NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'source_anchor_case_key', '')), '') AS source_anchor_case_key,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'source_anchor_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'source_anchor_timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS source_anchor_timesheet_id
    FROM stored_resolution_components AS stored_component
    WHERE stored_component.timesheet_id IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(stored_component.source_basis_fingerprint, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(stored_component.source_family_key, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(stored_component.component_key_type, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(stored_component.component_key_value, '')), '') IS NOT NULL
      AND UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'resolution_mode', ''))) IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE')
      AND COALESCE(stored_component.bucket_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND (stored_component.bucket_json->>'target_rate')::numeric >= 0
    ORDER BY
      stored_component.case_key,
      stored_component.timesheet_id,
      stored_component.source_basis_fingerprint,
      stored_component.source_family_key,
      COALESCE(stored_component.bucket_code, ''),
      stored_component.component_key_type,
      stored_component.component_key_value,
      stored_component.updated_at_utc DESC,
      stored_component.resolution_id DESC,
      stored_component.bucket_ordinal DESC;

    UPDATE transient_timesheet_component_review_rows_effective AS effective_component
    SET approved_resolution_mode = resolution_overlay.resolution_mode,
        approved_target_rate = resolution_overlay.target_rate,
        approved_resolution_payload_json = resolution_overlay.payload_json,
        approved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        resolved_rate_resolution_id = resolution_overlay.resolution_id,
        resolved_rate_applied_via_linked_scope = resolution_overlay.applied_via_linked_scope,
        resolved_rate_source_anchor_case_key = resolution_overlay.source_anchor_case_key,
        resolved_rate_source_anchor_timesheet_id = resolution_overlay.source_anchor_timesheet_id,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        has_suggested_resolution = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        target_pay_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
          ELSE round(
            (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
            - effective_component.source_margin_ex_vat,
            2
          )
        END,
        preview_component_amount_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        ready_preview_amount_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        blocked_preview_amount_ex_vat = 0::numeric,
        resolution_state = 'RESOLVED',
        target_rate = resolution_overlay.target_rate
    FROM workbench_bucket_resolution_overlay AS resolution_overlay
    WHERE effective_component.candidate_id = v_candidate_id
      AND effective_component.timesheet_id = resolution_overlay.timesheet_id
      AND resolution_overlay.case_key = ('timesheet:' || effective_component.timesheet_id::text)
      AND effective_component.source_family_key = resolution_overlay.source_family_key
      AND md5(COALESCE(effective_component.source_basis_json::text, '{}'::text)) = resolution_overlay.source_basis_fingerprint
      AND COALESCE(NULLIF(UPPER(BTRIM(COALESCE(effective_component.source_basis_json->>'bucket_code', ''))), ''), '') = COALESCE(resolution_overlay.bucket_code, '')
      AND effective_component.component_key_type = resolution_overlay.component_key_type
      AND effective_component.component_key_value = resolution_overlay.component_key_value
      AND round(effective_component.source_units, 6) = resolution_overlay.source_units
      AND round(effective_component.source_rate, 6) = resolution_overlay.source_rate
      AND round(effective_component.source_charge_rate, 6) = resolution_overlay.source_charge_rate
      AND (resolution_overlay.classification = '' OR UPPER(effective_component.classification::text) = resolution_overlay.classification)
      AND (resolution_overlay.source_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.source_pay_method, ''))) = resolution_overlay.source_pay_method)
      AND (resolution_overlay.target_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.current_target_pay_method, ''))) = resolution_overlay.target_pay_method)
      AND effective_component.is_actionable_resolution_row = true;
  END IF;

  create temporary table timesheet_case_actionable_basis on commit drop as
        select distinct
          effective_component.timesheet_id,
          md5(
            jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_family', 'BUCKETED',
                'classification', nullif(effective_component.classification::text, ''),
                'component_semantics', nullif(effective_component.component_key_type, ''),
                'category_identity', case
                  when effective_component.component_key_type in ('TS_DAY', 'TS_TOTAL') then concat_ws(
                    '|',
                    'WORKED_TIME',
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'bucket_code', ''))), ''), '~')
                  )
                  when effective_component.component_key_type in ('ADDITIONAL_CODE', 'ADDITIONAL_UNIT', 'ADDITIONAL_UNITS', 'PAY_CODE') then concat_ws(
                    '|',
                    effective_component.component_key_type,
                    coalesce(nullif(upper(btrim(effective_component.component_key_value)), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_code', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_unit_code', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'pay_code', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_unit_name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_unit_description', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_description', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_code_name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'additional_code_description', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'pay_code_name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'pay_code_description', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'description', ''))), ''), '~'),
                    coalesce(
                      nullif(
                        upper(
                          btrim(
                            case
                              when effective_component.component_key_type in ('TS_DAY', 'TS_TOTAL') then coalesce(nullif(btrim(coalesce(effective_component.source_basis_json->>'bucket_code', '')), ''), effective_component.component_key_value, effective_component.component_key_type)
                              when effective_component.component_key_type = 'ADDITIONAL_CODE' then coalesce(nullif(btrim(coalesce(effective_component.source_basis_json->>'additional_code', '')), ''), effective_component.component_key_value)
                              when effective_component.component_key_type = 'ADJUSTMENT_CODE' then coalesce(nullif(btrim(coalesce(effective_component.source_basis_json->>'adjustment_id', '')), ''), effective_component.component_key_value)
                              when effective_component.component_key_type = 'EXPENSE_CODE' then coalesce(nullif(btrim(coalesce(effective_component.source_basis_json->>'expense_code', '')), ''), effective_component.component_key_value)
                              else effective_component.component_key_value
                            end
                          )
                        ),
                        ''
                      ),
                      '~'
                    )
                  )
                  else concat_ws(
                    '|',
                    coalesce(nullif(effective_component.component_key_type, ''), '~'),
                    coalesce(nullif(upper(btrim(effective_component.component_key_value)), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'bucket_code', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'code', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'name', ''))), ''), '~'),
                    coalesce(nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'description', ''))), ''), '~')
                  )
                end,
                'source_pay_method', nullif(upper(btrim(coalesce(effective_component.source_pay_method, ''))), ''),
                'target_pay_method', nullif(upper(btrim(coalesce(effective_component.current_target_pay_method, ''))), ''),
                'source_rate', round(round(effective_component.source_rate, 2), 6),
                'source_charge_rate', round(round(effective_component.source_charge_rate, 2), 6)
              )
              || jsonb_build_object(
                'suggested_target_charge_rate', round(round(effective_component.source_charge_rate, 2), 6),
                'relevant_erni_pct', case when coalesce(effective_component.suggested_resolution_payload_json->>'relevant_erni_pct', effective_component.suggested_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round(coalesce(effective_component.suggested_resolution_payload_json->>'relevant_erni_pct', effective_component.suggested_resolution_result_json->>'relevant_erni_pct')::numeric, 6) else null end,
                'vat_rate_pct', case when coalesce(effective_component.suggested_resolution_payload_json->>'vat_rate_pct', effective_component.suggested_resolution_result_json->>'vat_rate_pct', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round(coalesce(effective_component.suggested_resolution_payload_json->>'vat_rate_pct', effective_component.suggested_resolution_result_json->>'vat_rate_pct')::numeric, 6) else null end,
                'umbrella_vat_chargeable', case
                  when lower(btrim(coalesce(effective_component.suggested_resolution_payload_json->>'umbrella_vat_chargeable', effective_component.suggested_resolution_result_json->>'umbrella_vat_chargeable', ''))) in ('true', 't', '1', 'yes', 'y', 'on') then true
                  when nullif(btrim(coalesce(effective_component.suggested_resolution_payload_json->>'umbrella_vat_chargeable', effective_component.suggested_resolution_result_json->>'umbrella_vat_chargeable', '')), '') is not null then false
                  else null
                end,
                'charge_basis', coalesce(
                  nullif(
                    upper(
                      btrim(
                        coalesce(
                          effective_component.suggested_resolution_payload_json->>'target_charge_basis',
                          effective_component.suggested_resolution_result_json->>'target_charge_basis',
                          effective_component.suggested_resolution_payload_json->>'charge_basis',
                          effective_component.suggested_resolution_result_json->>'charge_basis',
                          ''
                        )
                      )
                    ),
                    ''
                  ),
                  'FIXED_SOURCE_CHARGE'
                ),
                'taxability_context', nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'taxability', ''))), ''),
                'gross_net_context', nullif(upper(btrim(coalesce(effective_component.source_basis_json->>'gross_net_handling', ''))), ''),
                'reuse_mode', nullif(upper(btrim(coalesce(effective_component.suggested_resolution_payload_json->>'reuse_mode', effective_component.suggested_resolution_result_json->>'reuse_mode', ''))), '')
              )
            )::text
          ) as decision_context_key
        from transient_timesheet_component_review_rows_effective as effective_component
        where effective_component.requires_resolution is true
          and effective_component.is_actionable_resolution_row is true
          and effective_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          and upper(coalesce(effective_component.source_pay_method, '')) is distinct from upper(coalesce(effective_component.current_target_pay_method, ''))
          and effective_component.source_units is not null
          and coalesce(effective_component.source_units, 0) <> 0
          and effective_component.source_rate is not null
          and effective_component.source_charge_rate is not null
          and effective_component.component_key_type <> 'ADJUSTMENT_CODE'
  
  ;

  create temporary table timesheet_live_scope on commit drop as
        select distinct
          baseline_row.candidate_id,
          baseline_row.timesheet_id,
          baseline_row.client_id,
          timesheet_row.contract_id,
          case
            when timesheet_row.contract_id is not null then 'CONTRACT'
            else 'DAILY_SAME_BASIS'
          end as linked_scope_type
        from ts_baseline as baseline_row
        join public.timesheets as timesheet_row
          on timesheet_row.timesheet_id = baseline_row.timesheet_id
  
  ;

  create temporary table timesheet_linked_scope_counts on commit drop as
        select
          seed_scope.timesheet_id as seed_timesheet_id,
          count(*)::int as linked_timesheet_count,
          coalesce(jsonb_agg(target_scope.timesheet_id::text order by target_scope.timesheet_id::text), '[]'::jsonb) as linked_timesheet_ids_json
        from timesheet_live_scope as seed_scope
        join timesheet_live_scope as target_scope
          on target_scope.candidate_id = seed_scope.candidate_id
         and target_scope.timesheet_id <> seed_scope.timesheet_id
         and (
           (
             seed_scope.contract_id is not null
             and target_scope.contract_id is not distinct from seed_scope.contract_id
           )
           or (
             seed_scope.contract_id is null
             and target_scope.contract_id is null
             and target_scope.client_id is not distinct from seed_scope.client_id
           )
         )
        where exists (
          select 1
          from timesheet_case_actionable_basis as seed_basis
          join timesheet_case_actionable_basis as target_basis
            on target_basis.decision_context_key = seed_basis.decision_context_key
           and target_basis.timesheet_id = target_scope.timesheet_id
          where seed_basis.timesheet_id = seed_scope.timesheet_id
        )
        group by seed_scope.timesheet_id
  
  ;

  create temporary table timesheet_case_rollup on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          max(tcr.client_id::text)::uuid as client_id,
          max(tcr.ts_week_ending_date) as ts_week_ending_date,
          max(tcr.ts_client_name) as ts_client_name,
          max(tcr.ts_pay_method) as ts_pay_method,
          max(tcr.cand_pay_method) as cand_pay_method,
          max(tcr.cand_tms_ref) as cand_tms_ref,
          max(tcr.cand_display_name) as cand_display_name,
          max(tcr.cand_umbrella_id::text)::uuid as cand_umbrella_id,
          bool_or(tcr.umb_enabled) as umb_enabled,
          bool_or(tcr.umb_vat_chargeable) as umb_vat_chargeable,
          bool_or(tcr.cand_bank_hash is not null and btrim(tcr.cand_bank_hash) <> '') as candidate_has_bank_details,
          max(tcr.cand_bank_hash) as candidate_bank_hash,
          bool_or(tcr.umb_bank_hash is not null and btrim(tcr.umb_bank_hash) <> '') as umbrella_has_bank_details,
          max(tcr.umb_bank_hash) as umbrella_bank_hash,
          'BUCKETED'::text as resolution_family,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) as case_needs_resolution,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) = 0) as case_resolution_satisfied_now,
          'Suggested Rate'::text as resolution_action_label,
          jsonb_strip_nulls(
            jsonb_build_object(
              'resolve_all_linked_timesheets_default', (coalesce(max(tslc.linked_timesheet_count), 0) > 0),
              'linked_scope_type', case when coalesce(max(tslc.linked_timesheet_count), 0) > 0 then coalesce(max(tls.linked_scope_type), 'SELF_ONLY') else 'SELF_ONLY' end,
              'linked_timesheet_count', coalesce(max(tslc.linked_timesheet_count), 0),
              'linked_timesheet_ids', coalesce(min(tslc.linked_timesheet_ids_json::text)::jsonb, '[]'::jsonb),
              'contract_id', case when max(tls.contract_id::text) is null then null else max(tls.contract_id::text) end,
              'client_id', case when max(tls.client_id::text) is null then null else max(tls.client_id::text) end,
              'seed_timesheet_id', tcr.timesheet_id::text,
              'confirmation_text', case
                when coalesce(max(tslc.linked_timesheet_count), 0) > 0 then (
                  'Apply these decisions to ' || coalesce(max(tslc.linked_timesheet_count), 0)::text ||
                  ' additional eligible linked timesheet' || case when coalesce(max(tslc.linked_timesheet_count), 0) = 1 then '' else 's' end ||
                  ' in this current Banking Pay session?'
                )
                else null
              end
            )
          ) as linked_resolution_scope_json,
          round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) as case_total_amount_ex,
          round(
            case
              when count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0 then 0::numeric
              else sum(coalesce(tcr.ready_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0))
            end,
            2
          ) as safe_amount_ex,
          round(sum(case when coalesce(tcr.requires_resolution, false) = true then coalesce(tcr.blocked_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2) as unresolved_taxable_amount_ex,
          count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) as open_taxable_count,
          count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) as open_reimbursement_count,
          count(*) filter (where coalesce(tcr.requires_resolution, false) = true) as unresolved_taxable_count,
          0::integer as stale_count,
          (count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) > 0 and count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) > 0) as is_mixed_case,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) as is_blocked,
          round(sum(case when tcr.component_key_type in ('TS_DAY','TS_TOTAL') then coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2) as segments_total_ex,
          max(coalesce(td.delta_additional_pay_ex_vat, 0)) as delta_additional_pay_ex_vat,
          max(coalesce(td.delta_expenses_pay_ex_vat, 0)) as delta_expenses_pay_ex_vat,
          max(coalesce(td.delta_travel_pay_ex_vat, 0)) as delta_travel_pay_ex_vat,
          max(coalesce(td.delta_accommodation_pay_ex_vat, 0)) as delta_accommodation_pay_ex_vat,
          max(coalesce(td.delta_other_pay_ex_vat, 0)) as delta_other_pay_ex_vat,
          max(coalesce(td.delta_mileage_pay_ex_vat, 0)) as delta_mileage_pay_ex_vat,
          coalesce(min(td.segment_deltas_json::text)::jsonb, '[]'::jsonb) as segment_deltas_json,
          coalesce(min(td.adjustment_deltas_json::text)::jsonb, '[]'::jsonb) as adjustment_deltas_json,
          coalesce(min(td.additional_unit_deltas_json::text)::jsonb, '[]'::jsonb) as additional_unit_deltas_json,
          bool_or(coalesce(td.reservation_overrun_detected,false)) as reservation_overrun_detected,
          round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2) as payment_amount_ex_vat,
          round(
            case
              when max(tcr.cand_pay_method) = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2),
                  v_vat_rate_pct,
                  bool_or(tcr.umb_vat_chargeable)
                )->>'inc')::numeric
              else round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2)
            end,
            2
          ) as payment_amount_inc_vat,
          round(
            case
              when max(tcr.cand_pay_method) = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2),
                  v_vat_rate_pct,
                  bool_or(tcr.umb_vat_chargeable)
                )->>'inc')::numeric
              else round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2)
            end,
            2
          ) as payment_amount,
          jsonb_build_object(
            'case_key', ('timesheet:' || max(tcr.timesheet_id::text)),
            'case_type', 'TIMESHEET_PAYMENT',
            'resolution_family', 'BUCKETED',
            'case_needs_resolution', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0),
            'case_resolution_satisfied_now', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) = 0),
            'resolution_action_label', 'Suggested Rate',
            'has_resolved_rate', bool_or(tcr.approved_resolution_mode is not null),
            'resolved_rate_family', CASE WHEN bool_or(tcr.approved_resolution_mode is not null) THEN 'BUCKETED' ELSE NULL END,
            'resolved_rate_case_key', CASE WHEN bool_or(tcr.approved_resolution_mode is not null) THEN ('timesheet:' || max(tcr.timesheet_id::text)) ELSE NULL END,
            'resolved_rate_timesheet_id', CASE WHEN bool_or(tcr.approved_resolution_mode is not null) THEN max(tcr.timesheet_id::text) ELSE NULL END,
            'resolved_rate_candidate_id', CASE WHEN bool_or(tcr.approved_resolution_mode is not null) THEN max(tcr.candidate_id::text) ELSE NULL END,
            'resolved_rate_source_anchor_case_key', max(tcr.resolved_rate_source_anchor_case_key) FILTER (WHERE tcr.approved_resolution_mode is not null),
            'resolved_rate_source_anchor_timesheet_id', max(tcr.resolved_rate_source_anchor_timesheet_id::text) FILTER (WHERE tcr.approved_resolution_mode is not null),
            'resolved_rate_applied_via_linked_scope', bool_or(coalesce(tcr.resolved_rate_applied_via_linked_scope, false)),
            'resolved_rate_component_count', count(*) FILTER (WHERE tcr.approved_resolution_mode is not null),
            'resolved_rate_clear_payload_json', CASE
              WHEN bool_or(tcr.approved_resolution_mode is not null) THEN jsonb_build_object(
                'session_id', v_workbench_resolution_session_id::text,
                'candidate_id', max(tcr.candidate_id::text),
                'case_key', ('timesheet:' || max(tcr.timesheet_id::text)),
                'timesheet_id', max(tcr.timesheet_id::text),
                'linked_timesheet_id', max(tcr.timesheet_id::text),
                'resolution_family', 'BUCKETED'
              )
              ELSE NULL
            END,
            'linked_resolution_scope_json', jsonb_strip_nulls(
              jsonb_build_object(
                'resolve_all_linked_timesheets_default', (coalesce(max(tslc.linked_timesheet_count), 0) > 0),
                'linked_scope_type', case when coalesce(max(tslc.linked_timesheet_count), 0) > 0 then coalesce(max(tls.linked_scope_type), 'SELF_ONLY') else 'SELF_ONLY' end,
                'linked_timesheet_count', coalesce(max(tslc.linked_timesheet_count), 0),
                'linked_timesheet_ids', coalesce(min(tslc.linked_timesheet_ids_json::text)::jsonb, '[]'::jsonb),
                'contract_id', case when max(tls.contract_id::text) is null then null else max(tls.contract_id::text) end,
                'client_id', case when max(tls.client_id::text) is null then null else max(tls.client_id::text) end,
                'seed_timesheet_id', tcr.timesheet_id::text,
                'confirmation_text', case
                  when coalesce(max(tslc.linked_timesheet_count), 0) > 0 then (
                    'Apply these decisions to ' || coalesce(max(tslc.linked_timesheet_count), 0)::text ||
                    ' additional eligible linked timesheet' || case when coalesce(max(tslc.linked_timesheet_count), 0) = 1 then '' else 's' end ||
                    ' in this current Banking Pay session?'
                  )
                  else null
                end
              )
            ),
            'is_mixed_case', (count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) > 0 and count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) > 0),
            'open_taxable_count', count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),
            'open_reimbursement_count', count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum),
            'unresolved_taxable_count', count(*) filter (where coalesce(tcr.requires_resolution, false) = true),
            'stale_count', 0,
            'is_blocked', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0),
            'safe_amount_ex_vat', case when (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) then 0::numeric else round(sum(coalesce(tcr.ready_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) end,
            'blocked_case_amount_ex_vat', case when (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) then round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) else 0::numeric end,
            'unresolved_taxable_amount_ex_vat', round(sum(case when coalesce(tcr.requires_resolution, false) = true then coalesce(tcr.blocked_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2)
          ) as case_resolution_summary_json,
          coalesce(
            jsonb_agg(
              (
                jsonb_build_object(
                  'finance_component_id', null,
                  'source_family_key', tcr.source_family_key,
                  'component_key_type', tcr.component_key_type,
                  'component_key_value', tcr.component_key_value,
                  'label',
                    case
                      when tcr.component_key_type in ('TS_DAY','TS_TOTAL')
                        then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''), tcr.component_key_value, tcr.component_key_type)
                      when tcr.component_key_type = 'ADDITIONAL_CODE'
                        then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'additional_code','')), ''), tcr.component_key_value)
                      when tcr.component_key_type = 'ADJUSTMENT_CODE'
                        then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'adjustment_id','')), ''), tcr.component_key_value)
                      when tcr.component_key_type = 'EXPENSE_CODE'
                        then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'expense_code','')), ''), tcr.component_key_value)
                      else tcr.component_key_value
                    end,
                  'bucket_code', nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''),
                  'source_basis_fingerprint', md5(coalesce(tcr.source_basis_json::text, '{}'::text)),
                  'is_rate_bearing',
                    (
                      tcr.source_units is not null
                      and coalesce(tcr.source_units,0) <> 0
                      and tcr.source_rate is not null
                      and tcer.effective_source_charge_rate is not null
                      and tcr.component_key_type <> 'ADJUSTMENT_CODE'
                    ),
                  'classification', tcr.classification::text,
                  'source_pay_method', tcr.source_pay_method,
                  'current_target_pay_method', tcr.current_target_pay_method,
                  'component_amount_ex_vat', round(coalesce(tcr.component_amount_ex_vat,0),2),
                  'preview_component_amount_ex_vat', round(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0),2),
                  'ready_preview_amount_ex_vat', round(coalesce(tcr.ready_preview_amount_ex_vat, 0),2),
                  'blocked_preview_amount_ex_vat', round(coalesce(tcr.blocked_preview_amount_ex_vat, 0),2)
                )
                || jsonb_build_object(
                  'source_basis_json', jsonb_strip_nulls(
                    tcr.source_basis_json
                    || jsonb_build_object(
                      'source_rate', case when tcr.source_rate is null then null else round(tcr.source_rate,2) end,
                      'source_charge_rate',
                        case
                          when tcer.effective_source_charge_rate is null then null
                          else round(tcer.effective_source_charge_rate, 2)
                        end
                    )
                  ),
                  'saved_target_pay_method', case when tcr.approved_resolution_mode is null then null else tcr.current_target_pay_method end,
                  'saved_resolution_mode', case when tcr.approved_resolution_mode is null then null else tcr.approved_resolution_mode end,
                  'saved_resolution_payload_json', tcr.approved_resolution_payload_json,
                  'saved_resolution_result_json', tcr.approved_resolution_result_json,
                  'resolved_rate_resolution_id', case when tcr.resolved_rate_resolution_id is null then null else tcr.resolved_rate_resolution_id::text end,
                  'resolved_rate_applied_via_linked_scope', case when tcr.approved_resolution_mode is null then null else tcr.resolved_rate_applied_via_linked_scope end,
                  'resolved_rate_source_anchor_case_key', tcr.resolved_rate_source_anchor_case_key,
                  'resolved_rate_source_anchor_timesheet_id', case when tcr.resolved_rate_source_anchor_timesheet_id is null then null else tcr.resolved_rate_source_anchor_timesheet_id::text end,
                  'has_suggested_resolution', tcr.has_suggested_resolution,
                  'suggestion_provenance', tcr.suggestion_provenance,
                  'is_fresh_suggested_resolution', tcr.is_fresh_suggested_resolution,
                  'is_reusable_saved_resolution', tcr.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', tcr.is_stale_saved_resolution,
                  'suggested_resolution_payload_json', tcr.suggested_resolution_payload_json,
                  'suggested_resolution_result_json', tcr.suggested_resolution_result_json,
                  'source_units', tcr.source_units,
                  'target_units', case when ttrg.target_units is null then tcr.source_units else ttrg.target_units end,
                  'source_rate', case when tcr.source_rate is null then null else round(tcr.source_rate,2) end
                )
                || jsonb_build_object(
                  'source_charge_rate',
                    case
                      when tcer.effective_source_charge_rate is null then null
                      else round(tcer.effective_source_charge_rate, 2)
                    end,
                  'target_rate', case when tcr.target_rate is null then null else round(tcr.target_rate,2) end,
                  'source_pay_ex_vat', tcr.source_pay_ex_vat,
                  'source_charge_ex_vat', tcr.source_charge_component_ex_vat,
                  'source_margin_ex_vat', tcr.source_margin_ex_vat,
                  'target_pay_ex_vat', tcr.target_pay_ex_vat,
                  'target_charge_ex_vat', tcr.target_charge_ex_vat,
                  'target_margin_ex_vat', tcr.target_margin_ex_vat,
                  'margin_delta_ex_vat', tcr.margin_delta_ex_vat,
                  'suggestion_explanation_text', tcr.suggestion_explanation_text,
                  'component_fingerprint', tcr.component_fingerprint,
                  'is_resolution_stale', false,
                  'stale_reason', null,
                  'requires_resolution', coalesce(tcr.requires_resolution, false),
                  'resolution_state', tcr.resolution_state,
                  'is_actionable_resolution_row', coalesce(tcr.is_actionable_resolution_row, false),
                  'is_fixed_no_action_taxable_row', coalesce(tcr.is_fixed_no_action_taxable_row, false)
                )
              )
              order by
                case
                  when tcr.component_key_type in ('TS_DAY','TS_TOTAL') then 1
                  when tcr.component_key_type = 'ADDITIONAL_CODE' then 2
                  when tcr.component_key_type = 'ADJUSTMENT_CODE' then 3
                  when tcr.component_key_type = 'EXPENSE_CODE' then 4
                  else 9
                end,
                tcr.component_key_value,
                coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''), '')
            ),
            '[]'::jsonb
          ) as case_components_json
        from transient_timesheet_component_review_rows_effective tcr
        left join ts_deltas td
          on td.timesheet_id = tcr.timesheet_id
         and td.candidate_id = tcr.candidate_id
        left join timesheet_live_scope tls
          on tls.timesheet_id = tcr.timesheet_id
        left join timesheet_linked_scope_counts tslc
          on tslc.seed_timesheet_id = tcr.timesheet_id
        left join lateral (
          select
            case
              when tcr.source_charge_rate is not null then tcr.source_charge_rate
              when coalesce(tcr.source_basis_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$'
                then (tcr.source_basis_json->>'source_charge_rate')::numeric
              when coalesce(tcr.source_units,0) <> 0 and tcr.source_charge_component_ex_vat is not null
                then (tcr.source_charge_component_ex_vat / tcr.source_units)
              else null::numeric
            end as effective_source_charge_rate
        ) tcer on true
        left join lateral (
          select
            case
              when tcr.target_rate is not null and tcr.source_units is not null then round(tcr.source_units,6)
              else tcr.source_units
            end as target_units
        ) ttrg on true
        group by tcr.candidate_id, tcr.timesheet_id
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'timesheet_component_count', (select count(*)::int from timesheet_component_rows),
    'transient_review_component_count', (select count(*)::int from transient_timesheet_component_review_rows_effective),
    'timesheet_case_rollup_count', (select count(*)::int from timesheet_case_rollup)
  );
end;
$function$;

-- pay_preview_candidate_build_entitlement_rows(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_entitlement_rows(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_overpayment_sync_mode boolean := false;
  v_source_build_mode boolean := false;

  v_now timestamptz := now();
  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_line_work_ids_json jsonb := '[]'::jsonb;
  v_line_work_limit integer := 100;
  v_line_work_cursor_ordinal bigint := 0;
  v_line_work_selected_count integer := 0;
  v_line_work_error_count integer := 0;
  v_line_work_has_more boolean := false;
  v_line_work_next_cursor jsonb := NULL::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_overpayment_sync_mode := LOWER(BTRIM(COALESCE(v_context_json->>'overpayment_sync_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json#>>'{preview_decisions_json,overpayment_sync_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json->>'emit_raw_overpayment_components', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_context_json#>>'{preview_decisions_json,emit_raw_overpayment_components}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF jsonb_typeof(v_context_json->'line_work_ids') = 'array' THEN
    v_line_work_ids_json := COALESCE(v_context_json->'line_work_ids', '[]'::jsonb);
  ELSIF jsonb_typeof(v_context_json#>'{line_work,line_work_ids}') = 'array' THEN
    v_line_work_ids_json := COALESCE(v_context_json#>'{line_work,line_work_ids}', '[]'::jsonb);
  ELSIF jsonb_typeof(v_context_json#>'{line_work,page_ids}') = 'array' THEN
    v_line_work_ids_json := COALESCE(v_context_json#>'{line_work,page_ids}', '[]'::jsonb);
  ELSE
    v_line_work_ids_json := '[]'::jsonb;
  END IF;

  IF COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_line_work_limit := LEAST(GREATEST(COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit')::integer, 1), 100);
  ELSE
    v_line_work_limit := 100;
  END IF;

  BEGIN
    v_line_work_cursor_ordinal := COALESCE(
      NULLIF(BTRIM(COALESCE(v_context_json#>>'{line_work_cursor,last_line_ordinal}', '')), '')::bigint,
      NULLIF(BTRIM(COALESCE(v_context_json#>>'{line_work,cursor,last_line_ordinal}', '')), '')::bigint,
      NULLIF(BTRIM(COALESCE(v_context_json->>'last_line_ordinal', '')), '')::bigint,
      0
    );
  EXCEPTION WHEN OTHERS THEN
    v_line_work_cursor_ordinal := 0;
  END;

  IF v_workbench_session_id IS NOT NULL AND COALESCE(v_source_build_mode, false) IS NOT TRUE THEN
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS workbench_session
    WHERE workbench_session.id = v_workbench_session_id
      AND UPPER(BTRIM(COALESCE(workbench_session.status, ''))) = 'OPEN'
      AND workbench_session.discarded_at_utc IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_ENTITLEMENT_ROWS_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_ENTITLEMENT_ROWS_SESSION_NOT_OPEN',
                'session_id', v_workbench_session_id::text,
                'candidate_id', v_candidate_id::text
              )::text;
    END IF;

    DROP TABLE IF EXISTS pg_temp.pay_preview_candidate_line_work_economic_rows;

    CREATE TEMPORARY TABLE pay_preview_candidate_line_work_economic_rows ON COMMIT DROP AS
    WITH requested_line_work_ids AS (
      SELECT DISTINCT NULLIF(BTRIM(requested_line_work_id.value), '')::uuid AS line_work_id
      FROM jsonb_array_elements_text(COALESCE(v_line_work_ids_json, '[]'::jsonb)) AS requested_line_work_id(value)
      WHERE NULLIF(BTRIM(requested_line_work_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), source_line_work AS (
      SELECT
        candidate_line_work.id AS line_work_id,
        candidate_line_work.session_id,
        candidate_line_work.candidate_id,
        candidate_line_work.timesheet_id,
        candidate_line_work.line_key,
        candidate_line_work.line_ordinal,
        candidate_line_work.status,
        candidate_line_work.work_payload_json,
        candidate_line_work.result_row_json,
        COALESCE(candidate_line_work.work_payload_json->'line_json', candidate_line_work.result_row_json, '{}'::jsonb) AS live_source_json,
        ROW_NUMBER() OVER (ORDER BY candidate_line_work.line_ordinal, candidate_line_work.id) AS page_ordinal
      FROM public.banking_pay_workbench_candidate_line_work AS candidate_line_work
      WHERE candidate_line_work.session_id = v_workbench_session_id
        AND candidate_line_work.candidate_id = v_candidate_id
        AND (
          (
            jsonb_array_length(COALESCE(v_line_work_ids_json, '[]'::jsonb)) > 0
            AND EXISTS (
              SELECT 1
              FROM requested_line_work_ids AS requested_line_work
              WHERE requested_line_work.line_work_id = candidate_line_work.id
            )
          )
          OR (
            jsonb_array_length(COALESCE(v_line_work_ids_json, '[]'::jsonb)) = 0
            AND candidate_line_work.line_ordinal > COALESCE(v_line_work_cursor_ordinal, 0)
          )
        )
      ORDER BY candidate_line_work.line_ordinal, candidate_line_work.id
      LIMIT (v_line_work_limit + 1)
    ), selected_line_work AS (
      SELECT source_line_work.*
      FROM source_line_work
      WHERE source_line_work.page_ordinal <= v_line_work_limit
    )
    SELECT
      selected_line_work.line_work_id,
      selected_line_work.session_id,
      selected_line_work.candidate_id,
      selected_line_work.timesheet_id,
      selected_line_work.line_key,
      selected_line_work.line_ordinal,
      selected_line_work.status,
      selected_line_work.live_source_json,
      key_res.key_type,
      key_res.key_value,
      key_res.key_resolution_source,
      key_res.key_resolution_failure_reason,
      selected_line_work.page_ordinal
    FROM selected_line_work
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => selected_line_work.timesheet_id,
      p_live_source_json => selected_line_work.live_source_json,
      p_item_type => UPPER(NULLIF(BTRIM(COALESCE(
        selected_line_work.work_payload_json->>'item_type',
        selected_line_work.live_source_json->>'item_type',
        selected_line_work.live_source_json->>'line_type',
        selected_line_work.live_source_json->>'component_type',
        ''
      )), '')),
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(selected_line_work.live_source_json->>'work_date', selected_line_work.live_source_json->>'date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(selected_line_work.live_source_json->>'work_date', selected_line_work.live_source_json->>'date', '')), '')::date
        ELSE NULL::date
      END
    ) AS key_res ON true;

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE key_type IS NULL OR key_value IS NULL)::integer
    INTO v_line_work_selected_count,
         v_line_work_error_count
    FROM pg_temp.pay_preview_candidate_line_work_economic_rows AS economic_rows;

    SELECT EXISTS (
             SELECT 1
             FROM public.banking_pay_workbench_candidate_line_work AS candidate_line_work
             WHERE candidate_line_work.session_id = v_workbench_session_id
               AND candidate_line_work.candidate_id = v_candidate_id
               AND candidate_line_work.line_ordinal > COALESCE((
                 SELECT MAX(economic_rows.line_ordinal)
                 FROM pg_temp.pay_preview_candidate_line_work_economic_rows AS economic_rows
               ), v_line_work_cursor_ordinal)
           )
    INTO v_line_work_has_more;

    IF COALESCE(v_line_work_has_more, false) THEN
      SELECT jsonb_build_object('last_line_ordinal', MAX(economic_rows.line_ordinal))
      INTO v_line_work_next_cursor
      FROM pg_temp.pay_preview_candidate_line_work_economic_rows AS economic_rows;
    ELSE
      v_line_work_next_cursor := NULL::jsonb;
    END IF;

    UPDATE public.banking_pay_workbench_candidate_line_work AS candidate_line_work
    SET work_payload_json = COALESCE(candidate_line_work.work_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'economic_key', jsonb_build_object(
              'timesheet_id', CASE WHEN economic_rows.timesheet_id IS NULL THEN NULL ELSE economic_rows.timesheet_id::text END,
              'key_type', economic_rows.key_type,
              'key_value', economic_rows.key_value,
              'key_resolution_source', economic_rows.key_resolution_source,
              'key_resolution_failure_reason', economic_rows.key_resolution_failure_reason
            ),
            'policy_x_pre_draft_key_resolved', (economic_rows.key_type IS NOT NULL AND economic_rows.key_value IS NOT NULL)
          ),
        error_json = CASE
          WHEN economic_rows.key_type IS NULL OR economic_rows.key_value IS NULL THEN jsonb_build_object(
            'code', COALESCE(economic_rows.key_resolution_failure_reason, 'PRE_DRAFT_KEY_RESOLUTION_FAILED'),
            'message', 'Unable to resolve pre-draft economic key for supplied line-work row.',
            'line_work_id', economic_rows.line_work_id::text,
            'line_key', economic_rows.line_key
          )
          ELSE candidate_line_work.error_json
        END,
        updated_at_utc = v_now
    FROM pg_temp.pay_preview_candidate_line_work_economic_rows AS economic_rows
    WHERE candidate_line_work.id = economic_rows.line_work_id;

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'session_id', v_workbench_session_id::text,
      'row_backed_line_work', true,
      'processed_supplied_line_work_page_only', true,
      'line_work_limit', v_line_work_limit,
      'line_work_cursor_ordinal', COALESCE(v_line_work_cursor_ordinal, 0),
      'line_work_processed_count', COALESCE(v_line_work_selected_count, 0),
      'economic_row_count', COALESCE(v_line_work_selected_count, 0),
      'economic_key_error_count', COALESCE(v_line_work_error_count, 0),
      'next_cursor', v_line_work_next_cursor,
      'has_more', COALESCE(v_line_work_has_more, false)
    );
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.ts_baseline') is null then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.segment_status, pg_temp.blocked_items_all, pg_temp.blocked_items, pg_temp.blocked_items_snoozed, pg_temp.do_not_pay_all, pg_temp.do_not_pay_items, pg_temp.do_not_pay_items_snoozed, pg_temp.ts_deltas, pg_temp.ts_itemised;

  create temporary table segment_status on commit drop as
        -- Economic-key segment reconciliation:
        -- segment identity is retained only for UI continuity and snooze matching.
        -- Outstanding and reservation subtraction stay in the economic entitlement keyspace
        -- (TS_DAY => work_date, TS_TOTAL => TOTAL).
        with
        cur_segments as (
          select
            b.timesheet_id,
            b.candidate_id,
            cur_seg.seg_ord as source_seg_ord,
            nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')),'') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')),'') as ref_num,
            nullif(btrim(coalesce(cur_seg.seg->>'date','')),'') as work_date,
            coalesce(nullif(cur_seg.seg->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
            round(coalesce(nullif(cur_seg.seg->>'pay_amount','')::numeric,0),2) as pay_amount_ex_vat,
            round(coalesce(nullif(cur_seg.seg->>'charge_amount','')::numeric, nullif(cur_seg.seg->>'charge_ex_vat','')::numeric,0),2) as charge_amount_ex_vat,
            case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end as source_units,
            null::numeric as source_rate,
            case
              when nullif(cur_seg.seg->>'charge_rate','') is not null then round(nullif(cur_seg.seg->>'charge_rate','')::numeric, 6)
              when nullif(cur_seg.seg->>'charge_unit_rate','') is not null then round(nullif(cur_seg.seg->>'charge_unit_rate','')::numeric, 6)
              when (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) is not null
               and (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) <> 0
              then round(
                round(coalesce(nullif(cur_seg.seg->>'charge_amount','')::numeric, nullif(cur_seg.seg->>'charge_ex_vat','')::numeric,0),2) / (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end),
                6
              )
              else null::numeric
            end as source_charge_rate,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'date','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')),'')
            ) as segment_stable_key,
            case
              when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
              else 'TS_TOTAL'::text
            end as component_key_type,
            case
              when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null
                then nullif(btrim(coalesce(cur_seg.seg->>'date','')), '')
              else 'TOTAL'
            end as component_key_value
          from ts_baseline b
          join lateral jsonb_array_elements(coalesce(b.current_segments_json,'[]'::jsonb)) with ordinality as cur_seg(seg, seg_ord) on true
          where cur_seg.seg is not null
            and jsonb_typeof(cur_seg.seg) = 'object'
        ),
        bas_segments as (
          select
            b.timesheet_id,
            b.candidate_id,
            bas_seg.seg_ord as source_seg_ord,
            nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')),'') as segment_id,
            nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')),'') as ref_num,
            nullif(btrim(coalesce(bas_seg.seg->>'date','')),'') as work_date,
            coalesce(nullif(bas_seg.seg->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
            round(coalesce(nullif(bas_seg.seg->>'pay_amount','')::numeric,0),2) as pay_amount_ex_vat,
            round(coalesce(nullif(bas_seg.seg->>'charge_amount','')::numeric, nullif(bas_seg.seg->>'charge_ex_vat','')::numeric,0),2) as charge_amount_ex_vat,
            case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end as source_units,
            null::numeric as source_rate,
            case
              when nullif(bas_seg.seg->>'charge_rate','') is not null then round(nullif(bas_seg.seg->>'charge_rate','')::numeric, 6)
              when nullif(bas_seg.seg->>'charge_unit_rate','') is not null then round(nullif(bas_seg.seg->>'charge_unit_rate','')::numeric, 6)
              when (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) is not null
               and (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) <> 0
              then round(
                round(coalesce(nullif(bas_seg.seg->>'charge_amount','')::numeric, nullif(bas_seg.seg->>'charge_ex_vat','')::numeric,0),2) / (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end),
                6
              )
              else null::numeric
            end as source_charge_rate,
            coalesce(
              nullif(btrim(coalesce(bas_seg.seg->>'segment_stable_key','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'date','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')),'')
            ) as segment_stable_key,
            case
              when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
              else 'TS_TOTAL'::text
            end as component_key_type,
            case
              when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null
                then nullif(btrim(coalesce(bas_seg.seg->>'date','')), '')
              else 'TOTAL'
            end as component_key_value
          from ts_baseline b
          join lateral jsonb_array_elements(coalesce(b.base_json->'segments','[]'::jsonb)) with ordinality as bas_seg(seg, seg_ord) on true
          where bas_seg.seg is not null
            and jsonb_typeof(bas_seg.seg) = 'object'
        ),
        active_settled_key_baselines as (
          select
            ts_base.timesheet_id,
            ts_base.candidate_id,
            upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')) as component_key_type,
            nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '') as component_key_value,
            round(
              coalesce(
                sum(
                  coalesce(
                    nullif(btrim(coalesce(active_component.component_json->>'amount_ex_vat','')), '')::numeric,
                    0
                  )
                ),
                0
              ),
              2
            ) as baseline_amount_ex_vat,
            round(
              coalesce(
                sum(
                  coalesce(
                    nullif(btrim(coalesce(active_component.component_json->>'amount_inc_vat','')), '')::numeric,
                    0
                  )
                ),
                0
              ),
              2
            ) as baseline_amount_inc_vat
          from ts_baseline ts_base
          join lateral jsonb_array_elements(
            case
              when coalesce(ts_base.has_active_settled_artifact_baseline, false) = true
               and jsonb_typeof(coalesce(ts_base.active_settled_artifact_components_json, '[]'::jsonb)) = 'array'
              then coalesce(ts_base.active_settled_artifact_components_json, '[]'::jsonb)
              else '[]'::jsonb
            end
          ) as active_component(component_json) on true
          where active_component.component_json is not null
            and jsonb_typeof(active_component.component_json) = 'object'
            and upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')) is not null
            and nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '') is not null
          group by
            ts_base.timesheet_id,
            ts_base.candidate_id,
            upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')),
            nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '')
        ),
        cur_ranked as (
          select
            cs.timesheet_id,
            cs.candidate_id,
            cs.source_seg_ord,
            cs.segment_id,
            cs.ref_num,
            cs.work_date,
            cs.exclude_from_pay,
            cs.pay_amount_ex_vat,
            cs.charge_amount_ex_vat,
            cs.source_units,
            cs.source_rate,
            cs.source_charge_rate,
            cs.segment_stable_key,
            cs.component_key_type,
            cs.component_key_value,
            row_number() over (
              partition by cs.timesheet_id, cs.candidate_id, cs.component_key_type, cs.component_key_value
              order by cs.source_seg_ord nulls last, cs.segment_id nulls last, cs.ref_num nulls last
            ) as bucket_row_ord
          from cur_segments cs
        ),
        bas_ranked as (
          select
            bs.timesheet_id,
            bs.candidate_id,
            bs.source_seg_ord,
            bs.segment_id,
            bs.ref_num,
            bs.work_date,
            bs.exclude_from_pay,
            bs.pay_amount_ex_vat,
            bs.charge_amount_ex_vat,
            bs.source_units,
            bs.source_rate,
            bs.source_charge_rate,
            bs.segment_stable_key,
            bs.component_key_type,
            bs.component_key_value,
            row_number() over (
              partition by bs.timesheet_id, bs.candidate_id, bs.component_key_type, bs.component_key_value
              order by bs.source_seg_ord nulls last, bs.segment_id nulls last, bs.ref_num nulls last
            ) as bucket_row_ord
          from bas_segments bs
        ),
        ids as (
          select distinct
            cr.timesheet_id,
            cr.candidate_id,
            cr.component_key_type,
            cr.component_key_value,
            cr.bucket_row_ord
          from cur_ranked cr
          union
          select distinct
            br.timesheet_id,
            br.candidate_id,
            br.component_key_type,
            br.component_key_value,
            br.bucket_row_ord
          from bas_ranked br
        ),
        agg as (
          select
            i.timesheet_id,
            i.candidate_id,
            i.component_key_type,
            i.component_key_value,
            i.bucket_row_ord,
            max(cr.segment_id) as cur_segment_id,
            max(br.segment_id) as bas_segment_id,
            max(coalesce(cr.ref_num, br.ref_num)) as ref_num,
            max(coalesce(cr.work_date, br.work_date)) as work_date,
            max(coalesce(cr.segment_stable_key, br.segment_stable_key)) as segment_stable_key,
            max(cr.source_seg_ord) as cur_source_seg_ord,
            max(br.source_seg_ord) as bas_source_seg_ord,
            bool_or(coalesce(cr.exclude_from_pay,false)) as cur_excluded,
            max(cr.source_units) as cur_source_units,
            max(cr.source_rate) as cur_source_rate,
            max(cr.source_charge_rate) as cur_source_charge_rate,
            round(sum(case when cr.bucket_row_ord = i.bucket_row_ord then (case when coalesce(cr.exclude_from_pay,false) then 0 else coalesce(cr.pay_amount_ex_vat,0) end) else 0 end), 2) as cur_payable_ex_vat,
            round(sum(case when br.bucket_row_ord = i.bucket_row_ord then (case when coalesce(br.exclude_from_pay,false) then 0 else coalesce(br.pay_amount_ex_vat,0) end) else 0 end), 2) as bas_payable_ex_vat,
            round(sum(case when cr.bucket_row_ord = i.bucket_row_ord then (case when coalesce(cr.exclude_from_pay,false) then 0 else coalesce(cr.charge_amount_ex_vat,0) end) else 0 end), 2) as cur_charge_ex_vat,
            round(sum(case when br.bucket_row_ord = i.bucket_row_ord then (case when coalesce(br.exclude_from_pay,false) then 0 else coalesce(br.charge_amount_ex_vat,0) end) else 0 end), 2) as bas_charge_ex_vat
          from ids i
          left join cur_ranked cr
            on cr.timesheet_id = i.timesheet_id
           and cr.candidate_id = i.candidate_id
           and cr.component_key_type = i.component_key_type
           and cr.component_key_value = i.component_key_value
           and cr.bucket_row_ord = i.bucket_row_ord
          left join bas_ranked br
            on br.timesheet_id = i.timesheet_id
           and br.candidate_id = i.candidate_id
           and br.component_key_type = i.component_key_type
           and br.component_key_value = i.component_key_value
           and br.bucket_row_ord = i.bucket_row_ord
          group by i.timesheet_id, i.candidate_id, i.component_key_type, i.component_key_value, i.bucket_row_ord
        ),
        agg_active_baseline as (
          select
            agg_rows.timesheet_id,
            agg_rows.candidate_id,
            agg_rows.component_key_type,
            agg_rows.component_key_value,
            agg_rows.bucket_row_ord,
            agg_rows.cur_segment_id,
            agg_rows.bas_segment_id,
            agg_rows.ref_num,
            agg_rows.work_date,
            agg_rows.segment_stable_key,
            agg_rows.cur_source_seg_ord,
            agg_rows.bas_source_seg_ord,
            agg_rows.cur_excluded,
            agg_rows.cur_source_units,
            agg_rows.cur_source_rate,
            agg_rows.cur_source_charge_rate,
            agg_rows.cur_payable_ex_vat,
            agg_rows.bas_payable_ex_vat,
            agg_rows.cur_charge_ex_vat,
            agg_rows.bas_charge_ex_vat,
            active_key_baseline.baseline_amount_ex_vat as active_settled_key_baseline_ex_vat,
            active_key_baseline.baseline_amount_inc_vat as active_settled_key_baseline_inc_vat,
            round(
              case
                when active_key_baseline.baseline_amount_ex_vat is null then 0
                when coalesce(agg_rows.cur_payable_ex_vat, 0) <= 0 then 0
                else greatest(
                  least(
                    coalesce(agg_rows.cur_payable_ex_vat, 0),
                    greatest(
                      coalesce(active_key_baseline.baseline_amount_ex_vat, 0)
                      - coalesce(
                          sum(coalesce(agg_rows.cur_payable_ex_vat, 0)) over (
                            partition by agg_rows.timesheet_id, agg_rows.candidate_id, agg_rows.component_key_type, agg_rows.component_key_value
                            order by agg_rows.bucket_row_ord
                            rows between unbounded preceding and 1 preceding
                          ),
                          0
                        ),
                      0
                    )
                  ),
                  0
                )
              end,
              2
            ) as active_settled_allocated_baseline_ex_vat
          from agg agg_rows
          left join active_settled_key_baselines active_key_baseline
            on active_key_baseline.timesheet_id = agg_rows.timesheet_id
           and active_key_baseline.candidate_id = agg_rows.candidate_id
           and active_key_baseline.component_key_type = agg_rows.component_key_type
           and active_key_baseline.component_key_value = agg_rows.component_key_value
        ),
        agg_effective_baseline as (
          select
            active_rows.timesheet_id,
            active_rows.candidate_id,
            active_rows.component_key_type,
            active_rows.component_key_value,
            active_rows.bucket_row_ord,
            active_rows.cur_segment_id,
            active_rows.bas_segment_id,
            active_rows.ref_num,
            active_rows.work_date,
            active_rows.segment_stable_key,
            active_rows.cur_source_seg_ord,
            active_rows.bas_source_seg_ord,
            active_rows.cur_excluded,
            active_rows.cur_source_units,
            active_rows.cur_source_rate,
            active_rows.cur_source_charge_rate,
            active_rows.cur_payable_ex_vat,
            active_rows.bas_payable_ex_vat,
            active_rows.cur_charge_ex_vat,
            active_rows.bas_charge_ex_vat,
            active_rows.active_settled_key_baseline_ex_vat,
            active_rows.active_settled_key_baseline_inc_vat,
            active_rows.active_settled_allocated_baseline_ex_vat,
            round(
              case
                when active_rows.active_settled_key_baseline_ex_vat is not null
                then coalesce(active_rows.active_settled_allocated_baseline_ex_vat, 0)
                else coalesce(active_rows.bas_payable_ex_vat, 0)
              end,
              2
            ) as effective_bas_payable_ex_vat,
            round(
              case
                when active_rows.active_settled_key_baseline_ex_vat is not null then
                  case
                    when coalesce(active_rows.cur_payable_ex_vat, 0) <= 0 then 0
                    else round(
                      coalesce(active_rows.cur_charge_ex_vat, 0)
                      * (coalesce(active_rows.active_settled_allocated_baseline_ex_vat, 0) / nullif(coalesce(active_rows.cur_payable_ex_vat, 0), 0)),
                      2
                    )
                  end
                else coalesce(active_rows.bas_charge_ex_vat, 0)
              end,
              2
            ) as effective_bas_charge_ex_vat
          from agg_active_baseline active_rows
        ),
        calc as (
          select
            b.candidate_id,
            b.timesheet_id,
            b.ts_booking_id as booking_id,
            coalesce(a.cur_segment_id, a.bas_segment_id) as segment_id,
            coalesce(a.cur_segment_id, a.bas_segment_id) as segment_key,
            a.segment_stable_key,
            a.component_key_type,
            a.component_key_value,
            a.bucket_row_ord,
            coalesce(a.cur_source_seg_ord, a.bas_source_seg_ord) as segment_sort_ord,
            a.work_date,
            a.ref_num,
            a.cur_source_units as source_units,
            a.cur_source_rate as source_rate,
            a.cur_source_charge_rate as source_charge_rate,
            a.cur_excluded,
            coalesce(b.has_active_overpayment_case,false) as has_active_overpayment_case,
            b.require_reference_to_pay,
            coalesce(b.is_forced_advance,false) as is_forced_advance,
            round(
              coalesce(a.cur_payable_ex_vat,0)
              - coalesce(a.effective_bas_payable_ex_vat,0),
              2
            ) as raw_delta_before_reservation_ex,
            round(
              coalesce(a.cur_charge_ex_vat,0)
              - coalesce(a.effective_bas_charge_ex_vat,0),
              2
            ) as raw_delta_charge_ex_vat,
            round(
              case
                when (
                  coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) < 0
                )
                then 0
                when (
                  b.require_reference_to_pay = true
                  and coalesce(b.is_forced_advance,false) = false
                  and a.cur_excluded = false
                  and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) > 0
                )
                then 0
                else round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                )
              end,
              2
            ) as preview_base_eff_delta_ex,
            round(
              case
                when (
                  coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) < 0
                )
                then 0
                when round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                ) > 0
                then round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                )
                else 0
              end,
              2
            ) as allocatable_delta_ex,
            coalesce(rss.reserved_amount_ex_vat,0) as reserved_bucket_amount_ex_vat
          from ts_baseline b
          join agg_effective_baseline a
            on a.timesheet_id = b.timesheet_id
           and a.candidate_id = b.candidate_id
          left join reserved_segment_sums rss
            on rss.timesheet_id = b.timesheet_id
           and rss.component_key_type = a.component_key_type
           and rss.component_key_value = a.component_key_value
        ),
        alloc as (
          select
            c.candidate_id,
            c.timesheet_id,
            c.booking_id,
            c.segment_id,
            c.segment_key,
            c.segment_stable_key,
            c.component_key_type,
            c.component_key_value,
            c.bucket_row_ord,
            c.segment_sort_ord,
            c.work_date,
            c.ref_num,
            c.source_units,
            c.source_rate,
            c.source_charge_rate,
            c.cur_excluded,
            c.has_active_overpayment_case,
            c.require_reference_to_pay,
            c.is_forced_advance,
            c.raw_delta_before_reservation_ex,
            c.raw_delta_charge_ex_vat,
            c.preview_base_eff_delta_ex,
            c.reserved_bucket_amount_ex_vat,
            round(
              case
                when coalesce(c.allocatable_delta_ex,0) <= 0 then 0
                else greatest(
                  least(
                    coalesce(c.reserved_bucket_amount_ex_vat,0)
                    - coalesce(
                        sum(coalesce(c.allocatable_delta_ex,0)) over (
                          partition by c.timesheet_id, c.component_key_type, c.component_key_value
                          order by c.segment_sort_ord nulls last, c.bucket_row_ord, c.segment_id nulls last
                          rows between unbounded preceding and 1 preceding
                        ),
                        0
                      ),
                    c.allocatable_delta_ex
                  ),
                  0
                )
              end,
              2
            ) as allocated_reserved_amount_ex_vat
          from calc c
        )
        select
          a.candidate_id,
          a.timesheet_id,
          a.booking_id,
          a.segment_id,
          a.segment_key,
          a.segment_stable_key,
          a.component_key_type,
          a.component_key_value,
          a.bucket_row_ord,
          a.segment_sort_ord,
          a.work_date,
          a.ref_num,
          a.source_units,
          a.source_rate,
          a.source_charge_rate,
          a.raw_delta_before_reservation_ex,
          a.raw_delta_charge_ex_vat,
          a.preview_base_eff_delta_ex,
          round(
            case
              when (
                a.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) < 0
              )
              then 0
              else round(
                a.raw_delta_before_reservation_ex
                - a.allocated_reserved_amount_ex_vat,
                2
              )
            end,
            2
          ) as delta_pay_ex_vat,
          round(
            case
              when (
                a.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) < 0
              )
              then 0
              when (
                a.require_reference_to_pay = true
                and a.is_forced_advance = false
                and a.cur_excluded = false
                and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) > 0
              )
              then 0
              else round(
                a.raw_delta_before_reservation_ex
                - a.allocated_reserved_amount_ex_vat,
                2
              )
            end,
            2
          ) as eff_delta_ex,
          case
            when round(a.raw_delta_before_reservation_ex, 2) = 0 then round(a.raw_delta_charge_ex_vat, 2)
            else round(
              a.raw_delta_charge_ex_vat
              * (
                  (
                    case
                      when (
                        a.has_active_overpayment_case = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                        and round(
                          a.raw_delta_before_reservation_ex
                          - a.allocated_reserved_amount_ex_vat,
                          2
                        ) < 0
                      )
                      then 0
                      when (
                        a.require_reference_to_pay = true
                        and a.is_forced_advance = false
                        and a.cur_excluded = false
                        and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                        and round(
                          a.raw_delta_before_reservation_ex
                          - a.allocated_reserved_amount_ex_vat,
                          2
                        ) > 0
                      )
                      then 0
                      else round(
                        a.raw_delta_before_reservation_ex
                        - a.allocated_reserved_amount_ex_vat,
                        2
                      )
                    end
                  ) / nullif(round(a.raw_delta_before_reservation_ex, 2),0)
                ),
              2
            )
          end as eff_delta_charge_ex_vat,
          (
            coalesce(a.cur_excluded,false) = true
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) <> 0
          ) as is_do_not_pay,
          (
            a.require_reference_to_pay = true
            and a.is_forced_advance = false
            and a.cur_excluded = false
            and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) > 0
          ) as is_ref_missing,
          (
            a.require_reference_to_pay = true
            and a.is_forced_advance = false
            and a.cur_excluded = false
            and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) > 0
          ) as is_blocked,
          null::uuid as snooze_id,
          null::date as snooze_until_date,
          null::text as note
        from alloc a
  
  ;



  WITH policy_x_segment_rows AS (
    SELECT
      segment_row.ctid AS row_ctid,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM segment_status AS segment_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => segment_row.timesheet_id,
      p_live_source_json => jsonb_strip_nulls(
        jsonb_build_object(
          'timesheet_id', segment_row.timesheet_id::text,
          'item_type', 'SEGMENT_DELTA',
          'work_date', segment_row.work_date,
          'date', segment_row.work_date,
          'segment_id', segment_row.segment_id,
          'segment_key', segment_row.segment_key,
          'segment_stable_key', segment_row.segment_stable_key,
          'ref_num', segment_row.ref_num,
          'source_units', segment_row.source_units,
          'source_rate', segment_row.source_rate,
          'source_charge_rate', segment_row.source_charge_rate
        )
      ),
      p_item_type => 'SEGMENT_DELTA',
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(segment_row.work_date, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(segment_row.work_date, '')), '')::date
        ELSE NULL::date
      END
    ) AS policy_key ON true
  )
  UPDATE segment_status AS segment_row
  SET component_key_type = policy_x_segment_rows.resolved_key_type,
      component_key_value = policy_x_segment_rows.resolved_key_value
  FROM policy_x_segment_rows
  WHERE segment_row.ctid = policy_x_segment_rows.row_ctid
    AND policy_x_segment_rows.resolved_key_type IS NOT NULL
    AND policy_x_segment_rows.resolved_key_value IS NOT NULL;

  create temporary table blocked_items_all on commit drop as
        select
          ss.candidate_id,
          ss.timesheet_id,
          ss.booking_id,
          ss.segment_id,
          ss.segment_stable_key,
          ss.ref_num,
          ss.delta_pay_ex_vat as blocked_delta_ex,
          sn.snooze_id,
          sn.snooze_until_date,
          sn.note
        from segment_status ss
        left join active_segment_snoozes sn
          on sn.candidate_id = ss.candidate_id
         and sn.snooze_kind = 'BLOCKED_TIMESHEET'
         and (
           (sn.booking_id is not null and ss.booking_id is not null and sn.booking_id = ss.booking_id and sn.segment_stable_key is not distinct from ss.segment_stable_key)
           or (sn.booking_id is null and sn.timesheet_id is not distinct from ss.timesheet_id and sn.segment_id is not distinct from ss.segment_id)
         )
        where ss.is_blocked = true
  
  ;

  create temporary table blocked_items on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.booking_id,
          b.segment_id,
          b.segment_stable_key,
          b.ref_num,
          b.blocked_delta_ex,
          b.snooze_id
        from blocked_items_all b
        where b.snooze_id is null
  
  ;

  create temporary table blocked_items_snoozed on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.booking_id,
          b.segment_id,
          b.segment_stable_key,
          b.ref_num,
          b.blocked_delta_ex,
          b.snooze_id,
          b.snooze_until_date,
          b.note
        from blocked_items_all b
        where b.snooze_id is not null
          and b.snooze_until_date is not null
  
  ;

  create temporary table do_not_pay_all on commit drop as
        select
          ss.candidate_id,
          ss.timesheet_id,
          ss.booking_id,
          ss.segment_id,
          ss.segment_stable_key,
          ss.ref_num as ref_num,
          ss.delta_pay_ex_vat as raw_delta_ex,
          sn.snooze_id,
          sn.snooze_until_date,
          sn.note
        from segment_status ss
        left join active_segment_snoozes sn
          on sn.candidate_id = ss.candidate_id
         and sn.snooze_kind = 'DO_NOT_PAY'
         and (
           (sn.booking_id is not null and ss.booking_id is not null and sn.booking_id = ss.booking_id and sn.segment_stable_key is not distinct from ss.segment_stable_key)
           or (sn.booking_id is null and sn.timesheet_id is not distinct from ss.timesheet_id and sn.segment_id is not distinct from ss.segment_id)
         )
        where ss.is_do_not_pay = true
  
  ;

  create temporary table do_not_pay_items on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.booking_id,
          d.segment_id,
          d.segment_stable_key,
          d.ref_num,
          d.raw_delta_ex,
          d.snooze_id
        from do_not_pay_all d
        where d.snooze_id is null
           or coalesce(d.raw_delta_ex,0) <> 0
  
  ;

  create temporary table do_not_pay_items_snoozed on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.booking_id,
          d.segment_id,
          d.segment_stable_key,
          d.ref_num,
          d.raw_delta_ex,
          d.snooze_id,
          d.snooze_until_date,
          d.note
        from do_not_pay_all d
        where d.snooze_id is not null
          and d.snooze_until_date is not null
          and coalesce(d.raw_delta_ex,0) = 0
  
  ;

  create temporary table ts_deltas on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,

          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,

          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,

          b.umb_enabled,
          b.umb_vat_chargeable,

          b.cand_bank_hash,
          b.umb_bank_hash,

          -- SEGMENTS: reservation math stays in the economic entitlement keyspace,
          -- while stable identifiers are retained only for UI continuity.
          -- Ordinality must be based on the original preview rows (before preview-row reservation subtraction),
          -- otherwise preview_seg:<timesheet_id>:<ord> draft rows will not line up with the rows they reserved.
          coalesce((
            with ss_rows as (
              select
                ss.segment_id,
                ss.segment_key,
                ss.segment_stable_key,
                ss.component_key_type,
                ss.component_key_value,
                ss.work_date,
                ss.ref_num,
                ss.preview_base_eff_delta_ex,
                ss.eff_delta_ex,
                ss.eff_delta_charge_ex_vat,
                ss.source_units,
                ss.source_rate,
                ss.source_charge_rate,
                ss.bucket_row_ord,
                ss.segment_sort_ord,
                row_number() over (
                  partition by ss.timesheet_id
                  order by ss.segment_sort_ord nulls last, ss.bucket_row_ord, ss.component_key_type, ss.component_key_value, ss.segment_id nulls last
                ) as seg_ord
              from segment_status ss
              where ss.timesheet_id = b.timesheet_id
                and ss.preview_base_eff_delta_ex <> 0
            ),
            ss_effective as (
              select
                ssr.segment_id,
                ssr.segment_key,
                ssr.segment_stable_key,
                ssr.component_key_type,
                ssr.component_key_value,
                ssr.work_date,
                ssr.ref_num,
                ssr.eff_delta_charge_ex_vat,
                ssr.source_units,
                ssr.source_rate,
                ssr.source_charge_rate,
                ssr.bucket_row_ord,
                ssr.segment_sort_ord,
                round(
                  ssr.eff_delta_ex - coalesce(rpso.reserved_amount_ex_vat,0),
                  2
                ) as eff_delta_ex_after_reserved
              from ss_rows ssr
              left join reserved_preview_segment_ords rpso
                on rpso.timesheet_id = b.timesheet_id
               and rpso.preview_seg_ord = ssr.seg_ord
            )
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', sse.segment_id,
                'segment_key', sse.segment_key,
                'segment_stable_key', sse.segment_stable_key,
                'component_key_type', sse.component_key_type,
                'component_key_value', sse.component_key_value,
                'work_date', sse.work_date,
                'ref_num', sse.ref_num,
                'delta_pay_ex_vat', sse.eff_delta_ex_after_reserved,
                'delta_charge_ex_vat', sse.eff_delta_charge_ex_vat,
                'source_units', sse.source_units
              )
              order by sse.segment_sort_ord nulls last, sse.bucket_row_ord, sse.component_key_type, sse.component_key_value, sse.segment_id nulls last
            )
            from ss_effective sse
            where sse.eff_delta_ex_after_reserved <> 0
          ), '[]'::jsonb) as segment_deltas_json,

          -- ADDITIONAL (total): outstanding = current - baseline - reserved
          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_additional_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'additional'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_additional_pay_ex_vat,0)
                - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'additional'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_additional_pay_ex_vat,
          round(coalesce(b.current_additional_charge_ex_vat,0) - coalesce(nullif(b.base_json->>'additional_charge_ex_vat','')::numeric,0),2) as delta_additional_charge_ex_vat,

          -- ADDITIONAL (per code): best-effort from additional_units_json + baseline snapshot + reserved breakdowns
          coalesce((
            with
            cur as (
              select
                nullif(btrim(coalesce(e.key,'')), '') as code,
                round(
                  coalesce(
                    nullif(e.value->>'pay_ex_vat','')::numeric,
                    nullif(e.value->>'amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0)
                      * coalesce(nullif(e.value->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(e.value->>'charge_ex_vat','')::numeric, nullif(e.value->>'charge_amount_ex_vat','')::numeric, nullif(e.value->>'charge_amount','')::numeric, (coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0) * coalesce(nullif(e.value->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric) as source_units,
                coalesce(nullif(e.value->>'rate','')::numeric, nullif(e.value->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(e.value->>'charge_rate','')::numeric, nullif(e.value->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_each(case when jsonb_typeof(b.current_additional_units_json) = 'object' then b.current_additional_units_json else '{}'::jsonb end) e
              where jsonb_typeof(coalesce(b.current_additional_units_json,'{}'::jsonb)) = 'object'
                and nullif(btrim(coalesce(e.key,'')), '') is not null
            ),
            cur_arr as (
              select
                nullif(btrim(coalesce(elem->>'code','')),'') as code,
                round(
                  coalesce(
                    nullif(elem->>'pay_ex_vat','')::numeric,
                    nullif(elem->>'amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0)
                      * coalesce(nullif(elem->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(elem->>'charge_ex_vat','')::numeric, nullif(elem->>'charge_amount_ex_vat','')::numeric, nullif(elem->>'charge_amount','')::numeric, (coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0) * coalesce(nullif(elem->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric) as source_units,
                coalesce(nullif(elem->>'rate','')::numeric, nullif(elem->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(elem->>'charge_rate','')::numeric, nullif(elem->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_array_elements(case when jsonb_typeof(b.current_additional_units_json) = 'array' then b.current_additional_units_json else '[]'::jsonb end) elem
              where jsonb_typeof(coalesce(b.current_additional_units_json,'[]'::jsonb)) = 'array'
                and nullif(btrim(coalesce(elem->>'code','')),'') is not null
            ),
            cur_all as (
              select * from cur
              union all
              select * from cur_arr
            ),
            bas as (
              select
                nullif(btrim(coalesce(e.key,'')), '') as code,
                round(
                  coalesce(
                    nullif(e.value->>'pay_ex_vat','')::numeric,
                    nullif(e.value->>'amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0)
                      * coalesce(nullif(e.value->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(e.value->>'charge_ex_vat','')::numeric, nullif(e.value->>'charge_amount_ex_vat','')::numeric, nullif(e.value->>'charge_amount','')::numeric, (coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0) * coalesce(nullif(e.value->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric) as source_units,
                coalesce(nullif(e.value->>'rate','')::numeric, nullif(e.value->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(e.value->>'charge_rate','')::numeric, nullif(e.value->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_each(case when jsonb_typeof(b.base_json->'additional_units_json') = 'object' then b.base_json->'additional_units_json' else '{}'::jsonb end) e
              where jsonb_typeof(coalesce(b.base_json->'additional_units_json','{}'::jsonb)) = 'object'
                and nullif(btrim(coalesce(e.key,'')), '') is not null
            ),
            bas_arr as (
              select
                nullif(btrim(coalesce(elem->>'code','')),'') as code,
                round(
                  coalesce(
                    nullif(elem->>'pay_ex_vat','')::numeric,
                    nullif(elem->>'amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0)
                      * coalesce(nullif(elem->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(elem->>'charge_ex_vat','')::numeric, nullif(elem->>'charge_amount_ex_vat','')::numeric, nullif(elem->>'charge_amount','')::numeric, (coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0) * coalesce(nullif(elem->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric) as source_units,
                coalesce(nullif(elem->>'rate','')::numeric, nullif(elem->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(elem->>'charge_rate','')::numeric, nullif(elem->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_array_elements(case when jsonb_typeof(b.base_json->'additional_units_json') = 'array' then b.base_json->'additional_units_json' else '[]'::jsonb end) elem
              where jsonb_typeof(coalesce(b.base_json->'additional_units_json','[]'::jsonb)) = 'array'
                and nullif(btrim(coalesce(elem->>'code','')),'') is not null
            ),
            bas_all as (
              select * from bas
              union all
              select * from bas_arr
            ),
            ids as (
              select distinct
                x.code
              from (
                select code from cur_all where code is not null
                union
                select code from bas_all where code is not null
                union
                select rab.code from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code is not null
              ) x
            ),
            rows as (
              select
                i.code,
                round(
                  coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                  - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0),
                  2
                ) as raw_delta_amount_ex_vat,
                round(
                  coalesce((select sum(ca.charge_amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                  - coalesce((select sum(ba.charge_amount_ex_vat) from bas_all ba where ba.code = i.code),0),
                  2
                ) as raw_delta_charge_ex_vat,
                coalesce((select max(ca.source_units) from cur_all ca where ca.code = i.code),(select max(ba.source_units) from bas_all ba where ba.code = i.code)) as source_units,
                coalesce((select max(ca.source_rate) from cur_all ca where ca.code = i.code),(select max(ba.source_rate) from bas_all ba where ba.code = i.code)) as source_rate,
                coalesce((select max(ca.source_charge_rate) from cur_all ca where ca.code = i.code),(select max(ba.source_charge_rate) from bas_all ba where ba.code = i.code)) as source_charge_rate,
                case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                      - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0)
                      - coalesce((select rab.reserved_amount_ex_vat from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code = i.code limit 1),0),
                      2
                    ) < 0
                  )
                  then 0::numeric
                  else round(
                    coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                    - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0)
                    - coalesce((select rab.reserved_amount_ex_vat from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code = i.code limit 1),0),
                    2
                  )
                end as delta_amount_ex_vat
              from ids i
            )
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'code', r.code,
                  'delta_pay_ex_vat', r.delta_amount_ex_vat,
                  'delta_charge_ex_vat', case when coalesce(r.raw_delta_amount_ex_vat,0) = 0 then r.raw_delta_charge_ex_vat else round(r.raw_delta_charge_ex_vat * (r.delta_amount_ex_vat / nullif(r.raw_delta_amount_ex_vat,0)), 2) end,
                  'source_units', r.source_units,
                  'source_rate', r.source_rate,
                  'source_charge_rate', r.source_charge_rate
                )
                order by r.code
              ) filter (where r.delta_amount_ex_vat <> 0),
              '[]'::jsonb
            )
            from rows r
          ), '[]'::jsonb) as additional_unit_deltas_json,

          -- EXPENSES/TRAVEL/etc (outstanding = current - baseline - reserved)
          -- EXPENSES is an aggregate fallback only. If any specific expense bucket
          -- exists in current, baseline, or reserved state, the specific buckets are
          -- the canonical payable components and the aggregate must not also pay out.
          round(
            case
              when (
                coalesce(b.current_travel_pay_ex_vat,0) <> 0
                or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                or coalesce(b.current_other_pay_ex_vat,0) <> 0
                or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                or exists (
                  select 1
                  from reserved_by_source_ref r_specific_expense
                  where r_specific_expense.timesheet_id = b.timesheet_id
                    and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                    and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                )
              )
              then 0
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_expenses_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'expenses'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_expenses_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'expenses'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_expenses_pay_ex_vat,
          round(
            case
              when (
                coalesce(b.current_travel_pay_ex_vat,0) <> 0
                or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                or coalesce(b.current_other_pay_ex_vat,0) <> 0
                or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                or exists (
                  select 1
                  from reserved_by_source_ref r_specific_expense
                  where r_specific_expense.timesheet_id = b.timesheet_id
                    and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                    and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                )
              )
              then 0
              else coalesce(b.current_expenses_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,expenses_charge_ex_vat}','')::numeric,0)
            end,
            2
          ) as delta_expenses_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_travel_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'travel'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_travel_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'travel'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_travel_pay_ex_vat,
          round(coalesce(b.current_travel_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,travel_charge_ex_vat}','')::numeric,0),2) as delta_travel_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_accommodation_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'accommodation'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_accommodation_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'accommodation'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_accommodation_pay_ex_vat,
          round(coalesce(b.current_accommodation_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,accommodation_charge_ex_vat}','')::numeric,0),2) as delta_accommodation_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_other_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'other'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_other_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'other'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_other_pay_ex_vat,
          round(coalesce(b.current_other_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,other_charge_ex_vat}','')::numeric,0),2) as delta_other_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                and round(
                  coalesce(b.current_mileage_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'mileage'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_mileage_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'mileage'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_mileage_pay_ex_vat,
          round(coalesce(b.current_mileage_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,mileage_charge_ex_vat}','')::numeric,0),2) as delta_mileage_charge_ex_vat,

          -- ADJUSTMENTS: outstanding = current - baseline - reserved (source_ref='adj:<id>')
          coalesce((
            with
            cur as (
              select
                a.adj_id,
                round(coalesce(a.delta_pay_ex_vat,0),2) as amt
              from adj a
              where a.timesheet_id = b.timesheet_id
            ),
            bas as (
              select
                nullif(btrim(coalesce(x->>'adj_id','')),'')::uuid as adj_id,
                round(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0),2) as amt
              from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
              where nullif(btrim(coalesce(x->>'adj_id','')),'') is not null
            ),
            ids as (
              select distinct adj_id from cur
              union
              select distinct adj_id from bas
            ),
            rows_base as (
              select
                i.adj_id,
                round(
                  coalesce((select c.amt from cur c where c.adj_id = i.adj_id limit 1),0)
                  - coalesce((select x.amt from bas x where x.adj_id = i.adj_id limit 1),0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = ('adj:'||i.adj_id::text)
                      limit 1
                    ), 0),
                  2
                ) as delta_amt
              from ids i
            ),
            preview_reserved_total as (
              select
                round(
                  coalesce(sum(abs(rpso.reserved_amount_ex_vat)),0),
                  2
                ) as reserved_abs
              from reserved_preview_segment_ords rpso
              where rpso.timesheet_id = b.timesheet_id
                and coalesce(rpso.reserved_amount_ex_vat,0) < 0
            ),
            rows_negative as (
              select
                rb.adj_id,
                rb.delta_amt,
                row_number() over (order by rb.adj_id::text) as neg_ord,
                coalesce(
                  sum(abs(rb.delta_amt)) over (
                    order by rb.adj_id::text
                    rows between unbounded preceding and 1 preceding
                  ),
                  0
                ) as prev_neg_abs
              from rows_base rb
              where rb.delta_amt < 0
            ),
            rows_negative_applied as (
              select
                rn.adj_id,
                round(
                  rn.delta_amt
                  + greatest(
                      least(
                        coalesce(prt.reserved_abs,0) - rn.prev_neg_abs,
                        abs(rn.delta_amt)
                      ),
                      0
                    ),
                  2
                ) as delta_amt
              from rows_negative rn
              cross join preview_reserved_total prt
            ),
            rows as (
              select
                rb.adj_id,
                case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and coalesce(rna.delta_amt, rb.delta_amt) < 0
                  )
                  then 0::numeric
                  else coalesce(rna.delta_amt, rb.delta_amt)
                end as delta_amt
              from rows_base rb
              left join rows_negative_applied rna
                on rna.adj_id = rb.adj_id
            )
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'adj_id', r.adj_id,
                  'delta_pay_ex_vat', r.delta_amt
                )
                order by r.adj_id::text
              ) filter (where r.delta_amt <> 0),
              '[]'::jsonb
            )
            from rows r
          ), '[]'::jsonb) as adjustment_deltas_json,

          -- Reservation integrity (preview-only signal): reserved > remaining previewable truth
          (
            coalesce((
              select rtb.reserved_total_ex_vat
              from reserved_total_by_timesheet rtb
              where rtb.timesheet_id = b.timesheet_id
              limit 1
            ), 0)
            >
            (
              coalesce((
                select round(
                  sum(
                    case
                      when coalesce(ss.raw_delta_before_reservation_ex,0) < 0
                           and coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                        then 0
                      else coalesce(ss.raw_delta_before_reservation_ex,0)
                    end
                  ),
                  2
                )
                from segment_status ss
                where ss.timesheet_id = b.timesheet_id
              ), 0)
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_additional_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_additional_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.current_travel_pay_ex_vat,0) <> 0
                    or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                    or coalesce(b.current_other_pay_ex_vat,0) <> 0
                    or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                    or exists (
                      select 1
                      from reserved_by_source_ref r_specific_expense
                      where r_specific_expense.timesheet_id = b.timesheet_id
                        and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                        and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                    )
                  )
                  then 0
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_expenses_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_expenses_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_travel_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_travel_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_accommodation_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_accommodation_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_other_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_other_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce(b.current_mileage_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_mileage_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true AND COALESCE(v_overpayment_sync_mode, false) IS NOT TRUE
                    and round(
                      coalesce((
                        select round(sum(coalesce(a.delta_pay_ex_vat,0)),2)
                        from adj a
                        where a.timesheet_id = b.timesheet_id
                      ),0)
                      - coalesce((
                        select round(sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)),2)
                        from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
                      ),0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce((
                      select round(sum(coalesce(a.delta_pay_ex_vat,0)),2)
                      from adj a
                      where a.timesheet_id = b.timesheet_id
                    ),0)
                    - coalesce((
                      select round(sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)),2)
                      from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
                    ),0),
                    2
                  )
                end
            ) + 0.01
          ) as reservation_overrun_detected
        from ts_baseline b
  
  ;

  create temporary table ts_itemised on commit drop as
        select
          d2.*,
          d2.total_ex as payment_amount_ex_vat,
          round(
            case
              when d2.ts_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(d2.total_ex, v_vat_rate_pct, d2.umb_vat_chargeable)->>'inc')::numeric
              else d2.total_ex
            end,
            2
          ) as payment_amount_inc_vat,
          round(
            case
              when d2.ts_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(d2.total_ex, v_vat_rate_pct, d2.umb_vat_chargeable)->>'inc')::numeric
              else d2.total_ex
            end,
            2
          ) as payment_amount
        from (
          select
            d_calc.*,
            round(coalesce(d_calc.taxable_total_ex,0) + coalesce(d_calc.reimbursement_total_ex,0), 2) as total_ex
          from (
            select
              d1.*,
              round(
                coalesce((select sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)) from jsonb_array_elements(d1.segment_deltas_json) x),0)
                + coalesce(d1.delta_additional_pay_ex_vat,0)
                + coalesce((select sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)) from jsonb_array_elements(d1.adjustment_deltas_json) x),0),
                2
              ) as taxable_total_ex,
              round(
                coalesce(d1.delta_expenses_pay_ex_vat,0)
                + coalesce(d1.delta_travel_pay_ex_vat,0)
                + coalesce(d1.delta_accommodation_pay_ex_vat,0)
                + coalesce(d1.delta_other_pay_ex_vat,0)
                + coalesce(d1.delta_mileage_pay_ex_vat,0),
                2
              ) as reimbursement_total_ex
            from ts_deltas d1
          ) d_calc
        ) d2
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'segment_status_count', (select count(*)::int from segment_status),
    'blocked_item_count', (select count(*)::int from blocked_items),
    'do_not_pay_item_count', (select count(*)::int from do_not_pay_items),
    'timesheet_delta_count', (select count(*)::int from ts_deltas),
    'timesheet_itemised_count', (select count(*)::int from ts_itemised)
  );
end;
$function$;

-- pay_preview_candidate_build_finance_case_baseline(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_finance_case_baseline(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_workbench_resolution_session_id uuid := null::uuid;
  v_workbench_resolution_session_id_text text := null::text;
begin
  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_START',
    jsonb_build_object(
      'candidate_id', p_candidate_id,
      'context_pay_date', p_context_json->>'pay_date',
      'context_pay_week_start', p_context_json->>'pay_week_start'
    ),
    'pay_preview_finance',
    COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_workbench_resolution_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_resolution_session_id',
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,resolution_session_id}',
    v_context_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_workbench_resolution_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_resolution_session_id := v_workbench_resolution_session_id_text::uuid;

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS resolution_session
    WHERE resolution_session.id = v_workbench_resolution_session_id
      AND UPPER(BTRIM(COALESCE(resolution_session.status, ''))) = 'OPEN'
      AND resolution_session.discarded_at_utc IS NULL
      AND (
        v_candidate_id = ANY(COALESCE(resolution_session.scope_candidate_ids, ARRAY[]::uuid[]))
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS resolution_scope
          WHERE resolution_scope.session_id = resolution_session.id
            AND resolution_scope.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS resolution_preview_row
          WHERE resolution_preview_row.session_id = resolution_session.id
            AND resolution_preview_row.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS resolution_line_work
          WHERE resolution_line_work.session_id = resolution_session.id
            AND resolution_line_work.candidate_id = v_candidate_id
        )
      );

    IF NOT FOUND THEN
      v_workbench_resolution_session_id := NULL::uuid;
    END IF;
  ELSE
    v_workbench_resolution_session_id := NULL::uuid;
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.cand_payee') is null then
    perform public.pay_preview_candidate_build_payee_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_bucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay_alloc, pg_temp.finance_case_taxable_channel_restructure_resolution, pg_temp.finance_case_resolution_owner_state, pg_temp.finance_case_resolution_rollup;

  create temporary table finance_case_repaid_wtd on commit drop as
        select
          nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid as finance_case_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as repaid_wtd_ex
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        left join public.pay_bank_transfers pbt
          on pbt.id = pbi.pay_bank_transfer_id
        where coalesce(pbi.is_voided, false) = false
          and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
          and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
          and pbi.repayment_week_start = v_week_start
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
          and not exists (
            select 1
            from public.pay_payment_correction_items pci_repaid_wtd
            where pci_repaid_wtd.pay_batch_item_id = pbi.id
              and pci_repaid_wtd.status = 'APPLIED'
              and pci_repaid_wtd.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
            or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
            or pbt.completed_at_utc is not null
            or exists (
              select 1
              from public.pay_advance_reservations par_repaid_wtd
              where par_repaid_wtd.pay_batch_item_id = pbi.id
                and (
                  upper(btrim(coalesce(par_repaid_wtd.status, ''))) = 'SETTLED'
                  or par_repaid_wtd.settled_at_utc is not null
                )
            )
          )
        group by nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid

  ;


  /* Policy X: recovery headroom is pre-draft live truth, but it must use the
     same central economic-outstanding authority that preview materialisation
     uses.  Raw timesheet deltas whose settled baseline is already exhausted
     must not create funds from which a recovery can be taken. */
  drop table if exists pg_temp.candidate_authoritative_recovery_headroom;

  create temporary table candidate_authoritative_recovery_headroom on commit drop as
        with recovery_timesheet_scope as (
          select
            cr.candidate_id,
            coalesce(
              array_agg(distinct tcr.timesheet_id order by tcr.timesheet_id)
                filter (where tcr.timesheet_id is not null),
              array[]::uuid[]
            ) as timesheet_ids
          from candidate_rollup cr
          left join timesheet_case_rollup_payable tcr
            on tcr.candidate_id = cr.candidate_id
           and coalesce(tcr.is_blocked, false) = false
          group by cr.candidate_id
        )
        select
          rts.candidate_id,
          round(
            coalesce(
              sum(greatest(coalesce(oc.outstanding_ex_vat, 0), 0)),
              0
            ),
            2
          )::numeric(12,2) as authoritative_recovery_headroom_ex
        from recovery_timesheet_scope rts
        left join lateral public._pay_outstanding_components(
          rts.timesheet_ids,
          null::uuid
        ) oc on true
        group by rts.candidate_id

  ;


create temporary table finance_case_recovery_rows_base on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          upper(coalesce(cr.cand_pay_method,'')) as candidate_pay_method,
          round(greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),2)::numeric(12,2) as run_earnings_headroom_ex,
          round(
            greatest(
              coalesce(pwb.paid_wtd_before,0)
              + greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),
              0
            ),
            2
          )::numeric(12,2) as run_take_home_before,
          round(greatest(coalesce(c.min_take_home_wtd,0),0),2)::numeric(12,2) as default_take_home_floor,
          vfcr.payout_status,
          vfcr.created_at,
          case
            when vfcr.minimum_earnings_threshold is null then null::numeric(12,2)
            else round(greatest(vfcr.minimum_earnings_threshold,0),2)::numeric(12,2)
          end as minimum_earnings_threshold,
          case
            when vfcr.take_home_floor_override is null then null::numeric(12,2)
            else round(greatest(vfcr.take_home_floor_override,0),2)::numeric(12,2)
          end as take_home_floor_override,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE'
                 and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'OVERPAYMENT'
                then greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                else 0::numeric
              end,
              0::numeric
            ),
            2
          )::numeric(12,2) as nominal_due_amount
        from finance_case_baseline_scope vfcr
        join candidate_rollup cr
          on cr.candidate_id = vfcr.candidate_id
        join candidate_authoritative_recovery_headroom carh
          on carh.candidate_id = vfcr.candidate_id
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join paid_wtd_before pwb
          on pwb.candidate_id = vfcr.candidate_id
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        where vfcr.case_type in ('PAYMENT_ADVANCE','MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          and (
            (vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID')
            or vfcr.case_type in ('MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          )

  ;

  create temporary table manual_debt_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table manual_debt_recovery_allocations on commit drop as
        select
          mdra.candidate_id,
          mdra_alloc.finance_case_id,
          round(coalesce(mdra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            mdrr.candidate_id,
            max(mdrr.run_earnings_headroom_ex) as run_earnings_headroom_ex,
            max(mdrr.run_take_home_before) as run_take_home_before,
            max(mdrr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', mdrr.sort_order,
                'finance_case_id', mdrr.finance_case_id::text,
                'case_type', mdrr.case_type::text,
                'payout_status', case when mdrr.payout_status is null then null else mdrr.payout_status::text end,
                'nominal_due_amount', mdrr.nominal_due_amount,
                'minimum_earnings_threshold', mdrr.minimum_earnings_threshold,
                'take_home_floor_override', mdrr.take_home_floor_override
              )
              order by mdrr.sort_order, mdrr.finance_case_id
            ) as recovery_rows_json
          from manual_debt_recovery_rows mdrr
          group by mdrr.candidate_id
        ) mdra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => mdra.recovery_rows_json,
          p_run_earnings_headroom => mdra.run_earnings_headroom_ex,
          p_run_take_home_headroom => mdra.run_take_home_before,
          p_default_take_home_floor => mdra.default_take_home_floor
        ) mdra_alloc

  ;

  create temporary table manual_debt_recovery_totals on commit drop as
        select
          mdra.candidate_id,
          round(sum(mdra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from manual_debt_recovery_allocations mdra
        group by mdra.candidate_id

  ;

  create temporary table overpayment_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'OVERPAYMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table overpayment_recovery_allocations on commit drop as
        select
          opra.candidate_id,
          opra_alloc.finance_case_id,
          round(coalesce(opra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            oprr.candidate_id,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_take_home_before
              end
            ) as run_take_home_before,
            max(oprr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', oprr.sort_order,
                'finance_case_id', oprr.finance_case_id::text,
                'case_type', 'MANUAL_DEBT_ADJUSTMENT',
                'payout_status', null,
                'nominal_due_amount', oprr.nominal_due_amount,
                'minimum_earnings_threshold', oprr.minimum_earnings_threshold,
                'take_home_floor_override', oprr.take_home_floor_override
              )
              order by oprr.sort_order, oprr.finance_case_id
            ) as recovery_rows_json
          from overpayment_recovery_rows oprr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = oprr.candidate_id
          group by oprr.candidate_id
        ) opra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => opra.recovery_rows_json,
          p_run_earnings_headroom => opra.run_earnings_headroom_ex,
          p_run_take_home_headroom => opra.run_take_home_before,
          p_default_take_home_floor => opra.default_take_home_floor
        ) opra_alloc

  ;

  create temporary table overpayment_recovery_totals on commit drop as
        select
          opra.candidate_id,
          round(sum(opra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from overpayment_recovery_allocations opra
        group by opra.candidate_id

  ;

  create temporary table payment_advance_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'PAYMENT_ADVANCE'
          and upper(coalesce(fcrrb.payout_status::text,'')) = 'PAID'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table payment_advance_recovery_allocations on commit drop as
        select
          para.candidate_id,
          para_alloc.finance_case_id,
          round(coalesce(para_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            parr.candidate_id,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_take_home_before
              end
            ) as run_take_home_before,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', parr.sort_order,
                'finance_case_id', parr.finance_case_id::text,
                'case_type', parr.case_type::text,
                'payout_status', case when parr.payout_status is null then null else parr.payout_status::text end,
                'nominal_due_amount', parr.nominal_due_amount,
                'minimum_earnings_threshold', parr.minimum_earnings_threshold,
                'take_home_floor_override', parr.take_home_floor_override
              )
              order by parr.sort_order, parr.finance_case_id
            ) as recovery_rows_json
          from payment_advance_recovery_rows parr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = parr.candidate_id
          left join overpayment_recovery_totals oprt
            on oprt.candidate_id = parr.candidate_id
          group by parr.candidate_id
        ) para
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => para.recovery_rows_json,
          p_run_earnings_headroom => para.run_earnings_headroom_ex,
          p_run_take_home_headroom => para.run_take_home_before,
          p_default_take_home_floor => null::numeric
        ) para_alloc

  ;

  create temporary table finance_case_protected_allocations on commit drop as
        select
          mdra.finance_case_id,
          mdra.protected_recoverable_amount
        from manual_debt_recovery_allocations mdra

        union all

        select
          opra.finance_case_id,
          opra.protected_recoverable_amount
        from overpayment_recovery_allocations opra

        union all

        select
          para.finance_case_id,
          para.protected_recoverable_amount
        from payment_advance_recovery_allocations para

  ;

  create temporary table finance_case_payee_readiness on commit drop as
        select
          f0.finance_case_id,
          f0.payee_entity_kind,
          f0.payee_entity_id,
          f0.bank_details_hash,
          f0.beneficiary_name,
          f0.sort_code,
          f0.account_number,
          case
            when f0.account_number is null or btrim(coalesce(f0.account_number,'')) = '' then null
            else lpad(right(f0.account_number, 4), greatest(length(f0.account_number), 4), '*')
          end as masked_bank_account,
          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash) as name_check_has_override,
          (bpm.payee_id is not null) as payee_map_present,
          (
            f0.payee_entity_id is null
            or f0.bank_details_hash is null
            or btrim(coalesce(f0.bank_details_hash,'')) = ''
            or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
            or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
            or nullif(btrim(coalesce(f0.account_number,'')), '') is null
          ) as is_missing_bank_details,
          (
            v_need_name_check = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
          ) as is_name_check_blocked,
          (
            v_requires_payee_map = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and bpm.payee_id is null
          ) as is_payee_map_blocked,
          (
            (case
              when (
                f0.payee_entity_id is null
                or f0.bank_details_hash is null
                or btrim(coalesce(f0.bank_details_hash,'')) = ''
                or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                or nullif(btrim(coalesce(f0.account_number,'')), '') is null
              )
              then jsonb_build_array('BLOCKED_BANK_DETAILS')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_need_name_check = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
                and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
              )
              then jsonb_build_array('BLOCKED_NAME_CHECK')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_requires_payee_map = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and bpm.payee_id is null
              )
              then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes
        from (
          select
            vfcr.finance_case_id,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
              else 'CANDIDATE'
            end as payee_entity_kind,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c.umbrella_id
              else vfcr.candidate_id
            end as payee_entity_id,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.bank_details_hash
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.bank_details_hash
              else c.bank_details_hash
            end as bank_details_hash,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.beneficiary_name
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.name
              else coalesce(c.account_holder, c.display_name)
            end as beneficiary_name,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.sort_code
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.sort_code
              else c.sort_code
            end as sort_code,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.account_number
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.account_number
              else c.account_number
            end as account_number
          from finance_case_baseline_scope vfcr
          join public.candidates c
            on c.id = vfcr.candidate_id
          left join public.umbrellas u
            on u.id = c.umbrella_id
          left join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
        ) f0
        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = f0.payee_entity_kind
         and bnc.entity_id = f0.payee_entity_id
         and bnc.bank_details_hash is not distinct from f0.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = f0.payee_entity_kind
         and bpm.entity_id = f0.payee_entity_id
         and bpm.bank_details_hash is not distinct from f0.bank_details_hash

  ;

  create temporary table finance_case_component_rows on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          pfc.id as finance_component_id,
          pfc.source_family_key,
          pfc.component_key_type,
          pfc.component_key_value,
          pfc.classification,
          upper(coalesce(pfc.source_pay_method, '')) as source_pay_method,
          upper(coalesce(cp.cand_pay_method, '')) as current_target_pay_method,
          cp.umb_vat_chargeable,
          pfc.source_basis_json,
          round(coalesce(pfc.source_amount, 0), 2) as source_amount,
          round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_source_amount,
          pfc.saved_target_pay_method,
          pfc.saved_resolution_mode,
          pfc.saved_resolution_payload_json,
          pfc.saved_resolution_result_json,
          pfc.resolution_fingerprint,
          pfc.is_resolution_stale,
          pfc.stale_reason,
          public.pay_finance_component_fingerprint(
            pfc.source_family_key,
            pfc.component_key_type,
            pfc.component_key_value,
            pfc.classification,
            upper(coalesce(pfc.source_pay_method, '')),
            upper(coalesce(cp.cand_pay_method, '')),
            coalesce(pfc.source_basis_json, '{}'::jsonb),
            round(coalesce(pfc.source_amount, 0), 2),
            case
              when coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
                then coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct')::numeric
              else v_erni_pct
            end,
            coalesce(pfc.saved_resolution_payload_json, pfc.saved_resolution_result_json, '{}'::jsonb)
          ) as current_component_fingerprint
        from finance_case_baseline_scope vfcr
        join cand_payee cp
          on cp.candidate_id = vfcr.candidate_id
        join public.pay_finance_case_components pfc
          on pfc.finance_case_id = vfcr.finance_case_id
         and pfc.closed_at_utc is null
         and coalesce(pfc.remaining_source_amount, 0) > 0

  ;


  WITH policy_x_finance_component_rows AS (
    SELECT
      component_row.ctid AS row_ctid,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value
    FROM finance_case_component_rows AS component_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_live_source_json => COALESCE(component_row.source_basis_json, '{}'::jsonb)
        || jsonb_build_object(
          'finance_case_id', component_row.finance_case_id::text,
          'finance_component_id', CASE WHEN component_row.finance_component_id IS NULL THEN NULL ELSE component_row.finance_component_id::text END,
          'source_family_key', component_row.source_family_key,
          'component_key_type', component_row.component_key_type,
          'component_key_value', component_row.component_key_value,
          'classification', CASE WHEN component_row.classification IS NULL THEN NULL ELSE component_row.classification::text END,
          'item_type', CASE
            WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE'
             AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
            ELSE 'ADJUSTMENT_DELTA'
          END
        ),
      p_item_type => CASE
        WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE'
         AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        ELSE 'ADJUSTMENT_DELTA'
      END,
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '')::date
        ELSE NULL::date
      END
    ) AS policy_key ON true
  )
  UPDATE finance_case_component_rows AS component_row
  SET component_key_type = policy_x_finance_component_rows.resolved_key_type,
      component_key_value = policy_x_finance_component_rows.resolved_key_value,
      current_component_fingerprint = public.pay_finance_component_fingerprint(
        component_row.source_family_key,
        policy_x_finance_component_rows.resolved_key_type,
        policy_x_finance_component_rows.resolved_key_value,
        component_row.classification,
        component_row.source_pay_method,
        component_row.current_target_pay_method,
        COALESCE(component_row.source_basis_json, '{}'::jsonb),
        round(COALESCE(component_row.source_amount, 0), 2),
        CASE
          WHEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
            THEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct')::numeric
          ELSE v_erni_pct
        END,
        COALESCE(component_row.saved_resolution_payload_json, component_row.saved_resolution_result_json, '{}'::jsonb)
      )
  FROM policy_x_finance_component_rows
  WHERE component_row.ctid = policy_x_finance_component_rows.row_ctid
    AND policy_x_finance_component_rows.resolved_key_type IS NOT NULL
    AND policy_x_finance_component_rows.resolved_key_value IS NOT NULL;

  create temporary table finance_case_component_review_rows on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          nullif(fccr.source_basis_json->>'source_units','')::numeric as source_units,
          nullif(fccr.source_basis_json->>'source_rate','')::numeric as source_rate,
          nullif(fccr.source_basis_json->>'source_charge_rate','')::numeric as source_charge_rate,
          coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) as source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'REUSABLE_SAVED_RESOLUTION'
            when fccr.saved_resolution_mode is not null then 'STALE_SAVED_RESOLUTION'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
            and fccr.saved_resolution_mode is null
          ) as is_fresh_suggested_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and coalesce(fccr.is_resolution_stale,false) = false
            and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,''))
            and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
          ) as is_reusable_saved_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and (
              coalesce(fccr.is_resolution_stale,false) = true
              or upper(coalesce(fccr.saved_target_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              or (fccr.resolution_fingerprint is not null and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint)
            )
          ) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_payload_json
            else jsonb_strip_nulls(jsonb_build_object(
              'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
              'target_pay_method', fccr.current_target_pay_method,
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'suggested_target_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
            ))
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_result_json
            else jsonb_strip_nulls(jsonb_build_object(
              'target_pay_method', fccr.current_target_pay_method,
              'target_amount_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_amount_vat', round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2),
              'target_amount_inc_vat', round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2),
              'basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'replacement_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'target_amount_ex_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_inc_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_units_per_source_ex_vat', case when nullif(fccr.source_basis_json->>'source_units','') is not null and coalesce(fccr.source_amount,0) <> 0 then round((nullif(fccr.source_basis_json->>'source_units','')::numeric) / fccr.source_amount, 10) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
              'source_pay_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'source_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'source_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - fccr.source_amount,2) end,
              'target_pay_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'target_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end,
              'margin_delta_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(fccr.source_amount - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end
            ))
          end as suggested_resolution_result_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'This component already has a reusable saved resolution for the current target pay method.'
            when fccr.saved_resolution_mode is not null then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.source_pay_method <> fccr.current_target_pay_method then 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
            else 'This suggestion preserves equivalent basis using the current target pay method.'
          end as suggestion_explanation_text
        from finance_case_component_rows fccr
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(fccr.source_amount, v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct))
              when fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(fccr.source_amount,0),2), 'vat', 0, 'inc', round(coalesce(fccr.source_amount,0),2))
              when fccr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(fccr.source_amount, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) fcsr on true

  ;

  create temporary table finance_case_component_review_rows_effective on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          fccr.source_units,
          fccr.source_rate,
          fccr.source_charge_rate,
          fccr.source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          fctx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          fctx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          null::text as approved_nonbucket_resolution_mode,
          null::numeric as approved_nonbucket_target_amount_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then false
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then not (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then false
            when fctx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then true
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then true
            when fctx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'REUSABLE_SAVED_RESOLUTION'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'STALE_SAVED_RESOLUTION'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'FRESH_SUGGESTION'
            when fctx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
            and coalesce(fccr.is_reusable_saved_resolution,false) = false
            and coalesce(fccr.is_stale_saved_resolution,false) = false
            and (
              fctx.is_actionable_bucket_resolution = true
              or fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
            )
          ) as is_fresh_suggested_resolution,
          coalesce(fccr.is_reusable_saved_resolution,false) as is_reusable_saved_resolution,
          coalesce(fccr.is_stale_saved_resolution,false) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_payload_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else fccr.suggested_resolution_payload_json
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_result_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            else fccr.suggested_resolution_result_json
          end as suggested_resolution_result_json,
          round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end as source_charge_component_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
            else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null then round(fbasis.source_charge_basis_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.source_charge_basis_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as target_margin_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.basis_source_amount_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'This component already has a reusable saved resolution for the current target pay method.'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'This non-bucket finance case resolves as one suggested/editable gross total. The total remaining source amount is converted onto the current target pay method.'
            when fctx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text
        from finance_case_component_review_rows fccr
        left join lateral (
          select
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and fccr.source_units is not null
              and coalesce(fccr.source_units,0) <> 0
              and fccr.source_rate is not null
              and fccr.source_charge_rate is not null
              and fccr.component_key_type <> 'ADJUSTMENT_CODE'
    and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
            ) as is_actionable_bucket_resolution,
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and not (
                fccr.source_units is not null
                and coalesce(fccr.source_units,0) <> 0
                and fccr.source_rate is not null
                and fccr.source_charge_rate is not null
                and fccr.component_key_type <> 'ADJUSTMENT_CODE'
                and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
              )
            ) as is_fixed_taxable_conversion
        ) fctx on true
        left join lateral (
          select
            round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0), 2) as basis_source_amount_ex_vat,
            case
              when fccr.source_charge_ex_vat is null then null::numeric
              when round(coalesce(fccr.source_amount,0),2) = 0 then round(coalesce(fccr.source_charge_ex_vat,0),2)
              else round(round(coalesce(fccr.source_charge_ex_vat,0),2) * (round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0),2) / nullif(round(coalesce(fccr.source_amount,0),2),0)), 2)
            end as source_charge_basis_ex_vat
        ) fbasis on true
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct),2)
              when fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) fbase_pre on true
        left join lateral (
          select
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(fbase_pre.target_ex_before_rate / fccr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(round(fbase_pre.target_ex_before_rate / fccr.source_units, 2) * fccr.source_units, 2)
              else round(fbase_pre.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) fbase on true
        left join lateral (
          select
            case
              when fbase.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(fccr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) fbase_amounts on true
        left join lateral (
          select
            case
              when coalesce(fccr.is_reusable_saved_resolution,false) = true
               and coalesce(fccr.is_stale_saved_resolution,false) = false
               and coalesce(fccr.saved_resolution_result_json->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              then round((fccr.saved_resolution_result_json->>'target_amount_ex_vat')::numeric, 2)
              else null::numeric
            end as reusable_saved_target_pay_ex_vat
        ) fsaved on true

  ;


  IF v_workbench_resolution_session_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE finance_case_bucket_resolution_overlay ON COMMIT DROP AS
    WITH stored_resolution_components AS (
      SELECT
        stored_resolution.id AS resolution_id,
        stored_resolution.case_key,
        stored_resolution.timesheet_id,
        stored_resolution.source_basis_fingerprint,
        stored_resolution.source_family_key,
        stored_resolution.bucket_code,
        stored_resolution.component_key_type,
        stored_resolution.component_key_value,
        stored_resolution.payload_json,
        stored_resolution.updated_at_utc,
        bucket_element.ordinality::integer AS bucket_ordinal,
        bucket_element.value AS bucket_json
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(stored_resolution.payload_json->'bucket_resolutions') = 'array'
            THEN stored_resolution.payload_json->'bucket_resolutions'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS bucket_element(value, ordinality)
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'BUCKETED'
        AND jsonb_typeof(bucket_element.value) = 'object'
    )
    SELECT DISTINCT ON (
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value
    )
      resolved_component.resolution_id,
      resolved_component.finance_case_id,
      resolved_component.case_key,
      resolved_component.timesheet_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      resolved_component.bucket_code,
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.payload_json,
      resolved_component.bucket_json,
      resolved_component.classification,
      resolved_component.source_pay_method,
      resolved_component.target_pay_method,
      resolved_component.source_units,
      resolved_component.source_rate,
      resolved_component.source_charge_rate,
      resolved_component.resolution_mode,
      resolved_component.target_rate
    FROM (
      SELECT
        stored_component.resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_component.case_key,
        stored_component.timesheet_id,
        COALESCE(
          NULLIF(BTRIM(COALESCE(stored_component.source_basis_fingerprint, '')), ''),
          NULLIF(BTRIM(COALESCE(stored_component.bucket_json->>'source_basis_fingerprint', '')), ''),
          CASE
            WHEN jsonb_typeof(stored_component.bucket_json->'source_basis_json') = 'object'
              THEN md5((stored_component.bucket_json->'source_basis_json')::text)
            ELSE NULL::text
          END
        ) AS source_basis_fingerprint,
        NULLIF(BTRIM(COALESCE(stored_component.source_family_key, stored_component.bucket_json->>'source_family_key', '')), '') AS source_family_key,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.bucket_code, stored_component.bucket_json->>'bucket_code', ''))), '') AS bucket_code,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.component_key_type, stored_component.bucket_json->>'component_key_type', ''))), '') AS component_key_type,
        NULLIF(BTRIM(COALESCE(stored_component.component_key_value, stored_component.bucket_json->>'component_key_value', '')), '') AS component_key_value,
        stored_component.payload_json,
        stored_component.bucket_json,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'classification', ''))) AS classification,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'source_pay_method', ''))) AS source_pay_method,
        UPPER(BTRIM(COALESCE(
          stored_component.bucket_json->>'target_pay_method',
          stored_component.bucket_json->>'current_target_pay_method',
          stored_component.payload_json->>'target_pay_method',
          stored_component.payload_json->>'current_target_pay_method',
          ''
        ))) AS target_pay_method,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_units')::numeric, 6)
          ELSE NULL::numeric
        END AS source_units,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_rate,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_charge_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_charge_rate,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'resolution_mode', stored_component.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate')::numeric, 2)
          ELSE NULL::numeric
        END AS target_rate,
        stored_component.updated_at_utc,
        stored_component.bucket_ordinal
      FROM stored_resolution_components AS stored_component
    ) AS resolved_component
    WHERE resolved_component.finance_case_id IS NOT NULL
      AND resolved_component.source_basis_fingerprint IS NOT NULL
      AND resolved_component.source_family_key IS NOT NULL
      AND resolved_component.component_key_type IS NOT NULL
      AND resolved_component.component_key_value IS NOT NULL
      AND resolved_component.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE')
      AND resolved_component.target_rate IS NOT NULL
      AND resolved_component.target_rate >= 0
    ORDER BY
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.updated_at_utc DESC,
      resolved_component.resolution_id DESC,
      resolved_component.bucket_ordinal DESC;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_resolution_mode = resolution_overlay.resolution_mode,
        approved_target_rate = resolution_overlay.target_rate,
        saved_target_pay_method = COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
        saved_resolution_mode = resolution_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'replacement_rate', round(resolution_overlay.target_rate, 2),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        target_pay_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
          ELSE round(
            (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
            - effective_component.source_margin_ex_vat,
            2
          )
        END,
        suggestion_explanation_text = 'This component uses the current Workbench Case Resolution selected for this finance case.'
    FROM finance_case_bucket_resolution_overlay AS resolution_overlay
    WHERE effective_component.candidate_id = v_candidate_id
      AND effective_component.finance_case_id = resolution_overlay.finance_case_id
      AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      AND effective_component.source_family_key = resolution_overlay.source_family_key
      AND md5(COALESCE(effective_component.source_basis_json::text, '{}'::text)) = resolution_overlay.source_basis_fingerprint
      AND COALESCE(NULLIF(UPPER(BTRIM(COALESCE(effective_component.source_basis_json->>'bucket_code', ''))), ''), '') = COALESCE(resolution_overlay.bucket_code, '')
      AND effective_component.component_key_type = resolution_overlay.component_key_type
      AND effective_component.component_key_value = resolution_overlay.component_key_value
      AND round(effective_component.source_units, 6) = resolution_overlay.source_units
      AND round(effective_component.source_rate, 6) = resolution_overlay.source_rate
      AND round(effective_component.source_charge_rate, 6) = resolution_overlay.source_charge_rate
      AND (resolution_overlay.classification = '' OR UPPER(effective_component.classification::text) = resolution_overlay.classification)
      AND (resolution_overlay.source_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.source_pay_method, ''))) = resolution_overlay.source_pay_method)
      AND (resolution_overlay.target_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.current_target_pay_method, ''))) = resolution_overlay.target_pay_method)
      AND effective_component.is_actionable_resolution_row = true;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay ON COMMIT DROP AS
    SELECT DISTINCT ON (resolved_nonbucket.finance_case_id)
      resolved_nonbucket.resolution_id,
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.case_key,
      resolved_nonbucket.payload_json,
      resolved_nonbucket.resolution_mode,
      resolved_nonbucket.target_amount_ex_vat
    FROM (
      SELECT
        stored_resolution.id AS resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_resolution.case_key,
        stored_resolution.payload_json,
        UPPER(BTRIM(COALESCE(stored_resolution.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount')::numeric, 2)
          ELSE NULL::numeric
        END AS target_amount_ex_vat,
        stored_resolution.updated_at_utc
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
    ) AS resolved_nonbucket
    WHERE resolved_nonbucket.finance_case_id IS NOT NULL
      AND resolved_nonbucket.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
      AND resolved_nonbucket.target_amount_ex_vat IS NOT NULL
      AND resolved_nonbucket.target_amount_ex_vat >= 0
    ORDER BY
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.updated_at_utc DESC,
      resolved_nonbucket.resolution_id DESC;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay_alloc ON COMMIT DROP AS
    WITH target_components AS (
      SELECT
        effective_component.ctid AS row_ctid,
        effective_component.finance_case_id,
        effective_component.finance_component_id,
        resolution_overlay.resolution_id,
        resolution_overlay.payload_json,
        resolution_overlay.resolution_mode,
        resolution_overlay.target_amount_ex_vat,
        round(coalesce(effective_component.remaining_source_amount, 0), 2) AS remaining_source_amount,
        round(sum(coalesce(effective_component.remaining_source_amount, 0)) OVER (PARTITION BY effective_component.finance_case_id), 2) AS total_remaining_source_amount,
        row_number() OVER (PARTITION BY effective_component.finance_case_id ORDER BY effective_component.finance_component_id) AS component_ord,
        count(*) OVER (PARTITION BY effective_component.finance_case_id) AS component_count
      FROM finance_case_component_review_rows_effective AS effective_component
      JOIN finance_case_nonbucket_resolution_overlay AS resolution_overlay
        ON resolution_overlay.finance_case_id = effective_component.finance_case_id
       AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      WHERE effective_component.candidate_id = v_candidate_id
        AND effective_component.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
        AND effective_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND round(coalesce(effective_component.remaining_source_amount, 0), 2) > 0
    ), preliminary_components AS (
      SELECT
        target_components.*,
        round(
          CASE
            WHEN coalesce(target_components.target_amount_ex_vat, 0) = 0 THEN 0::numeric
            WHEN coalesce(target_components.total_remaining_source_amount, 0) = 0 THEN 0::numeric
            WHEN target_components.component_count = 1 THEN target_components.target_amount_ex_vat
            WHEN target_components.component_ord < target_components.component_count THEN target_components.target_amount_ex_vat * target_components.remaining_source_amount / nullif(target_components.total_remaining_source_amount, 0)
            ELSE 0::numeric
          END,
          2
        ) AS preliminary_target_amount_ex_vat
      FROM target_components
    )
    SELECT
      preliminary_components.row_ctid,
      preliminary_components.finance_case_id,
      preliminary_components.finance_component_id,
      preliminary_components.resolution_id,
      preliminary_components.payload_json,
      preliminary_components.resolution_mode,
      round(
        CASE
          WHEN preliminary_components.component_count = 1 THEN preliminary_components.target_amount_ex_vat
          WHEN preliminary_components.component_ord < preliminary_components.component_count THEN preliminary_components.preliminary_target_amount_ex_vat
          ELSE preliminary_components.target_amount_ex_vat - coalesce(
            sum(preliminary_components.preliminary_target_amount_ex_vat) OVER (
              PARTITION BY preliminary_components.finance_case_id
              ORDER BY preliminary_components.component_ord
              ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ),
            0
          )
        END,
        2
      ) AS allocated_target_amount_ex_vat
    FROM preliminary_components;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_nonbucket_resolution_mode = nonbucket_overlay.resolution_mode,
        approved_nonbucket_target_amount_ex_vat = nonbucket_overlay.allocated_target_amount_ex_vat,
        saved_target_pay_method = effective_component.current_target_pay_method,
        saved_resolution_mode = nonbucket_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        target_pay_ex_vat = round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        suggestion_explanation_text = 'This finance case uses the current Workbench non-bucket Case Resolution selected for this session.'
    FROM finance_case_nonbucket_resolution_overlay_alloc AS nonbucket_overlay
    WHERE effective_component.ctid = nonbucket_overlay.row_ctid;
  END IF;

  create temporary table finance_case_due_source_amounts on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'PAYMENT_ADVANCE' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                when vfcr.case_type = 'UNDERPAYMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else greatest(coalesce(vfcr.outstanding_amount, vfcr.original_amount, 0) - coalesce(vfcr.active_reserved_amount,0), 0)
                end
                when vfcr.case_type = 'OVERPAYMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                )
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                else 0::numeric
              end,
              0::numeric
            ),
            2
          ) as due_source_amount_ex_vat
        from finance_case_baseline_scope vfcr
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        left join finance_case_protected_allocations fcpa
          on fcpa.finance_case_id = vfcr.finance_case_id
        where vfcr.finance_case_id is not null

  ;

  create temporary table finance_case_component_due_source_base on commit drop as
        select
          fce.finance_case_id,
          fce.candidate_id,
          fce.case_type,
          fce.taxability,
          fce.finance_component_id,
          round(coalesce(fce.remaining_source_amount,0),2) as remaining_source_amount,
          round(coalesce(fcds.due_source_amount_ex_vat,0),2) as due_source_amount_ex_vat,
          round(sum(coalesce(fce.remaining_source_amount,0)) over (partition by fce.finance_case_id),2) as total_remaining_source_amount,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count
        from finance_case_component_review_rows_effective fce
        join finance_case_due_source_amounts fcds
          on fcds.finance_case_id = fce.finance_case_id

  ;

  create temporary table finance_case_component_due_source_shares on commit drop as
        select
          fcdsb.*,
          round(
            case
              when coalesce(fcdsb.due_source_amount_ex_vat,0) = 0 then 0::numeric
              when coalesce(fcdsb.total_remaining_source_amount,0) = 0 then 0::numeric
              when fcdsb.component_count = 1 then fcdsb.due_source_amount_ex_vat
              when fcdsb.component_ord < fcdsb.component_count then (fcdsb.due_source_amount_ex_vat * fcdsb.remaining_source_amount / nullif(fcdsb.total_remaining_source_amount,0))
              else 0::numeric
            end,
            2
          ) as preliminary_source_due_amount_ex_vat
        from finance_case_component_due_source_base fcdsb

  ;

  create temporary table finance_case_component_due_source_allocations on commit drop as
        select
          fcdss.finance_case_id,
          fcdss.finance_component_id,
          round(
            case
              when fcdss.component_count = 1 then fcdss.due_source_amount_ex_vat
              when fcdss.component_ord < fcdss.component_count then fcdss.preliminary_source_due_amount_ex_vat
              else fcdss.due_source_amount_ex_vat - coalesce(sum(fcdss.preliminary_source_due_amount_ex_vat) over (partition by fcdss.finance_case_id order by fcdss.component_ord rows between unbounded preceding and 1 preceding), 0)
            end,
            2
          ) as allocated_source_due_amount_ex_vat
        from finance_case_component_due_source_shares fcdss

  ;

  create temporary table finance_case_component_due_preview_base on commit drop as
        select
          fce.finance_case_id,
          fce.finance_component_id,
          fcda.allocated_source_due_amount_ex_vat,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count,
          round(
            case
              when coalesce(fcda.allocated_source_due_amount_ex_vat,0) = 0 then 0::numeric
              when fce.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fce.approved_nonbucket_target_amount_ex_vat,0) <> 0 and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when fce.case_type = 'OVERPAYMENT' and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when round(coalesce(fce.remaining_source_amount,0),2) <> 0 and round(coalesce(fce.target_pay_ex_vat,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              else fcda.allocated_source_due_amount_ex_vat
            end,
            2
          ) as preliminary_preview_due_amount_ex_vat
        from finance_case_component_review_rows_effective fce
        join finance_case_component_due_source_allocations fcda
          on fcda.finance_case_id = fce.finance_case_id
         and fcda.finance_component_id = fce.finance_component_id

  ;

  create temporary table finance_case_component_due_preview_allocations on commit drop as
        select
          fcdpb.finance_case_id,
          fcdpb.finance_component_id,
          round(fcdpb.preliminary_preview_due_amount_ex_vat, 2) as allocated_preview_due_amount_ex_vat
        from finance_case_component_due_preview_base fcdpb

  ;

  create temporary table finance_case_taxable_channel_restructure_resolution on commit drop as
        with component_base as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.candidate_id,
            vfcr.client_id,
            vfcr.next_due_week_start,
            vfcr.weekly_due,
            vfcr.weeks_total,
            vfcr.outstanding_amount,
            vfcr.schedule_json,
            cp.cand_pay_method as target_pay_method,
            fccr.finance_component_id,
            fccr.source_family_key,
            fccr.component_key_type,
            fccr.component_key_value,
            fccr.classification,
            fccr.source_pay_method,
            fccr.current_target_pay_method,
            fccr.umb_vat_chargeable,
            fccr.source_basis_json,
            fccr.source_amount,
            fccr.remaining_source_amount,
            fccr.source_units,
            fccr.source_rate,
            fccr.source_charge_rate,
            fccr.source_charge_ex_vat,
            fccr.saved_target_pay_method,
            fccr.saved_resolution_mode,
            fccr.saved_resolution_payload_json,
            fccr.saved_resolution_result_json,
            fccr.resolution_fingerprint,
            fccr.current_component_fingerprint,
            fccr.is_stale_saved_resolution,
            fccr.is_reusable_saved_resolution,
            fccr.stale_reason,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
            ) as has_taxable_channel_mismatch,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
              and (
                coalesce(fccr.is_stale_saved_resolution,false) = true
                or nullif(btrim(coalesce(fccr.saved_target_pay_method,'')), '') is null
                or upper(coalesce(fccr.saved_target_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
                or (
                  fccr.resolution_fingerprint is not null
                  and fccr.current_component_fingerprint is not null
                  and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint
                )
              )
            ) as requires_component_restructure
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          where vfcr.case_type in (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'UNDERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
            'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
            and fccr.finance_component_id is not null
            and round(coalesce(fccr.remaining_source_amount,0),2) > 0
        ),
        component_projected as (
          select
            cb.*,
            round(
              case
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'UMBRELLA'
                 and cb.current_target_pay_method = 'PAYE'
                  then public._pay_convert_umbrella_to_paye_ex(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct)
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'PAYE'
                 and cb.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_convert_paye_to_umbrella(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct, v_vat_rate_pct, coalesce(cb.umb_vat_chargeable,false))->>'ex')::numeric, 0)
                else round(coalesce(cb.remaining_source_amount,0),2)
              end,
              2
            ) as target_remaining_ex
          from component_base cb
        ),
        component_projected_vat as (
          select
            cpj.*,
            round(
              case
                when cpj.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                else 0
              end,
              2
            ) as target_remaining_vat,
            round(
              coalesce(cpj.target_remaining_ex,0)
              + case
                  when cpj.current_target_pay_method = 'UMBRELLA'
                    then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                  else 0
                end,
              2
            ) as target_remaining_inc
          from component_projected cpj
        ),
        case_shape as (
          select
            cpv.finance_case_id,
            (array_agg(cpv.case_type))[1] as case_type,
            (array_remove(array_agg(cpv.candidate_id), null::uuid))[1] as candidate_id,
            (array_remove(array_agg(cpv.client_id), null::uuid))[1] as client_id,
            max(cpv.next_due_week_start) as next_due_week_start,
            max(cpv.weekly_due) as weekly_due,
            max(cpv.weeks_total) as weeks_total,
            max(cpv.outstanding_amount) as outstanding_amount,
            coalesce((jsonb_agg(cpv.schedule_json order by cpv.finance_component_id) filter (where cpv.schedule_json is not null))->0, '[]'::jsonb) as schedule_json,
            max(cpv.target_pay_method) as target_pay_method,
            count(*)::int as open_component_count,
            count(*) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum)::int as open_taxable_count,
            count(*) filter (where cpv.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum))::int as open_fixed_count,
            bool_or(cpv.has_taxable_channel_mismatch) as has_taxable_channel_mismatch,
            bool_or(cpv.requires_component_restructure) as requires_restructure,
            bool_or(coalesce(cpv.is_reusable_saved_resolution,false)) as is_reusable_saved_resolution,
            bool_or(coalesce(cpv.is_stale_saved_resolution,false)) as is_stale_saved_resolution,
            round(coalesce(sum(cpv.remaining_source_amount),0),2) as existing_source_total_ex,
            round(coalesce(sum(cpv.remaining_source_amount) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as existing_taxable_source_total_ex,
            round(coalesce(sum(cpv.target_remaining_ex),0),2) as suggested_target_total_ex,
            round(coalesce(sum(cpv.target_remaining_vat),0),2) as suggested_target_total_vat,
            round(coalesce(sum(cpv.target_remaining_inc),0),2) as suggested_target_total_inc,
            round(coalesce(sum(cpv.target_remaining_ex) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as suggested_taxable_target_total_ex,
            bool_or(coalesce(cpv.umb_vat_chargeable,false)) as umbrella_vat_chargeable,
            coalesce(
              jsonb_agg(
                jsonb_strip_nulls(jsonb_build_object(
                  'finance_component_id', cpv.finance_component_id::text,
                  'source_family_key', cpv.source_family_key,
                  'component_key_type', cpv.component_key_type,
                  'component_key_value', cpv.component_key_value,
                  'classification', cpv.classification::text,
                  'source_pay_method', cpv.source_pay_method,
                  'target_pay_method', cpv.current_target_pay_method,
                  'source_remaining_amount_ex_vat', round(coalesce(cpv.remaining_source_amount,0),2),
                  'target_remaining_amount_ex_vat', round(coalesce(cpv.target_remaining_ex,0),2),
                  'target_remaining_amount_vat', round(coalesce(cpv.target_remaining_vat,0),2),
                  'target_remaining_amount_inc_vat', round(coalesce(cpv.target_remaining_inc,0),2),
                  'requires_component_conversion', cpv.has_taxable_channel_mismatch,
                  'requires_restructure', cpv.requires_component_restructure,
                  'source_units', cpv.source_units,
                  'source_rate', cpv.source_rate,
                  'source_charge_rate', cpv.source_charge_rate,
                  'source_charge_ex_vat', cpv.source_charge_ex_vat,
                  'saved_target_pay_method', cpv.saved_target_pay_method,
                  'saved_resolution_mode', case when cpv.saved_resolution_mode is null then null else cpv.saved_resolution_mode::text end,
                  'is_reusable_saved_resolution', cpv.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', cpv.is_stale_saved_resolution,
                  'stale_reason', cpv.stale_reason
                ))
                order by cpv.classification::text, cpv.component_key_type, cpv.component_key_value, cpv.finance_component_id
              ),
              '[]'::jsonb
            ) as component_breakdown_json
          from component_projected_vat cpv
          group by cpv.finance_case_id
        ),
        case_with_schedule as (
          select
            cs.*,
            coalesce(cs.next_due_week_start, v_week_start) as restructure_start_week_start,
            coalesce(
              (
                select count(*)::integer
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched(schedule_entry)
                where jsonb_typeof(sched.schedule_entry) = 'object'
                  and coalesce(sched.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched.schedule_entry->>'amount')::numeric) > 0
              ),
              case
                when coalesce(cs.weekly_due,0) > 0 and coalesce(cs.existing_source_total_ex,0) > 0 then greatest(ceil(cs.existing_source_total_ex / cs.weekly_due)::integer, 1)
                when coalesce(cs.weeks_total,0) > 0 then cs.weeks_total
                else 1
              end
            ) as existing_weeks_remaining,
            coalesce(
              nullif(round(coalesce(cs.weekly_due,0),2),0),
              (
                select round(abs((sched2.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched2(schedule_entry)
                where jsonb_typeof(sched2.schedule_entry) = 'object'
                  and coalesce(sched2.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched2.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched2.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched2.schedule_entry->>'amount')::numeric) > 0
                order by (sched2.schedule_entry->>'week_start')::date asc
                limit 1
              ),
              round(ceil((cs.existing_source_total_ex / greatest(coalesce(cs.weeks_total,1),1)) * 100) / 100, 2)
            ) as existing_weekly_due,
            coalesce(
              (
                select round(abs((sched3.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched3(schedule_entry)
                where jsonb_typeof(sched3.schedule_entry) = 'object'
                  and coalesce(sched3.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched3.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched3.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched3.schedule_entry->>'amount')::numeric) > 0
                order by (sched3.schedule_entry->>'week_start')::date desc
                limit 1
              ),
              0::numeric
            ) as existing_final_week_amount
          from case_shape cs
        ),
        open_batch as (
          select
            cws.finance_case_id,
            exists (
              select 1
              from public.pay_batch_items pbi_open
              join public.pay_batch_candidates pbc_open
                on pbc_open.id = pbi_open.pay_batch_candidate_id
              join public.pay_batches pb_open
                on pb_open.id = pbc_open.pay_batch_id
              where coalesce(pbi_open.is_voided,false) = false
                and pb_open.cancelled_at_utc is null
                and upper(coalesce(pb_open.status::text,'')) not in ('CANCELLED','COMPLETED','SETTLED')
                and (
                  pbi_open.finance_case_id = cws.finance_case_id
                  or exists (
                    select 1
                    from public.pay_finance_case_components pfc_open
                    where pfc_open.finance_case_id = cws.finance_case_id
                      and pfc_open.closed_at_utc is null
                      and pfc_open.id = pbi_open.finance_component_id
                  )
                )
            ) as has_open_batch_item
          from case_with_schedule cws
        )
        select
          cws.finance_case_id,
          coalesce(cws.requires_restructure,false) as has_dedicated_resolution_payload,
          coalesce(cws.requires_restructure,false) as use_dedicated_blocker,
          case
            when coalesce(cws.requires_restructure,false) = true then jsonb_strip_nulls(jsonb_build_object(
              'resolution_kind', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_action_label', 'Suggested Restructure',
              'modal_title', 'Finance Restructure',
              'finance_case_id', cws.finance_case_id::text,
              'case_type', cws.case_type::text,
              'source_method', (
                select coalesce(jsonb_agg(distinct cb.source_pay_method), '[]'::jsonb)
                from component_base cb
                where cb.finance_case_id = cws.finance_case_id
                  and cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              ),
              'target_method', cws.target_pay_method,
              'can_apply', coalesce(ob.has_open_batch_item,false) = false,
              'open_batch_blocked_reason', case when coalesce(ob.has_open_batch_item,false) = true then 'CASE_ALREADY_IN_OPEN_BATCH' else null end,
              'existing_arrangement', jsonb_build_object(
                'source_remaining_balance_ex_vat', cws.existing_source_total_ex,
                'taxable_source_remaining_balance_ex_vat', cws.existing_taxable_source_total_ex,
                'weekly_due', round(coalesce(cws.existing_weekly_due,0),2),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', case
                  when coalesce(cws.existing_final_week_amount,0) > 0 then round(cws.existing_final_week_amount,2)
                  else round(least(round(coalesce(cws.existing_weekly_due,0),2), greatest(cws.existing_source_total_ex - (round(coalesce(cws.existing_weekly_due,0),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),0)),2)
                end,
                'start_week_start', cws.restructure_start_week_start::text,
                'schedule_json', coalesce(cws.schedule_json,'[]'::jsonb)
              ),
              'suggested_arrangement', jsonb_build_object(
                'target_remaining_balance_ex_vat', cws.suggested_target_total_ex,
                'target_remaining_balance_vat', cws.suggested_target_total_vat,
                'target_remaining_balance_inc_vat', cws.suggested_target_total_inc,
                'taxable_target_remaining_balance_ex_vat', cws.suggested_taxable_target_total_ex,
                'weekly_due', round(
                  greatest(
                    round(coalesce(cws.existing_weekly_due,0),2)
                    * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end,
                    0.01
                  ),
                  2
                ),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', round(
                  least(
                    greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),
                    greatest(
                      cws.suggested_target_total_ex
                      - (round(greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),
                      0
                    )
                  ),
                  2
                ),
                'erni_rate_pct', round(v_erni_pct,6),
                'erni_component_ex_vat', round(abs(cws.existing_taxable_source_total_ex - cws.suggested_taxable_target_total_ex),2),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'vat_amount', cws.suggested_target_total_vat,
                'umbrella_vat_chargeable', coalesce(cws.umbrella_vat_chargeable,false)
              ),
              'component_breakdown', cws.component_breakdown_json,
              'suggestion_explanation_text', 'This taxable finance case must be durably restructured onto the current pay method before it can move to Ready to Pay.'
            ))
            else null::jsonb
          end as taxable_channel_restructure_resolution_json
        from case_with_schedule cws
        left join open_batch ob
          on ob.finance_case_id = cws.finance_case_id

  ;

  /*
   * Cancellation ownership is deliberately independent from the blocker that
   * an applied resolution has satisfied.  A finance line is clearable only
   * when one exact, current, server-owned resolution can be proved.  This is
   * pre-Draft live authority; frozen Draft and downstream artefacts are not
   * consulted or rewritten here (Policy X).
   */
  create temporary table finance_case_resolution_owner_state on commit drop as
  with taxable_owner_rows as (
    select
      component_row.finance_case_id,
      component_row.finance_component_id,
      component_row.classification,
      component_row.saved_target_pay_method,
      component_row.saved_resolution_mode,
      component_row.saved_resolution_payload_json,
      component_row.saved_resolution_result_json,
      component_row.resolution_fingerprint,
      component_row.is_resolution_stale,
      component_row.current_target_pay_method,
      component_row.current_component_fingerprint,
      (
        component_row.saved_target_pay_method is not null
        or component_row.saved_resolution_mode is not null
        or component_row.saved_resolution_payload_json is not null
        or component_row.saved_resolution_result_json is not null
        or nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        or coalesce(component_row.is_resolution_stale, false) = true
      ) as has_saved_evidence,
      (
        component_row.saved_resolution_mode is not null
        and jsonb_typeof(component_row.saved_resolution_payload_json) = 'object'
        and jsonb_typeof(component_row.saved_resolution_result_json) = 'object'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and coalesce(component_row.is_resolution_stale, false) = false
        and nullif(btrim(coalesce(component_row.saved_target_pay_method, '')), '') is not null
        and upper(btrim(component_row.saved_target_pay_method)) = upper(btrim(coalesce(component_row.current_target_pay_method, '')))
        and nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        and component_row.resolution_fingerprint is not distinct from component_row.current_component_fingerprint
      ) as is_current_taxable_owner_component
    from finance_case_component_review_rows as component_row
    where component_row.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and round(coalesce(component_row.remaining_source_amount, 0), 2) > 0
  ), taxable_owner_state as (
    select
      taxable_row.finance_case_id,
      count(*)::integer as taxable_component_count,
      count(*) filter (where taxable_row.is_current_taxable_owner_component)::integer as current_taxable_component_count,
      count(*) filter (where taxable_row.has_saved_evidence)::integer as taxable_saved_evidence_count
    from taxable_owner_rows as taxable_row
    group by taxable_row.finance_case_id
  ), nonbucket_owner_rows as (
    select
      stored_resolution.id as resolution_id,
      case
        when stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substring(stored_resolution.case_key from 9)::uuid
        else null::uuid
      end as finance_case_id,
      stored_resolution.case_key,
      stored_resolution.timesheet_id,
      stored_resolution.payload_json,
      linked_identity.linked_timesheet_id,
      (
        jsonb_typeof(stored_resolution.payload_json) = 'object'
        and stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
        and upper(btrim(coalesce(stored_resolution.payload_json->>'resolution_mode', ''))) in ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
        and coalesce(
          stored_resolution.payload_json->>'target_amount_ex_vat',
          stored_resolution.payload_json->>'target_amount',
          stored_resolution.payload_json->>'amount_ex_vat',
          stored_resolution.payload_json->>'amount',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        and case
          when coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          then coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount'
          )::numeric >= 0
          else false
        end
        and (
          nullif(btrim(coalesce(stored_resolution.payload_json->>'finance_case_id', '')), '') is null
          or btrim(stored_resolution.payload_json->>'finance_case_id') = substring(stored_resolution.case_key from 9)
        )
        and linked_identity.identity_is_valid
      ) as is_valid_nonbucket_owner
    from public.banking_pay_workbench_session_case_resolutions as stored_resolution
    left join lateral (
      select
        case
          when count(distinct identity_value) <= 1
            and count(*) filter (where identity_value is null and raw_value <> '') = 0
          then min(identity_value)::uuid
          else null::uuid
        end as linked_timesheet_id,
        (
          count(distinct identity_value) <= 1
          and count(*) filter (where identity_value is null and raw_value <> '') = 0
        ) as identity_is_valid
      from (
        select
          raw_identity.raw_value,
          case
            when raw_identity.raw_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then lower(raw_identity.raw_value)
            else null::text
          end as identity_value
        from unnest(array[
          coalesce(stored_resolution.timesheet_id::text, ''),
          btrim(coalesce(stored_resolution.payload_json->>'linked_timesheet_id', '')),
          btrim(coalesce(stored_resolution.payload_json->>'timesheet_id', ''))
        ]) as raw_identity(raw_value)
      ) as normalized_identity
    ) as linked_identity on true
    where stored_resolution.session_id = v_workbench_resolution_session_id
      and stored_resolution.candidate_id = v_candidate_id
      and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
  ), nonbucket_owner_state as (
    select
      nonbucket_row.finance_case_id,
      count(*)::integer as nonbucket_owner_row_count,
      count(*) filter (where nonbucket_row.is_valid_nonbucket_owner)::integer as valid_nonbucket_owner_row_count,
      case
        when count(*) = 1 and count(*) filter (where nonbucket_row.is_valid_nonbucket_owner) = 1
          then min(nonbucket_row.linked_timesheet_id::text)::uuid
        else null::uuid
      end as current_nonbucket_linked_timesheet_id
    from nonbucket_owner_rows as nonbucket_row
    where nonbucket_row.finance_case_id is not null
    group by nonbucket_row.finance_case_id
  )
  select
    scope_row.finance_case_id,
    coalesce(taxable_state.taxable_component_count, 0) as taxable_component_count,
    coalesce(taxable_state.current_taxable_component_count, 0) as current_taxable_component_count,
    coalesce(taxable_state.taxable_saved_evidence_count, 0) as taxable_saved_evidence_count,
    coalesce(nonbucket_state.nonbucket_owner_row_count, 0) as nonbucket_owner_row_count,
    coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) as valid_nonbucket_owner_row_count,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'TAXABLE_CHANNEL_RESTRUCTURE'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'NON_BUCKET'
      else null::text
    end as current_saved_resolution_family,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'FINANCE_COMPONENT_SET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'SESSION_NON_BUCKET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
        then 'AMBIGUOUS'
      else 'NONE'
    end as current_saved_resolution_owner_kind,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
        then taxable_state.current_taxable_component_count
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
        then 1
      else 0
    end::integer as current_saved_resolution_owner_count,
    (
      (coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT'))
      or
      (coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT')
    ) as has_current_saved_resolution,
    (
      (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and not (
          coalesce(taxable_state.taxable_component_count, 0) > 0
          and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
          and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
          and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        )
      )
      or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 1
      or (
        coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
        and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) <> 1
      )
      or (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
      )
    ) as has_ambiguous_saved_resolution,
    nonbucket_state.current_nonbucket_linked_timesheet_id as current_saved_resolution_linked_timesheet_id
  from finance_case_baseline_scope as scope_row
  left join taxable_owner_state as taxable_state
    on taxable_state.finance_case_id = scope_row.finance_case_id
  left join nonbucket_owner_state as nonbucket_state
    on nonbucket_state.finance_case_id = scope_row.finance_case_id
  where scope_row.finance_case_id is not null;

  create temporary table finance_case_resolution_rollup on commit drop as
        with grouped as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method as candidate_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            fpr.bank_details_hash as payee_bank_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then true
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then true
              else false
            end as is_recovery_case,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then '[]'::jsonb
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then '[]'::jsonb
              else coalesce(fpr.blocked_reason_codes, '[]'::jsonb)
            end as payee_blocked_reason_codes,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then 'one-off specified bank account'
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'umbrella company'
              else 'normal PAYE route'
            end as destination_label,
            round(coalesce(max(fcds.due_source_amount_ex_vat),0),2) as due_source_amount_ex_vat,
            round(coalesce(sum(fcdpa.allocated_preview_due_amount_ex_vat), max(fcds.due_source_amount_ex_vat), 0),2) as due_amount_ex_vat,
            coalesce(fctcr.has_dedicated_resolution_payload,false) as has_taxable_channel_restructure_payload,
            coalesce(fctcr.use_dedicated_blocker,false) as use_taxable_channel_restructure_blocker,
            fctcr.taxable_channel_restructure_resolution_json as taxable_channel_restructure_resolution_json,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'TAXABLE_CHANNEL_RESTRUCTURE'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'NON_BUCKET'::text
              else 'BUCKETED'::text
            end as resolution_family,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'Suggested Restructure'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Suggested Gross Total'::text
              else 'Suggested Rate'::text
            end as resolution_action_label,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            coalesce(fcros.current_saved_resolution_owner_count, 0)::integer as current_saved_resolution_owner_count,
            coalesce(fcros.has_current_saved_resolution, false) as has_current_saved_resolution,
            coalesce(fcros.has_ambiguous_saved_resolution, false) as has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0)::int as open_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0)::int as open_reimbursement_count,
            (coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true), 0)
              + case when coalesce(fctcr.use_dedicated_blocker,false) = true then 1 else 0 end)::int as unresolved_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.is_stale_saved_resolution,false) = true), 0)::int as stale_count,
            (coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0) > 0
             and
             coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0) > 0) as is_mixed_case,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = true
              or coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) > 0
            ) as case_needs_resolution,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = false
              and coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) = 0
            ) as case_resolution_satisfied_now,
            case when coalesce(fctcr.use_dedicated_blocker,false) = true then null::jsonb else coalesce(
              (jsonb_agg(
                jsonb_build_object(
                  'resolution_kind', 'NON_BUCKET_GROSS_TOTAL',
                  'resolution_family', 'NON_BUCKET',
                  'resolution_action_label', 'Suggested Gross Total',
                  'source_amount_ex_vat', round(coalesce(fccr.remaining_source_amount,0),2),
                  'suggested_target_amount_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'approved_target_amount_ex_vat', case when fccr.approved_nonbucket_target_amount_ex_vat is null then null else round(fccr.approved_nonbucket_target_amount_ex_vat,2) end,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text
                )
              ) filter (where vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fccr.finance_component_id is not null))->0,
              null::jsonb
            ) end as non_bucket_resolution_json,
            coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'finance_component_id', fccr.finance_component_id::text,
                  'source_family_key', fccr.source_family_key,
                  'component_key_type', fccr.component_key_type,
                  'component_key_value', fccr.component_key_value,
                  'classification', fccr.classification::text,
                  'source_pay_method', fccr.source_pay_method,
                  'current_target_pay_method', fccr.current_target_pay_method,
                  'source_amount', round(coalesce(fccr.source_amount,0),2),
                  'remaining_source_amount', round(coalesce(fccr.remaining_source_amount,0),2),
                  'source_basis_json', jsonb_strip_nulls(fccr.source_basis_json || jsonb_build_object('source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end, 'source_charge_rate', case when fccr.source_charge_rate is null then null else round(fccr.source_charge_rate,2) end)),
                  'saved_target_pay_method', fccr.saved_target_pay_method,
                  'saved_resolution_mode', case when fccr.saved_resolution_mode is null then null else fccr.saved_resolution_mode::text end,
                  'saved_resolution_payload_json', fccr.saved_resolution_payload_json,
                  'saved_resolution_result_json', fccr.saved_resolution_result_json,
                  'has_suggested_resolution', fccr.has_suggested_resolution,
                  'suggestion_provenance', fccr.suggestion_provenance,
                  'is_fresh_suggested_resolution', fccr.is_fresh_suggested_resolution,
                  'is_reusable_saved_resolution', fccr.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', fccr.is_stale_saved_resolution,
                  'suggested_resolution_payload_json', fccr.suggested_resolution_payload_json,
                  'suggested_resolution_result_json', fccr.suggested_resolution_result_json,
                  'source_units', fccr.source_units,
                  'target_units', case when nullif(fccr.suggested_resolution_result_json->>'target_units','') is not null then (fccr.suggested_resolution_result_json->>'target_units')::numeric else fccr.source_units end,
                  'source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end,
                  'target_rate', case when nullif(fccr.suggested_resolution_result_json->>'replacement_rate','') is not null then round((fccr.suggested_resolution_result_json->>'replacement_rate')::numeric,2) when nullif(fccr.suggested_resolution_payload_json->>'suggested_target_rate','') is not null then round((fccr.suggested_resolution_payload_json->>'suggested_target_rate')::numeric,2) else null end,
                  'source_pay_ex_vat', round(coalesce(fccr.source_pay_ex_vat,0),2),
                  'source_charge_ex_vat', fccr.source_charge_component_ex_vat,
                  'source_margin_ex_vat', fccr.source_margin_ex_vat,
                  'target_pay_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'target_charge_ex_vat', fccr.target_charge_ex_vat,
                  'target_margin_ex_vat', fccr.target_margin_ex_vat,
                  'margin_delta_ex_vat', fccr.margin_delta_ex_vat,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text,
                  'component_fingerprint', fccr.current_component_fingerprint,
                  'is_resolution_stale', coalesce(fccr.is_stale_saved_resolution,false),
                  'stale_reason', fccr.stale_reason,
                  'requires_resolution', coalesce(fccr.requires_resolution,false),
                  'resolution_state', case
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fccr.requires_resolution,false) = true then 'REQUIRED'
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'RESOLVED'
                    else case when fccr.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'FIXED' when coalesce(fccr.requires_resolution,false) = true then 'REQUIRED' else 'RESOLVED' end
                  end,
                  'is_actionable_resolution_row', coalesce(fccr.is_actionable_resolution_row,false),
                  'is_fixed_no_action_taxable_row', coalesce(fccr.is_fixed_no_action_taxable_row,false),
                  'allocated_source_due_amount_ex_vat', round(coalesce(fcda.allocated_source_due_amount_ex_vat,0),2),
                  'preview_due_amount_ex_vat', round(coalesce(fcdpa.allocated_preview_due_amount_ex_vat, coalesce(fcda.allocated_source_due_amount_ex_vat,0)),2)
                )
                order by fccr.classification::text, fccr.component_key_type, fccr.component_key_value
              ) filter (where fccr.finance_component_id is not null),
              '[]'::jsonb
            ) as case_components_json
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          left join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          left join finance_case_payee_readiness fpr
            on fpr.finance_case_id = vfcr.finance_case_id
          left join finance_case_due_source_amounts fcds
            on fcds.finance_case_id = vfcr.finance_case_id
          left join finance_case_component_due_source_allocations fcda
            on fcda.finance_case_id = fccr.finance_case_id
           and fcda.finance_component_id = fccr.finance_component_id
          left join finance_case_component_due_preview_allocations fcdpa
            on fcdpa.finance_case_id = fccr.finance_case_id
           and fcdpa.finance_component_id = fccr.finance_component_id
          left join finance_case_taxable_channel_restructure_resolution fctcr
            on fctcr.finance_case_id = vfcr.finance_case_id
          left join finance_case_resolution_owner_state fcros
            on fcros.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
          group by
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            fpr.bank_details_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            fpr.blocked_reason_codes,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            vfcr.payout_status,
            fctcr.has_dedicated_resolution_payload,
            fctcr.use_dedicated_blocker,
            fctcr.taxable_channel_restructure_resolution_json,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            fcros.current_saved_resolution_owner_count,
            fcros.has_current_saved_resolution,
            fcros.has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id
        )
        select
          g.finance_case_id,
          g.case_type,
          g.advance_kind,
          g.reason,
          g.candidate_id,
          g.cand_tms_ref,
          g.cand_display_name,
          g.candidate_pay_method,
          g.payee_entity_kind,
          g.payee_entity_id,
          (jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) = 0) as candidate_ready_for_draft,
          g.client_id,
          g.client_name,
          g.linked_timesheet_id,
          g.linked_shift_date,
          g.adjustment_comment,
          g.next_due_week_start,
          g.active_snooze_id,
          g.active_snooze_kind,
          g.active_snooze_until_date,
          g.active_snooze_note,
          g.taxability,
          g.routing_kind,
          g.oneoff_bank_details_present,
          g.oneoff_bank_details_required,
          g.is_candidate_directed_oneoff_payout,
          g.appears_on_umbrella_remittance,
          g.generates_candidate_payment_advice,
          g.snooze_allowed,
          g.lifecycle_status_display,
          g.payee_bank_hash,
          g.beneficiary_name,
          g.masked_bank_account,
          g.destination_label,
          g.due_amount_ex_vat,
          g.open_taxable_count,
          g.open_reimbursement_count,
          g.unresolved_taxable_count,
          g.stale_count,
          g.is_mixed_case,
          g.resolution_family,
          case when g.case_needs_resolution then g.resolution_family else null::text end as required_resolution_family,
          g.current_saved_resolution_family,
          g.current_saved_resolution_owner_kind,
          g.current_saved_resolution_owner_count,
          g.has_current_saved_resolution,
          g.has_ambiguous_saved_resolution,
          g.current_saved_resolution_linked_timesheet_id,
          case
            when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
            when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
            when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
            else 'NOT_REQUIRED'
          end as finance_resolution_clearability_state,
          case
            when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
            else null::text
          end as finance_resolution_clear_block_reason,
          g.case_needs_resolution,
          g.case_resolution_satisfied_now,
          g.resolution_action_label,
          g.taxable_channel_restructure_resolution_json,
          null::jsonb as linked_resolution_scope_json,
          (
            g.case_needs_resolution = true
            or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
          ) as is_blocked,
          (
            coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
              when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
              when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          jsonb_strip_nulls(
            jsonb_build_object(
              'case_key', ('finance:' || g.finance_case_id::text),
              'case_type', g.case_type::text,
              'resolution_family', g.resolution_family,
              'required_resolution_family', case when g.case_needs_resolution then g.resolution_family else null end,
              'current_saved_resolution_family', g.current_saved_resolution_family,
              'current_saved_resolution_owner_kind', g.current_saved_resolution_owner_kind,
              'current_saved_resolution_owner_count', g.current_saved_resolution_owner_count,
              'has_current_saved_resolution', g.has_current_saved_resolution,
              'has_ambiguous_saved_resolution', g.has_ambiguous_saved_resolution,
              'current_saved_resolution_linked_timesheet_id', case
                when g.current_saved_resolution_linked_timesheet_id is null then null
                else g.current_saved_resolution_linked_timesheet_id::text
              end,
              'finance_resolution_clearability_state', case
                when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
                when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
                when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
                else 'NOT_REQUIRED'
              end,
              'finance_resolution_clear_block_reason', case
                when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
                else null
              end,
              'case_needs_resolution', g.case_needs_resolution,
              'case_resolution_satisfied_now', g.case_resolution_satisfied_now,
              'resolution_action_label', g.resolution_action_label,
              'linked_resolution_scope_json', null,
              'taxability', case when g.taxability is null then null else g.taxability::text end,
              'routing_kind', case when g.routing_kind is null then null else g.routing_kind::text end,
              'destination_label', g.destination_label,
              'is_mixed_case', g.is_mixed_case,
              'open_taxable_count', g.open_taxable_count,
              'open_reimbursement_count', g.open_reimbursement_count,
              'unresolved_taxable_count', g.unresolved_taxable_count,
              'stale_count', g.stale_count,
              'is_blocked', (
                g.case_needs_resolution = true
                or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
              ),
              'due_amount_ex_vat', g.due_amount_ex_vat,
              'blocked_reason_codes', (
                coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
                ||
                (case
                  when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
                  when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
                  when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                  else '[]'::jsonb
                end)
              ),
              'non_bucket_resolution', g.non_bucket_resolution_json,
              'taxable_channel_restructure', g.taxable_channel_restructure_resolution_json,
              'taxable_channel_restructure_resolution', g.taxable_channel_restructure_resolution_json
            )
          ) as case_resolution_summary_json,
          case
            when g.resolution_family = 'NON_BUCKET'
              and jsonb_typeof(g.non_bucket_resolution_json) = 'object'
            then g.non_bucket_resolution_json
            else null::jsonb
          end as taxable_manual_debt_resolution_json,
          g.case_components_json
        from grouped g

  ;

  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_RESULT',
    jsonb_build_object(
      'candidate_id', v_candidate_id,
      'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
      'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup),
      'finance_case_repaid_wtd_count', (select count(*)::int from finance_case_repaid_wtd)
    ),
    'pay_preview_finance',
    COALESCE(v_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
    'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup)
  );

exception
  when others then
    PERFORM public._imp_debug_audit(
      v_actor_user_id,
      'PAY_PREVIEW_FINANCE_CASE_BASELINE_ERROR',
      jsonb_build_object(
        'candidate_id', p_candidate_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_preview_finance',
      COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

-- pay_preview_candidate_build_payee_baseline(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_payee_baseline(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.timesheet_case_rollup') is null then
    perform public.pay_preview_candidate_build_case_component_rows(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_candidate_seed, pg_temp.candidate_base, pg_temp.timesheet_candidate_rollup, pg_temp.candidate_rollup, pg_temp.blocked_counts, pg_temp.do_not_pay_counts, pg_temp.loan_due, pg_temp.overpayment_balances, pg_temp.loan_due_this_week, pg_temp.loan_repaid_wtd, pg_temp.paid_wtd_before, pg_temp.cand_enriched, pg_temp.payee_baseline_rows, pg_temp.payees_src, pg_temp.payees, pg_temp.payees_enriched, pg_temp.payees_json, pg_temp.cand_payee0, pg_temp.cand_payee, pg_temp.timesheet_case_rollup_payable, pg_temp.timesheet_case_rollup_effective;

  create temporary table finance_candidate_seed on commit drop as
        select
          vfcr.candidate_id,
          c.tms_ref as cand_tms_ref,
          c.display_name as cand_display_name,
          upper(coalesce(c.pay_method,'')) as cand_pay_method,
          c.umbrella_id as cand_umbrella_id,
          coalesce(u.enabled,false) as umb_enabled,
          coalesce(u.vat_chargeable,false) as umb_vat_chargeable,
          (c.bank_details_hash is not null and btrim(c.bank_details_hash) <> '') as candidate_has_bank_details,
          c.bank_details_hash as candidate_bank_hash,
          (u.bank_details_hash is not null and btrim(u.bank_details_hash) <> '') as umbrella_has_bank_details,
          u.bank_details_hash as umbrella_bank_hash
        from finance_case_baseline_scope vfcr
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join public.umbrellas u
          on u.id = c.umbrella_id
  
  ;

  create temporary table candidate_base on commit drop as
        select
          x.candidate_id,
          max(x.cand_tms_ref) as cand_tms_ref,
          max(x.cand_display_name) as cand_display_name,
          max(x.cand_pay_method) as cand_pay_method,
          max(x.cand_umbrella_id::text)::uuid as cand_umbrella_id,
          bool_or(x.umb_enabled) as umb_enabled,
          bool_or(x.umb_vat_chargeable) as umb_vat_chargeable,
          bool_or(x.candidate_has_bank_details) as candidate_has_bank_details,
          max(x.candidate_bank_hash) as candidate_bank_hash,
          bool_or(x.umbrella_has_bank_details) as umbrella_has_bank_details,
          max(x.umbrella_bank_hash) as umbrella_bank_hash
        from (
          select
            d.candidate_id,
            d.cand_tms_ref,
            d.cand_display_name,
            d.cand_pay_method,
            d.cand_umbrella_id,
            d.umb_enabled,
            d.umb_vat_chargeable,
            (d.cand_bank_hash is not null and btrim(d.cand_bank_hash) <> '') as candidate_has_bank_details,
            d.cand_bank_hash as candidate_bank_hash,
            (d.umb_bank_hash is not null and btrim(d.umb_bank_hash) <> '') as umbrella_has_bank_details,
            d.umb_bank_hash as umbrella_bank_hash
          from ts_deltas d
          union all
          select
            fcs.candidate_id,
            fcs.cand_tms_ref,
            fcs.cand_display_name,
            fcs.cand_pay_method,
            fcs.cand_umbrella_id,
            fcs.umb_enabled,
            fcs.umb_vat_chargeable,
            fcs.candidate_has_bank_details,
            fcs.candidate_bank_hash,
            fcs.umbrella_has_bank_details,
            fcs.umbrella_bank_hash
          from finance_candidate_seed fcs
        ) x
        group by x.candidate_id
  
  ;

  create temporary table timesheet_case_rollup_payable on commit drop as
        with normalized_timesheet_rollup as (
          select
            tcr.candidate_id,
            tcr.timesheet_id,
            tcr.client_id,
            tcr.ts_week_ending_date,
            tcr.ts_client_name,
            tcr.ts_pay_method,
            tcr.cand_pay_method,
            tcr.cand_tms_ref,
            tcr.cand_display_name,
            tcr.cand_umbrella_id,
            tcr.umb_enabled,
            tcr.umb_vat_chargeable,
            tcr.candidate_has_bank_details,
            tcr.candidate_bank_hash,
            tcr.umbrella_has_bank_details,
            tcr.umbrella_bank_hash,
            tcr.resolution_family,
            round(coalesce(ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount_ex_vat,
            round(coalesce(ti.payment_amount_inc_vat, ti.payment_amount, ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount_inc_vat,
            round(coalesce(ti.payment_amount, ti.payment_amount_inc_vat, ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount, tcr.payment_amount_inc_vat, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount,
            round(coalesce(case when ti.timesheet_id is not null then ti_segment_totals.segment_total_ex else null::numeric end, tcr.segments_total_ex, 0), 2) as effective_segments_total_ex,
            coalesce(ti.segment_deltas_json, tcr.segment_deltas_json, '[]'::jsonb) as effective_segment_deltas_json,
            coalesce(ti.adjustment_deltas_json, tcr.adjustment_deltas_json, '[]'::jsonb) as effective_adjustment_deltas_json,
            coalesce(ti.additional_unit_deltas_json, tcr.additional_unit_deltas_json, '[]'::jsonb) as effective_additional_unit_deltas_json,
            round(coalesce(ti.delta_additional_pay_ex_vat, tcr.delta_additional_pay_ex_vat, 0), 2) as effective_delta_additional_pay_ex_vat,
            round(coalesce(ti.delta_expenses_pay_ex_vat, tcr.delta_expenses_pay_ex_vat, 0), 2) as effective_delta_expenses_pay_ex_vat,
            round(coalesce(ti.delta_travel_pay_ex_vat, tcr.delta_travel_pay_ex_vat, 0), 2) as effective_delta_travel_pay_ex_vat,
            round(coalesce(ti.delta_accommodation_pay_ex_vat, tcr.delta_accommodation_pay_ex_vat, 0), 2) as effective_delta_accommodation_pay_ex_vat,
            round(coalesce(ti.delta_other_pay_ex_vat, tcr.delta_other_pay_ex_vat, 0), 2) as effective_delta_other_pay_ex_vat,
            round(coalesce(ti.delta_mileage_pay_ex_vat, tcr.delta_mileage_pay_ex_vat, 0), 2) as effective_delta_mileage_pay_ex_vat,
            coalesce(ti.reservation_overrun_detected, tcr.reservation_overrun_detected, false) as effective_reservation_overrun_detected,
            tcr.case_components_json,
            tcr.case_resolution_summary_json,
            tcr.case_needs_resolution,
            tcr.case_resolution_satisfied_now,
            tcr.resolution_action_label,
            tcr.linked_resolution_scope_json,
            tcr.unresolved_taxable_amount_ex,
            tcr.open_taxable_count,
            tcr.open_reimbursement_count,
            tcr.unresolved_taxable_count,
            tcr.stale_count,
            tcr.is_mixed_case,
            tcr.is_blocked
          from timesheet_case_rollup tcr
          left join ts_itemised ti
            on ti.timesheet_id = tcr.timesheet_id
           and ti.candidate_id = tcr.candidate_id
          left join lateral (
            select round(
                     coalesce(
                       sum(
                         case
                           when coalesce(segment_delta.value->>'delta_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                             then (segment_delta.value->>'delta_pay_ex_vat')::numeric
                           else 0::numeric
                         end
                       ),
                       0::numeric
                     ),
                     2
                   ) as segment_total_ex
            from jsonb_array_elements(
              case
                when jsonb_typeof(coalesce(ti.segment_deltas_json, '[]'::jsonb)) = 'array'
                  then coalesce(ti.segment_deltas_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) as segment_delta(value)
          ) ti_segment_totals on true
        )
        select
          normalized_timesheet_rollup.candidate_id,
          normalized_timesheet_rollup.timesheet_id,
          normalized_timesheet_rollup.client_id,
          normalized_timesheet_rollup.ts_week_ending_date,
          normalized_timesheet_rollup.ts_client_name,
          normalized_timesheet_rollup.ts_pay_method,
          normalized_timesheet_rollup.cand_pay_method,
          normalized_timesheet_rollup.cand_tms_ref,
          normalized_timesheet_rollup.cand_display_name,
          normalized_timesheet_rollup.cand_umbrella_id,
          normalized_timesheet_rollup.umb_enabled,
          normalized_timesheet_rollup.umb_vat_chargeable,
          normalized_timesheet_rollup.candidate_has_bank_details,
          normalized_timesheet_rollup.candidate_bank_hash,
          normalized_timesheet_rollup.umbrella_has_bank_details,
          normalized_timesheet_rollup.umbrella_bank_hash,
          normalized_timesheet_rollup.resolution_family,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
            else normalized_timesheet_rollup.case_needs_resolution
          end as case_needs_resolution,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then true
            else normalized_timesheet_rollup.case_resolution_satisfied_now
          end as case_resolution_satisfied_now,
          normalized_timesheet_rollup.resolution_action_label,
          normalized_timesheet_rollup.linked_resolution_scope_json,
          normalized_timesheet_rollup.effective_payment_amount_ex_vat as case_total_amount_ex,
          case
            when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then 0::numeric
            else normalized_timesheet_rollup.effective_payment_amount_ex_vat
          end as safe_amount_ex,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0::numeric
            else normalized_timesheet_rollup.unresolved_taxable_amount_ex
          end as unresolved_taxable_amount_ex,
          normalized_timesheet_rollup.open_taxable_count,
          normalized_timesheet_rollup.open_reimbursement_count,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0
            else normalized_timesheet_rollup.unresolved_taxable_count
          end as unresolved_taxable_count,
          normalized_timesheet_rollup.stale_count,
          normalized_timesheet_rollup.is_mixed_case,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
            else normalized_timesheet_rollup.is_blocked
          end as is_blocked,
          normalized_timesheet_rollup.effective_segments_total_ex as segments_total_ex,
          normalized_timesheet_rollup.effective_delta_additional_pay_ex_vat as delta_additional_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_expenses_pay_ex_vat as delta_expenses_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_travel_pay_ex_vat as delta_travel_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_accommodation_pay_ex_vat as delta_accommodation_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_other_pay_ex_vat as delta_other_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_mileage_pay_ex_vat as delta_mileage_pay_ex_vat,
          normalized_timesheet_rollup.effective_segment_deltas_json as segment_deltas_json,
          normalized_timesheet_rollup.effective_adjustment_deltas_json as adjustment_deltas_json,
          normalized_timesheet_rollup.effective_additional_unit_deltas_json as additional_unit_deltas_json,
          normalized_timesheet_rollup.effective_reservation_overrun_detected as reservation_overrun_detected,
          normalized_timesheet_rollup.effective_payment_amount_ex_vat as payment_amount_ex_vat,
          normalized_timesheet_rollup.effective_payment_amount_inc_vat as payment_amount_inc_vat,
          normalized_timesheet_rollup.effective_payment_amount as payment_amount,
          (
            coalesce(normalized_timesheet_rollup.case_resolution_summary_json, '{}'::jsonb)
            || jsonb_build_object(
              'case_needs_resolution', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
                else normalized_timesheet_rollup.case_needs_resolution
              end,
              'case_resolution_satisfied_now', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then true
                else normalized_timesheet_rollup.case_resolution_satisfied_now
              end,
              'safe_amount_ex_vat', case
                when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then 0::numeric
                else normalized_timesheet_rollup.effective_payment_amount_ex_vat
              end,
              'blocked_case_amount_ex_vat', case
                when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then normalized_timesheet_rollup.effective_payment_amount_ex_vat
                else 0::numeric
              end,
              'unresolved_taxable_amount_ex_vat', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0::numeric
                else normalized_timesheet_rollup.unresolved_taxable_amount_ex
              end
            )
          ) as case_resolution_summary_json,
          normalized_timesheet_rollup.case_components_json
        from normalized_timesheet_rollup

  ;

  create temporary table timesheet_candidate_rollup on commit drop as
        select
          tcr.candidate_id,
          bool_or(coalesce(tcr.unresolved_taxable_count, 0) > 0) as has_mismatch,
          round(sum(case when coalesce(tcr.is_blocked, false) = false then coalesce(tcr.case_total_amount_ex, 0) else 0 end), 2) as non_mismatch_total_ex,
          round(sum(case when coalesce(tcr.unresolved_taxable_count, 0) > 0 and tcr.ts_pay_method = 'PAYE' then coalesce(tcr.unresolved_taxable_amount_ex, 0) else 0 end), 2) as mismatch_source_paye_ex,
          round(sum(case when coalesce(tcr.unresolved_taxable_count, 0) > 0 and tcr.ts_pay_method = 'UMBRELLA' then coalesce(tcr.unresolved_taxable_amount_ex, 0) else 0 end), 2) as mismatch_source_umbrella_ex,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'timesheet_id', tcr.timesheet_id::text,
                'week_ending_date', case when tcr.ts_week_ending_date is null then null else tcr.ts_week_ending_date::text end,
                'client_id', case when tcr.client_id is null then null else tcr.client_id::text end,
                'client_name', tcr.ts_client_name,
                'payment_amount_ex_vat', tcr.payment_amount_ex_vat,
                'payment_amount_inc_vat', tcr.payment_amount_inc_vat,
                'payment_amount', tcr.payment_amount,
                'source_pay_method', tcr.ts_pay_method,
                'candidate_pay_method', tcr.cand_pay_method,
                'segment_deltas', tcr.segment_deltas_json,
                'adjustment_deltas', tcr.adjustment_deltas_json,
                'delta_additional_pay_ex_vat', tcr.delta_additional_pay_ex_vat,
                'additional_unit_deltas', tcr.additional_unit_deltas_json,
                'reservation_overrun_detected', tcr.reservation_overrun_detected,
                'delta_expenses_pay_ex_vat', tcr.delta_expenses_pay_ex_vat,
                'delta_travel_pay_ex_vat', tcr.delta_travel_pay_ex_vat,
                'delta_accommodation_pay_ex_vat', tcr.delta_accommodation_pay_ex_vat,
                'delta_other_pay_ex_vat', tcr.delta_other_pay_ex_vat,
                'delta_mileage_pay_ex_vat', tcr.delta_mileage_pay_ex_vat,
                'case_key', ('timesheet:' || tcr.timesheet_id::text),
                'case_resolution_summary', coalesce(tcr.case_resolution_summary_json, '{}'::jsonb),
                'components', coalesce(tcr.case_components_json, '[]'::jsonb)
              )
              order by tcr.ts_week_ending_date, tcr.ts_client_name, tcr.timesheet_id
            ) filter (where round(coalesce(tcr.case_total_amount_ex,0),2) <> 0),
            '[]'::jsonb
          ) as timesheets_itemisation
        from timesheet_case_rollup_payable tcr
        group by tcr.candidate_id
  
  ;

  create temporary table candidate_rollup on commit drop as
        select
          cb.candidate_id,
          cb.cand_tms_ref,
          cb.cand_display_name,
          cb.cand_pay_method,
          cb.cand_umbrella_id,
          cb.umb_enabled,
          cb.umb_vat_chargeable,
          cb.candidate_has_bank_details,
          cb.candidate_bank_hash,
          cb.umbrella_has_bank_details,
          cb.umbrella_bank_hash,
          coalesce(tcrr.has_mismatch, false) as has_mismatch,
          coalesce(tcrr.non_mismatch_total_ex, 0) as non_mismatch_total_ex,
          coalesce(tcrr.mismatch_source_paye_ex, 0) as mismatch_source_paye_ex,
          coalesce(tcrr.mismatch_source_umbrella_ex, 0) as mismatch_source_umbrella_ex,
          coalesce(tcrr.timesheets_itemisation, '[]'::jsonb) as timesheets_itemisation
        from candidate_base cb
        left join timesheet_candidate_rollup tcrr
          on tcrr.candidate_id = cb.candidate_id
  
  ;

  create temporary table blocked_counts on commit drop as
        select bi.candidate_id, count(*)::int as blocked_count
        from blocked_items bi
        group by bi.candidate_id
  
  ;

  create temporary table do_not_pay_counts on commit drop as
        select di.candidate_id, count(*)::int as do_not_pay_count
        from do_not_pay_items di
        group by di.candidate_id
  
  ;

  create temporary table loan_due on commit drop as
        select
          pa.candidate_id,
          round(
            sum(
              abs(coalesce(nullif(e->>'amount','')::numeric,0))
            ),
            2
          ) as loan_due_total,
          jsonb_agg(
            jsonb_build_object(
              'advance_id', pa.id::text,
              'week_start', (nullif(e->>'week_start','')::date)::text,
              'due_amount', round(abs(coalesce(nullif(e->>'amount','')::numeric,0)),2),
              'reason', pa.reason::text,
              -- legacy alias (kept to avoid breaking any existing consumer)
              'scheduled_amount', round(abs(coalesce(nullif(e->>'amount','')::numeric,0)),2)
            )
            order by (nullif(e->>'week_start','')::date) asc nulls last, pa.created_at asc, pa.id
          ) as loan_due_entries
        from public.pay_advances pa
        join lateral jsonb_array_elements(coalesce(pa.schedule_json,'[]'::jsonb)) e on true
        where pa.status::text = 'ACTIVE'
          and nullif(e->>'week_start','') is not null
          and (nullif(e->>'week_start','')::date) <= v_week_start
          and coalesce(nullif(e->>'amount','')::numeric,0) < 0
        group by pa.candidate_id
  
  ;

  create temporary table overpayment_balances on commit drop as
        select
          pa.candidate_id,
          round(sum(coalesce(pa.outstanding_amount,0)),2) as overpayment_balance_remaining
        from public.pay_advances pa
        where upper(coalesce(pa.advance_kind::text,'')) = 'OVERPAYMENT'
          and upper(coalesce(pa.status::text,'')) = 'ACTIVE'
        group by pa.candidate_id
  
  ;

  create temporary table loan_due_this_week on commit drop as
        select
          pa.candidate_id,
          round(sum(
            case
              when upper(coalesce(pa.advance_kind::text,'')) = 'LOAN'
                and upper(coalesce(pa.status::text,'')) = 'ACTIVE'
                and upper(coalesce(pa.payout_status::text,'')) = 'PAID'
                and coalesce(pa.outstanding_amount,0) > 0
                and (pa.start_week_start is null or pa.start_week_start <= v_week_start)
              then least(coalesce(pa.weekly_due,0), coalesce(pa.outstanding_amount,0))
              else 0
            end
          ),2) as loan_due_this_week
        from public.pay_advances pa
        group by pa.candidate_id
  
  ;

  create temporary table loan_repaid_wtd on commit drop as
        select
          pbc.candidate_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as loan_repaid_wtd
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        where pbi.item_type = 'LOAN_REPAYMENT'
          and pb.pay_date::date >= v_week_start
          and pb.pay_date::date < v_pay_date
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
        group by pbc.candidate_id
  
  ;

  create temporary table paid_wtd_before on commit drop as
        select
          cr.candidate_id,
          public._pay_candidate_arranged_pay_wtd_before(
            p_candidate_id => cr.candidate_id,
            p_week_start => v_week_start,
            p_pay_date => v_pay_date,
            p_before_created_at_utc => null::timestamptz,
            p_before_pay_batch_id => null::uuid
          )::numeric(12,2) as paid_wtd_before
        from candidate_rollup cr
  
  ;

  create temporary table cand_enriched on commit drop as
        select
          cr.candidate_id,
          cr.cand_tms_ref,
          cr.cand_display_name,
          cr.cand_pay_method,
          cr.cand_umbrella_id,
          cr.umb_enabled,
          cr.umb_vat_chargeable,
          cr.has_mismatch,
          cr.non_mismatch_total_ex,
          cr.mismatch_source_paye_ex,
          cr.mismatch_source_umbrella_ex,
          cr.timesheets_itemisation,
          coalesce(bc.blocked_count,0) as blocked_count,
          coalesce(dpc.do_not_pay_count,0) as do_not_pay_count,

          -- ✅ bank readiness
          cr.candidate_has_bank_details,
          cr.candidate_bank_hash,
          cr.umbrella_has_bank_details,
          cr.umbrella_bank_hash,

          -- ✅ loan catch-up (legacy schedule)
          coalesce(ld.loan_due_total,0) as loan_due_total,
          coalesce(ld.loan_due_entries,'[]'::jsonb) as loan_due_entries,

          -- ✅ Policy B: overpayment + loan state (week-to-date)
          coalesce(ob.overpayment_balance_remaining,0) as overpayment_balance_remaining,
          coalesce(ldtw.loan_due_this_week,0) as loan_due_this_week,
          coalesce(lrw.loan_repaid_wtd,0) as loan_repaid_wtd,
          coalesce(cand.min_take_home_wtd,0) as min_take_home_wtd,
          round(
            case
              when cr.cand_pay_method = 'UMBRELLA' then
                least(
                  greatest(coalesce(ldtw.loan_due_this_week,0) - coalesce(lrw.loan_repaid_wtd,0),0),
                  greatest(
                    least(
                      -- earnings_after_recovery
                      (greatest(cr.non_mismatch_total_ex,0) - least(coalesce(ob.overpayment_balance_remaining,0), greatest(cr.non_mismatch_total_ex,0))),
                      -- above-floor cap
                      (coalesce(pwb.paid_wtd_before,0) + (greatest(cr.non_mismatch_total_ex,0) - least(coalesce(ob.overpayment_balance_remaining,0), greatest(cr.non_mismatch_total_ex,0)))) - coalesce(cand.min_take_home_wtd,0)
                    ),
                    0
                  )
                )
              else null
            end,
            2
          ) as max_possible_loan_take_this_run,
          case when cr.cand_pay_method = 'PAYE' then 'NET_REQUIRED' else 'NOT_REQUIRED' end as paye_net_status
        from candidate_rollup cr
        left join blocked_counts bc on bc.candidate_id = cr.candidate_id
        left join do_not_pay_counts dpc on dpc.candidate_id = cr.candidate_id
        left join loan_due ld on ld.candidate_id = cr.candidate_id
        left join overpayment_balances ob on ob.candidate_id = cr.candidate_id
        left join loan_due_this_week ldtw on ldtw.candidate_id = cr.candidate_id
        left join loan_repaid_wtd lrw on lrw.candidate_id = cr.candidate_id
        left join paid_wtd_before pwb on pwb.candidate_id = cr.candidate_id
        left join public.candidates cand on cand.id = cr.candidate_id
  
  ;

  create temporary table payee_baseline_rows on commit drop as
        select
          'CANDIDATE'::text as payee_entity_kind,
          ce.candidate_id as payee_entity_id,
          nullif(btrim(coalesce(ce.candidate_bank_hash,'')), '') as bank_details_hash
        from cand_enriched ce
        union all
        select
          'UMBRELLA'::text as payee_entity_kind,
          ce.cand_umbrella_id as payee_entity_id,
          nullif(btrim(coalesce(ce.umbrella_bank_hash,'')), '') as bank_details_hash
        from cand_enriched ce
        where ce.cand_umbrella_id is not null
        union all
        select
          'CANDIDATE'::text as payee_entity_kind,
          fcb.candidate_id as payee_entity_id,
          nullif(btrim(coalesce(obd.bank_details_hash,'')), '') as bank_details_hash
        from finance_case_baseline_scope fcb
        join public.pay_finance_case_oneoff_payout_bank_details obd
          on obd.finance_case_id = fcb.finance_case_id
        where fcb.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
        union all
        select
          case
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
            else 'CANDIDATE'
          end as payee_entity_kind,
          case
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c_fc.umbrella_id
            else fcb.candidate_id
          end as payee_entity_id,
          case
            when fcb.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then nullif(btrim(coalesce(obd.bank_details_hash,'')), '')
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then nullif(btrim(coalesce(u_fc.bank_details_hash,'')), '')
            else nullif(btrim(coalesce(c_fc.bank_details_hash,'')), '')
          end as bank_details_hash
        from finance_case_baseline_scope fcb
        join public.candidates c_fc
          on c_fc.id = fcb.candidate_id
        left join public.umbrellas u_fc
          on u_fc.id = c_fc.umbrella_id
        left join public.pay_finance_case_oneoff_payout_bank_details obd
          on obd.finance_case_id = fcb.finance_case_id
  
  ;

  create temporary table payees_src on commit drop as
        select
          pbr.payee_entity_kind,
          pbr.payee_entity_id,
          pbr.bank_details_hash
        from payee_baseline_rows pbr
        where pbr.payee_entity_id is not null
  
  ;

  create temporary table payees on commit drop as
        select
          upper(btrim(coalesce(ps.payee_entity_kind,''))) as payee_entity_kind,
          ps.payee_entity_id as payee_entity_id,
          ps.bank_details_hash as bank_details_hash
        from payees_src ps
        where ps.payee_entity_id is not null
        group by 1,2,3
  
  ;

  create temporary table payees_enriched on commit drop as
        select
          p.payee_entity_kind,
          p.payee_entity_id,
          p.bank_details_hash,

          b.payee_name,
          b.account_holder,
          b.bank_name,
          b.sort_code,
          b.account_number,
          b.account_type,

          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          bnc.checked_at_utc as name_check_checked_at_utc,
          bnc.override_reason as name_check_override_reason,
          bnc.override_by_user_id as name_check_override_by_user_id,
          bnc.override_at_utc as name_check_override_at_utc,
          bnc.override_hash as name_check_override_hash,
          (bnc.override_reason is not null and bnc.override_hash = p.bank_details_hash) as name_check_has_override,

          bpm.payee_id as payee_map_payee_id,
          bpm.payee_account_id as payee_map_payee_account_id,
          bpm.meta_json as payee_map_meta_json,
          (bpm.payee_id is not null) as payee_map_present,

          b.is_missing_bank_details as is_missing_bank_details,
          (p.payee_entity_kind = 'UMBRELLA' and coalesce(u_pay.enabled, false) = false) as is_umbrella_inactive,

          (
            v_need_name_check = true
            and b.is_missing_bank_details = false
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = p.bank_details_hash)
          ) as is_name_check_blocked,

          (
            v_requires_payee_map = true
            and b.is_missing_bank_details = false
            and (bpm.payee_id is null)
          ) as is_payee_map_blocked
        from payees p
        left join public.candidates c_pay
          on p.payee_entity_kind = 'CANDIDATE'
         and c_pay.id = p.payee_entity_id
        left join public.umbrellas u_pay
          on p.payee_entity_kind = 'UMBRELLA'
         and u_pay.id = p.payee_entity_id
        left join lateral (
          select
            vfcr_oneoff.finance_case_id,
            obd.beneficiary_name,
            obd.sort_code,
            obd.account_number,
            obd.bank_details_hash
          from finance_case_baseline_scope vfcr_oneoff
          join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr_oneoff.finance_case_id
          where p.payee_entity_kind = 'CANDIDATE'
            and vfcr_oneoff.candidate_id = p.payee_entity_id
            and vfcr_oneoff.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
            and obd.bank_details_hash is not distinct from p.bank_details_hash
          order by vfcr_oneoff.finance_case_id
          limit 1
        ) obd_pay on true

        left join lateral (
          select
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
              when p.payee_entity_kind = 'CANDIDATE' then c_pay.display_name
              else u_pay.name
            end as payee_name,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
              when p.payee_entity_kind = 'CANDIDATE' then c_pay.account_holder
              else u_pay.name
            end as account_holder,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then null::text
              else coalesce(c_pay.bank_name, u_pay.bank_name)
            end as bank_name,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.sort_code
              else coalesce(c_pay.sort_code, u_pay.sort_code)
            end as sort_code,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.account_number
              else coalesce(c_pay.account_number, u_pay.account_number)
            end as account_number,
            case
              when p.payee_entity_kind = 'CANDIDATE' then 'personal'
              else 'business'
            end as account_type,
            (
              p.bank_details_hash is null
              or btrim(p.bank_details_hash) = ''
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
                      when p.payee_entity_kind = 'CANDIDATE' then c_pay.account_holder
                      else u_pay.name
                    end,
                    ''
                  )), '') is null
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.sort_code
                      else coalesce(c_pay.sort_code, u_pay.sort_code)
                    end,
                    ''
                  )), '') is null
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.account_number
                      else coalesce(c_pay.account_number, u_pay.account_number)
                    end,
                    ''
                  )), '') is null
            ) as is_missing_bank_details
        ) b on true

        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = p.payee_entity_kind
         and bnc.entity_id = p.payee_entity_id
         and bnc.bank_details_hash is not distinct from p.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = p.payee_entity_kind
         and bpm.entity_id = p.payee_entity_id
         and bpm.bank_details_hash is not distinct from p.bank_details_hash
  
  ;

  create temporary table payees_json on commit drop as
        select
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'payee_entity_kind', pe.payee_entity_kind,
                'payee_entity_id', pe.payee_entity_id::text,
                'bank_details_hash', pe.bank_details_hash,

                -- ✅ Bank fields required to call the rail
                'payee_name', pe.payee_name,
                'account_holder', pe.account_holder,
                'bank_name', pe.bank_name,
                'sort_code', pe.sort_code,
                'account_number', pe.account_number,
                'account_type', pe.account_type,

                -- ✅ Name-check details (status + timestamps + override metadata)
                'name_check', jsonb_build_object(
                  'status', pe.name_check_status,
                  'checked_at_utc', pe.name_check_checked_at_utc,
                  'has_override', (pe.name_check_has_override = true),
                  'override_reason', pe.name_check_override_reason,
                  'override_by_user_id', case when pe.name_check_override_by_user_id is null then null else pe.name_check_override_by_user_id::text end,
                  'override_at_utc', pe.name_check_override_at_utc,
                  'override_hash', pe.name_check_override_hash
                ),

                -- ✅ Payee map details (presence + IDs)
                'payee_map', jsonb_build_object(
                  'present', (pe.payee_map_present = true),
                  'payee_id', pe.payee_map_payee_id,
                  'payee_account_id', pe.payee_map_payee_account_id
                ),

                'blockers',
                  (
                    (case when pe.is_missing_bank_details then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
                    ||
                    (case when pe.is_umbrella_inactive then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE') else '[]'::jsonb end)
                    ||
                    (case when pe.is_name_check_blocked then jsonb_build_array('BLOCKED_NAME_CHECK') else '[]'::jsonb end)
                    ||
                    (case when pe.is_payee_map_blocked then jsonb_build_array('BLOCKED_NO_PAYEE_MAP') else '[]'::jsonb end)
                  )
              )
              order by pe.payee_entity_kind, pe.payee_entity_id::text
            ),
            '[]'::jsonb
          ) as payees
        from payees_enriched pe
  
  ;

  create temporary table cand_payee0 on commit drop as
        select
          ce.*,
          case when ce.cand_pay_method = 'PAYE' then 'CANDIDATE' else 'UMBRELLA' end as payee_entity_kind,
          case when ce.cand_pay_method = 'PAYE' then ce.candidate_id else ce.cand_umbrella_id end as payee_entity_id,
          case when ce.cand_pay_method = 'PAYE' then nullif(btrim(coalesce(ce.candidate_bank_hash,'')), '') else nullif(btrim(coalesce(ce.umbrella_bank_hash,'')), '') end as payee_bank_hash
        from cand_enriched ce
  
  ;

  create temporary table cand_payee on commit drop as
        select
          cp.*,

          coalesce(pe.name_check_status, 'UNVERIFIED') as payee_name_check_status,
          coalesce(pe.name_check_has_override, false) as payee_name_check_has_override,
          coalesce(pe.payee_map_present, false) as payee_map_present,

          (
            (case when (cp.payee_entity_id is null or cp.payee_bank_hash is null or btrim(cp.payee_bank_hash) = '') then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
            ||
            (case
               when (cp.payee_entity_kind = 'UMBRELLA' and coalesce(cp.umb_enabled, false) = false)
               then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE')
               else '[]'::jsonb
             end)
            ||
            (case
               when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_need_name_check = true and coalesce(pe.name_check_status,'UNVERIFIED') <> 'PASS' and not coalesce(pe.name_check_has_override,false))
               then jsonb_build_array('BLOCKED_NAME_CHECK')
               else '[]'::jsonb
             end)
            ||
            (case
               when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_requires_payee_map = true and not coalesce(pe.payee_map_present,false))
               then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
               else '[]'::jsonb
             end)
          ) as blockers,

          (
            jsonb_array_length(
              (
                (case when (cp.payee_entity_id is null or cp.payee_bank_hash is null or btrim(cp.payee_bank_hash) = '') then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
                ||
                (case
                   when (cp.payee_entity_kind = 'UMBRELLA' and coalesce(cp.umb_enabled, false) = false)
                   then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE')
                   else '[]'::jsonb
                 end)
                ||
                (case
                   when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_need_name_check = true and coalesce(pe.name_check_status,'UNVERIFIED') <> 'PASS' and not coalesce(pe.name_check_has_override,false))
                   then jsonb_build_array('BLOCKED_NAME_CHECK')
                   else '[]'::jsonb
                 end)
                ||
                (case
                   when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_requires_payee_map = true and not coalesce(pe.payee_map_present,false))
                   then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
                   else '[]'::jsonb
                 end)
              )
            ) = 0
          ) as is_ready_for_draft
        from cand_payee0 cp
        left join payees_enriched pe
          on pe.payee_entity_kind = cp.payee_entity_kind
         and pe.payee_entity_id = cp.payee_entity_id
         and pe.bank_details_hash is not distinct from cp.payee_bank_hash
  
  ;

  create temporary table timesheet_case_rollup_effective on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tcr.client_id,
          tcr.ts_week_ending_date,
          tcr.ts_client_name,
          tcr.ts_pay_method,
          tcr.cand_pay_method,
          tcr.cand_tms_ref,
          tcr.cand_display_name,
          tcr.cand_umbrella_id,
          tcr.umb_enabled,
          tcr.umb_vat_chargeable,
          tcr.candidate_has_bank_details,
          tcr.candidate_bank_hash,
          tcr.umbrella_has_bank_details,
          tcr.umbrella_bank_hash,
          tcr.resolution_family,
          tcr.case_needs_resolution,
          tcr.case_resolution_satisfied_now,
          tcr.resolution_action_label,
          tcr.linked_resolution_scope_json,
          tcr.case_total_amount_ex,
          case
            when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
            then 0::numeric
            else tcr.safe_amount_ex
          end as safe_amount_ex,
          tcr.unresolved_taxable_amount_ex,
          tcr.open_taxable_count,
          tcr.open_reimbursement_count,
          tcr.unresolved_taxable_count,
          tcr.stale_count,
          tcr.is_mixed_case,
          (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false)) as is_blocked,
          tcr.segments_total_ex,
          tcr.delta_additional_pay_ex_vat,
          tcr.delta_expenses_pay_ex_vat,
          tcr.delta_travel_pay_ex_vat,
          tcr.delta_accommodation_pay_ex_vat,
          tcr.delta_other_pay_ex_vat,
          tcr.delta_mileage_pay_ex_vat,
          tcr.segment_deltas_json,
          tcr.adjustment_deltas_json,
          tcr.additional_unit_deltas_json,
          tcr.reservation_overrun_detected,
          tcr.payment_amount_ex_vat,
          tcr.payment_amount_inc_vat,
          tcr.payment_amount,
          (
            coalesce(tcr.case_resolution_summary_json, '{}'::jsonb)
            || jsonb_build_object(
              'is_blocked', (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false)),
              'resolution_family', tcr.resolution_family,
              'case_needs_resolution', tcr.case_needs_resolution,
              'case_resolution_satisfied_now', (tcr.case_resolution_satisfied_now and coalesce(cp.is_ready_for_draft, false)),
              'resolution_action_label', tcr.resolution_action_label,
              'linked_resolution_scope_json', tcr.linked_resolution_scope_json,
              'safe_amount_ex_vat', case
                when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
                then 0::numeric
                else coalesce(tcr.case_total_amount_ex, 0)
              end,
              'blocked_case_amount_ex_vat', case
                when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
                then coalesce(tcr.case_total_amount_ex, 0)
                else 0::numeric
              end,
              'blocked_reason_codes', case
                when coalesce(tcr.is_blocked, false) = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                else '[]'::jsonb
              end
            )
          ) as case_resolution_summary_json,
          tcr.case_components_json
        from timesheet_case_rollup_payable tcr
        left join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'candidate_rollup_count', (select count(*)::int from candidate_rollup),
    'payee_count', (select count(*)::int from payees_enriched),
    'candidate_payee_count', (select count(*)::int from cand_payee),
    'timesheet_case_rollup_effective_count', (select count(*)::int from timesheet_case_rollup_effective)
  );
end;
$function$;

-- pay_preview_candidate_build_summary_fragment(jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_summary_fragment(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_paye jsonb := '[]'::jsonb;
  v_nonpaye jsonb := '[]'::jsonb;
  v_blocked jsonb := '[]'::jsonb;
  v_do_not_pay jsonb := '[]'::jsonb;
  v_snoozed jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_canonical_preview_lines jsonb := '[]'::jsonb;
  v_paye_summary_breakdown jsonb := '{}'::jsonb;
  v_case_resolution_states jsonb := '[]'::jsonb;
  v_candidate_row jsonb := '{}'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_filtered_canonical_preview_lines jsonb := '[]'::jsonb;
  v_carry_forward_itemisation jsonb := '[]'::jsonb;
  v_carry_forward_total_ex_vat numeric := 0;
  v_carry_forward_total_vat numeric := 0;
  v_carry_forward_total_inc_vat numeric := 0;
  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_preview_row_count integer := 0;
  v_draftable_row_count integer := 0;
  v_blocked_row_count integer := 0;
  v_do_not_pay_row_count integer := 0;
  v_case_resolution_row_count integer := 0;
  v_pending_line_count integer := 0;
  v_ready_line_count integer := 0;
  v_materialised_line_count integer := 0;
  v_error_line_count integer := 0;
  v_total_amount_ex_vat numeric := 0;
  v_draftable_amount_ex_vat numeric := 0;
  v_ordinary_positive_selectable_count integer := 0;
  v_ordinary_positive_selectable_amount numeric := 0;
  v_recognised_deduction_selectable_count integer := 0;
  v_recognised_deduction_selectable_amount numeric := 0;
  v_negative_ordinary_blocked_count integer := 0;
  v_negative_ordinary_cases_count integer := 0;
  v_invalid_ready_negative_parent_count integer := 0;
  v_preview_section_counts jsonb := '{}'::jsonb;
  v_semantic_ready_publication_enabled boolean := false;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled,false)
  INTO v_semantic_ready_publication_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF v_workbench_session_id IS NOT NULL THEN
    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_workbench_session_id
      AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_SUMMARY_FRAGMENT_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_SUMMARY_FRAGMENT_SESSION_NOT_OPEN',
                'session_id', v_workbench_session_id::text,
                'candidate_id', v_candidate_id::text
              )::text;
    END IF;

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (
        WHERE COALESCE(preview_row.selected, false) = true
          AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED')
          AND (
            COALESCE(v_semantic_ready_publication_enabled,false) IS NOT TRUE
            OR (
              LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable','false'))) IN ('true','t','1','yes','y','on')
              AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
              AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
            )
          )
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) = 'DO_NOT_PAY'
           OR LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_do_not_pay', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) = 'CASES_RESOLUTIONS'
      )::integer,
      COALESCE(SUM(CASE
        WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
         AND (
           COALESCE(v_semantic_ready_publication_enabled,false) IS NOT TRUE
           OR (
             LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable','false'))) IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
           )
         )
        THEN (preview_row.row_json->>'amount_ex_vat')::numeric
        ELSE 0::numeric
      END), 0::numeric),
      COALESCE(SUM(CASE
        WHEN COALESCE(preview_row.selected, false) = true
         AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED')
         AND COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
         AND (
           COALESCE(v_semantic_ready_publication_enabled,false) IS NOT TRUE
           OR (
             LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable','false'))) IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
           )
         )
        THEN (preview_row.row_json->>'amount_ex_vat')::numeric
        ELSE 0::numeric
      END), 0::numeric),
      COUNT(*) FILTER (
        WHERE preview_row.row_json->>'line_type' = 'TIMESHEET_PAYMENT'
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END > 0
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
      )::integer,
      COALESCE(SUM(CASE
        WHEN preview_row.row_json->>'line_type' = 'TIMESHEET_PAYMENT'
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END > 0
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
        THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END),0::numeric),
      COUNT(*) FILTER (
        WHERE preview_row.row_json->>'line_type' IN ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END < 0
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
      )::integer,
      COALESCE(SUM(CASE
        WHEN preview_row.row_json->>'line_type' IN ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END < 0
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed','false'))) IN ('true','t','1','yes','y','on')
          AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_excluded_from_allocation','false'))) NOT IN ('true','t','1','yes','y','on')
        THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END),0::numeric),
      COUNT(*) FILTER (
        WHERE preview_row.row_json->>'line_type'='TIMESHEET_PAYMENT'
          AND COALESCE(preview_row.row_json->>'presentation_role','')='PARENT'
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END < 0
          AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section','')))='BLOCKED_FOR_PAY'
      )::integer,
      COUNT(*) FILTER (
        WHERE preview_row.row_json->>'line_type'='TIMESHEET_PAYMENT'
          AND COALESCE(preview_row.row_json->>'presentation_role','')='PARENT'
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END < 0
          AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section','')))='CASES_RESOLUTIONS'
      )::integer,
      COUNT(*) FILTER (
        WHERE preview_row.row_json->>'line_type'='TIMESHEET_PAYMENT'
          AND COALESCE(preview_row.row_json->>'presentation_role','')='PARENT'
          AND COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
          AND CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END < 0
          AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section','')))='READY_TO_PAY'
      )::integer
    INTO
      v_preview_row_count,
      v_draftable_row_count,
      v_blocked_row_count,
      v_do_not_pay_row_count,
      v_case_resolution_row_count,
      v_total_amount_ex_vat,
      v_draftable_amount_ex_vat,
      v_ordinary_positive_selectable_count,
      v_ordinary_positive_selectable_amount,
      v_recognised_deduction_selectable_count,
      v_recognised_deduction_selectable_amount,
      v_negative_ordinary_blocked_count,
      v_negative_ordinary_cases_count,
      v_invalid_ready_negative_parent_count
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_workbench_session_id
      AND preview_row.candidate_id = v_candidate_id;

    SELECT
      COALESCE(
        jsonb_object_agg(section_counts.section_key, section_counts.section_count ORDER BY section_counts.section_key),
        '{}'::jsonb
      )
    INTO v_preview_section_counts
    FROM (
      SELECT
        COALESCE(NULLIF(BTRIM(COALESCE(preview_row.section, '')), ''), 'canonical_preview_lines') AS section_key,
        COUNT(*)::integer AS section_count
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = v_workbench_session_id
        AND preview_row.candidate_id = v_candidate_id
      GROUP BY COALESCE(NULLIF(BTRIM(COALESCE(preview_row.section, '')), ''), 'canonical_preview_lines')
    ) AS section_counts;

    SELECT
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING')::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'READY')::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'MATERIALISED')::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'ERROR')::integer
    INTO
      v_pending_line_count,
      v_ready_line_count,
      v_materialised_line_count,
      v_error_line_count
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    WHERE line_work.session_id = v_workbench_session_id
      AND line_work.candidate_id = v_candidate_id;

    v_summary := jsonb_build_object(
      'candidate_count', 1,
      'canonical_preview_line_count', COALESCE(v_preview_row_count, 0),
      'ready_preview_line_count', COALESCE(v_draftable_row_count, 0),
      'blocked_preview_line_count', COALESCE(v_blocked_row_count, 0),
      'do_not_pay_line_count', COALESCE(v_do_not_pay_row_count, 0),
      'case_resolution_state_count', COALESCE(v_case_resolution_row_count, 0),
      'pending_line_work_count', COALESCE(v_pending_line_count, 0),
      'ready_line_work_count', COALESCE(v_ready_line_count, 0),
      'materialised_line_work_count', COALESCE(v_materialised_line_count, 0),
      'error_line_work_count', COALESCE(v_error_line_count, 0),
      'preview_section_counts', COALESCE(v_preview_section_counts, '{}'::jsonb),
      'total_amount_ex_vat', round(COALESCE(v_total_amount_ex_vat, 0), 2),
      'draftable_amount_ex_vat', round(COALESCE(v_draftable_amount_ex_vat, 0), 2),
      'ordinary_positive_selectable_count', COALESCE(v_ordinary_positive_selectable_count, 0),
      'ordinary_positive_selectable_amount', round(COALESCE(v_ordinary_positive_selectable_amount, 0), 2),
      'recognised_deduction_selectable_count', COALESCE(v_recognised_deduction_selectable_count, 0),
      'recognised_deduction_selectable_amount', round(COALESCE(v_recognised_deduction_selectable_amount, 0), 2),
      'negative_ordinary_blocked_count', COALESCE(v_negative_ordinary_blocked_count, 0),
      'negative_ordinary_cases_count', COALESCE(v_negative_ordinary_cases_count, 0),
      'invalid_ready_negative_parent_count', COALESCE(v_invalid_ready_negative_parent_count, 0),
      'semantic_ready_publication_enabled',COALESCE(v_semantic_ready_publication_enabled,false),
      'is_ready_for_draft', (COALESCE(v_draftable_row_count, 0) > 0 AND COALESCE(v_error_line_count, 0) = 0),
      'is_review_required', (COALESCE(v_blocked_row_count, 0) > 0 OR COALESCE(v_do_not_pay_row_count, 0) > 0 OR COALESCE(v_case_resolution_row_count, 0) > 0 OR COALESCE(v_error_line_count, 0) > 0),
      'row_backed', true
    );

    v_candidate_row := jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'row_backed', true,
      'is_ready_for_draft', (COALESCE(v_draftable_row_count, 0) > 0 AND COALESCE(v_error_line_count, 0) = 0),
      'is_review_required', (COALESCE(v_blocked_row_count, 0) > 0 OR COALESCE(v_do_not_pay_row_count, 0) > 0 OR COALESCE(v_case_resolution_row_count, 0) > 0 OR COALESCE(v_error_line_count, 0) > 0),
      'preview_row_count', COALESCE(v_preview_row_count, 0),
      'draftable_preview_row_count', COALESCE(v_draftable_row_count, 0),
      'pending_line_work_count', COALESCE(v_pending_line_count, 0),
      'ready_line_work_count', COALESCE(v_ready_line_count, 0),
      'materialised_line_work_count', COALESCE(v_materialised_line_count, 0),
      'error_line_work_count', COALESCE(v_error_line_count, 0)
    );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'workbench_session_id', v_workbench_session_id::text,
      'row_backed_summary_fragment', true,
      'candidate_row', v_candidate_row,
      'summary_fragment', v_summary,
      'case_resolution_states', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'paye_candidates', '[]'::jsonb,
      'non_paye_candidates', '[]'::jsonb,
      'paye_summary_breakdown', '{}'::jsonb
    );
  END IF;


  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.canonical_preview_lines') is null then
    perform public.pay_preview_candidate_build_canonical_lines(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.summary_json, pg_temp.timesheet_case_states_flat, pg_temp.finance_case_states_flat, pg_temp.candidate_case_states_flat, pg_temp.candidate_case_states, pg_temp.case_resolution_states_json, pg_temp.finance_candidate_totals, pg_temp.candidate_finance_itemisation, pg_temp.candidate_timesheet_itemisation_merged, pg_temp.paye_summary_breakdown_json, pg_temp.timesheet_baseline_component_rows, pg_temp.finance_baseline_component_rows, pg_temp.baseline_component_rows_json;

  create temporary table summary_json on commit drop as
        select
          jsonb_build_object(
            'readiness', jsonb_build_object(
              'payees_total', pr.payees_total,
              'payees_need_name_check', pr.payees_need_name_check,
              'payees_need_payee_map', pr.payees_need_payee_map,
              'payees_missing_bank_details', pr.payees_missing_bank_details
            ),
            'candidates', jsonb_build_object(
              'ready_count', cr.ready_count,
              'review_required_count', cr.review_required_count,
              'total_candidates', cr.total_candidates
            )
          ) as summary
        from (
          select
            count(*)::int as payees_total,
            sum(case when pe.is_missing_bank_details then 1 else 0 end)::int as payees_missing_bank_details,
            sum(case when pe.is_name_check_blocked then 1 else 0 end)::int as payees_need_name_check,
            sum(case when pe.is_payee_map_blocked then 1 else 0 end)::int as payees_need_payee_map
          from payees_enriched pe
        ) pr
        cross join (
          select
            count(*)::int as total_candidates,
            sum(
              case when
                (
                  (coalesce(cp.non_mismatch_total_ex,0) <> 0
                   or coalesce(cp.mismatch_source_paye_ex,0) <> 0
                   or coalesce(cp.mismatch_source_umbrella_ex,0) <> 0)
                  and cp.is_ready_for_draft = true
                  and coalesce(cp.blocked_count,0) = 0
                  and coalesce(cp.do_not_pay_count,0) = 0
                  and cp.has_mismatch = false
                )
              then 1 else 0 end
            )::int as ready_count,
            sum(
              case when
                (
                  (coalesce(cp.non_mismatch_total_ex,0) <> 0
                   or coalesce(cp.mismatch_source_paye_ex,0) <> 0
                   or coalesce(cp.mismatch_source_umbrella_ex,0) <> 0)
                  and (
                    cp.has_mismatch = true
                    or jsonb_array_length(cp.blockers) > 0
                    or coalesce(cp.blocked_count,0) > 0
                    or coalesce(cp.do_not_pay_count,0) > 0
                  )
                )
              then 1 else 0 end
            )::int as review_required_count
          from cand_payee cp
        ) cr
  
  ;

  create temporary table timesheet_case_states_flat on commit drop as
        select
          tcr.candidate_id,
          tcr.cand_display_name as sort_candidate_display,
          tcr.cand_tms_ref as sort_candidate_tms_ref,
          1 as sort_case_order,
          ('timesheet:' || tcr.timesheet_id::text) as case_key,
          true as is_blocked,
          jsonb_build_object(
            'case_key', ('timesheet:' || tcr.timesheet_id::text),
            'case_scope', 'TIMESHEET_PAYMENT',
            'finance_case_id', null,
            'case_type', 'TIMESHEET_PAYMENT',
            'timesheet_id', tcr.timesheet_id::text,
            'candidate_id', tcr.candidate_id::text,
            'client_id', case when tcr.client_id is null then null else tcr.client_id::text end,
            'client_name', tcr.ts_client_name,
            'week_ending_date', case when tcr.ts_week_ending_date is null then null else tcr.ts_week_ending_date::text end,
            'source_pay_method', tcr.ts_pay_method,
            'candidate_pay_method', tcr.cand_pay_method,
            'resolution_family', tcr.resolution_family,
            'case_needs_resolution', tcr.case_needs_resolution,
            'case_resolution_satisfied_now', tcr.case_resolution_satisfied_now,
            'resolution_action_label', tcr.resolution_action_label,
            'linked_resolution_scope_json', tcr.linked_resolution_scope_json,
            'is_blocked', true,
            'is_mixed_case', tcr.is_mixed_case,
            'open_taxable_count', tcr.open_taxable_count,
            'open_reimbursement_count', tcr.open_reimbursement_count,
            'unresolved_taxable_count', tcr.unresolved_taxable_count,
            'stale_count', tcr.stale_count,
            'safe_amount_ex_vat', tcr.safe_amount_ex,
            'unresolved_taxable_amount_ex_vat', tcr.unresolved_taxable_amount_ex,
            'case_resolution_summary', tcr.case_resolution_summary_json,
            'components', tcr.case_components_json
          ) as case_json
        from timesheet_case_rollup_effective tcr
        where coalesce(tcr.case_needs_resolution, false) = true
          and coalesce(tcr.case_resolution_satisfied_now, false) = false
  
  ;

  create temporary table finance_case_states_flat on commit drop as
        select
          fcrr.candidate_id,
          fcrr.cand_display_name as sort_candidate_display,
          fcrr.cand_tms_ref as sort_candidate_tms_ref,
          2 as sort_case_order,
          ('finance:' || fcrr.finance_case_id::text) as case_key,
          true as is_blocked,
          jsonb_build_object(
            'case_key', ('finance:' || fcrr.finance_case_id::text),
            'case_scope', 'FINANCE_CASE',
            'finance_case_id', fcrr.finance_case_id::text,
            'timesheet_id', case when fcrr.linked_timesheet_id is null then null else fcrr.linked_timesheet_id::text end,
            'candidate_id', fcrr.candidate_id::text,
            'client_id', case when fcrr.client_id is null then null else fcrr.client_id::text end,
            'client_name', fcrr.client_name,
            'linked_shift_date', case when fcrr.linked_shift_date is null then null else fcrr.linked_shift_date::text end,
            'next_due_week_start', case when fcrr.next_due_week_start is null then null else fcrr.next_due_week_start::text end,
            'case_type', fcrr.case_type::text,
            'candidate_pay_method', fcrr.candidate_pay_method,
            'taxability', case when fcrr.taxability is null then null else fcrr.taxability::text end,
            'routing_kind', case when fcrr.routing_kind is null then null else fcrr.routing_kind::text end,
            'destination_label', fcrr.destination_label,
            'resolution_family', fcrr.resolution_family,
            'case_needs_resolution', fcrr.case_needs_resolution,
            'case_resolution_satisfied_now', fcrr.case_resolution_satisfied_now,
            'resolution_action_label', fcrr.resolution_action_label,
            'linked_resolution_scope_json', fcrr.linked_resolution_scope_json,
            'blocked_reason_codes', fcrr.blocked_reason_codes,
            'snooze_allowed', fcrr.snooze_allowed,
            'is_blocked', true,
            'is_mixed_case', fcrr.is_mixed_case,
            'open_taxable_count', fcrr.open_taxable_count,
            'open_reimbursement_count', fcrr.open_reimbursement_count,
            'unresolved_taxable_count', fcrr.unresolved_taxable_count,
            'stale_count', fcrr.stale_count,
            'due_amount_ex_vat', fcrr.due_amount_ex_vat,
            'case_resolution_summary', fcrr.case_resolution_summary_json,
            'components', fcrr.case_components_json
          ) || jsonb_strip_nulls(
            jsonb_build_object(
              'taxable_manual_debt_resolution', fcrr.taxable_manual_debt_resolution_json
            )
          ) as case_json
        from finance_case_resolution_rollup fcrr
        where fcrr.due_amount_ex_vat > 0
          and coalesce(fcrr.case_needs_resolution, false) = true
          and coalesce(fcrr.case_resolution_satisfied_now, false) = false
  
  ;

  create temporary table candidate_case_states_flat on commit drop as
        select
          tcsf.candidate_id,
          tcsf.sort_candidate_display,
          tcsf.sort_candidate_tms_ref,
          tcsf.sort_case_order,
          tcsf.case_key,
          tcsf.is_blocked,
          tcsf.case_json
        from timesheet_case_states_flat tcsf

        union all

        select
          fcsf.candidate_id,
          fcsf.sort_candidate_display,
          fcsf.sort_candidate_tms_ref,
          fcsf.sort_case_order,
          fcsf.case_key,
          fcsf.is_blocked,
          fcsf.case_json
        from finance_case_states_flat fcsf
  
  ;

  create temporary table candidate_case_states on commit drop as
        select
          ccsf.candidate_id,
          count(*)::int as total_case_count,
          sum(case when ccsf.is_blocked then 1 else 0 end)::int as blocked_case_count,
          sum(case when ccsf.is_blocked then 0 else 1 end)::int as safe_case_count,
          coalesce(jsonb_agg(ccsf.case_json order by ccsf.sort_case_order, ccsf.case_key), '[]'::jsonb) as case_resolution_states
        from candidate_case_states_flat ccsf
        group by ccsf.candidate_id
  
  ;

  create temporary table case_resolution_states_json on commit drop as
        select coalesce(jsonb_agg(ccsf.case_json order by ccsf.sort_candidate_display nulls last, ccsf.sort_candidate_tms_ref nulls last, ccsf.sort_case_order, ccsf.case_key), '[]'::jsonb) as payload
        from candidate_case_states_flat ccsf
  
  ;

  create temporary table finance_candidate_totals on commit drop as
        select
          fcrr.candidate_id,
          round(sum(case when fcrr.due_amount_ex_vat > 0 then fcrr.due_amount_ex_vat else 0 end), 2) as finance_due_total_ex_vat,
          round(sum(case when fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = false then fcrr.due_amount_ex_vat else 0 end), 2) as finance_safe_due_total_ex_vat,
          round(sum(case when fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = true then fcrr.due_amount_ex_vat else 0 end), 2) as finance_blocked_due_total_ex_vat,
          count(*) filter (where fcrr.due_amount_ex_vat > 0) as finance_due_case_count,
          count(*) filter (where fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = false) as finance_safe_case_count,
          count(*) filter (where fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = true) as finance_blocked_case_count
        from finance_case_resolution_rollup fcrr
        where fcrr.due_amount_ex_vat > 0
        group by fcrr.candidate_id
  
  ;

  create temporary table candidate_finance_itemisation on commit drop as
        select
          fcl.candidate_id,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'case_type', fcl.case_type::text,
                'line_type', fcl.line_type,
                'item_type_label', fcl.item_type_label,
                'item_direction', fcl.item_direction,
                'client_id', case when fcl.client_id is null then null else fcl.client_id::text end,
                'client_name', fcl.client_name,
                'linked_shift_date', case when fcl.linked_shift_date is null then null else fcl.linked_shift_date::text end,
                'next_due_week_start', case when fcl.next_due_week_start is null then null else fcl.next_due_week_start::text end,
                'taxability', case when fcl.taxability is null then null else fcl.taxability::text end,
                'routing_kind', case when fcl.routing_kind is null then null else fcl.routing_kind::text end,
                'destination_label', fcl.destination_label,
                'amount_ex_vat', fcl.signed_amount_ex_vat,
                'amount_display', fcl.signed_amount_ex_vat,
                'nominal_due_amount_ex_vat', round(coalesce(fcl.nominal_due_amount_ex_vat, 0), 2),
                'recoverable_this_pay_run_ex_vat', round(greatest(coalesce(fcl.due_amount_ex_vat, 0), 0), 2),
                'paye_treatment', fcl.paye_treatment,
                'presentation_section', fcl.readiness_state,
                'case_resolution_summary', fcl.case_resolution_summary_json,
                'components', fcl.case_components_json
              ) || jsonb_strip_nulls(
                jsonb_build_object(
                  'taxable_manual_debt_resolution', fcl.taxable_manual_debt_resolution_json
                )
              )
              order by fcl.case_type::text, fcl.finance_case_id
            ),
            '[]'::jsonb
          ) as finance_itemisation
        from finance_case_lines fcl
        group by fcl.candidate_id
  
  ;

  create temporary table candidate_timesheet_itemisation_merged on commit drop as
        select
          ce.candidate_id,
          (
            coalesce(
              (
                select
                  jsonb_agg(
                    case
                      when ready_match.ready_item is null then base_items.base_item
                      else (base_items.base_item || ready_match.ready_item)
                    end
                    order by base_items.base_ord
                  )
                from (
                  select
                    base_entry.base_ord,
                    base_entry.base_item,
                    coalesce(
                      nullif(btrim(coalesce(base_entry.base_item->>'case_key', '')), ''),
                      case
                        when nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), '') is null then null
                        else ('timesheet:' || nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), ''))
                      end
                    ) as match_key
                  from jsonb_array_elements(coalesce(ce.timesheets_itemisation, '[]'::jsonb)) with ordinality as base_entry(base_item, base_ord)
                ) base_items
                left join lateral (
                  select
                    ready_items.ready_item
                  from (
                    select
                      ready_entry.ready_item,
                      ready_entry.ready_ord,
                      coalesce(
                        nullif(btrim(coalesce(ready_entry.ready_item->>'case_key', '')), ''),
                        case
                          when nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), '') is null then null
                          else ('timesheet:' || nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), ''))
                        end
                      ) as match_key
                    from jsonb_array_elements(coalesce(cptr.ready_timesheets_itemisation, '[]'::jsonb)) with ordinality as ready_entry(ready_item, ready_ord)
                  ) ready_items
                  where ready_items.match_key is not null
                    and ready_items.match_key = base_items.match_key
                  order by ready_items.ready_ord
                  limit 1
                ) ready_match on true
              ),
              '[]'::jsonb
            )
            ||
            coalesce(
              (
                select
                  jsonb_agg(ready_items.ready_item order by ready_items.ready_ord)
                from (
                  select
                    ready_entry.ready_item,
                    ready_entry.ready_ord,
                    coalesce(
                      nullif(btrim(coalesce(ready_entry.ready_item->>'case_key', '')), ''),
                      case
                        when nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), '') is null then null
                        else ('timesheet:' || nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), ''))
                      end
                    ) as match_key
                  from jsonb_array_elements(coalesce(cptr.ready_timesheets_itemisation, '[]'::jsonb)) with ordinality as ready_entry(ready_item, ready_ord)
                ) ready_items
                where not exists (
                  select 1
                  from (
                    select
                      coalesce(
                        nullif(btrim(coalesce(base_entry.base_item->>'case_key', '')), ''),
                        case
                          when nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), '') is null then null
                          else ('timesheet:' || nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), ''))
                        end
                      ) as match_key
                    from jsonb_array_elements(coalesce(ce.timesheets_itemisation, '[]'::jsonb)) with ordinality as base_entry(base_item, base_ord)
                  ) base_keys
                  where base_keys.match_key is not null
                    and base_keys.match_key = ready_items.match_key
                )
              ),
              '[]'::jsonb
            )
          ) as merged_timesheets_itemisation
        from cand_payee ce
        left join candidate_preview_timesheet_rollup cptr
          on cptr.candidate_id = ce.candidate_id

  ;

  create temporary table paye_summary_breakdown_json on commit drop as
        select jsonb_build_object(
          'gross_side_additions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'GROSS_ADD' and cpl.is_excluded_from_allocation = false then greatest(cpl.amount_ex_vat,0) else 0 end),0),2),
          'gross_side_deductions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'GROSS_DEDUCT' and cpl.is_excluded_from_allocation = false then abs(cpl.amount_ex_vat) else 0 end),0),2),
          'net_side_additions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'NET_ADD' and cpl.is_excluded_from_allocation = false then greatest(cpl.amount_ex_vat,0) else 0 end),0),2),
          'net_side_deductions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'NET_DEDUCT' and cpl.is_excluded_from_allocation = false then abs(cpl.amount_ex_vat) else 0 end),0),2)
        ) as payload
        from canonical_preview_lines cpl
  
  ;

  create temporary table timesheet_baseline_component_rows on commit drop as
        select
          1 as sort_scope,
          ('timesheet:' || ttr.timesheet_id::text) as sort_case_key,
          coalesce(ttr.component_fingerprint, '') as sort_component_fingerprint,
          coalesce(ttr.component_key_type, '') as sort_component_key_type,
          coalesce(ttr.component_key_value, '') as sort_component_key_value,
          jsonb_strip_nulls(
            jsonb_build_object(
              'component_scope', 'TIMESHEET',
              'candidate_id', ttr.candidate_id::text,
              'case_key', ('timesheet:' || ttr.timesheet_id::text),
              'timesheet_id', ttr.timesheet_id::text,
              'finance_case_id', null,
              'finance_component_id', null,
              'source_family_key', ttr.source_family_key,
              'component_key_type', ttr.component_key_type,
              'component_key_value', ttr.component_key_value,
              'bucket_code', nullif(btrim(coalesce(ttr.source_basis_json->>'bucket_code', '')), ''),
              'source_basis_json', coalesce(ttr.source_basis_json, '{}'::jsonb),
              'source_basis_fingerprint', case when coalesce(ttr.source_basis_json, '{}'::jsonb) <> '{}'::jsonb then md5(ttr.source_basis_json::text) else null::text end,
              'component_fingerprint', ttr.component_fingerprint,
              'classification', ttr.classification::text,
              'source_pay_method', ttr.source_pay_method,
              'current_target_pay_method', ttr.current_target_pay_method,
              'source_units', case when ttr.source_units is null then null else round(ttr.source_units, 6) end,
              'source_rate', case when ttr.source_rate is null then null else round(ttr.source_rate, 6) end,
              'source_charge_rate', case when ttr.source_charge_rate is null then null else round(ttr.source_charge_rate, 6) end,
              'component_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat, 0), 2),
              'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat, 2) end,
              'source_pay_ex_vat', case when ttr.source_pay_ex_vat is null then null else round(ttr.source_pay_ex_vat, 2) end,
              'source_margin_ex_vat', case when ttr.source_margin_ex_vat is null then null else round(ttr.source_margin_ex_vat, 2) end,
              'target_pay_ex_vat', case when ttr.target_pay_ex_vat is null then null else round(ttr.target_pay_ex_vat, 2) end,
              'target_charge_ex_vat', case when ttr.target_charge_ex_vat is null then null else round(ttr.target_charge_ex_vat, 2) end,
              'target_margin_ex_vat', case when ttr.target_margin_ex_vat is null then null else round(ttr.target_margin_ex_vat, 2) end,
              'requires_resolution', coalesce(ttr.requires_resolution, false),
              'case_resolution_satisfied_now_component', coalesce(ttr.case_resolution_satisfied_now_component, false),
              'has_suggested_resolution', coalesce(ttr.has_suggested_resolution, false),
              'suggestion_provenance', ttr.suggestion_provenance,
              'approved_resolution_mode', case when ttr.approved_resolution_mode is null then null else ttr.approved_resolution_mode::text end,
              'approved_target_rate', case when ttr.approved_target_rate is null then null else round(ttr.approved_target_rate, 6) end,
              'suggested_resolution_payload_json', ttr.suggested_resolution_payload_json,
              'suggested_resolution_result_json', ttr.suggested_resolution_result_json,
              'is_actionable_resolution_row', coalesce(ttr.is_actionable_resolution_row, false),
              'is_fixed_no_action_taxable_row', coalesce(ttr.is_fixed_no_action_taxable_row, false)
            )
          ) as row_json
        from transient_timesheet_component_review_rows_effective ttr
        where ttr.candidate_id = v_candidate_id
  
  ;

  create temporary table finance_baseline_component_rows on commit drop as
        select
          2 as sort_scope,
          ('finance:' || fcr.finance_case_id::text) as sort_case_key,
          coalesce(fcr.current_component_fingerprint, '') as sort_component_fingerprint,
          coalesce(fcr.component_key_type, '') as sort_component_key_type,
          coalesce(fcr.component_key_value, '') as sort_component_key_value,
          jsonb_strip_nulls(
            jsonb_build_object(
              'component_scope', 'FINANCE_CASE',
              'candidate_id', fcr.candidate_id::text,
              'case_key', ('finance:' || fcr.finance_case_id::text),
              'timesheet_id', null,
              'finance_case_id', fcr.finance_case_id::text,
              'finance_component_id', case when fcr.finance_component_id is null then null else fcr.finance_component_id::text end,
              'case_type', fcr.case_type::text,
              'taxability', case when fcr.taxability is null then null else fcr.taxability::text end,
              'source_family_key', fcr.source_family_key,
              'component_key_type', fcr.component_key_type,
              'component_key_value', fcr.component_key_value,
              'bucket_code', nullif(btrim(coalesce(fcr.source_basis_json->>'bucket_code', '')), ''),
              'source_basis_json', coalesce(fcr.source_basis_json, '{}'::jsonb),
              'source_basis_fingerprint', case when coalesce(fcr.source_basis_json, '{}'::jsonb) <> '{}'::jsonb then md5(fcr.source_basis_json::text) else null::text end,
              'component_fingerprint', fcr.current_component_fingerprint,
              'classification', fcr.classification::text,
              'source_pay_method', fcr.source_pay_method,
              'current_target_pay_method', fcr.current_target_pay_method,
              'saved_target_pay_method', fcr.saved_target_pay_method,
              'source_amount', round(coalesce(fcr.source_amount, 0), 2),
              'remaining_source_amount', round(coalesce(fcr.remaining_source_amount, 0), 2),
              'source_units', case when fcr.source_units is null then null else round(fcr.source_units, 6) end,
              'source_rate', case when fcr.source_rate is null then null else round(fcr.source_rate, 6) end,
              'source_charge_rate', case when fcr.source_charge_rate is null then null else round(fcr.source_charge_rate, 6) end,
              'source_charge_ex_vat', case when fcr.source_charge_component_ex_vat is null then null else round(fcr.source_charge_component_ex_vat, 2) end,
              'source_pay_ex_vat', case when fcr.source_pay_ex_vat is null then null else round(fcr.source_pay_ex_vat, 2) end,
              'source_margin_ex_vat', case when fcr.source_margin_ex_vat is null then null else round(fcr.source_margin_ex_vat, 2) end,
              'target_pay_ex_vat', case when fcr.target_pay_ex_vat is null then null else round(fcr.target_pay_ex_vat, 2) end,
              'target_charge_ex_vat', case when fcr.target_charge_ex_vat is null then null else round(fcr.target_charge_ex_vat, 2) end,
              'target_margin_ex_vat', case when fcr.target_margin_ex_vat is null then null else round(fcr.target_margin_ex_vat, 2) end,
              'approved_resolution_mode', case when fcr.approved_resolution_mode is null then null else fcr.approved_resolution_mode::text end,
              'approved_target_rate', case when fcr.approved_target_rate is null then null else round(fcr.approved_target_rate, 6) end,
              'approved_nonbucket_resolution_mode', case when fcr.approved_nonbucket_resolution_mode is null then null else fcr.approved_nonbucket_resolution_mode::text end,
              'approved_nonbucket_target_amount_ex_vat', case when fcr.approved_nonbucket_target_amount_ex_vat is null then null else round(fcr.approved_nonbucket_target_amount_ex_vat, 2) end,
              'saved_resolution_mode', case when fcr.saved_resolution_mode is null then null else fcr.saved_resolution_mode::text end,
              'saved_resolution_payload_json', fcr.saved_resolution_payload_json,
              'saved_resolution_result_json', fcr.saved_resolution_result_json,
              'resolution_fingerprint', fcr.resolution_fingerprint,
              'is_resolution_stale', coalesce(fcr.is_resolution_stale, false),
              'stale_reason', fcr.stale_reason,
              'requires_resolution', coalesce(fcr.requires_resolution, false),
              'case_resolution_satisfied_now_component', coalesce(fcr.case_resolution_satisfied_now_component, false),
              'suggested_resolution_payload_json', fcr.suggested_resolution_payload_json,
              'suggested_resolution_result_json', fcr.suggested_resolution_result_json,
              'is_actionable_resolution_row', coalesce(fcr.is_actionable_resolution_row, false),
              'is_fixed_no_action_taxable_row', coalesce(fcr.is_fixed_no_action_taxable_row, false)
            )
          ) as row_json
        from finance_case_component_review_rows_effective fcr
        where fcr.candidate_id = v_candidate_id
  
  ;

  create temporary table baseline_component_rows_json on commit drop as
        select
          coalesce(
            jsonb_agg(u.row_json order by u.sort_scope, u.sort_case_key, u.sort_component_fingerprint, u.sort_component_key_type, u.sort_component_key_value),
            '[]'::jsonb
          ) as payload
        from (
          select * from timesheet_baseline_component_rows
          union all
          select * from finance_baseline_component_rows
        ) u
  
  ;

  select
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'candidate_id', ce.candidate_id::text,
            'tms_ref', ce.cand_tms_ref,
            'display_name', ce.cand_display_name,
            'current_pay_method', ce.cand_pay_method,
            'umbrella_id', case when ce.cand_umbrella_id is null then null else ce.cand_umbrella_id::text end,
            'umbrella_enabled', ce.umb_enabled,
            'umbrella_vat_chargeable', ce.umb_vat_chargeable,

            'candidate_has_bank_details', ce.candidate_has_bank_details,
            'candidate_bank_hash', ce.candidate_bank_hash,
            'umbrella_has_bank_details', null,
            'umbrella_bank_hash', null,

            'payee_entity_kind', ce.payee_entity_kind,
            'payee_entity_id', case when ce.payee_entity_id is null then null else ce.payee_entity_id::text end,
            'payee_bank_hash', ce.payee_bank_hash,
            'payee_map_present', ce.payee_map_present,
            'name_check_status', ce.payee_name_check_status,
            'name_check_has_override', ce.payee_name_check_has_override,
            'blockers', ce.blockers,

            'blocked_count', ce.blocked_count,
            'do_not_pay_count', ce.do_not_pay_count,
            'blocked_case_count', coalesce(ccs.blocked_case_count, 0),
            'safe_case_count', coalesce(ccs.safe_case_count, 0),
            'preview_blocked_timesheet_count', coalesce(cptr.blocked_timesheet_preview_count, 0),
            'preview_ready_timesheet_count', coalesce(cptr.ready_timesheet_preview_count, 0),
            'case_resolution_states', coalesce(ccs.case_resolution_states, '[]'::jsonb),
            'gross_preview_ex_vat_non_mismatch', coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),
            'finance_due_total_ex_vat', coalesce(fct.finance_due_total_ex_vat,0),
            'finance_safe_due_total_ex_vat', coalesce(fct.finance_safe_due_total_ex_vat,0),
            'finance_blocked_due_total_ex_vat', coalesce(fct.finance_blocked_due_total_ex_vat,0),
            'mismatch', jsonb_build_object(
              'has_mismatch', ce.has_mismatch,
              'source_paye_ex_vat', ce.mismatch_source_paye_ex,
              'source_umbrella_ex_vat', ce.mismatch_source_umbrella_ex,
              'if_settle_via_paye_ex_vat',
                round(
                  ce.mismatch_source_paye_ex
                  + public._pay_convert_umbrella_to_paye_ex(ce.mismatch_source_umbrella_ex, v_erni_pct),
                  2
                ),
              'if_settle_via_umbrella',
                public._pay_convert_paye_to_umbrella(ce.mismatch_source_paye_ex, v_erni_pct, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
                ||
                public._pay_umbrella_vat_calc(ce.mismatch_source_umbrella_ex, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
            ),
            'overpayment_balance_remaining', ce.overpayment_balance_remaining,
            'loan_due_this_week', ce.loan_due_this_week,
            'loan_repaid_wtd', ce.loan_repaid_wtd,
            'min_take_home_wtd', ce.min_take_home_wtd,
            'max_possible_loan_take_this_run',
              round(
                case
                  when ce.cand_pay_method = 'UMBRELLA' then
                    least(
                      greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                      greatest(
                        least(
                          (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                          (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                        ),
                        0
                      )
                    )
                  else null
                end,
                2
              ),
            'paye_net_status', ce.paye_net_status,
            'loan', jsonb_build_object(
              'pay_week_start', v_week_start::text,
              'loan_due_total', ce.loan_due_total,
              'loan_due_entries', ce.loan_due_entries,
              'loan_due_this_week', ce.loan_due_this_week,
              'loan_repaid_wtd', ce.loan_repaid_wtd,
              'min_take_home_wtd', ce.min_take_home_wtd,
              'max_possible_loan_take_this_run',
                round(
                  case
                    when ce.cand_pay_method = 'UMBRELLA' then
                      least(
                        greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                        greatest(
                          least(
                            (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                            (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                          ),
                          0
