                      )
                    else null
                  end,
                  2
                ),
              'paye_net_status', ce.paye_net_status,
              'cap_fields', jsonb_build_object(
                'min_take_home', ce.min_take_home_wtd,
                'max_deduction',
                  round(
                    case
                      when ce.cand_pay_method = 'UMBRELLA' then
